def quiet_daily_member(series: str) -> bool:
    """A daily-classified series that still takes the global quiet hours."""
    if series in QUIET_HOURS_OFF_SERIES:
        return False
    return series in QUIET_DAILY_SERIES or (
        QUIET_RAIN_PERIOD and rain_period_member(series))


def _hour_window_mult(series: str, now_utc: datetime) -> float:
    """The hour-of-day part of hour_size_mult(): 1.0 outside configured
    windows and for excluded series prefixes."""
    # the opportunistic AS test's gas dailies (2026-10-25, ASTEST_ENABLE): x1
    # at every hour -- the family's own quote window does the timing, and
    # the 4pm-1am gas halving would starve it under the payout floor. The
    # daily picks (2026-10-27) are x1 at every hour too, gas or not.
    if astest_gas_series(series) or astest_member_family(series) == "PICK":
        return 1.0
    et = now_utc.astimezone(ET)
    hour = et.hour
    # A per-series rule wins ONLY for the hours it actually names. Returning
    # its default for every other hour would silently cancel the global
    # window: adding the 4pm halving to KXDIESELD/KXAAAGASD would have taken
    # away their quiet-hours 3-7am x2 as a side effect, which nobody asked for.
    # The period-rain family (KXRAINNAPAM) holds its x2 at every hour (Jack
    # 2026-10-05, "KXRAINNAPAM-01NOV26-31MAR27 isnt at 2x"): the KXRAIN
    # 19-1 ET halving matched it by prefix and rested the season at x1 every
    # evening. That window is the rain DAILIES' (the evening before the rain
    # day is informed by it); a November-March total has no such evening.
    for prefix, hours in SERIES_HOUR_MULTS:
        if series.startswith(prefix) and hour in hours \
                and not rain_period_member(series):
            return hours[hour]
    # sports ladders / escalators: one flat value at every hour (2026-10-06)
    # -- and the NFL head-to-head family, sized as the ladders (2026-10-12)
    if SPORTS_LADDER_HOUR_MULT > 0 and (sports_ladder_league(series)
                                        or nfl_h2h_series(series)
                                        or nfl_auto_ladder(series)):
        return SPORTS_LADDER_HOUR_MULT
    # Daily (print) families never take the GLOBAL window (Jack 2026-09-12,
    # with the 0-9am ET extension): the quiet hours are quiet for long-dated
    # books, while a daily's overnight fills are informed by its own print
    # (gas dailies at 8-9am ET fill at 0.093/contract-hour, 3.2c lost per
    # fill; rain 11.8c). Their per-series windows above still apply, and the
    # QUIET_DAILY members take the global window's quiet hours (2026-10-06).
    if is_daily_series(series):
        if quiet_daily_member(series):
            return global_hour_mults(et.date()).get(hour, 1.0)
        return 1.0
    # Open-scan members (2026-09-05) never take the quiet-hours doubling:
    # the 3-7am ET x2 was measured on the enrolled families' fill data, and
    # an unreviewed family has no such measurement behind it. IMM_SCAN_HOUR_
    # MULT=1 restores the global window for them.
    if not SCAN_HOUR_MULT and series in SCAN_GUARDED_SERIES:
        return 1.0
    mults = global_hour_mults(et.date())
    evening = evening_hour_mults(et.date())
    if not mults and not evening:
        return 1.0
    if any(series.startswith(p) for p in HOUR_MULT_EXCLUDE):
        return 1.0
    if hour in mults:
        # (approval: never the quiet hours, 2026-10-11)
        return 1.0 if series in QUIET_HOURS_OFF_SERIES else mults[hour]
    # the evening window (2026-10-05): never on a quiet hour, never on the
    # sports ladders / escalators (their pre-kickoff window)
    if hour in evening and not sports_ladder_league(series) \
            and nfl_auto_entry(series) is None \
            and league_auto_entry(series) is None:
        return evening[hour]
    return 1.0


# ---------------------------------------------------------------------------
# DAILY (print) FAMILIES — a structural class, not a prefix list (Jack
# 2026-09-12: "extend to midnight to 10am ET for longdated. ensure future
# daily families are excluded (in addition to current daily families)").
# A daily family is one whose markets resolve on a scheduled print within
# about a day of listing: gas/diesel dailies (16-18h programs, a new event
# every day), rain dailies (44h, listed two days out), hourly temp (1h),
# Truflation (27h), the Treasury daily prints (23.5h). Their overnight and
# weekend fills are informed by the print itself, so they take NEITHER the
# quiet-hours doubling NOR the Saturday multiplier — only their own
# per-series windows (the 16-1 / 19-1 halvings). Two layers:
#   * DAILY_PREFIXES is the floor for the families we know today (rain's
#     44h listing window sits outside the structural rule).
#   * every universe refresh classifies each programmed series from the
#     LIVE feed (classify_daily_series / refresh_daily_series). Three tests,
#     all on the series' live markets: DATED event tickers with at least
#     DAILY_MIN_DATES distinct event dates live at once (a daily family
#     always carries today's and tomorrow's; earnings mention lists one
#     event per company and fails here even at 12-20h windows); a 75th-
#     percentile program window of at most DAILY_MAX_HOURS (KXTRUMPMENTION
#     mixes same-day speech events with 22-day programs, p75 112-450h, so
#     the p75 rather than the median keeps it long-dated); and a 75th-
#     percentile EVENT HORIZON — program start to the end of the ticker's
#     event day — of at most DAILY_MAX_HORIZON_HOURS. The horizon is what
#     separates a print daily from a weekly market that Kalshi funds in
#     24h program chunks: KXSUEZWEEKLY / KXBABELMANDEBWEEKLY run 24-36h
#     programs on 7-day markets (horizon ~228h) and stay long-dated.
#     Validated 2026-09-12 on the whole feed history (76k programs): daily
#     = temp hourlies, gas state dailies (16h/40h), KXDIESELD, KXRAIN (45h/
#     43h), KXTRUEV, KXUST*AD (23.5h/32h), KXSOFRD, KXEURUSD/KXUSDJPY,
#     KXTXERCOTPEAKD, the 15-minute metals, WORLDNEWSMENTION, TRUMPMENTIONB,
#     KXMAMDANIMENTION (44h/37h); long-dated = KXTRUMPMENTION, every
#     earnings mention, *CC, KPI months, the shipping weeklies, gas/diesel
#     weeklies/monthlies/annuals.
# Hysteresis: once daily, a series stays daily until its p75 program window
# exceeds DAILY_DROP_HOURS (a momentary single-date feed cannot flip the
# ladder shape), and is forgotten after 14 days out of the feed. The set
# persists to STATUS_DIR/daily_series.json so a restart quotes right from
# its first cycle and imm_saturday_tracker.py shares the classification.
# IMM_DAILY_EXEMPT prefixes are never classified daily (the knob if a
# structurally-daily family should take the boosts after all).
# The prefix floor is the TRUE dailies only: KXAAAGASD (national + every
# state daily), KXDIESELD, KXRAIN (dailies + KXRAINWKND), KXTEMP. The gas/
# diesel weeklies, monthlies and annuals are long-dated by structure and
# measured benign overnight (weekday 0-9 ET: 0.024 fills per contract-hour,
# 0.6c lost per fill, vs the dailies' 0.165 / 3.2c), so they keep the hour
# window; the Saturday multiplier still skips the whole gas/diesel family
# via SAT_MULT_EXCLUDE, as decided that morning.
DAILY_PREFIXES = tuple(p for p in os.environ.get(
    "IMM_DAILY_PREFIXES", "KXAAAGASD,KXDIESELD,KXRAIN,KXTEMP").split(",") if p)
# KXBIGGESTQUAKE is exempt (Jack 2026-10-26: "Yes give boost"): its x4 of
# 10/07 was planned as x6 in the evening and x12 in the quiet hours, but the
# feed classifier read its one-UTC-day events as daily and it rested x1 at
# every hour. A quake is not informed by a coming print overnight, and the
# family is bid-only and capped at the fair, so it takes the global hour
# windows and the Saturday step again.
DAILY_EXEMPT_PREFIXES = tuple(
    p for p in os.environ.get("IMM_DAILY_EXEMPT", "KXBIGGESTQUAKE").split(",") if p)
DAILY_MAX_HOURS = _env_float("IMM_DAILY_MAX_HOURS", 48.0)
DAILY_DROP_HOURS = _env_float("IMM_DAILY_DROP_HOURS", 72.0)
DAILY_MAX_HORIZON_HOURS = _env_float("IMM_DAILY_MAX_HORIZON_HOURS", 72.0)
DAILY_MIN_DATES = _env_int("IMM_DAILY_MIN_DATES", 2)
DAILY_SERIES_FILE = "daily_series.json"
DAILY_SERIES_DYNAMIC: Dict[str, dict] = {}   # series -> {p75_h, dates, n, since, seen}


def is_daily_series(series: str) -> bool:
    """Prefix floor OR structurally classified from the live feed; exempt
    prefixes never count."""
    if any(series.startswith(p) for p in DAILY_EXEMPT_PREFIXES):
        return False
    # the NFL auto families take the overnight / Saturday step-ups (Jack
    # 2026-10-12) -- never daily, whatever the feed classifier reads
    if nfl_auto_entry(series) is not None or league_auto_entry(series) is not None:
        return False
    if any(series.startswith(p) for p in DAILY_PREFIXES):
        return True
    # the snow monthlies (2026-10-04) sit with the rain monthlies, which the
    # KXRAIN floor covers: x1 at every hour, no Saturday or yield size
    if snow_monthly_series(series):
        return True
    # the YouTube #2 pilot (2026-10-05) is x1 at every hour by spec -- not
    # left to the feed classifier (read at call time: defined further down)
    if series in globals().get("YT2_SERIES", ()) and globals().get("YT2_ENABLE"):
        return True
    # ... and so is the YouTube #1 leader-bid pilot (2026-10-14)
    if series == globals().get("YT1_SERIES") and globals().get("YT1_ENABLE"):
        return True
    # ... and so is the YouTube weekly pilot (2026-10-06)
    if series == globals().get("YTW_SERIES") and globals().get("YTW_ENABLE"):
        return True
    # ... and so are the Trump weekly pilots (2026-10-11)
    if series in globals().get("TWK_SERIES", ()) and globals().get("TWK_ENABLE"):
        return True
    # ... and Big Sky's resort snowfall (2026-10-13), quoted with no fair
    if series in globals().get("BIGSKY_SERIES", ()) and globals().get("BIGSKY_ENABLE"):
        return True
    # ... and the ski resorts' season snowfall (2026-10-22), on its gate
    _rss = globals().get("resort_snow_series")
    if _rss is not None and _rss(series):
        return True
    # ... and the AS test's Billboard and VoteHub families (2026-10-27)
    _asn = globals().get("astest_new_series")
    if _asn is not None and _asn(series):
        return True
    return series in DAILY_SERIES_DYNAMIC


def _p75(values: List[float]) -> float:
    """Nearest-rank 75th percentile (n=1 -> the value, n=2 -> the max)."""
    s = sorted(values)
    idx = -(-3 * len(s) // 4) - 1
    return s[max(0, min(len(s) - 1, idx))]


def classify_daily_series(by_market: Dict[str, dict]) -> Dict[str, dict]:
    """Pure: per-series {p75_h, horizon_h, dates, n} from a programs feed
    (market_ticker -> {start, end, ...} as fetch_programs returns it).
    horizon_h = p75 of (end of the ticker's event day - program start);
    None when no ticker in the series carries a date."""
    hours: Dict[str, List[float]] = {}
    horizons: Dict[str, List[float]] = {}
    dates: Dict[str, set] = {}
    for t, info in by_market.items():
        start, end = info.get("start"), info.get("end")
        if start is None or end is None:
            continue
        s = series_of(t)
        hours.setdefault(s, []).append((end - start).total_seconds() / 3600.0)
        d = parse_event_date(t)          # reads the ticker's date segment
        if d is not None:
            dates.setdefault(s, set()).add(d.date())
            horizons.setdefault(s, []).append(
                (d + timedelta(hours=24) - start).total_seconds() / 3600.0)
    return {s: {"p75_h": round(_p75(hs), 2),
                "horizon_h": (round(_p75(horizons[s]), 2) if horizons.get(s) else None),
                "dates": len(dates.get(s, ())), "n": len(hs)}
            for s, hs in hours.items()}


def _daily_by_rule(st: dict) -> bool:
    hz = st.get("horizon_h")
    return (st.get("dates", 0) >= DAILY_MIN_DATES
            and st.get("p75_h", 1e9) <= DAILY_MAX_HOURS
            and hz is not None and -24.0 <= hz <= DAILY_MAX_HORIZON_HOURS)


def _daily_out_of_bounds(st: dict) -> bool:
    """A member leaves the class when its program window crosses the
    hysteresis line OR its event horizon is outside the structural bound.
    Only the dates test is hysteretic (a feed can momentarily carry one
    date); the horizon is a property of the family, so it is re-checked
    every refresh and on load — 2026-09-12: a stale file seeded five
    shipping weeklies (24h programs on 7-day markets, horizon 203h) and the
    program-length-only drop would have kept them daily forever."""
    hz = st.get("horizon_h")
    return (st.get("p75_h", 0.0) > DAILY_DROP_HOURS
            or (hz is not None and not (-24.0 <= hz <= DAILY_MAX_HORIZON_HOURS)))


def daily_series_path() -> str:
    return os.path.join(STATUS_DIR, DAILY_SERIES_FILE)


def save_daily_series_file(now_utc: datetime) -> None:
    try:
        tmp = daily_series_path() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"updated": now_utc.isoformat(), "max_hours": DAILY_MAX_HOURS,
                       "drop_hours": DAILY_DROP_HOURS, "min_dates": DAILY_MIN_DATES,
                       "max_horizon_hours": DAILY_MAX_HORIZON_HOURS,
                       "prefixes": list(DAILY_PREFIXES),
                       "series": DAILY_SERIES_DYNAMIC}, f, indent=1, sort_keys=True)
        os.replace(tmp, daily_series_path())
    except OSError as e:
        log(f"[IMM] ! {DAILY_SERIES_FILE} write failed: {e}")


def load_daily_series_file() -> int:
    """Seed DAILY_SERIES_DYNAMIC from the persisted file; returns the count
    (0 and untouched when the file is absent/unreadable)."""
    try:
        with open(daily_series_path(), encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, ValueError):
        return 0
    ser = data.get("series") if isinstance(data, dict) else None
    if isinstance(ser, dict):
        DAILY_SERIES_DYNAMIC.clear()
        DAILY_SERIES_DYNAMIC.update({str(k): dict(v) for k, v in ser.items()
                                     if isinstance(v, dict)
                                     and not _daily_out_of_bounds(v)})
    return len(DAILY_SERIES_DYNAMIC)


def refresh_daily_series(by_market: Dict[str, dict],
                         now_utc: datetime) -> Tuple[List[str], List[str]]:
    """Update DAILY_SERIES_DYNAMIC from a LIVE feed (the caller guards
    empty/failed reads) and persist it. Returns (added, dropped)."""
    stats = classify_daily_series(by_market)
    added: List[str] = []
    dropped: List[str] = []
    for s, st in stats.items():
        if any(s.startswith(p) for p in DAILY_EXEMPT_PREFIXES + DAILY_PREFIXES):
            continue                     # floor / exempt: no bookkeeping
        cur = DAILY_SERIES_DYNAMIC.get(s)
        if cur is None:
            if _daily_by_rule(st):
                DAILY_SERIES_DYNAMIC[s] = dict(st, since=now_utc.isoformat(),
                                               seen=now_utc.isoformat())
                added.append(s)
        else:
            cur.update(st)
            cur["seen"] = now_utc.isoformat()
            if _daily_out_of_bounds(st):
                DAILY_SERIES_DYNAMIC.pop(s)
                dropped.append(s)
    cutoff = now_utc - timedelta(days=14)
    for s in list(DAILY_SERIES_DYNAMIC):
        seen = DAILY_SERIES_DYNAMIC[s].get("seen")
        try:
            if seen and datetime.fromisoformat(seen) < cutoff:
                DAILY_SERIES_DYNAMIC.pop(s)
                dropped.append(s)
        except (TypeError, ValueError):
            pass
    save_daily_series_file(now_utc)
    return added, dropped


# Saturday ladder multiplier (Jack 2026-09-12: "Saturday multiplier of 1.5x,
# only on long-dated families"), from the weekday-vs-weekend study on the
# post-temp window 2026-08-08..09-11 (cycle logs + the account fills API,
# IMM maker fills scored to settlement). Rent per RESTING contract is flat
# across day types (~2c/day) — pools and competition do not change by day —
# so the whole difference is on the cost side. Saturday: 0.20 fills per
# resting contract (weekday 0.64), 2.4c lost per filled contract (2.6c) ->
# net +1.17c per resting contract-day vs +0.44c, and +5.8c per FILLED
# contract vs +0.7c. Sunday is the WORST day of the week (turnover 0.59,
# 4.6c lost per fill, net -0.61c/ct-day: Sunday rain + Sunday-evening
# mention bursts) and gets nothing. The effect lives in the long-dated
# families (turnover 0.51 -> 0.08 on Saturday, 13.5c rent per fill) while
# the dailies fill at the same rate every day — is_daily_series() (prefix
# floor + the structural class above) keeps them out, and SAT_MULT_EXCLUDE
# (default KXAAAGAS,KXDIESEL) keeps the whole gas/diesel family out the way
# it was measured, weeklies and monthlies included (their Saturday evidence
# is thin and negative: KXDIESELW -29c/fill on 89 contracts, KXAAAGASM
# -17c on 66/day). Saturday is the ET calendar day (Sat 00:00-
# 23:59 ET). Composes multiplicatively with the hour windows (Sat 0-9am ET
# on the global ladder = x3, exactly how the mention family mult composed)
# and sits INSIDE hour_size_mult so every consumer — ladder shape, placement
# caps, collateral estimate, TOTAL_SIZE_MULT_CAP via capped_ref_mult, the
# cycle log's hour_mult column — sees one number. Code default OFF (1.0);
# the launcher sets IMM_SAT_SIZE_MULT=1.5. Four Saturdays of evidence at
# deploy: a hypothesis under test, re-measured every Monday by
# imm_saturday_tracker.py.
SAT_SIZE_MULT = _env_float("IMM_SAT_SIZE_MULT", 1.0)
SAT_MULT_EXCLUDE = tuple(
    p for p in os.environ.get("IMM_SAT_MULT_EXCLUDE", "KXAAAGAS,KXDIESEL").split(",") if p)

# GATED STEP-UP (Jack 2026-09-26: "2x next saturday if today + prior
# saturdays show no sign of edge degradation"). Armed by a VERDICT FILE, not
# by a clock: imm_saturday_tracker.py scores every boosted Saturday (9/12
# from 10:00 ET, when the knob went live; 9/19; 9/26) once the newest one's
# fills carry a full 24h mark-out -- the Monday 07:40 ET run -- and writes
# SAT_GATE_FILE ONCE: {"verdict": "PASS"|"FAIL", "mult": 2.0,
# "effective_from": <the first Saturday after the run>, "checks": [...]}.
# On PASS, Saturdays from effective_from on run at min(SAT_SIZE_MULT_GATED,
# the file's mult) instead of SAT_SIZE_MULT; on FAIL, a missing/unreadable
# file, a verdict whose mult is not above SAT_SIZE_MULT, or the Saturday
# knob off, Saturday stays at SAT_SIZE_MULT (fail closed). Same exclusions
# and the same composition with the hour windows (a PASS makes Saturday
# 0-9 ET x4 on the global ladder, where TOTAL_SIZE_MULT_CAP leaves the at-ref
# depth mult x1.25). Read at import and by mtime each refresh: hand-editing
# the verdict to anything but PASS is an instant kill with no restart;
# IMM_SAT_SIZE_MULT_GATED=0 is the restart-level kill. Deleting the file
# RE-ARMS the gate (the next Monday tracker run evaluates again).
SAT_SIZE_MULT_GATED = _env_float("IMM_SAT_SIZE_MULT_GATED", 2.0)
SAT_GATE_FILE = "sat_mult_gate.json"
SAT_GATE_STATE: Dict[str, object] = {"mtime": 0.0, "verdict": "", "mult": 0.0,
                                      "effective_from": None}


def sat_gate_path() -> str:
    return os.path.join(STATUS_DIR, SAT_GATE_FILE)


def gated_sat_mult(et_day) -> float:
    """The approved Saturday step-up for this ET calendar date (a
    datetime.date), or 0.0 when the gate does not apply."""
    if SAT_SIZE_MULT_GATED <= 0 or SAT_GATE_STATE["verdict"] != "PASS":
        return 0.0
    eff = SAT_GATE_STATE["effective_from"]
    if eff is None or et_day < eff:
        return 0.0
    m = min(SAT_SIZE_MULT_GATED, float(SAT_GATE_STATE["mult"] or 0.0))
    return m if m > SAT_SIZE_MULT else 0.0


def sat_gate_summary() -> str:
    """One line for the banner / refresh log / tracker knobs block."""
    st = SAT_GATE_STATE
    if SAT_SIZE_MULT <= 0 or SAT_SIZE_MULT == 1.0:
        return "Saturday multiplier off (IMM_SAT_SIZE_MULT), so the step-up is inert"
    if SAT_SIZE_MULT_GATED <= 0:
        return "step-up off (IMM_SAT_SIZE_MULT_GATED=0)"
    if not st["mtime"]:
        return (f"step-up x{SAT_SIZE_MULT_GATED:g} awaiting the tracker's verdict "
                f"(no {SAT_GATE_FILE}); Saturday stays x{SAT_SIZE_MULT:g}")
    eff = st["effective_from"]
    if st["verdict"] == "PASS" and eff is not None:
        m = min(SAT_SIZE_MULT_GATED, float(st["mult"] or 0.0))
        if m > SAT_SIZE_MULT:
            return f"verdict PASS: x{m:g} on Saturdays from {eff.isoformat()}"
        return (f"verdict PASS for x{float(st['mult'] or 0.0):g}, not above "
                f"x{SAT_SIZE_MULT:g}; Saturday stays x{SAT_SIZE_MULT:g}")
    return f"verdict {st['verdict'] or 'unreadable'}; Saturday stays x{SAT_SIZE_MULT:g}"


def load_sat_gate() -> bool:
    """Mirror SAT_GATE_FILE into SAT_GATE_STATE (mtime-gated). A missing or
    unreadable file clears the verdict (fail closed). True when it changed."""
    try:
        mtime = os.path.getmtime(sat_gate_path())
    except OSError:
        mtime = 0.0
    if mtime == SAT_GATE_STATE["mtime"]:
        return False
    before = (SAT_GATE_STATE["verdict"], SAT_GATE_STATE["mult"],
              SAT_GATE_STATE["effective_from"])
    verdict, mult, eff = "", 0.0, None
    if mtime:
        try:
            with open(sat_gate_path(), encoding="utf-8") as f:
                data = json.load(f)
            verdict = str(data.get("verdict") or "").strip().upper()
            mult = float(data.get("mult") or 0.0)
            eff = datetime.strptime(str(data.get("effective_from")), "%Y-%m-%d").date()
        except (OSError, ValueError, TypeError, AttributeError) as e:
            log(f"[IMM] ! {SAT_GATE_FILE} unreadable ({e}); fail closed")
            verdict, mult, eff = "", 0.0, None
    SAT_GATE_STATE.update(mtime=mtime, verdict=verdict, mult=mult, effective_from=eff)
    changed = (verdict, mult, eff) != before
    if changed:
        log(f"[IMM] Saturday gate: {sat_gate_summary()}")
    return changed


def saturday_size_mult(series: str, now_utc: datetime) -> float:
    """SAT_SIZE_MULT on Saturdays (ET calendar day) for long-dated series
    (not daily families, not SAT_MULT_EXCLUDE prefixes) -- or the gated
    step-up on a Saturday the tracker's PASS verdict covers; 1.0 otherwise
    and whenever the Saturday knob is off/invalid."""
    if SAT_SIZE_MULT <= 0 or SAT_SIZE_MULT == 1.0:
        return 1.0
    et = now_utc.astimezone(ET)
    if et.weekday() != 5:
        return 1.0
    if is_daily_series(series) or any(series.startswith(p) for p in SAT_MULT_EXCLUDE):
        return 1.0
    return gated_sat_mult(et.date()) or SAT_SIZE_MULT


def _share_x1(series: str) -> bool:
    """An OpenRouter market-share series (KX<AUTHOR>SHARE). Since 2026-10-03
    (Jack: "make the share market change") the family quotes x1 at every
    hour -- no quiet-hours, Saturday, evening or yield-mode size -- and nets
    at most SHARE_EVENT_CAP per event. The worst fills of 10/01-10/03 were
    100-lots at the quiet-hours x2 while the book ran over a lagging fair.
    Read at call time: SHARE_FAIR_SERIES is defined with the gate below."""
    return series in globals().get("SHARE_FAIR_SERIES", ())


# CARBON ARC AT 1x WHILE ITS DATA LANDS (Jack 2026-10-10: "reduce carbon arc
# families to only be at 1x in their regular window of when new data lands").
# Each Carbon Arc category refreshes at its own time of day (the prisms'
# last_refreshed_at, 9/27-10/10, ET):
#   point of sale  07-08h (12 of 13 drops)   foot traffic ~08h (12 of 16)
#   apps           mostly 08-10h             card spend   11-14h (all 18)
#   ad spend       02h x2, 21h, 11h x2 (lumps every 1-5 days)
# and the informed flow trades the new read within hours: on 10/10 the
# ad-spend read landed 02:32 ET and the sweep ran 03:20-05:43 (-$424), every
# rung 120-150 lots because the quiet-hours x3 (00-08h ET) was on. That
# morning every Carbon Arc market quoted at x6 (x3 quiet hours x Saturday x2)
# straight through the point-of-sale and foot-traffic drops. Inside its
# category's window a Carbon Arc market is at 1x: the hour / Saturday
# multipliers are capped at 1 here, and the per-market boosts (yield x1.5,
# near-cliff) are off in the bot (ca_landing_window). The windows are the
# landing hours plus ~2h for the reaction, [start, end) in ET hours; a window
# may wrap midnight. IMM_CA_LANDING_WINDOWS: "category=a-b+c-d;..." (prism
# categories, lowercased); empty = off.
_DEFAULT_CA_LANDING_WINDOWS = ("point of sale=7-10;foot traffic=8-11;app=8-12;"
                               "credit card=11-15;advertising=21-6+11-14")
CA_LANDING_WINDOWS: Dict[str, List[Tuple[int, int]]] = {}
for _part in os.environ.get("IMM_CA_LANDING_WINDOWS", _DEFAULT_CA_LANDING_WINDOWS).split(";"):
    if "=" not in _part:
        continue
    _cat, _spans = _part.split("=", 1)
    for _span in _spans.split("+"):
        try:
            _a, _b = (int(x) % 24 for x in _span.split("-", 1))
        except ValueError:
            continue
        CA_LANDING_WINDOWS.setdefault(_cat.strip().lower(), []).append((_a, _b))
# a series with no read yet is categorised by its ticker suffix
_CA_SUFFIX_CATEGORY = (("ADS", "advertising"), ("APP", "app"),
                       ("POS", "point of sale"), ("FT", "foot traffic"),
                       ("CC", "credit card"))
# ...and, with no suffix either, by the Kalshi series title its source
# verdict stored (Jack 2026-10-16: "Ship A1 and A2 now"). The Carbon Arc
# SECTOR ARRAYS listed 10/16 (KXSODAARRAY "Soda point of sale spend array",
# KXFASTARRAY "Fast food credit card spend array", KXSTREAMARRAY "Streaming
# app downloads array", ...) end in ARRAY, and their prisms 404 for our
# token, so neither a read nor a suffix names the category the late-month
# blocked side, the landing window and the scheduled-data hold key on.
_CA_TITLE_CATEGORY = (("point of sale", "point of sale"),
                      ("credit card", "credit card"),
                      ("app download", "app"),
                      ("foot traffic", "foot traffic"),
                      ("ad spend", "advertising"),
                      ("advertising", "advertising"))


def ca_category(series: str) -> Optional[str]:
    """The Carbon Arc category of a Carbon Arc-settled series (lowercased
    prism category, else its suffix's, else its verdict title's), or None."""
    if not carbon_arc_settled(series):
        return None
    e = (globals().get("_ca_fair_state") or {}).get("entries", {}).get(series)
    if e and e.get("category"):
        return str(e["category"]).strip().lower()
    for suf, cat in _CA_SUFFIX_CATEGORY:
        if series.endswith(suf):
            return cat
    title = str((FAMILY_VERDICTS.get(series) or {}).get("title") or "").lower()
    for key, cat in _CA_TITLE_CATEGORY:
        if key in title:
            return cat
    return None


def ca_landing_window(series: str, now_utc: datetime) -> bool:
    """True while `series` is a Carbon Arc series inside its category's data
    landing window (CA_LANDING_WINDOWS)."""
    if not CA_LANDING_WINDOWS:
        return False
    cat = ca_category(series)
    if not cat or cat not in CA_LANDING_WINDOWS:
        return False
    h = now_utc.astimezone(ET).hour
    return any((a <= h < b) if a < b else (h >= a or h < b)
               for a, b in CA_LANDING_WINDOWS[cat])


def hour_size_mult(series: str, now_utc: datetime) -> float:
    """Active ladder multiplier for this series at this instant: the
    hour-of-day window (global or per-series) times the Saturday multiplier;
    1.0 when neither applies, and always for the OpenRouter market-share
    family (_share_x1). Capped at 1 for a Carbon Arc series inside its data
    landing window (CA_LANDING_WINDOWS)."""
    if _share_x1(series):
        return 1.0
    m = _hour_window_mult(series, now_utc) * saturday_size_mult(series, now_utc)
    if m > 1.0 and ca_landing_window(series, now_utc):
        return 1.0
    return m


# Mention-family ladder multiplier. Jack 2026-07-28: x1.5 ("raise any caps
# commensurately") -> REMOVED 2026-07-30 ("remove 1.5x multiplier on
# MENTION, so that they are at 10 contracts"): default 1.0 = whole family
# on the global ladder, and the commensurate caps (150/750, skew 45/90)
# revert to 100/500/30-60 through applied_mention_mult automatically. The
# machinery stays env-tunable (IMM_MENTION_SIZE_MULT) if he wants it back.
MENTION_SIZE_MULT = _env_float("IMM_MENTION_SIZE_MULT", 1.0)

# EARNINGS-ONLY ladder multiplier (Jack 2026-09-17: "increase quote size on
# EARNINGSMENTIONS by 1.5x"). A SEPARATE knob from MENTION_SIZE_MULT on
# purpose: that one is the WHOLE mention family -- KXTRUMPMENTION,
# KXNBAMENTION, KXWCMENTION, KXLOVEISLMENTION and every future *MENTION ride
# it -- and only the per-company earnings-call books (KXEARNINGSMENTION<TKR>)
# were asked for. It MULTIPLIES on top of the family knob rather than
# replacing it, so restoring IMM_MENTION_SIZE_MULT=1.5 would put earnings at
# 2.25x and the rest of the family at 1.5x, which is the composition the two
# knobs are meant to express.
#
# Everything downstream scales commensurately because this rides
# applied_mention_mult, the single multiplier every geometry consumer reads:
# ladder rung sizes (hour_scaled_levels: 20 -> 30 at the live IMM_LEVELS=0:20),
# the per-market position cap (series_max_position: 150 -> 225), the per-event
# net cap (event_cap_contracts: 1000 -> 1500) and the inventory skew knees
# (SKEW_SOFT/HARD_CONTRACTS: 30/60 -> 45/90). That is exactly the wiring the
# 2026-07-28 family-wide x1.5 used, so the pieces stay proportional to each
# other instead of a fat ladder fighting an unchanged cap.
#
# Hand-tuned override series are still exempt via applied_mention_mult (no
# earnings series carries a SeriesOverride today; the exemption is structural,
# not a guess). Env IMM_EARNINGS_SIZE_MULT; 1.0 reverts to family-only.
EARNINGS_SIZE_MULT = _env_float("IMM_EARNINGS_SIZE_MULT", 1.5)
# SCHEDULED successor (Jack 2026-10-02: "make both changes for monday"):
# IMM_EARNINGS_SIZE_MULT_NEXT replaces IMM_EARNINGS_SIZE_MULT from 00:00 ET
# on IMM_EARNINGS_SIZE_MULT_FROM (an ET day); the launcher sets x2 from
# 2026-10-05. Checked against the clock on every call (an epoch compare), so
# the rung, the per-market / per-event caps and the skew knees step up
# together at midnight without a restart. NEXT 0 / unset = no change. The
# floor projection prices the family part at the CURRENT value (only the
# hour part is walked per hour), which under-projects earnings accrual for
# the last day before the switch; nothing else reads ahead.
# Evidence (9/18-10/1): +$81/day net at the paid rate, positive 13 of 14
# days; since the x1.5 (9/17) net per resting contract-hour rose 25 -> 33
# -> 66c per 1k and settled P&L per filled contract went -9c -> +9c.
# 2026-10-11 (Jack: "increase it to 3x"): the launcher's NEXT is 3.0 from
# 2026-10-11 -- rung 20 -> 60, per-market cap 450, per-event 3,000, skew
# knees 90/180.
EARNINGS_SIZE_MULT_NEXT = _env_float("IMM_EARNINGS_SIZE_MULT_NEXT", 0.0)
EARNINGS_SIZE_MULT_FROM = _env_et_day("IMM_EARNINGS_SIZE_MULT_FROM")
EARNINGS_SIZE_MULT_FROM_TS = _et_day_start_ts(EARNINGS_SIZE_MULT_FROM)


def earnings_size_mult(now_utc: Optional[datetime] = None) -> float:
    """The earnings family multiplier in force now (or at `now_utc`)."""
    if EARNINGS_SIZE_MULT_NEXT > 0 and EARNINGS_SIZE_MULT_FROM_TS is not None:
        ts = now_utc.timestamp() if now_utc is not None else time.time()
        if ts >= EARNINGS_SIZE_MULT_FROM_TS:
            return EARNINGS_SIZE_MULT_NEXT
    return EARNINGS_SIZE_MULT


def mention_size_mult(series: str) -> float:
    # Earnings first: KXEARNINGSMENTION<TKR> does NOT end in "MENTION" (the
    # company symbol is the tail), but the bare stem does, so the order
    # matters for the stem and is harmless for every real series.
    if series.startswith("KXEARNINGSMENTION"):
        return MENTION_SIZE_MULT * earnings_size_mult()
    if series.endswith("MENTION"):
        return MENTION_SIZE_MULT
    return 1.0


# BASE SIZE SPLIT TEST (Jack 2026-10-22: "I want to test increasing base
# contract size by 1.5x" -> "Split test"). For SIZE_TEST_DAYS from 00:00 ET
# on SIZE_TEST_FROM, a fixed half of the series ("test": the first byte of
# sha256(SIZE_TEST_SALT:series) is odd) quotes at SIZE_TEST_MULT on the family
# wire -- rungs, per-market and per-event caps and the skew knees together,
# the wiring of the 10/11 family x2s that measured reward elasticity 0.51 and
# fill-loss elasticity 0.90 -- and the other half ("control") stays as it is,
# so both halves trade the same days. The salt balanced the halves on
# 10/08-10/21 (rewards $489 vs $496/day, fills -$326 vs -$332). Out of both
# halves: hand-tuned ladders (applied_mention_mult leaves them literal) and
# SIZE_TEST_EXCLUDE (the Trump mentions B test; KXGENERALMOV, sized x3 by
# hand on 10/23, see GENMOV_SIZE_MULT; KXPRESRUN, whose hand-set x6 the test
# half would have made x9 -- Jack 2026-10-25: "Take it out"; KXAPRPOTUS,
# resized x3 -> x5 by hand the day before the start, see APRPOTUS_SIZE_MULT;
# KXRT and the Vercel family, x2 -> x3 on its first day, added where their
# sizes are set) and every series under SIZE_TEST_EXCLUDE_PREFIXES: the
# temperature families (KXHIGH*, KXLOWT*), sized x5 by hand on 10/24, two
# days before the start. Their override carries only size_mult, so the test
# half -- 20 of the 48 cities -- ran x7.5; and with no pre-test baseline
# (they started 10/23) their settlement swings, about +-$300 a day, were only
# noise in the score (Jack 2026-10-27: "do 1 and 3", 1 = "take the
# temperature markets out of the size test").
# imm_size_test_report (IMM
# family watch pass 7) scores it daily and writes SIZE_TEST_STOP_FILE (in
# STATUS_DIR) when its stop rule trips; the file ends the test by hand too,
# read once a minute. IMM_SIZE_TEST_MULT=1 turns it off.
SIZE_TEST_MULT = _env_float("IMM_SIZE_TEST_MULT", 1.5)
SIZE_TEST_FROM = _env_et_day("IMM_SIZE_TEST_FROM", "2026-10-26")
SIZE_TEST_DAYS = _env_float("IMM_SIZE_TEST_DAYS", 14)
SIZE_TEST_SALT = os.environ.get("IMM_SIZE_TEST_SALT", "size15-1026-31")
SIZE_TEST_EXCLUDE = frozenset(
    s.strip() for s in os.environ.get(
        "IMM_SIZE_TEST_EXCLUDE",
        "KXTRUMPMENTION,KXTRUMPMENTIONB,KXGENERALMOV,KXPRESRUN,KXAPRPOTUS"
    ).split(",") if s.strip())
SIZE_TEST_EXCLUDE_PREFIXES = tuple(
    p.strip() for p in os.environ.get(
        "IMM_SIZE_TEST_EXCLUDE_PREFIXES", "KXHIGH,KXLOWT").split(",") if p.strip())
SIZE_TEST_STOP_FILE = "size_test_stop.txt"                     # in STATUS_DIR
_size_test_stop = {"checked": 0.0, "stopped": False}
_size_test_cache: Dict[Any, Any] = {}           # the window per knobs, a parity per series


def size_test_window() -> Tuple[Optional[float], Optional[float]]:
    """(start, end) UTC epochs of the size test, (None, None) when off."""
    key = (SIZE_TEST_FROM, SIZE_TEST_DAYS, SIZE_TEST_MULT)
    if key not in _size_test_cache:
        start = _et_day_start_ts(SIZE_TEST_FROM)
        if start is None or SIZE_TEST_MULT == 1.0 or SIZE_TEST_DAYS <= 0:
            _size_test_cache[key] = (None, None)
        else:
            day = SIZE_TEST_FROM + timedelta(days=int(round(SIZE_TEST_DAYS)))
            _size_test_cache[key] = (start, _et_day_start_ts(day))
    return _size_test_cache[key]


def size_test_arm(series: str) -> Optional[str]:
    """"test" / "control" for a series in the size test, None for one out of
    both halves."""
    ov = SERIES_OVERRIDES.get(series)
    if (series in SIZE_TEST_EXCLUDE or series.startswith(SIZE_TEST_EXCLUDE_PREFIXES)
            or (ov and (ov.levels or ov.max_position is not None))):
        return None
    key = (SIZE_TEST_SALT, series)
    if key not in _size_test_cache:
        _size_test_cache[key] = hashlib.sha256(f"{SIZE_TEST_SALT}:{series}".encode()).digest()[0] % 2
    return "test" if _size_test_cache[key] else "control"


def size_test_stopped() -> bool:
    now = time.time()
    if now - _size_test_stop["checked"] >= 60:
        _size_test_stop["checked"] = now
        _size_test_stop["stopped"] = os.path.exists(os.path.join(STATUS_DIR, SIZE_TEST_STOP_FILE))
    return _size_test_stop["stopped"]


def size_test_mult(series: str, now_ts: Optional[float] = None) -> float:
    """SIZE_TEST_MULT for a "test" series inside the window, else 1.0."""
    start, end = size_test_window()
    if start is None:
        return 1.0
    ts = time.time() if now_ts is None else now_ts
    if not (start <= ts < end) or size_test_arm(series) != "test" or size_test_stopped():
        return 1.0
    return SIZE_TEST_MULT


def applied_mention_mult(series: str) -> float:
    """The mention multiplier ACTUALLY applied to this series' geometry:
    1.0 for series with a hand-tuned SeriesOverride ladder/cap (Love Island
    5/5/5 net-50 stays literal — Jack's 2026-07-12 spec, not an accident of
    the family test); MENTION_SIZE_MULT for mention series riding the
    global geometry. Every consumer (ladder, per-market/event caps, skew)
    uses THIS, so the scaled pieces stay proportional to each other."""
    ov = SERIES_OVERRIDES.get(series)
    if ov and (ov.levels or ov.max_position is not None):
        return 1.0
    m = mention_size_mult(series)
    # FAMILY size multiplier on the global geometry (2026-09-26: sports
    # ladders / escalators x2). Rides the same wire as the mention x1.5, so
    # ladder rungs, per-market and per-event caps and the skew knees stay
    # proportional -- and the estimator's hypothetical ladder, hence the
    # payout-floor projection, sees the doubled size, as Jack asked.
    if ov and ov.size_mult is not None:
        m *= ov.size_mult
    # ...and the base size split test's half (SIZE_TEST_MULT, 2026-10-26)
    return m * size_test_mult(series)


def hour_scaled_levels(series: str, now_utc: datetime) -> List[Tuple[int, int]]:
    """series_levels() with the family (mention) and hour multipliers applied
    to every rung size (half-up rounding, floor 1). The single ladder-shape
    source for the quote loop, the placement caps, the collateral estimate
    and the yield overlay."""
    lv = series_levels(series)
    m = hour_size_mult(series, now_utc) * applied_mention_mult(series)
    if m == 1.0:
        return lv
    return [(t, max(1, int(s * m + 0.5))) for t, s in lv]


def base_scaled_levels(series: str) -> List[Tuple[int, int]]:
    """hour_scaled_levels() with the time-of-day / Saturday multiplier OFF
    (1.0): the day ladder. The family (mention / earnings) multiplier is
    kept -- it is not a time-of-day effect. Feeds the day-size floor
    projection (FLOOR_PROJECTION_BASE_SIZE, 2026-09-25)."""
    lv = series_levels(series)
    m = applied_mention_mult(series)
    if m == 1.0:
        return lv
    return [(t, max(1, int(s * m + 0.5))) for t, s in lv]


def scaled_levels_at(series: str, mult: float) -> List[Tuple[int, int]]:
    """series_levels() at an EXPLICIT time-of-day multiplier `mult` (the
    family multiplier always applied): the ladder the quote loop rests
    whenever hour_size_mult() reads `mult`. hour_scaled_levels() is this at
    the live multiplier, base_scaled_levels() at 1.0. Feeds the
    schedule-weighted floor projection (FLOOR_PROJECTION_SCHEDULE)."""
    lv = series_levels(series)
    m = mult * applied_mention_mult(series)
    if m == 1.0:
        return lv
    return [(t, max(1, int(s * m + 0.5))) for t, s in lv]


def size_mult_profile(series: str, start_utc: datetime,
                      horizon_days: float) -> List[Tuple[float, float]]:
    """[(multiplier, share of the window)], sorted by multiplier: how the
    next `horizon_days` split between the size multipliers hour_size_mult()
    will apply to this series -- quiet hours x2, Saturday x1.5 (composed:
    x3), the per-series evening halvings, the daily-family / scan / prefix
    exclusions, all of it, because this IS hour_size_mult sampled once per
    ET hour (ET hour boundaries are UTC hour boundaries). The walk is capped
    at FLOOR_PROFILE_MAX_DAYS, whose mix then stands for a longer window.
    An empty window reports the live multiplier alone."""
    if horizon_days <= 0:
        return [(hour_size_mult(series, start_utc), 1.0)]
    remaining = min(horizon_days, max(FLOOR_PROFILE_MAX_DAYS, 1.0 / 24)) * 24.0
    weights: Dict[float, float] = {}
    t = start_utc
    while remaining > 1e-9:
        nxt = t.replace(minute=0, second=0, microsecond=0) + timedelta(hours=1)
        step = min(remaining, (nxt - t).total_seconds() / 3600.0)
        if step <= 0:
            step = min(remaining, 1.0)
        m = hour_size_mult(series, t + timedelta(hours=step / 2.0))
        weights[m] = weights.get(m, 0.0) + step
        t += timedelta(hours=step)
        remaining -= step
    total = sum(weights.values()) or 1.0
    return sorted((m, w / total) for m, w in weights.items())


def series_max_position(series: str) -> float:
    ov = SERIES_OVERRIDES.get(series)
    base = ov.max_position if (ov and ov.max_position is not None) \
        else MAX_POSITION_CONTRACTS
    # commensurate with the mention ladder multiplier (Jack 2026-07-28);
    # 1.0 for hand-tuned override series via applied_mention_mult
    return base * applied_mention_mult(series)


def series_price_min(series: str) -> int:
    ov = SERIES_OVERRIDES.get(series)
    return ov.price_min_cents if (ov and ov.price_min_cents is not None) \
        else PRICE_MIN_CENTS


def series_price_max(series: str) -> int:
    ov = SERIES_OVERRIDES.get(series)
    return ov.price_max_cents if (ov and ov.price_max_cents is not None) \
        else PRICE_MAX_CENTS


def series_min_hours_to_close(series: str) -> float:
    ov = SERIES_OVERRIDES.get(series)
    return ov.min_hours_to_close if (ov and ov.min_hours_to_close is not None) \
        else MIN_HOURS_TO_CLOSE


def member_price_band(series: str, is_member: bool) -> Tuple[int, int]:
    """Effective quoting band: the series band for fresh placement, widened
    to STICKY_PRICE_MIN/MAX (2-98) for markets already quoting — sticky
    accrual rides to the extremes instead of standing down at 5/90."""
    lo, hi = series_price_min(series), series_price_max(series)
    if is_member:
        lo, hi = min(lo, STICKY_PRICE_MIN), max(hi, STICKY_PRICE_MAX)
    return lo, hi


def series_min_est_total(series: str) -> float:
    """Per-series min-payout entry/hopeless floor, else the global
    MIN_EST_TOTAL_DOLLARS (read at call time so env/test patches apply).

    A per-series OVERRIDE is clamped up to PAYOUT_FLOOR_DOLLARS (2026-08-04):
    the floor is compared against an OPTIMISTIC projection (accrued + best of
    current/1h-peak; members only since 2026-09-13, a fresh candidate is
    judged on current + accrued), so a series bar below the exchange's own $1 minimum
    admits markets whose very best case is a payout of zero. KXTEMP's $0.70
    was exactly that (40 markets landed in the dead $0.70-$1.00 band over the
    2026-08-02..04 window, ~20/day, earning $0). The GLOBAL knob
    is left alone so setting it to 0 still disables floors wholesale, which is
    how the cutoff/mention-window tests isolate their subject.
    2026-09-12: the global moved 1.0 -> 1.5 and KXTEMP dropped its own value,
    so every series reads the same $1.50 unless an override pins one."""
    ov = SERIES_OVERRIDES.get(series)
    if ov and ov.min_est_total is not None:
        return max(ov.min_est_total, PAYOUT_FLOOR_DOLLARS)
    return MIN_EST_TOTAL_DOLLARS


def floor_bar_dollars(series: str, banked: bool) -> float:
    """The min-payout bar a projection must reach. `banked` = the market is
    a current member OR has accrued anything this program period: those
    are judged against the exchange's own PAYOUT_FLOOR_DOLLARS cliff
    (EXIT_FLOOR_IS_PAYOUT, 2026-09-25) because sub-$1 accrual pays NOTHING
    and evicting a market that has banked most of its $1 destroys a
    near-certain credit. A fresh candidate keeps the series entry bar
    (series_min_est_total, $1.50 since 2026-09-12)."""
    if EXIT_FLOOR_IS_PAYOUT and banked:
        return PAYOUT_FLOOR_DOLLARS
    return series_min_est_total(series)


def near_cliff_ok(accrued: float, projected_total: float) -> bool:
    """The near-cliff rule (NEAR_CLIFF_DOLLARS, 2026-09-26): True when this
    period's banked accrual is at least NEAR_CLIFF_MIN_BANKED_FRAC of the
    PAYOUT_FLOOR_DOLLARS cliff AND the projected total (banked + remaining
    window) lands within NEAR_CLIFF_DOLLARS under the cliff. Off outside
    the cliff regime and when the knob is 0."""
    if NEAR_CLIFF_DOLLARS <= 0 or not EXIT_FLOOR_IS_PAYOUT:
        return False
    if accrued < NEAR_CLIFF_MIN_BANKED_FRAC * PAYOUT_FLOOR_DOLLARS:
        return False
    return projected_total >= PAYOUT_FLOOR_DOLLARS - NEAR_CLIFF_DOLLARS


def series_atref_price_tol(series: str) -> int:
    """Per-series at-ref requote hysteresis (ticks), else the global
    ATREF_PRICE_TOL_TICKS (read at call time so env/test patches apply)."""
    ov = SERIES_OVERRIDES.get(series)
    if ov and ov.atref_price_tol_ticks is not None:
        return ov.atref_price_tol_ticks
    return ATREF_PRICE_TOL_TICKS


def series_in_blackout(series: str, now_utc: datetime) -> bool:
    """True while `series` sits inside its daily no-quote window (ET).
    Jack 2026-08-04: AAA posts gas AND diesel between 03:18 and 03:36 ET
    (observed 5 consecutive days by the gas sniper at 5s resolution). The
    DAILY markets close 01:59 ET so they are safe, but the WEEKLY and
    MONTHLY ones stay open straight through the print and were being picked
    off — hour 3 measured -14.4c/contract against a -2.3c book average."""
    ov = SERIES_OVERRIDES.get(series)
    if not ov or not ov.blackout_et:
        return False
    try:
        start_s, end_s = ov.blackout_et
        sh, sm = (int(x) for x in start_s.split(":"))
        eh, em = (int(x) for x in end_s.split(":"))
    except (ValueError, AttributeError):
        return False
    et = now_utc.astimezone(ET)
    if ov.blackout_weekdays_only and et.weekday() >= 5:
        return False
    cur = et.hour * 60 + et.minute
    start, end = sh * 60 + sm, eh * 60 + em
    return start <= cur < end if start <= end else (cur >= start or cur < end)


# STATE STATISTICS RELEASE PAUSE (Jack 2026-10-22: "Can you pause state
# statistics around monthly releases"). The ECONSTATE books (the 10/13 auto
# family, the 10/03 scan graduates) settle months out on a state statistic the
# agency republishes every month: KXTNTRANSEMP-27APR30 settles on BLS series
# SMU47000003133600001's 2026 annual average, so each monthly State Employment
# and Unemployment release -- and the national Employment Situation that state
# payrolls track -- moves its fair while our quotes rest; so do the USDA NASS,
# EIA, Census and FHFA state series on their reports (_AGENCY_RELEASE_RULES).
# A market whose rules cite a source on RELEASE_CALENDAR_FILE stands fully aside from
# RELEASE_PAUSE_BEFORE_MIN before each release to RELEASE_PAUSE_AFTER_MIN after,
# through the blackout path (orders cancelled, the market kept). The sources
# come from the rules text as markets load (release_sources_from_rules); the
# calendar is the agencies' published times, re-read when the file changes.
# A source whose dates run out within RELEASE_CALENDAR_WARN_DAYS logs a warning
# once a day: BLS posts a year's state dates late in the year before.
# WHY 8 HOURS BEFORE TO 24 AFTER: around the 10/20 State release (10:00 ET)
# the 22 mapped series took 22 maker fills from 02:49 ET that night to 08:05
# ET the next morning, -$58 to date (Missouri manufacturing bid 60 @ 75c at
# 02:49 ET, 51c by 10:15) -- ~40% of their fill losses since 9/24 in one day,
# against ~-$3/day on the other days. 30 minutes / 3 hours would have kept
# -$11 of it. Reward forgone: ~9% of the time on ~$0.50/day series.
# IMM_RELEASE_PAUSE=0 turns it off.
RELEASE_PAUSE = os.environ.get("IMM_RELEASE_PAUSE", "1") == "1"
RELEASE_PAUSE_BEFORE_MIN = _env_float("IMM_RELEASE_PAUSE_BEFORE_MIN", 480)
RELEASE_PAUSE_AFTER_MIN = _env_float("IMM_RELEASE_PAUSE_AFTER_MIN", 1440)
RELEASE_CALENDAR_WARN_DAYS = _env_float("IMM_RELEASE_CALENDAR_WARN_DAYS", 35)
RELEASE_CALENDAR_FILE = os.environ.get(
    "IMM_RELEASE_CALENDAR_FILE",
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "release_calendar.json"))
# Dates the IMM family watch reads off the agencies' schedule pages each day
# (imm_release_calendar; Jack 2026-10-22: "check daily for new calendar times
# for any unresolved ones") are merged in from STATUS_DIR, so the repo file is
# never edited in the live checkout. The bot writes its series -> sources map
# there too, for the watch to know which reports are in use.
RELEASE_CALENDAR_FOUND_FILE = "release_calendar_found.json"     # in STATUS_DIR
RELEASE_PAUSE_MAP_FILE = "release_pause_map.json"               # in STATUS_DIR
# BLS state series ids: SM[SU] + state FIPS (2) + area (5, 00000 = statewide)
# + industry (8) + data type (2); LA[SU] + ST|MT + the area for LAUS. A state
# code 00 is national CES, which is not a state statistic.
_BLS_SM_RE = re.compile(r"\bSM[SU](\d{2})(\d{5})\d{10}\b")
_BLS_LA_RE = re.compile(r"\bLA[SU](ST|MT)(\d{2})\d{13}\b")
# BLS QCEW, quarterly: KXAZSEMIJOBS / KXKYDISTEMP name it, not a series id
_BLS_QCEW_RE = re.compile(r"\bQCEW\b|Quarterly Census of Employment and Wages", re.I)
# ...and state payrolls described in words (KXOHMFGEMP "BLS's officially
# published 2026 annual-average Manufacturing employment for Ohio", KXPAMFGEMP,
# KXWAAEROEMP): BLS + employment wording + a state, with no id
_BLS_TEXT_RE = re.compile(r"\bBLS\b|Bureau of Labor Statistics")
_BLS_EMPLOY_RE = re.compile(r"employ|payroll|\bjobs\b", re.I)
_US_STATE_RE = re.compile(
    r"\b(?:Alabama|Alaska|Arizona|Arkansas|California|Colorado|Connecticut|Delaware|"
    r"Florida|Georgia|Hawaii|Idaho|Illinois|Indiana|Iowa|Kansas|Kentucky|Louisiana|"
    r"Maine|Maryland|Massachusetts|Michigan|Minnesota|Mississippi|Missouri|Montana|"
    r"Nebraska|Nevada|New Hampshire|New Jersey|New Mexico|New York|North Carolina|"
    r"North Dakota|Ohio|Oklahoma|Oregon|Pennsylvania|Rhode Island|South Carolina|"
    r"South Dakota|Tennessee|Texas|Utah|Vermont|Virginia|Washington|West Virginia|"
    r"Wisconsin|Wyoming|District of Columbia|Puerto Rico)\b|\bin states and selected areas")
# The other agencies' state statistics (Jack 2026-10-22: "Can you not map
# these?" -- the USDA, EIA, Census permits and FHFA home-price series): the
# agency the rules name, the report's own words, and a state, metro or shale
# play. A national print is left out (KXEIACRUDEW's weekly U.S. crude stocks
# settle AT their release; its -$47 of fills over the past month came a day
# or two before one). Around NASS's 10/09 noon Crop Production the corn-yield books
# took 20 maker fills in the next two hours, -$70 to date (the crop books -$85
# on 24 fills inside the window); its 10/22 3 PM Milk Production filled the
# Wisconsin and Vermont asks 5 times from 14:33 to 15:06 ET (-$14). A report
# whose rules name no agency is matched by EIA's own term for it
# (KXAKCRUDEOIL's "crude oil field production").
_NASS_RE = re.compile(r"\bUSDA\b|\bNASS\b|National Agricultural Statistics")
_EIA_RE = re.compile(r"\bEIA\b|Energy Information Administration")
_CENSUS_RE = re.compile(r"\bCensus\b")
_FHFA_RE = re.compile(r"\bFHFA\b|Federal Housing Finance")
_AGENCY_RELEASE_RULES = (            # (source, agency or None, the report's words)
    ("nass_crop", _NASS_RE, re.compile(
        r"\b(?:corn|soybeans?|cotton|wheat|sorghum|peanuts?|potato(?:es)?|maple syrup)\b"
        r"|Crop Production", re.I)),
    # "or cattle on feed" in KXMTCATTLE's rules is not the report
    ("nass_cof", _NASS_RE, re.compile(r"cattle[- ]on[- ]feed (?:report|inventory)", re.I)),
    ("nass_cattle", _NASS_RE, re.compile(r"cattle and calves|cattle, including calves", re.I)),
    ("nass_milk", _NASS_RE, re.compile(r"\bmilk production\b", re.I)),
    ("nass_poultry", _NASS_RE, re.compile(r"\bbroiler", re.I)),
    ("nass_catfish", _NASS_RE, re.compile(r"\bcatfish\b", re.I)),
    ("eia_epm", _EIA_RE, re.compile(
        r"Electric Power Monthly|net electricity generation|electricity net generation"
        r"|electricity price|price of electricity", re.I)),
    ("eia_psm", None, re.compile(r"field production of crude oil|crude oil field production", re.I)),
    ("eia_ngm", _EIA_RE, re.compile(
        r"marketed natural[- ]gas production|natural gas marketed production", re.I)),
    ("eia_steo", _EIA_RE, re.compile(r"\bSTEO\b|Short-Term Energy Outlook")),
    ("eia_qcr", _EIA_RE, re.compile(r"Quarterly Coal Report", re.I)),
    ("census_bps", _CENSUS_RE, re.compile(r"building permits|housing units authorized", re.I)),
    ("census_popest", _CENSUS_RE, re.compile(r"population estimate", re.I)),
    ("fhfa_hpi", _FHFA_RE, re.compile(r"House Price Index|\bHPI\b")),
)
_SUBNATIONAL_RE = re.compile(_US_STATE_RE.pattern + r"|\bCBSA\b|\bmetropolitan\b|\bformation\b")
_SERIES_RELEASE_SOURCES: Dict[str, Tuple[str, ...]] = {}
_release_cal: dict = {"checked": 0.0, "files": {}, "sources": {}}
_release_warned: Dict[str, str] = {}             # source -> ET day of its last warning


def release_sources_from_rules(text: str) -> Tuple[str, ...]:
    """The release-calendar sources a market's rules tie it to: a statewide
    BLS series -> the State release and the Employment Situation; a metro one
    adds the Metropolitan release; BLS QCEW -> its quarterly release; a state
    statistic from USDA NASS, EIA, Census or FHFA -> that agency's report
    (_AGENCY_RELEASE_RULES)."""
    out: List[str] = []
    for st, area in _BLS_SM_RE.findall(text or ""):
        if st == "00":
            continue
        out += (["bls_state", "bls_empsit"] if area == "00000"
                else ["bls_metro", "bls_state", "bls_empsit"])
    for kind, st in _BLS_LA_RE.findall(text or ""):
        if st == "00":
            continue
        out += (["bls_state", "bls_empsit"] if kind == "ST"
                else ["bls_metro", "bls_state", "bls_empsit"])
    if _BLS_QCEW_RE.search(text or ""):
        out.append("bls_qcew")
    elif not out and _BLS_TEXT_RE.search(text or "") and _BLS_EMPLOY_RE.search(text) \
            and _US_STATE_RE.search(text):
        out += ["bls_state", "bls_empsit"]
    if _SUBNATIONAL_RE.search(text or ""):
        out += [src for src, agency, words in _AGENCY_RELEASE_RULES
                if (agency is None or agency.search(text)) and words.search(text)]
    return tuple(dict.fromkeys(out))


def note_release_sources(series: str, market: Optional[dict]) -> None:
    """Map `series` to its release sources from a market's rules: the first
    market whose rules name one sets it (a market without them leaves the
    series for the next)."""
    if not RELEASE_PAUSE or series in _SERIES_RELEASE_SOURCES or not isinstance(market, dict):
        return
    srcs = release_sources_from_rules(
        " ".join(str(market.get(k) or "") for k in ("rules_primary", "rules_secondary")))
    if srcs:
        _SERIES_RELEASE_SOURCES[series] = srcs
        log(f"[IMM] release pause: {series} -> {'+'.join(srcs)}")
        save_release_pause_map()


def release_calendar_found_path() -> str:
    return os.path.join(STATUS_DIR, RELEASE_CALENDAR_FOUND_FILE)


def release_pause_map_path() -> str:
    return os.path.join(STATUS_DIR, RELEASE_PAUSE_MAP_FILE)


def save_release_pause_map() -> None:
    try:
        tmp = release_pause_map_path() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"updated": datetime.now(timezone.utc).isoformat(),
                       "series": {s: list(v) for s, v in _SERIES_RELEASE_SOURCES.items()}},
                      f, indent=1, sort_keys=True)
        os.replace(tmp, release_pause_map_path())
    except OSError as e:
        log(f"[IMM] ! {RELEASE_PAUSE_MAP_FILE} write failed: {e}")


def load_release_calendar(force: bool = False) -> Dict[str, Tuple[str, List[datetime]]]:
    """{source: (name, sorted UTC release times)} from RELEASE_CALENDAR_FILE
    and the watch's found dates (release_calendar_found_path()), each re-read
    when its mtime changes (looked at once a minute). An unreadable file keeps
    its last good read."""
    now = time.time()
    if not force and now - _release_cal["checked"] < 60:
        return _release_cal["sources"]
    _release_cal["checked"] = now
    paths = (RELEASE_CALENDAR_FILE, release_calendar_found_path())
    changed = False
    for path in paths:
        try:
            mt = os.path.getmtime(path)
        except OSError:
            continue
        prev = _release_cal["files"].get(path)
        if prev is not None and prev[0] == mt:
            continue
        try:
            with open(path, encoding="utf-8") as f:
                raw = json.load(f)
            recs = {}
            for key, rec in (raw.get("sources") or {}).items():
                recs[key] = (str(rec.get("name") or key),
                             [ET.localize(datetime.strptime(s, "%Y-%m-%d %H:%M"))
                              .astimezone(timezone.utc) for s in rec.get("times_et") or []])
            _release_cal["files"][path] = (mt, recs)
            changed = True
        except (OSError, ValueError, TypeError, AttributeError) as e:
            log(f"[IMM] ! release calendar {path} unreadable "
                f"({type(e).__name__}: {e}) -- keeping the last good read")
    if changed:
        names: Dict[str, str] = {}
        times: Dict[str, set] = {}
        for path in paths:                          # the repo file names a source first
            for key, (name, ts) in (_release_cal["files"].get(path) or (0, {}))[1].items():
                names.setdefault(key, name)
                times.setdefault(key, set()).update(ts)
        _release_cal["sources"] = {k: (names[k], sorted(times[k])) for k in names}
    return _release_cal["sources"]


def series_release_window(series: str, now_utc: datetime) -> Optional[Tuple[str, datetime]]:
    """(release name, release time UTC) while `series` is inside a release
    pause, else None."""
    srcs = _SERIES_RELEASE_SOURCES.get(series) if RELEASE_PAUSE else None
    if not srcs:
        return None
    cal = load_release_calendar()
    before = timedelta(minutes=RELEASE_PAUSE_BEFORE_MIN)
    after = timedelta(minutes=RELEASE_PAUSE_AFTER_MIN)
    hit = None
    for s in srcs:
        name, times = cal.get(s, (s, []))
        last = times[-1] if times else None
        day = now_utc.astimezone(ET).strftime("%Y-%m-%d")
        if (last is None or last < now_utc + timedelta(days=RELEASE_CALENDAR_WARN_DAYS)) \
                and _release_warned.get(s) != day:
            _release_warned[s] = day
            log(f"[IMM] ! release calendar: {name} has "
                + (f"no date after {last.astimezone(ET):%Y-%m-%d}" if last else "no dates")
                + f" -- add the next ones to {os.path.basename(RELEASE_CALENDAR_FILE)} "
                  f"(state statistics pause around them)")
        for t in times:
            if hit is None and t - before <= now_utc < t + after:
                hit = (name, t)
    return hit


def series_fast_lane(series: str) -> bool:
    """Membership in the FAST_LANE_SECS mini-cycle set (KXTEMP by default)."""
    ov = SERIES_OVERRIDES.get(series)
    return bool(ov and ov.fast_lane)


def series_min_est_rate(series: str) -> float:
    """Per-series est-$/day RATE floor for fresh candidates (0 = off)."""
    ov = SERIES_OVERRIDES.get(series)
    return ov.min_est_per_day if (ov and ov.min_est_per_day) else 0.0


def series_safe_join(series: str) -> bool:
    ov = SERIES_OVERRIDES.get(series)
    return bool(ov and ov.safe_join)


def series_unwind_full(series: str) -> bool:
    ov = SERIES_OVERRIDES.get(series)
    return bool(ov and ov.unwind_full_position)


def unwind_side_sizes(series: str, pos: float, maxpos: float) -> Tuple[int, int]:
    """(bid, ask) size floors under FULL UNWIND (Jack 2026-10-01, on
    KXNFLESCALATORRSHYDS-26OCT01PITCLE-PITJWARREN30: short 240 at the skew
    limit, the reducing bid resting only the ladder's 80 -- "happy to unload
    the whole position on the other side so can quote 240"). The side that
    reduces `pos` may rest the whole position, in whole contracts and never
    more than the market's position cap, so one fill can flatten it; the
    other side gets no floor. (0, 0) when flat or off the family."""
    if not series_unwind_full(series) or abs(pos) < 1:
        return 0, 0
    n = int(min(abs(pos), maxpos))
    return (n, 0) if pos < 0 else (0, n)


def series_pre_cutoff_reduce_only_secs(series: str) -> int:
    ov = SERIES_OVERRIDES.get(series)
    return ov.pre_cutoff_reduce_only_secs \
        if (ov and ov.pre_cutoff_reduce_only_secs is not None) \
        else PRE_CUTOFF_REDUCE_ONLY_SECS


