# "KXOSCAR" and "KXCRITICS" are); its override is registered beside
# AWARDS_SERIES, where AWARDS_PRE_EVENT_DAYS is known
AWARDS_AUTO_PARENT = "KXAWARDSAUTO"
AWARDS_AUTO_EVENT_TOP_N = _env_int("IMM_AWARDS_AUTO_EVENT_TOP_N", 3)
AWARDS_EXCLUDE = frozenset(
    s.strip() for s in os.environ.get("IMM_AWARDS_EXCLUDE", "").split(",")
    if s.strip())
AWARDS_EXTRA_SERIES: Set[str] = set()
_awards_extra_state = {"mtime": 0.0}


def awards_extra_path() -> str:
    return os.path.join(STATUS_DIR, AWARDS_EXTRA_FILE)


def load_awards_extra_series() -> int:
    """Re-read AWARDS_EXTRA_FILE when it changed; members changed, else 0.
    Refuses blocklisted series, mention books and AWARDS_EXCLUDE."""
    try:
        mtime = os.path.getmtime(awards_extra_path())
    except OSError:
        return 0
    if mtime == _awards_extra_state["mtime"]:
        return 0
    _awards_extra_state["mtime"] = mtime
    try:
        with open(awards_extra_path(), encoding="utf-8") as f:
            data = json.load(f) or {}
    except (OSError, ValueError) as e:
        log(f"[IMM] ! awards extra file unreadable: {e}")
        return 0
    fresh: Set[str] = set()
    for s in data.get("series") or []:
        s = str(s).strip()
        if not s or not s.startswith("KX") or "MENTION" in s or s in AWARDS_EXCLUDE:
            continue
        if any(s.startswith(p) for p in SERIES_BLOCKLIST_PREFIXES) \
                or series_pattern_blocked(s):
            log(f"[IMM] ! refused blocklisted series in awards extra: {s}")
            continue
        fresh.add(s)
    changed = len(fresh ^ AWARDS_EXTRA_SERIES)
    AWARDS_EXTRA_SERIES.clear()
    AWARDS_EXTRA_SERIES.update(fresh)
    if changed:
        log(f"[IMM] awards extra series: {len(fresh)} enrolled "
            f"({changed} changed)")
    return changed


def awards_extra_series(series: str) -> bool:
    """An awards family member by Kalshi tag (AWARDS_EXTRA_FILE); nothing
    while IMM_AWARDS_AUTO=0."""
    return AWARDS_AUTO and series in AWARDS_EXTRA_SERIES


def awards_auto_rules(series: str) -> bool:
    """A tag member running on the awards rule set: its override is the
    family parent's (or not yet inherited, before the refresh's
    ensure_family_override). A code family that covers the series as well
    (KXCMA's undated guard set) keeps its own caps too."""
    ov = SERIES_OVERRIDES.get(series)
    return awards_extra_series(series) and (
        ov is None or ov == SERIES_OVERRIDES.get(AWARDS_AUTO_PARENT))


# NFL GAME / SEASON FAMILIES, AUTO-ENROLLED (Jack 2026-10-12: "can you
# automatically quote new NFL game families, like how new election families
# are automatically quoted?" -> scope "anything tied to a single NFL game or
# season props", start "Pilot size, you upsize"; then "any props that go
# beyond a single game, should be turned off anytime there's a live game").
# The new-series pass (imm_earnings_overrides.enroll_new_series, run by the
# 30-min family watch and the overrides task) writes each newly paying,
# not-yet-allowed KXNFL series that Kalshi files under Sports / Football --
# less the off-field contracts (draft, combine, stadium, sellouts, player
# contracts, trades, coaching, Hall of Fame ...) and the hand-configured
# families (ladders / escalators, H2H: nfl_hand_configured, refused by name
# here and in the loader even with their own switches off) -- into
# NFL_AUTO_FILE and emails it:
#   {"series": {S: {"kind": "game" | "season", "buffer_min": int | null,
#                   "size": "pilot" | "ladder", "title", "contract", "since"}}}
# Hot-reloaded by mtime at import and every universe refresh. A member
# quotes with this guard set (nfl_auto_override):
#   kind "game"   -- one NFL game per event ("26OCT12BUFLAR"): cut off at
#                    the ESPN NFL scoreboard's kickoff less buffer_min -- 0
#                    when Kalshi's rules resolve a player who does not enter
#                    the game at a fair price, else NFL_AUTO_INACTIVE_BUFFER_MIN
#                    (90, the inactive list) -- plus the ladders' team-news
#                    hold (nfl_team_news_gate).
#   kind "season" -- beyond a single game (season / weekly props): no cutoff
#                    (the undated guard set's precedent) and NO QUOTES WHILE
#                    ANY NFL GAME IS LIVE (nfl_live_verdict: kicked off and
#                    not yet final, plus NFL_LIVE_COOLDOWN_MIN after it goes
#                    final; a scoreboard that cannot be read counts as live).
#   size "pilot"  -- the default (Jack the same evening: "do a 3x
#                    multiplier, include overnight/saturday scale ups. raise
#                    halt to $100/day and make it per event. set event caps
#                    to be same as ladder/escalator"; it first shipped at 20
#                    lots x1, 100 / 100, $40 per series): safe-join, the
#                    family size_mult NFL_AUTO_SIZE_MULT (x3: the rung, the
#                    per-market cap and the skew knees together -- 60 lots,
#                    450 per market at the launcher's 20 / 150), the
#                    overnight quiet hours and the Saturday step on top
#                    (never daily-classified; no evening window, as the
#                    ladders), the deep-reference size, the ladders' event
#                    cap, and a daily loss halt PER EVENT at
#                    -NFL_AUTO_DAILY_LOSS_LIMIT ($100) on the pilots' halt
#                    machinery (pilot_budget_key "NFLAUTO:<event>").
#   size "ladder" -- upsized by hand ("size" in the file): safe-join and the
#                    sports ladders' multipliers (family size_mult, the flat
#                    hour multiplier, Saturday), the same event cap, no
#                    halt.
# IMM_NFL_AUTO_ENABLE=0 takes every member out; positions ride.
NFL_AUTO_ENABLE = os.environ.get("IMM_NFL_AUTO_ENABLE", "1") == "1"
NFL_AUTO_FILE = "nfl_auto_series.json"                  # in STATUS_DIR
NFL_AUTO_INACTIVE_BUFFER_MIN = _env_int("IMM_NFL_AUTO_INACTIVE_BUFFER_MIN", 90)
NFL_AUTO_SIZE_MULT = _env_float("IMM_NFL_AUTO_SIZE_MULT", 3.0)
NFL_AUTO_DAILY_LOSS_LIMIT = _env_float("IMM_NFL_AUTO_DAILY_LOSS_LIMIT", 100)   # per event
NFL_LIVE_COOLDOWN_MIN = _env_int("IMM_NFL_LIVE_COOLDOWN_MIN", 15)
NFL_LIVE_TTL_SECS = _env_int("IMM_NFL_LIVE_TTL_SECS", 60)
NFL_AUTO_SERIES: Dict[str, dict] = {}
_nfl_auto_state: dict = {"mtime": 0.0, "installed": set()}


def nfl_auto_path() -> str:
    return os.path.join(STATUS_DIR, NFL_AUTO_FILE)


def nfl_auto_entry(series: str) -> Optional[dict]:
    """The series' NFL auto-family entry, None when it is not a member (or
    the family is off)."""
    return NFL_AUTO_SERIES.get(series) if NFL_AUTO_ENABLE else None


def nfl_auto_game(series: str) -> bool:
    e = nfl_auto_entry(series)
    return bool(e) and e["kind"] == "game"


def nfl_auto_season(series: str) -> bool:
    e = nfl_auto_entry(series)
    return bool(e) and e["kind"] == "season"


def nfl_auto_pilot(series: str) -> bool:
    e = nfl_auto_entry(series)
    return bool(e) and e["size"] == "pilot"


def nfl_auto_ladder(series: str) -> bool:
    e = nfl_auto_entry(series)
    return bool(e) and e["size"] == "ladder"


def nfl_auto_override(entry: dict) -> "SeriesOverride":
    """A member's guard set (see NFL_AUTO_ENABLE): safe-join always; a game
    member's start buffer; the family multiplier NFL_AUTO_SIZE_MULT, or the
    ladders' at ladder size."""
    kw: dict = {"safe_join": True}
    if entry["kind"] == "game":
        kw["start_buffer_min"] = int(entry["buffer_min"])
    if entry["size"] == "ladder":
        kw["size_mult"] = SERIES_OVERRIDES["KXNFLLADDERREC"].size_mult
    else:
        kw["size_mult"] = NFL_AUTO_SIZE_MULT
    return SeriesOverride(**kw)


def nfl_hand_configured(series: str) -> bool:
    """An NFL family with hand-set rules of its own -- the sports ladders /
    escalators and the head-to-head pilot -- matched by NAME, whatever its
    kill switch says, so the auto family never takes one in and a family
    switched off stays off. (nfl_h2h_series reads False with the H2H switch
    off, and at the import-time load, which runs before NFL_H2H_ENABLE is
    defined -- 2026-10-12.)"""
    return bool(sports_ladder_league(series) or NFL_H2H_RE.match(series))


def load_nfl_auto_series() -> int:
    """Hot-reload NFL_AUTO_FILE by mtime into NFL_AUTO_SERIES and (re)install
    each member's guard set; entries changed on a reload, else 0. Refuses
    blocklisted series and the hand-configured NFL families (the ladders /
    escalators and the head-to-head pilot keep their own rules,
    nfl_hand_configured)."""
    try:
        mtime = os.path.getmtime(nfl_auto_path())
    except OSError:
        return 0
    if mtime == _nfl_auto_state["mtime"]:
        return 0
    _nfl_auto_state["mtime"] = mtime
    try:
        with open(nfl_auto_path(), encoding="utf-8") as f:
            data = json.load(f) or {}
    except (OSError, ValueError) as e:
        log(f"[IMM] ! nfl auto file unreadable: {e}")
        return 0
    fresh: Dict[str, dict] = {}
    for s_, e in (data.get("series") or {}).items():
        s_ = str(s_).strip()
        if not s_.startswith("KXNFL") or not isinstance(e, dict):
            continue
        if any(s_.startswith(p_) for p_ in SERIES_BLOCKLIST_PREFIXES):
            log(f"[IMM] ! refused blocklisted series in nfl auto: {s_}")
            continue
        if nfl_hand_configured(s_):
            log(f"[IMM] ! refused hand-configured NFL family in nfl auto: {s_}")
            continue
        kind, size = e.get("kind"), e.get("size") or "pilot"
        if kind not in ("game", "season") or size not in ("pilot", "ladder"):
            log(f"[IMM] ! nfl auto {s_}: kind/size {kind!r}/{size!r} not understood, skipped")
            continue
        try:
            buf = int(e["buffer_min"]) if e.get("buffer_min") is not None \
                else NFL_AUTO_INACTIVE_BUFFER_MIN
        except (TypeError, ValueError):
            buf = NFL_AUTO_INACTIVE_BUFFER_MIN
        fresh[s_] = {"kind": kind, "size": size, "buffer_min": max(0, buf),
                     "title": str(e.get("title") or "")}
    for s_ in _nfl_auto_state["installed"] - set(fresh):
        SERIES_OVERRIDES.pop(s_, None)
    for s_, e in fresh.items():
        SERIES_OVERRIDES[s_] = nfl_auto_override(e)
    changed = sum(1 for s_ in set(fresh) | set(NFL_AUTO_SERIES)
                  if fresh.get(s_) != NFL_AUTO_SERIES.get(s_))
    NFL_AUTO_SERIES.clear()
    NFL_AUTO_SERIES.update(fresh)
    _nfl_auto_state["installed"] = set(fresh)
    if changed:
        log(f"[IMM] nfl auto families: {len(fresh)} enrolled ({changed} changed)")
    return changed


def nfl_live_verdict(get_json, now_ts: float,
                     final_seen: Dict[str, float]) -> Tuple[Optional[bool], str]:
    """(True, why) while any NFL game is live -- past its scheduled kickoff
    and not final, or final less than NFL_LIVE_COOLDOWN_MIN ago (by when
    `final_seen` first saw it; a game that kicked off over 5h ago is long
    over); (False, '') when none is; (None, why) when the scoreboard cannot
    be read -- callers treat that as live (fail closed). Reads today's ET
    scoreboard, and yesterday's before 4am ET (a late game past midnight)."""
    return espn_live_verdict("NFL", get_json, now_ts, final_seen,
                             NFL_LIVE_COOLDOWN_MIN, 5.0, "kickoff")


def espn_live_verdict(league: str, get_json, now_ts: float,
                      final_seen: Dict[str, float], cooldown_min: float,
                      over_after_h: float, start_word: str
                      ) -> Tuple[Optional[bool], str]:
    """nfl_live_verdict for any ESPN_LEAGUE_PATHS league: live while a game
    is past its scheduled start and not final, or final less than
    `cooldown_min` ago (a final that started over `over_after_h` hours ago is
    long over); None when the scoreboard cannot be read."""
    now = datetime.fromtimestamp(now_ts, timezone.utc)
    et = now.astimezone(ET)
    days = [et.date()] + ([et.date() - timedelta(days=1)] if et.hour < 4 else [])
    for d in days:
        try:
            data = get_json(f"{ESPN_SITE_API}/{ESPN_LEAGUE_PATHS[league]}/"
                            f"scoreboard?dates={d.strftime('%Y%m%d')}")
        except Exception as e:                       # noqa: BLE001
            return None, f"{league} scoreboard unreadable ({type(e).__name__})"
        for ev in (data or {}).get("events") or []:
            st = (ev.get("status") or {}).get("type") or {}
            name, state = str(st.get("name") or ""), str(st.get("state") or "")
            if name in ("STATUS_POSTPONED", "STATUS_CANCELED", "STATUS_CANCELLED"):
                continue
            kick = parse_iso_utc(ev.get("date", ""))
            short = ev.get("shortName") or ev.get("id") or "game"
            if state == "in":
                return True, f"{short} live ({st.get('detail') or name})"
            if state == "post" or st.get("completed"):
                if kick is not None and now - kick > timedelta(hours=over_after_h):
                    continue
                gid = str(ev.get("id") or short)
                first = final_seen.setdefault(gid, now_ts)
                if now_ts - first < cooldown_min * 60:
                    return True, (f"{short} final {(now_ts - first) / 60:.0f}m ago "
                                  f"(cooldown {cooldown_min:g}m)")
                continue
            if kick is not None and kick <= now:
                return True, f"{short} past {start_word}, not yet live on ESPN"
    return False, ""


# MLB POSTSEASON MVPs (Jack 2026-10-12: "yes quote MLB MVPs under a
# no-quotes-during-games rule"). KXMLBALCSMVP / KXMLBNLCSMVP / KXMLBWSMVP:
# one market per player ("If <player> wins the ... MVP in the 2026 season"),
# 49 / 49 / 98 markets, $100 per market per period on the 10/12 programs
# (~$7.6k across the three); not award-tagged (Sports / Baseball). Kalshi's
# dates are placeholders (close Dec 8, expiration Dec 31; can_close_early),
# so the markets give no cutoff. The MVP is decided INSIDE games -- every
# at-bat moves it -- and announced on the field minutes after the clinching
# out, before Kalshi closes the event. So a member sits out (orders
# cancelled, positions ride):
#   * while ANY MLB game is live -- espn_live_verdict on ESPN's MLB board:
#     started and not final, or final under MLB_LIVE_COOLDOWN_MIN ago (an
#     LCS game moves the World Series MVP too) -- the NFL season props' rule;
#   * for good once its ROUND is decided: a game of that round ("ALCS - Game
#     7", "World Series - Game 4" in ESPN's notes) whose series is completed,
#     on today's board or the MLB_DECIDED_LOOKBACK_DAYS before it (sticky for
#     the process; after that the repriced book -- 1c / 99c -- is outside the
#     band anyway);
#   * whenever a board cannot be read (fail closed).
# Safe-join, the standard ladder and caps (no family size). Exact series
# names only: KXMLBMENTION is mlb_trading.py's book. IMM_MLB_MVP_ENABLE=0
# takes them out.
MLB_MVP_ENABLE = os.environ.get("IMM_MLB_MVP_ENABLE", "1") == "1"
# series -> the ESPN round its MVP is decided in (the game note's prefix)
MLB_MVP_ROUNDS = {"KXMLBALCSMVP": "ALCS", "KXMLBNLCSMVP": "NLCS",
                  "KXMLBWSMVP": "World Series"}
MLB_LIVE_COOLDOWN_MIN = _env_int("IMM_MLB_LIVE_COOLDOWN_MIN", 15)
MLB_LIVE_TTL_SECS = _env_int("IMM_MLB_LIVE_TTL_SECS", 60)
MLB_GAME_OVER_AFTER_H = _env_float("IMM_MLB_GAME_OVER_AFTER_H", 8.0)  # extra innings
MLB_DECIDED_LOOKBACK_DAYS = _env_int("IMM_MLB_DECIDED_LOOKBACK_DAYS", 3)
# x2 on every MVP series (Jack 2026-10-13: "2x" after "KXMLBWSMVP-26 is not
# quoting", then "why not 2x the other MVP markets?"). Every in-band WS MVP
# player sat on payout_floor -- touches ~2,000 contracts deep, our share 2-7%,
# $0.19-0.92 projected per market over the 1.5 days left in the program (to
# 10/14 23:19Z) against the $1.30 bar; at x2 Ramirez / Caminero / Chourio
# project ~$1.4-1.8. The LCS MVPs at x1 quoted two NLCS markets (Contreras,
# Turang) with three ALCS ones just under the bar (Diaz / Ramirez / Caminero
# $0.73-1.06). The family size_mult wire scales rungs, caps and skew knees
# together. IMM_MLB_MVP_SIZE_MULT=1 reverts.
MLB_MVP_SIZE_MULT = _env_float("IMM_MLB_MVP_SIZE_MULT", 2.0)
for _s in MLB_MVP_ROUNDS:
    SERIES_OVERRIDES[_s] = SeriesOverride(safe_join=True, size_mult=MLB_MVP_SIZE_MULT)


def mlb_mvp_series(series: str) -> bool:
    """A postseason MVP series (MLB_MVP_ROUNDS); nothing while
    IMM_MLB_MVP_ENABLE=0."""
    return MLB_MVP_ENABLE and series in MLB_MVP_ROUNDS


def mlb_rounds_decided(board) -> Dict[str, str]:
    """{round: series summary} for the postseason rounds an ESPN MLB board
    shows decided: a game whose series is completed (the clinching game,
    "TOR wins series 4-3"), or a side with the wins to take it."""
    out: Dict[str, str] = {}
    for ev in (board or {}).get("events") or []:
        comp = (ev.get("competitions") or [{}])[0]
        rnd = " ".join(str(n.get("headline") or "")
                       for n in comp.get("notes") or []).split(" - ")[0].strip()
        ser = comp.get("series") or {}
        if not rnd or not ser:
            continue
        total = int(ser.get("totalCompetitions") or 0)
        wins = max((int(c.get("wins") or 0) for c in ser.get("competitors") or []),
                   default=0)
        if ser.get("completed") or (total and wins >= total // 2 + 1):
            out[rnd] = str(ser.get("summary") or f"{wins} wins")
    return out


# NBA / WNBA / MLB / NHL FAMILIES, AUTO-ENROLLED (Jack 2026-10-15:
# "KXWNBAFINALSMVP should be quoted", then "New NBA, WNBA, MLB families
# should be auto quoted like elections, nfl, etc", then "same with NHL e.g.
# KXNHLSEASONGOALS, KXNHLSEASONPPTS"; League of Legends rides the same
# family on a live feed of its own, see LOL_API). The NFL auto family's
# machinery (NFL_AUTO_ENABLE) for three more leagues. The new-series pass
# (imm_earnings_overrides.enroll_new_series, run by the 30-min family watch
# and the overrides task) writes each newly paying, not-yet-allowed KXNBA /
# KXWNBA / KXMLB / KXNHL series that Kalshi files under Sports with the
# league's tag (Basketball / Baseball / Hockey) -- less the off-field contracts (team sales,
# franchise values, next team, attendance, plus the NFL family's list) and
# the families with hand-set rules (league_hand_configured: the sports
# ladders / escalators, the MLB postseason MVPs, the mention books, the
# exact sports allowlist) -- into LEAGUE_AUTO_FILE and emails it:
#   {"series": {S: {"league": "NBA" | "WNBA" | "MLB" | "NHL" | "LOL",
#                   "kind": "game" | "season",
#                   "buffer_min": int | null, "size": "pilot",
#                   "decided_by": round | null, "title", "contract", "since"}}}
# Hot-reloaded by mtime at import and every universe refresh. A member
# quotes with this guard set (league_auto_override):
#   kind "game"   -- one game per event ("26OCT21LALGSW"): cut off at the
#                    league's ESPN scoreboard start less buffer_min. These
#                    leagues have no team-news feed (the NFL family's hold
#                    reads nflverse rosters), so a game member is out
#                    LEAGUE_AUTO_GAME_BUFFER_MIN (90) before the start: the
#                    injury report / lineup window.
#   kind "season" -- beyond a single game (awards, playoff props, series):
#                    no cutoff; NO QUOTES WHILE ANY GAME OF ITS LEAGUE IS
#                    LIVE (espn_live_verdict, plus LEAGUE_LIVE_COOLDOWN_MIN
#                    after it goes final; a board that cannot be read counts
#                    as live); and with "decided_by" -- the ESPN round its
#                    result is settled in ("WNBA Finals", "NBA Finals",
#                    "World Series", "ALCS", "NLCS", "Stanley Cup Final") --
#                    out for good once that
#                    round is decided: the MLB MVPs' rule, since a Finals MVP
#                    is announced on the floor minutes after the clinching
#                    game, before Kalshi closes the event.
#   size "pilot"  -- the NFL auto family's pilot as it stands (959080a):
#                    safe-join, the family size_mult LEAGUE_AUTO_SIZE_MULT
#                    (x3), the overnight quiet hours and the Saturday step
#                    (never daily, no evening window), the ladders' event cap
#                    and a daily loss halt PER EVENT at
#                    -LEAGUE_AUTO_DAILY_LOSS_LIMIT ($100) on the pilots' halt
#                    machinery (pilot_budget_key "LEAGUEAUTO:<event>").
# New KXNBA / KXWNBA / KXMLB events land on Kalshi's exchange shard 3
# (baseball / basketball / tennis), which holds its own cash: an empty shard
# refuses every order (imm_health_alert emails when one runs dry).
# IMM_LEAGUE_AUTO_ENABLE=0 takes every member out; positions ride.
LEAGUE_AUTO_ENABLE = os.environ.get("IMM_LEAGUE_AUTO_ENABLE", "1") == "1"
LEAGUE_AUTO_FILE = "league_auto_series.json"              # in STATUS_DIR
# series prefix -> league (KXNBA does not prefix KXWNBA: the W comes first)
LEAGUE_AUTO_PREFIXES = {"KXNBA": "NBA", "KXWNBA": "WNBA", "KXMLB": "MLB",
                        "KXNHL": "NHL"}
LEAGUE_AUTO_GAME_BUFFER_MIN = _env_int("IMM_LEAGUE_AUTO_GAME_BUFFER_MIN", 90)
LEAGUE_AUTO_SIZE_MULT = _env_float("IMM_LEAGUE_AUTO_SIZE_MULT", NFL_AUTO_SIZE_MULT)
LEAGUE_AUTO_DAILY_LOSS_LIMIT = _env_float("IMM_LEAGUE_AUTO_DAILY_LOSS_LIMIT", 100)  # per event
LEAGUE_LIVE_COOLDOWN_MIN = _env_int("IMM_LEAGUE_LIVE_COOLDOWN_MIN", 15)
LEAGUE_LIVE_TTL_SECS = _env_int("IMM_LEAGUE_LIVE_TTL_SECS", 60)
# a final that started this long ago is long over (MLB: extra innings)
LEAGUE_GAME_OVER_AFTER_H = {"NBA": 4.0, "WNBA": 4.0, "MLB": MLB_GAME_OVER_AFTER_H,
                            "NHL": 4.0}
LEAGUE_START_WORD = {"NBA": "tip-off", "WNBA": "tip-off", "MLB": "first pitch",
                     "NHL": "puck drop"}
LEAGUE_DECIDED_ROUNDS = frozenset({"NBA Finals", "WNBA Finals", "World Series",
                                   "ALCS", "NLCS", "Stanley Cup Final"})
LEAGUE_AUTO_BUDGET_PREFIX = "LEAGUEAUTO:"
LEAGUE_AUTO_SERIES: Dict[str, dict] = {}
_league_auto_state: dict = {"mtime": 0.0, "installed": set()}
# TEAM-NEWS HOLD for the league auto families' GAME members (Jack 2026-10-22:
# "Build it", to "Should I build an NBA team-news hold like NFL's?"). An NFL
# auto game member stands aside NFL_NEWS_HOLD_MIN after team news
# (nfl_team_news_gate); a league game member had only its pre-start cutoff,
# and an NBA star ruled out three hours before tip moves every prop of his
# game. league_news.py reads ESPN's league-wide injury report (one call)
# every LEAGUE_NEWS_REFRESH_SECS into _league_news_state, each read diffed
# against the last; league_news_gate holds a game member of a
# LEAGUE_NEWS_LEAGUES league while either of its teams had a report change
# -- a status set or changed, or a player cleared -- inside
# LEAGUE_NEWS_HOLD_MIN, failing CLOSED on a missing or stale read
# (LEAGUE_NEWS_TTL_MIN) and on a ticker whose two teams it cannot name.
# 10/22, 38 open KXNBAGAME events: every one named its two teams (Kalshi's
# GSW / NOP / NYK / SAS / UTA / WAS are ESPN's GS / NO / NY / SA / UTAH /
# WSH); the report carried 72 players on 26 teams. IMM_LEAGUE_NEWS_LEAGUES=""
# turns it off (the cutoff alone again).
LEAGUE_NEWS_LEAGUES: Tuple[str, ...] = tuple(
    s.strip().upper() for s in os.environ.get("IMM_LEAGUE_NEWS_LEAGUES", "NBA").split(",")
    if s.strip())
LEAGUE_NEWS_HOLD_MIN = _env_int("IMM_LEAGUE_NEWS_HOLD_MIN", 15)
LEAGUE_NEWS_REFRESH_SECS = _env_int("IMM_LEAGUE_NEWS_REFRESH_SECS", 120)
LEAGUE_NEWS_TTL_MIN = _env_int("IMM_LEAGUE_NEWS_TTL_MIN", 10)
LEAGUE_NEWS_TEAMS_TTL_SECS = 6 * 3600
_league_news_state: Dict[str, dict] = {}


def league_news_gate(ticker: str, league: str, now_ts: float) -> Tuple[str, dict]:
    """('', {}) when a league auto GAME member may quote, else (why,
    guard-skip inputs): the team-news hold above for a LEAGUE_NEWS_LEAGUES
    league, failing CLOSED; any other league quotes on its cutoff alone."""
    if league not in LEAGUE_NEWS_LEAGUES:
        return "", {}
    snap = _league_news_state.get(league)
    if snap is None:
        return f"no {league} injury-report read yet", {"reason": "no_read"}
    age = now_ts - float(snap.get("ts") or 0.0)
    if age > LEAGUE_NEWS_TTL_MIN * 60:
        return (f"{league} injury-report read is {age / 60:.0f}m old",
                {"reason": "stale", "age_s": round(age)})
    try:
        import league_news as _ln
        pair = _ln.team_pair(snap, ticker)
    except Exception as e:                       # noqa: BLE001
        return (f"team parse failed: {type(e).__name__}",
                {"reason": "teams", "err": str(e)[:120]})
    if not pair:
        return "teams not parsed from the ticker", {"reason": "teams"}
    for team in pair:
        ctx = (snap.get("teams") or {}).get(team) or {}
        nat = ctx.get("news_at")
        if LEAGUE_NEWS_HOLD_MIN > 0 and nat is not None:
            nage = now_ts - float(nat)
            # a stamp a little ahead of our clock still holds; far ahead is junk
            if -600.0 <= nage < LEAGUE_NEWS_HOLD_MIN * 60:
                return (f"{team} news: {ctx.get('news')} {max(0.0, nage) / 60:.0f}m "
                        f"ago (hold {LEAGUE_NEWS_HOLD_MIN}m)",
                        {"reason": "news_hold", "team": team,
                         "news": ctx.get("news"), "age_s": round(nage)})
    return "", {}


def league_auto_path() -> str:
    return os.path.join(STATUS_DIR, LEAGUE_AUTO_FILE)


def series_league(series: str) -> Optional[str]:
    """'KXWNBAFINALSMVP' -> 'WNBA', 'KXMLBPLAYOFFHRS' -> 'MLB'; None for any
    series outside the three leagues."""
    for prefix, league in LEAGUE_AUTO_PREFIXES.items():
        if series.startswith(prefix):
            return league
    return None


def league_auto_entry(series: str) -> Optional[dict]:
    """The series' league auto-family entry, None when it is not a member
    (or the family is off)."""
    return LEAGUE_AUTO_SERIES.get(series) if LEAGUE_AUTO_ENABLE else None


def league_auto_game(series: str) -> bool:
    e = league_auto_entry(series)
    return bool(e) and e["kind"] == "game"


def league_auto_season(series: str) -> bool:
    e = league_auto_entry(series)
    return bool(e) and e["kind"] == "season"


def league_auto_pilot(series: str) -> bool:
    e = league_auto_entry(series)
    return bool(e) and e["size"] == "pilot"


def league_hand_configured(series: str) -> bool:
    """A league family with hand-set rules of its own, matched by NAME so the
    auto family never takes one in: the sports ladders / escalators, the MLB
    postseason MVPs (MLB_MVP_ROUNDS), the mention books (KXMLBMENTION is
    mlb_trading.py's) and the exact sports allowlist (KXMLBPLAYOFFS,
    KXMLBSEASONGAMES: the undated guard set)."""
    return (bool(sports_ladder_league(series)) or series in MLB_MVP_ROUNDS
            or "MENTION" in series or series in globals().get("ALLOW_SERIES", ()))


def league_auto_override(entry: dict) -> "SeriesOverride":
    """A member's guard set (see LEAGUE_AUTO_ENABLE): safe-join, the family
    multiplier and, for a game member, its start buffer."""
    kw: dict = {"safe_join": True, "size_mult": LEAGUE_AUTO_SIZE_MULT}
    if entry["kind"] == "game":
        kw["start_buffer_min"] = int(entry["buffer_min"])
    return SeriesOverride(**kw)


# LEAGUE OF LEGENDS (esports; Jack 2026-10-15: "also build auto-quoting for
# esports similar to existing sports categories e.g. KXLOLQUALIFIERS,
# KXLOLAWARD, KXLOLREGION, KXLOL"). ESPN does not carry esports, so the LoL
# members ("league": "LOL" in LEAGUE_AUTO_FILE, written for Kalshi's
# Esports-tagged League of Legends series) read lolesports.com's own feed
# (LOL_API getLive / getSchedule, with the x-api-key the site's front end
# ships: undocumented, so a read that fails means no quotes). SEASON members
# only: the single-match markets (KXLOLGAME / KXLOLMAP ...) stay in review,
# because Kalshi's ticker times do not match the official schedule
# (KXLOLGAME-26OCT151400MVKFUR started 23:00Z on 10/15), so any cutoff would
# be a guess. A member sits out:
#   * while a match of its tournament (lol_event_tournament: Worlds / MSI /
#     EWC / Demacia Cup, else any LoL match) is in progress, or past its
#     scheduled start and not yet live, plus LEAGUE_LIVE_COOLDOWN_MIN after
#     the last live sighting;
#   * for good once its deciding stage (lol_deciding_stage) has every match
#     of the current edition completed: Worlds quarterfinalists on the Swiss
#     stage, semifinalists on the quarterfinals, finalists on the semifinals,
#     everything else (champion, Finals MVP, region, tournament stats) on the
#     Finals;
#   * whenever the feed cannot be read.
LOL_API = os.environ.get("IMM_LOL_API", "https://esports-api.lolesports.com/persisted/gw")
LOL_API_KEY = os.environ.get("IMM_LOL_API_KEY", "0TvQnueqKa5mxJntVWt0w4LpLfEkrV1Ta8rQBb9Z")
LOL_LEAGUE_IDS = {"worlds": "98767975604431411", "msi": "98767991325878492",
                  "ewc_lol": "116838530616006090", "demacia_cup": "117126995932274206"}
LOL_SCHEDULE_TTL_SECS = _env_int("IMM_LOL_SCHEDULE_TTL_SECS", 600)
LOL_SCHEDULE_PAGES = 3          # older / newer pages followed per read, each way
LOL_EDITION_DAYS = 150          # an edition's matches start within this of now
LOL_PAST_START_MAX_H = 12       # an unstarted match past its start this long reads live
ESPORTS_LEAGUES = frozenset({"LOL"})


def lol_get_json(path: str):
    """One lolesports feed read (LOL_API + path); raises on failure."""
    r = requests.get(f"{LOL_API}/{path}", timeout=(5, 10), headers={
        "x-api-key": LOL_API_KEY, "Accept": "application/json",
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                      "AppleWebKit/537.36 (KHTML, like Gecko) "
                      "Chrome/124.0 Safari/537.36"})
    r.raise_for_status()
    return r.json()


def lol_event_tournament(event: str) -> Optional[str]:
    """The lolesports league slug of a Kalshi LoL event, from its ticker
    ('KXLOLQUALIFIERS-26WORLDSQF' -> 'worlds'); None = unknown (any LoL match
    then gates it)."""
    u = event.upper()
    if "WORLDS" in u:
        return "worlds"
    if "MSI" in u or "MIDSEASON" in u:
        return "msi"
    if "DCGI" in u or "DEMACIA" in u:
        return "demacia_cup"
    if "EWC" in u:
        return "ewc_lol"
    return None


def lol_deciding_stage(event: str) -> Optional[str]:
    """The Worlds stage whose completion decides an event (see LOL_API);
    None outside Worlds (the live rule alone)."""
    if lol_event_tournament(event) != "worlds":
        return None
    seg = event.split("-")[1].upper() if "-" in event else ""
    if seg.endswith("QF"):
        return "Swiss"
    if seg.endswith("SF"):
        return "Quarterfinals"
    if seg.endswith("FIN"):
        return "Semifinals"
    return "Finals"


def _lol_start_ts(e: dict) -> Optional[float]:
    d = parse_iso_utc(e.get("startTime", ""))
    return d.timestamp() if d is not None else None


def lol_stage_complete(events: List[dict], stage: str, now_ts: float) -> bool:
    """Every match of `stage` in the current edition (start within
    LOL_EDITION_DAYS of now: the feed also carries past years) is completed,
    and there is at least one."""
    rows = [e for e in events
            if (e.get("type") or "match") == "match" and e.get("blockName") == stage
            and _lol_start_ts(e) is not None
            and abs(_lol_start_ts(e) - now_ts) <= LOL_EDITION_DAYS * 86400]
    return bool(rows) and all(e.get("state") == "completed" for e in rows)


def lol_live_reason(live: List[dict], schedule: List[dict],
                    slug: Optional[str], now_ts: float) -> str:
    """Why LoL reads live for a tournament ('' = it does not): a match in
    progress on getLive (any league when slug is None), or a scheduled match
    of the tournament past its start and not yet live."""
    for e in live:
        lg = (e.get("league") or {}).get("slug") or ""
        if (e.get("type") or "match") == "match" and e.get("state") == "inProgress" \
                and (slug is None or lg == slug):
            codes = " vs ".join(str(t_.get("code") or "?")
                                for t_ in (e.get("match") or {}).get("teams") or [])
            return f"{lg or 'LoL'} {codes or 'match'} live ({e.get('blockName') or 'match'})"
    for e in schedule:
        st = _lol_start_ts(e)
        if e.get("state") == "unstarted" and st is not None \
                and st <= now_ts <= st + LOL_PAST_START_MAX_H * 3600:
            return f"{slug} match past its start ({e.get('startTime')}), not yet live"
    return ""


def load_league_auto_series() -> int:
    """Hot-reload LEAGUE_AUTO_FILE by mtime into LEAGUE_AUTO_SERIES and
    (re)install each member's guard set; entries changed on a reload, else 0.
    Refuses blocklisted series, a league that disagrees with the name and
    the hand-configured families (league_hand_configured)."""
    try:
        mtime = os.path.getmtime(league_auto_path())
    except OSError:
        return 0
    if mtime == _league_auto_state["mtime"]:
        return 0
    _league_auto_state["mtime"] = mtime
    try:
        with open(league_auto_path(), encoding="utf-8") as f:
            data = json.load(f) or {}
    except (OSError, ValueError) as e:
        log(f"[IMM] ! league auto file unreadable: {e}")
        return 0
    fresh: Dict[str, dict] = {}
    for s_, e in (data.get("series") or {}).items():
        s_ = str(s_).strip()
        if not isinstance(e, dict):
            continue
        league = series_league(s_)
        if league is None and e.get("league") in ESPORTS_LEAGUES \
                and s_.startswith("KX") and not s_.startswith("KXNFL"):
            league = e["league"]          # esports: the enrollment read the title
        if league is None:
            continue
        if e.get("league") not in (None, league):
            log(f"[IMM] ! league auto {s_}: league {e.get('league')!r} is not "
                f"the name's {league}, skipped")
            continue
        if any(s_.startswith(p_) for p_ in SERIES_BLOCKLIST_PREFIXES):
            log(f"[IMM] ! refused blocklisted series in league auto: {s_}")
            continue
        if league_hand_configured(s_):
            log(f"[IMM] ! refused hand-configured family in league auto: {s_}")
            continue
        kind, size = e.get("kind"), e.get("size") or "pilot"
        if league in ESPORTS_LEAGUES and kind != "season":
            log(f"[IMM] ! league auto {s_}: {league} quotes season members only, skipped")
            continue
        if kind not in ("game", "season") or size != "pilot":
            log(f"[IMM] ! league auto {s_}: kind/size {kind!r}/{size!r} not "
                f"understood, skipped")
            continue
        try:
            buf = int(e["buffer_min"]) if e.get("buffer_min") is not None \
                else LEAGUE_AUTO_GAME_BUFFER_MIN
        except (TypeError, ValueError):
            buf = LEAGUE_AUTO_GAME_BUFFER_MIN
        rnd = e.get("decided_by") or None
        if rnd is not None and rnd not in LEAGUE_DECIDED_ROUNDS:
            log(f"[IMM] ! league auto {s_}: decided_by {rnd!r} is not an ESPN "
                f"round this rule knows, ignored")
            rnd = None
        fresh[s_] = {"league": league, "kind": kind, "size": size,
                     "buffer_min": max(0, buf), "decided_by": rnd,
                     "title": str(e.get("title") or "")}
    for s_ in _league_auto_state["installed"] - set(fresh):
        SERIES_OVERRIDES.pop(s_, None)
    for s_, e in fresh.items():
        SERIES_OVERRIDES[s_] = league_auto_override(e)
    changed = sum(1 for s_ in set(fresh) | set(LEAGUE_AUTO_SERIES)
                  if fresh.get(s_) != LEAGUE_AUTO_SERIES.get(s_))
    LEAGUE_AUTO_SERIES.clear()
    LEAGUE_AUTO_SERIES.update(fresh)
    _league_auto_state["installed"] = set(fresh)
    if changed:
        log(f"[IMM] league auto families: {len(fresh)} enrolled ({changed} changed)")
    return changed


def election_series(series: str) -> bool:
    """The election family (see ELECTION_SERIES): the exact general-election
    list, the Elections-category file (ELECTION_EXTRA_FILE) or a name
    pattern, less ELECTION_EXCLUDE; nothing while IMM_ELECTION_ALLOW=0."""
    return ELECTION_ALLOW and series not in ELECTION_EXCLUDE and (
        series in ELECTION_SERIES
        or series in ELECTION_EXTRA_SERIES
        or any(p.fullmatch(series) for p in ELECTION_SERIES_PATTERNS))


# DATA CENTER COUNTS (Jack 2026-10-01: "allowlist the datacenter family ...
# max 3 markets per event"). KX<state>DATACENTERS -- "will <state> have at
# least N data centers this year?", settled on the count Data Center Map's
# directory page shows for the state at 11:59:59 PM ET Dec 31; nine states
# listed 2026-09-30 (AZ CA FL GA NY OH PA TX VA), $100 per strike per 4-day
# period (Pennsylvania $500 per 2 weeks). Pennsylvania ran in the open-scan
# tier from 9/9 under the scan guard set (safe-join, no rate bar, global
# ladder): 11 fills, -$14.45 marked to mid against ~$29.5 of rewards, ~+$15
# net. The family keeps that guard set (DATACENTER_ARCHETYPE) and quotes 3
# strikes per event (EVENT_TOP_N "*DATACENTERS:3") and quotes against the
# live count Data Center Map gave permission to read (DC_GATE_ENABLE). The
# name must carry a real state code. IMM_DATACENTER_ALLOW=0 removes the
# family.
DATACENTER_ALLOW = os.environ.get("IMM_DATACENTER_ALLOW", "1") == "1"
DATACENTER_SERIES_RE = re.compile(r"KX([A-Z]{2})DATACENTERS")
US_STATE_CODES = frozenset(
    "AL AK AZ AR CA CO CT DE FL GA HI ID IL IN IA KS KY LA ME MD MA MI MN MS "
    "MO MT NE NV NH NJ NM NY NC ND OH OK OR PA RI SC SD TN TX UT VT VA WA WV "
    "WI WY DC".split())


def datacenter_series(series: str) -> bool:
    """The data center count family (see DATACENTER_ALLOW)."""
    m = DATACENTER_SERIES_RE.fullmatch(series)
    return DATACENTER_ALLOW and bool(m) and m.group(1) in US_STATE_CODES
