    "KXEURUSD,KXUSDJPY,KXGBPUSD,KXUSDCAD,KXUSDCHF,KXAUDUSD,KXUSDCNY,KXUSDMXN,"
    "KXINX,KXNASDAQ,KXNDX,KXRUT,KXDJI,KXCAC40,KXDAX,KXFTSE,KXHSI,KXNIKKEI,"
