ASTEST_PICK_HALT_KEY = "ASTEST:PICK"
ASTEST_PICK_FAMILY_KEY = "*PICK"
# the picks in force (load_astest_picks): series -> its picked event, and the
# series set the family hooks read
ASTEST_PICK_EVENTS: Dict[str, str] = {}
ASTEST_PICK_SERIES: frozenset = frozenset()
_ASTEST_GAS_STATE_RE = re.compile(r"KXAAAGASD[A-Z][A-Z]")
# the startup line's account of each family's window
ASTEST_WINDOW_NOTE = {
    "BB": f"out {ASTEST_BB_CUTOFF_DAYS:g} days before the chart date (its tracking week's end)",
    "VH": (f"{'-'.join(ASTEST_VH_WINDOW_ET)} ET only, out at "
           f"{ASTEST_VH_WINDOW_ET[1]} ET on the read day"),
    "PICK": (f"the events in {ASTEST_PICK_FILE} (imm_astest_picks.py, daily; "
             f"lapse after {ASTEST_PICK_MAX_AGE_H:g}h)")}
_astest_family_stop: Dict[str, Dict[str, Any]] = {
    f: {"checked": 0.0, "stopped": False} for f in ASTEST_FAMILIES}


def astest_knob(family: str, name: str):
    """ASTEST_<family>_<name> ("GAS", "BB", "VH"), read at call time so a
    patched module constant takes effect: astest_knob("BB", "EVENT_CAP")."""
    return globals()[f"ASTEST_{family}_{name}"]


def astest_family_stopped(family: str) -> bool:
    """A new family's stop file (ASTEST_<F>_STOP_FILE), read at most once a
    minute; the gas family's is astest_stopped()."""
    if family == "GAS":
        return astest_stopped()
    st = _astest_family_stop[family]
    now = time.time()
    if now - st["checked"] >= 60:
        st["checked"] = now
        st["stopped"] = os.path.exists(os.path.join(STATUS_DIR, astest_knob(family, "STOP_FILE")))
    return st["stopped"]


def astest_member_family(series: str) -> Optional[str]:
    """"BB" / "VH" / "PICK" for a series of a new family while it is on --
    membership alone, the stop file aside (the gas family:
    astest_gas_member). On the budget and cap paths for every ticker, so
    plain lookups."""
    if not ASTEST_ENABLE:
        return None
    if ASTEST_BB_ENABLE and series in ASTEST_BB_SERIES:
        return "BB"
    if ASTEST_VH_ENABLE and series in ASTEST_VH_SERIES:
        return "VH"
    if ASTEST_PICK_ENABLE and series in ASTEST_PICK_SERIES:
        return "PICK"
    return None


def astest_family(series: str) -> Optional[str]:
    """The live AS-test family of `series` -- "GAS", "BB", "VH" or "PICK" --
    or None (not a member, the family switched off, or its stop file
    present)."""
    if astest_gas_series(series):
        return "GAS"
    fam = astest_member_family(series)
    return fam if fam is not None and not astest_family_stopped(fam) else None


def astest_new_series(series: str) -> bool:
    """A live member of the Billboard, VoteHub or daily-pick family: allowed
    into the book (_allowed; a pick's event only, astest_pick_event_ok) and
    quoted x1 at every hour (is_daily_series)."""
    fam = astest_family(series)
    return fam is not None and fam != "GAS"


def _astest_levels(family: str) -> Optional[List[Tuple[int, int]]]:
    """The family's literal ladder: the global rungs x ASTEST_<F>_SIZE_MULT
    (None at x1 -- the global ladder itself)."""
    m = astest_knob(family, "SIZE_MULT")
    return None if m == 1.0 else scale_levels(LEVELS, m)


SERIES_OVERRIDES.update({
    s: SeriesOverride(levels=_astest_levels("BB"), max_position=ASTEST_BB_MAX_POSITION,
                      cutoff_before_event_min=(int(round(ASTEST_BB_CUTOFF_DAYS * 1440))
                                               if ASTEST_BB_CUTOFF_DAYS > 0 else None))
    for s in ASTEST_BB_SERIES})
SERIES_OVERRIDES.update({
    s: SeriesOverride(levels=_astest_levels("VH"), max_position=ASTEST_VH_MAX_POSITION,
                      blackout_et=astest_blackout(ASTEST_VH_WINDOW_ET),
                      event_day_cutoff_et=tuple(
                          int(x) for x in ASTEST_VH_WINDOW_ET[1].split(":")))
    for s in ASTEST_VH_SERIES})


def astest_pick_event_ok(ticker: str) -> bool:
    """A daily pick admits its EVENT, never its series: False for a market (or
    event) of a picked series outside the picked event, True otherwise."""
    ev = ASTEST_PICK_EVENTS.get(series_of(ticker))
    if ev is None:
        return True
    return ticker == ev or ticker.startswith(ev + "-")


def astest_pick_gas_ticker(ticker: str) -> bool:
    """A market (or the event) of a gas-state daily pick while the picks are
    live: the one ticker the state-pattern block stands aside for (_blocked)."""
    series = series_of(ticker)
    return (_ASTEST_GAS_STATE_RE.fullmatch(series) is not None
            and astest_family(series) == "PICK" and astest_pick_event_ok(ticker))


def astest_plain_gas(series: str) -> bool:
    """A gas state the AS test quotes plain, without the GasBuddy gate: a live
    gas-family member, or a gas-state daily pick."""
    return astest_gas_series(series) or (
        _ASTEST_GAS_STATE_RE.fullmatch(series) is not None
        and astest_family(series) == "PICK")


# series -> its SERIES_OVERRIDES entry before it became a pick (None = none),
# restored when it leaves the picks
_ASTEST_PICK_PRIOR: Dict[str, Optional[SeriesOverride]] = {}


def _astest_pick_window(raw) -> Optional[Tuple[str, str]]:
    """A pick's "window_et" ("16:00-24:00") -> ("16:00", "24:00"); None when
    absent or malformed (no window: every hour)."""
    parts = str(raw or "").strip().split("-")
    if len(parts) != 2 or not all(re.fullmatch(r"\d\d:\d\d", p) for p in parts):
        return None
    return parts[0], parts[1]


def _astest_pick_overlay(series: str, window: Optional[Tuple[str, str]]) -> None:
    """Stamp a pick's x1 guard set on its series: the series' own family
    guards first (ensure_family_override -- a gas state takes the national's),
    then the global ladder, the pick's net cap and its quote window."""
    if series not in _ASTEST_PICK_PRIOR:
        ensure_family_override(series)
        _ASTEST_PICK_PRIOR[series] = SERIES_OVERRIDES.get(series)
    ov = replace(_ASTEST_PICK_PRIOR[series] or SeriesOverride(),
                 levels=_astest_levels("PICK"),
                 max_position=ASTEST_PICK_MAX_POSITION)
    if window is not None:
        ov = replace(ov, blackout_et=astest_blackout(window))
    SERIES_OVERRIDES[series] = ov


def load_astest_picks(now_utc: Optional[datetime] = None) -> int:
    """Read ASTEST_PICK_FILE (imm_astest_picks.py) into ASTEST_PICK_EVENTS /
    ASTEST_PICK_SERIES, stamping each pick's guard set on its series
    (_astest_pick_overlay) and handing a series that left the picks its prior
    override back. Called at each universe refresh. A missing, unreadable or
    stale (older than ASTEST_PICK_MAX_AGE_H) file means NO picks -- fail
    closed -- and a blocklisted, frozen or excluded series is refused
    whatever the file says (a gas state's pattern block aside). Returns the
    number of picks in force."""
    global ASTEST_PICK_EVENTS, ASTEST_PICK_SERIES
    now = now_utc or datetime.now(timezone.utc)
    picks: Dict[str, str] = {}
    windows: Dict[str, Optional[Tuple[str, str]]] = {}
    note = ""
    if ASTEST_ENABLE and ASTEST_PICK_ENABLE:
        try:
            with open(os.path.join(STATUS_DIR, ASTEST_PICK_FILE), encoding="utf-8") as f:
                data = json.load(f)
            gen = parse_iso_utc(str(data.get("generated_at") or ""))
            if gen is None or (now - gen).total_seconds() > ASTEST_PICK_MAX_AGE_H * 3600:
                note = f"stale ({data.get('generated_at')})"
            else:
                for p in data.get("picks") or []:
                    ev = str((p or {}).get("event") or "").strip().upper()
                    series = series_of(ev)
                    if "-" not in ev or series in picks:
                        continue
                    gas = _ASTEST_GAS_STATE_RE.fullmatch(series) is not None
                    if (any(ev.startswith(x) for x in SERIES_BLOCKLIST_PREFIXES)
                            or series in FREEZE_SERIES
                            or any(series.startswith(x) for x in SCAN_EXCLUDE_PREFIXES)
                            or (series_pattern_blocked(series) and not gas)
                            or astest_member_family(series) in ("BB", "VH")):
                        log(f"[IMM] ! astest pick {ev} refused: the series is "
                            f"blocked, frozen, excluded or another AS family's")
                        continue
                    picks[series] = ev
                    windows[series] = _astest_pick_window((p or {}).get("window_et"))
        except FileNotFoundError:
            note = "no file"
        except Exception as e:                              # noqa: BLE001
            note = f"unreadable ({e!r})"
    for s in [s for s in _ASTEST_PICK_PRIOR if s not in picks]:
        prior = _ASTEST_PICK_PRIOR.pop(s)
        if prior is None:
            SERIES_OVERRIDES.pop(s, None)
        else:
            SERIES_OVERRIDES[s] = prior
    for s, ev in picks.items():
        _astest_pick_overlay(s, windows[s])
    if picks != ASTEST_PICK_EVENTS:
        log(f"[IMM] astest picks: {len(picks)} in force"
            + (f": {', '.join(sorted(picks.values()))}" if picks else
               (f" ({note})" if note else "")))
    ASTEST_PICK_EVENTS = dict(picks)
    ASTEST_PICK_SERIES = frozenset(picks)
    return len(picks)



# ---- family guard inheritance (Jack 2026-09-01 "fix this going forward",
# after Kalshi lit five new state gas dailies + 12 new *APP series overnight
# and the 8/31 exact lists missed every one for a day). A series admitted by
# a FAMILY rule — the KXAAAGASD* prefix above, or *FT/*APP via the daily
# auto-enroll — clones its archetype's SERIES_OVERRIDES entry the first time
# it shows up in the candidate feed, so a new member is never
# allowed-but-unguarded: safe-join, the family's rate-floor setting and the
# AAA blackout read across (hour-mults were already startswith-matched). A
# hand-tuned exact entry always wins — inheritance only fills a missing key.
# Called from refresh_universe's candidates loop, where every series has
# passed _allowed; suffix rules ALSO require exact/extra-allow membership so
# an unrelated *FT-ending series that is never allowlisted (KXNFLDRAFT) can
# never clone a guard set even if a future caller runs this over the raw
# feed. A "family_suffix" entry is the exception: there the suffix itself
# IS the allowlist membership (ALLOW_FAMILY_SUFFIXES, the *CC family since
# 2026-09-10), so no exact list exists to require -- _blocked still wins
# upstream in _allowed.
# The Oscar family (2026-09-25): every KXOSCAR<CATEGORY> series inherits
# the awards guard set registered on "KXOSCAR" (beside awards_event_start),
# EXCEPT the mention book, which belongs to the mention family's rules.
OSCAR_FAMILY_RE = re.compile(r"(?!.*MENTION)KXOSCAR[A-Z0-9]*")
# Critics Choice (2026-10-06): the same shape on "KXCRITICS"
CRITICS_FAMILY_RE = re.compile(r"(?!.*MENTION)KXCRITICS[A-Z0-9]*")
# the low-temperature family's parent (2026-10-23, see LOWT_ENABLE): a key
# only; its size and price band are set beside the family's other knobs
LOWT_PARENT = "KXLOWTFAMILY"
HIGHT_PARENT = "KXHIGHFAMILY"        # ...and the high-temperature family's
FAMILY_OVERRIDE_PARENTS = (
    # the low- and high-temperature dailies (2026-10-23): first, so no
    # broader family rule can claim a city ahead of its own
    ("predicate", lambda s: lowt_series(s), LOWT_PARENT),
    ("predicate", lambda s: hight_series(s), HIGHT_PARENT),
    ("prefix", "KXAAAGASD", "KXAAAGASD"),
    ("pattern", OSCAR_FAMILY_RE, "KXOSCAR"),
    ("pattern", CRITICS_FAMILY_RE, "KXCRITICS"),
    # Grammy nominees (2026-10-07), see GRAMMY_NOM_FAMILY_RE
    ("pattern", GRAMMY_NOM_FAMILY_RE, "KXGRAMMYNOM"),
    ("suffix", "FT", "KXBKFT"),
    ("suffix", "APP", "KXCLAUDEAPP"),
    ("family_suffix", "CC", "KXAMZNCC"),
    ("family_suffix", "ADS", "KXAMUSEMENTADS"),
    ("family_suffix", "POS", "KXDRPEPPERPOS"),
    # regex kind (2026-09-24): the sports ladder / escalator families
    ("pattern", SPORTS_LADDER_LEAGUE_RE, "KXNFLLADDERREC"),
    # monthly rain cities beyond the named list (2026-10-26, see
    # rain_monthly_auto): BEFORE the rainstorm regex, which also matches a
    # KXRAINS??M monthly name (KXRAINSEAM's shape)
    ("predicate", lambda s: rain_monthly_auto(s), RAIN_MONTHLY_ARCHETYPE),
    # rainstorm spans (2026-09-24 pm): KXRAINS<CITY>, archetype KXRAINSBOS.
    # The name regex also matches the KXRAINS*M monthlies, but only a
    # series that passed _allowed (the two-date ticker shape) reaches here.
    ("pattern", RAINSTORM_SERIES_RE, RAINSTORM_ARCHETYPE),
    # period rain totals (2026-10-04): any other KXRAIN series that reached
    # here did so through the period shape, archetype KXRAINNAPAM
    ("predicate", rain_period_family_series, RAIN_PERIOD_ARCHETYPE),
    # monthly snow (2026-10-04): a KX<CITY>SNOWM beyond the named ten
    ("predicate", snow_monthly_series, SNOW_MONTHLY_ARCHETYPE),
    # ski-resort season snowfall (2026-10-22): a resort series the writer
    # mapped after the six (defined further down: called late)
    ("predicate", lambda s: resort_snow_series(s), "KXBEAVERSNOW"),
    # elections (2026-09-28): a name pattern OR the exact general-election
    # list, so the family is a predicate rather than one regex
    ("predicate", election_series, ELECTION_ARCHETYPE),
    # data center counts (2026-10-01): KX<state code>DATACENTERS
    ("predicate", datacenter_series, DATACENTER_ARCHETYPE),
    # open-scan graduates (2026-10-03): the scan's guard set, see above
    ("predicate", scan_graduate_series, SCAN_GRADUATE_ARCHETYPE),
    # graduate families by Kalshi metadata (2026-10-12): a copy of that
    # guard set without the archetype's family size, see GRADUATE_AUTO_FILE
    ("predicate", graduate_auto_series, GRADUATE_AUTO_PARENT),
    # single-event mentions by Kalshi category (2026-10-13): safe-join on the
    # generic cutoff, see MENTION_AUTO_FILE
    ("predicate", mention_auto_series, MENTION_AUTO_PARENT),
    # NFL head-to-head (2026-10-12): a new KXNFL*H2H stat series, see
    # NFL_H2H_ENABLE (archetype KXNFLPASSYDSH2H)
    ("predicate", nfl_h2h_series, "KXNFLPASSYDSH2H"),
    # awards by Kalshi tag (2026-10-12): the awards rule set, see
    # AWARDS_EXTRA_FILE; last, so a family named above keeps its own
    ("predicate", awards_extra_series, AWARDS_AUTO_PARENT),
)
_family_override_warned: Set[str] = set()


def ensure_family_override(series: str) -> None:
    if series in SERIES_OVERRIDES:
        return
    for kind, pat, parent in FAMILY_OVERRIDE_PARENTS:
        if kind == "prefix":
            if not series.startswith(pat):
                continue
        elif kind == "pattern":
            if not pat.fullmatch(series):
                continue
        elif kind == "family_suffix":
            if not series.endswith(pat):
                continue
        elif kind == "predicate":
            if not pat(series):
                continue
        elif not series.endswith(pat) or (series not in ALLOW_SERIES
                                          and series not in EXTRA_ALLOW_SERIES):
            continue
        ov = SERIES_OVERRIDES.get(parent)
        if ov is None:
            # A missing parent would be a silent exclusion of the guard set
            # — say so once instead of quietly quoting unguarded.
            if parent not in _family_override_warned:
                _family_override_warned.add(parent)
                log(f"[IMM] ! family parent {parent} has no override; "
                    f"{series} quotes unguarded")
            return
        if GB_FAIR_ENABLE and parent == "KXAAAGASD" and gb_fair_series(series):
            # The AAA state dailies keep every national guard EXCEPT its
            # $2/day rate floor (Jack 2026-09-27: "drop the $2/day floor"):
            # the $1-per-period payout floor still decides entry.
            ov = replace(ov, min_est_per_day=GB_STATE_MIN_RATE)
        if parent == "KXAAAGASD" and astest_gas_member(series):
            # the opportunistic AS test's states (2026-10-26): the test's
            # window and net cap on top of the state guard set
            ov = replace(ov, blackout_et=astest_blackout(ASTEST_GAS_WINDOW_ET),
                         max_position=ASTEST_GAS_MAX_POSITION)
        if parent == "KXNFLLADDERREC" and nfl_ffpts_series(series):
            # NFL fantasy ladders stop at the inactive list, not kickoff - 30
            # (Jack 2026-10-04, see NFL_FFPTS_START_BUFFER_MIN)
            ov = replace(ov, start_buffer_min=NFL_FFPTS_START_BUFFER_MIN)
        if parent == SCAN_GRADUATE_ARCHETYPE and ov.size_mult is not None:
            # The graduate archetype is also a live series with its OWN
            # family size (KXSUEZWEEKLY x2, 2026-10-11, FAMILY_X2_1011): a
            # graduate clones the scan's guard set, never that size.
            ov = replace(ov, size_mult=None)
        SERIES_OVERRIDES[series] = ov
        log(f"[IMM] {series}: family override inherited from {parent}")
        return


# Event-start resolution for mention markets: the ticker date's midnight-ET
# cutoff forfeits game-day daytime, but programs run ~1-2 days INCLUDING game
# day — resolve real start times where a reliable source exists, cut off
# EVENT_START_BUFFER_MIN before it, fall back to midnight ET.
EVENT_START_BUFFER_MIN = _env_int("IMM_EVENT_START_BUFFER_MIN", 30)
# Tighter buffer for FILE/CODE event-start OVERRIDES (earnings CALL times and
# company-disclosure RELEASE times): be fully OUT — every order expired
# exchange-side — this many minutes before the scheduled call/release. 10 min
# (Jack 2026-07-23: "all orders expire 10min before the release, 3:50pm for
# Intel"). Distinct from the 30-min game buffer because a hard scheduled
# disclosure is a precise instant, not an approximate kickoff.
OVERRIDE_BUFFER_MIN = _env_int("IMM_OVERRIDE_BUFFER_MIN", 10)
# Power Slap match winners (hand-enrolled 2026-10-23): out OVERRIDE_BUFFER_MIN
# before the card's start once it is on file (apply_series_cutoff_adjustments)
POWERSLAP_SERIES = "KXPOWERSLAPMATCH"
# MARATHONS (Jack 2026-10-30: "why isnt KXMARATHON-NYC26 quoting? marathon
# shaped family should auto-quote"). Kalshi names every road-race series
# KXMARATHON*: the winner, American to win, top American, fastest time,
# course record and European record (Sports, tag "Other", frequency custom);
# a new one joins with its first liquidity program, admitted from the feed
# like any allowlisted series. KXMCMARATHON is a video game's Metacritic
# score and does not match. The race is the information event and its
# tickers carry no date -- Kalshi's occurrence is the night after the race
# (KXMARATHON-NYC26: 11/02 03:00Z for an 11/01 morning start) -- so nothing
# else would stop the bot before the gun: an event is out
# OVERRIDE_BUFFER_MIN before its division's start on EVENT_START_OVERRIDES,
# and with none on file it is stood down (fail closed) on a config gap the
# family watch's research fills (its kind "marathon"). Base size, no family
# multiplier. IMM_MARATHON_ENABLE=0 takes the family out (an env change: a
# task restart).
MARATHON_PREFIX = "KXMARATHON"
MARATHON_ENABLE = os.environ.get("IMM_MARATHON_ENABLE", "1") == "1"


def marathon_series(series: str) -> bool:
    """A road-race series of the marathon family (MARATHON_PREFIX)."""
    return MARATHON_ENABLE and series.startswith(MARATHON_PREFIX)

# Fresh candidates aren't admitted inside this many minutes of a cutoff
# (pointless entry + placement race); MEMBERS are exempt and quote to the
# true cutoff — the exchange-side order expiration is the hard stop there.
CUTOFF_SCREEN_BUFFER_MIN = _env_int("IMM_CUTOFF_SCREEN_BUFFER", 5)
# THE POOL RATE OVER THE WINDOW KALSHI PAYS (Jack 2026-10-13 on
# KXTRUMPMENTION-26OCT13: "why is it not quoting? it should"). From 26OCT12
# Kalshi lists a rally's programs to the MARKET's close -- 14 days after the
# rally, its postponement window -- where 10/05-10/09 ran to the rally night
# (26OCT09: 10/06 20:45Z -> 10/10 02:00Z). fetch_programs spread the same $100
# pool over that listed stretch: $6.91/day per market on 26OCT13 against
# $31-400/day on 10/05-10/09, so every strike sat under the $1.30 payout bar
# (26OCT12 quoted nothing, 26OCT13 one strike for an hour). But Kalshi TRIMS
# the period to the market's real close and pays the WHOLE pool over it:
# across 20 past mention events whose program had been listed 2-136x longer
# than it ran (TRUMPMENTION 26AUG03-26OCT01, MAMDANIMENTION, WORLDNEWSMENTION),
# credited / (bot estimate x stretch) = 0.96-1.06. So for a MENTION event with
# a start time (EVENT_START_OVERRIDES: the WH / RNC / TVmaze / hand-set start)
# whose program is listed more than TRIMMED_POOL_MIN_STRETCH_H past it, the
# pool rate is the reward over [program start, start +
# TRIMMED_POOL_CLOSE_PAD_H], the close Kalshi trims to: programs ended a
# median 2.9h after the scheduled start across 112 mention events
# (TRUMPMENTION 26OCT05 / 26OCT12: 2.4h / 2.6h). A program already ending
# near its event (the 10/05-10/09 shape, earnings calls) is left alone.
# THE RULES' DATE WHEN NO START IS KNOWN (Jack 2026-10-13: "build it"): 13 of
# the 16 stretched mention events since 9/06 had no start time (the September
# WORLDNEWSMENTION shows, TRUMPMENTION 26SEP29 / 26OCT01, MAMDANIMENTION). The
# newer markets' rules name the day ("... as part of Midterm Rally in Durant,
# Oklahoma originally scheduled for Oct 1, 2026"), so such an event's pool is
# spread to TRIMMED_POOL_DATE_END_H ET the morning after it (06:00: past an
# Alaska or Hawaii evening and its close), and only while that is still ahead
# -- a postponed event keeps its markets open past it. A "next NYC Mayor's
# Office announcement" (MAMDANIMENTION) names no day and keeps the listed
# window. The auto-enrolled Mentions-category singles (mention_auto_series:
# KXDJTRALLY ... on the TRUMPMENTION contract) are covered beside the
# MENTION-named series. IMM_TRIMMED_POOL=0 restores the listed window.
TRIMMED_POOL = os.environ.get("IMM_TRIMMED_POOL", "1") == "1"
TRIMMED_POOL_CLOSE_PAD_H = _env_float("IMM_TRIMMED_POOL_CLOSE_PAD_H", 3.0)
TRIMMED_POOL_MIN_STRETCH_H = _env_float("IMM_TRIMMED_POOL_MIN_STRETCH_H", 24.0)
TRIMMED_POOL_DATE_END_H = _env_float("IMM_TRIMMED_POOL_DATE_END_H", 6.0)
TRIMMED_POOL_WORDS = tuple(
    w for w in os.environ.get("IMM_TRIMMED_POOL_WORDS", "MENTION").split(",") if w)
_SCHEDULED_FOR_RE = re.compile(
    r"originally scheduled for\s+([A-Za-z]{3,9})\.?\s+(\d{1,2}),?\s+(\d{4})", re.I)


def rules_scheduled_date(rules: str) -> Optional[date]:
    """The day in a market's "... originally scheduled for October 13, 2026"
    (or "Oct 1, 2026") rules line, else None."""
    m = _SCHEDULED_FOR_RE.search(rules or "")
    if not m:
        return None
    month = _MONTHS.get(m.group(1)[:3].upper())
    if month is None:
        return None
    try:
        return date(int(m.group(3)), month, int(m.group(2)))
    except ValueError:
        return None


def trimmed_pool_rate(series: str, event_ticker: str, dollars_per_day: float,
                      program_start: Optional[datetime],
                      program_end: Optional[datetime],
                      rules: str = "", now: Optional[datetime] = None
                      ) -> Tuple[float, Optional[datetime]]:
    """(pool $/day, effective window end) for a market's program: the listed
    rate with None, or -- a TRIMMED_POOL_WORDS / mention_auto_series series
    whose program is listed far past its event -- the same pool over
    [program start, start + TRIMMED_POOL_CLOSE_PAD_H] when the start is known,
    else to TRIMMED_POOL_DATE_END_H ET after the rules' scheduled day, and
    that end."""
    if not TRIMMED_POOL or dollars_per_day <= 0 \
            or program_start is None or program_end is None \
            or not (any(w in series for w in TRIMMED_POOL_WORDS)
                    or mention_auto_series(series)):
        return dollars_per_day, None
    start = EVENT_START_OVERRIDES.get(event_ticker)
    if start is not None:
        if program_end - start <= timedelta(hours=TRIMMED_POOL_MIN_STRETCH_H):
            return dollars_per_day, None
        eff_end = start + timedelta(hours=TRIMMED_POOL_CLOSE_PAD_H)
    else:
        day = rules_scheduled_date(rules)
        if day is None:
            return dollars_per_day, None
        eff_end = ET.localize(datetime(day.year, day.month, day.day)
                              + timedelta(days=1, hours=TRIMMED_POOL_DATE_END_H)
                              ).astimezone(timezone.utc)
        if program_end - eff_end <= timedelta(hours=TRIMMED_POOL_MIN_STRETCH_H) \
                or (now or datetime.now(timezone.utc)) >= eff_end:
            return dollars_per_day, None
    if eff_end <= program_start:
        return dollars_per_day, None
    # fetch_programs' days floor (1h) holds for the trimmed window too
    eff_secs = max((eff_end - program_start).total_seconds(), 3600.0)
    listed_secs = max((program_end - program_start).total_seconds(), 3600.0)
    return dollars_per_day * listed_secs / eff_secs, eff_end


# Series with a real schedule API. Their games can be POSTPONED past the
# ticker date (NYDAL 7/16 -> makeup 7/20 while 18 program markets kept paying
# $100/day each), so the cheap 24h ticker-date pre-drop must not apply — the
# resolver + _screen decide from the live schedule instead.
SCHEDULE_RESOLVED_SERIES = frozenset(
    s for s in os.environ.get(
        "IMM_SCHEDULE_RESOLVED_SERIES",
        "KXWNBAMENTION,KXMLBMENTION,KXWCMENTION").split(",") if s)
# Fixed broadcast hours (ET) for series with no schedule API. Conservative early.
SERIES_START_ET = {}
for _pair in os.environ.get(
        "IMM_SERIES_START_ET",
        # LATENIGHT: generic "late night TV" series — currently Corden's WC
        # After Hours (nightly 11pm ET per Fox listings); 22:00 stays safe even
        # if a future episode is a 10pm-ET show (Gutfeld class). Without an
        # entry the midnight-ET fallback forfeits the whole day-of (2026-07-19).
        "KXLOVEISLMENTION=21:00,KXBIGBROTHERMENTION=20:00,KXFIGHTMENTION=17:00,"
        "KXLATENIGHTMENTION=22:00").split(","):
    if "=" in _pair:
        _s, _hm = _pair.split("=")
        try:
            _h, _m = _hm.split(":")
            SERIES_START_ET[_s.strip()] = (int(_h), int(_m))
        except ValueError:
            pass

# Candidate cap: the pre-meta list is sorted by raw pool $/day and truncated
# here — a SILENT exclusion (no skip count) that also fights the pass-2
# objective (small pools with empty books can out-yield big farmed pools).
# 250 was already binding on 2026-07-22 and swallowed the entire new
# company-metric class (~$19/day markets); the econ-series addition on 7/23
# pushed the allowed universe past 450 too. 700 covers ~544 with headroom.
# Refresh cost scales with this (book reads), fine under keep-alive.
# 700 -> 5000 (Jack 2026-08-03 "i dont want this to be a limiter"): the cap
# first BOUND at 700 on 8/3 02:38Z (diesel + re-entry + earnings-week
# listings). At 5000 every allowed program market becomes a candidate;
# refresh cost now scales with the allowed universe (~800-1000 book reads),
# lengthening hh:00-hh:11 activation-window cycles — accepted trade.
MAX_CANDIDATE_BOOKS = _env_int("IMM_MAX_CANDIDATE_BOOKS", 5000)
# Payout floor is the $1/market MINIMUM PAYOUT itself, tested against the
# bot's expected TOTAL accrual over the market's remaining quotable life
# (est $/day x days to program end, capped by cutoff/close) — NOT a per-day
# rate (Jack 2026-07-22): a $0.40/day estimate on a 5-day program clears the
# $1 minimum comfortably; the old per-day floor only existed to catch 1-2-day
# programs that couldn't.
# 1.0 -> 1.5 (Jack 2026-09-12: "across IMM going forward, increase $1 payout
# floor to $1.5 (to account for risks of the orderbook changing and earnings
# falling below $1 minimum)"). The bar WAS the exchange minimum itself, so a
# market projected to just clear $1.00 at entry paid zero whenever the book
# moved against it afterwards -- a competitor stacking the touch, the
# reference walking a rung away, a period ending early -- and the accrual
# finished under the minimum. The extra $0.50 is that margin, and it is the
# same bar everywhere series_min_est_total() is read: fresh entry, the
# hopeless exit, the open-scan hopeless bar and the finecon walk. KXTEMP
# dropped its own $1.00 value the same day, so nothing reads a lower bar.
# PAYOUT_FLOOR_DOLLARS below stays $1.00: that one is a FACT about the
# exchange, not a choice.
# Per-series override: SeriesOverride.min_est_total via series_min_est_total(),
# but NOTHING may sit below PAYOUT_FLOOR_DOLLARS — see series_min_est_total().
# 1.5 -> 1.3 (Jack 2026-10-11: "lower payout bar to $1.30 (since pays out
# 1.15x on average, so a $1.30 payout bar is equivalent to ~$1.5 in
# reality)"): the bar is tested against the bot's ESTIMATE, and Kalshi pays
# ~1.15x the estimate on average, so $1.30 estimated ~ $1.50 paid. Same
# single bar everywhere series_min_est_total() is read; the exit still uses
# the $1.00 cliff (EXIT_FLOOR_IS_PAYOUT) and ladders have their own $1.00.
MIN_EST_TOTAL_DOLLARS = _env_float("IMM_MIN_EST_TOTAL", 1.3)
# The exchange's own minimum: a market whose payout for a program period comes
# to less than this is paid NOTHING. Measured, not assumed — across all 2,720
# LIQUIDITY credits on Jack's 2026-08-04 statement the smallest is exactly
# $1.00 and none is below it (the floor is a liquidity-program rule: the one
# VOLUME incentive on the statement is $0.31), and "one credit per market clearing $1" predicts
# the actual per-event credit count exactly on 94 of 99 clean-window events
# (272 predicted vs 273 actual). This is a hard threshold, so a per-series
# entry floor UNDER it can only admit markets that provably pay zero: they are
# pure fill risk. KXTEMP's $0.70 (Jack 2026-08-02) was exactly that and is now
# clamped away.
PAYOUT_FLOOR_DOLLARS = _env_float("IMM_PAYOUT_FLOOR", 1.0)
# Horizon escape from the per-series RATE floor (Jack 2026-08-03): a fresh
# candidate admits on EITHER est_rate >= the series bar OR a projected TOTAL
# >= this. The rate bar alone is horizon-blind — it rejects a slow market that
# would still earn well over its life exactly as hard as one that never pays.
# CAREFUL: the projection is bounded by the PROGRAM end, not the market close.
# The foot-traffic markets that prompted this close 2026-09-07 but their
# incentive programs end 2026-08-09, so the window is 5 days and only 1 of 22
# clears $5 — the rule is deliberately not a blanket admission.
RATE_FLOOR_TOTAL_ALT = _env_float("IMM_RATE_FLOOR_TOTAL_ALT", 5.0)
# ...but the escape's TOTAL is only allowed to accumulate over this many days
# of window. A total threshold dilutes with window length: KXCRYPTOSTRUCTURE
# entered 2026-08-07 06:22Z at ~$0.36/day because its 13.9-day program window
# stretched pennies-rate to a $5.04 total — an effective bar of $0.36/day,
# 5.5x looser than the $2/day the rate bar demands. Capping the horizon at
# ALT/bar days (5/2 = 2.5) makes the escape exactly bar-neutral: windows
# shorter than 2.5d keep the full anti-flapping escape, longer windows face
# the bar undiluted. (Jack 2026-08-07: "yes implement".)
RATE_FLOOR_ESCAPE_DAYS = _env_float("IMM_RATE_FLOOR_ESCAPE_DAYS", 2.5)


def rate_floor_projected(accrued: float, est_total: float, peak: float,
                         quotable_days: float) -> float:
    """The value the re-entry rate floor's horizon escape compares against
    RATE_FLOOR_TOTAL_ALT. est_total/peak are whole-window projections; scale
    them to the first RATE_FLOOR_ESCAPE_DAYS of window so long windows cannot
    dilute the bar. Banked accrual counts in full — it is money, not a
    projection."""
    cap = min(1.0, RATE_FLOOR_ESCAPE_DAYS / max(quotable_days, 1.0 / 24))
    return accrued + max(est_total, peak) * cap


def rate_floor_rate(meta) -> float:
    """The $/day the per-series rate bar compares: the schedule-weighted
    floor rate (RATE_FLOOR_SCHEDULE), else the live-size estimate."""
    return meta.floor_dollars_per_day if RATE_FLOOR_SCHEDULE \
        else meta.est_dollars_per_day
# The floor is a hard threshold on a NOISY estimate (thin books swing the
# share estimate ±50% between refreshes), so borderline markets could flap
# just under $1 at every sampling instant and never enter (observed
# 2026-07-23: 28 company markets measuring $1-2.6 in a spot check, all
# floored at the live refreshes). Entry therefore used the market's PEAK
# estimate over the last hour; sticky selection holds it once in.
# 2026-09-13: the peak is a MEMBERS-ONLY dip guard now. A fresh candidate is
# judged on its current estimate plus accrued (Jack: "test fresh admissions
# on the current estimate plus accrued only, no peak") -- see the projection
# block in refresh_universe for the 15-strike admit-then-evict that decided
# it. The borderline-flap concern above is covered from the other side: a
# seat left empty costs nothing, while a seat filled on a stale peak costs
# an hour of fill risk and a permanent bar.
# 2026-09-26: OFF for members too by default (MEMBER_PEAK_GUARD, below
# HOPELESS_SUSTAIN_SECS); still tracked and persisted so the knob can
# restore it.
EST_PEAK_TTL_SECS = _env_int("IMM_EST_PEAK_TTL", 3600)
# STICKY EXIT for hopeless markets (Jack 2026-07-25: "quoting markets that
# don't hit $1 is a big drain" — if there's <5% chance of reaching the $1 min
# payout before the incentive expires, stop quoting EVEN IF already started).
# The one deliberate exception to sticky retention: sub-$1 accrual pays
# NOTHING, so riding a hopeless market to its natural end is pure fill risk
# for zero reward. "<5%" is encoded structurally, not statistically: even the
# OPTIMISTIC projection (accrued-so-far + the better of the current and
# 1h-peak remaining estimate) stays under the bar. quote_all series exempt.
HOPELESS_EXIT = os.environ.get("IMM_HOPELESS_EXIT", "1") == "1"
# ...but ONLY after the projection has been under the bar CONTINUOUSLY for
# this long (Jack 2026-08-05: "dont evict on dips under $1").
#
# The peak-TTL guard above was supposed to already do this — its comment
# claimed "eviction needs a full peak-TTL hour of sustained sub-$1 projection"
# — and it does not. `pts` is only refreshed when a NEW HIGH is set, so a
# market whose estimate DECLINES (the normal path: competitors arrive, our
# share falls) never refreshes it, the peak silently expires an hour later,
# and then a SINGLE low reading evicts. Measured on KXUST7AM-26AUG31: 15
# strikes -> 7 overnight, and the same signature on KXFSLR-26OCTMWSOLD and
# KXHOOD-26NOVECVOL (7 -> 5 each).
#
# Eviction is also effectively PERMANENT, which is what makes a false one
# expensive: an evicted market re-enters as a FRESH candidate and must clear
# the per-series rate bar, which these structurally cannot (est $0.37/day
# against a $2/day bar). The `rate_floor` skip bucket climbs monotonically as
# `hopeless` fires — 96 -> 106 over the same window. So the exit needs to be
# sure, not fast.
#
# 30 MINUTES, ON THE LIVE PROJECTION (Jack 2026-09-26, on
# KXNFLFFPTSLADDER-26SEP27MINTB-MINKMURRAY1: "let's make the hopeless clock
# more consistent / faster. what about 30min checks instead of hourly?").
# The exit had TWO one-hour guards in series: a member's projection carried
# its 1h est peak (EST_PEAK_TTL_SECS), and only after that lapsed did this
# clock start its own hour. The peak made the timing a lottery -- it
# re-seeds from whatever SINGLE reading lands on the first refresh after it
# expires, so a thin-book moment at that instant buys another full hour.
# MURRAY1: admitted 21:32Z on a 10-minute thin-book reading ($2.50/day
# est), carried by that peak to 22:42Z, re-seeded inside a second 20-minute
# thin window, carried to 23:43Z, and only then put on the clock -- ~3h15m
# quoted, 135 contracts filled, $0.11 banked against the $1.00 cliff.
# Measured 9/6-9/26: 1,826 admit -> hopeless rides, median 2.8h, p25 2.07h
# (the structural 2h floor), 13% of them filled, 12,206 contracts taken on
# markets then evicted as unable to reach the floor. Now a MEMBER is judged
# on its live projection (banked + current remaining estimate -- the test a
# fresh candidate has had since 9/13) and this clock is the one dip guard:
# evicted after 30 continuous minutes under the bar (~3-4 refreshes at the
# 600s cadence), i.e. 30-40 minutes after its last above-bar reading,
# whatever lands on any single refresh. A market with >= half the cliff
# banked that projects within NEAR_CLIFF_DOLLARS of it is still held by the
# near-cliff rule. IMM_HOPELESS_SUSTAIN_SECS=3600 restores the hour;
# IMM_MEMBER_PEAK_GUARD=1 restores the member peak carry.
HOPELESS_SUSTAIN_SECS = _env_int("IMM_HOPELESS_SUSTAIN_SECS", 1800)
MEMBER_PEAK_GUARD = os.environ.get("IMM_MEMBER_PEAK_GUARD", "0") == "1"
# THE ADMISSION CLOCK (Jack 2026-09-27, from the ROI scan: "build 1,2,3,4").
# Entry used to be ONE reading: a fresh candidate (or a re-entrant with any
# banked accrual) whose projection touched the bar at a single refresh was
# admitted in that refresh. The estimate swings ~2x between refreshes, so
# admission systematically bought the spikes. Measured 9/18-9/27: at
# admission the estimate was a median 1.69x the market's last REJECTED
# reading (p75 2.64x, n=2,217); once resting, the market earned a median
# 0.74x of the admission estimate in its first 3 cycles and 0.71x over its
# first hour (n=1,276) -- while members scored at the same instant match the
# estimator's hypothetical ladder (median 1.00), so the gap is the spike
# reverting, not the model. 1,370 of 1,987 fresh admissions 9/13-9/26 (69%)
# ended `hopeless`, and the fills taken on those rides lost $495 held to
# settlement (-5.6c/ct). The same noise slowed the EXIT: one above-bar
# reading reset the 30-minute hopeless clock (42 single-reading resets on 18
# members on 9/27 alone).
# So a projection must now HOLD at/above its bar for ADMIT_SUSTAIN_SECS --
# an unbroken run of readings, the mirror of HOPELESS_SUSTAIN_SECS -- before
# a fresh candidate is admitted (skip reason `admit_pending`), and before an
# above-bar run may reset a member's hopeless clock. A run breaks on any
# sub-bar reading, and on a gap of more than ADMIT_RUN_MAX_GAP_SECS between
# readings (a market screened out, a restart after a sleep): an old run must
# never admit a market on its first reading back. Near-cliff re-entrants
# (>= half the cliff banked this period) skip the admission wait -- their
# credit is real and the verdict is "quote to completion". Members,
# quote_all, FORCE_EVENTS and curated events never wait. At the 600s refresh
# cadence the default is exactly two consecutive readings.
# IMM_ADMIT_SUSTAIN_SECS=0 restores single-reading entry AND reset.
ADMIT_SUSTAIN_SECS = _env_int("IMM_ADMIT_SUSTAIN_SECS", 600)
ADMIT_RUN_MAX_GAP_SECS = _env_int("IMM_ADMIT_RUN_MAX_GAP_SECS", 1500)
# THE $1 FLOOR IS PER PROGRAM PERIOD (Jack 2026-09-22 pm, on KXRT-STRA-50 /
# -45: "why is this quoted? it should be hopeless"). Kalshi had re-listed
# the Rotten Tomatoes programs as a fresh ONE-DAY period at 16:49Z; in it
# those two had accrued $0.09 / $0.06 with 0.68 days left and $0.15-0.22/day
# of estimated share -- hopeless by the 7/25 rule -- but the projection
# credited their LIFETIME accrued_est ($5.01 / $6.83, banked and PAID in the
# period that ended 16:46Z), so reaches_min was trivially true and the
# hopeless clock never started. The exchange pays each market's credits per
# program period behind a hard $1 floor (reference: imm_reward_recon), so
# the floor credit -- entry floor, hopeless exit AND the digest's paid-basis
# crossing -- is THIS period's accrual: accrued_est - period_base, the
# baseline _roll_reward_periods records at every re-listing (2026-09-11);
# no baseline = first period seen = the lifetime number, as before. Measured
# 00:10Z 9/23: 89 of 833 quoting members cleared the bar on lifetime
# accrual alone (74 KXRT, 11 KXFSLR, 4 others), every one under $0.30 for
# the period. IMM_FLOOR_ACCRUAL_PER_PERIOD=0 restores the lifetime credit.
FLOOR_ACCRUAL_PER_PERIOD = os.environ.get(
    "IMM_FLOOR_ACCRUAL_PER_PERIOD", "1") == "1"
# THE EXIT BAR IS THE EXCHANGE'S $1.00 CLIFF, NOT THE $1.50 ENTRY MARGIN
# (Jack 2026-09-25, KXVENUEPERFORM-REDROCKS28JAN01: "a bunch of markets ...
# stopped quoting but are close to the $1 cutoff -- that is lost money").
# The 9/12 move of MIN_EST_TOTAL_DOLLARS to $1.50 fed the SAME bar to the
# hopeless exit, so a member with $0.93 banked this period and $0.04-0.06/day
# over the 6 days left projected $1.2-1.3 -- above the cliff, under the
# entry bar -- and was evicted; the $0.93 then pays nothing. Measured 9/25:
# 11 Red Rocks markets with $0.50-$0.99 banked, 1,510 unquoted market-hours
# over the period, book-wide ~$44 of period accrual parked under the cliff.
# The $0.50 margin was asked for as ENTRY risk cover; on an exit it
# guarantees the sub-$1 outcome it was meant to avoid. So (floor_bar_dollars):
#   * a MEMBER, or a re-entrant with ANY banked accrual this period, is
#     tested against PAYOUT_FLOOR_DOLLARS;
#   * a fresh candidate (nothing banked) still needs MIN_EST_TOTAL_DOLLARS.
# IMM_EXIT_FLOOR_IS_PAYOUT=0 restores the single $1.50 bar everywhere.
EXIT_FLOOR_IS_PAYOUT = os.environ.get("IMM_EXIT_FLOOR_IS_PAYOUT", "1") == "1"
# NEAR-CLIFF QUOTE-TO-COMPLETION (Jack 2026-09-26, "build the knob for
# banked markets near the cliff"). Measured at the 16:10Z refresh: the
# Red Rocks strikes had $0.50-0.70 banked this period and projected
# $0.85-1.00 in total against the $1.00 cliff -- CHR at $1.00 vs $1.00,
# floored by rounding -- and while they sit out the banked part is frozen,
# so they can only drift further under. A market that has ALREADY banked
# at least NEAR_CLIFF_MIN_BANKED_FRAC of the cliff this period and projects
# (banked + remaining) to within NEAR_CLIFF_DOLLARS under it is treated as
# reaching the bar: it re-enters or stays (the hopeless exit reads the same
# verdict, so no flapping around the cliff) and quotes to completion. The
# downside is bounded -- at most NEAR_CLIFF_DOLLARS of projected shortfall
# on a market that is mostly paid for -- and the upside is the whole banked
# credit. Fresh candidates (nothing banked) are untouched: the $1.50 entry
# bar stays. Only meaningful in the cliff regime (EXIT_FLOOR_IS_PAYOUT).
# IMM_NEAR_CLIFF_DOLLARS=0 switches it off.
NEAR_CLIFF_DOLLARS = _env_float("IMM_NEAR_CLIFF_DOLLARS", 0.15)
NEAR_CLIFF_MIN_BANKED_FRAC = _env_float("IMM_NEAR_CLIFF_MIN_BANKED_FRAC", 0.5)
# ...and a SIZE BOOST to get it across (Jack 2026-09-26: "if Banked +
# projected is near cliff, do a 1.5x size multiplier to ensure it gets
# across the cliff"). While a market is in near-cliff mode its ladder is
# scaled by NEAR_CLIFF_SIZE_MULT everywhere the shape is read -- the quote
# loop, the collateral reservation, the placement guard's bracket and the
# estimator's hypothetical ladder (the 2026-07-14 lesson: every consumer
# sees the same shape). The mode is STICKY for the period once armed: it
# ends when the banked accrual crosses the cliff (the $1 is secured and
# accrual above it pays linearly, so size goes back to normal), when the
# market leaves the selection, or when the period rolls -- so the boosted
# projection clearing the bar outright never switches the boost off and
# on again. 1.0 = off.
NEAR_CLIFF_SIZE_MULT = _env_float("IMM_NEAR_CLIFF_SIZE_MULT", 1.5)
# ...and only for a market that has ALREADY banked more than this (Jack
# 2026-09-26 pm: "only do this if banked is > $0.50" -- strict). The
# quote-to-completion verdict is unaffected: a near-cliff market with
# $0.50 or less banked keeps quoting at plain size.
NEAR_CLIFF_BOOST_MIN_BANKED = _env_float("IMM_NEAR_CLIFF_BOOST_MIN_BANKED", 0.50)
# YIELD SIZE MODE (Jack 2026-10-02, "1 and 2 for monday", from the multiplier
# review): from 00:00 ET 2026-10-05 a market whose modelled reward per resting
# contract (meta.yield_per_contract, $/contract/day -- the estimator's own
# number, pads excluded) is at least YIELD_SIZE_MIN rests its ladder at
# YIELD_SIZE_MULT. Market-days 9/15-10/1, long-dated families with no family
# multiplier, less the exclusions below: yield >= $0.011 (~the top two-fifths)
# netted 47c per 1k resting contract-hours on the 24h mark-out (39c on the
# dashboard's trading P&L), positive every week, while the bottom fifth
# netted ~0. x1.5 there: modelled +$17-22/day (reward diluted by our share of
# the scored book, fills scaled 1:1).
# Wired like the near-cliff size mode (the 2026-07-14 lesson): per ticker,
# composed with it, at every reader of the shape -- the estimator's probe
# ladder and the floor projection, the collateral reservation, the quote
# loop and the placement guard's bracket (_market_size_mult). Caps and skew
# knees are NOT scaled: the per-market cap bounds a boosted ladder exactly as
# it bounds a near-cliff one. Decided on every refresh's estimate and STICKY
# with hysteresis: a boosted market keeps the mode down to
# YIELD_SIZE_EXIT_FRAC of the bar (its own extra size dilutes its per-contract
# yield by up to 1 / (1 + 0.5 x its share)) and loses it when it leaves the
# selection. Not eligible (yield_size_eligible): daily families; series with
# a family multiplier or a hand-tuned ladder (applied_mention_mult != 1 --
# earnings, sports ladders, Treasuries, daily rain, KXTRUMPAPPROVE ...);
# open-scan members (unreviewed); the finecon tier (company KPIs, food
# trackers, central banks); elections; and the families that lost money even
# in their high-yield markets or are paid well under the model -- KXRT, gas
# and diesel, econ & rates, sports & venues and awards (Kalshi pays them
# 0.41x the model). IMM_YIELD_SIZE_MULT=1 switches it off.
YIELD_SIZE_MULT = _env_float("IMM_YIELD_SIZE_MULT", 1.5)
YIELD_SIZE_MULT_FROM = _env_et_day("IMM_YIELD_SIZE_MULT_FROM", "2026-10-05")
YIELD_SIZE_MULT_FROM_TS = _et_day_start_ts(YIELD_SIZE_MULT_FROM)
YIELD_SIZE_MIN = _env_float("IMM_YIELD_SIZE_MIN", 0.011)
YIELD_SIZE_EXIT_FRAC = _env_float("IMM_YIELD_SIZE_EXIT_FRAC", 0.85)
# prefixes: KXRT; gas & diesel; Treasuries and econ & rates; sports & venues;
# awards, charts & media (imm_dashboard.family_of's lists)
YIELD_SIZE_EXCLUDE_PREFIXES = tuple(p for p in os.environ.get(
    "IMM_YIELD_SIZE_EXCLUDE",
    "KXRT,KXAAAGAS,KXDIESEL,KXUSGASCPI,KXPAGAS,"
    "KXUST,KXNOTE,KXTNOTE,TNOTE,KXTREASURYMAX,KX3MTBILL,"
    "KXCBD,KXFED,KXRBNZ,KXBOI,KXECB,KXCPI,KXPCE,KXCOREPCE,KXOER,KXIBONDFIX,KXTEMPHELP,"
    "KXNFL,KXMLB,KXNBA,KXNHL,KXWNBA,KXNCAA,KXUFC,KXVENUEPERFORM,KXMLS,KXWC,KXF1,"
    "KXTTELITE,KXPGA,KXATP,KXWTA,"
    "KXGGNOM,KXGRAMMY,KXOSCAR,KXCMA,KXART,KXTOP10BB,KXNETFLIXTOP,KXWEEKSNUM,"
    "KXNATBOOK,KXVMA,KXEMMY,KXSPOTIFY,KXBILLBOARD,KXBOXOFFICE,KXYT,KXMUSIC,KXDWTS"
).split(",") if p)
# ...and by word: the unambiguous econ & rates words of family_of, plus awards
YIELD_SIZE_EXCLUDE_WORDS = tuple(p for p in os.environ.get(
    "IMM_YIELD_SIZE_EXCLUDE_WORDS",
    "INFL,MORT,MTG,HPI,HOUSING,NHSALES,PERMITS,JOBS,JOBLESS,PAYROLL,JOLTS,UNEMP,GDP,CFNAI,NOBEL,ALBUM"
).split(",") if p)
_YIELD_TREASURY_RE = re.compile(r"KX\d+YR(DIR|RATE)")


def yield_size_active(now_ts: Optional[float] = None) -> bool:
    """Is the yield size mode switched on at `now_ts` (default: now)?"""
    if YIELD_SIZE_MULT <= 0 or YIELD_SIZE_MULT == 1.0:
        return False
    if YIELD_SIZE_MULT_FROM_TS is None:
        return True
    return (now_ts if now_ts is not None else time.time()) >= YIELD_SIZE_MULT_FROM_TS


def yield_size_eligible(series: str) -> bool:
    """May a market of this series take the yield size mode at all?"""
    if is_daily_series(series) or series in SCAN_GUARDED_SERIES:
        return False
    if _share_x1(series):
        return False       # the OpenRouter share family stays x1 (2026-10-03)
    if scan_graduate_series(series):
        return False       # open-scan graduates keep the scan's size (2026-10-03)
    if series in FINECON_SERIES or series in FINECON_FAMILY:
        return False
    # a family multiplier, or a hand-tuned ladder / cap / quote-all spec
    # (literal by design -- applied_mention_mult reads 1.0 for those)
    ov = SERIES_OVERRIDES.get(series)
    if ov and (ov.levels or ov.max_position is not None or ov.quote_all):
        return False
    if applied_mention_mult(series) != 1.0 or election_series(series) \
            or sports_ladder_league(series):
        return False
    if "MENTION" in series:
        return True        # a mention is none of the families below (KXWCMENTION)
    if series.startswith(YIELD_SIZE_EXCLUDE_PREFIXES) or _YIELD_TREASURY_RE.match(series):
        return False
    return not any(w in series for w in YIELD_SIZE_EXCLUDE_WORDS)
