BOOK_LOG_CANDIDATES = os.environ.get("IMM_BOOK_LOG_CANDIDATES", "1") == "1"
BOOK_LOG_GZ_LEVEL = _env_int("IMM_BOOK_LOG_GZ_LEVEL", 6)
