def _git_sha() -> str:
    """Short HEAD sha, best-effort. Never raises, never blocks startup."""
    import subprocess
    try:
        out = subprocess.run(
            ["git", "-C", os.path.dirname(_SOURCE_PATH) or ".",
             "rev-parse", "--short", "HEAD"],
            capture_output=True, text=True, timeout=5)
        return (out.stdout or "").strip() or "unknown"
    except Exception:
        return "unknown"


def _build_config() -> Tuple[Dict[str, str], str]:
    """Snapshot the effective configuration and digest it.

    Secrets are excluded by name, not by value: this dict is written to disk
    in full, and KALSHI_* legitimately holds key material."""
    import hashlib
    # FEED_URL: a data-feed URL can carry its key in the query string
    secret = ("KEY", "SECRET", "TOKEN", "PASSWORD", "PRIVATE", "FEED_URL")
    cfg: Dict[str, str] = {}
    for k, v in os.environ.items():
        if not (k.startswith("IMM_") or k.startswith("KALSHI_")):
            continue
        cfg[k] = "<redacted>" if any(s in k.upper() for s in secret) else str(v)
    g = globals()
    for name in _CONFIG_CODE_KNOBS:
        if name in g:
            cfg[f"code:{name}"] = str(g[name])
    digest = hashlib.sha1(
        json.dumps(cfg, sort_keys=True).encode("utf-8")).hexdigest()[:8]
    return cfg, digest
_HOURLY_TEMP_RE = re.compile(r"^KXTEMP[A-Z]+H-")


def code_change_exit_due(selected, now_utc: datetime,
                         current_mtime: Optional[float] = None,
                         now_ts: Optional[float] = None) -> bool:
    """True when the on-disk source differs from the imported one and this
    instant is safe to restart in. `selected` is the live selection (ticker
    -> meta; only the tickers are read) — hourly-temp membership is judged
    on the same ^KXTEMP<CITY>H- shape restart_imm.ps1 keys on. The
    current_mtime/now_ts params exist for tests."""
    if not EXIT_ON_CODE_CHANGE:
        return False
    if current_mtime is None:
        try:
            current_mtime = os.path.getmtime(_SOURCE_PATH)
        except OSError:
            return False
    if current_mtime == _SOURCE_MTIME:
        return False
    if (now_ts if now_ts is not None else time.time()) - current_mtime < 60:
        return False
    minute = now_utc.astimezone(ET).minute
    if minute >= 50 or minute <= 5:
        return True
    return not any(_HOURLY_TEMP_RE.match(str(t)) for t in (selected or ()))

ALERT_EMAIL_FROM = os.environ.get("ALERT_EMAIL_FROM", "")
ALERT_EMAIL_PASSWORD = os.environ.get("ALERT_EMAIL_PASSWORD", "")
ALERT_RECIPIENTS = [r.strip() for r in os.environ.get(
    "IMM_ALERT_TO", "jackdu224@gmail.com").split(",") if r.strip()]
ALERT_DEDUPE_SECS = 6 * 3600
SMS_MAX_CHARS = 300
SUMMARY_HOUR_CT = _env_int("IMM_SUMMARY_HOUR_CT", 5)   # counters roll 6am ET

# Watchdog: N selected markets with almost nothing resting for several cycles
# is the signature of every silent-death class seen so far (midnight-ET
# earnings cutoff, program races, override gaps) — page instead of waiting
# for someone to look at the book.
WATCHDOG_MIN_SELECTED = _env_int("IMM_WATCHDOG_MIN_SELECTED", 10)
WATCHDOG_MIN_RESTING = _env_int("IMM_WATCHDOG_MIN_RESTING", 5)
WATCHDOG_CYCLES = _env_int("IMM_WATCHDOG_CYCLES", 3)
# Coverage alert (Jack 2026-08-02, the sides==1 leak): a SELECTED market
# quoted while only one side qualifies accrues ZERO with full fill risk.
# pad_missing_side should make this ~impossible; page if it persists anyway.
COVERAGE_ALERT_CYCLES = _env_int("IMM_COVERAGE_ALERT_CYCLES", 5)

# Account hard floor: the bot's risk math sees only its OWN book, but the
# account is shared (crypto fleet, cloud bots, manual). If the ACCOUNT VALUE
# drops this much below the daily anchor -- whatever the source -- halt and
# page. Deposits/withdrawals move it too; the alert says so. 0 = off.
# ACCOUNT VALUE, not cash (Jack 2026-10-03: "make the balance guard use
# account value. drop of $2k in a day should halt."): cash plus Kalshi's own
# valuation of every position (balance_dollars + portfolio_value), the
# equity send_portfolio_digest reports. The cash version tripped at 01:40 ET
# 10/3 on INVENTORY -- cash $8,978 -> $3,882 as the Saturday-stacked
# 400-lot fills turned cash into positions, while the bot's marked-to-market
# trading P&L over the span was only about -$700 -- cancelled all 3,590
# orders and idled the most boosted 4.3 hours of the week. Buying inventory
# moves value from cash into positions and leaves this sum alone; losses,
# other bots, manual trading and withdrawals still move it. A new knob name
# (was IMM_BALANCE_DROP_HALT, cash, 5000 in the launcher) because the
# measure changed; the anchor (account_value_day_start) re-arms on the first
# check and at every 5am-CT roll.
ACCOUNT_DROP_HALT = _env_float("IMM_ACCOUNT_DROP_HALT", 2000.0)


def account_value_dollars(balance: dict) -> Optional[float]:
    """Cash + Kalshi's valuation of the positions from one /portfolio/balance
    response, in dollars; None when the positions value is missing (cash
    alone is exactly the measure that misfires on inventory)."""
    cash = float(balance.get("balance_dollars") or 0.0)
    if balance.get("portfolio_value_dollars") is not None:
        return cash + float(balance["portfolio_value_dollars"])
    if balance.get("portfolio_value") is not None:
        return cash + float(balance["portfolio_value"]) / 100.0     # cents
    return None


def balance_halt_email(drop: float, anchor: float, value: float, cash: float,
                       n_cancelled: int, halted_until: float, imm_pnl_today: float,
                       live: bool) -> Tuple[str, str]:
    """(subject, plain-text body) of the account-value halt email (Jack
    2026-10-03: "i also need a clear email alert if halts due to balance
    guard"). Its own subject line, never the generic "balance_floor alert"
    of 10/3 01:40 ET; the first body line stands alone (an SMS gateway gets
    the first 300 characters and no subject)."""
    until = datetime.fromtimestamp(halted_until, timezone.utc).astimezone(ET)
    until_s = until.strftime("%a %b %d, %I:%M %p ET").replace(" 0", " ")
    positions = value - cash
    imm_loss = max(0.0, -imm_pnl_today)
    elsewhere = max(0.0, drop - imm_loss)
    sign = "+" if imm_pnl_today >= 0 else "-"
    subject = (f"IMM HALTED: account value down ${drop:,.0f} today "
               f"(limit ${ACCOUNT_DROP_HALT:,.0f}) - orders cancelled until {until_s}")
    body = "\n".join([
        f"IMM HALTED by the account-value guard: down ${drop:,.0f} since today's anchor "
        f"(limit ${ACCOUNT_DROP_HALT:,.0f}). {n_cancelled:,} IMM orders cancelled; "
        f"no quoting until {until_s}.",
        "",
        "ACCOUNT VALUE = cash + Kalshi's value of every position on the account",
        f"  today's anchor:  ${anchor:,.2f}",
        f"  now:             ${value:,.2f}  (cash ${cash:,.2f} + positions ${positions:,.2f})",
        f"  change:          -${drop:,.2f}",
        "",
        "WHERE IT CAME FROM",
        f"  IMM's own P&L today (realized + marked): {sign}${abs(imm_pnl_today):,.2f}",
        f"  not explained by the IMM's P&L:           ${elsewhere:,.2f}"
        + ("  <- another bot, manual trading, a withdrawal, or Kalshi re-pricing "
           "positions" if elsewhere >= 0.25 * drop else ""),
        "",
        "WHAT THE BOT DID",
        f"  - cancelled {n_cancelled:,} resting IMM orders; positions are NOT closed (they ride)",
        f"  - quotes nothing until {until_s} (the {SUMMARY_HOUR_CT}am CT roll), then resumes",
        "    on its own against a fresh anchor",
        "",
        "TO RESUME SOONER (deliberately)",
        "  stop the 'KL incentive_mm' task, run  python incentive_mm.py --clear-halt",
        "  in C:\\Users\\jackd\\Documents\\KL, then start the task again. --clear-halt",
        "  also re-anchors today's account value at the restart.",
        "",
        f"[{'LIVE' if live else 'DRY'}] Buying inventory only moves money from cash into "
        "positions and never trips this guard (the cash version did, 10/3 01:40 ET).",
    ])
    return subject, body


def risk_line(account: Optional[Tuple[float, float]], pnl_today: float,
              scan_pnl: Optional[float]) -> str:
    """The once-per-full-cycle "risk:" log line: where the three daily
    halts stand against their limits (Jack 2026-10-03: the 7:00 email shows
    how close each risk control came to breaching). `account` is (value,
    anchor) from the last account-value check, None when the check did not
    run or read nothing. send_imm_digest / imm_risk_controls parse this line
    for the day's worst reading, so change the wording there too."""
    parts = []
    if account is not None and account[1] > 0:
        value, anchor = account
        drop = anchor - value
        parts.append(f"account value ${value:,.0f} (anchor ${anchor:,.0f}, "
                     f"{'down' if drop >= 0 else 'up'} ${abs(drop):,.0f} of "
                     f"${ACCOUNT_DROP_HALT:,.0f} halt)")
    parts.append(f"P&L today ${pnl_today:+,.2f} of -${DAILY_LOSS_LIMIT:,.0f} halt")
    if scan_pnl is not None and SCAN_TOP_N > 0 and SCAN_DAILY_LOSS_LIMIT > 0:
        parts.append(f"open-scan ${scan_pnl:+,.2f} of "
                     f"-${SCAN_DAILY_LOSS_LIMIT:,.0f} budget")
    return "risk: " + " | ".join(parts)


def _halt_day_key(now_utc: datetime) -> str:
    """The 5am-CT roll day the halt/carry/balance anchors belong to."""
    return (now_utc.astimezone(CT)
            - timedelta(hours=SUMMARY_HOUR_CT)).date().isoformat()


def _next_roll_utc(now_utc: datetime) -> datetime:
    """The next 5am-CT roll after now_utc: the moment _halt_day_key changes
    and the daily counters reset. The daily-loss, balance-floor and open-scan
    halts last until here (Jack 2026-10-01). They used to lift at ET
    midnight, five hours before their counters reset, so a halted bot woke
    into the same roll day's loss and halted again until the NEXT midnight:
    a trip at 2pm ET idled the bot ~34 hours, through all of the next day."""
    ct = now_utc.astimezone(CT)
    day = ct.date() if ct.hour < SUMMARY_HOUR_CT else ct.date() + timedelta(days=1)
    # localize, not replace(): a pytz zone keeps the old UTC offset through
    # replace() and timedelta math, an hour off across a DST change
    return CT.localize(datetime(day.year, day.month, day.day, SUMMARY_HOUR_CT)) \
        .astimezone(timezone.utc)


def log(msg: str) -> None:
    print(f"{datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%SZ')} {msg}", flush=True)


# Rewards accrue only while orders REST — every sleep is lost rent plus a
# degraded post-wake cycle (DNS not back yet -> books/positions read as junk).
# SetThreadExecutionState(ES_SYSTEM_REQUIRED) vetoes S0/idle sleep while the
# process lives (display may still turn off; lid-close policy still wins).
# Cleared by the OS automatically when the process exits.
_ES_CONTINUOUS = 0x80000000
_ES_SYSTEM_REQUIRED = 0x00000001
_keep_awake_state = {"ok": None}


def _keep_awake() -> None:
    if sys.platform != "win32" or os.environ.get("IMM_KEEP_AWAKE", "1") != "1":
        return
    try:
        import ctypes
        r = ctypes.windll.kernel32.SetThreadExecutionState(
            _ES_CONTINUOUS | _ES_SYSTEM_REQUIRED)
        ok = bool(r)
    except Exception:
        ok = False
    if ok != _keep_awake_state["ok"]:   # log transitions only, not every cycle
        _keep_awake_state["ok"] = ok
        log(f"[IMM] keep-awake (block idle sleep): {'ON' if ok else 'FAILED'}")


# POWER (Jack 2026-10-11: "fix the issue where it hangs when i take laptop off
# power"). Off AC, Windows can throttle a background process to its efficient
# cores and low clocks (EcoQoS). The bot runs hidden, so it qualifies, and on
# 10/11 the whole process once stalled 192s. _no_power_throttling opts this
# process out, once at start (IMM_NO_POWER_THROTTLING=0 leaves it).
# _power_check logs each switch between AC and battery (and battery saver) and
# feeds the status file's `power`, so a hang can be lined up with the power
# source. On battery the Wi-Fi adapter's power plan setting (Medium Power
# Saving on this laptop) is what degraded the network; the bot cannot change
# that. Jack set it to Maximum Performance on 10/11 (powercfg DC index 0).
_power_state: Dict[str, Any] = {}


def _no_power_throttling() -> bool:
    """SetProcessInformation(ProcessPowerThrottling): EXECUTION_SPEED
    controlled and off, so this process runs at full speed on battery.
    True when Windows took it. Never raises."""
    if sys.platform != "win32" or os.environ.get("IMM_NO_POWER_THROTTLING", "1") != "1":
        return False
    try:
        import ctypes
        from ctypes import wintypes

        class _PPTS(ctypes.Structure):
            _fields_ = [("Version", wintypes.ULONG), ("ControlMask", wintypes.ULONG),
                        ("StateMask", wintypes.ULONG)]
        # a private kernel32 handle: typed arguments (the pseudo-handle -1
        # overflows ctypes' default int) without touching windll's shared one
        k32 = ctypes.WinDLL("kernel32")
        k32.GetCurrentProcess.restype = wintypes.HANDLE
        k32.SetProcessInformation.argtypes = [wintypes.HANDLE, ctypes.c_int,
                                              ctypes.c_void_p, wintypes.DWORD]
        k32.SetProcessInformation.restype = wintypes.BOOL
        st = _PPTS(1, 0x1, 0x0)     # CURRENT_VERSION, EXECUTION_SPEED, not throttled
        ok = bool(k32.SetProcessInformation(k32.GetCurrentProcess(), 4,  # ProcessPowerThrottling
                                            ctypes.byref(st), ctypes.sizeof(st)))
    except Exception:
        ok = False
    log(f"[IMM] power throttling (EcoQoS) for this process: "
        + ("OFF -- full speed on battery" if ok else "could not be turned off"))
    return ok


# PRIORITY + MEMORY (Jack 2026-10-11: "plugged in, i thought this was fixed").
# The Task Scheduler task starts the bot at its default priority 7: CPU below
# normal, memory priority 2 (of 5) and I/O priority low. This 16GB laptop runs
# short of RAM (10/11 13:24Z: 0.2GB free, 49 of 60GB committed, ~5,400 page
# reads/s), so Windows trims every working set hard and the bot's pages are
# the last to come back. Leaving Modern Standby wakes every app at once, and
# each time on 10/11 the bot then froze for minutes ("a 30s tick took 72s" at
# 00:28Z on AC, 192s at 01:18Z, 72s + 144s at 13:11-13:16Z): a hard page fault
# inside code that holds the GIL stops every thread. _normal_priority raises
# all three to normal, once at start (IMM_NORMAL_PRIORITY=0 leaves them). In a
# scratch A/B under that pressure a process at normal priority read 400MB back
# in 1.7s, against 4.1s at the task's priorities. A hard working-set minimum
# did NOT hold there (trimmed to 14MB like the control), so none is set.
# _memory_check logs the laptop going short of RAM and back (status
# power.memory), and the watchdog's stall line carries the free RAM, so the
# next stall can be lined up with it. Freeing RAM is Jack's (close idle apps).
MEM_LOW_MB = 512    # free RAM below this: "memory: LOW" (once per spell)
MEM_OK_MB = 1024    # ...and back above this: "memory: ok again"


def _normal_priority() -> Optional[Dict[str, str]]:
    """Raise this process's CPU priority class, memory priority and I/O
    priority to normal where they are below it (never lowers one). Returns
    {"cpu", "memory", "io"} -> "<was> -> <now>" / "<as is>" / "failed", or
    None off Windows / when turned off. Logs one line. Never raises."""
    if sys.platform != "win32" or os.environ.get("IMM_NORMAL_PRIORITY", "1") != "1":
        return None
    out = {"cpu": "failed", "memory": "failed", "io": "failed"}
    try:
        import ctypes
        from ctypes import wintypes
        H = wintypes.HANDLE
        # private handles: typed arguments (the pseudo-handle -1 overflows
        # ctypes' default int) without touching windll's shared ones
        k32 = ctypes.WinDLL("kernel32")
        nt = ctypes.WinDLL("ntdll")
        k32.GetCurrentProcess.restype = H
        k32.GetPriorityClass.argtypes = [H]
        k32.GetPriorityClass.restype = wintypes.DWORD
        k32.SetPriorityClass.argtypes = [H, wintypes.DWORD]
        k32.SetPriorityClass.restype = wintypes.BOOL
        for f in (k32.GetProcessInformation, k32.SetProcessInformation):
            f.argtypes = [H, ctypes.c_int, ctypes.c_void_p, wintypes.DWORD]
            f.restype = wintypes.BOOL
        nt.NtQueryInformationProcess.argtypes = [H, ctypes.c_int, ctypes.c_void_p,
                                                 wintypes.ULONG, ctypes.c_void_p]
        nt.NtQueryInformationProcess.restype = ctypes.c_long
        nt.NtSetInformationProcess.argtypes = [H, ctypes.c_int, ctypes.c_void_p,
                                               wintypes.ULONG]
        nt.NtSetInformationProcess.restype = ctypes.c_long
        me = k32.GetCurrentProcess()
    except Exception:
        log("[IMM] process priority: could not be read")
        return out
    cpu_names = {0x40: "idle", 0x4000: "below normal", 0x20: "normal",
                 0x8000: "above normal", 0x80: "high", 0x100: "realtime"}
    try:    # CPU: idle / below normal -> NORMAL_PRIORITY_CLASS
        pc = int(k32.GetPriorityClass(me))
        if pc in (0x40, 0x4000):
            out["cpu"] = (f"{cpu_names[pc]} -> normal" if k32.SetPriorityClass(me, 0x20)
                          else f"{cpu_names[pc]} (raise failed)")
        elif pc:
            out["cpu"] = cpu_names.get(pc, hex(pc))
    except Exception:
        pass
    try:    # memory priority (ProcessMemoryPriority = 0): 0..5, 5 = normal
        v = wintypes.ULONG(0)
        if k32.GetProcessInformation(me, 0, ctypes.byref(v), 4):
            was = int(v.value)
            if was < 5:
                v = wintypes.ULONG(5)
                out["memory"] = (f"{was} -> 5" if k32.SetProcessInformation(
                    me, 0, ctypes.byref(v), 4) else f"{was} (raise failed)")
            else:
                out["memory"] = str(was)
    except Exception:
        pass
    io_names = {0: "very low", 1: "low", 2: "normal", 3: "high"}
    try:    # I/O priority (ProcessIoPriority = 33): 0 very low, 1 low, 2 normal
        v = wintypes.ULONG(9)
        if nt.NtQueryInformationProcess(me, 33, ctypes.byref(v), 4, None) == 0:
            was = int(v.value)
            if was < 2:
                v = wintypes.ULONG(2)
                out["io"] = (f"{io_names[was]} -> normal"
                             if nt.NtSetInformationProcess(me, 33, ctypes.byref(v), 4) == 0
                             else f"{io_names[was]} (raise failed)")
            else:
                out["io"] = io_names.get(was, str(was))
    except Exception:
        pass
    _power_state["priority"] = dict(out)
    log(f"[IMM] process priority: CPU {out['cpu']}, memory {out['memory']}, "
        f"I/O {out['io']} (the Task Scheduler task starts it low, and a low one "
        f"is paged out first when the laptop runs short of RAM)")
    return out


def _read_memory_status() -> Optional[Tuple[int, int, int, int]]:
    """(free RAM MB, total RAM MB, committed MB, commit limit MB) from
    GlobalMemoryStatusEx, or None off Windows / on failure."""
    if sys.platform != "win32":
        return None
    try:
        import ctypes

        class _MSX(ctypes.Structure):
            _fields_ = [("dwLength", ctypes.c_ulong), ("dwMemoryLoad", ctypes.c_ulong),
                        ("ullTotalPhys", ctypes.c_ulonglong),
                        ("ullAvailPhys", ctypes.c_ulonglong),
                        ("ullTotalPageFile", ctypes.c_ulonglong),
                        ("ullAvailPageFile", ctypes.c_ulonglong),
                        ("ullTotalVirtual", ctypes.c_ulonglong),
                        ("ullAvailVirtual", ctypes.c_ulonglong),
                        ("ullAvailExtendedVirtual", ctypes.c_ulonglong)]
        m = _MSX()
        m.dwLength = ctypes.sizeof(m)
        if not ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(m)):
            return None
    except Exception:
        return None
    mb = 2 ** 20
    return (int(m.ullAvailPhys // mb), int(m.ullTotalPhys // mb),
            int((m.ullTotalPageFile - m.ullAvailPageFile) // mb),
            int(m.ullTotalPageFile // mb))


def _memory_note(read: Optional[Callable[[], Optional[tuple]]] = None) -> str:
    """'free RAM 0.2 of 15.7GB, 48 of 59GB committed', or '' when unknown.
    Never raises."""
    try:
        r = (read or _read_memory_status)()
        free, total, used, limit = r
    except Exception:
        return ""
    return (f"free RAM {free / 1024:.1f} of {total / 1024:.1f}GB, "
            f"{used / 1024:.0f} of {limit / 1024:.0f}GB committed")


def _memory_check(read: Optional[Callable[[], Optional[tuple]]] = None) -> None:
    """Every cycle: keep the latest RAM reading for the status file
    (power.memory) and log a spell of free RAM under MEM_LOW_MB once, and its
    end (back over MEM_OK_MB). Never raises."""
    try:
        r = (read or _read_memory_status)()
        free, total, used, limit = r
    except Exception:
        return
    low = bool((_power_state.get("memory") or {}).get("low"))
    note = None
    if not low and free < MEM_LOW_MB:
        low, note = True, (
            f"[IMM] memory: LOW -- {_memory_note(lambda: r)}; Windows pages "
            f"processes out when RAM runs short, and the bot stalls while its "
            f"pages come back (close apps that are not needed)")
    elif low and free > MEM_OK_MB:
        low, note = False, f"[IMM] memory: ok again -- {_memory_note(lambda: r)}"
    _power_state["memory"] = {"free_mb": free, "total_mb": total,
                              "committed_mb": used, "commit_limit_mb": limit,
                              "low": low}
    if note:
        log(note)


def _read_power_status() -> Optional[Tuple[Optional[bool], Optional[int], bool]]:
    """(on AC? None = unknown, battery %, battery saver on) from
    GetSystemPowerStatus, or None off Windows / on failure."""
    if sys.platform != "win32":
        return None
    try:
        import ctypes

        class _SPS(ctypes.Structure):
            _fields_ = [("ACLineStatus", ctypes.c_ubyte), ("BatteryFlag", ctypes.c_ubyte),
                        ("BatteryLifePercent", ctypes.c_ubyte),
                        ("SystemStatusFlag", ctypes.c_ubyte),
                        ("BatteryLifeTime", ctypes.c_ulong),
                        ("BatteryFullLifeTime", ctypes.c_ulong)]
        s = _SPS()
        if not ctypes.windll.kernel32.GetSystemPowerStatus(ctypes.byref(s)):
            return None
    except Exception:
        return None
    return ({0: False, 1: True}.get(s.ACLineStatus),
            None if s.BatteryLifePercent == 255 else int(s.BatteryLifePercent),
            bool(s.SystemStatusFlag & 1))


def _power_check(read: Callable[[], Optional[tuple]] = _read_power_status) -> None:
    """Log a change of power source / battery saver (checked every cycle) and
    keep the latest reading for the status file. Never raises."""
    try:
        r = read()
    except Exception:
        r = None
    if r is None:
        return
    ac, pct, saver = r
    _power_state.update(ac=ac, pct=pct, saver=saver,
                        at=datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"))
    key = (ac, saver)
    if _power_state.get("key") == key:
        return
    _power_state["key"] = key
    what = ("an unknown power source" if ac is None else
            "AC power" if ac else "BATTERY")
    log(f"[IMM] power: on {what}" + (f" ({pct}%)" if pct is not None else "")
        + (", battery saver ON" if saver else ""))


def is_network_error(e: BaseException) -> bool:
    """True for a call that never got an answer: connect, TLS, timeout or a
    dropped connection. False for an HTTP error status (the server
    answered), a parse error, or a test double's RuntimeError."""
    return isinstance(e, (requests.exceptions.ConnectionError,
                          requests.exceptions.Timeout,
                          requests.exceptions.ChunkedEncodingError,
                          ConnectionError, TimeoutError))


def run_bounded(fn: Callable[[], Any], timeout: float,
                name: str) -> Tuple[bool, Any]:
    """Run fn on a daemon thread and wait at most `timeout` seconds for it.
    Returns (True, its result) when it returned in time. Otherwise returns
    (False, the exception it raised), or (False, None) while it still runs;
    a still-running fn is left to finish or die with the process. The hang
    watchdog's file writes and log lines go through this (see
    WEDGE_IO_TIMEOUT_SECS)."""
    box: Dict[str, Any] = {}

    def target() -> None:
        try:
            box["r"] = fn()
        except BaseException as e:
            box["e"] = e
    t = threading.Thread(target=target, daemon=True, name=name)
    t.start()
    t.join(timeout)
    if "r" in box:
        return True, box["r"]
    return False, box.get("e")


def format_thread_stacks(skip_ident: Optional[int] = None) -> Tuple[str, str]:
    """(every thread's Python stack, a one-line summary of the main thread's).
    Main thread first, then by name; innermost call last, as in a traceback.
    The summary is the main thread's three innermost frames plus its
    innermost frame in this file. `skip_ident`: the calling thread."""
    frames = sys._current_frames()
    by_ident = {t.ident: t for t in threading.enumerate()}
    main_ident = threading.main_thread().ident
    here = os.path.basename(__file__)
    out: List[str] = []
    summary = ""
    for ident in sorted(frames, key=lambda i: (
            i != main_ident, getattr(by_ident.get(i), "name", "?"))):
        if ident == skip_ident:
            continue
        th = by_ident.get(ident)
        out.append(f"--- thread {getattr(th, 'name', '?')} (ident {ident}"
                   f"{', daemon' if th is not None and th.daemon else ''}) ---\n")
        stack = traceback.extract_stack(frames[ident])
        out.extend(traceback.format_list(stack))
        if ident == main_ident and stack:
            inner = list(reversed(stack[-3:]))
            parts = [f"{os.path.basename(fs.filename)}:{fs.lineno} {fs.name}"
                     for fs in inner]
            own = next((fs for fs in reversed(stack)
                        if os.path.basename(fs.filename) == here), None)
            if own is not None and own not in inner:
                parts.append(f"... {here}:{own.lineno} {own.name}")
            summary = " <- ".join(parts)
    return "".join(out), summary


def wedge_dump_path(now_ts: float) -> str:
    """STATUS_DIR/wedge_<utc>.txt. Resolved at call time: tests re-point
    STATUS_DIR after import."""
    return os.path.join(STATUS_DIR, "wedge_" + time.strftime(
        "%Y%m%dT%H%M%SZ", time.gmtime(now_ts)) + ".txt")


def parse_iso_utc(s) -> Optional[datetime]:
    try:
        return datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(timezone.utc)
    except (ValueError, AttributeError, TypeError):
        return None


# Manual EVENT-start cutoffs, event_ticker -> datetime (highest priority in the
# resolver). For earnings-mention markets this is the EARNINGS CALL start time
# (the market resolves on what's SAID DURING THE CALL) — NOT when earnings "come
# out" (the press release). Those can differ by a day: e.g. UAL releases Jul 15
# 4pm ET but the call is Jul 16 10:30am ET; NFLX releases Jul 15... no, releases
# AND interviews Jul 16 4:40pm ET. The ticker date and every automated feed
# (Kalshi occurrence/expiration, Nasdaq AMC/BMO) track the RELEASE or are stale,
# so call times are looked up per-company from the IR page (Kalshi
# settlement_sources) / press release and set here. Format env
# "EVENT_TICKER=ISO8601;...".
EVENT_START_OVERRIDES: Dict[str, datetime] = {}
for _pair in os.environ.get(
        "IMM_EVENT_START_OVERRIDE",
        "KXEARNINGSMENTIONNFLX-26JUL02=2026-07-16T16:40:00-04:00"      # NFLX call 4:40pm ET
        ";KXEARNINGSMENTIONUAL-26JUL16=2026-07-16T10:30:00-04:00"      # UAL call 10:30am ET
        # Jul 22 calls (looked up 2026-07-22; GEV omitted — its 7:30am ET call
        # already passed, midnight fallback correctly keeps it dead):
        ";KXEARNINGSMENTIONTSLA-26JUL22=2026-07-22T17:30:00-04:00"     # TSLA call 5:30pm ET
        ";KXEARNINGSMENTIONGOOGL-26JUL22=2026-07-22T16:30:00-04:00"    # GOOGL call 4:30pm ET
        ";KXEARNINGSMENTIONALK-26JUL22=2026-07-22T11:30:00-04:00"      # ALK call 11:30am ET
        ).split(";"):
    if "=" in _pair:
        _ev, _iso = _pair.split("=", 1)
        _dt = parse_iso_utc(_iso.strip())
        if _dt is not None:
            EVENT_START_OVERRIDES[_ev.strip()] = _dt

# File-based event-start overrides, written by imm_earnings_overrides.py (the
# daily call-time task) and hand-edits: {event_ticker: ISO8601}. Merged into
# EVENT_START_OVERRIDES at each universe refresh, hot-reloaded by mtime so a
# daytime write needs NO bot restart. Precedence: explicit env/code entries
# win; file entries may be updated/removed by later file writes.
EVENT_OVERRIDES_FILE = os.path.join(STATUS_DIR, "event_start_overrides.json")
_file_override_state = {"mtime": 0.0, "keys": set()}


def load_file_event_overrides() -> int:
    """Merge the overrides file into EVENT_START_OVERRIDES. Returns the
    number of entries added/changed; 0 when the file is unchanged/absent."""
    try:
        mtime = os.path.getmtime(EVENT_OVERRIDES_FILE)
    except OSError:
        return 0
    if mtime == _file_override_state["mtime"]:
        return 0
    _file_override_state["mtime"] = mtime
    changed = 0
    try:
        with open(EVENT_OVERRIDES_FILE, encoding="utf-8") as f:
            data = json.load(f) or {}
    except (OSError, ValueError) as e:
        log(f"[IMM] ! event overrides file unreadable: {e}")
        return 0
    file_keys = set()
    for ev, iso in data.items():
        ev = str(ev).strip()
        dt_ = parse_iso_utc(str(iso).strip())
        if not ev or dt_ is None:
            log(f"[IMM] ! bad override entry ignored: {ev}={iso}")
            continue
        file_keys.add(ev)
        owned_by_env = (ev in EVENT_START_OVERRIDES
                        and ev not in _file_override_state["keys"])
        if owned_by_env:
            continue                      # env/code entry wins
        if EVENT_START_OVERRIDES.get(ev) != dt_:
            EVENT_START_OVERRIDES[ev] = dt_
            changed += 1
    for ev in _file_override_state["keys"] - file_keys:
        EVENT_START_OVERRIDES.pop(ev, None)   # removed from file -> forget
        changed += 1
    _file_override_state["keys"] = file_keys
    if changed:
        log(f"[IMM] event-start overrides file: {changed} entr(y/ies) merged")
    return changed


# Auto-enrolled series (written by the daily imm_earnings_overrides.py run,
# which classifies newly-programmed series against Jack's strategy families):
# {"series": [...]}. Hot-reloaded by mtime, merged into the allow check.
# SAFETY: the blocklist always wins regardless, and the loader itself refuses
# fleet monthly (*MAXMON/*MINMON) entries even if hand-added.
EXTRA_ALLOW_FILE = os.path.join(STATUS_DIR, "extra_allow_series.json")
EXTRA_ALLOW_SERIES: Set[str] = set()
_extra_allow_state = {"mtime": 0.0}


def load_extra_allow_series() -> int:
    try:
        mtime = os.path.getmtime(EXTRA_ALLOW_FILE)
    except OSError:
        return 0
    if mtime == _extra_allow_state["mtime"]:
        return 0
    _extra_allow_state["mtime"] = mtime
    try:
        with open(EXTRA_ALLOW_FILE, encoding="utf-8") as f:
            data = json.load(f) or {}
    except (OSError, ValueError) as e:
        log(f"[IMM] ! extra allow file unreadable: {e}")
        return 0
    fresh: Set[str] = set()
    for s in data.get("series") or []:
        s = str(s).strip()
        if not s or not s.startswith("KX"):
            continue
        if s.endswith("MAXMON") or s.endswith("MINMON"):
            log(f"[IMM] ! refused fleet monthly series in extra allow: {s}")
            continue
        if any(s.startswith(p) for p in SERIES_BLOCKLIST_PREFIXES) \
                or series_pattern_blocked(s):
            log(f"[IMM] ! refused blocklisted series in extra allow: {s}")
            continue
        fresh.add(s)
    changed = len(fresh ^ EXTRA_ALLOW_SERIES)
    EXTRA_ALLOW_SERIES.clear()
    EXTRA_ALLOW_SERIES.update(fresh)
    if changed:
        log(f"[IMM] extra allow series: {len(fresh)} enrolled ({changed} changed)")
    return changed


# Finecon self-extension (Jack 2026-09-05 "yes self-extend carbon arc"):
# the daily overrides task detects new Carbon Arc-sourced series in the
# programs feed and appends them here; the bot merges them into
# FINECON_SERIES (group walk + caps + _allowed) and applies the standard
# finecon guard (safe-join, no rate bar) on first sight. Same mtime
# hot-reload and blocklist-wins safety as the extra-allow file; format
# {"series": [...]}. Removing a line drops group membership on the next
# refresh (a removed series that is still quoting deselects through the
# normal path — the file is the source of truth for the EXTRA portion,
# _FINECON_BASE stays code-owned).
FINECON_EXTRA_FILE = os.path.join(STATUS_DIR, "finecon_extra_series.json")
_finecon_extra_state = {"mtime": 0.0}
_finecon_family_skipped: Set[str] = set()


def finecon_family_override() -> "SeriesOverride":
    """Guard set for a feed-discovered finecon family member: the ordinary
    finecon guards (safe-join, no rate bar) PLUS a close-anchored cutoff, so
    quoting stops FINECON_FAMILY_CUTOFF_FROM_CLOSE_MIN before the scheduled
    announcement instead of at the ticker date's midnight ET."""
    return SeriesOverride(
        min_est_per_day=_env_float("IMM_FINECON_MIN_RATE", 0.0),
        safe_join=True,
        cutoff_from_close_min=FINECON_FAMILY_CUTOFF_FROM_CLOSE_MIN)


def finecon_expand_family(series_seen) -> int:
    """Admit live-feed series matching FINECON_SERIES_PREFIXES into the
    finecon group (Jack 2026-09-09). Returns how many were newly added.

    Blocklisted/frozen series are refused, and a series the normal book
    already allows is left alone — this only ever ADDS a family member the
    curator would have added by hand. A hand-tuned override elsewhere wins;
    this only fills gaps, exactly like the base-list loop above."""
    if not FINECON_SERIES_PREFIXES:
        return 0
    added = set()
    for t in series_seen:
        s = series_of(t) if "-" in str(t) else str(t)
        if not s or s in FINECON_SERIES or s in FINECON_FAMILY:
            continue
        if not any(s.startswith(p) for p in FINECON_SERIES_PREFIXES):
            continue
        if IncentiveMarketMaker._blocked(f"{s}-X"):
            log(f"[IMM] ! finecon family: refused blocklisted {s}")
            continue
        added.add(s)
    if not added:
        return 0
    for s in added:
        if s not in SERIES_OVERRIDES:
            SERIES_OVERRIDES[s] = finecon_family_override()
    FINECON_FAMILY.update(added)
    FINECON_SERIES.update(added)
    log(f"[IMM] finecon family: +{len(added)} by prefix "
        f"{list(FINECON_SERIES_PREFIXES)} -> {', '.join(sorted(added))} "
        f"(quoting stops {FINECON_FAMILY_CUTOFF_FROM_CLOSE_MIN}min before close)")
    return len(added)


def load_finecon_extra_series() -> int:
    try:
        mtime = os.path.getmtime(FINECON_EXTRA_FILE)
    except OSError:
        return 0
    if mtime == _finecon_extra_state["mtime"]:
        return 0
    _finecon_extra_state["mtime"] = mtime
    try:
        with open(FINECON_EXTRA_FILE, encoding="utf-8") as f:
            data = json.load(f) or {}
    except (OSError, ValueError) as e:
        log(f"[IMM] ! finecon extra file unreadable: {e}")
        return 0
    fresh: Set[str] = set()
    for s in data.get("series") or []:
        s = str(s).strip()
        if not s or not s.startswith("KX"):
            continue
        if any(s.startswith(p) for p in SERIES_BLOCKLIST_PREFIXES) \
                or series_pattern_blocked(s):
            log(f"[IMM] ! refused blocklisted series in finecon extra: {s}")
            continue
        # A name-pattern family member belongs to the NORMAL book (2026-09-22:
        # the 17 *POS entries the Carbon Arc self-extend wrote here were
        # walked/capped as finecon and mostly unquoted). Skipped and logged
        # once; the file itself is left alone.
        if series_family_suffix(s):
            if s not in _finecon_family_skipped:
                _finecon_family_skipped.add(s)
                log(f"[IMM] finecon extra: {s} matches a family suffix "
                    f"-> normal book (ALLOW_FAMILY_SUFFIXES), not finecon")
            continue
        fresh.add(s)
    target = _FINECON_BASE | FINECON_FAMILY | fresh
    changed = len(target ^ FINECON_SERIES)
    if changed:
        for s in target - FINECON_SERIES:
            if s not in SERIES_OVERRIDES:
                SERIES_OVERRIDES[s] = (
                    finecon_family_override()
                    if any(s.startswith(p) for p in FINECON_SERIES_PREFIXES)
                    else SeriesOverride(
                        min_est_per_day=_env_float("IMM_FINECON_MIN_RATE", 0.0),
                        safe_join=True))
        FINECON_SERIES.clear()
        FINECON_SERIES.update(target)
        log(f"[IMM] finecon extra series: {len(fresh)} extended "
            f"({changed} changed)")
    return changed


# Family-suffix source verdicts (2026-09-22, see ALLOW_FAMILY_SUFFIXES):
# {"series": {"KXAMZNCC": {"carbon_arc": true, "ts": ..., "title": ...},
# ...}}. WRITTEN by the bot as it resolves novel suffix matches
# (_resolve_family_verdicts), READ at import by every script that
# classifies the feed through _allowed (quote gaps, feed audit, new-
# programs email, the overrides task) and by mtime each refresh, so one
# membership serves the bot and its reports. Deleting the file = every
# family series is re-read on the next refresh (and NOT allowed until it
# is -- fail closed); a hand edit is honored on the next refresh.
FAMILY_VERDICT_FILE = os.path.join(STATUS_DIR, "family_series_verdicts.json")
_family_verdict_state = {"mtime": 0.0}


def load_family_verdicts() -> int:
    """Mirror FAMILY_VERDICT_FILE into FAMILY_VERDICTS (mtime-gated).
    Returns the number of series whose verdict changed."""
    try:
        mtime = os.path.getmtime(FAMILY_VERDICT_FILE)
    except OSError:
        return 0
    if mtime == _family_verdict_state["mtime"]:
        return 0
    _family_verdict_state["mtime"] = mtime
    try:
        with open(FAMILY_VERDICT_FILE, encoding="utf-8") as f:
            data = json.load(f) or {}
    except (OSError, ValueError) as e:
        log(f"[IMM] ! family verdict file unreadable: {e}")
        return 0
    fresh: Dict[str, dict] = {}
    for s, ent in (data.get("series") or {}).items():
        s = str(s).strip()
        if not s.startswith("KX") or not isinstance(ent, dict) \
                or "carbon_arc" not in ent:
            continue
        fresh[s] = {"carbon_arc": bool(ent.get("carbon_arc")),
                    "ts": float(ent.get("ts") or 0.0),
                    "title": str(ent.get("title") or "")}
    changed = sum(
        1 for s in set(fresh) | set(FAMILY_VERDICTS)
        if (fresh.get(s) or {}).get("carbon_arc")
        != (FAMILY_VERDICTS.get(s) or {}).get("carbon_arc"))
    FAMILY_VERDICTS.clear()
    FAMILY_VERDICTS.update(fresh)
    if changed:
        log(f"[IMM] family verdicts: {len(fresh)} loaded ({changed} changed)")
    return changed


def save_family_verdicts() -> None:
    """Persist FAMILY_VERDICTS atomically. The loader's mtime is bumped so
    the bot does not re-read its own write on the next refresh."""
    try:
        os.makedirs(STATUS_DIR, exist_ok=True)
        tmp = FAMILY_VERDICT_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"series": FAMILY_VERDICTS}, f, indent=1, sort_keys=True)
        os.replace(tmp, FAMILY_VERDICT_FILE)
        _family_verdict_state["mtime"] = os.path.getmtime(FAMILY_VERDICT_FILE)
    except OSError as e:
        log(f"[IMM] ! family verdict file write failed: {e}")


load_family_verdicts()
load_sat_gate()          # Saturday step-up verdict (defined next to saturday_size_mult)
load_election_extra_series()   # Elections-category members (beside election_series)
load_nfl_auto_series()         # NFL auto families (beside the election file)
load_league_auto_series()      # NBA / WNBA / MLB auto families (ditto)
load_awards_extra_series()     # awards by Kalshi tag (beside the election file)
load_graduate_auto_series()    # graduate families by Kalshi metadata (ditto)
load_mention_auto_series()     # single-event mentions by Kalshi category (ditto)


