# been the better forecaster; 40c still stops a book that is wildly off
LOWT_FAIR_TOL_CENTS = _env_int("IMM_LOWT_FAIR_TOL_CENTS", 40)
LOWT_FAIR_TTL_MIN = _env_int("IMM_LOWT_FAIR_TTL_MIN", 90)
LOWT_FAIR_REFRESH_SECS = _env_int("IMM_LOWT_FAIR_REFRESH_SECS", 1800)
LOWT_DAILY_LOSS_LIMIT = _env_float("IMM_LOWT_DAILY_LOSS_LIMIT", 0.0)
LOWT_HALT_KEY = "LOWT"
# SIZE x3 AND A 3-97c BAND (Jack 2026-10-23: "3x and also extend range to
# 3-97"). On the first pass only 6 of 144 next-day markets cleared the $1.30
# payout bar: each pays ~$12/day against ~8,000 contracts already in the
# scoring range, and a next-day market has at most 14 hours (10 AM listing
# to midnight ET). The bot's estimate scales with size (x1 15 markets, x3
# 51 on a full window), and the per-market / per-event caps scale with it
# (applied_mention_mult). The band replaces 5-90c both for entry (the
# extreme_mid screen widens to a series' own band) and for every rung.
# Every KXLOWT city clones the parent (FAMILY_OVERRIDE_PARENTS).
# x5 since 2026-10-24 (Jack: "5x multiplier"): the markets under the payout
# bar projected ~45c each before their stop at x3, about a third of $1.30
LOWT_SIZE_MULT = _env_float("IMM_LOWT_SIZE_MULT", 5.0)
LOWT_PRICE_MIN = _env_int("IMM_LOWT_PRICE_MIN", 3)
LOWT_PRICE_MAX = _env_int("IMM_LOWT_PRICE_MAX", 97)
SERIES_OVERRIDES[LOWT_PARENT] = SeriesOverride(
    size_mult=LOWT_SIZE_MULT, price_min_cents=LOWT_PRICE_MIN,
    price_max_cents=LOWT_PRICE_MAX)
_lowt_state: dict = {"mtime": 0.0, "events": {}}
_lowt_owner: dict = {"at": 0.0, "paused": False}


def lowt_owner_paused(now_ts: Optional[float] = None, force: bool = False) -> bool:
    """Is low_temp_trading.py paused (its flag file present)? Cached for
    LOWT_OWNER_CHECK_SECS: _allowed asks for every ticker, every refresh."""
    now_ts = time.time() if now_ts is None else now_ts
    if force or now_ts - _lowt_owner["at"] > LOWT_OWNER_CHECK_SECS:
        _lowt_owner["paused"] = os.path.exists(LOWT_OWNER_FLAG)
        _lowt_owner["at"] = now_ts
    return _lowt_owner["paused"]


def lowt_series(series: str) -> bool:
    """A KXLOWT daily, while the family is on and the low bot stays paused."""
    return (LOWT_ENABLE and series.startswith(LOWT_PREFIX)
            and lowt_owner_paused())


def _load_temp_fair(path: str, state: dict, what: str) -> int:
    """Hot-reload a temperature fair file (lowt_fair / hight_fair) by mtime
    into `state`. Returns the number of events loaded on a reload, else 0."""
    try:
        mtime = os.path.getmtime(path)
    except OSError:
        return 0
    if mtime == state["mtime"]:
        return 0
    state["mtime"] = mtime
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f) or {}
    except (OSError, ValueError) as e:
        log(f"[IMM] ! {what} fair file unreadable: {e}")
        return 0
    fresh: Dict[str, dict] = {}
    for ev, e in (data.get("events") or {}).items():
        ts = parse_iso_utc(str((e or {}).get("fetched_at") or ""))
        if ts is None:
            continue
        fresh[str(ev)] = dict(e, ts=ts.timestamp())
    state["events"] = fresh
    # the series the writer found to be US daily temperatures (a CLI station
    # in the rules): the high family's membership (hight_series)
    state["series"] = {str(s) for s, cli in (data.get("series") or {}).items() if cli}
    return len(fresh)


def load_lowt_fair() -> int:
    """Hot-reload LOWT_FAIR_FILE by mtime into _lowt_state."""
    return _load_temp_fair(LOWT_FAIR_FILE, _lowt_state, "low-temp")


def _temp_gate(state: dict, ticker: str, now_ts: float,
               ext_bid: Optional[float], ext_ask: Optional[float],
               tol: int, ttl_min: int, what: str) -> Tuple[str, dict]:
    """('', inputs) when a temperature-family market may quote (joining the
    touch, as everywhere), else (why, guard-skip inputs). Fails CLOSED: no
    read for the event, a stale one, a skipped day or an unmodelled market;
    else stands aside when the touch fights the fair by more than `tol`."""
    e = state["events"].get(ticker.rsplit("-", 1)[0])
    if e is None:
        return f"no {what} fair for this event", {"reason": "no_read"}
    age = now_ts - float(e.get("ts") or 0.0)
    if age > ttl_min * 60:
        return (f"{what} fair is {age / 60:.0f}m old",
                {"reason": "stale", "age_s": round(age)})
    if e.get("skip"):
        why = str(e["skip"])[:160]
        return f"no fair: {why}", {"reason": "skip", "why": why}
    p = (e.get("markets") or {}).get(ticker)
    if p is None:
        return f"market not in the {what} read", {"reason": "no_market"}
    fair = float(p) * 100.0
    inputs = {"fair": round(fair, 2), "mu": e.get("mu"), "b": e.get("b"),
              "nws": e.get("nws"), "wu": e.get("wu"), "tol": tol}
    bid_bad, ask_bad = fair_gate_breach(ext_bid, ext_ask, fair, tol)
    if bid_bad or ask_bad:
        return (f"book {ext_bid}x{ext_ask} vs fair {fair:.0f}c (tol {tol}c, "
                f"{'bid' if bid_bad else 'ask'} side; {what} {e.get('mu')}F, "
                f"scale {e.get('b')}F)",
                dict(inputs, reason="band", bid_bad=bid_bad, ask_bad=ask_bad))
    return "", inputs


def lowt_gate(ticker: str, now_ts: float, ext_bid: Optional[float],
              ext_ask: Optional[float]) -> Tuple[str, dict]:
    """_temp_gate on the low-temperature read."""
    return _temp_gate(_lowt_state, ticker, now_ts, ext_bid, ext_ask,
                      LOWT_FAIR_TOL_CENTS, LOWT_FAIR_TTL_MIN, "low-temp")


