def pilot_halt_key(series: str) -> Optional[str]:
    """The daily loss budget a pilot series spends: its own name for a Trump
    weekly pilot (one budget per series), NFL_H2H_HALT_KEY for the whole NFL
    head-to-head family while it has one (NFL_H2H_DAILY_LOSS_LIMIT > 0; off
    since 2026-10-12), None for everything else."""
    if twk_series(series):
        return series
    if nfl_h2h_series(series) and NFL_H2H_DAILY_LOSS_LIMIT > 0:
        return NFL_H2H_HALT_KEY
    # the YouTube #1 leader-bid pilot (2026-10-14): one budget, its series
    if yt1_series(series) and YT1_DAILY_LOSS_LIMIT > 0:
        return series
    # the low- and high-temperature families (2026-10-23): one budget each
    if lowt_series(series) and LOWT_DAILY_LOSS_LIMIT > 0:
        return LOWT_HALT_KEY
    if hight_series(series) and HIGHT_DAILY_LOSS_LIMIT > 0:
        return HIGHT_HALT_KEY
    # the opportunistic AS test's families (gas 2026-10-25; Billboard and
    # VoteHub 2026-10-27): one budget each
    _asf = astest_family(series)
    if _asf is not None and astest_knob(_asf, "DAILY_LOSS") > 0:
        return astest_knob(_asf, "HALT_KEY")
    return None


NFL_AUTO_BUDGET_PREFIX = "NFLAUTO:"


def nfl_auto_event_key(ticker: str) -> str:
    """'KXNFLTD-26OCT15SEADEN-SEAEWILSON23-3' -> 'KXNFLTD-26OCT15SEADEN': the
    series and its game / season segment -- Kalshi's event for every NFL
    auto family seen (KXNFLTD-26OCT15SEADEN, KXNFLLASTTOWIN-27,
    KXNFLPLAYOFFC-27NYJNYG; event_ticker_of would cut KXNFLTD per player)."""
    return "-".join(ticker.split("-")[:2])


def pilot_budget_key(ticker: str) -> Optional[str]:
    """The daily loss budget a pilot MARKET spends: its series' (a Trump
    weekly series, the NFL head-to-head family -- pilot_halt_key), or one
    per EVENT for an NFL auto family at pilot size (Jack 2026-10-12: "make
    it per event"), 'NFLAUTO:<event>'."""
    series = series_of(ticker)
    if nfl_auto_pilot(series):
        return (NFL_AUTO_BUDGET_PREFIX + nfl_auto_event_key(ticker)
                if NFL_AUTO_DAILY_LOSS_LIMIT > 0 else None)
    # the league auto families (2026-10-15): the same budget per event
    if league_auto_pilot(series):
        return (LEAGUE_AUTO_BUDGET_PREFIX + nfl_auto_event_key(ticker)
                if LEAGUE_AUTO_DAILY_LOSS_LIMIT > 0 else None)
    return pilot_halt_key(series)


def pilot_halt_limit(key: str) -> float:
    if key == NFL_H2H_HALT_KEY:
        return NFL_H2H_DAILY_LOSS_LIMIT
    if key == YT1_SERIES:
        return YT1_DAILY_LOSS_LIMIT
    if key == LOWT_HALT_KEY:
        return LOWT_DAILY_LOSS_LIMIT
    if key == HIGHT_HALT_KEY:
        return HIGHT_DAILY_LOSS_LIMIT
    if key == ASTEST_GAS_HALT_KEY:
        return ASTEST_GAS_DAILY_LOSS
    for _f in ASTEST_FAMILIES:
        if key == astest_knob(_f, "HALT_KEY"):
            return astest_knob(_f, "DAILY_LOSS")
    if key.startswith(NFL_AUTO_BUDGET_PREFIX):
        return NFL_AUTO_DAILY_LOSS_LIMIT
    if key.startswith(LEAGUE_AUTO_BUDGET_PREFIX):
        return LEAGUE_AUTO_DAILY_LOSS_LIMIT
    return TWK_DAILY_LOSS_LIMIT


def pilot_halt_keys() -> List[str]:
    """Every live pilot budget, Trump weekly series first."""
    keys = sorted(TWK_SERIES) if TWK_ENABLE else []
    if NFL_H2H_ENABLE and NFL_H2H_DAILY_LOSS_LIMIT > 0:
        keys.append(NFL_H2H_HALT_KEY)
    if YT1_ENABLE and YT1_DAILY_LOSS_LIMIT > 0:
        keys.append(YT1_SERIES)
    if LOWT_ENABLE and LOWT_DAILY_LOSS_LIMIT > 0:
        keys.append(LOWT_HALT_KEY)
    if HIGHT_ENABLE and HIGHT_DAILY_LOSS_LIMIT > 0:
        keys.append(HIGHT_HALT_KEY)
    if ASTEST_ENABLE and ASTEST_GAS_DAILY_LOSS > 0:
        keys.append(ASTEST_GAS_HALT_KEY)
    for _f in ASTEST_FAMILIES:
        if ASTEST_ENABLE and astest_knob(_f, "ENABLE") and astest_knob(_f, "DAILY_LOSS") > 0:
            keys.append(astest_knob(_f, "HALT_KEY"))
    return keys


