def _parse_awards_dates(spec: str) -> Tuple[Tuple[str, datetime], ...]:
    """'<event-ticker glob>=<YYYY-MM-DD>,...' -> ((glob, 00:00 ET of that
    day as UTC), ...) in the order given: the first matching glob wins, so
    a nominations glob must be listed before its family-wide ceremony glob."""
    out = []
    for part in (p.strip() for p in spec.split(",") if p.strip()):
        try:
            glob_s, day = part.split("=")
            when = datetime.strptime(day.strip(), "%Y-%m-%d")
        except ValueError:
            raise ValueError(f"bad IMM_AWARDS_EVENT_DATES part: {part!r}")
        out.append((glob_s.strip(), ET.localize(when).astimezone(timezone.utc)))
    return tuple(out)


AWARDS_EVENT_DATES = _parse_awards_dates(os.environ.get(
    "IMM_AWARDS_EVENT_DATES", _AWARDS_DATES_DEFAULT))


# HOT-RELOADED ROWS (Jack 2026-10-07: "how to ensure new events get quoted
# when they should fall under existing quote families e.g. elections, award
# ceremonies, rain, etc. dont want to manually catch this going fwd" -> "yes
# build all 5"). Dated rows the code tables lack live in two files beside the
# state, {"rows": [{"glob", "date", "zone" (elections), "sources", "by", "at",
# "note"}]} ("term_end" and "checked" too on an election row for a vote not
# yet called: election_term_end), written by imm_rows.py (the gap-fixer
# routine and hand fixes: two
# different sources a row) and by imm_family_watch.py's US-general rule. Re-read
# by mtime at import and every universe refresh, so a fix lands in one refresh
# with no deploy. The code tables are checked first and win on an event both
# match.
ELECTION_DATES_EXTRA_FILE = "election_dates_extra.json"     # in STATUS_DIR
AWARDS_DATES_EXTRA_FILE = "awards_dates_extra.json"         # in STATUS_DIR
# a series name of 3+ letters/digits, then the glob: Kalshi's legacy
# un-prefixed series (CONTROLH, ECMOV, POPVOTEMOV) date here too -- the old
# KX-only pattern refused them (2026-10-14) -- and no row may open on a
# wildcard (the old pattern took a catch-all "KX*")
ROWS_GLOB_RE = re.compile(r"[A-Z][A-Z0-9]{2,}[A-Z0-9*?\[\]-]*")
ELECTION_DATES_EXTRA: List[Tuple[str, datetime, Any, Any]] = []
# the election rows marked "term_end" (a vote not yet called, see
# election_term_end): (glob, cutoff, day, zone, checked epoch)
ELECTION_TERM_ENDS: List[Tuple[str, datetime, Any, Any, float]] = []
AWARDS_DATES_EXTRA: List[Tuple[str, datetime]] = []
_rows_extra_state: Dict[str, float] = {}


def election_dates_extra_path() -> str:
    return os.path.join(STATUS_DIR, ELECTION_DATES_EXTRA_FILE)


def awards_dates_extra_path() -> str:
    return os.path.join(STATUS_DIR, AWARDS_DATES_EXTRA_FILE)


def _rows_file(path: str) -> Optional[list]:
    """A hot-reloaded rows file's rows when it changed since the last read
    (by mtime; a file that went away reads as []), else None."""
    try:
        mtime = os.path.getmtime(path)
    except OSError:
        if _rows_extra_state.get(path):
            _rows_extra_state[path] = 0.0
            return []
        return None
    if mtime == _rows_extra_state.get(path):
        return None
    _rows_extra_state[path] = mtime
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f) or {}
    except (OSError, ValueError) as e:
        log(f"[IMM] ! {os.path.basename(path)} unreadable: {e}")
        return None
    return [r for r in (data.get("rows") or []) if isinstance(r, dict)]


def _row_spec(r: dict, with_zone: bool) -> Optional[str]:
    """'<glob>=<date>[@<zone>]' for a well-formed row, else None."""
    g = str(r.get("glob") or "").strip()
    d = str(r.get("date") or "").strip()
    z = str(r.get("zone") or "").strip() if with_zone else ""
    if not ROWS_GLOB_RE.fullmatch(g) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", d):
        return None
    return f"{g}={d}" + (f"@{z}" if z else "")


def load_awards_dates_extra() -> int:
    """Re-read AWARDS_DATES_EXTRA_FILE when it changed. Returns how many
    rows changed (0 when unchanged)."""
    rows = _rows_file(awards_dates_extra_path())
    if rows is None:
        return 0
    fresh = []
    for r in rows:
        spec = _row_spec(r, with_zone=False)
        try:
            fresh += list(_parse_awards_dates(spec)) if spec else []
        except ValueError as e:
            log(f"[IMM] ! awards dates extra: {e}")
    changed = len(set(fresh) ^ set(AWARDS_DATES_EXTRA))
    AWARDS_DATES_EXTRA[:] = fresh
    if changed:
        log(f"[IMM] awards dates extra: {len(fresh)} row(s) ({changed} changed)")
    return changed


load_awards_dates_extra()


def awards_event_start(event_ticker: str, market: Optional[dict],
                       dates_only: bool = False) -> Optional[datetime]:
    """When an award event starts (UTC): the hand table first, then Kalshi's
    occurrence / expected expiration off the market object unless
    `dates_only`. None when nothing trustworthy says (the caller fails
    closed)."""
    for glob_s, when in tuple(AWARDS_EVENT_DATES) + tuple(AWARDS_DATES_EXTRA):
        if fnmatch.fnmatchcase(event_ticker, glob_s):
            return when
    if dates_only or not isinstance(market, dict):
        return None
    occ = parse_iso_utc(market.get("occurrence_datetime", ""))
    exp = parse_iso_utc(market.get("expected_expiration_time", ""))
    if occ is not None and exp is not None \
            and occ <= exp - timedelta(minutes=60):
        start = occ
    else:
        start = exp
    if start is None or (start.month == 12 and start.day == 31):
        return None          # absent, or Kalshi's year-end placeholder
    return start


def awards_family_default(event_ticker: str) -> Optional[datetime]:
    """A category Kalshi lists after its table-only family's rows were
    written (Jack 2026-10-07, after 8 Critics Choice TV categories sat dark:
    "also resolve issues like this going forward"): the family's EARLIEST
    row for the same show, so the newcomer stands down no later than any
    sibling (an early stand-down is the safe error) and quotes until then
    instead of not at all. A show with no rows (next year's) still gets
    None, as does a series outside AWARDS_TABLE_ONLY_SERIES. The same show
    is the same edition, the event segment's trailing number (else its
    leading one, _awards_edition), so a series that carries the category IN
    the segment (KXCRITICSCHOICENOM-SONG27, KXGRAMMYNOM-69BPDGP) finds its
    siblings' rows (-CINE27, and the winners' -27) too."""
    series, _, suffix = event_ticker.partition("-")
    fam = max((f for f in AWARDS_TABLE_ONLY_SERIES if series.startswith(f)),
              key=len, default=None)
    if fam is None or not suffix:
        return None
    edition = _awards_edition(suffix)
    best = None
    for glob_s, when in tuple(AWARDS_EVENT_DATES) + tuple(AWARDS_DATES_EXTRA):
        g_series, _, g_suffix = glob_s.partition("-")
        if g_series.startswith(fam) and g_suffix \
                and (fnmatch.fnmatchcase(suffix, g_suffix)
                     or (edition is not None
                         and _awards_edition(g_suffix) == edition)) \
                and (best is None or when < best):
            best = when
    return best


def _awards_edition(segment: str) -> Optional[str]:
    """The show's edition off an event segment or its glob: the trailing
    number ('27' of '27' / 'ACTR27' / '*27', '69' of 'BAMP69'), else a
    leading one ('69' of '69BPDGP' / '69*', the one-series KXGRAMMYNOM
    shape, 2026-10-12), else None."""
    m = re.search(r"\d+$", segment) or re.match(r"\d+", segment)
    return m.group(0) if m else None


