def _parse_election_dates(spec: str) -> Tuple[Tuple[str, datetime, Any, Any], ...]:
    """'<event-ticker glob>=<YYYY-MM-DD>[@<IANA zone>],...' -> ((glob,
    cutoff_utc, voting_day, zone), ...), first matching glob wins. The cutoff is the
    START of the voting day wherever it starts first: the earlier of 00:00 ET
    and 00:00 in the voting jurisdiction's zone (default ET). West of ET
    (Nevada, Alaska, Hawaii) that is ET midnight; east of it (Europe, India,
    Taiwan) it is local midnight -- Taipei's Nov 28 begins 11:00 ET Nov 27."""
    out = []
    for part in (p.strip() for p in spec.split(",") if p.strip()):
        try:
            glob_s, val = part.split("=")
            day, _, zone = val.strip().partition("@")
            naive = datetime.strptime(day.strip(), "%Y-%m-%d")
            zone = zone.strip() or "America/New_York"
            local = pytz.timezone(zone).localize(naive)
        except (ValueError, pytz.UnknownTimeZoneError):
            raise ValueError(f"bad IMM_ELECTION_DATES part: {part!r}")
        et_mid = ET.localize(naive)
        out.append((glob_s.strip(),
                    min(et_mid, local).astimezone(timezone.utc), naive.date(),
                    pytz.timezone(zone)))
    return tuple(out)


ELECTION_DATES = _parse_election_dates(os.environ.get(
    "IMM_ELECTION_DATES", _ELECTION_DATES_DEFAULT))


def load_election_dates_extra() -> int:
    """Re-read ELECTION_DATES_EXTRA_FILE when it changed. Returns how many
    rows changed (0 when unchanged). A row marked "term_end" goes to
    ELECTION_TERM_ENDS with its "checked" stamp (else its "at"), not to the
    voting-day rows."""
    rows = _rows_file(election_dates_extra_path())
    if rows is None:
        return 0
    fresh, term = [], []
    for r in rows:
        spec = _row_spec(r, with_zone=True)
        try:
            parsed = list(_parse_election_dates(spec)) if spec else []
        except ValueError as e:
            log(f"[IMM] ! election dates extra: {e}")
            continue
        if r.get("term_end"):
            checked = parse_iso_utc(str(r.get("checked") or r.get("at") or ""))
            term += [p + ((checked.timestamp() if checked else 0.0),) for p in parsed]
        else:
            fresh += parsed
    changed = (len(set(fresh) ^ set(ELECTION_DATES_EXTRA))
               + len(set(term) ^ set(ELECTION_TERM_ENDS)))
    ELECTION_DATES_EXTRA[:] = fresh
    ELECTION_TERM_ENDS[:] = term
    if changed:
        log(f"[IMM] election dates extra: {len(fresh)} row(s)"
            + (f" + {len(term)} term-end" if term else "") + f" ({changed} changed)")
    return changed


load_election_dates_extra()
ELECTION_OCC_BACK_HOURS = 6
_election_disagree_warned: Set[str] = set()


def _kalshi_vote_days(event_ticker: str, market: Optional[dict], zone) -> list:
    """Kalshi's own days for an election event's vote -- the ticker date and
    the occurrence's day in the vote's zone. Only ever compared."""
    kalshi = []
    td = parse_event_date(event_ticker)
    if td is not None:
        kalshi.append(td.astimezone(ET).date())
    occ = (parse_iso_utc(market.get("occurrence_datetime") or "")
           if isinstance(market, dict) else None)
    if occ is not None:
        # Kalshi's occurrence is usually the poll close: its calendar day in
        # the VOTE's zone, a few hours back so a close just after midnight
        # still counts for the voting day
        kalshi.append((occ - timedelta(hours=ELECTION_OCC_BACK_HOURS))
                      .astimezone(zone).date())
    return kalshi


# TERM END (Jack 2026-10-28, of KXJAPANHOUSE-30FEB07 -- "Next Japanese general
# election winner?", 7 parties at $115 a market, dark for want of a voting
# day -- "date it to term end as a rule"). A vote nobody has called yet (a
# "next general election" or "next leader" market, a snap election not yet
# triggered) has no voting day to verify, so it used to stay dark like
# Punjab. It now quotes to its TERM END: a hot row (imm_rows.py election add
# ... --term-end, two sources like every row) on the day by which the vote
# must happen under the rules in force -- the sitting term's end (Japan's
# House: four years from the 2026-02-08 election, so 2030-02-07), a default
# date set in law, the contract's own deadline, or Kalshi's own date for the
# event, whichever is earliest. The row stands
# ELECTION_TERM_END_RECHECK_DAYS from its "checked" stamp; the family watch
# re-checks it from TERM_END_REFRESH_DAYS and either re-stamps it (no vote
# yet) or replaces it with the voting day once one is called. Past its
# re-check, or once Kalshi dates the vote EARLIER than the row (the
# occurrence moved: a vote may have been called), the event stands down
# (fail closed) until research looks again. The re-check is the safety: a
# Japanese vote comes 16-24 days after a dissolution in practice (40 at most,
# Constitution art. 54), so a weekly look sees it a week or more before
# voting day. Any voting-day row, code or hot, wins over a term-end row.
# IMM_ELECTION_TERM_END_RECHECK_DAYS=0 stands every term-end row down.
ELECTION_TERM_END_RECHECK_DAYS = _env_float("IMM_ELECTION_TERM_END_RECHECK_DAYS", 7.0)
_election_term_end_noted: Dict[str, str] = {}


def election_term_end_row(event_ticker: str) -> Optional[Tuple[str, datetime, Any, Any, float]]:
    """The first ELECTION_TERM_ENDS row whose glob matches, else None."""
    return next((r for r in tuple(ELECTION_TERM_ENDS)
                 if fnmatch.fnmatchcase(event_ticker, r[0])), None)


def election_term_end(event_ticker: str, market: Optional[dict] = None,
                      now_ts: Optional[float] = None) -> Tuple[Optional[datetime], str]:
    """(cutoff, "") when a standing term-end row dates the event; (None, why)
    when its row is past its re-check or Kalshi now dates the vote earlier;
    (None, "") with no term-end row."""
    row = election_term_end_row(event_ticker)
    if row is None:
        return None, ""
    _glob, when, day, zone, checked = row
    stamp = datetime.fromtimestamp(checked, timezone.utc).strftime("%Y-%m-%d")
    now_ts = time.time() if now_ts is None else now_ts
    if now_ts - checked > ELECTION_TERM_END_RECHECK_DAYS * 86400:
        return None, (f"its term-end row {day} was last checked {stamp}, over "
                      f"{ELECTION_TERM_END_RECHECK_DAYS:g} days ago: a vote may "
                      f"have been called")
    early = [k for k in _kalshi_vote_days(event_ticker, market, zone)
             if k < day and (k.month, k.day) != (12, 31)]
    if early:
        return None, (f"Kalshi now dates the vote {min(early)}, before its "
                      f"term-end row {day}: a vote may have been called")
    note = f"{day} checked {stamp}"
    if _election_term_end_noted.get(event_ticker) != note:
        _election_term_end_noted[event_ticker] = note
        log(f"[IMM] {event_ticker}: no vote called yet -- quoting to its term "
            f"end {day} (checked {stamp})")
    return when, ""


def election_cutoff_utc(event_ticker: str,
                        market: Optional[dict] = None) -> Optional[datetime]:
    """The verified start of an election event's voting day (as UTC) from
    ELECTION_DATES, else a standing TERM-END row's (election_term_end), else
    None (the caller stands the market down). Kalshi's own dates are never
    used; when the ticker date or the occurrence's day is EARLIER than the
    verified day it is logged once, so a stale row shows up (a term-end row
    stands down on it instead)."""
    for glob_s, when, day, zone in tuple(ELECTION_DATES) + tuple(ELECTION_DATES_EXTRA):
        if fnmatch.fnmatchcase(event_ticker, glob_s):
            break
    else:
        return election_term_end(event_ticker, market)[0]
    early = [k for k in _kalshi_vote_days(event_ticker, market, zone)
             if k < day and (k.month, k.day) != (12, 31)]
    if early and event_ticker not in _election_disagree_warned:
        _election_disagree_warned.add(event_ticker)
        log(f"[IMM] ! {event_ticker}: Kalshi dates the vote {min(early)} but "
            f"the verified table says {day} -- quoting to the verified day; "
            f"re-check the row")
    return when


def market_data_month(market: Optional[dict]) -> Optional[Tuple[int, int]]:
    """(year, month) of the DATA month a market's text names, or None."""
    if not isinstance(market, dict):
        return None
    for key in ("title", "rules_primary", "rules_secondary"):
        m = _DATA_MONTH_RE.search(str(market.get(key) or ""))
        if m:
            return int(m.group(2)), _MONTH_NUM[m.group(1).lower()]
    return None


def release_guard_cutoff(year: int, month: int, day: int) -> datetime:
    """00:00 ET on `day` of the month AFTER (year, month), as UTC."""
    y, mo = (year + 1, 1) if month == 12 else (year, month + 1)
    return ET.localize(datetime(y, mo, day)).astimezone(timezone.utc)


# SAME-DAY SECOND EVENT (Jack 2026-10-15: "ship 1 - 4", item 3 of the 10/14-15
# pick-off review). Trump repeats his stump speech, so once his first event of
# the day is under way, a later event's words are no longer a forecast.
# KXTRUMPMENTIONB-26OCT14 (the Montana rally, 20:15 ET on file) was quoted
# after KXTRUMPMENTION-26OCT14 (Arizona, 15:45 ET) had ended: on the words he
# had just said in Arizona, 503 contracts of ours lost $134 at settlement; on
# the words he had not, $7. So an event of a SAME_DAY_SPEAKER_PREFIXES series
# with a start on file (EVENT_START_OVERRIDES: the WH / RNC / hand-set times)
# is out from the earliest start, less OVERRIDE_BUFFER_MIN, of the group's
# other events on the same ET day that start before it. An event with no
# start on file keeps its rules: a ticker date can be a listing date
# (ticker_date_is_listing_date), so it cannot place the event on a day.
# IMM_SAME_DAY_SPEAKER_PREFIXES="" turns it off.
SAME_DAY_SPEAKER_PREFIXES: Tuple[str, ...] = tuple(
    p.strip() for p in os.environ.get(
        "IMM_SAME_DAY_SPEAKER_PREFIXES", "KXTRUMPMENTION").split(",") if p.strip())
_same_day_noted: Dict[str, str] = {}


def same_day_speaker(series: str) -> Optional[str]:
    """The SAME_DAY_SPEAKER_PREFIXES group a series belongs to, else None."""
    return next((p for p in SAME_DAY_SPEAKER_PREFIXES if series.startswith(p)), None)


def same_day_first_start(event_ticker: str) -> Optional[Tuple[datetime, str]]:
    """(start, event) of the EARLIEST other event of event_ticker's speaker
    group whose start on file falls on the same ET day and before its own,
    else None. Both starts come from EVENT_START_OVERRIDES."""
    grp = same_day_speaker(series_of(event_ticker))
    own = EVENT_START_OVERRIDES.get(event_ticker)
    if grp is None or own is None:
        return None
    day = own.astimezone(ET).date()
    best: Optional[Tuple[datetime, str]] = None
    for ev, st in EVENT_START_OVERRIDES.items():
        if ev == event_ticker or st is None or st >= own \
                or same_day_speaker(series_of(ev)) != grp \
                or st.astimezone(ET).date() != day:
            continue
        if best is None or st < best[0]:
            best = (st, ev)
    return best


def apply_series_cutoff_adjustments(series: str, event_ticker: str,
                                    cutoff: Optional[datetime],
                                    close_time: Optional[datetime] = None,
                                    market: Optional[dict] = None,
                                    ) -> Optional[datetime]:
    """Series-level tighteners every cutoff PRODUCER must run: the
    CLOSE-ANCHORED rule (cutoff_from_close_min, e.g. hourly temp close-10),
    the early-stop (cutoff_before_event_min, e.g. rain 6pm-day-before) and
    the hard-expiry floor (Love Island 8:30pm). Exists because the 2026-07-29
    rain early-stop was applied only in refresh_universe — orphan-restored
    positions rebuilt their own cutoff via raw trade_cutoff_utc and kept
    reduce-only quoting past 6pm (the 7/14 duplicated-threshold class, in
    cutoff form).

    2026-08-04: the close-anchored rule was STILL missing here, so the same
    bug recurred one layer down — orphan-restored TEMP markets got cutoff =
    close instead of close-10 and quoted into the final ten minutes, the most
    informed window of the hour (7 fills observed as late as 6.7 min to
    close, on a -18c/contract-at-4am book). Pass close_time and the tightener
    is applied for BOTH producers.

    2026-09-12: the DATA-MONTH release guard (release_guard_day) lives here
    for the same reason, and needs the market OBJECT (`market`), whose
    title/rules carry the month. A guarded series called without a
    parseable month -- no object passed, or text without "for <Month>
    <Year>" -- gets RELEASE_GUARD_UNKNOWN, a cutoff already in the past: a
    producer that forgets the object stands the market down rather than
    quoting it through the print on the ticker-date fallback."""
    note_release_sources(series, market)       # the release pause's map (2026-10-22)
    ov = SERIES_OVERRIDES.get(series)
    # POWER SLAP (Jack 2026-10-23: "Powerslap bot should stop before match
    # start, not at midnight et"). Kalshi gives no start time before a card:
    # each match's market closes when the match begins (10/23's closed one
    # by one from 12:40 to 2:29 PM ET; 10/09's stayed open into the next
    # morning), so the ticker-date midnight was the only stop. With the
    # card's start on EVENT_START_OVERRIDES (the family watch's research
    # writes it for every match of the card), the bot quotes match day until
    # OVERRIDE_BUFFER_MIN before that start -- REPLACING midnight, which is
    # earlier. With none, midnight stands; the tighteners below still apply.
    if series == POWERSLAP_SERIES:
        start = EVENT_START_OVERRIDES.get(event_ticker)
        if start is not None:
            cutoff = start - timedelta(minutes=OVERRIDE_BUFFER_MIN)
    # MARATHONS (2026-10-30, see MARATHON_PREFIX): out before the division's
    # start on file -- here as well as in the resolver, since the orphan-
    # restore producer never asks the resolver -- and with none on file,
    # stood down.
    if marathon_series(series):
        start = EVENT_START_OVERRIDES.get(event_ticker)
        if start is None:
            cutoff = RELEASE_GUARD_UNKNOWN
            _config_gap(series, event_ticker,
                        f"{event_ticker} has no race start on file "
                        f"(EVENT_START_OVERRIDES) -- standing it down (fail closed) "
                        f"until research or imm_earnings_overrides.py --set adds "
                        f"its division's start")
        else:
            early = start - timedelta(minutes=OVERRIDE_BUFFER_MIN)
            cutoff = early if cutoff is None else min(cutoff, early)
    # NOTE the event-day EXTENDER (event_day_cutoff_et) deliberately does NOT
    # live here — it shifts the ticker-date CANDIDATE inside trade_cutoff_utc,
    # before min() runs, so an occurrence-based cutoff still wins. Applying it
    # here could only ever compare against the already-minimised result and
    # would have quoted straight through a real event start.
    if ov and ov.cutoff_from_close_min is not None and close_time is not None:
        anchored = close_time - timedelta(minutes=ov.cutoff_from_close_min)
        cutoff = anchored if cutoff is None else min(cutoff, anchored)
    if ov and ov.cutoff_before_event_min is not None:
        td = parse_event_date(event_ticker)
        if td is not None:
            early = td - timedelta(minutes=ov.cutoff_before_event_min)
            cutoff = early if cutoff is None else min(cutoff, early)
    if hight_series(series):
        # HIGH-TEMPERATURE FAMILY (2026-10-23, see HIGHT_ENABLE): out at 20:45
        # ET the evening before the market day, ahead of high_temp_trading's
        # evening run. Keyed on the family, not its inherited override, so a
        # producer that runs before the inheritance (orphan restore) applies
        # it too; no date in the ticker -> stood down (fail closed).
        stop = hight_stop_utc(event_ticker)
        cutoff = stop if cutoff is None else min(cutoff, stop)
    if bigsky_series(series):
        # BIG SKY (2026-10-13): out BIGSKY_STOP_DAYS before its month starts;
        # no month in the ticker -> stood down (fail closed), logged once
        stop = bigsky_cutoff(event_ticker)
        if stop == RELEASE_GUARD_UNKNOWN:
            _config_gap(series, event_ticker,
                        f"Big Sky stop needs the month in {event_ticker} "
                        f"(<YYMON>) -- standing it down (fail closed)")
        cutoff = stop if cutoff is None else min(cutoff, stop)
    first = same_day_first_start(event_ticker) if same_day_speaker(series) else None
    if first is not None:
        # SAME-DAY SECOND EVENT (2026-10-15): out once the speaker's earlier
        # event of the day starts; logged once per (event, earlier event)
        early = first[0] - timedelta(minutes=OVERRIDE_BUFFER_MIN)
        note = f"{first[1]}@{first[0].isoformat()}"
        if _same_day_noted.get(event_ticker) != note:
            _same_day_noted[event_ticker] = note
            log(f"[IMM] same-day second event: {event_ticker} "
                f"(start {EVENT_START_OVERRIDES[event_ticker].astimezone(ET):%m-%d %H:%M} ET) "
                f"is out from {early.astimezone(ET):%m-%d %H:%M} ET, "
                f"{OVERRIDE_BUFFER_MIN} min before {first[1]} starts "
                f"({first[0].astimezone(ET):%H:%M} ET) -- the speaker's first "
                f"event of the day reveals the second's words")
        cutoff = early if cutoff is None else min(cutoff, early)
    if mention_auto_series(series) and cutoff is None \
            and event_ticker not in EVENT_START_OVERRIDES:
        # MENTION AUTO WITH NO EVENT WINDOW (2026-10-13): no start on file and
        # nothing dated -- stand down, as the named mention families'
        # no_event_window screen does (it keys on the MENTION name). A dated
        # event keeps 00:00 ET of its ticker's day; a start on file, the
        # resolver's start - OVERRIDE_BUFFER_MIN.
        cutoff = RELEASE_GUARD_UNKNOWN
    if ov and ov.release_guard_day is not None:
        ym = market_data_month(market)
        if ym is None:
            guard = RELEASE_GUARD_UNKNOWN
            _config_gap(series, event_ticker,
                        f"release guard needs the data month "
                        f"but {event_ticker}'s market text does not say "
                        f"'for <Month> <Year>' -- standing it down (fail closed)")
        else:
            guard = release_guard_cutoff(ym[0], ym[1], ov.release_guard_day)
        cutoff = guard if cutoff is None else min(cutoff, guard)
    if series in AUCTION_DATE_SERIES:
        # AUCTION-DAY CUTOFF (2026-09-25, see AUCTION_DATE_SERIES): out at
        # 00:00 ET on the sale day read from the event segment's trailing
        # DDMMMYY; unreadable -> stood down (fail closed), logged once.
        ad = auction_event_date(event_ticker)
        if ad is None:
            ad = RELEASE_GUARD_UNKNOWN
            _config_gap(series, event_ticker,
                        f"auction-day cutoff needs a trailing "
                        f"DDMMMYY date in {event_ticker} -- standing it down "
                        f"(fail closed)")
        cutoff = ad if cutoff is None else min(cutoff, ad)
    if ov and ov.pre_event_days is not None:
        # AWARDS PRE-EVENT STAND-DOWN (2026-09-25, see AWARDS_SERIES): out
        # pre_event_days before the event's start; a table-only family's
        # category with no row takes the family's earliest row for the show
        # (awards_family_default, 2026-10-07); no usable start at all ->
        # stood down (fail closed). Either way a config gap, logged once.
        start = awards_event_start(event_ticker, market,
                                   ov.pre_event_dates_only)
        if start is None and ov.pre_event_dates_only:
            start = awards_family_default(event_ticker)
            if start is not None:
                _config_gap(series, event_ticker,
                            f"no hand-table row for {event_ticker} -- on its "
                            f"family's earliest date for the show, "
                            f"{start.astimezone(ET):%Y-%m-%d} (out "
                            f"{ov.pre_event_days:g}d before, the safe "
                            f"error) until a row is added")
        if start is None:
            pre = RELEASE_GUARD_UNKNOWN
            _config_gap(series, event_ticker,
                        f"pre-event stand-down needs the event "
                        f"start but {event_ticker} has no usable date (hand "
                        f"table, occurrence, expected expiration) -- standing it "
                        f"down (fail closed)")
        else:
            pre = start - timedelta(days=ov.pre_event_days)
        cutoff = pre if cutoff is None else min(cutoff, pre)
    if election_series(series):
        # ELECTION DAY (see ELECTION_DATES): out at the start of the VERIFIED
        # voting day. It REPLACES what came in -- trade_cutoff_utc built that
        # from Kalshi's ticker date / occurrence, which are not trusted here
        # (Jack 2026-09-28: "dont trust that, verify yourself"); only a hand
        # event_start_overrides entry may still pull it earlier. Keyed on the
        # family, not its inherited override, so a producer that runs before
        # the inheritance (orphan restore) applies it too. No verified row ->
        # stood down (fail closed), logged once; a vote not yet called quotes
        # to its term end (election_term_end), and the gap says why one that
        # has a term-end row is out.
        eday = election_cutoff_utc(event_ticker, market)
        if eday is None:
            eday = RELEASE_GUARD_UNKNOWN
            why = election_term_end(event_ticker, market)[1]
            _config_gap(series, event_ticker,
                        f"{event_ticker} has no verified "
                        f"election day in ELECTION_DATES"
                        + (f" ({why})" if why else "") +
                        " -- standing it down "
                        f"(fail closed) until a checked row is added")
        hand = EVENT_START_OVERRIDES.get(event_ticker)
        if hand is not None:
            eday = min(eday, hand - timedelta(minutes=OVERRIDE_BUFFER_MIN))
        cutoff = eday
    hard = series_hard_expiry_utc(series, event_ticker)
    if hard is not None:
        cutoff = hard if cutoff is None else min(cutoff, hard)
    if vercel_series(series):
        # VERCEL PRE-D CUTOFF (2026-09-27, see VERCEL_ENABLE): out
        # VERCEL_CUTOFF_BEFORE_D_MIN before the measured UTC day starts --
        # the export shows D live. Unparseable -> stood down, logged once.
        d0 = vercel_measured_day(event_ticker)
        if d0 is None:
            pre = RELEASE_GUARD_UNKNOWN
            _config_gap(series, event_ticker,
                        f"Vercel pre-D cutoff needs the measured "
                        f"day but {event_ticker} does not parse -- standing it "
                        f"down (fail closed)")
        else:
            pre = d0 - timedelta(minutes=VERCEL_CUTOFF_BEFORE_D_MIN)
        cutoff = pre if cutoff is None else min(cutoff, pre)
    if yt2_series(series):
        # YOUTUBE #2 PILOT CUTOFF (2026-10-05, see YT2_ENABLE): the close
        # anchor above (YT2_CUTOFF_FROM_CLOSE_MIN before the close) is the
        # cutoff; with IMM_YT2_CHART_DAY_CUTOFF=1 also out at the end of the
        # UTC chart day (00:00Z D+1) less YT2_CUTOFF_BEFORE_DAY_END_MIN.
        # Unparseable -> stood down, once.
        d0 = yt2_chart_day(event_ticker)
        if d0 is None:
            end = RELEASE_GUARD_UNKNOWN
            _config_gap(series, event_ticker,
                        f"YouTube #2 cutoff needs the chart day "
                        f"but {event_ticker} does not parse -- standing it down "
                        f"(fail closed)")
            cutoff = end if cutoff is None else min(cutoff, end)
        elif YT2_CHART_DAY_CUTOFF:
            end = d0 + timedelta(days=1,
                                 minutes=-YT2_CUTOFF_BEFORE_DAY_END_MIN)
            cutoff = end if cutoff is None else min(cutoff, end)
    if yt1_series(series):
        # YOUTUBE #1 LEADER-BID PILOT (2026-10-14, see YT1_MODE): out at the
        # end of the UTC chart day; unparseable -> stood down
        d0 = yt2_chart_day(event_ticker)
        end = RELEASE_GUARD_UNKNOWN if d0 is None else d0 + timedelta(days=1)
        cutoff = end if cutoff is None else min(cutoff, end)
    if ytw_series(series) and ytw_event_code(event_ticker) is None:
        # YOUTUBE WEEKLY PILOT (2026-10-06): the close anchor above is the
        # cutoff; an event whose artist code does not parse stands down
        cutoff = RELEASE_GUARD_UNKNOWN
    if mort_series(series):
        # LONG-DATED MORTGAGE CUTOFF (2026-09-28, see MORT_ENABLE): out
        # MORT_CUTOFF_BUFFER_DAYS before the measurement week of the first
        # print that can settle the event. An unknown shape (the in-year
        # touch markets) -> stood down, logged once.
        mc = mort_cutoff_utc(event_ticker)
        if mc is None:
            mc = RELEASE_GUARD_UNKNOWN
            _config_gap(series, event_ticker,
                        f"{event_ticker} is not a modelled "
                        f"mortgage shape (year-end / how-high-in-a-year) -- "
                        f"standing it down (fail closed)")
        cutoff = mc if cutoff is None else min(cutoff, mc)
    # CARBON ARC LATE-MONTH STOP (Jack 2026-09-24 pm, see CA_LATE_STOP_DAYS):
    # keyed on the bot's own source verdict, not the name, so a *FT that is
    # not Carbon Arc (the Taylor Swift charts) keeps its ordinary cutoff.
    if carbon_arc_settled(series):
        stop = ca_stop_utc(event_ticker)
        if stop is not None:
            cutoff = stop if cutoff is None else min(cutoff, stop)
    return cutoff


# Kalshi's long-window mention programs (KXMAMDANIMENTION-26AUG14,
# KXTRUMPMENTION-26AUG05, KXTRUMPMENTIONB-26AUG04) embed the LISTING date in
# the ticker; resolution is close_time, 2-4 weeks out. Reading that segment as
# an event day truncated a 21.5d/$1,300 program to the 2h15m between its
# 01:45Z listing and fake-midnight on 2026-08-14 — payout_floor ate the sliver
# (est_total pennies vs the $1.00 exchange minimum), then `cutoff` locked the
# remaining 21.5d. Third instance of the class; ~$5,800 of pool measured idle
# 2026-08-06. The discriminator is the market's OWN expiration: a mention
# market expiring >5d past its ticker date cannot be resolving on that date
# (historical mention events: median 1.05d; settlement lag <=3d). Scoped to
# MENTION-family series ON PURPOSE — everywhere else the ticker date IS the
# event day (weather, gas, sports, treasuries), and a stray late expiration
# placeholder there must keep failing toward quoting LESS, never through a
# live event. Same-day mentions (KXWCMENTION match day) sit far under the gap
# bar and keep the midnight rule; occurrence and EVENT_START_OVERRIDES
# cutoffs still apply through min() regardless. KXEARNINGSMENTION* is NOT a
# same-day mention and is excluded outright: see EARNINGS_UNDATED_LEAD_DAYS.
MENTION_LISTING_GAP_DAYS = 5.0

# UNDATED EARNINGS CALL (Jack 2026-09-27, KXEARNINGSMENTIONARITZIA-26OCT14).
# An earnings-mention market is a "next earnings call" contract expiring Dec
# 31, so the listing-date rule above ALWAYS fired for it (the comment above
# once assumed earnings sat under the gap bar) and every event with no
# event_start_overrides entry was quoted to Dec 31 -- through its call, with
# nothing else standing it down. ARITZIA (not on Nasdaq's calendar,
# JavaScript-only IR page) sat that way for two weeks: call Oct 8 16:30 ET,
# ticker date Oct 14. The ticker date is Kalshi's GUESS at the call and has
# run late by up to 6 days (ARITZIA +6, LLY +2, DELL +2), so an undated event
# stands down this many days BEFORE it. imm_earnings_overrides.py dates events
# from the company's own announcement (IR event feed, press releases) and the
# Nasdaq calendar; this lead is only what applies when all of those miss.
# 0 restores the midnight-of-ticker-date rule the resolver always assumed.
EARNINGS_UNDATED_LEAD_DAYS = _env_float("IMM_EARNINGS_UNDATED_LEAD_DAYS", 14)


def ticker_date_is_listing_date(event_ticker: str, td: datetime,
                                expected_expiration: Optional[datetime]) -> bool:
    """True when a mention-family ticker's date segment is the day Kalshi
    LISTED the event rather than the day it resolves — the signal that td
    must not become a trade cutoff. No expiration to compare against means
    no proof: keep the conservative reading. Never for earnings mentions:
    their Dec 31 expiration is the contract's, not the event's."""
    series = series_of(event_ticker)
    return ("MENTION" in series
            and not series.startswith(_EARNINGS_PREFIX)
            and expected_expiration is not None
            and expected_expiration - td > timedelta(days=MENTION_LISTING_GAP_DAYS))


def trade_cutoff_utc(event_ticker: str, occurrence: Optional[datetime],
                     expected_expiration: Optional[datetime]) -> Optional[datetime]:
    """When we must be OUT of this market. Ticker-embedded event dates cut off
    at ET midnight day-of (most conservative reading — kickoff hour isn't in
    the API), EXCEPT mention-family tickers whose expiration proves the date
    is a listing date (see ticker_date_is_listing_date) — those quote the
    whole listing window and cut off at expiration. An occurrence_datetime
    meaningfully before expiration marks a scheduled underlying event
    (earnings report, game) — cut off there too.
    None = no known event start; breakers are the only protection.

    Earnings mentions: the override when one exists (the orphan-restore path
    calls this without consulting the resolver, and its reduce-only wind-down
    must run to the real call, not stop 14 days early), else the ticker date
    minus EARNINGS_UNDATED_LEAD_DAYS."""
    candidates = []
    td = parse_event_date(event_ticker)
    if series_of(event_ticker).startswith(_EARNINGS_PREFIX):
        start = EVENT_START_OVERRIDES.get(event_ticker)
        if start is not None:
            candidates.append(start - timedelta(minutes=OVERRIDE_BUFFER_MIN))
            td = None
        elif td is not None:
            td = td - timedelta(days=EARNINGS_UNDATED_LEAD_DAYS)
    if td is not None and ticker_date_is_listing_date(event_ticker, td,
                                                      expected_expiration):
        # The whole listing window is the quotable period: be out at
        # expiration. NOT None — a cutoff-less mention-family market trips
        # _screen()'s no_event_window stand-down (that rule targets
        # tournament-wide tickers with no date segment at all), which is
        # exactly where the 26AUG13/26AUG14 events landed on the first
        # post-fix cycle. An occurrence, if Kalshi ever sets one, still
        # wins the min() below.
        candidates.append(expected_expiration)
        td = None
    if td is not None:
        # EVENT-DAY EXTENDER (Jack 2026-08-04: "quote treasuries until 7:30am
        # EST"). Midnight is the right default for a market with a scheduled
        # RELEASE — be gone before the day the number drops. A Treasury yield
        # is not that: the underlying is continuously priced in a deep market
        # and the contract is a 3:30pm ET snapshot of it, so 00:00-07:30 ET is
        # no more informed than the evening before, while 07:30 puts the bot
        # out ahead of the 08:30 releases that DO move rates.
        #
        # It shifts the ticker-date CANDIDATE, deliberately, rather than the
        # finished cutoff: min() below then still lets a real
        # occurrence_datetime win, which a post-hoc adjustment could not do.
        # A caller that skips this function keeps midnight — failing toward
        # quoting LESS, which is the safe direction for a missed rule.
        ov = SERIES_OVERRIDES.get(series_of(event_ticker))
        if ov and ov.event_day_cutoff_et is not None:
            hh, mm = ov.event_day_cutoff_et
            td = td + timedelta(hours=hh, minutes=mm)
            if expected_expiration is not None:
                td = min(td, expected_expiration)
        candidates.append(td)
    if (occurrence is not None and expected_expiration is not None
            and occurrence < expected_expiration - timedelta(minutes=60)):
        candidates.append(occurrence)
    elif occurrence is not None and expected_expiration is None:
        candidates.append(occurrence)
    return min(candidates) if candidates else None


# ----------------------------------------------------------------------------
# Price/book helpers (same conventions as the crypto MM: YES-book cents)
# ----------------------------------------------------------------------------

def dollars_to_cents(v) -> Optional[int]:
    try:
        c = round(float(v) * 100)
    except (TypeError, ValueError):
        return None
    return c if 0 <= c <= 100 else None


# ---- SUB-PENNY CENT BUCKETS (Jack 2026-09-26, "yes" to making the estimator
# sub-penny aware). The sports escalators trade in 0.0001 steps; the whole
# bot reasons in whole cents, and it used to ROUND every price to the penny.
# Rounding put a 0.1940 bid and a 0.1960 ask in the SAME cent (19/19): no
# integer bid can rest below the ask, so no ladder, est $0.00, 157-160
# "zero_yield" skips per refresh -- while the sub-penny join can only move a
# rung that was already built. The convention is now FLOOR for bids and
# CEIL for asks (a NO level is floored in NO terms, which is the YES ask
# ceiled): the integer touch is never better than the true touch, so an
# integer bid never crosses the true ask, and any sub-cent spread survives
# as a >= 1c integer spread. 19.40 / 19.60 reads 19 / 20; the ordinary
# pipeline builds 19 / 20 and subpenny_snap (same buckets) rests them at
# 19.40 / 19.60 exactly. Whole-cent prices are unchanged (floor == ceil ==
# round). Levels that share a cent are MERGED (sizes summed) -- the share
# model keyed on integer prices used to keep only the last of them.
def _floor_cents(p) -> int:
    """Dollars -> whole cents, floored (0.1940 -> 19; 0.29 -> 29: the round to
    4 dp + 1e-9 absorbs 0.29 * 100 == 28.999...)."""
    return int(math.floor(round(float(p) * 100, 4) + 1e-9))


def _ceil_cents(p) -> int:
    """Dollars -> whole cents, ceiled (0.1960 -> 20; 0.19 -> 19)."""
    return int(math.ceil(round(float(p) * 100, 4) - 1e-9))


def _merge_levels(pairs) -> List[List[float]]:
    """[[cents, qty]] ascending with equal cents merged (sizes summed)."""
    acc: Dict[int, float] = {}
    for c, q in pairs:
        acc[c] = acc.get(c, 0.0) + q
    return [[c, acc[c]] for c in sorted(acc)]


def market_cents(m: dict, base: str) -> Optional[int]:
    """Read a price off a market object: prefers '<base>_dollars' (V2 string),
    falls back to legacy integer-cent '<base>'. Returns None when absent or 0
    (Kalshi reports an empty BID as 0). An empty ASK is NOT 0: Kalshi reports
    it as $1.00, and this returns it as 100. The quoting callers rely on that
    (a 100c ask is outside every band, so a no-offer book reads as wide or out
    of band), but a 100c ask is not a price: anything that VALUES a position
    takes its touch from yes_touch_cents / bulk_mark_cents. Sub-penny aware: a
    *_bid is floored to the cent, a *_ask ceiled (see _floor_cents)."""
    v = m.get(base + "_dollars")
    c = None
    if v is not None:
        try:
            c = _ceil_cents(v) if base.endswith("_ask") else _floor_cents(v)
        except (TypeError, ValueError):
            c = None
        if c is not None and not (0 <= c <= 100):
            c = None
    if c is None:
        v = m.get(base)
        try:
            c = int(v) if v is not None else None
        except (TypeError, ValueError):
            c = None
    return c if c else None   # 0 == side absent


def _side_live(m: dict, base: str) -> bool:
    """True when the market object shows a real resting level on this side.
    Kalshi reads an empty YES bid as $0 and an empty YES ask as $1.00, and
    nobody can trade at either, so only a raw price strictly inside (0, 1) is a
    side. Read raw rather than through market_cents, whose ceil turns a real
    $0.9999 escalator offer into the same 100 as the placeholder."""
    v = m.get(base + "_dollars")
    if v is not None:
        try:
            return 0.0 < float(v) < 1.0
        except (TypeError, ValueError):
            pass
    v = m.get(base)
    try:
        return v is not None and 0 < float(v) < 100
    except (TypeError, ValueError):
        return False


def yes_touch_cents(m: dict) -> Tuple[Optional[int], Optional[int]]:
    """(bid, ask) in whole cents off a market object, with None for an EMPTY
    side: the market_cents convention (bid floored, ask ceiled), minus Kalshi's
    $0 / $1.00 placeholders."""
    bid = market_cents(m, "yes_bid") if _side_live(m, "yes_bid") else None
    ask = market_cents(m, "yes_ask") if _side_live(m, "yes_ask") else None
    return bid, ask


def wide_mark_book(bid: Optional[int], ask: Optional[int]) -> bool:
    """A two-sided touch too wide for its mid to be a mark
    (MARK_WIDE_SPREAD_CENTS; never when that is 0)."""
    return (MARK_WIDE_SPREAD_CENTS > 0 and bid is not None and ask is not None
            and ask - bid >= MARK_WIDE_SPREAD_CENTS)


def touch_mark_cents(bid: Optional[int], ask: Optional[int],
                     last: Optional[int]) -> Optional[float]:
    """The YES mark (cents) for a touch (None = an EMPTY side) and the last
    trade (None = never traded), or None when nothing in it is usable.

    Two-sided: the mid -- unless the book is MARK_WIDE_SPREAD_CENTS or wider,
    then the last trade clamped inside the touch. One-sided: the LAST TRADE
    clamped to the live side -- max(last, bid) with only a bid, min(last, ask)
    with only an offer. A missing side is never a price. Until 2026-10-01 the
    bulk refresh averaged in the empty ask's $1.00 placeholder:
    KXDDCOLDBREW-26OCT02-T4.45 (bot short 58.64 @ 91.5c) marked 52.5 =
    (5 + 100) / 2 at the 10/1 ET midnight on a stray 5c bid with no offer,
    against a last trade of 97 and a YES settlement; KXSBUXSAR-26OCT02-T5.08
    sat at 64.5-66 for ~35h the same way (last trade 96). Both sides empty (a
    closed or settled book reads 0 / 100): the last trade, as before."""
    if bid is not None and ask is not None:
        if last is not None and wide_mark_book(bid, ask):
            return float(min(max(last, bid), ask))
        return (bid + ask) / 2.0
    if last is None:
        return None
    if bid is not None:
        return float(max(last, bid))
    if ask is not None:
        return float(min(last, ask))
    return float(last)


def bulk_mark_cents(m: dict,
                    touch: Optional[Tuple[Optional[int], Optional[int]]] = None
                    ) -> Optional[float]:
    """The YES mark (cents) of a held position off a bulk market read -- the
    touch_mark_cents rule on the market's touch and last trade -- or None when
    the read carries no usable price (the caller keeps its previous mark).
    `touch` overrides the market object's touch with the EXTERNAL (bid, ask)
    of a market whose order book was read this cycle: Kalshi's touch includes
    our own resting quotes, which are no price for our own position."""
    bid, ask = yes_touch_cents(m) if touch is None else touch
    return touch_mark_cents(bid, ask, market_cents(m, "last_price"))


# Market statuses at which Kalshi has paid a settlement out ("settled" is the
# older API's name for "finalized").
SETTLED_STATUSES = ("finalized", "settled")


def settlement_value_cents(m: dict) -> Optional[float]:
    """The YES payout of a settled market in cents, read exactly from
    settlement_value_dollars -- a scalar escalator pays "0.2160" = 21.6c, so
    this is never rounded to the penny (dollars_to_cents would say 22).
    None when absent, unparseable or outside 0-100."""
    try:
        c = round(float(m.get("settlement_value_dollars")) * 100.0, 4)
    except (TypeError, ValueError):
        return None
    return c if 0.0 <= c <= 100.0 else None


def orderbook_levels(orderbook_response: dict) -> Tuple[List[List[float]], List[List[float]]]:
    """(yes_levels, no_levels) as [price_cents, qty], ascending by price.
    Sub-penny aware (2026-09-26): each book's prices are FLOORED to the cent
    in their own terms -- a YES bid down, a NO bid down, which is the YES ask
    UP -- so a 0.1940 / 0.1960 escalator reads bid 19 / ask 20 instead of a
    locked 19 / 19, and levels sharing a cent are merged (sizes summed).
    Whole-cent books are unchanged."""
    yes_levels: List[List[float]] = []
    no_levels: List[List[float]] = []
    if "orderbook_fp" in orderbook_response:
        ob = orderbook_response.get("orderbook_fp") or {}
        yes_levels = _merge_levels((_floor_cents(p), float(q)) for p, q in (ob.get("yes_dollars") or []))
        no_levels = _merge_levels((_floor_cents(p), float(q)) for p, q in (ob.get("no_dollars") or []))
    elif "orderbook" in orderbook_response:
        ob = orderbook_response.get("orderbook") or {}
        yes_levels = [[float(p), float(q)] for p, q in (ob.get("yes") or [])]
        no_levels = [[float(p), float(q)] for p, q in (ob.get("no") or [])]
    return yes_levels, no_levels


# ---- SUB-PENNY JOIN (Jack 2026-09-26: "allow for quoting within a cent if it
# means staying in the earnings range. e.g. KXNFLESCALATORREC-26SEP27NYJDET-
# DETASTBROWN14"). The sports ladders / escalators are priced in 0.0001
# steps (price_level_structure center_centi_edge_centi_cent). The bot reasons
# in whole cents: orderbook_levels rounds the book to the penny and the
# ladder rests on the penny grid -- so on DETASTBROWN14 the true bid was
# 0.1915 (13,192 contracts) and the ask 0.1970, the bot read 19/20 and rested
# 0.1900 / 0.2000, a fraction of a cent BEHIND both touches. Kalshi scores
# the first 1,000 contracts from the best price, all of them at the maker's
# 0.1915 level, so a 0.1900 order is not in the scored range at all. The fix
# keeps every integer-cent decision as it is and, for a market whose
# price_step is finer than a cent, snaps each rung to the most aggressive
# EXTERNAL level inside the rung's own cent bucket (the level the integer
# logic meant to join): bid 19 -> 19.15, ask 20 -> 19.70. Never crosses (the
# snapped bid stays under the exact external ask and vice versa), never moves
# a rung outside its bucket ("within a cent"), never invents a price (it only
# joins a level that already exists on the grid), pads untouched, our own
# resting size netted out so we never chase ourselves. Exact rungs match
# resting orders by their 4-decimal price (diff_orders), so a moved touch
# gets a cancel + fresh place, never an amend. IMM_SUBPENNY_JOIN=0 = off.
SUBPENNY_JOIN = os.environ.get("IMM_SUBPENNY_JOIN", "1") == "1"


def market_price_step(m: Optional[dict]) -> float:
    """Kalshi price granularity in dollars from a market object: the finest
    `price_ranges[].step`, else 0.001 when the level structure names centi
    ticks, else the penny grid."""
    steps = []
    for r in (m or {}).get("price_ranges") or []:
        try:
            steps.append(float((r or {}).get("step")))
        except (TypeError, ValueError, AttributeError):
            continue
    steps = [s for s in steps if s > 0]
    if steps:
        return max(min(steps), 0.0001)
    if "centi" in str((m or {}).get("price_level_structure") or "").lower():
        return 0.001
    return 0.01


def orderbook_exact_levels(orderbook_response: dict
                           ) -> Tuple[List[List[float]], List[List[float]]]:
    """(yes_levels, no_levels) as [price_cents_2dp, qty], ascending, keeping
    the sub-penny precision orderbook_levels rounds away (V2 dollars only)."""
    ob = orderbook_response.get("orderbook_fp") or {}
    yes_levels = [[round(float(p) * 100, 2), float(q)] for p, q in (ob.get("yes_dollars") or [])]
    no_levels = [[round(float(p) * 100, 2), float(q)] for p, q in (ob.get("no_dollars") or [])]
    return yes_levels, no_levels


def order_yes_exact_cents(order: dict) -> Optional[float]:
    """A resting order's YES price in cents at sub-penny precision (19.15):
    the bot's own ledger/sim `yes_price_exact`, else the exchange's 4-decimal
    dollar fields. None when the order carries only an integer price."""
    v = order.get("yes_price_exact")
    if v is not None:
        try:
            return round(float(v), 2)
        except (TypeError, ValueError):
            pass
    for key in ("yes_price_dollars", "price_dollars"):
        v = order.get(key)
        if v is not None:
            try:
                return round(float(v) * 100, 2)
            except (TypeError, ValueError):
                return None
    v = order.get("no_price_dollars")
    if v is not None:
        try:
            return round(100 - float(v) * 100, 2)
        except (TypeError, ValueError):
            return None
    return None


def subpenny_snap(quotes: List["Quote"], yes_exact: List[List[float]],
                  no_exact: List[List[float]],
                  own_exact: List[Tuple[str, float, float]] = ()) -> List["Quote"]:
    """Snap each non-pad rung to the most aggressive EXTERNAL level inside its
    own cent bucket. yes_exact/no_exact from orderbook_exact_levels (cents,
    2 dp); own_exact = (book_side, yes_cents_2dp, remaining) of our resting
    orders, netted out first. A rung whose bucket holds no external level
    keeps its integer price (it is already the best in that cent). Buckets
    follow orderbook_levels: a bid level belongs to floor(price), an ask
    level to ceil(price) -- so the 19 / 20 rungs the integer pipeline builds
    on a 19.40 / 19.60 escalator snap to 19.40 / 19.60 exactly."""
    if not quotes:
        return quotes
    own_yes: Dict[float, float] = {}
    own_no: Dict[float, float] = {}
    for bs, px, rem in own_exact:
        if bs == "bid":
            own_yes[px] = own_yes.get(px, 0.0) + rem
        else:
            k = round(100 - px, 2)
            own_no[k] = own_no.get(k, 0.0) + rem
    bids = [(px, q - own_yes.get(px, 0.0)) for px, q in yes_exact]
    bids = [(px, q) for px, q in bids if q > 1e-9]
    asks = [(round(100 - px, 2), q - own_no.get(px, 0.0)) for px, q in no_exact]
    asks = [(px, q) for px, q in asks if q > 1e-9]
    best_bid = max((px for px, _q in bids), default=None)
    best_ask = min((px for px, _q in asks), default=None)
    out: List[Quote] = []
    for q in quotes:
        if getattr(q, "is_pad", False) or q.price_exact is not None:
            out.append(q)
            continue
        exact = None
        if q.book_side == "bid":
            cands = [px for px, _q in bids if int(math.floor(px + 1e-9)) == q.price_cents]
            if cands:
                exact = max(cands)
                if best_ask is not None and exact >= best_ask:
                    exact = None                       # would cross: keep the cent
        else:
            cands = [px for px, _q in asks if int(math.ceil(px - 1e-9)) == q.price_cents]
            if cands:
                exact = min(cands)
                if best_bid is not None and exact <= best_bid:
                    exact = None
        if exact is None or abs(exact - q.price_cents) < 0.005:
            out.append(q)
        else:
            out.append(replace(q, price_exact=exact))
    return out


def external_best(yes_levels: List[List[float]], no_levels: List[List[float]],
                  own_orders: List[Tuple[str, int, float]] = ()
                  ) -> Tuple[Optional[int], Optional[int]]:
    """(best_yes_bid, best_yes_ask) in cents EXCLUDING our own resting orders
    given as (book_side, yes_price_cents, remaining). Our asks rest on the NO
    book at (100 - yes_price)."""
    own_yes: Dict[int, float] = {}
    own_no: Dict[int, float] = {}
    for book_side, yes_px, remaining in own_orders:
        if book_side == "bid":
            own_yes[yes_px] = own_yes.get(yes_px, 0.0) + remaining
        else:
            own_no[100 - yes_px] = own_no.get(100 - yes_px, 0.0) + remaining

    def best(levels: List[List[float]], own: Dict[int, float]) -> Optional[int]:
        for px, qty in reversed(levels):
            if qty - own.get(int(px), 0.0) > 0.01:
                return int(px)
        return None

    best_yes_bid = best(yes_levels, own_yes)
    best_no_bid = best(no_levels, own_no)
    best_yes_ask = (100 - best_no_bid) if best_no_bid is not None else None
    return best_yes_bid, best_yes_ask


def external_depths(yes_levels: List[List[float]], no_levels: List[List[float]],
                    own_orders: List[Tuple[str, int, float]] = ()
                    ) -> Tuple[float, float]:
    """(yes_depth, no_depth) in contracts EXCLUDING our own resting orders
    (same own-order tuples as external_best). The live-event depth gate must
    measure the EXTERNAL book: the signal is everyone else pulling out, and
    our own ladder — or a legacy 1k pad still resting through the config
    change — would otherwise hold the reading over the bar forever."""
    own_yes = sum(r for s, _px, r in own_orders if s == "bid")
    own_no = sum(r for s, _px, r in own_orders if s != "bid")
    d_yes = sum(q for _px, q in yes_levels) - own_yes
    d_no = sum(q for _px, q in no_levels) - own_no
    return max(d_yes, 0.0), max(d_no, 0.0)


def external_levels(yes_levels: List[List[float]], no_levels: List[List[float]],
                    own_orders: List[Tuple[str, int, float]]
                    ) -> Tuple[List[List[float]], List[List[float]]]:
    """The book WITHOUT our own resting orders, level by level (a bid rests
    on the YES side at its price; an ask is a NO bid at 100 - price). Sizes
    clamp at zero and emptied levels drop, so the result can be re-overlaid
    with estimate_reward_share(own_in_book=False). Feeds the day-size floor
    projection for an incumbent (FLOOR_PROJECTION_BASE_SIZE, 2026-09-25)."""
    own_yes: Dict[int, float] = {}
    own_no: Dict[int, float] = {}
    for book_side, yes_px, remaining in own_orders:
        if book_side == "bid":
            own_yes[int(yes_px)] = own_yes.get(int(yes_px), 0.0) + float(remaining)
        else:
            own_no[100 - int(yes_px)] = (own_no.get(100 - int(yes_px), 0.0)
                                         + float(remaining))

    def strip(levels: List[List[float]], own: Dict[int, float]) -> List[List[float]]:
        out: List[List[float]] = []
        for px, q in levels:
            q2 = float(q) - own.get(int(px), 0.0)
            if q2 > 1e-9:
                out.append([px, q2])
        return out
    return strip(yes_levels, own_yes), strip(no_levels, own_no)


def order_yes_book_cents(order: dict) -> Optional[Tuple[str, int]]:
    """(book_side, yes_price_cents) from a normalized V2 order dict."""
    book_side = order.get("book_side")
    if book_side not in ("bid", "ask"):
        side, action = order.get("side"), order.get("action")
        if side in ("yes", "no") and action in ("buy", "sell"):
            book_side = "bid" if (side == "yes") == (action == "buy") else "ask"
        else:
            return None
    # sub-penny aware (2026-09-26): the same cent buckets as orderbook_levels
    # -- a bid's YES price floored, an ask's ceiled (= its NO price floored)
    for key in ("price_dollars", "yes_price_dollars"):
        v = order.get(key)
        if v is not None:
            return book_side, (_floor_cents(v) if book_side == "bid" else _ceil_cents(v))
    if order.get("yes_price") is not None:
        return book_side, int(order["yes_price"])
    if order.get("no_price_dollars") is not None:
        v = order["no_price_dollars"]
        return book_side, 100 - (_ceil_cents(v) if book_side == "bid" else _floor_cents(v))
    if order.get("no_price") is not None:
        return book_side, 100 - int(order["no_price"])
    return None


def order_remaining(order: dict) -> float:
    for key in ("remaining_count", "remaining_count_fp", "count"):
        v = order.get(key)
        if v is not None:
            try:
                return float(v)
            except (TypeError, ValueError):
                pass
    return 0.0


# ----------------------------------------------------------------------------
# Reward-share estimator (implements the program's snapshot scoring)
# ----------------------------------------------------------------------------

def levels_desc(levels: List[List[float]]) -> List[Tuple[int, float]]:
    """Orderbook side -> (price_cents, size) best price first (highest first;
    both YES-bid and NO-bid books quote their own price space)."""
    by: Dict[int, float] = {}
    for px, q in levels:
        by[int(px)] = by.get(int(px), 0.0) + float(q)
    return sorted(by.items(), key=lambda kv: -kv[0])


def side_reference_level(levels_best_first: List[Tuple[int, float]],
                         target: float) -> Optional[int]:
    """Post-2026-07-30 reference price for one side: the first level, best
    price first, where cumulative size reaches target/5. None if the walk
    never gets there (side can't qualify without more depth). Placing our
    own size AT the returned level cannot move the reference (levels above
    it are untouched), so it is a stable full-weight placement."""
    if target <= 0:
        return None
    cum = 0.0
    for px, size in levels_best_first:
        cum += size
        if cum >= target / 5.0:
            return px
    return None


def ladder_reference_prices(yes_levels: List[List[float]],
                            no_levels: List[List[float]],
                            target: float) -> Tuple[Optional[int], Optional[int]]:
    """(bid ref in YES cents, ask ref in YES-ASK cents) for atref placement;
    (None, None) when the mode is off or a side has no reference."""
    if LADDER_MODE != "atref" or target <= 0:
        return None, None
    rb = side_reference_level(levels_desc(yes_levels), target)
    rn = side_reference_level(levels_desc(no_levels), target)
    return rb, (100 - rn) if rn is not None else None


# LONE-REFERENCE GUARD (2026-10-16, after the League of Legends Worlds props
# were baited). Under LADDER_MODE atref a side rests AT Kalshi's reward
# reference: the first level, best first, where the cumulative size reaches
# target/5. One order of target/5 contracts inside a wide spread therefore IS
# our price. On 10/16 03:01-03:43Z a 200-lot (target 1000) walked the
# KXLOLTEEMO / KXLOLTOURPENTA references from 2-10c up to 62-93c within
# minutes. The bot followed each step. A seller then sold exactly our size 16
# times, while the 200-lot ahead of us was pulled before each hit: about -$275
# at mid for $0.34 of reward. Safe-join cannot help, since it is capped at the
# reference.
# A side TRIPS (lone_ref_trip) when all three hold:
#   * its EXTERNAL reference (our own orders netted out) rests on a thin top,
#     i.e. the external size at or above it is under LONE_REF_MAX_MULT x
#     target/5;
#   * where the side would rest sits >= LONE_REF_MIN_GAP_C above the
#     reference the rest of the external book sets (0 when that never
#     reaches target/5);
#   * our rung got there by a jump: within the last LONE_REF_JUMP_WINDOW_MIN
#     minutes it rested >= LONE_REF_MIN_GAP_C lower, or there was no rung on
#     that side at all (a window of 0 drops this test).
# A rung that has rested at its price for the whole window is left alone. A
# side the guard holds out has no rung, so it stays out while the thin top
# lasts. The mention books (LONE_REF_SKIP) have their own live gates and are
# not checked; nor, since 2026-10-18, are markets with a fair gate
# (LONE_REF_SKIP_FAIR).
# Measured on 9/30-10/16 (41M book snapshots replayed, the bot's own share
# model, fills at the dashboard's 4h markout), mention books out:
#   * these defaults (x3, 20c, 60 min) give up ~$21/day of reward and avoid
#     ~$48/day of fills, net ~+$27/day (+$13/day without 10/16);
#   * x1.5 gives up ~$7/day for ~+$22/day net;
#   * every rule WITHOUT the jump test loses (x3 20c: -$18/day).
# IMM_LONE_REF_GUARD (on 2026-10-16, Jack: "Ship the lone-reference guard on
# at x3 / 20c / 60 min with mention books skipped"; DRY since 2026-10-22,
# Jack: "Build it and put guard on dry mode" -- live it read -$140 over 5.5
# days, $103 of it one news fill it kept us out of, against the replay's
# +$34/day; the bait-fingerprint stop below now covers the LoL repeat):
#   "on"  stands a tripped side aside: no rungs that cycle, and the requote
#         cancels the resting ones;
#   "dry" logs each trip (its rung still follows the top, so dry shows where
#         trips start, not how long "on" would hold);
#   "off" skips the check.
# A bait stop turns it ON for the stopped market's event until ET midnight.
LONE_REF_GUARD_MODE = os.environ.get("IMM_LONE_REF_GUARD", "dry").strip().lower()
LONE_REF_MAX_MULT = _env_float("IMM_LONE_REF_MAX_MULT", 3.0)
LONE_REF_MIN_GAP_C = _env_int("IMM_LONE_REF_MIN_GAP_C", 20)
LONE_REF_JUMP_WINDOW_MIN = _env_int("IMM_LONE_REF_JUMP_WINDOW_MIN", 60)
LONE_REF_SKIP: Tuple[str, ...] = tuple(
    p.strip() for p in os.environ.get("IMM_LONE_REF_SKIP", "MENTION").split(",")
    if p.strip())
# FAIR-GATED MARKETS LEFT OUT (Jack 2026-10-18: "Build it", to "Take
# fair-gated markets out of the lone-ref guard?"). Where a quote-loop fair
# gate bounds the quote (fair_gate_of), one lone order cannot pull the side
# past our own fair value, so a hold there only blocks fills the model wants.
# Live 10/16-17 the guard netted -$78, all of it fair-gated (weekend rain
# -$66, quake -$19: fills it blocked that the rain and the missing quake made
# good); markets with no fair value made +$7.5. In the 17-day replay the
# fair-gated value was OpenRouter share (+$86; the family is off since 10/09)
# and Rotten Tomatoes' 10/15 first reviews (+$81; the RT gate stands those
# aside since 10/16); the other gates netted -$0.26/day at 4h. The replay's
# no-fair-value markets: +$17.44/day. IMM_LONE_REF_SKIP_FAIR=0 checks the
# fair-gated markets again.
LONE_REF_SKIP_FAIR = os.environ.get("IMM_LONE_REF_SKIP_FAIR", "1") == "1"


def fair_gate_of(series: str) -> str:
    """The fair gate the quote loop runs on this series ('' = none): its own
    series checks, in the quote loop's terms. The lone-ref guard leaves these
    out (LONE_REF_SKIP_FAIR) and send_lone_ref_monitor.py classes its holds
    by them. A check that raises reads as no gate."""
    t = series + "-X"
    checks = (
        ("carbon arc", lambda: CA_FAIR_ENABLE and carbon_arc_settled(series)),
        ("openrouter tokens", lambda: OR_FAIR_ENABLE and series in OR_FAIR_SERIES),
        ("openrouter share", lambda: share_fair_series(series)),
        ("rain monthly", lambda: rain_monthly_series(series)),
        ("rain period", lambda: rain_period_gated(t)),
        ("snow monthly", lambda: snow_monthly_series(series)),
        ("resort snow", lambda: resort_snow_series(series)),
        ("broadway", lambda: bway_fair_series(series)),
        ("rcp approval", lambda: approve_fair_series(series)),
        ("trump mention", lambda: tmention_fair_series(series)),
        ("ercot peak", lambda: ercot_fair_series(series)),
        ("cpi", lambda: cpi_fair_series(series)),
        ("rain weekend", lambda: rain_wknd_series(series)),
        ("rotten tomatoes", lambda: rt_fair_series(series)),
        ("gasbuddy", lambda: GB_FAIR_ENABLE and gb_fair_series(series)),
        ("datacenter", lambda: DC_GATE_ENABLE and datacenter_series(series)),
        ("quake", lambda: quake_gated(series)),
        ("vercel", lambda: vercel_series(series)),
        ("yt2", lambda: yt2_series(series)),
        ("yt weekly", lambda: ytw_series(series)),
        ("yt1", lambda: yt1_series(series)),
        ("treasury", lambda: treasury_gated_series(series)),
        ("mortgage", lambda: mort_series(series)),
        ("pokemon", lambda: poke_series(series)),
        ("nfl props", lambda: nfl_series(series)),
    )
    for name, hit in checks:
        try:
            if hit():
                return name
        except Exception:
            continue
    return ""


_fair_gate_memo: Dict[str, str] = {}
_fair_gate_memo_at = [0.0]


def fair_gate_cached(series: str) -> str:
    """fair_gate_of, remembered for 10 minutes (the gates' series lists are
    hot-reloaded files)."""
    now = time.time()
    if now - _fair_gate_memo_at[0] > 600:
        _fair_gate_memo.clear()
        _fair_gate_memo_at[0] = now
    g = _fair_gate_memo.get(series)
    if g is None:
        g = _fair_gate_memo[series] = fair_gate_of(series)
    return g


def lone_ref_series(series: str) -> bool:
    """Is this series checked by the lone-reference guard? Not the
    LONE_REF_SKIP name parts (the mention books), nor, while
    LONE_REF_SKIP_FAIR, a series with a quote-loop fair gate."""
    if any(p in series for p in LONE_REF_SKIP):
        return False
    return not (LONE_REF_SKIP_FAIR and fair_gate_cached(series))


# BAIT-FINGERPRINT STOP (2026-10-22, Jack: "Build it and put guard on dry
# mode", after a replay of three fixes for the 10/16 LoL bait). One of our
# maker fills that took the WHOLE rung on a side the lone-reference test
# flags (lone_ref_trip: a thin top >= LONE_REF_MIN_GAP_C over the rest of
# the book that our rung jumped to), where the taker's order on Kalshi's
# public tape was exactly our size -- the LoL seller sold exactly our size
# 14 of 16 times while the order ahead of us was pulled -- stops that side
# of that market until ET midnight, and turns the lone-ref guard ON for the
# market's event until then whatever LONE_REF_GUARD_MODE says. Real flow
# trades the order ahead of us first, so its taker is bigger than our rung.
# Replay 9/30-10/16 (475 thin-top fills, Kalshi's public tape, marked to
# settlement):
#   * 28 fingerprints, -$10.45 a fill (whole-rung jumped fills with a bigger
#     taker: -$4.4); 12 of the 28 were the LoL night;
#   * a side out for the day after each: 20 sides, 18 later fills prevented
#     (-$151, LoL -$146) for ~$9 of reward: net +$142 over 17 days;
#   * the event-wide guard adds ~$46 on the LoL pentakill strikes.
# Rejected the same day: a 2nd sweep within 30 min -> side out for the day
# (net -$172: it stopped real repricing), and a 1/4-size taper on jumps (a
# smaller guard, ~+$25/day against the guard's +$34/day).
# The tape is read once per candidate -- a whole-rung fill on a flagged side,
# ~11/day in the replay -- BAIT_TAPE_DELAY_SECS after the fill, retried for
# BAIT_TAPE_MAX_TRIES cycles while our print is not on it yet. The mention
# books (BAIT_STOP_SKIP) keep their own live gates and toxic-halt exemption.
# IMM_BAIT_STOP: "on" (default), "dry" (logged, nothing stopped), "off".
BAIT_STOP_MODE = os.environ.get("IMM_BAIT_STOP", "on").strip().lower()
BAIT_STOP_SKIP: Tuple[str, ...] = tuple(
    p.strip() for p in os.environ.get("IMM_BAIT_STOP_SKIP", "MENTION").split(",")
    if p.strip())
BAIT_TAPE_DELAY_SECS = _env_float("IMM_BAIT_TAPE_DELAY_SECS", 5.0)
BAIT_TAPE_MAX_TRIES = _env_int("IMM_BAIT_TAPE_MAX_TRIES", 6)


def bait_series(series: str) -> bool:
    """Is this series watched by the bait-fingerprint stop? Every series but
    the BAIT_STOP_SKIP name parts (the mention books), fair-gated ones
    included (the replay's fingerprints had KXTOKENUSE and CPI fills)."""
    return BAIT_STOP_MODE in ("on", "dry") and \
        not any(p in series for p in BAIT_STOP_SKIP)


def _trade_count(tr: dict) -> float:
    raw = tr.get("count_fp")
    return float(raw if raw not in (None, "") else (tr.get("count") or 0.0))


def bait_fingerprint(trades: List[dict], trade_id: str,
                     count: float) -> Optional[bool]:
    """The fingerprint on Kalshi's public tape around one of our fills: True
    when the taker order behind our print `trade_id` was exactly our `count`
    (the prints with our print's created_time and taker_side sum to it),
    False when that order was bigger, None when our print is not on the
    tape (yet)."""
    ours = next((x for x in trades if str(x.get("trade_id") or "") == trade_id), None)
    if ours is None:
        return None
    ct, side = ours.get("created_time"), ours.get("taker_side")
    total = sum(_trade_count(x) for x in trades
                if x.get("created_time") == ct and x.get("taker_side") == side)
    return abs(total - float(count)) < 0.5


def et_day_end_ts(ts: float) -> float:
    """The epoch of the first ET midnight after `ts`."""
    d = datetime.fromtimestamp(ts, timezone.utc).astimezone(ET).date()
    return ET.localize(datetime(d.year, d.month, d.day) + timedelta(days=1)).timestamp()


def lone_reference(ext_levels_best_first: List[Tuple[int, float]], target: float,
                   max_mult: Optional[float] = None
                   ) -> Optional[Tuple[int, float, int]]:
    """(reference, top size, rest reference) when one side's EXTERNAL reward
    reference rests on a thin top -- external size at or above it under
    max_mult x target/5 -- else None. The rest reference is the one the
    external levels below the thin top set (0 when they never reach
    target/5). One side, own price space, best price first."""
    if max_mult is None:
        max_mult = LONE_REF_MAX_MULT
    ref = side_reference_level(ext_levels_best_first, target)
    if ref is None:
        return None
    top = sum(q for p, q in ext_levels_best_first if p >= ref)
    if top >= max_mult * target / 5.0:
        return None
    rest = side_reference_level([(p, q) for p, q in ext_levels_best_first
                                 if p < ref], target)
    return ref, top, (rest if rest is not None else 0)


def lone_ref_trip(ext_levels_best_first: List[Tuple[int, float]], target: float,
                  rest_px: Optional[int], rung_window: Optional[List[int]],
                  max_mult: Optional[float] = None,
                  min_gap: Optional[int] = None) -> Optional[dict]:
    """The lone-reference guard's verdict for one side (see
    LONE_REF_GUARD_MODE): None when it does not trip, else {ref, top, rest,
    jump}. `rest_px` is where the side would rest and `rung_window` the
    prices our rung on that side rested at within the jump window ([] = no
    rung there, None = no jump test), all in the side's own price space (YES
    cents for a bid, NO cents for an ask). `jump` is None for a fresh rung
    and 0 without a jump test."""
    if max_mult is None:
        max_mult = LONE_REF_MAX_MULT
    if min_gap is None:
        min_gap = LONE_REF_MIN_GAP_C
    if rest_px is None or target <= 0:
        return None
    lr = lone_reference(ext_levels_best_first, target, max_mult)
    if lr is None:
        return None
    ref, top, rest = lr
    if rest_px < rest + min_gap:
        return None
    if rung_window is None:
        jump: Optional[int] = 0
    elif not rung_window:
        jump = None
    else:
        jump = rest_px - min(rung_window)
        if jump < min_gap:
            return None
    return dict(ref=ref, top=top, rest=rest, jump=jump)


def _side_share(levels_best_first: List[Tuple[int, float]], own: Dict[int, float],
                target: float, df: float) -> Tuple[float, bool]:
    """Our expected score share for one side of the book.

    levels_best_first: (price_cents, total_size) best price first, sizes
    INCLUDING our own resting size. own: price -> our size. Returns
    (our_share, side_qualifies).

    Post-2026-07-30 program rules (CFTC amendment filed 2026-07-15): walk
    levels from the best price accumulating size; the REFERENCE price is the
    level where cumulative size first reaches target/5 (no longer simply the
    touch); every bid at or ABOVE the reference scores at full weight
    (N clamped to 0), bids below decay df^(ticks below reference); the
    qualifying walk continues until cumulative >= target and the side
    qualifies nobody if the book runs out first. The old touch>=99
    disqualifier is gone (only a missing best bid disqualifies)."""
    if not levels_best_first or target <= 0:
        return 0.0, False
    ref: Optional[int] = None
    accumulated = 0.0
    qualifying: List[Tuple[int, float]] = []
    for px, size in levels_best_first:
        qualifying.append((px, size))
        accumulated += size
        if ref is None and accumulated >= target / 5.0:
            ref = px
        if accumulated >= target:
            break
    else:
        return 0.0, False   # book thinner than target: side doesn't qualify
    total_score = 0.0
    our_score = 0.0
    for px, size in qualifying:
        w = df ** max(ref - px, 0)
        total_score += w * size
        our_score += w * min(own.get(px, 0.0), size)
    if total_score <= 0:
        return 0.0, False
    return our_score / total_score, True


def estimate_reward_share(yes_levels: List[List[float]], no_levels: List[List[float]],
                          own_orders: List[Tuple[str, int, float]],
                          target: float, df: float,
                          own_in_book: bool) -> Tuple[float, int]:
    """(our_fraction_of_pool, qualifying_sides). own_in_book=True when the
    orderbook read already contains our resting orders (live mode); False
    overlays them (dry run).

    Post-2026-07-30 rules: a snapshot only COUNTS when BOTH sides reach the
    target size ("two-sided liquidity" exclusion); a counted snapshot's total
    score is 2.0 (each side normalizes to 1.0), so our fraction is
    (our_yes_share + our_no_share) / 2 — and 0.0 whenever either side fails,
    because that snapshot is excluded outright (it also shrinks the paid pool
    via the non-excluded ratio; see coverage EMA at the call sites).
    `qualifying_sides` still reports 0/1/2 for observability."""
    own_yes: Dict[int, float] = {}
    own_no: Dict[int, float] = {}
    for book_side, yes_px, remaining in own_orders:
        if book_side == "bid":
            own_yes[yes_px] = own_yes.get(yes_px, 0.0) + remaining
        else:
            own_no[100 - yes_px] = own_no.get(100 - yes_px, 0.0) + remaining

    def prep(levels: List[List[float]], own: Dict[int, float]) -> List[Tuple[int, float]]:
        by_px: Dict[int, float] = {int(px): float(q) for px, q in levels}
        if not own_in_book:
            for px, q in own.items():
                by_px[px] = by_px.get(px, 0.0) + q
        return sorted(by_px.items(), key=lambda kv: -kv[0])

    share_yes, q_yes = _side_share(prep(yes_levels, own_yes), own_yes, target, df)
    share_no, q_no = _side_share(prep(no_levels, own_no), own_no, target, df)
    sides = int(q_yes) + int(q_no)
    if sides < 2:
        return 0.0, sides   # snapshot excluded: one qualifying side pays nobody
    return (share_yes + share_no) / 2.0, sides


def zero_share_strike_counts(frac: float,
                             est_own: List[Tuple[str, int, float]]) -> bool:
    """Is a zero reward share a verdict on the MARKET, or only on us?

    Only the first may score a zero-share strike. `estimate_reward_share`
    scores OUR size against the book, so in live mode `frac` is 0.0 BY
    CONSTRUCTION whenever our orders are absent — that measures our own
    failure to have orders up, not the book.

    2026-08-06, the incident this exists to prevent. Kalshi went down for
    maintenance 07:16-09:00Z (19,949 x 503 in 07Z, 18,737 in 08Z, 13 in 09Z).
    The failsafe cancelled every order at 07:18:44Z ("4 consecutive cycle
    errors (last: HttpError('Service Unavailable')); cancelled all"); then
    post-only 409s and our own 429 throttle kept us off the book — 36,321
    rejections, ZERO successful placements, two hours — and the 08Z half had
    no 503s at all, so an exchange-health guard would have stopped only half
    of it. The strike guard scored `own` (our RESTING orders) but tested `mq`
    (what we WANTED), so every selected market struck every cycle against
    books that never stopped qualifying (both sides at or above target on
    97-98% of cycle-log rows in every 10-minute bucket). Thirty cycles later
    307 markets benched 07:45:59-08:13:29Z: 293 of 471 candidates, selected
    390 -> 31, estimated reward ~$404/day -> ~$159/day for four hours. Not one
    of those benches was a statement about any book.

    A strike is scored only when real, non-pad size of ours is actually
    resting on BOTH sides and still earns exactly nothing — i.e. our rungs sit
    outside the qualifying walk, or the snapshot is excluded outright. That is
    fill risk carried for zero rent, which is the only thing the bench is for.

    Pads are excluded because a 1c/99c pad can never score: `_side_share`
    breaks the qualifying walk once cumulative depth reaches target, thousands
    of ticks above the pad. A pads-only market is therefore guaranteed
    frac == 0.0 with a NON-EMPTY desired set, which is exactly the case the
    old `and mq` test waved through.

    `remaining > 0` is load-bearing on its own: if the count field is ever
    renamed, `order_remaining` falls through to 0.0 (:2067-2075) and
    own_by_ticker fills with all-zero entries that would otherwise read as
    real resting size. That is the class of the `_fp` rename that silently
    killed position reads for two weeks.

    `est_own` MUST be the same list that produced `frac` at the call site —
    our real resting orders when live, the desired ladder when dry — so the
    predicate can never disagree with the number it judges. That mismatch WAS
    the bug.

    Pad classification is deliberately looser than
    IncentiveMarketMaker._is_pad_price (a bound, not equality): if
    IMM_PAD_BID_CENTS/IMM_PAD_ASK_CENTS are retuned while pads are resting,
    stale pads must still read as pads. Every error in that direction fails
    toward NOT striking, which is the safe side of this predicate."""
    if frac > 0.0:
        return False
    real_bid = any(bs == "bid" and n > 0 and px > PAD_BID_CENTS
                   for bs, px, n in est_own)
    real_ask = any(bs == "ask" and n > 0 and px < PAD_ASK_CENTS
                   for bs, px, n in est_own)
    return real_bid and real_ask


# ----------------------------------------------------------------------------
# Quote construction
# ----------------------------------------------------------------------------

@dataclass(frozen=True)
class Quote:
    ticker: str
    book_side: str      # 'bid' (buy YES) or 'ask' (sell YES == buy NO)
    price_cents: int
    count: int
    is_pad: bool = False   # deep 1c/99c depth-padding order (see pad_to_target):
    #   fills the side to the reward target so the near-touch ladder qualifies;
    #   earns ~0 itself, exempt from the per-market ladder/position caps.
    price_exact: Optional[float] = None   # SUB-PENNY JOIN (Jack 2026-09-26):
    #   the exact YES price in cents (2 dp, e.g. 19.15) to send instead of the
    #   whole-cent price_cents, set by subpenny_snap on markets whose price
    #   step is finer than a cent so the rung rests AT the scored touch
    #   rather than a fraction of a cent behind it. price_cents stays the
    #   integer bucket every other consumer (bands, caps, ledger) reasons in.


# JOIN AHEAD OF THE PILE (Jack 2026-10-11: "do 1,2,6,8" -- #8 of the
# consolidated recommendations, after his question that morning: "if im
# quoting 200 contracts, and the orderbook is 5,10,2000 ... i should add the
# 200 contracts to the 10 and be ahead of the 2000 contracts"). The
# at-reference rung is placed on the book as it stands, so it never sees that
# OUR size can move the reference: resting at a thinner level ahead of a pile
# makes that level the reference and drops the pile behind it to discounted
# weight (df^ticks), so the same contracts score a bigger share. A survey of
# 1,074 live books (10/11 ~16:00Z, scored with _side_share; report_tools/
# mult_study/survey_forward.py + forward_combine.py) found ~5% of at-reference
# sides could gain. With the guards below: ~67 sides, +$26/day of modelled
# reward against ~$2/day of extra fill cost (24h mark-outs by depth behind
# the touch, cost_by_depth.py), about half of it outside the families left
# out below. Per side, every cycle, on the EXTERNAL book (our orders netted out):
#   * candidates run from the plain at-reference price up to
#     JOIN_AHEAD_MIN_TICKS behind the external best -- never the touch
#     itself, never improving it -- inside the safe-join offset and the band;
#   * each candidate rests what the at-reference rule would rest at THAT
#     depth (the deep-reference multiplier shrinks as the rung moves up);
#   * the side moves to the best-scoring candidate only when that lifts its
#     share by >= JOIN_AHEAD_MIN_GAIN and >= JOIN_AHEAD_MIN_DAY $/day while
#     >= JOIN_AHEAD_MIN_AHEAD contracts still rest ahead of us; otherwise it
#     rests at the external reference (so our own rung cannot hold the
#     reference forward once the pile is gone).
# Left out: sports ladders / escalators (1c ahead of their piles is its own
# test, not taken), daily families and Carbon Arc (the most informed fills;
# Carbon Arc's late-month rule is judged from 10/18), the approval markets
# (JOIN_AHEAD_EXCLUDE), sub-penny books, any market whose fair gate caps a
# side this cycle, and reduce-only / full-unwind sides.
# IMM_JOIN_AHEAD=dry logs the moves without making them; off disables.
JOIN_AHEAD_MODE = os.environ.get("IMM_JOIN_AHEAD", "on").strip().lower()
JOIN_AHEAD_MIN_GAIN = _env_float("IMM_JOIN_AHEAD_MIN_GAIN", 0.5)
JOIN_AHEAD_MIN_DAY = _env_float("IMM_JOIN_AHEAD_MIN_DAY", 0.05)
JOIN_AHEAD_MIN_AHEAD = _env_float("IMM_JOIN_AHEAD_MIN_AHEAD", 50.0)
JOIN_AHEAD_MIN_TICKS = max(1, _env_int("IMM_JOIN_AHEAD_MIN_TICKS", 1))
JOIN_AHEAD_EXCLUDE: Tuple[str, ...] = tuple(
    p.strip() for p in os.environ.get(
        "IMM_JOIN_AHEAD_EXCLUDE", "KXTRUMPAPPROVE,KXAPRPOTUS").split(",")
    if p.strip())


def join_ahead_series(series: str) -> bool:
    """May this series' at-reference rungs join ahead of a pile at all?"""
    if JOIN_AHEAD_MODE not in ("on", "dry") or LADDER_MODE != "atref":
        return False
    if sports_ladder_league(series) is not None or is_daily_series(series) \
            or nfl_h2h_series(series) or nfl_auto_entry(series) is not None \
            or league_auto_entry(series) is not None:
        return False
    # Carbon Arc by its verified source OR its name pattern: an unverified
    # *POS / *FT / *APP / *ADS / *CC stays out too (fails toward no move)
    if carbon_arc_settled(series) \
            or series.endswith(tuple(suf for suf, _c in _CA_SUFFIX_CATEGORY)):
        return False
    return not series.startswith(JOIN_AHEAD_EXCLUDE)


def join_ahead_pick(ext_levels: List[Tuple[int, float]], base_px: int,
                    top_px: int, size_at: Callable[[int], int],
                    target: float, df: float,
                    pool_per_day: float) -> Optional[dict]:
    """The join-ahead decision for ONE side, in that side's own price space
    (YES cents for a bid, NO cents for an ask: higher = more aggressive).
    `ext_levels`: the side's external levels (no own orders), best first.
    `base_px`: where the plain at-reference rule rests; `top_px`: the most
    aggressive price allowed; `size_at(px)`: the contracts that would rest
    at px. None when the plain placement stands, else {px, size, share,
    base_share, ahead, base_ahead, gain_day} (shares of the side; gain in
    $/day of the market's pool, which pays each side half)."""
    if target <= 0 or top_px <= base_px:
        return None
    by: Dict[int, float] = {}
    for p, q in ext_levels:
        if q > 0:
            by[int(p)] = by.get(int(p), 0.0) + float(q)

    def score(px: int, n: int) -> float:
        lv = dict(by)
        lv[px] = lv.get(px, 0.0) + n
        return _side_share(sorted(lv.items(), key=lambda kv: -kv[0]),
                           {px: float(n)}, target, df)[0]

    def ahead(px: int) -> float:
        return sum(q for p, q in by.items() if p >= px)

    n0 = int(size_at(base_px))
    if n0 <= 0:
        return None
    s0 = score(base_px, n0)
    best: Optional[Tuple[int, float, int, float]] = None
    for px in range(base_px + 1, top_px + 1):
        a = ahead(px)
        if a < JOIN_AHEAD_MIN_AHEAD:
            continue
        n = int(size_at(px))
        if n <= 0:
            continue
        s = score(px, n)
        if best is None or s > best[1] + 1e-12:      # a tie keeps the deeper price
            best = (px, s, n, a)
    if best is None:
        return None
    px, s, n, a = best
    gain_day = pool_per_day * (s - s0) / 2.0
    if s < (1.0 + JOIN_AHEAD_MIN_GAIN) * s0 or gain_day < JOIN_AHEAD_MIN_DAY:
        return None
    return dict(px=px, size=n, share=s, base_share=s0, ahead=a,
                base_ahead=ahead(base_px), gain_day=gain_day)


# COMPLEMENT LEAD (Jack 2026-10-28: "in examples like this, you can infer the
