COMP_LEAD_MODE = os.environ.get("IMM_COMP_LEAD", "on").strip().lower()
COMP_LEAD_SHARE = _env_float("IMM_COMP_LEAD_SHARE", 0.95)
COMP_LEAD_MARGIN_C = max(0, _env_int("IMM_COMP_LEAD_MARGIN_C", 5))
