    # ---- restart persistence (which markets are OURS) ------------------------
    # Realized P&L and breakers reset on restart (accepted); the set of tickers
    # this bot has ever quoted must not — it drives the fills filter and the
    # inventory budget reserve, and misclassifying the crypto fleet's positions
    # as ours (or ours as theirs) breaks both.

    PERSIST_PATH = os.path.join(STATUS_DIR, "imm_state.json")

    ORDER_JOURNAL_PATH = os.path.join(STATUS_DIR, "imm_order_journal.jsonl")

    def state_account_mismatch(self) -> Optional[str]:
        """Why this process must not trade on the persisted state, or None.

        imm_state.json describes ONE account (2026-10-02): its positions, its
        order ids, the reward accrual banked there, the P&L carry and the
        balance-floor anchor. Read against another account it would manage
        inventory that is not there, protect accrual never earned there and
        anchor the balance floor to the wrong balance. main() refuses a live
        start and --cancel-all on a mismatch; dry runs and tests never ask."""
        if self._state_owner == KEY_ID:
            return None
        return (f"{self.PERSIST_PATH} belongs to Kalshi key "
                f"{self._state_owner[:8]}..., but this process signs as "
                f"{KEY_ID[:8]}... ({IMM_ACCOUNT.source}). Either sign as the "
                f"account that owns it (the IMM_KALSHI_* user variables, see "
                f"imm_account.py) or, to move to this account: stop the bot, "
                f"--cancel-all while still signing as the old account, then "
                f"archive imm_state.json, imm_order_journal.jsonl and "
                f"{RESTART_HANDOFF_FILE} before starting it here.")

    # ------------------------------------------------------------------
    # Structured analytics sinks
    #
    # These write ANALYSIS data only. Three rules hold for every one of
    # them, and they are why this is safe to run on a live book:
    #   1. No sink may change a trading decision.
    #   2. No sink may raise — a failed write is swallowed.
    #   3. No sink may flood the log — a broken sink mutes itself.
    #
    # Each is one append-only JSONL file per UTC day under STATUS_DIR, so a
    # day of any stream is a single `bq load` (or pandas
    # read_json(lines=True)) away, and every row carries run_id +
    # config_hash so results can be grouped by the configuration that
    # produced them.
    #
    # IMM_ANALYTICS=0 disables all of them at once.
    # ------------------------------------------------------------------
    ANALYTICS_ON = os.environ.get("IMM_ANALYTICS", "1") == "1"

    def _sink(self, name: str, rec: dict) -> None:
        """Append one JSON object to STATUS_DIR/<name>_YYYY-MM-DD.jsonl.

        A sink that fails (full disk, permissions, a serialisation bug in a
        new field) is muted for the rest of the run after one line: on a
        live book a per-cycle failure would otherwise turn into thousands
        of identical log lines and bury the trading messages that matter."""
        if not self.ANALYTICS_ON:
            return
        try:
            rec.setdefault("run_id", RUN_ID)
            rec.setdefault("config_hash", CONFIG_HASH)
            path = os.path.join(
                STATUS_DIR,
                f"{name}_{datetime.now(timezone.utc).strftime('%Y-%m-%d')}.jsonl")
            with open(path, "a", encoding="utf-8") as f:
                f.write(json.dumps(rec, default=str) + "\n")
        except Exception as e:
            if name not in self._sink_muted:
                self._sink_muted.add(name)
                log(f"{self.tag} ! analytics sink '{name}' failed ({e}); "
                    f"muted for the rest of this run")

    def _book_log_add(self, ticker: str, source: str, ob, own_exact,
                      meta=None, fast: bool = False,
                      own_src: str = "") -> None:
        """Queue one book for the full-depth log. O(1): keeps a REFERENCE to
        the raw response; serialisation happens in _book_log_flush, off the
        placement path. Never raises."""
        if not (self.ANALYTICS_ON and BOOK_LOG_ON) or not isinstance(ob, dict):
            return
        try:
            if len(self._book_buf) >= BOOK_LOG_MAX_BUFFER:
                # A stuck disk must not grow memory without bound: drop the
                # oldest half (the flush is failing anyway; it will say so).
                del self._book_buf[:len(self._book_buf) // 2]
            self._book_buf.append((
                time.time(), self._book_cycle_ts, ticker, source, bool(fast), ob,
                list(own_exact or ()),
                getattr(meta, "target_size", None),
                getattr(meta, "discount_factor", None),
                getattr(meta, "dollars_per_day", None),
                own_src))
        except Exception:
            pass

    @staticmethod
    def _book_row(rec) -> Optional[str]:
        """One queued book -> one compact JSON line, or None. Prices stay in
        the unit Kalshi sent them (orderbook_fp: dollars, sub-penny exact);
        `unit` says which. Our own size is keyed by exact YES cents on the yes
        side and by NO cents (100 - YES) on the no side, matching the book."""
        try:
            ts, cyc, t, src, fast, ob, own, tgt, disc, pool, own_src = rec
            fp = ob.get("orderbook_fp")
            if fp is not None:
                yes = fp.get("yes_dollars") or []
                no = fp.get("no_dollars") or []
                unit = "dollars"
            else:                                   # legacy integer-cent shape
                lg = ob.get("orderbook") or {}
                yes, no, unit = lg.get("yes") or [], lg.get("no") or [], "cents"
            oy: Dict[float, float] = {}
            on: Dict[float, float] = {}
            for bs, px, rem in own:                 # (book_side, yes_cents, remaining)
                if bs == "bid":
                    k = round(float(px), 4)
                    oy[k] = oy.get(k, 0.0) + float(rem)
                else:                               # our ask is a NO bid at 100 - yes
                    k = round(100.0 - float(px), 4)
                    on[k] = on.get(k, 0.0) + float(rem)
            return json.dumps({
                "ts": round(ts, 3), "cycle_ts": cyc, "ticker": t, "source": src,
                "fast": fast, "unit": unit, "yes": yes, "no": no,
                "own_yes_cents": sorted([k, v] for k, v in oy.items()),
                "own_no_cents": sorted([k, v] for k, v in on.items()),
                # where own size came from: "resting_read" (managed, this
                # cycle's exchange read) or "resting_prev_cycle" (candidate)
                "own_src": own_src,
                "target": tgt, "discount": disc, "pool_per_day": pool,
                "run_id": RUN_ID, "config_hash": CONFIG_HASH,
            }, separators=(",", ":"), default=str)
        except Exception:
            return None                              # one bad row never kills a flush

    def _book_log_flush(self) -> None:
        """Write queued books: one complete gzip member per UTC day per flush,
        appended to a per-run file book_depth/book_depth_<day>_<RUN_ID>.jsonl.gz.
        Concatenated gzip members are valid gzip. A hard kill can only truncate
        THIS run's tail member, and a failed write moves to a fresh part file,
        so a partial member is never followed by good data. Never raises; mutes
        itself after 5 consecutive failures."""
        if not self._book_buf:
            return
        if "book_depth" in self._sink_muted:
            self._book_buf = []
            return
        buf = self._book_buf
        try:
            by_day: Dict[str, List[str]] = {}
            for rec in buf:
                line = self._book_row(rec)
                if line is not None:
                    d = time.strftime("%Y-%m-%d", time.gmtime(rec[0]))
                    by_day.setdefault(d, []).append(line)
            dirp = book_log_dir()
            os.makedirs(dirp, exist_ok=True)
            sfx = f"_{RUN_ID}" + (f".p{self._book_part}" if self._book_part else "")
            for d, lines in by_day.items():
                member = gzip.compress(("\n".join(lines) + "\n").encode("utf-8"),
                                       compresslevel=BOOK_LOG_GZ_LEVEL)
                with open(os.path.join(dirp, f"book_depth_{d}{sfx}.jsonl.gz"),
                          "ab") as f:
                    f.write(member)
            self._book_buf = []
            self._book_fail = 0
        except Exception as e:
            self._book_fail += 1
            self._book_part += 1
            if self._book_fail == 1:
                log(f"{self.tag} ! book-depth flush failed ({e}); keeping "
                    f"{len(buf)} rows, retry next cycle")
            if self._book_fail >= 5:
                self._sink_muted.add("book_depth")
                self._book_buf = []
                log(f"{self.tag} ! book-depth log muted for the rest of this run")

    def _gskip(self, t: str, guard: str, inputs=None, book=None) -> None:
        """Record that the managed loop leaves `t` at `guard` this cycle -- a
        skip that otherwise writes no cycle_log row at all.

        `inputs` and `book` are zero-argument CALLABLES (lambdas at the call
        site), evaluated HERE inside the try. That is deliberate: keyword
        arguments would be evaluated at the call site, BEFORE any try, so an
        unbound name or a None subtraction would raise straight into the live
        placement loop. A lambda defers evaluation to where it is caught, so
        the call site cannot raise. (It does NOT protect against a STALE name
        -- Python keeps the previous market's loop locals bound -- so each call
        site passes only names assigned for THIS market on that path.)

        Pure dict write; _flush_guard_skips emits change-driven rows after the
        loop."""
        if not (self.ANALYTICS_ON and GUARD_LOG):
            return
        try:
            rec = {"guard": guard, "inputs": {}, "ext_bid": None,
                   "ext_ask": None, "yes_depth": None, "no_depth": None}
            if inputs is not None:
                try:
                    rec["inputs"] = inputs()
                except Exception as e:
                    rec["inputs"] = {"_input_error": type(e).__name__}
            if book is not None:
                try:
                    eb, ea, yl, nl = book()
                    rec["ext_bid"], rec["ext_ask"] = eb, ea
                    rec["yes_depth"] = round(sum(q for _p, q in yl)) if yl is not None else None
                    rec["no_depth"] = round(sum(q for _p, q in nl)) if nl is not None else None
                except Exception:
                    pass
            self._guard_now[t] = rec
        except Exception:
            pass

    def _flush_guard_skips(self, now_utc, now_ts, managed) -> None:
        """guard_skips_YYYY-MM-DD.jsonl, change-driven like selection_events:
          kind=enter     ticker newly held by a guard, or moved to another
                         (prev = the old guard, None if newly held)
          kind=clear     held last full cycle, evaluated clean now
                         (managed=False: it left the book entirely)
          kind=snapshot  hourly: every ticker a guard holds right now
          kind=cycle     hourly: counts per guard + n_managed (the denominator)
        The dedup key is (ticker, guard); inputs are NOT part of it, so input
        drift while a guard holds shows only in the hourly snapshot. State is
        per process: after a restart every held guard re-emits as enter with
        prev=None. Without dedup this would be ~55k rows/day; with it,
        ESTIMATED ~1.5-4k."""
        if not (self.ANALYTICS_ON and GUARD_LOG):
            return
        try:
            ts, now = now_utc.isoformat(), self._guard_now
            for t, rec in now.items():
                prev = self._guard_prev.get(t)
                if prev != rec["guard"]:
                    self._sink("guard_skips", {"ts": ts, "kind": "enter",
                                               "ticker": t, "prev": prev, **rec})
            for t, prev in self._guard_prev.items():
                if t not in now:
                    # Book context only for a market still managed (its panel
                    # is this cycle's). One that LEFT the book has no fresh
                    # panel -- _last_panel would be from its last managed
                    # cycle, possibly hours old -- so it logs nulls rather
                    # than a stale book passed off as current.
                    on_book = t in managed
                    p = (self._last_panel.get(t) or {}) if on_book else {}
                    self._sink("guard_skips", {
                        "ts": ts, "kind": "clear", "ticker": t, "guard": None,
                        "prev": prev, "managed": on_book, "inputs": {},
                        "ext_bid": p.get("ext_bid"), "ext_ask": p.get("ext_ask"),
                        "yes_depth": p.get("yes_depth"),
                        "no_depth": p.get("no_depth"),
                        "panel_ts": p.get("ts")})
            self._guard_prev = {t: r["guard"] for t, r in now.items()}
            if now_ts - self._guard_snap_at >= 3600:
                self._guard_snap_at = now_ts
                counts: Dict[str, int] = {}
                for t, rec in now.items():
                    counts[rec["guard"]] = counts.get(rec["guard"], 0) + 1
                    self._sink("guard_skips", {"ts": ts, "kind": "snapshot",
                                               "ticker": t, "prev": None, **rec})
                self._sink("guard_skips", {"ts": ts, "kind": "cycle",
                                           "n_managed": len(managed),
                                           "counts": counts})
        except Exception as e:
            if "guard_skips" not in self._sink_muted:
                self._sink_muted.add("guard_skips")
                log(f"{self.tag} ! guard-skip sink failed ({e}); muted this run")

    def _book_fill(self, f: dict, now_ts: float, toxic: bool = True) -> None:
        """Book one of OUR fills: own book, fills counter, fills sink and --
        when `toxic` -- the pick-off queue. The one path every own fill
        takes: the cycle's fills read, and the startup reconcile's orphaned
        fills (toxic=False: a pick-off check needs the mark shortly after
        the fill, which an old fill no longer has)."""
        side, action = f.get("side"), f.get("action")
        count = float(f.get("count_fp") or f.get("count") or 0)
        px = f.get("yes_price_dollars")
        px_cents = float(px) * 100 if px is not None else float(f.get("yes_price") or 0)
        if side in ("yes", "no") and action in ("buy", "sell") and count > 0:
            tkr = f.get("ticker", "?")
            # Read position BEFORE booking; log AFTER. Ordering is
            # deliberate: the fill must be booked into P&L even if
            # anything about the analytics row is broken.
            pos_before = self.pnl.pos.get(tkr, 0.0)
            avg_before = self.pnl.avg.get(tkr, 0.0)
            self.pnl.on_fill(tkr, side, action, count, px_cents)
            self.state.fills_today += count
            if QUAKE_ASK_STRIKES and quake_gated(series_of(tkr)) \
                    and self.pnl.pos.get(tkr, 0.0) < pos_before - 1e-9:
                # one of our quake asks sold YES: brake the event's asks
                # (the WS fill usually got here first)
                self._quake_ask_brake_note(tkr, now_ts, "fill")
            # a lock leg's fill is a hedge: no fill pauses, pick-off or bait
            # notes for it
            leg = self._lock_leg_fill(str(f.get("order_id") or ""))
            if not f.get("is_taker") and not leg and yt2_series(series_of(tkr)):
                # a fill on the YouTube #2 pilot: stand its event aside
                # (YT2_FILL_PAUSE_MIN; the WS fill usually got here first)
                self._yt2_fill_pause_note(tkr, float(self._fill_ts(f) or now_ts),
                                          "fill")
            if not f.get("is_taker") and not leg and astest_family(series_of(tkr)) is not None:
                # a fill on an AS test family: stand its event aside
                # (ASTEST_<F>_FILL_PAUSE_MIN; the WS fill usually got here first)
                self._astest_fill_pause_note(tkr, float(self._fill_ts(f) or now_ts),
                                             "fill", count=count)
            join = self._log_fill(f, tkr, side, action, count, px_cents,
                                  now_ts, pos_before, avg_before)
            if toxic and not leg:
                self._toxic_note_fill(f, tkr, side, action, px_cents)
                self._bait_note_fill(f, tkr, join, count, now_ts)
            # a fill that opens a position in a linked event is locked if
            # its hedge clears the edge; a lock leg's fill credits its job
            # (COMP_HEDGE_MODE for a lead's fill, LOCK_MODE for any other)
            self._comp_hedge_on_fill(f, tkr, side, action, count, px_cents, now_ts,
                                     pos_before=pos_before,
                                     pos_after=self.pnl.pos.get(tkr, 0.0))

    def _log_fill(self, f: dict, tkr: str, side: str, action: str,
                  count: float, px_cents: float, now_ts: float,
                  pos_before: float, avg_before: float) -> None:
        """One row per fill — the single most important thing this bot was
        not recording.

        Three joins are taken here that are impossible to reconstruct later:

        `ledger`  the order this fill hit AS IT STOOD WHEN THE FILL HIT: the
                  price WE quoted, the rung's remaining size as we last set
                  it and what was left of it, whether it was a 1c/99c pad,
                  and when it was placed. Read from _fill_join (FILL_JOIN_*),
                  which keeps every version the ledger gave the order --
                  the ledger itself drops an order that filled out before
                  this poll books the fill, and an amend overwrites it.
                  `join_src` says where it came from: "ledger" (this run),
                  "handoff" (the run before a restart handoff) or "derived"
                  (no record of the order: our_book_side from Kalshi's side /
                  action, the rest null). our_order_ids keeps only the
                  last ORDER_ID_KEEP_HOURS, so later the OWNERSHIP of a
                  historical fill rests on the orders log's `place` rows
                  alone on a shared account.

        `panel`   the book/reward state from the last cycle read — ext bid/ask,
                  depth, target, est_frac, pool. This is what makes
                  adverse-selection analysis possible: fill price against the
                  book it filled into.

        `pos_*`   inventory before and after, so a fill can be classified as
                  opening, adding or reducing without replaying the tape."""
        try:
            oid = str(f.get("order_id") or "")
            book_side = our_px = rem = left = coid = placed = src = None
            try:
                hit = self._join_fill(f, px_cents, count)
            except Exception as ex:          # the row still goes out
                self._join_fail(ex)
                hit = None
            if hit is not None:
                ent, vi = hit
                v = ent["v"][vi]
                book_side, our_px, coid, placed, src = (
                    ent["side"], v[1], ent["coid"], ent["placed"], v[4])
                left = self._join_left(ent, vi, float(self._fill_ts(f)),
                                       str(f.get("trade_id") or f.get("fill_id") or ""))
                # a version set after the fill (an adopted order's gap fill
                # with nothing handed over) does not know the size before it
                rem = v[3] if left is not None else None
            else:
                led = self.state.ledger.get(oid)
                if led:
                    book_side, our_px, rem = (led.get("book_side"),
                                              led.get("yes_price"),
                                              led.get("remaining_count"))
                    coid, placed, src = (led.get("client_order_id"),
                                         led.get("_placed_at"), "ledger")
                else:
                    # no record of the order (a restart that handed nothing
                    # over, a taker order): Kalshi's side / action, which
                    # matches the join on every row that has both
                    book_side, src = _FILL_BOOK_SIDE.get((side, action)), "derived"
            panel = self._last_panel.get(tkr) or {}
            self._sink("fills", {
                "ts": self._fill_ts(f),
                "cycle_ts": now_ts,
                "fill_id": f.get("trade_id") or f.get("fill_id"),
                "order_id": f.get("order_id"),
                "ticker": tkr,
                "series": series_of(tkr),
                "event_ticker": self._event_of(tkr),
                "side": side,
                "action": action,
                "count": count,
                "yes_price_cents": px_cents,
                "is_taker": f.get("is_taker"),
                # --- the order we had resting (ledger join) ---
                "our_book_side": book_side,
                "our_price_cents": our_px,
                "our_remaining_before": rem,
                "client_order_id": coid,
                "order_age_secs": (round(now_ts - placed, 1)
                                   if placed else None),
                "is_pad": (self._is_pad_price(book_side, our_px)
                           if book_side and our_px is not None
                           else None),
                # --- inventory context ---
                "pos_before": pos_before,
                "avg_before": avg_before,
                "pos_after": self.pnl.pos.get(tkr, 0.0),
                "avg_after": self.pnl.avg.get(tkr, 0.0),
                # --- book context at the last read (adverse selection) ---
                "ext_bid": panel.get("ext_bid"),
                "ext_ask": panel.get("ext_ask"),
                "yes_depth": panel.get("yes_depth"),
                "no_depth": panel.get("no_depth"),
                "target": panel.get("target"),
                "est_frac": panel.get("est_frac"),
                "qual_sides": panel.get("qual_sides"),
                "pool_per_day": panel.get("pool_per_day"),
                "panel_ts": panel.get("ts"),
                "is_scan": panel.get("is_scan"),
                # --- the join's source, and what was left (2026-10-04) ---
                "join_src": src,
                # our_remaining_before less the order's earlier fills on the
                # same version: count >= this means the fill took the rung
                "our_left_before": left,
            })
            # the join, for the bait-fingerprint stop's whole-rung test
            return book_side, our_px, rem, left
        except Exception as e:
            if "fills" not in self._sink_muted:
                self._sink_muted.add("fills")
                log(f"{self.tag} ! fill sink failed ({e}); muted for this run")
        return None

    # ---- fills-sink ledger join (FILL_JOIN_*, 2026-10-04) --------------------

    def _join_fail(self, ex: Exception) -> None:
        """One log line per run for a join bookkeeping failure; the order
        paths and the fills row carry on without it."""
        if "fill_join" not in self._sink_muted:
            self._sink_muted.add("fill_join")
            log(f"{self.tag} ! fill-join bookkeeping failed ({ex}); fills rows "
                f"may lack their ledger join this run")

    def _join_set(self, oid: str, ticker: str, book_side: str, yes_price,
                  exact, remaining, coid=None, placed=None) -> None:
        """Keep one ledger write (placement, amend, restart adoption) as a new
        version of the order for the fills sink's join. Called from the order
        paths, so it never raises."""
        if not (self.ANALYTICS_ON and oid):
            return
        try:
            ent = self._fill_join.get(oid)
            if ent is None:
                ent = self._fill_join[oid] = {
                    "t": ticker, "side": book_side, "coid": coid,
                    "placed": placed, "v": [], "f": {}, "gone": None}
            else:
                ent["coid"] = ent.get("coid") or coid
                ent["placed"] = ent.get("placed") or placed
            ent["v"].append([time.time(),
                             None if yes_price is None else int(yes_price),
                             None if exact is None else float(exact),
                             None if remaining is None else float(remaining),
                             "ledger"])
            ent["gone"] = None
        except Exception as ex:
            self._join_fail(ex)

    def _join_fill(self, f: dict, px_cents: float, count: float):
        """(entry, version index) of the order one of our fills hit, the fill
        registered on that version once (by fill id) so the order's later
        fills count it; None when there is no record of the order."""
        ent = self._fill_join.get(str(f.get("order_id") or ""))
        if ent is None or not ent["v"]:
            return None
        fid = str(f.get("trade_id") or f.get("fill_id") or "")
        got = ent["f"].get(fid) if fid else None
        if got is not None:
            return ent, int(got[2])
        fts = float(self._fill_ts(f))
        vi = _join_pick(ent["v"], fts, px_cents)
        if fid:
            ent["f"][fid] = [fts, float(count), vi]
        return ent, vi

    @staticmethod
    def _join_left(ent: dict, vi: int, fts: float, fid: str) -> Optional[float]:
        """What was left of the order just before this fill: version `vi`'s
        remaining less the fills registered on it earlier (Kalshi's stamp,
        then fill id). None when the version was set after the fill. A fill
        older than the version (an adopted order's gap fill) is already
        netted out of the remaining the version was read with, so it never
        counts against a later one."""
        v = ent["v"][vi]
        if v[3] is None or v[0] > fts + FILL_JOIN_SKEW_SECS:
            return None
        key = (fts, fid)
        prior = sum(x[1] for k, x in ent["f"].items()
                    if int(x[2]) == vi and k != fid
                    and x[0] + FILL_JOIN_SKEW_SECS >= v[0] and (x[0], k) < key)
        return round(max(0.0, v[3] - prior), 4)

    def _join_note_fills(self, fills: List[dict]) -> None:
        """Register a fills poll's whole batch on its orders' versions BEFORE
        any of it is booked: Kalshi returns a batch newest first, and what was
        left of an order before a fill counts that order's EARLIER fills.
        Never raises."""
        if not self._fill_join:
            return
        for f in fills:
            try:
                # parsed as _book_fill parses it
                count = float(f.get("count_fp") or f.get("count") or 0)
                px = f.get("yes_price_dollars")
                px_cents = float(px) * 100 if px is not None else float(f.get("yes_price") or 0)
                if count > 0:
                    self._join_fill(f, px_cents, count)
            except Exception as ex:
                self._join_fail(ex)

    def _join_prune(self, now_ts: float) -> None:
        """Once a cycle, after the fills poll is booked: an order out of the
        ledger is kept FILL_JOIN_KEEP_SECS from the first prune that finds it
        gone (its last fills are booked by the next poll), then forgotten.
        Never raises."""
        if not self._fill_join:
            return
        try:
            led = self.state.ledger
            drop = []
            for oid, ent in self._fill_join.items():
                if oid in led:
                    ent["gone"] = None
                elif ent["gone"] is None:
                    ent["gone"] = now_ts
                elif now_ts - ent["gone"] > FILL_JOIN_KEEP_SECS:
                    drop.append(oid)
            for oid in drop:
                del self._fill_join[oid]
            over = len(self._fill_join) - FILL_JOIN_MAX_ORDERS
            if over > 0:
                for _g, oid in sorted((ent["gone"], oid) for oid, ent
                                      in self._fill_join.items()
                                      if ent["gone"] is not None)[:over]:
                    del self._fill_join[oid]
        except Exception as ex:
            self._join_fail(ex)

    def _join_export(self) -> Dict[str, dict]:
        """The join's records, JSON-safe, for the relaunch to book the fills
        that land after this run's last poll (restart handoff). Never raises:
        empty on failure."""
        def num(x):
            return None if x is None else float(x)

        def txt(x):
            return None if x is None else str(x)
        try:
            # coerced field by field: the handoff's json.dump must never trip
            # on a value the export carries
            return {str(oid): {
                "t": txt(ent["t"]), "side": txt(ent["side"]),
                "coid": txt(ent["coid"]), "placed": num(ent["placed"]),
                "v": [[float(v[0]), None if v[1] is None else int(v[1]),
                       num(v[2]), num(v[3])] for v in ent["v"]],
                "f": {str(k): [float(x[0]), float(x[1]), int(x[2])]
                      for k, x in ent["f"].items()}}
                for oid, ent in self._fill_join.items() if ent["v"]}
        except Exception as ex:
            self._join_fail(ex)
            return {}

    def _join_import(self, data) -> int:
        """Load the records a restart handoff carried; their versions are
        marked "handoff". A malformed record is skipped, an order this run
        already holds is kept as is. Returns the number loaded; never
        raises."""
        if not (self.ANALYTICS_ON and isinstance(data, dict)):
            return 0
        n = 0
        for oid, ent in data.items():
            try:
                oid = str(oid)
                if not oid or oid in self._fill_join:
                    continue
                vs = [[float(v[0]), None if v[1] is None else int(v[1]),
                       None if v[2] is None else float(v[2]),
                       None if v[3] is None else float(v[3]), "handoff"]
                      for v in ent["v"]]
                if not vs:
                    continue
                fs = {str(k): [float(x[0]), float(x[1]), int(x[2])]
                      for k, x in (ent.get("f") or {}).items()
                      if 0 <= int(x[2]) < len(vs)}
                placed = ent.get("placed")
                self._fill_join[oid] = {
                    "t": ent.get("t"), "side": ent.get("side"),
                    "coid": ent.get("coid"),
                    "placed": None if placed is None else float(placed),
                    "v": vs, "f": fs, "gone": None}
                n += 1
            except Exception:
                continue
        return n

    # ---- toxic-flow side halt (TOXIC_*, Jack 2026-09-29) ---------------------

    @staticmethod
    def _toxic_key(ticker: str, book_side: str) -> str:
        return f"{ticker}|{book_side}"

    def _toxic_note_fill(self, f: dict, tkr: str, side: str, action: str,
                         px_cents: float) -> None:
        """Queue one of OUR maker fills for its pick-off check. Taker fills
        (the rain directional take) and 1c/99c pads never count -- the same
        ledger join _log_fill makes."""
        if not TOXIC_HALT or f.get("is_taker"):
            return
        led = self.state.ledger.get(f.get("order_id") or "") or {}
        our_px = led.get("yes_price")
        if led.get("book_side") and our_px is not None \
                and self._is_pad_price(led["book_side"], our_px):
            return
        # buying YES (or selling NO) = our BID was hit; else our ask was
        book_side = "bid" if (side, action) in (("yes", "buy"),
                                                ("no", "sell")) else "ask"
        self.state.toxic_pending.append(
            [tkr, book_side, float(px_cents),
             float(self._fill_ts(f) or time.time())])

    def _toxic_est(self, tickers) -> float:
        """The bot's own est reward $/day over `tickers` that are selected --
        what a halt of them forgoes per day (recorded for the morning
        email)."""
        tot = 0.0
        for t in tickers:
            m = self.state.selected.get(t)
            if m is not None:
                tot += float(getattr(m, "est_dollars_per_day", 0.0) or 0.0)
        return tot

    def _toxic_confirm(self, now_ts: float, fresh: Set[str]) -> List[str]:
        """Judge every queued fill whose check is due against the market's
        mark and record the pick-offs. A side halts on its TOXIC_PICKOFFS-th
        pick-off inside TOXIC_WINDOW_SECS; the whole EVENT halts once
        pick-offs inside TOXIC_EVENT_WINDOW_SECS span TOXIC_EVENT_MARKETS
        different markets of it. Only a mark refreshed THIS cycle (`fresh`)
        judges a fill; one with no fresh mark waits, and is dropped unjudged
        once TOXIC_MAX_LATE_SECS past due. Every pick-off and halt is written
        to the toxic_halts sink (the morning email reads it). A pick-off on an
        exempt series (TOXIC_EXEMPT_WORDS) is written and goes no further.
        Returns the side keys and event tickers halted by this call."""
        keep: List[list] = []
        halted: List[str] = []
        for p in self.state.toxic_pending:
            t, side, px, fts = p[0], p[1], float(p[2]), float(p[3])
            due = fts + TOXIC_CONFIRM_SECS
            if now_ts < due:
                keep.append(p)
                continue
            if now_ts - due > TOXIC_MAX_LATE_SECS:
                continue
            mark = self.state.last_mark.get(t)
            if mark is None or t not in fresh:
                keep.append(p)
                continue
            d = 1.0 if side == "bid" else -1.0
            if d * (float(mark) - px) > -TOXIC_PICKOFF_CENTS:
                continue                              # not picked off
            ev = self._event_of(t)
            exempt = toxic_exempt(series_of(t))
            self._sink("toxic_halts", {
                "kind": "pickoff", "ts": round(now_ts, 1), "ticker": t,
                "event": ev, "side": side, "fill_px": px,
                "fill_ts": round(fts, 1), "mark": round(float(mark), 2),
                "exempt": exempt})
            if exempt:
                continue                  # mention families: recorded, never halt
            # ---- the side rule ----
            key = self._toxic_key(t, side)
            picks = [x for x in self.state.toxic_picks.get(key, [])
                     if now_ts - x <= TOXIC_WINDOW_SECS] + [now_ts]
            if (len(picks) >= TOXIC_PICKOFFS
                    and self.state.toxic_halt_until.get(key, 0.0) <= now_ts):
                self.state.toxic_halt_until[key] = now_ts + TOXIC_HALT_SECS
                halted.append(key)
                msg = (f"{t} {side.upper()} picked off {len(picks)}x in "
                       f"{TOXIC_WINDOW_SECS / 3600:g}h (latest: filled "
                       f"{px:.0f}c, mark {float(mark):.1f}c "
                       f"{(now_ts - fts) / 60:.0f}min later) -- halting that "
                       f"side {TOXIC_HALT_SECS / 60:g}min")
                log(f"{self.tag} TOXIC {msg}")
                self.alerter.alert("toxic_halt", msg, key=key, urgent=False,
                                   now_ts=now_ts)
                self._sink("toxic_halts", {
                    "kind": "side_halt", "ts": round(now_ts, 1),
                    "until": round(now_ts + TOXIC_HALT_SECS, 1), "ticker": t,
                    "event": ev, "side": side, "pickoffs": len(picks),
                    "window_secs": TOXIC_WINDOW_SECS,
                    # one side of the market: about half its est reward
                    "est_per_day": round(0.5 * self._toxic_est([t]), 4)})
                picks = []
            self.state.toxic_picks[key] = picks
            # ---- the event rule ----
            if TOXIC_EVENT_MARKETS > 0:
                ep = [q for q in self.state.toxic_event_picks.get(ev, [])
                      if now_ts - q[0] <= TOXIC_EVENT_WINDOW_SECS] + [[now_ts, t]]
                mkts = sorted({q[1] for q in ep})
                if (len(mkts) >= TOXIC_EVENT_MARKETS
                        and self.state.toxic_event_halt_until.get(ev, 0.0) <= now_ts):
                    self.state.toxic_event_halt_until[ev] = \
                        now_ts + TOXIC_EVENT_HALT_SECS
                    halted.append(ev)
                    ev_mkts = [m.ticker for m in self.state.selected.values()
                               if self._event_of(m.ticker) == ev]
                    msg = (f"{ev} picked off on {len(mkts)} markets in "
                           f"{TOXIC_EVENT_WINDOW_SECS / 60:g}min ("
                           + ", ".join(m.rsplit("-", 1)[-1] for m in mkts[:6])
                           + f") -- halting the whole event "
                           f"{TOXIC_EVENT_HALT_SECS / 60:g}min")
                    log(f"{self.tag} TOXIC {msg}")
                    self.alerter.alert("toxic_halt", msg, key=ev, urgent=False,
                                       now_ts=now_ts)
                    self._sink("toxic_halts", {
                        "kind": "event_halt", "ts": round(now_ts, 1),
                        "until": round(now_ts + TOXIC_EVENT_HALT_SECS, 1),
                        "event": ev, "markets_picked": mkts,
                        "pickoffs": len(ep),
                        "window_secs": TOXIC_EVENT_WINDOW_SECS,
                        "markets_halted": len(ev_mkts),
                        "est_per_day": round(self._toxic_est(ev_mkts), 4)})
                    ep = []
                self.state.toxic_event_picks[ev] = ep
        self.state.toxic_pending = keep
        return halted

    def toxic_event_halted(self, event: str, now_ts: float) -> bool:
        """True while `event` is halted whole by the event rule. Never on an
        exempt series, so a halt saved before the exemption lapses too."""
        return TOXIC_HALT and not toxic_exempt(series_of(event)) and \
            self.state.toxic_event_halt_until.get(event, 0.0) > now_ts

    def toxic_market_halted(self, ticker: str, now_ts: float) -> bool:
        """Any toxic halt on this market: either side, or its event."""
        return (self.toxic_side_halted(ticker, "bid", now_ts)
                or self.toxic_side_halted(ticker, "ask", now_ts)
                or self.toxic_event_halted(self._event_of(ticker), now_ts))

    def toxic_side_halted(self, ticker: str, book_side: str,
                          now_ts: float) -> bool:
        """True while `book_side` of `ticker` is halted by the toxic rule
        (never on an exempt series)."""
        return TOXIC_HALT and not toxic_exempt(series_of(ticker)) and \
            self.state.toxic_halt_until.get(
                self._toxic_key(ticker, book_side), 0.0) > now_ts

    def _log_order(self, kind: str, ticker: str, book_side: str,
                   price_cents: Optional[int], count: Optional[float],
                   order_id: str = "", now_ts: float = 0.0, **extra) -> None:
        """One row per order-lifecycle event: place / reject / uncertain /
        amend / cancel.

        This is the denominator nothing else provides. Fills alone say what
        traded; only the orders that DIDN'T fill make fill-rate, queue
        position and ladder-shape answerable — and ~99.6% of this bot's
        ~38k daily placements are cancelled, so the denominator is almost
        the whole story. The exchange keeps orders for ~67 days and the only
        local record was a free-text stdout line whose amend variant
        truncates the order id to 8 chars.

        Book context comes from the cached panel, never a fresh read: this
        runs inside the placement wave and must not add API calls."""
        try:
            panel = self._last_panel.get(ticker) or {}
            eb, ea = panel.get("ext_bid"), panel.get("ext_ask")
            # Distance from the touch on our own side, in ticks — the axis
            # fill-rate is actually a function of.
            ticks = None
            if price_cents is not None:
                if book_side == "bid" and eb is not None:
                    ticks = int(eb) - int(price_cents)
                elif book_side == "ask" and ea is not None:
                    ticks = int(price_cents) - int(ea)
            rec = {
                "ts": datetime.now(timezone.utc).isoformat(),
                "cycle_ts": now_ts or None,
                "kind": kind,
                "order_id": order_id,
                "ticker": ticker,
                "series": series_of(ticker),
                "event_ticker": self._event_of(ticker),
                "book_side": book_side,
                "price_cents": price_cents,
                "count": count,
                "is_pad": (self._is_pad_price(book_side, price_cents)
                           if book_side and price_cents is not None else None),
                "ticks_from_touch": ticks,
                "ext_bid": eb, "ext_ask": ea,
                "yes_depth": panel.get("yes_depth"),
                "no_depth": panel.get("no_depth"),
                "target": panel.get("target"),
                "est_frac": panel.get("est_frac"),
                "is_scan": panel.get("is_scan"),
            }
            rec.update(extra)
            self._sink("orders", rec)
        except Exception as e:
            if "orders" not in self._sink_muted:
                self._sink_muted.add("orders")
                log(f"{self.tag} ! order sink failed ({e}); muted this run")

    def _journal_order_id(self, oid: str, ts: float) -> None:
        """Append-only crash journal for order ownership: one line per placed
        order so a hard-kill can never orphan a fill, without paying the full
        state dump per order. Folded into the main file (and truncated) by
        _save_persist."""
        try:
            with open(self.ORDER_JOURNAL_PATH, "a", encoding="utf-8") as f:
                f.write(json.dumps({"oid": oid, "ts": ts}) + "\n")
        except OSError as e:
            log(f"{self.tag} ! order journal write failed: {e}")

    def _load_journal(self) -> None:
        """Merge journaled order ids the last run placed but never folded into
        the main state file (i.e. it was killed mid-wave)."""
        try:
            with open(self.ORDER_JOURNAL_PATH, encoding="utf-8") as f:
                n = 0
                for line in f:
                    try:
                        rec = json.loads(line)
                        oid = str(rec["oid"])
                        if oid not in self.state.our_order_ids:
                            self.state.our_order_ids[oid] = float(rec["ts"])
                            n += 1
                    except (ValueError, KeyError, TypeError):
                        continue
            if n:
                log(f"{self.tag} recovered {n} journaled order id(s) from an unclean shutdown")
        except FileNotFoundError:
            pass
        except OSError as e:
            log(f"{self.tag} ! order journal read failed: {e}")

    def _load_persist(self) -> None:
        try:
            with open(self.PERSIST_PATH, encoding="utf-8") as f:
                data = json.load(f)
            # A file from before 2026-10-02 names no owner: it can only be the
            # fleet account's, the one account the IMM traded until then.
            self._state_owner = str(data.get("account_key_id")
                                    or imm_account.fleet_key_id())
            self.state.known_tickers = set(data.get("known_tickers") or [])
            self.state.last_fill_ts = int(data.get("last_fill_ts") or 0)
            self.state.seen_fill_ids = {str(k): int(v) for k, v in
                                        (data.get("seen_fill_ids") or {}).items()}
            self.state.our_order_ids = {str(k): float(v) for k, v in
                                        (data.get("our_order_ids") or {}).items()}
            # The bot's own net book (positions AND entry costs), rebuilt so
            # manual-vs-bot divergence and mark-to-market both survive
            # restarts (realized P&L still resets).
            for t, p in (data.get("own_pos") or {}).items():
                self.pnl.pos[str(t)] = float(p)
            for t, a in (data.get("own_avg") or {}).items():
                self.pnl.avg[str(t)] = float(a)
            for t, v in (data.get("own_filled") or {}).items():
                try:
                    self.pnl.filled[str(t)] = float(v)
                except (TypeError, ValueError):
                    pass
            # SEED FROM INVENTORY (Jack 2026-09-09 "Seed own_filled from
            # |own_pos| on load"). `filled` was born with 3e91438 and started
            # at ZERO for every market that traded before it, so the earned-
            # slot rule read heavily worked slot-holders as never traded:
            # KXDIESELW-26SEP14 released T5.84/T5.86/T5.92 as "filled 0 < 6"
            # while holding -65/-72/-40 in them, refilled the slots with
            # T6.00/T6.02/T6.04, and ended the day with inventory in EIGHT
            # strikes of one weekly. A market holding N contracts has filled
            # at least N — a lower bound, never a reduction — so a counter
            # can never again read below the position it is carrying,
            # whatever state file this process inherits.
            for t, p in self.pnl.pos.items():
                if abs(p) > self.pnl.filled.get(t, 0.0):
                    self.pnl.filled[t] = abs(p)
            self.state.reward_est_lifetime = float(data.get("reward_est_lifetime") or 0.0)
            # realized_seen deliberately NOT restored: the tracker starts empty
            self.state.realized_lifetime = float(data.get("realized_lifetime") or 0.0)
            self.state.reward_history = {str(k): float(v) for k, v in
                                         (data.get("reward_history") or {}).items()}
            self.state.reward_paid_lifetime = float(
                data.get("reward_paid_lifetime") or 0.0)
            self.state.reward_paid_history = {str(k): float(v) for k, v in
                                              (data.get("reward_paid_history") or {}).items()}
            # Which markets already cleared the $1 floor MUST persist with
            # accrued_est: restoring the accrual without it would re-credit
            # every carried market's whole backlog on the first cycle after a
            # restart, inflating the paid basis by ~one full book per restart.
            self.state.paid_crossed = set(data.get("paid_crossed") or [])
            # Daily reward/contract-minutes survive restarts within the SAME
            # roll day (2026-08-03 fix): without this every restart zeroed the
            # counter the digest reports.
            if data.get("reward_day_key") == _halt_day_key(datetime.now(timezone.utc)):
                self.state.reward_est_today = float(data.get("reward_est_today") or 0.0)
                self.state.reward_paid_today = float(data.get("reward_paid_today") or 0.0)
                self.state.contract_minutes_today = float(
                    data.get("contract_minutes_today") or 0.0)
                if self.state.reward_est_today:
                    log(f"{self.tag} restored est reward today "
                        f"${self.state.reward_est_today:.2f} raw / "
                        f"${self.state.reward_paid_today:.2f} paid-basis "
                        f"(same roll-day restart)")
            self.state.sticky_prev = set(data.get("selected_tickers") or [])
            # Peak-entry memory survives restarts: it's in-memory otherwise, and
            # this bot restarts often (launcher-env changes, hang-watchdog), so
            # every restart used to wipe the 1h peak and make borderline markets
            # re-clear the floor from scratch for an hour. The read is already
            # TTL-guarded, so stale entries are harmless.
            self._est_peak = {str(t): (float(v[0]), float(v[1]))
                              for t, v in (data.get("est_peak") or {}).items()
                              if isinstance(v, (list, tuple)) and len(v) == 2}
            # Per-market accrued reward estimate: the hopeless-exit / entry
            # credit must survive restarts or every restart would re-evict
            # (or re-floor) markets that already banked most of their $1.
            self.state.accrued_est = {str(t): float(v) for t, v in
                                      (data.get("accrued_est") or {}).items()}
            self.state.period_start = {str(t): str(v) for t, v in
                                       (data.get("period_start") or {}).items()}
            self.state.period_base = {str(t): float(v) for t, v in
                                      (data.get("period_base") or {}).items()}
            self.state.hopeless_since = {str(t): float(v) for t, v in
                                         (data.get("hopeless_since") or {}).items()}
            self.state.admit_run = {
                str(t): [float(v[0]), float(v[1])]
                for t, v in (data.get("admit_run") or {}).items()
                if isinstance(v, (list, tuple)) and len(v) == 2}
            self._loaded_credit = (set(self.state.accrued_est)
                                   | set(self.state.period_base)
                                   | set(self.state.period_start)
                                   | set(self.state.hopeless_since)
                                   | set(self.state.admit_run))
            # finecon openings: day mismatch is resolved at refresh (reset),
            # so restore unconditionally here
            self.state.finecon_admit_day = str(data.get("finecon_admit_day") or "")
            self.state.finecon_admits_today = int(
                data.get("finecon_admits_today") or 0)
            # open-scan tier (2026-09-05): membership, caches, counters. The
            # guard geometry is re-applied for every persisted member's
            # series RIGHT HERE, before any cycle can size a ladder — a
            # restart must never leave a scan member on the global shape
            # (the allowed-but-unguarded class, in restart form).
            self.state.scan_admit_day = str(data.get("scan_admit_day") or "")
            self.state.scan_admits_today = int(data.get("scan_admits_today") or 0)
            self.state.scan_members = set(data.get("scan_members") or [])
            self.state.scan_book = (set(data.get("scan_book") or [])
                                    | self.state.scan_members)
            self.state.scan_entry_mid = {
                str(t): float(v)
                for t, v in (data.get("scan_entry_mid") or {}).items()}
            for _s, _v in (data.get("no_cutoff_mention_gate") or {}).items():
                try:
                    _DYNAMIC_DEPTH_GATE[str(_s)] = float(_v)
                except (TypeError, ValueError):
                    pass
            self.state.event_slots = {
                str(e): {"markets": [str(x) for x in (v.get("markets") or [])],
                         "ts": float(v.get("ts") or 0.0)}
                for e, v in (data.get("event_slots") or {}).items()
                if isinstance(v, dict)}
            if EVENT_TOP_N_LIFETIME and not self.state.event_slots:
                # First run on a state file written before the lifetime
                # ledger existed. Seed it from the persisted selection:
                # those markets HAVE spent their slots (they are quoting and
                # carrying inventory), and starting empty would hand every
                # capped event a fresh budget on every upgrade or restart —
                # the exact "kept admitting replacements" the ledger exists
                # to stop. Positions are deliberately NOT used as the seed:
                # an event the bot churned through before today can hold
                # inventory in more than N markets, and seeding that would
                # start the ledger already over its own cap.
                for _t in sorted(self.state.sticky_prev):
                    if event_top_n_for(series_of(_t)) <= 0:
                        continue
                    _e = "-".join(_t.split("-")[:2])
                    _s = self.state.event_slots.setdefault(
                        _e, {"markets": [], "ts": time.time()})
                    if _t not in _s["markets"]:
                        _s["markets"].append(_t)
                if self.state.event_slots:
                    log(f"{self.tag} seeded lifetime event slots from the "
                        f"persisted selection: {len(self.state.event_slots)} "
                        f"events, "
                        f"{sum(len(v['markets']) for v in self.state.event_slots.values())}"
                        f" markets")
            self.state.scan_evicted_events = {
                str(e): float(v)
                for e, v in (data.get("scan_evicted_events") or {}).items()}
            self.state.scan_hopeless_barred = {
                str(t): float(v)
                for t, v in (data.get("scan_hopeless_barred") or {}).items()}
            self.state.scan_series_strikes = {
                str(s): [float(x) for x in v]
                for s, v in (data.get("scan_series_strikes") or {}).items()
                if isinstance(v, list)}
            self.state.scan_history_cache = {
                str(t): dict(v)
                for t, v in (data.get("scan_history_cache") or {}).items()
                if isinstance(v, dict)}
            self.state.scan_series_meta = {
                str(s): dict(v)
                for s, v in (data.get("scan_series_meta") or {}).items()
                if isinstance(v, dict)}
            self.state.scan_halt_day = str(data.get("scan_halt_day") or "")
            self.state.yt2_halt_day = str(data.get("yt2_halt_day") or "")
            self.state.yt2_fill_pause_until = {
                str(e): float(v)
                for e, v in (data.get("yt2_fill_pause_until") or {}).items()}
            self.state.astest_fill_pause_until = {
                str(e): float(v)
                for e, v in (data.get("astest_fill_pause_until") or {}).items()}
            self.state.ytw_halt_day = str(data.get("ytw_halt_day") or "")
            self.state.twk_halt_day = {
                str(k): str(v) for k, v in (data.get("twk_halt_day") or {}).items()}
            for _t in sorted(self.state.scan_book):
                ensure_scan_override(series_of(_t))
            # MIGRATION (2026-08-04, first load after the paid-basis counters
            # shipped): a state file written by the old code has accrued_est
            # but no paid_crossed, so every carried market sitting above the
            # floor would "cross" on the first cycle and dump its entire
            # backlog — accrued over days, already counted in the raw
            # counters — into TODAY's paid figure. Adopt their crossed status
            # silently instead; only accrual from here forward counts.
            if "paid_crossed" not in data:
                self.state.paid_crossed = {
                    t for t, v in self.state.accrued_est.items()
                    if v >= PAYOUT_FLOOR_DOLLARS}
                if self.state.paid_crossed:
                    log(f"{self.tag} paid-basis migration: adopted "
                        f"{len(self.state.paid_crossed)} market(s) already over "
                        f"${PAYOUT_FLOOR_DOLLARS:.2f} without back-crediting")
            # rain-directional once-per-market dedupe must survive restarts
            # (this bot restarts often) or every restart would re-take the
            # same divergent books.
            self.state.rain_dir_done = {str(t): float(v) for t, v in
                                        (data.get("rain_dir_done") or {}).items()}
            # Live-event depth halts survive restarts: this bot restarts many
            # times a day, and a restart mid-speech must not spend a cycle
            # quoting the deep strikes before rediscovering the thin one.
            self.state.event_depth_halt = {str(e): float(v) for e, v in
                                           (data.get("event_depth_halt") or {}).items()}
            # ...and permanent live confirms + the gated-series mid history
            # the jump detector needs to keep confirming across a restart.
            self.state.event_live_halt = {str(e): float(v) for e, v in
                                          (data.get("event_live_halt") or {}).items()}
            self.state.event_fill_strikes = {
                str(e): int(v) for e, v in
                (data.get("event_fill_strikes") or {}).items()}
            self.state.event_fill_strike_ts = {
                str(e): float(v) for e, v in
                (data.get("event_fill_strike_ts") or {}).items()}
            self.state.event_depth_ignore = {
                str(e): [str(t) for t in (v or [])] for e, v in
                (data.get("event_depth_ignore") or {}).items()}
            # a halt persisted before the ignore set existed keeps the old
            # rule (every strike must be healthy): its out-of-band strikes may
            # have SETTLED during the halt, which must still hold it down
            for _e in self.state.event_depth_halt:
                self.state.event_depth_ignore.setdefault(_e, [])
            self.state.prev_mid.update(
                {str(t): float(v) for t, v in
                 (data.get("prev_mid_gated") or {}).items()})
            # toxic-flow side halt: a restart must not forget a halted side
            # or the pick-offs that are one short of halting it
            self.state.toxic_pending = [
                [str(p[0]), str(p[1]), float(p[2]), float(p[3])]
                for p in (data.get("toxic_pending") or []) if len(p) >= 4]
            self.state.toxic_picks = {
                str(k): [float(x) for x in v]
                for k, v in (data.get("toxic_picks") or {}).items()}
            self.state.toxic_halt_until = {
                str(k): float(v)
                for k, v in (data.get("toxic_halt_until") or {}).items()}
            self.state.toxic_event_picks = {
                str(e): [[float(p[0]), str(p[1])] for p in v if len(p) >= 2]
                for e, v in (data.get("toxic_event_picks") or {}).items()}
            self.state.toxic_event_halt_until = {
                str(e): float(v)
                for e, v in (data.get("toxic_event_halt_until") or {}).items()}
            # bait-fingerprint stops: a restart keeps the day's stops
            self.state.bait_side_until = {
                str(k): float(v)
                for k, v in (data.get("bait_side_until") or {}).items()}
            self.state.bait_event_until = {
                str(e): float(v)
                for e, v in (data.get("bait_event_until") or {}).items()}
            # every other breaker / hold still running (GUARDS ACROSS RESTARTS)
            try:
                self._restore_guard_holds(data)
            except Exception as e:                   # noqa: BLE001 - the rest restores
                log(f"{self.tag} ! guard holds restore failed ({e!r}); the rest restores")
            # the ladder asks' cash switch (SPORTS_LADDER_ASKS_ON_CASH / _OFF_CASH)
            self.state.ladder_asks_on_at = float(data.get("ladder_asks_on_at") or 0.0)
            # Halt continuity (same roll-day only): a restart must NOT hand
            # the bot a fresh loss budget or clear an active halt. Use
            # --clear-halt (bot stopped) for a deliberate un-halt.
            if data.get("halt_day_key") == _halt_day_key(datetime.now(timezone.utc)):
                self.state.pnl_carry = float(data.get("pnl_today_carry") or 0.0)
                self.state.halted_until = float(data.get("halted_until") or 0.0)
                self.state.account_value_day_start = float(
                    data.get("account_value_day_start") or 0.0)
                # open-scan tier P&L carry (same roll-day rule as pnl_carry)
                self.state.scan_pnl_carry = float(data.get("scan_pnl_carry") or 0.0)
                # YouTube #2 pilot P&L carry (2026-10-05), same rule
                self.state.yt2_pnl_carry = float(data.get("yt2_pnl_carry") or 0.0)
                self.state.ytw_pnl_carry = float(data.get("ytw_pnl_carry") or 0.0)
                self.state.twk_pnl_carry = {
                    str(k): float(v or 0.0)
                    for k, v in (data.get("twk_pnl_carry") or {}).items()}
                if self.state.halted_until > time.time():
                    log(f"{self.tag} restored ACTIVE daily-loss halt "
                        f"(pnl carry ${self.state.pnl_carry:+.2f})")
                elif abs(self.state.pnl_carry) > 0.005:
                    log(f"{self.tag} restored pnl_today carry "
                        f"${self.state.pnl_carry:+.2f} (same roll-day restart)")
            if self.state.known_tickers:
                log(f"{self.tag} restored {len(self.state.known_tickers)} known tickers")
        except FileNotFoundError:
            pass
        except Exception as e:
            log(f"{self.tag} ! state restore failed ({e}); starting fresh")
        # After the main file (or its absence): fold in ids the previous run
        # journaled but never got to fold in itself.
        self._load_journal()

    def _fold_realized(self) -> None:
        """Accumulate the tracker's realized delta into the persistent
        lifetime counter (see BotState.realized_lifetime). Called on every
        save so a hard kill loses at most one cycle of realizations."""
        total = self.pnl.total_realized()
        delta = total - self.state.realized_seen
        if abs(delta) > 1e-9:
            self.state.realized_lifetime += delta
            self.state.realized_seen = total
        # Per-MARKET realized, appended as deltas. self.pnl.realized is the
        # right object and has always existed, but it is collapsed into one
        # lifetime scalar here and dies with the process ~20 times a day, so
        # "which markets earn credits but lose money on the position" has
        # never had a per-market answer on our own book. Append-only deltas
        # mean pruning the live dict stays safe.
        try:
            for tkr, val in self.pnl.realized.items():
                prev = self._realized_by_ticker.get(tkr, 0.0)
                d = val - prev
                if abs(d) <= 1e-9:
                    continue
                self._realized_by_ticker[tkr] = val
                self._sink("realized", {
                    "ts": datetime.now(timezone.utc).isoformat(),
                    "ticker": tkr, "series": series_of(tkr),
                    "event_ticker": self._event_of(tkr),
                    "realized_delta_dollars": round(d, 6),
                    "realized_total_dollars": round(val, 6),
                    "pos_after": self.pnl.pos.get(tkr, 0.0),
                    "avg_after": self.pnl.avg.get(tkr, 0.0),
                })
        except Exception as e:
            if "realized" not in self._sink_muted:
                self._sink_muted.add("realized")
                log(f"{self.tag} ! realized sink failed ({e}); muted this run")

    def _keeps_accrual(self, t: str) -> bool:
        """Persist this market's per-period credit (accrued_est, period_base,
        period_start, hopeless_since, paid_crossed)? Always while it is
        quoted or held (known_tickers); since 2026-09-25 also while its LIVE
        program period is still running (KEEP_ACCRUAL_WHILE_PROGRAMMED) --
        the counter is what lets a flat evicted market re-enter on its
        banked accrual, and once pruned it is gone for good. With NO feed
        read yet this run (`programmed` empty: startup before the first
        refresh, or a failed read) the counters the file already held are
        kept -- a feed outage must never look like every program ended --
        while a counter born in memory this run still prunes with
        known_tickers, as before."""
        if t in self.state.known_tickers:
            return True
        if not KEEP_ACCRUAL_WHILE_PROGRAMMED:
            return False
        if self.state.programmed:
            return t in self.state.programmed
        return t in self._loaded_credit

    def _order_id_horizon(self) -> float:
        """The oldest placement time our_order_ids keeps (ORDER_ID_KEEP_HOURS):
        that long before the fills cursor, which a sleep or an outage leaves
        where it was -- or before now, when there is no cursor yet or it
        reads ahead of this clock."""
        now = time.time()
        cursor = float(self.state.last_fill_ts or 0)
        anchor = min(now, cursor) if cursor > 0 else now
        return anchor - max(ORDER_ID_KEEP_HOURS * 3600.0, ORDER_TTL_SECS + 7200.0)

    def _strike_kept(self, ev: str) -> bool:
        """A fill-burst strike the state file keeps: its halt still runs, or
        it still counts toward the live confirm (EVENT_FILL_STRIKE_TTL_SECS;
        0 = strikes never expire, kept a week)."""
        if ev in self.state.event_depth_halt or ev in self.state.event_live_halt:
            return True
        ts = self.state.event_fill_strike_ts.get(ev)
        if ts is None:
            return False
        ttl = EVENT_FILL_STRIKE_TTL_SECS if EVENT_FILL_STRIKE_TTL_SECS > 0 else 7 * 86400
        return time.time() - ts <= ttl

    def _guard_holds_payload(self) -> dict:
        """The state file's breakers and holds still running (GUARDS ACROSS
        RESTARTS): {key: until} maps, the sweep escalation chains and the
        fairs' moved_at holds."""
        now = time.time()

        def live(d: dict) -> dict:
            return {str(k): round(float(v), 1) for k, v in d.items() if float(v) > now}
        return {
            "breaker_until": live(self.state.breaker_until),
            "bench_until": live(self.state.bench_until),
            "sweep_until": live(self._sweep_until),
            "sweep_hold": live(self._sweep_hold),
            "sweep_esc": {str(k): {"n": int(s["n"]), "hold_until": round(float(s["hold_until"]), 1),
                                   "reset_at": round(float(s["reset_at"]), 1)}
                          for k, s in self._sweep_esc.items() if float(s["reset_at"]) > now},
            "grp_hold": {"\t".join(k): round(float(v), 1)
                         for k, v in self._grp_hold.items() if float(v) > now},
            "fair_moved_at": {name: {str(k): round(float(v), 1)
                                     for k, v in st["moved_at"].items()
                                     if now - float(v) < FAIR_MOVED_KEEP_SECS}
                              for name, st in _fair_hold_states()},
        }

    def _restore_guard_holds(self, data: dict) -> None:
        """Put back what _guard_holds_payload saved, skipping what has run
        out; a bad entry is logged and skipped, never fatal to the restore."""
        now = time.time()
        n: Dict[str, int] = {}
        for name, d in (("breaker_until", self.state.breaker_until),
                        ("bench_until", self.state.bench_until),
                        ("sweep_until", self._sweep_until),
                        ("sweep_hold", self._sweep_hold)):
            for k, v in (data.get(name) or {}).items():
                try:
                    if float(v) > now:
                        d[str(k)] = max(float(v), float(d.get(str(k), 0.0)))
                        n[name] = n.get(name, 0) + 1
                except (TypeError, ValueError):
                    log(f"{self.tag} ! state file: bad {name} entry {k!r}: {v!r}")
        for k, s in (data.get("sweep_esc") or {}).items():
            try:
                if float(s["reset_at"]) > now:
                    self._sweep_esc[str(k)] = {"n": int(s["n"]), "hold_until": float(s["hold_until"]),
                                               "reset_at": float(s["reset_at"])}
                    n["sweep_esc"] = n.get("sweep_esc", 0) + 1
            except (KeyError, TypeError, ValueError):
                log(f"{self.tag} ! state file: bad sweep_esc entry {k!r}: {s!r}")
        for k, v in (data.get("grp_hold") or {}).items():
            try:
                if float(v) > now and "\t" in k:
                    self._grp_hold[tuple(k.split("\t", 1))] = float(v)
                    n["grp_hold"] = n.get("grp_hold", 0) + 1
            except (TypeError, ValueError):
                log(f"{self.tag} ! state file: bad grp_hold entry {k!r}: {v!r}")
        moved = data.get("fair_moved_at") or {}
        for name, st in _fair_hold_states():
            for k, v in (moved.get(name) or {}).items():
                try:
                    if now - float(v) < FAIR_MOVED_KEEP_SECS:
                        st["moved_at"][str(k)] = max(float(v), float(st["moved_at"].get(str(k), 0.0)))
                        n[f"{name}_moved"] = n.get(f"{name}_moved", 0) + 1
                except (TypeError, ValueError):
                    log(f"{self.tag} ! state file: bad {name} moved_at entry {k!r}: {v!r}")
        strikes = sum(1 for e in self.state.event_fill_strikes if e not in self.state.event_depth_halt
                      and e not in self.state.event_live_halt)
        if strikes:
            n["fill_strikes_after_resume"] = strikes
        if n:
            log(f"{self.tag} restored guards still running across the restart: "
                + ", ".join(f"{k} {v}" for k, v in sorted(n.items())))

    def _save_persist(self) -> bool:
        """Write the state file; True when it was written."""
        try:
            self._fold_realized()
            os.makedirs(STATUS_DIR, exist_ok=True)
            tmp = self.PERSIST_PATH + ".tmp"
            # Bound our_order_ids to the orders whose fills may still be
            # unread (_order_id_horizon): an order fills only while it rests.
            horizon = self._order_id_horizon()
            self.state.our_order_ids = {k: v for k, v in self.state.our_order_ids.items()
                                        if v >= horizon}
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump({"account_key_id": self._state_owner,
                           "known_tickers": sorted(self.state.known_tickers),
                           "selected_tickers": sorted(set(self.state.selected)
                                                      | self.state.sticky_prev),
                           "last_fill_ts": self.state.last_fill_ts,
                           "seen_fill_ids": self.state.seen_fill_ids,
                           "our_order_ids": self.state.our_order_ids,
                           "own_pos": {t: p for t, p in self.pnl.pos.items()
                                       if abs(p) > 1e-9},
                           "own_avg": {t: self.pnl.avg.get(t, 0.0)
                                       for t, p in self.pnl.pos.items()
                                       if abs(p) > 1e-9},
                           # gross contracts ever filled per market; the
                           # lifetime slot rule reads it (2026-09-09)
                           "own_filled": {t: round(v, 2)
                                          for t, v in self.pnl.filled.items()
                                          if v > 0},
                           "reward_est_lifetime": self.state.reward_est_lifetime,
                           # lifetime realized trading P&L incl. settlements
                           "realized_lifetime": round(self.state.realized_lifetime, 4),
                           # daily reward must survive restarts (see BotState):
                           # anchored to the roll day so a NEW day starts clean
                           "reward_day_key": _halt_day_key(datetime.now(timezone.utc)),
                           "reward_est_today": round(self.state.reward_est_today, 4),
                           "reward_paid_today": round(self.state.reward_paid_today, 4),
                           "reward_paid_lifetime": round(
                               self.state.reward_paid_lifetime, 4),
                           "contract_minutes_today": round(
                               self.state.contract_minutes_today, 1),
                           # 60 days kept: the digest's daily table shows every
                           # prior day that earned (Jack 2026-08-03)
                           "reward_history": {k: round(v, 2) for k, v in sorted(
                               self.state.reward_history.items())[-60:]},
                           "reward_paid_history": {k: round(v, 2) for k, v in sorted(
                               self.state.reward_paid_history.items())[-60:]},
                           "halt_day_key": _halt_day_key(datetime.now(timezone.utc)),
                           "pnl_today_carry": round(self.state.pnl_today_last, 2),
                           "halted_until": self.state.halted_until,
                           "account_value_day_start": round(self.state.account_value_day_start, 2),
                           "ladder_asks_on_at": self.state.ladder_asks_on_at,
                           # peak-entry memory, pruned to TTL so it stays bounded
                           "est_peak": {t: [round(v[0], 4), round(v[1], 1)]
                                        for t, v in self._est_peak.items()
                                        if time.time() - v[1] <= EST_PEAK_TTL_SECS},
                           # accrued-est credit, pruned with known_tickers so
                           # settled markets don't grow it unboundedly -- but
                           # KEPT while the live program period runs
                           # (_keeps_accrual, 2026-09-25)
                           "accrued_est": {t: round(v, 4)
                                           for t, v in self.state.accrued_est.items()
                                           if v >= 1e-4
                                           and self._keeps_accrual(t)},
                           # pruned on the SAME rule as accrued_est — a
                           # ticker that drops out of one must drop out of
                           # both, or a re-listed market would measure this
                           # period against a baseline from its last life
                           "period_start": {
                               t: v for t, v in self.state.period_start.items()
                               if self._keeps_accrual(t)},
                           "period_base": {
                               t: round(v, 4)
                               for t, v in self.state.period_base.items()
                               if self._keeps_accrual(t)},
                           # the sub-bar clock must survive restarts or this
                           # bot's ~20 deploys/day would keep resetting it and
                           # the hopeless exit could never fire at all
                           "hopeless_since": {
                               t: round(v, 1)
                               for t, v in self.state.hopeless_since.items()
                               if self._keeps_accrual(t)},
                           # the admission / clock-reset run (2026-09-27),
                           # same pruning as the clock it gates
                           "admit_run": {
                               t: [round(v[0], 1), round(v[1], 1)]
                               for t, v in self.state.admit_run.items()
                               if self._keeps_accrual(t)},
                           # pruned on the SAME rule as accrued_est: a ticker
                           # that drops out of one must drop out of the other,
                           # or a re-listed ticker resumes "already paid"
                           "paid_crossed": sorted(
                               t for t in self.state.paid_crossed
                               if self._keeps_accrual(t)),
                           "rain_dir_done": {t: round(v, 1)
                                             for t, v in self.state.rain_dir_done.items()
                                             if time.time() - v < 7 * 86400},
                           # finecon daily-openings counter: restart-proof
                           # or every deploy would refill the day's 5
                           "finecon_admit_day": self.state.finecon_admit_day,
                           "finecon_admits_today": self.state.finecon_admits_today,
                           # open-scan tier (2026-09-05)
                           "scan_admit_day": self.state.scan_admit_day,
                           "scan_admits_today": self.state.scan_admits_today,
                           "scan_members": sorted(self.state.scan_members),
                           # the loss-budget book: every market the tier
                           # admitted, kept WHOLE until the daily roll — a
                           # settlement loss booked on a flat evicted market
                           # must stay in today's tier P&L, not vanish at the
                           # next save (pruned in build_daily_summary)
                           "scan_book": sorted(self.state.scan_book),
                           "scan_entry_mid": {
                               t: round(v, 1)
                               for t, v in self.state.scan_entry_mid.items()
                               if t in self.state.scan_members},
                           # lifetime slots: age-pruned ONLY (a quiet event
                           # must never get its cap back — see EVENT_TOP_N)
                           "no_cutoff_mention_gate": {
                               s: round(v, 1) for s, v in _DYNAMIC_DEPTH_GATE.items()
                               if time.time() - v <= MENTION_NO_CUTOFF_TTL_SECS},
                           "event_slots": {
                               e: {"markets": v["markets"],
                                   "ts": round(v["ts"], 1)}
                               for e, v in self.state.event_slots.items()
                               if time.time() - v["ts"] < EVENT_SLOTS_TTL_SECS},
                           # permanent for the event; the TTL is file hygiene
                           "scan_evicted_events": {
                               e: round(v, 1)
                               for e, v in self.state.scan_evicted_events.items()
                               if time.time() - v < SCAN_EVICT_TTL_SECS},
                           # permanent for the market; TTL is file hygiene
                           "scan_hopeless_barred": {
                               t: round(v, 1)
                               for t, v in self.state.scan_hopeless_barred.items()
                               if time.time() - v < SCAN_EVICT_TTL_SECS},
                           "scan_series_strikes": {
                               s: [round(x, 1) for x in v
                                   if time.time() - x < SCAN_SERIES_STRIKE_TTL_SECS]
                               for s, v in self.state.scan_series_strikes.items()
                               if any(time.time() - x < SCAN_SERIES_STRIKE_TTL_SECS
                                      for x in v)},
                           "scan_history_cache": {
                               t: v for t, v in self.state.scan_history_cache.items()
                               if time.time() - float(v.get("ts", 0))
                               < SCAN_HISTORY_TTL_SECS},
                           "scan_series_meta": {
                               s: v for s, v in self.state.scan_series_meta.items()
                               if time.time() - float(v.get("ts", 0))
                               < SCAN_SERIES_META_TTL_SECS},
                           "scan_halt_day": self.state.scan_halt_day,
                           "scan_pnl_carry": round(self.state.scan_pnl_today_last, 2),
                           "yt2_halt_day": self.state.yt2_halt_day,
                           "yt2_pnl_carry": round(self.state.yt2_pnl_today_last, 2),
                           # a snapshot: the WS thread adds pauses
                           "yt2_fill_pause_until": {
                               e: round(v, 1)
                               for e, v in list(self.state.yt2_fill_pause_until.items())
                               if v > time.time()},
                           "astest_fill_pause_until": {
                               e: round(v, 1)
                               for e, v in list(self.state.astest_fill_pause_until.items())
                               if v > time.time()},
                           "ytw_halt_day": self.state.ytw_halt_day,
                           "ytw_pnl_carry": round(self.state.ytw_pnl_today_last, 2),
                           "twk_halt_day": dict(self.state.twk_halt_day),
                           "twk_pnl_carry": {k: round(v, 2) for k, v in
                                             self.state.twk_pnl_today_last.items()},
                           # live-event depth halts (pruned with the same 7d
                           # TTL: mention events settle within a day, this
                           # just stops dead events accreting)
                           "event_depth_halt": {
                               e: round(v, 1)
                               for e, v in self.state.event_depth_halt.items()
                               if time.time() - v < 7 * 86400},
                           # permanent live confirms — "forever" in practice
                           # means until settlement, so the 7d TTL is pure
                           # file hygiene, never an early release
                           "event_live_halt": {
                               e: round(v, 1)
                               for e, v in self.state.event_live_halt.items()
                               if time.time() - v < 7 * 86400},
                           # fill-tripwire strikes: while their halt runs AND
                           # for their TTL after it (a resumed event's strike
                           # still counts toward the live confirm)
                           "event_fill_strikes": {
                               e: n
                               for e, n in self.state.event_fill_strikes.items()
                               if self._strike_kept(e)},
                           "event_fill_strike_ts": {
                               e: round(v, 1)
                               for e, v in self.state.event_fill_strike_ts.items()
                               if e in self.state.event_fill_strikes
                               and self._strike_kept(e)},
                           "event_depth_ignore": {
                               e: sorted(v)
                               for e, v in self.state.event_depth_ignore.items()
                               if e in self.state.event_depth_halt},
                           # gated-series mid history: the settled-strike
                           # jump detector needs prev_mid ACROSS restarts, or
                           # a strike that jumps to 99c during the seconds a
                           # restart takes would look "always pinned" to the
                           # new process and confirm nothing
                           "prev_mid_gated": {
                               t: round(v, 1)
                               for t, v in self.state.prev_mid.items()
                               if series_event_depth_gated(series_of(t))},
                           # toxic-flow side halt (TOXIC_*): pending checks,
                           # confirmed pick-offs inside the window, live halts
                           "toxic_pending": [
                               p for p in self.state.toxic_pending
                               if time.time() - p[3] <= TOXIC_CONFIRM_SECS
                               + TOXIC_MAX_LATE_SECS],
                           "toxic_picks": {
                               k: [round(x, 1) for x in v
                                   if time.time() - x <= TOXIC_WINDOW_SECS]
                               for k, v in self.state.toxic_picks.items()
                               if any(time.time() - x <= TOXIC_WINDOW_SECS
                                      for x in v)},
                           "toxic_halt_until": {
                               k: round(v, 1)
                               for k, v in self.state.toxic_halt_until.items()
                               if v > time.time()},
                           "toxic_event_picks": {
                               e: [[round(p[0], 1), p[1]] for p in v
                                   if time.time() - p[0] <= TOXIC_EVENT_WINDOW_SECS]
                               for e, v in self.state.toxic_event_picks.items()
                               if any(time.time() - p[0] <= TOXIC_EVENT_WINDOW_SECS
                                      for p in v)},
                           "toxic_event_halt_until": {
                               e: round(v, 1)
                               for e, v in self.state.toxic_event_halt_until.items()
                               if v > time.time()},
                           "bait_side_until": {
                               k: round(v, 1)
                               for k, v in self.state.bait_side_until.items()
                               if v > time.time()},
                           "bait_event_until": {
                               e: round(v, 1)
                               for e, v in self.state.bait_event_until.items()
                               if v > time.time()},
                           # every other breaker / hold still running
                           # (GUARDS ACROSS RESTARTS)
                           **self._guard_holds_payload()}, f)
            os.replace(tmp, self.PERSIST_PATH)
            # Journal contents are now in the main file; truncate so a later
            # crash-load doesn't re-merge stale (already-pruned) ids.
            try:
                open(self.ORDER_JOURNAL_PATH, "w", encoding="utf-8").close()
            except OSError:
                pass
            return True
        except Exception as e:
            log(f"{self.tag} ! state save failed: {e}")
            return False

    # ---- exchange wrappers (writes gated on self.live) ----------------------

    def place_order(self, q: Quote, now_ts: float) -> bool:
        self._heartbeat = time.time()      # see cancel_order heartbeat note
        client_order_id = f"{CLIENT_ORDER_PREFIX}-{RUN_ID}-{uuid.uuid4().hex[:12]}"
        expiration_ts = int(time.time() + ORDER_TTL_SECS)   # stamped per-send
        # Never let an order outlive the market's event-start cutoff: the
        # exchange enforces the user's hard rule even if this process dies.
        cutoff_ts = self.state.cutoff_ts.get(q.ticker)
        if cutoff_ts is not None:
            expiration_ts = min(expiration_ts, int(cutoff_ts))
            if expiration_ts <= time.time() + 1:
                log(f"{self.tag} not placing {q.ticker} {q.book_side}: cutoff reached")
                return False
        if q.book_side == "bid":
            kwargs = dict(side="yes", action="buy", yes_price=q.price_cents)
        else:
            kwargs = dict(side="no", action="buy", no_price=100 - q.price_cents)
        kwargs["self_trade_prevention_type"] = STP_TYPE   # user's order wins a self-cross
        if q.price_exact is not None:
            # sub-penny join: the wire price is the exact YES price (4 dp);
            # the integer bucket above still drives side/ledger/caps
            kwargs["price_dollars"] = f"{q.price_exact / 100.0:.4f}"
        label = (f"{q.ticker} {q.book_side.upper():4s} {q.count}x @ "
                 + (f"{q.price_exact:.2f}c" if q.price_exact is not None
                    else f"{q.price_cents}c"))
        if q.book_side == "ask" and quake_gated(series_of(q.ticker)):
            # far-strike quake ask (QUAKE_ASK_STRIKES): the verdict again, at
            # the last moment (a quake may have landed since the cycle quoted
            # it), and the short exchange-side expiry
            floor, why = quake_ask_floor(q.ticker, time.time())
            px = q.price_exact if q.price_exact is not None else q.price_cents
            if floor is None or px < floor - 1e-9:
                log(f"{self.tag} not placing {label}: quake ask "
                    + (f"off ({why})" if floor is None else f"under the {floor}c floor"))
                return False
            expiration_ts = min(expiration_ts, int(time.time() + QUAKE_ASK_TTL_SECS))
        if not self.live:
            oid = f"sim-{uuid.uuid4().hex[:12]}"
            self.state.sim_orders[oid] = {
                "order_id": oid, "ticker": q.ticker, "book_side": q.book_side,
                "yes_price": q.price_cents, "remaining_count": float(q.count),
                "yes_price_exact": q.price_exact,
                "status": "resting", "client_order_id": client_order_id,
                "expire_at": float(expiration_ts),
            }
            self.state.order_ages[oid] = now_ts
            log(f"{self.tag} [DRY] place {label}")
            return True
        if self._xp and self._xp_hold(q.ticker, time.time()):
            return False       # its shard is paused (EXCH_PAUSE_MODE): not sent
        if self._cash_pause and self._cash_waiting(q, time.time()):
            return False       # its shard just refused one this costly for cash
        try:
            resp = self.client.create_order(
                ticker=q.ticker, client_order_id=client_order_id,
                count=q.count, type="limit", post_only=True,
                expiration_ts=expiration_ts, **kwargs)
            oid = (resp.get("order") or {}).get("order_id") or resp.get("order_id", "?")
            self.state.order_ages[oid] = now_ts
            self.state.our_order_ids[oid] = now_ts   # fills are matched by ownership
            self.state.ledger[oid] = {
                "order_id": oid, "ticker": q.ticker, "book_side": q.book_side,
                "yes_price": q.price_cents, "remaining_count": float(q.count),
                "yes_price_exact": q.price_exact,
                "status": "resting", "client_order_id": client_order_id,
                "_placed_at": now_ts, "_confirmed": False,
            }
            self._join_set(oid, q.ticker, q.book_side, q.price_cents,
                           q.price_exact, float(q.count), client_order_id, now_ts)
            log(f"{self.tag} placed {label} -> {oid}")
            if self._xp:
                self._xp_ok(q.ticker, "place")
            self._log_order("place", q.ticker, q.book_side, q.price_cents,
                            q.count, oid, now_ts,
                            client_order_id=client_order_id,
                            quote_is_pad=q.is_pad,
                            yes_price_exact=q.price_exact,
                            expiration_ts=expiration_ts)
            # Durable PER ORDER, but cheap: append the id to a journal (<1ms)
            # instead of dumping the full ~3.4MB state (~450ms) — a hard-kill
            # mid-wave orphaned 3 fills on unsaved ids (2026-07-19, ~19:22Z
            # restart) and the false "manual" standoffs cost CONNPHX its
            # evening. _save_persist folds the journal in and truncates it.
            if self.live:
                self._journal_order_id(oid, now_ts)
            return True
        except HttpError as e:
            # A definitive rejection (post-only would cross, etc.) — no order exists.
            # KALSHI'S REASON (2026-10-04, Jack: "why is this happening? I have
            # enough cash"): the client keeps the response body on the error
            # (e.body) -- "post only cross" and a short balance are both a
            # bare 400 without it, and the day's 52k rejects had to be told
            # apart from the reject rate at vs behind the touch.
            body = str(getattr(e, "body", "") or "")[:300]
            log(f"{self.tag} ! place rejected ({e}){' ' + body if body else ''}: {label}")
            # Rejections are signal, not noise: a post-only reject means the
            # touch moved between the book read and the send, which is the
            # measurable form of "our quotes are stale".
            self._log_order("reject", q.ticker, q.book_side, q.price_cents,
                            q.count, "", now_ts,
                            client_order_id=client_order_id,
                            quote_is_pad=q.is_pad, error=str(e),
                            error_body=body,
                            http_status=getattr(e, "status", None))
            self._xp_refused(q.ticker, e, "place")   # a trading pause? (EXCH_PAUSE_MODE)
            self._cash_refused(q, e, time.time())    # short of cash? (SHARD_CASH_PAUSE)
            return False
        except Exception as e:
            # Ambiguous failure (timeout mid-flight): the order MAY be live but
            # untracked, and the eventually-consistent read won't show it yet.
            # Cool this exact level down so the next cycle can't double-place
            # before the read catches up (TTL bounds the orphan either way).
            self.state.place_uncertain[(q.ticker, q.book_side, q.price_cents)] = now_ts
            log(f"{self.tag} ! place failed ({e}): {label}; level cooled "
                f"{2 * POLL_SECS}s (order may exist untracked)")
            # kind='uncertain', not 'reject': the order MAY be live but
            # untracked, so any fill-rate denominator must be able to exclude
            # these rather than silently count them as unfilled.
            self._log_order("uncertain", q.ticker, q.book_side, q.price_cents,
                            q.count, "", now_ts,
                            client_order_id=client_order_id,
                            quote_is_pad=q.is_pad, error=str(e))
            return False

    def cancel_order(self, order_id: str, reason: str = "") -> bool:
        # Heartbeat per order: a 1000-order sweep/wave legitimately outlasts
        # the hang-watchdog window; a WEDGED call still freezes these touches.
        self._heartbeat = time.time()
        if not self.live:
            self.state.sim_orders.pop(order_id, None)
            self.state.order_ages.pop(order_id, None)
            self._cycle_cancelled.add(order_id)
            log(f"{self.tag} [DRY] cancel {order_id}")
            return True
        # Snapshot the ledger entry before either path pops it — it carries
        # the ticker/side/price this cancel refers to, and after the pop the
        # order id alone is meaningless.
        led = self.state.ledger.get(order_id) or {}
        placed_at = led.get("_placed_at")
        ticker = led.get("ticker") or self._order_ticker.get(order_id, "")
        try:
            if ticker and self._ticker_shard.get(ticker) != 0:
                # EXCHANGE SHARDS (2026-10-14, Jack: "KXMLBWSMVP-26 still not
                # quoting"): this DELETE goes to shard 0 unless told otherwise,
                # and an order resting on another shard (2 = crypto /
                # commodities, 3 = baseball / basketball / tennis) 404s there,
                # which the handler below books as "already gone" while the
                # order keeps resting -- 207 KXSTRKMAXY/MINY cancels on 10/14,
                # and doubled rungs on the book. Route by the market, as the
                # crypto bots do; a market not yet seen on a read is routed
                # too. Creates and amends carry the ticker and route already.
                self.client.cancel_order(order_id, exchange_index=-1,
                                         market_ticker=ticker)
            else:
                self.client.cancel_order(order_id)
            self._cycle_cancelled.add(order_id)
            self.state.order_ages.pop(order_id, None)
            self.state.ledger.pop(order_id, None)
            self._log_order(
                "cancel", led.get("ticker", ""), led.get("book_side", ""),
                led.get("yes_price"), led.get("remaining_count"), order_id,
                reason=reason,
                rested_secs=(round(time.time() - placed_at, 1)
                             if placed_at else None))
            return True
        except HttpError as e:
            if e.status in (404, 409):
                self._cycle_cancelled.add(order_id)
                self.state.order_ages.pop(order_id, None)
                self.state.ledger.pop(order_id, None)
                # Already gone — filled, expired or cancelled elsewhere.
                # Distinct from 'cancel' on purpose: an order that vanished
                # before we could cancel it must not be counted as one we
                # pulled when computing fill rates.
                self._log_order(
                    "gone", led.get("ticker", ""), led.get("book_side", ""),
                    led.get("yes_price"), led.get("remaining_count"),
                    order_id, reason=reason, http_status=e.status,
                    rested_secs=(round(time.time() - placed_at, 1)
                                 if placed_at else None))
                return True
            log(f"{self.tag} ! cancel failed {order_id}: {e}")
            return False
        except Exception as e:
            log(f"{self.tag} ! cancel failed {order_id}: {e}")
            return False

    def amend_order_inplace(self, o: dict, q: Quote, now_ts: float,
                            reason: str = "") -> bool:
        """Reprice/resize a resting order IN PLACE (V2 amend, 2026-08-02
        requote-downtime fix): the rung never leaves the book — no
        cancel->place gap — and the order_id survives, so ownership/fill
        matching and the crash journal need nothing new. V2 count semantics:
        total max-fillable = already-filled + desired remainder. Amend has
        no post_only; desired prices are already clamped to the last-read
        opposite touch upstream (a fast race can still take; accepted).
        order_ages is deliberately NOT touched: amend cannot extend the
        exchange-side expiration, so the 25-min TTL refresh must still
        rewrite the order for real."""
        self._heartbeat = time.time()
        oid = o.get("order_id", "")
        try:
            filled = float(o.get("fill_count_fp") or o.get("fill_count") or 0)
        except (TypeError, ValueError):
            filled = 0.0
        total = float(q.count) + max(0.0, filled)
        label = (f"{q.ticker} {q.book_side.upper():4s} -> {q.count}x @ "
                 f"{q.price_cents}c (amend {oid[:8]})")
        if not self.live:
            so = self.state.sim_orders.get(oid)
            if so is None:
                return False
            so["yes_price"] = q.price_cents
            so["remaining_count"] = float(q.count)
            log(f"{self.tag} [DRY] amend {label}")
            return True
        if self._xp and self._xp_hold(q.ticker, time.time()):
            return False       # its shard is paused (EXCH_PAUSE_MODE): not sent
        try:
            self.client.amend_order(
                order_id=oid, ticker=q.ticker, book_side=q.book_side,
                yes_price_cents=q.price_cents, total_count=total)
            self._cycle_amended[oid] = int(q.price_cents)
            self._cycle_amended_ct[oid] = float(q.count)
            led = self.state.ledger.get(oid)
            # Read the previous price/size BEFORE the overwrite below, and
            # keep the FULL order id: the prose line truncates it to 8 chars,
            # which makes an order's price history unreconstructable even by
            # regex. ~13k amends a day carry the whole requote story.
            prev_px = led.get("yes_price") if led is not None else None
            prev_ct = led.get("remaining_count") if led is not None else None
            if led is not None:
                led["yes_price"] = q.price_cents
                led["remaining_count"] = float(q.count)
            # the fills sink joins a fill to the version it hit: one landing
            # before this amend is booked after it. An amend sends whole
            # cents, so the new version has no sub-penny price.
            self._join_set(oid, q.ticker, q.book_side, q.price_cents, None,
                           float(q.count), o.get("client_order_id"),
                           self.state.order_ages.get(oid))
            log(f"{self.tag} amended {label}" + (f" [{reason}]" if reason else ""))
            if self._xp:
                self._xp_ok(q.ticker, "amend")
            self._log_order("amend", q.ticker, q.book_side, q.price_cents,
                            q.count, oid, now_ts,
                            prev_price_cents=prev_px, prev_count=prev_ct,
                            filled_before=filled, total_count=total,
                            quote_is_pad=q.is_pad,
                            **({"reason": reason} if reason else {}))
            return True
        except HttpError as e:
            if self._xp_refused(q.ticker, e, "amend"):
                # a trading pause (EXCH_PAUSE_MODE), not a dead order: it
                # still rests, so it stays booked
                return False
            if e.status in (404, 409):
                # Order died mid-flight (filled/expired/cancelled): forget it;
                # the next cycle's diff places fresh.
                self.state.order_ages.pop(oid, None)
                self.state.ledger.pop(oid, None)
                return False
            log(f"{self.tag} ! amend failed {label}: {e}")
            return False
        except Exception as e:
            log(f"{self.tag} ! amend failed {label}: {e}")
            return False

    # ---- WebSocket books (2026-10-03, see WS_MODE) ----------------------------

    def _read_book(self, ticker: str) -> dict:
        """The market's order book for the quote loop. IMM_WS=shadow (the
        default) and off: the REST read exactly as before -- in shadow it is
        then compared with the WS book, which is never used. IMM_WS=on: the
        WS book when it is trustworthy, else REST; 1 read in WS_AUDIT_EVERY
        also reads REST, trades on the REST book and compares the two, and a
        tripped audit sends every read to REST (compared) until it re-arms.
        A REST failure raises as it always did (the blind path is unchanged),
        except on an audit read, which then trades on the WS book. With
        IMM_WS=on the REST reads are budgeted per cycle (BOOK_REST_BUDGET_SECS):
        once spent, an audit trades on the WS book and a book the feed cannot
        serve raises BookRestOff without a REST call."""
        # the read phase's clock (latency.cycle), and the in-cycle stale check
        self._cycle_last_read = time.time()
        self._ws_cycle_tick()
        ws = self._ws
        if ws is not None and WS_MODE == "on" and not self._ws_audit["tripped"]:
            ob = ws.book_fp(ticker)
            if ob is not None:
                if not self._ws_audit_draw() or self._book_rest_off():
                    self._ws_books_used += 1
                    return ob
                try:
                    rest = self._book_rest_read(ticker)
                except Exception:
                    self._ws_audit["rest_errors"] += 1
                    self._ws_books_used += 1
                    return ob
                self._ws_compare(ticker, rest, audit=True)
                return rest
            self._ws_rest_fallback += 1
        budgeted = ws is not None and WS_MODE == "on"
        if budgeted and self._book_rest_off():
            raise BookRestOff(self._book_rest["off"])
        ob = (self._book_rest_read(ticker) if budgeted
              else self.client.get_orderbook(ticker=ticker))
        if ws is not None and WS_MODE in ("shadow", "on"):
            self._ws_compare(ticker, ob, audit=self._ws_audit_draw())
        return ob

    def _book_rest_off(self) -> str:
        """Why this cycle's quote loop has stopped reading books over REST, or
        "" while it may (BOOK_REST_BUDGET_SECS of REST time spent, or
        BOOK_REST_MAX_FAILS network failures in a row; the time bound is
        waived while the REST audit is tripped, when every read is REST by
        design). No budget outside the read loop. Once off, off for the rest
        of the cycle."""
        b = self._book_rest
        if b is None:
            return ""
        if (not b["off"] and BOOK_REST_BUDGET_SECS > 0
                and not self._ws_audit["tripped"]
                and b["spent"] > BOOK_REST_BUDGET_SECS):
            b["off"] = f"its {BOOK_REST_BUDGET_SECS:g}s REST budget ran out"
        return b["off"]

    def _book_rest_read(self, ticker: str) -> dict:
        """A managed book over REST, timed into this cycle's budget: a network
        failure extends the streak, any answer (a book or an HTTP error)
        ends it."""
        b = self._book_rest
        t0 = time.monotonic()
        try:
            ob = self.client.get_orderbook(ticker=ticker)
        except Exception as e:
            self._note_net_error(e)
            if b is not None:
                b["spent"] += time.monotonic() - t0
                if not is_network_error(e):
                    b["fails"] = 0
                else:
                    b["fails"] += 1
                    if (not b["off"] and BOOK_REST_MAX_FAILS > 0
                            and b["fails"] >= BOOK_REST_MAX_FAILS):
                        b["off"] = (f"{b['fails']} network failures in a row "
                                    f"({type(e).__name__})")
            raise
        if b is not None:
            b["spent"] += time.monotonic() - t0
            b["fails"] = 0
        return ob

    def _read_candidate_book(self, ticker: str) -> dict:
        """A candidate's book for the universe refresh (WS_CANDIDATES). off:
        the REST read as before. shadow: REST, compared with the feed's book
        (latency.ws.cand.shadow; 1 compare in WS_AUDIT_EVERY feeds the audit
        window). on (with IMM_WS=on): the feed's book when trustworthy, else
        REST; 1 read in WS_AUDIT_EVERY also reads REST, uses it and feeds the
        audit, and a tripped audit sends every read to REST (compared, so the
        window can re-arm). A REST failure raises -- the caller marks the
        book unreadable, as before -- except on an audit read, which then
        uses the WS book. Once pass 2's REST budget is spent (_cand_rest_off)
        a feed book is used without the audit draw, and a book the feed
        cannot serve raises CandidateRestOff without a REST call."""
        ws = self._ws
        st = self._ws_cand
        off = self._cand_rest_off()
        if (ws is not None and WS_CANDIDATES == "on" and WS_MODE == "on"
                and not self._ws_audit["tripped"]):
            ob = ws.book_fp(ticker)
            if ob is not None:
                if off or not self._ws_audit_draw():
                    st["ws"] += 1
                    return ob
                try:
                    rest = self._cand_rest_read(ticker)
                except Exception:
                    self._ws_audit["rest_errors"] += 1
                    st["ws"] += 1
                    return ob
                st["rest"] += 1
                st["audits"] += 1
                self._ws_compare(ticker, rest, audit=True,
                                 stats=self._ws_cand_shadow)
                return rest
            st["rest_fallback"] += 1
        if off:
            st["rest_skipped"] += 1
            raise CandidateRestOff(off)
        ob = self._cand_rest_read(ticker)
        st["rest"] += 1
        if ws is not None and WS_CANDIDATES != "off" and WS_MODE in ("shadow", "on"):
            self._ws_compare(ticker, ob, audit=self._ws_audit_draw(),
                             stats=self._ws_cand_shadow)
        return ob

    def _cand_rest_off(self) -> str:
        """Why pass 2 has stopped reading candidate books over REST, or ""
        while it may: CAND_REST_BUDGET_SECS spent, or CAND_REST_MAX_FAILS
        network failures in a row (_cand_rest_read). No budget outside pass
        2. Once off, off for the rest of the pass."""
        b = self._cand_rest
        if b is None:
            return ""
        if (not b["off"] and CAND_REST_BUDGET_SECS > 0
                and time.monotonic() - b["t0"] > CAND_REST_BUDGET_SECS):
            b["off"] = f"its {CAND_REST_BUDGET_SECS:g}s REST budget ran out"
        return b["off"]

    def _cand_rest_read(self, ticker: str) -> dict:
        """A candidate's REST book, kept in pass 2's failure streak: a
        network failure adds one, an answer of any kind (a book, an HTTP
        error) ends the streak."""
        b = self._cand_rest
        try:
            ob = self.client.get_orderbook(ticker=ticker)
        except Exception as e:
            self._note_net_error(e)             # (UNIVERSE_NET_GUARD)
            if b is not None:
                if not is_network_error(e):
                    b["fails"] = 0
                else:
                    b["fails"] += 1
                    if (not b["off"] and CAND_REST_MAX_FAILS > 0
                            and b["fails"] >= CAND_REST_MAX_FAILS):
                        b["off"] = (f"{b['fails']} network failures in a row "
                                    f"({type(e).__name__})")
            raise
        if b is not None:
            b["fails"] = 0
        return ob

    def _ws_cand_subscribe(self, tickers: Iterable[str]) -> None:
        """Put the universe refresh's candidates on the feed (WS_CANDIDATES
        shadow / on), beside the managed set last sent, just before their
        books are read. In on mode a refresh that adds WS_CAND_WARM_MIN+ new
        books (a restart's first) waits up to WS_CAND_WARM_SECS for their
        snapshots, ticking the WS checks meanwhile; whatever has not arrived
        by then reads REST. Never raises."""
        ws = self._ws
        if ws is None or WS_CANDIDATES == "off":
            return
        try:
            want = set(tickers)
            new = want - self._ws_cand_want - self._ws_managed_last
            self._ws_cand_want = want
            ws.set_markets(self._ws_managed_last | want)
            if (WS_CANDIDATES != "on" or WS_MODE != "on"
                    or len(new) < WS_CAND_WARM_MIN or WS_CAND_WARM_SECS <= 0):
                return
            t0 = time.time()
            while time.time() - t0 < WS_CAND_WARM_SECS:
                if ws.ready(new) >= 0.98 * len(new):
                    break
                self._ws_cycle_tick()
                time.sleep(0.25)
            self._ws_cand["warm_waits"] += 1
            self._ws_cand["warm_s"] = round(
                self._ws_cand["warm_s"] + time.time() - t0, 1)
        except Exception as e:
            log(f"{self.tag} ! WS candidate sync failed: {e}")

    def _note_universe_refresh(self, t0: float, t1: float, before: dict) -> None:
        """One universe refresh ran from t0 to t1: keep it for
        latency.universe and, with WS_CANDIDATES on, log where its candidate
        books came from. `before` is self._ws_cand as the refresh began."""
        st = self._ws_cand
        d = {k: st[k] - before.get(k, 0) for k in ("ws", "rest", "rest_fallback",
                                                   "audits")}
        reads = d["ws"] + d["rest"]
        self._universe_times.append((t0, t1, reads, d["ws"]))
        if WS_CANDIDATES != "off" and self._ws is not None:
            log(f"{self.tag} universe refresh: {t1 - t0:.0f}s; candidate books "
                f"{d['ws']} from WS, {d['rest']} REST"
                + (f" ({d['rest_fallback']} not ready on the feed, "
                   f"{d['audits']} audits)" if WS_CANDIDATES == "on" else
                   " (shadow: every REST read compared)"))

    def _ws_audit_draw(self) -> bool:
        """True for 1 book read in WS_AUDIT_EVERY, at random. Only these
        compares feed the audit's trip window, in every mode: shadow then
        rehearses exactly the audit `on` would run, and a burst of racing
        books (a data release moves 20-50 markets the cycle reads back to
        back) cannot crowd the window with timing mismatches."""
        return self._ws_rng.random() * WS_AUDIT_EVERY < 1.0

    def _ws_compare(self, ticker: str, rest_ob: dict, audit: bool = False,
                    stats: Optional[dict] = None) -> None:
        """Compare the WS book with a REST read of the same market: count
        whole-book / top-of-book agreement (status latency.ws.shadow, or
        `stats` -- the candidate books' own counters), log a sample of top
        mismatches, and -- an audit draw -- feed the audit's trip window.
        Never raises; trading sees the outcome only through a trip."""
        try:
            import kalshi_ws
            lv = self._ws.book_levels(ticker)
            st = self._ws_shadow if stats is None else stats
            if lv is None:
                st["ws_missing"] += 1
                return
            st["compared"] += 1
            ry, rn = kalshi_ws.rest_book_levels(rest_ob)
            wy, wn = lv

            def r2(d):
                return {k: round(v, 2) for k, v in d.items() if round(v, 2) > 0}
            exact = r2(ry) == r2(wy) and r2(rn) == r2(wn)
            top_r = (max(ry, default=None), max(rn, default=None))
            top_w = (max(wy, default=None), max(wn, default=None))
            st["exact"] += int(exact)
            st["top"] += int(top_r == top_w)
            if top_r != top_w:
                now = time.time()
                while self._ws_shadow_logged and \
                        self._ws_shadow_logged[0] < now - 3600:
                    self._ws_shadow_logged.popleft()
                if len(self._ws_shadow_logged) < WS_SHADOW_LOG_PER_HOUR:
                    self._ws_shadow_logged.append(now)
                    log(f"{self.tag} WS shadow: top mismatch {ticker} "
                        f"rest {top_r} ws {top_w}")
            if audit:
                self._ws_audit["audits"] += 1
                self._ws_audit_note(exact, top_r == top_w)
        except Exception:
            pass

    def _ws_audit_note(self, exact: bool, top: bool,
                       now_ts: Optional[float] = None) -> None:
        """One WS-vs-REST compare into the audit window; trip on too many
        mismatches, re-arm after the cooldown on a clean window."""
        now_ts = time.time() if now_ts is None else now_ts
        win = self._ws_audit_win
        win.append((bool(exact), bool(top)))
        bad_top = sum(1 for _e, tp in win if not tp)
        bad_book = sum(1 for e, _tp in win if not e)
        st = self._ws_audit
        clean = bad_top < WS_AUDIT_TRIP_TOP and bad_book < WS_AUDIT_TRIP_EXACT
        if not st["tripped"]:
            if clean:
                return
            st.update(tripped=True, tripped_at=now_ts, trips=st["trips"] + 1,
                      last_trip=f"{bad_top} top-of-book / {bad_book} whole-book "
                                f"mismatches in the last {len(win)} compares")
            win.clear()
            what = ("every book read is back on REST" if WS_MODE == "on"
                    else "the stale-quote check is paused (trading reads REST)")
            self.alerter.alert(
                "ws_audit", f"WebSocket books disagree with REST: "
                f"{st['last_trip']}; {what}; the feed reconnects for fresh "
                f"snapshots; re-arms after {WS_AUDIT_COOLDOWN_SECS / 60:.0f} min "
                f"on a clean window", key="trip", urgent=(WS_MODE == "on"),
                now_ts=now_ts)
            try:
                if self._ws is not None:
                    self._ws.resync("REST audit tripped")
            except Exception:
                pass
            return
        if (clean and len(win) >= WS_AUDIT_WINDOW
                and now_ts - st["tripped_at"] >= WS_AUDIT_COOLDOWN_SECS):
            st.update(tripped=False, rearms=st["rearms"] + 1)
            log(f"{self.tag} WS audit re-armed: {len(win)} compares since the "
                f"trip, {bad_top} top / {bad_book} whole-book mismatches"
                + ("; WS books back in use" if WS_MODE == "on" else ""))

    def _ws_start(self) -> None:
        """Start the WebSocket feed thread (IMM_WS=shadow|on). Any failure
        leaves self._ws None: the bot runs exactly as with IMM_WS=off."""
        if WS_MODE == "off" or self._ws is not None:
            return
        client = self.client
        if client is None or not hasattr(client, "sign_pss_text"):
            log(f"{self.tag} ! WS {WS_MODE} requested but no signing client; off")
            return
        try:
            import kalshi_ws
            from urllib.parse import urlparse
            path = urlparse(WS_URL).path or "/trade-api/ws/v2"
            key_id = getattr(client, "key_id", None) or KEY_ID

            def headers() -> Dict[str, str]:
                ts = str(int(time.time() * 1000))
                return {"KALSHI-ACCESS-KEY": key_id,
                        "KALSHI-ACCESS-SIGNATURE":
                            client.sign_pss_text(ts + "GET" + path),
                        "KALSHI-ACCESS-TIMESTAMP": ts}

            prefix = CLIENT_ORDER_PREFIX + "-"
            feed = kalshi_ws.KalshiFeed(
                WS_URL, headers, log=lambda s: log(f"{self.tag} {s}"),
                fill_filter=lambda f: str(f.get("client_order_id") or "").startswith(prefix),
                want_fills=True, want_order_groups=False,
                chunk=WS_SUB_CHUNK, stale_secs=WS_STALE_SECS)
            feed.start()
            self._ws = feed
            log(f"{self.tag} WebSocket feed started ({WS_MODE}"
                f"{', fast path' if WS_FAST and WS_MODE == 'on' else ''}) "
                f"-> {WS_URL}")
        except Exception as e:
            self._ws = None
            log(f"{self.tag} ! WS feed failed to start ({e}); running REST-only")

    def _ws_stop(self) -> None:
        ws, self._ws = self._ws, None
        if ws is not None:
            try:
                ws.stop()
            except Exception:
                pass

    def _ws_process_events(self, now_ts: float, in_cycle: bool = False) -> None:
        """Drain the feed: our fills (the sweep breaker; in fast mode, between
        cycles, start the next cycle early) and the books that changed, for
        the stale-quote check -- between cycles, and inside them too with
        WS_CHECK_IN_CYCLE: live in fast mode, DRY (counting only) otherwise."""
        ws = self._ws
        if ws is None:
            return
        try:
            dirty, events, dropped = ws.drain()
        except Exception:
            return
        # a tripped REST audit distrusts the books: no stale-quote check at all
        ok = not self._ws_audit["tripped"]
        fast = WS_FAST and WS_MODE == "on" and ok
        # with the fast path off, the same check runs DRY: it counts (and
        # samples in the log) the cancels it would have sent -- the evidence
        # for a fast path, gathered on the live book
        fast_dry = not fast and WS_MODE in ("on", "shadow") and ok
        for kind, body in events:
            self._ws_fast["events"] += 1
            if kind == "fill":
                self._ws_fast["fills"] += 1
                self._sweep_note_fill(body, now_ts)
                if fast and not in_cycle:
                    self._ws_wake = True
        if (fast or fast_dry) and (not in_cycle or WS_CHECK_IN_CYCLE):
            if dropped or self._ws_recheck_all:
                # a fresh view: every market once, not just the books that
                # changed -- an order can be ahead from its placement on a
                # book that then goes quiet
                dirty = set(dirty) | set(self._resting_view)
                self._ws_recheck_all = False
            self._ws_fast_check(set(dirty), now_ts, dry=fast_dry,
                                in_cycle=in_cycle)

    def _ws_cycle_tick(self) -> None:
        """The feed's events INSIDE the cycle (WS_CHECK_IN_CYCLE): the stale-
        quote check and the sweep breaker, at most every WS_TICK_SECS, called
        from the book reads and the write loops. Never raises; never re-enters
        itself (a live cancel inside it writes, and writes tick)."""
        if self._ws is None or not WS_CHECK_IN_CYCLE or self._ws_ticking:
            return
        now_ts = time.time()
        if now_ts - self._ws_tick_last < WS_TICK_SECS:
            return
        self._ws_tick_last = now_ts
        self._ws_ticking = True
        try:
            self._ws_process_events(now_ts, in_cycle=True)
        except Exception as e:
            log(f"{self.tag} ! WS event handling failed: {e}")
        finally:
            self._ws_ticking = False

    def _ws_fast_check(self, dirty: Set[str], now_ts: float,
                       dry: bool = False, in_cycle: bool = False) -> int:
        """Between cycles (and inside them, in_cycle, with WS_CHECK_IN_CYCLE):
        find any resting rung the external touch has left STRICTLY AHEAD of
        the book -- the stale quote a sweep picks off (join-never-lead means
        it is never intended). It must read ahead on two looks >= 1s apart
        (our own new order can reach the book a moment after a delta) and be
        >= 2s old; pads are never touched; in_cycle, an order this cycle has
        already amended or cancelled is skipped. DRY (shadow, or on without
        IMM_WS_FAST): count it once in `would_cancel` and log a sample. LIVE
        (on + IMM_WS_FAST=1): cancel it and start the next cycle early. With
        the narrow gate (WS_FAST_MIN_GAP_C > 0) only a rung at least that
        many cents ahead of the rest of its side acts -- the others stay dry
        -- and an episode's first time past the gap is logged (`narrow`).
        Returns cancels sent."""
        ws = self._ws
        if ws is None:
            return 0
        cancels = 0
        phase = "cycle" if in_cycle else "idle"
        check = set(dirty) | {o_t for o_t, lst in self._resting_view.items()
                              if any(o["order_id"] in self._ws_suspect for o in lst)}
        # a complement lead is judged on its twin's book too, so a move there
        # re-checks it (COMP_LEAD_MODE)
        check |= {s for d in dirty for s in self._comp_groups.get(d, ())
                  if s != d and s in self._comp_lead_px}
        check |= {s for d in dirty for s in self._ladders.get(d, ())
                  if s != d and s in self._comp_lead_px}

        def _own_by_px(lst) -> Tuple[Dict[float, float], Dict[float, float]]:
            oy: Dict[float, float] = {}
            on: Dict[float, float] = {}
            for o in lst:
                if o["side"] == "bid":
                    k = round(o["px"] / 100.0, 4)
                    oy[k] = oy.get(k, 0.0) + o["rem"]
                else:
                    k = round((100.0 - o["px"]) / 100.0, 4)
                    on[k] = on.get(k, 0.0) + o["rem"]
            return oy, on

        for t in sorted(check):
            orders = self._resting_view.get(t)
            if not orders:
                continue
            exempt = ws_fast_exempt(series_of(t))      # IMM_WS_FAST_EXEMPT
            lv = ws.book_levels(t)
            if lv is None:
                continue
            yes, no = lv
            own_yes, own_no = _own_by_px(orders)
            ext_bid = max((p for p, q in yes.items()
                           if q - own_yes.get(p, 0.0) > 0.01), default=None)
            ext_no = max((p for p, q in no.items()
                          if q - own_no.get(p, 0.0) > 0.01), default=None)
            ext_ask = None if ext_no is None else round(1.0 - ext_no, 4)
            # COMPLEMENT LEAD: a leading side's touch is the better of its own
            # and the one its siblings' books imply -- 100 less their best YES
            # bids for our ask, the twin's best NO bid for our bid -- our own
            # orders there netted out; with any sibling's book off the feed it
            # is its own alone, so a lead they no longer back reads ahead like
            # any stale rung
            lead_px = self._comp_lead_px.get(t)
            grp = self._comp_groups.get(t)
            if lead_px is not None and grp:
                sibs = [s for s in grp if s != t]
                slv = [ws.book_levels(s) for s in sibs]
                if all(b is not None for b in slv):
                    best_yes = []
                    for s, (s_yes, s_no) in zip(sibs, slv):
                        so_yes, so_no = _own_by_px(self._resting_view.get(s) or [])
                        best_yes.append(max((p for p, q in s_yes.items()
                                             if q - so_yes.get(p, 0.0) > 0.01),
                                            default=0.0))
                        if lead_px[0] is not None and len(sibs) == 1:
                            imp = max((p for p, q in s_no.items()
                                       if q - so_no.get(p, 0.0) > 0.01), default=None)
                            if imp is not None:
                                ext_bid = imp if ext_bid is None else max(ext_bid, imp)
                    if lead_px[1] is not None:
                        imp_ask = round(1.0 - sum(best_yes), 4)
                        ext_ask = imp_ask if ext_ask is None else min(ext_ask, imp_ask)
            lad = self._ladders.get(t) if lead_px is not None and not grp else None
            if lad:
                # a ladder strike: the harder strikes' best bids are our bid's
                # touch too, the easier strikes' best offers our ask's (a strike
                # off the feed is left out)
                i = lad.index(t)
                for s in (lad[i + 1:] if lead_px[0] is not None else ()):
                    b = ws.book_levels(s)
                    if b is None:
                        continue
                    so_yes, _so_no = _own_by_px(self._resting_view.get(s) or [])
                    imp = max((p for p, q in b[0].items()
                               if q - so_yes.get(p, 0.0) > 0.01), default=None)
                    if imp is not None:
                        ext_bid = imp if ext_bid is None else max(ext_bid, imp)
                for s in (lad[:i] if lead_px[1] is not None else ()):
                    b = ws.book_levels(s)
                    if b is None:
                        continue
                    _so_yes, so_no = _own_by_px(self._resting_view.get(s) or [])
                    nb = max((p for p, q in b[1].items()
                              if q - so_no.get(p, 0.0) > 0.01), default=None)
                    if nb is not None:
                        imp_ask = round(1.0 - nb, 4)
                        ext_ask = imp_ask if ext_ask is None else min(ext_ask, imp_ask)
            for o in list(orders):
                oid = o["order_id"]
                if in_cycle and (oid in self._cycle_amended
                                 or oid in self._cycle_cancelled):
                    continue      # this cycle acted on it: its entry is stale
                if o["pad"] or now_ts - o["placed"] < 2.0:
                    self._ws_suspect_end(oid, now_ts, "young")
                    continue
                # the view is the cycle's read: an order filled out or pulled
                # since leaves no size at its price in the book, and there is
                # nothing to cancel (10/4: an ask lifted mid-cycle was flagged
                # 52s after its fill). A partly filled remainder still shows.
                lvl = (yes.get(round(o["px"] / 100.0, 4), 0.0) if o["side"] == "bid"
                       else no.get(round((100.0 - o["px"]) / 100.0, 4), 0.0))
                if lvl <= 0.01:
                    self._ws_suspect_end(oid, now_ts, "gone")
                    if oid in self._ws_flagged:
                        self._ws_episode_end(oid, "gone", now_ts)
                    continue
                p = round(o["px"] / 100.0, 4)
                ahead = ((ext_bid is None or p > ext_bid + 1e-6)
                         if o["side"] == "bid"
                         else (ext_ask is None or p < ext_ask - 1e-6))
                if not ahead:
                    self._ws_suspect_end(oid, now_ts, "clear")
                    if oid in self._ws_flagged:     # the touch came back
                        self._ws_episode_end(oid, "clear", now_ts,
                                             ext_bid=_ws_cents(ext_bid),
                                             ext_ask=_ws_cents(ext_ask))
                    continue
                # the narrow gate (WS_FAST_MIN_GAP_C): only a rung at least
                # that far ahead is cancelled; the other flags stay dry
                gap = _ws_gap_c(o["side"], o["px"], ext_bid, ext_ask)
                wide = WS_FAST_MIN_GAP_C <= 0 or (
                    gap is not None and gap >= WS_FAST_MIN_GAP_C - 1e-9)
                act = not dry and wide and not exempt
                if oid not in self._ws_suspect:
                    # first seen ahead: draw its arm (2026-10-17) and log it
                    self._ws_suspect[oid] = now_ts
                    arm = "control" if (WS_FAST_CONFIRM_HOLDOUT > 0 and
                                        self._ws_rng.random() < WS_FAST_CONFIRM_HOLDOUT) \
                        else "fast"
                    self._ws_arm[oid] = arm
                    if WS_SEEN_LOG and WS_STALE_LOG:
                        self._sink("ws_stale", {
                            "ev": "seen", "ts": round(now_ts, 3), "phase": phase,
                            "ticker": t, "order_id": oid, "side": o["side"],
                            "px": o["px"], "rem": o["rem"],
                            "gap_c": None if gap is None else round(gap, 2),
                            "acts": act, "arm": arm,
                            "ext_bid": _ws_cents(ext_bid),
                            "ext_ask": _ws_cents(ext_ask)})
                first = self._ws_suspect[oid]
                # an acting episode in the fast arm confirms after
                # WS_FAST_CONFIRM_SECS; the control and dry episodes after 1s
                need = WS_FAST_CONFIRM_SECS if (
                    act and self._ws_arm.get(oid, "fast") == "fast") else 1.0
                if now_ts - first < need:
                    continue
                new = self._ws_episode_flag(t, o, now_ts, first, ext_bid,
                                            ext_ask, yes, no, orders, not act,
                                            phase=phase)
                if WS_FAST_MIN_GAP_C > 0 and wide:
                    self._ws_episode_narrow(t, o, now_ts, gap, not act, phase)
                if not act:
                    # count each episode once; never cancel, never spend budget
                    if new:
                        self._ws_fast["would_cancel"] = \
                            self._ws_fast.get("would_cancel", 0) + 1
                        while self._ws_shadow_logged and \
                                self._ws_shadow_logged[0] < now_ts - 3600:
                            self._ws_shadow_logged.popleft()
                        if len(self._ws_shadow_logged) < WS_SHADOW_LOG_PER_HOUR:
                            self._ws_shadow_logged.append(now_ts)
                            log(f"{self.tag} WS fast (dry): would cancel {t} "
                                f"{o['side'].upper()} @ {o['px']:g}c -- the "
                                f"external touch left it ahead (bid {ext_bid}, "
                                f"ask {ext_ask})")
                    continue
                while self._ws_cancel_times and \
                        self._ws_cancel_times[0] < now_ts - 60.0:
                    self._ws_cancel_times.popleft()
                if len(self._ws_cancel_times) >= WS_FAST_MAX_CANCELS_PER_MIN:
                    self._ws_fast["skipped_budget"] += 1
                    continue
                self._ws_cancel_times.append(now_ts)
                self._ws_suspect.pop(oid, None)
                arm = self._ws_arm.pop(oid, None)
                if self.cancel_order(oid, reason="ws_stale"):
                    self.state.cancelled_today += 1
                    cancels += 1
                    self._ws_fast["cancels"] += 1
                    orders.remove(o)
                    self._ws_episode_end(oid, "cancel", now_ts, by="fast",
                                         arm=arm, seen_s=round(now_ts - first, 2))
                    log(f"{self.tag} WS fast: cancelled {t} "
                        f"{o['side'].upper()} @ {o['px']:g}c -- the external "
                        f"touch left it ahead (bid {ext_bid}, ask {ext_ask})")
        if cancels:
            self._ws_wake = True
        return cancels

    def _ws_suspect_end(self, oid: str, now_ts: float, why: str) -> None:
        """A suspect stops reading ahead (`why`: clear / gone / cycle). One
        that was never confirmed -- a flicker the old 1s rule never logged --
        gets an `unseen` line with how long it lasted (2026-10-17, the
        faster fast cancel's report)."""
        first = self._ws_suspect.pop(oid, None)
        arm = self._ws_arm.pop(oid, None)
        if first is None or arm is None or oid in self._ws_flagged:
            return
        if WS_SEEN_LOG and WS_STALE_LOG:
            self._sink("ws_stale", {"ev": "unseen", "ts": round(now_ts, 3),
                                    "order_id": oid, "why": why, "arm": arm,
                                    "secs": round(now_ts - first, 2)})

    def _ws_episode_flag(self, t: str, o: dict, now_ts: float, first: float,
                         ext_bid: Optional[float], ext_ask: Optional[float],
                         yes: Dict[float, float], no: Dict[float, float],
                         orders: List[dict], dry: bool,
                         phase: str = "idle") -> bool:
        """Open a stale-quote episode for a rung the check just confirmed
        ahead -- once per order and price -- and log its `flag` line (the
        book, the external touch, our orders on the market; `phase` cycle /
        idle: whether the in-cycle check caught it). True if new."""
        oid = o["order_id"]
        ep = self._ws_flagged.get(oid)
        if ep is not None and abs(ep["px"] - o["px"]) < 1e-9:
            return False
        if ep is not None:                  # the same order at a new price
            self._ws_episode_end(oid, "amend", now_ts, new_px=o["px"])
        self._ws_flagged[oid] = {"t": t, "side": o["side"], "px": o["px"],
                                 "at": now_ts}
        if WS_STALE_LOG:
            px = o["px"]
            gap = _ws_gap_c(o["side"], px, ext_bid, ext_ask)
            self._sink("ws_stale", {
                "ev": "flag", "ts": round(now_ts, 3),
                "mode": "dry" if dry else "live", "phase": phase,
                "ticker": t, "order_id": oid, "side": o["side"], "px": px,
                "rem": o["rem"],
                "age_s": round(now_ts - o["placed"], 1) if o["placed"] else None,
                "ahead_s": round(now_ts - first, 2),
                "arm": self._ws_arm.get(oid),
                "ext_bid": _ws_cents(ext_bid), "ext_ask": _ws_cents(ext_ask),
                "gap_c": None if gap is None else round(gap, 2),
                "yes": _ws_top(yes), "no": _ws_top(no),
                "ours": [[x["side"], x["px"], x["rem"]] for x in orders]})
        return True

    def _ws_episode_narrow(self, t: str, o: dict, now_ts: float,
                           gap: Optional[float], dry: bool,
                           phase: str = "idle") -> None:
        """The narrow gate (WS_FAST_MIN_GAP_C): the first time an open
        episode sits at least the gap ahead, log its `narrow` line -- the
        moment the gated fast cancel goes (live) or would go (dry) -- and,
        dry, count it in `would_cancel_narrow` with a log sample. Once per
        episode; the episode itself stays open until its usual end line."""
        ep = self._ws_flagged.get(o["order_id"])
        if ep is None or ep.get("narrow"):
            return
        ep["narrow"] = True
        if WS_STALE_LOG:
            self._sink("ws_stale", {
                "ev": "narrow", "ts": round(now_ts, 3),
                "mode": "dry" if dry else "live", "phase": phase,
                "ticker": t, "order_id": o["order_id"], "side": o["side"],
                "px": o["px"], "rem": o["rem"],
                "gap_c": None if gap is None else round(gap, 2),
                "min_gap_c": WS_FAST_MIN_GAP_C,
                "since_flag_s": round(now_ts - ep["at"], 2)})
        if not dry:
            return
        self._ws_fast["would_cancel_narrow"] = \
            self._ws_fast.get("would_cancel_narrow", 0) + 1
        while self._ws_narrow_logged and \
                self._ws_narrow_logged[0] < now_ts - 3600:
            self._ws_narrow_logged.popleft()
        if len(self._ws_narrow_logged) < WS_SHADOW_LOG_PER_HOUR:
            self._ws_narrow_logged.append(now_ts)
            log(f"{self.tag} WS fast (dry, >= {WS_FAST_MIN_GAP_C:g}c): would "
                f"cancel {t} {o['side'].upper()} @ {o['px']:g}c -- "
                f"{gap:.1f}c ahead of the rest of its side")

    def _ws_episode_end(self, oid: str, ev: str, now_ts: float,
                        **extra: Any) -> None:
        """Close an open stale-quote episode with its `ev` line: clear (the
        touch came back), amend / cancel (by the cycle, or by="fast"), gone
        (it left the book: filled out or expired)."""
        ep = self._ws_flagged.pop(oid, None)
        if ep is None or not WS_STALE_LOG:
            return
        rec = {"ev": ev, "ts": round(now_ts, 3), "ticker": ep["t"],
               "order_id": oid, "side": ep["side"], "px": ep["px"],
               "stale_s": round(now_ts - ep["at"], 1)}
        rec.update(extra)
        self._sink("ws_stale", rec)

    def sweep_held(self, event: str, now_ts: float) -> bool:
        """True while a LIVE sweep-breaker trip holds `event` out of quoting
        (a control trip, SWEEP_HOLDOUT, never does). A linked series' events
        share their group's hold (sweep_hold_key)."""
        return SWEEP_BREAKER == "on" and \
            self._sweep_hold.get(sweep_hold_key(event), 0.0) > now_ts

    def group_held(self, ticker: str, side: str, now_ts: float) -> bool:
        """True while a LIVE cross-event breaker trip (SWEEP_GROUP on) holds
        `side` ('bid' / 'ask') of the ticker's risk_group out of quoting."""
        if SWEEP_GROUP != "on" or not self._grp_hold:
            return False
        g = risk_group_of(ticker)
        return g is not None and self._grp_hold.get((g, side), 0.0) > now_ts

    def coverage_exempt(self, ticker: str, now_ts: float) -> bool:
        """A market the coverage alert neither counts nor pages: one the
        toxic-flow halt, the sweep breaker (its event) or the group breaker
        (either side) stands down on purpose (Jack 2026-10-25: "Stop alert",
        after KXGOOGVREQ-28OCT26-T11P9 paged inside the 120 s hold a sweep of
        its sibling T11P4 put on the event). Nor one on a shard Kalshi has
        paused (_xp_shard_paused): its pads and amends are held, so a side
        another maker thins can't be topped back up (Jack 2026-10-29: "Yes,
        ship it" -- the 10/29 Thursday pause paged 13 markets 07:05-07:38Z,
        10/22's 17, every one two-sided again from the 09:00Z reopen)."""
        return (self.toxic_market_halted(ticker, now_ts)
                or self.sweep_held(self._event_of(ticker), now_ts)
                or self.group_held(ticker, "bid", now_ts)
                or self.group_held(ticker, "ask", now_ts)
                or self._xp_shard_paused(ticker))

    def _group_note_fill(self, t: str, oid: str, side: str, px: float,
                         n: float, fts: float, now_ts: float,
                         trade_id: Any) -> None:
        """The CROSS-EVENT BREAKER (SWEEP_GROUP) on one of our maker fills,
        from _sweep_note_fill. A fill on a side inside a trip's window is a
        `held_fill` line (dry: a fill `on` would not have taken); otherwise a
        fill on the same side of the group in ANOTHER event within
        SWEEP_GROUP_WINDOW_SECS of the last trips that side for
        SWEEP_GROUP_HOLD_SECS -- logged dry, held and pulled on."""
        g = risk_group_of(t)
        if g is None or side not in ("bid", "ask"):
            return
        st = self._grp
        st["fills"] += 1
        ev = self._event_of(t)
        key = (g, side)
        win = self._grp_win.get(key)
        if win is not None and win["until"] > now_ts:
            st["held_fills"] += 1
            st["held_ct"] += n
            self._sink("ws_group", {
                "ev": "held_fill", "ts": round(now_ts, 3), "mode": win["mode"],
                "group": g, "side": side, "event": ev, "ticker": t,
                "order_id": oid, "px": px, "count": n, "fill_ts": fts,
                "trade_id": trade_id, "trip_ts": win["at"],
                "since_trip_s": round(now_ts - win["at"], 1)})
            return
        if n + 1e-9 < SWEEP_GROUP_MIN_CT:
            return
        prev = self._grp_last.get(key)
        self._grp_last[key] = {"ts": fts, "event": ev, "ticker": t, "count": n,
                               "px": px, "order_id": oid, "trade_id": trade_id}
        if prev is None or prev["event"] == ev or \
                fts - prev["ts"] > SWEEP_GROUP_WINDOW_SECS:
            return
        for k_old in [k for k, w in self._grp_win.items()
                      if w["until"] < now_ts - 3600]:
            del self._grp_win[k_old]
        for k_old in [k for k, u in self._grp_hold.items() if u < now_ts - 3600]:
            del self._grp_hold[k_old]
        for k_old in [k for k, p in self._grp_last.items() if p["ts"] < fts - 3600]:
            del self._grp_last[k_old]
        live = SWEEP_GROUP == "on"
        mode = "on" if live else "dry"
        until = now_ts + SWEEP_GROUP_HOLD_SECS
        self._grp_win[key] = {"at": now_ts, "until": until, "mode": mode}
        st["trips"] += 1
        if live:
            self._grp_hold[key] = until
            st["trips_live"] += 1
        # the group's markets we quote, their reward a day (holding one side
        # gives up about half), and that side's orders -- the cycle's view,
        # plus what was placed since, which only the ledger holds yet
        pull: List[Tuple[str, dict]] = []
        grp_day, n_mkts = 0.0, 0
        for tk, lst in self._resting_view.items():
            if risk_group_of(tk) != g:
                continue
            n_mkts += 1
            pnl = self._last_panel.get(tk) or {}
            grp_day += float(pnl.get("est_frac") or 0.0) * \
                float(pnl.get("pool_per_day") or 0.0)
            pull.extend((tk, o) for o in lst
                        if o["side"] == side and o["rem"] > 0)
        in_view = {o["order_id"] for _tk, o in pull}
        for l_oid, led in list(self.state.ledger.items()):
            l_t = str(led.get("ticker") or "")
            l_rem = float(led.get("remaining_count") or 0.0)
            if l_oid in in_view or l_oid in self._cycle_cancelled or l_rem <= 0 \
                    or str(led.get("book_side") or "") != side or not l_t \
                    or any(o["order_id"] == l_oid
                           for o in self._resting_view.get(l_t, ())) \
                    or risk_group_of(l_t) != g:
                continue
            l_px = led.get("yes_price_exact")
            pull.append((l_t, {"order_id": l_oid, "side": side,
                               "px": float(l_px) if l_px is not None
                               else float(led.get("yes_price") or 0),
                               "rem": l_rem}))
        self._sink("ws_group", {
            "ev": "trip", "ts": round(now_ts, 3), "mode": mode, "group": g,
            "side": side, "hold_s": SWEEP_GROUP_HOLD_SECS,
            "gap_s": round(fts - prev["ts"], 1),
            "first": {"event": prev["event"], "ticker": prev["ticker"],
                      "count": prev["count"], "px": prev["px"],
                      "fill_ts": prev["ts"], "order_id": prev["order_id"],
                      "trade_id": prev["trade_id"]},
            "second": {"event": ev, "ticker": t, "count": n, "px": px,
                       "fill_ts": fts, "order_id": oid, "trade_id": trade_id},
            "markets": n_mkts, "group_day": round(grp_day, 2),
            "side_day": round(grp_day / 2.0, 2),
            "pull": [[tk, o["order_id"], o["px"], o["rem"]] for tk, o in pull]})
        log(f"{self.tag} group breaker ({mode}): {g} {side.upper()}s hit in "
            f"{prev['event']} then {ev} ({fts - prev['ts']:.0f}s apart) -> "
            f"{'holding' if live else 'would hold'} that side "
            f"{SWEEP_GROUP_HOLD_SECS / 60:.0f} min: {len(pull)} order(s) on "
            f"{n_mkts} market(s), ~${grp_day / 2.0:.2f}/day of reward")
        if not live:
            return
        for _tk, o in pull:
            while self._ws_cancel_times and \
                    self._ws_cancel_times[0] < now_ts - 60.0:
                self._ws_cancel_times.popleft()
            if len(self._ws_cancel_times) >= WS_FAST_MAX_CANCELS_PER_MIN:
                st["skipped_budget"] += 1          # the cycle pulls it
                continue
            self._ws_cancel_times.append(now_ts)
            if self.cancel_order(o["order_id"], reason="group_breaker"):
                self.state.cancelled_today += 1
                st["cancels"] += 1
                o["rem"] = 0.0
                self._ws_suspect.pop(o["order_id"], None)
                if o["order_id"] in self._ws_flagged:
                    self._ws_episode_end(o["order_id"], "cancel", now_ts,
                                         by="group")

    def _sweep_note_fill(self, body: dict, now_ts: float) -> None:
        """One of our WS fills. Every maker fill is logged (for the next view
        rebuild) and booked down in the resting view, whatever the mode.
        Then the EVENT SWEEP BREAKER (SWEEP_BREAKER): a maker fill that takes
        ALL that was left of its order trips the order's event:
          - dry: the trip is logged and counted;
          - on: every other resting order of ours in the event is cancelled
            at once (on the fast-cancel budget), and the cycle quotes nothing
            there until the hold ends.
        A partial fill only books the order down, so a later fill that clears
        the rest counts as the sweep. Never raises."""
        try:
            oid = str(body.get("order_id") or "")
            t = str(body.get("market_ticker") or body.get("ticker") or "")
            raw = body.get("count_fp")
            n = float(raw if raw not in (None, "") else (body.get("count") or 0.0))
            fts = body.get("ts_ms")
            fts = float(fts) / 1000.0 if fts else float(body.get("ts") or now_ts)
            maker = bool(oid and t and n > 0 and not body.get("is_taker"))
            mine = next((o for o in self._resting_view.get(t, ())
                         if o["order_id"] == oid), None) if maker else None
            prior = 0.0
            if maker:
                if mine is None:   # placed since the last rebuild: its fills so far
                    prior = sum(f_n for _ft, f_oid, f_n in self._ws_fill_log
                                if f_oid == oid)
                self._ws_fill_log.append((fts, oid, n))
            if mine is not None:
                rem, side, px = mine["rem"], mine["side"], mine["px"]
                mine["rem"] = max(0.0, rem - n)        # the view books the fill
            if maker and QUAKE_ASK_STRIKES and quake_gated(series_of(t)):
                # a fill on one of our far-strike quake asks: brake every ask
                # in the event at once (QUAKE_ASK_FILL_BRAKE_MIN)
                q_side = mine["side"] if mine is not None else \
                    str((self.state.ledger.get(oid) or {}).get("book_side") or "")
                if q_side == "ask":
                    self._quake_ask_brake_note(t, now_ts, "WS fill")
            if maker and yt2_series(series_of(t)):
                # a fill on the YouTube #2 pilot: stand its event aside
                # (YT2_FILL_PAUSE_MIN; the cycle's fill read notes it too)
                self._yt2_fill_pause_note(t, fts, "WS fill")
            if maker and astest_family(series_of(t)) is not None:
                # a fill on an AS test family: stand its event aside
                # (ASTEST_<F>_FILL_PAUSE_MIN; the cycle's fill read notes it too)
                self._astest_fill_pause_note(t, fts, "WS fill")
            if SWEEP_BREAKER == "off":
                return
            self._sweep["fills_seen"] += 1
            if not oid or not t or n <= 0:
                self._sweep["unparsed"] += 1
                return
            if body.get("is_taker"):
                return
            if mine is None:
                led = self.state.ledger.get(oid)
                if not led:
                    self._sweep["unknown_order"] += 1
                    return
                rem = max(0.0, float(led.get("remaining_count") or 0.0) - prior)
                side = str(led.get("book_side") or "")
                pxe = led.get("yes_price_exact")
                px = float(pxe) if pxe is not None else float(led.get("yes_price") or 0)
            if SWEEP_GROUP != "off":
                # the cross-event breaker counts every maker fill, partial
                # or not (2026-10-17)
                self._group_note_fill(t, oid, side, px, n, fts, now_ts,
                                      body.get("trade_id"))
            if rem <= 0 or n + 1e-6 < rem or n < SWEEP_MIN_CT:
                return                                  # partial: no sweep
            ev = self._event_of(t)
            # a linked series (SWEEP_LINKED_GROUPS) trips, holds and pulls its
            # whole group, for its SWEEP_HOLD_BY_SERIES length
            group = sweep_linked_series(series_of(t))
            key = sweep_hold_key(ev)
            hold_s = sweep_hold_secs(series_of(t))

            def _in_trip(tk: str) -> bool:
                return series_of(tk) in group if len(group) > 1 \
                    else self._event_of(tk) == ev
            if self._sweep_until.get(key, 0.0) > now_ts:
                return                                  # already tripped
            for d in (self._sweep_until, self._sweep_hold):
                for e_old in [e for e, u in d.items() if u < now_ts - 3600]:
                    del d[e_old]
            for e_old in [e for e, s in self._sweep_esc.items()
                          if s["reset_at"] < now_ts - 3600]:
                del self._sweep_esc[e_old]
            self._sweep_until[key] = now_ts + hold_s
            if sweep_exempt(series_of(t)):
                # mention families (SWEEP_EXEMPT_WORDS): logged, nothing pulled
                self._sweep["exempt"] += 1
                self._sink("ws_sweep", {
                    "ev": "trip", "ts": round(now_ts, 3), "mode": "exempt",
                    "event": ev, "ticker": t, "order_id": oid, "side": side,
                    "px": px, "count": n, "rem_before": rem, "fill_ts": fts,
                    "trade_id": body.get("trade_id"), "hold_s": hold_s,
                    "pull": []})
                log(f"{self.tag} sweep breaker (exempt): {t} "
                    f"{side.upper()} @ {px:g}c filled out ({n:g}) -> mention "
                    f"series, nothing pulled")
                return
            # ESCALATING HOLDS (2026-10-17, SWEEP_ESCALATE): this trip's place
            # in the event's chain, kept the same way dry and on
            esc_n, esc_hold, shadowed = 1, hold_s, False
            esc_on = SWEEP_ESCALATE != "off" and \
                not sweep_escalate_excluded(series_of(t))
            if esc_on:
                st = self._sweep_esc.get(key)
                if st is not None and now_ts < st["hold_until"]:
                    # only dry (or a control trip) gets here: `on` would still
                    # be holding the event, so this trip would not happen and
                    # it does not advance the chain
                    shadowed = True
                    esc_n = int(st["n"])
                    self._sweep["esc_shadowed"] += 1
                else:
                    esc_n = int(st["n"]) + 1 if (
                        st is not None and now_ts <= st["reset_at"]) else 1
                    esc_hold = sweep_escalated_hold(esc_n, hold_s)
                    self._sweep_esc[key] = {
                        "n": esc_n, "hold_until": now_ts + esc_hold,
                        "reset_at": now_ts + esc_hold + SWEEP_ESCALATE_WINDOW_SECS}
                    if esc_n == 2:
                        self._sweep["esc_2"] += 1
                    elif esc_n >= 3:
                        self._sweep["esc_3"] += 1
            self._sweep["trips"] += 1
            # on: live, unless drawn into the control (SWEEP_HOLDOUT)
            live = SWEEP_BREAKER == "on" and \
                not (SWEEP_HOLDOUT > 0 and self._ws_rng.random() < SWEEP_HOLDOUT)
            mode = "on" if live else ("control" if SWEEP_BREAKER == "on" else "dry")
            base_hold_s = hold_s
            if live and SWEEP_ESCALATE == "on" and esc_hold > hold_s:
                hold_s = esc_hold
                self._sweep_until[key] = now_ts + hold_s
                self._sweep["esc_live"] += 1
            if live:
                self._sweep_hold[key] = now_ts + hold_s
                self._sweep["trips_live"] += 1
            elif SWEEP_BREAKER == "on":
                self._sweep["trips_control"] += 1
            pull = [(tk, o) for tk, lst in self._resting_view.items()
                    if _in_trip(tk) for o in lst
                    if o["order_id"] != oid and o["rem"] > 0]
            # ...and the event's orders placed since the last rebuild, which
            # only the ledger holds yet
            in_view = {o["order_id"] for _tk, o in pull} | {oid}
            for l_oid, led in list(self.state.ledger.items()):
                l_t = str(led.get("ticker") or "")
                l_rem = float(led.get("remaining_count") or 0.0)
                if l_oid in in_view or l_oid in self._cycle_cancelled or \
                        l_rem <= 0 or not l_t or not _in_trip(l_t):
                    continue
                if any(o["order_id"] == l_oid for o in self._resting_view.get(l_t, ())):
                    continue
                l_px = led.get("yes_price_exact")
                pull.append((l_t, {"order_id": l_oid,
                                   "side": str(led.get("book_side") or ""),
                                   "px": float(l_px) if l_px is not None
                                   else float(led.get("yes_price") or 0),
                                   "rem": l_rem}))
            rec = {
                "ev": "trip", "ts": round(now_ts, 3), "mode": mode,
                "event": ev, "ticker": t, "order_id": oid, "side": side,
                "px": px, "count": n, "rem_before": rem, "fill_ts": fts,
                "trade_id": body.get("trade_id"), "hold_s": hold_s,
                "pull": [[tk, o["order_id"], o["side"], o["px"], o["rem"]]
                         for tk, o in pull]}
            if len(group) > 1:
                rec["linked"] = list(group)
            if esc_on:
                rec.update(trip_n=esc_n, esc_hold_s=esc_hold, esc=SWEEP_ESCALATE,
                           esc_shadowed=shadowed)
            elif SWEEP_ESCALATE != "off":
                rec["esc"] = "excluded"
            self._sink("ws_sweep", rec)
            others = sorted({self._event_of(tk) for tk, _o in pull} - {ev})
            esc_txt = ""
            if shadowed:
                esc_txt = (f"; escalation ({SWEEP_ESCALATE}): inside the longer "
                           f"hold of trip {esc_n} -- on, no trip here")
            elif esc_on and esc_n >= 2:
                esc_txt = (f"; trip {esc_n} within "
                           f"{SWEEP_ESCALATE_WINDOW_SECS / 60:.0f} min of the last "
                           f"hold: " + (f"held {hold_s / 60:.0f} min"
                                        if hold_s > base_hold_s else
                                        f"escalation {SWEEP_ESCALATE}, would hold "
                                        f"{esc_hold / 60:.0f} min"))
            log(f"{self.tag} sweep breaker ({mode}): {t} "
                f"{side.upper()} @ {px:g}c filled out ({n:g}) -> "
                f"{'pulling' if live else 'would pull'} "
                f"{len(pull)} order(s) in {ev}"
                + (f" + linked {'/'.join(group)}"
                   + (f" ({', '.join(others)})" if others else "")
                   if len(group) > 1 else "")
                + f" for {hold_s:.0f}s" + esc_txt)
            if not live:
                return
            for _tk, o in pull:
                while self._ws_cancel_times and \
                        self._ws_cancel_times[0] < now_ts - 60.0:
                    self._ws_cancel_times.popleft()
                if len(self._ws_cancel_times) >= WS_FAST_MAX_CANCELS_PER_MIN:
                    self._sweep["skipped_budget"] += 1  # the cycle pulls it
                    continue
                self._ws_cancel_times.append(now_ts)
                if self.cancel_order(o["order_id"], reason="sweep_breaker"):
                    self.state.cancelled_today += 1
                    self._sweep["cancels"] += 1
                    o["rem"] = 0.0
                    self._ws_suspect.pop(o["order_id"], None)
                    if o["order_id"] in self._ws_flagged:
                        self._ws_episode_end(o["order_id"], "cancel", now_ts,
                                             by="sweep")
        except Exception as e:
            log(f"{self.tag} ! sweep breaker failed: {e}")

    def _build_resting_view(self, resting: List[dict], now_ts: float) -> None:
        """Our resting orders per ticker as this cycle leaves them -- the
        cycle-top read less this cycle's cancels, at this cycle's amended
        prices, plus this cycle's placements (ledger) -- for _ws_fast_check."""
        view: Dict[str, List[dict]] = {}
        seen: Set[str] = set()
        # our WS fills that landed after the cycle's resting read (more than
        # 1s after, so a fill at the boundary is never taken off twice): the
        # read cannot hold them, and an amend's new size nets out only the
        # fills before that read
        after: Dict[str, float] = {}
        cut = self._resting_read_at + 1.0
        for f_ts, f_oid, f_n in self._ws_fill_log:
            if f_ts > cut:
                after[f_oid] = after.get(f_oid, 0.0) + f_n

        def add(oid: str, t: str, side: str, px: float, rem: float,
                placed: float) -> None:
            rem -= after.get(oid, 0.0)
            if not oid or oid in seen or not t or rem <= 0:
                return
            seen.add(oid)
            view.setdefault(t, []).append({
                "order_id": oid, "side": side, "px": float(px),
                "rem": float(rem), "placed": float(placed),
                "pad": _order_is_pad(side, int(round(px)))})

        for o in resting:
            oid = str(o.get("order_id") or "")
            if oid in self._cycle_cancelled:
                continue
            parsed = order_yes_book_cents(o)
            if parsed is None:
                continue
            side, px = parsed
            ox = order_yes_exact_cents(o)
            pxe = float(self._cycle_amended[oid]) if oid in self._cycle_amended \
                else (ox if ox is not None else float(px))
            # an amend this cycle may have resized it (10/4: an ask amended
            # 38 -> 30 and then filled out for 30 read as a partial fill)
            rem = self._cycle_amended_ct.get(oid)
            add(oid, str(o.get("ticker") or ""), side, pxe,
                rem if rem is not None else order_remaining(o),
                self.state.order_ages.get(oid, 0.0))
        for oid, led in list(self.state.ledger.items()):
            if oid in self._cycle_cancelled or oid in seen:
                continue
            px = led.get("yes_price_exact")
            px = float(px) if px is not None else float(led.get("yes_price") or 0)
            add(oid, str(led.get("ticker") or ""), str(led.get("book_side") or ""),
                px, float(led.get("remaining_count") or 0.0),
                float(led.get("_placed_at") or now_ts))
        self._resting_view = view
        self._ws_recheck_all = True        # the next check looks at all of it
        # an order the cycle amended keeps no first-seen-ahead time from its
        # old price: the two looks start over at the new one
        for k in [k for k in self._ws_suspect
                  if k not in seen or k in self._cycle_amended]:
            self._ws_suspect_end(k, now_ts, "cycle")   # unseen lines, arms (2026-10-17)
        self._ws_suspect = {k: v for k, v in self._ws_suspect.items()
                            if k in seen and k not in self._cycle_amended}
        self._ws_arm = {k: v for k, v in self._ws_arm.items()
                        if k in self._ws_suspect or k in self._ws_flagged}
        # the stale-quote episodes this cycle closed: amended to a new price,
        # cancelled, or gone from the book (filled out / expired)
        if self._ws_flagged:
            cur = {o["order_id"]: o for lst in view.values() for o in lst}
            for oid in list(self._ws_flagged):
                o = cur.get(oid)
                if o is None:
                    self._ws_episode_end(
                        oid, "cancel" if oid in self._cycle_cancelled else "gone",
                        now_ts)
                elif abs(o["px"] - self._ws_flagged[oid]["px"]) > 1e-9:
                    self._ws_episode_end(oid, "amend", now_ts, new_px=o["px"])

    def _back_of_line_pass(self, resting: List[dict], now_ts: float) -> None:
        """BACK OF THE LINE (2026-10-17, BACK_OF_LINE), the PLAN, at the end of
        a cycle: every BACK_OF_LINE_EVERY_SECS, pick our whole-cent rungs that
        share their price with at least BACK_OF_LINE_MIN_BEHIND external
        contracts (the WS book less our own). No API call here: the line reads
        and the moves run BETWEEN cycles, in _idle (_back_of_line_step; Jack
        2026-10-17: "send it between cycles"), so they never hold a cycle up.
        A new plan replaces an unfinished one. Live orders only. Never
        raises."""
        if BACK_OF_LINE == "off" or self._ws is None or not self.live:
            return
        if now_ts - self._bol_last_pass < BACK_OF_LINE_EVERY_SECS:
            return
        self._bol_last_pass = now_ts
        st = self._bol
        try:
            if self._bol_plan is not None and not self._bol_plan["done"]:
                st["unfinished"] += 1
            st["passes"] += 1
            view = self._resting_view
            live_ids = {o["order_id"] for lst in view.values() for o in lst}
            for d in (self._bol_bumps, self._bol_last):
                for oid in [k for k in d if k not in live_ids]:
                    del d[oid]
            # an order with a fill since the cycle's read has an unsettled
            # count: the +1 must go on top of filled + remaining exactly
            cut = self._resting_read_at + 1.0
            filled_since = {f_oid for f_ts, f_oid, _n in self._ws_fill_log
                            if f_ts > cut}
            read = {str(o.get("order_id") or ""): o for o in resting}
            cands: List[dict] = []
            for t, lst in view.items():
                lv: Optional[Tuple[Dict[float, float], Dict[float, float]]] = None
                for o in lst:
                    oid = o["order_id"]
                    px = float(o["px"])
                    if o.get("pad") or abs(px - round(px)) > 0.005 or o["rem"] < 1:
                        continue
                    # placed this cycle (not in the read) or amended: at the
                    # back already
                    if oid not in read or oid in self._cycle_amended or \
                            oid in filled_since:
                        continue
                    if now_ts - self._bol_last.get(oid, 0.0) < BACK_OF_LINE_COOLDOWN_SECS:
                        continue
                    if BACK_OF_LINE_MAX_BUMPS and \
                            self._bol_bumps.get(oid, 0) >= BACK_OF_LINE_MAX_BUMPS:
                        continue
                    # FAIR CLOSE: the closing rung wants the front of its line
                    if self._fair_close_px.get(t) == (o["side"], int(round(px))):
                        continue
                    if lv is None:
                        lv = self._ws.book_levels(t) or ({}, {})
                    c = int(round(px))
                    side_lv, at = (lv[0], c / 100.0) if o["side"] == "bid" \
                        else (lv[1], (100 - c) / 100.0)
                    own = sum(x["rem"] for x in lst if x["side"] == o["side"]
                              and abs(float(x["px"]) - px) < 0.005)
                    ext = back_of_line_level(side_lv, at) - own
                    if ext >= BACK_OF_LINE_MIN_BEHIND:
                        cands.append({"t": t, "oid": oid, "side": o["side"], "c": c,
                                      "rem": float(o["rem"]), "ext": ext,
                                      "ro": read[oid]})
            st["candidates"] += len(cands)
            self._bol_plan = {"at": now_ts, "read_at": self._resting_read_at,
                              "cands": cands,
                              "tickers": sorted({x["t"] for x in cands}),
                              "next_chunk": 0, "ahead": {}, "moves": None,
                              "next_move": 0, "done": not cands}
        except Exception as e:
            log(f"{self.tag} ! back-of-line plan failed: {e}")

    def _back_of_line_step(self, now_ts: float, slice_secs: float = 0.3) -> bool:
        """BACK OF THE LINE, the SENDS, between cycles (called from _idle): up
        to `slice_secs` of work on the current plan -- first its queue-position
        reads (BACK_OF_LINE_CHUNK markets a GET), then its moves, the most
        external size behind first and at most BACK_OF_LINE_MAX_PER_PASS, each
        re-checked just before it goes and paced like the cycle's writes
        (PLACE_RATE_PER_SEC; a move is two writes). True while work remains.
        Never raises."""
        p = self._bol_plan
        if p is None or p["done"]:
            return False
        if BACK_OF_LINE == "off" or not self.live:
            p["done"] = True
            return False
        st = self._bol
        t0 = time.time()
        try:
            st["steps"] += 1
            while p["next_chunk"] < len(p["tickers"]):
                if time.time() - t0 > slice_secs:
                    return True
                i = p["next_chunk"]
                p["next_chunk"] = i + BACK_OF_LINE_CHUNK
                self._heartbeat = time.time()
                try:
                    resp = self.client.get_queue_positions(
                        market_tickers=",".join(p["tickers"][i:i + BACK_OF_LINE_CHUNK]))
                    st["reads"] += 1
                except Exception as e:
                    st["read_fails"] += 1
                    if st["read_fails"] <= 3 or st["read_fails"] % 100 == 0:
                        log(f"{self.tag} ! back-of-line queue read failed "
                            f"({st['read_fails']}): {e}")
                    continue
                for q in (resp or {}).get("queue_positions") or []:
                    try:
                        p["ahead"][str(q.get("order_id") or "")] = \
                            float(q.get("queue_position_fp"))
                    except (TypeError, ValueError):
                        continue
            if p["moves"] is None:
                moves = []
                for m in p["cands"]:
                    a = p["ahead"].get(m["oid"])
                    if a is None:
                        st["no_position"] += 1
                        continue
                    behind = m["ext"] - a
                    if behind < max(BACK_OF_LINE_MIN_BEHIND,
                                    BACK_OF_LINE_MIN_BEHIND_FRAC * m["ext"]):
                        continue
                    moves.append(dict(m, ahead=a, behind=behind))
                st["front"] += len(moves)
                # the most protection per call first
                moves.sort(key=lambda x: -x["behind"])
                if len(moves) > BACK_OF_LINE_MAX_PER_PASS:
                    st["capped"] += len(moves) - BACK_OF_LINE_MAX_PER_PASS
                    moves = moves[:BACK_OF_LINE_MAX_PER_PASS]
                p["moves"] = moves
            while p["next_move"] < len(p["moves"]):
                if time.time() - t0 > slice_secs:
                    return True
                m = p["moves"][p["next_move"]]
                p["next_move"] += 1
                self._back_of_line_move(m, p, now_ts)
            p["done"] = True
            return False
        except Exception as e:
            p["done"] = True
            log(f"{self.tag} ! back-of-line step failed: {e}")
            return False

    def _back_of_line_move(self, m: dict, p: dict, now_ts: float) -> None:
        """One planned move, re-checked first: the order still rests at the
        planned price and size (no fill since the plan's read, no re-price by
        a later cycle) and its event is not held by the sweep breaker. Then
        +1 contract (Kalshi re-queues it at the back) and straight -1 (a size
        cut keeps that place), or, dry, a logged row."""
        st = self._bol
        t, oid, c = m["t"], m["oid"], m["c"]
        cur = next((x for x in self._resting_view.get(t, ())
                    if x["order_id"] == oid), None)
        if cur is None or abs(float(cur["px"]) - c) > 0.005 or \
                abs(float(cur["rem"]) - m["rem"]) > 1e-6 or \
                oid in self._cycle_amended or \
                any(f_oid == oid and f_ts > p["read_at"] + 1.0
                    for f_ts, f_oid, _n in self._ws_fill_log) or \
                self.sweep_held(self._event_of(t), now_ts) or \
                self.group_held(t, m["side"], now_ts):
            st["stale"] += 1
            return
        rec = {"ts": round(now_ts, 3), "mode": BACK_OF_LINE, "ticker": t,
               "order_id": oid, "side": m["side"], "px": c,
               "rem": round(m["rem"], 2), "ahead": round(m["ahead"], 2),
               "ext": round(m["ext"], 2), "behind": round(m["behind"], 2),
               "bumps": self._bol_bumps.get(oid, 0),
               "plan_age_s": round(now_ts - p["at"], 1)}
        did = False
        if BACK_OF_LINE == "on":
            if self._bol_pacer is None:
                self._bol_pacer = WritePacer(PLACE_RATE_PER_SEC)
            self._bol_pacer.wait(2)
            # same price, one more contract: Kalshi re-queues it at the back
            # (amend_order_inplace sends the read's filled + this)...
            ro = m["ro"]
            rem0 = order_remaining(ro)
            q = Quote(ticker=t, book_side=m["side"], price_cents=c, count=rem0 + 1.0)
            did = self.amend_order_inplace(ro, q, now_ts, reason="back_of_line")
            rec["ok"] = bool(did)
            if did:
                st["requeued"] += 1
                self._bol_bumps[oid] = self._bol_bumps.get(oid, 0) + 1
                cur["rem"] = rem0 + 1.0
                # ...and straight back to its size (Jack 2026-10-17: "add this
                # if it's cleaner"): a size cut keeps the order's place, now
                # the back. The total sent is the read's filled + rem0, so a
                # fill landing between the two calls still nets one contract.
                q2 = Quote(ticker=t, book_side=m["side"], price_cents=c, count=rem0)
                back = self.amend_order_inplace(ro, q2, now_ts,
                                                reason="back_of_line_restore")
                rec["restored"] = bool(back)
                if back:
                    st["restored"] += 1
                    cur["rem"] = rem0
                else:
                    st["restore_fails"] += 1
            else:
                st["amend_fails"] += 1
        else:
            st["would_requeue"] += 1
        self._bol_last[oid] = now_ts
        self._sink("back_of_line", rec)
        while self._bol_logged and self._bol_logged[0] < now_ts - 3600:
            self._bol_logged.popleft()
        if len(self._bol_logged) < 30:
            self._bol_logged.append(now_ts)
            log(f"{self.tag} back-of-line ({BACK_OF_LINE}): "
                f"{'re-queued' if did else 'would re-queue'} {t} "
                f"{m['side'].upper()} @ {c}c ({m['rem']:g} left): "
                f"{m['ahead']:g} ahead, {m['behind']:g} of {m['ext']:g} external "
                f"contracts behind")

    def _rate_limit_scan_logs(self) -> Dict[str, Tuple[int, str, int]]:
        """The other bots' new 429 lines since the last look: {bot: (rejected
        writes, the first one's line, reads)} -- a line RATE_LIMIT_READ_LINE
        calls a read is counted apart (2026-10-22). A log first seen starts
        from its current end (no history); a log that shrank is re-anchored
        at its end."""
        found: Dict[str, Tuple[int, str, int]] = {}
        cutoff = time.time() - 2 * 86400
        for d in RATE_LIMIT_SCAN_DIRS:
            try:
                names = [n for n in os.listdir(d) if n.endswith(".log")]
            except OSError:
                continue
            for n in names:
                path = os.path.join(d, n)
                try:
                    stt = os.stat(path)
                except OSError:
                    continue
                if stt.st_mtime < cutoff:
                    continue
                size = stt.st_size
                off = self._rl_offsets.get(path)
                if off is None or size < off:
                    self._rl_offsets[path] = size
                    continue
                if size == off:
                    continue
                start = max(off, size - RATE_LIMIT_MAX_READ_BYTES)
                try:
                    with open(path, "rb") as f:
                        f.seek(start)
                        chunk = f.read(size - start)
                except OSError:
                    continue
                self._rl_offsets[path] = size
                if b"HttpError(429" not in chunk:
                    continue
                lines = [ln for ln in chunk.decode("utf-8", "replace").splitlines()
                         if "HttpError(429" in ln]
                writes = [ln for ln in lines if not RATE_LIMIT_READ_LINE.search(ln)]
                bot = f"{os.path.basename(d)}/{n.rsplit('.', 1)[0]}"
                cnt, ex, rd = found.get(bot, (0, "", 0))
                found[bot] = (cnt + len(writes), ex or (writes[0][:240] if writes else ""),
                              rd + len(lines) - len(writes))
        return found

    def _rate_limit_watch(self, now_ts: float) -> None:
        """RATE-LIMIT ALERT (2026-10-17, RATE_LIMIT_ALERT): count the 429s
        since the last look -- this bot's, off the Kalshi client's counter,
        and the other bots', off the lines their logs gained -- and send an
        urgent `rate_limit` alert (email) when any write was rejected. Never
        raises."""
        if not RATE_LIMIT_ALERT or now_ts - self._rl_last < RATE_LIMIT_CHECK_SECS:
            return
        self._rl_last = now_ts
        st = self._rl
        try:
            st["looks"] += 1
            cnt = getattr(_kalshi_client_mod, "RATE_LIMITED", None) or {}
            w = int(cnt.get("writes", 0)) - self._rl_seen["writes"]
            r = int(cnt.get("reads", 0)) - self._rl_seen["reads"]
            self._rl_seen = {"writes": int(cnt.get("writes", 0)),
                             "reads": int(cnt.get("reads", 0))}
            # (a log seen for the first time only anchors, so the first look
            # reports this bot's own 429s since startup and nobody's history)
            fleet = self._rate_limit_scan_logs()
            st["imm_writes"] += max(0, w)
            st["imm_reads"] += max(0, r)
            n_fleet = sum(c for c, _ex, _rd in fleet.values())
            fleet_reads = sum(rd for _c, _ex, rd in fleet.values())
            st["fleet"] += n_fleet
            st["fleet_reads"] += fleet_reads
            if w <= 0 and n_fleet <= 0:
                if r > 0 or fleet_reads > 0:
                    log(f"{self.tag} rate limit: "
                        + " and ".join(x for x in (
                            f"{r} of our reads (retried)" if r > 0 else "",
                            f"{fleet_reads} of the other bots' reads"
                            if fleet_reads > 0 else "") if x)
                        + f" got a 429 in the last {RATE_LIMIT_CHECK_SECS / 60:g} min "
                          f"-- reads, so no email")
                return
            parts = []
            if w > 0:
                parts.append(f"this bot: {w} write(s) rejected"
                             + (f" (last {cnt.get('last')})" if cnt.get("last") else ""))
            if r > 0:
                parts.append(f"{r} of its reads got a 429 and were retried")
            for bot, (c, ex, _rd) in sorted(fleet.items()):
                if c > 0:
                    parts.append(f"{bot}: {c} rejected (e.g. {ex})")
            msg = (f"Kalshi rate-limit rejections (429 Too Many Requests) in the "
                   f"last {RATE_LIMIT_CHECK_SECS / 60:g} min -- " + "; ".join(parts)
                   + f". This bot paces its writes at {PLACE_RATE_PER_SEC:g}/s "
                     f"(IMM_PLACE_RATE_PER_SEC, raised from 12 on 10/17); lower "
                     f"it if these keep coming.")
            st["alerts"] += 1
            st["last_alert_ts"] = now_ts
            st["last"] = msg[:500]
            self.alerter.alert("rate_limit", msg, key="rate_limit", urgent=True,
                               now_ts=now_ts)
        except Exception as e:
            log(f"{self.tag} ! rate-limit watch failed: {e}")

    # ---- exchange pause (2026-10-22, EXCH_PAUSE_MODE) ------------------------

    def _xp_poll(self, now_ts: float, force: bool = False) -> Optional[Set[int]]:
        """GET /exchange/status: what it shows not trading
        (exchange_status_paused). Read every EXCH_PAUSE_POLL_SECS while a
        pause holds, or now when `force`d (a refusal to judge) -- at most
        every 5s, the last read answering in between. A shard it shows
        trading again leaves its pause, unless that pause began against the
        status (by_status false). Returns the read (None: not read, or
        unreadable). Never raises."""
        if now_ts - self._xp_status_at < (5.0 if force else EXCH_PAUSE_POLL_SECS):
            return self._xp_status if force else None
        if not force and not self._xp:
            return None
        self._xp_status_at = now_ts
        st = self._xp_stats
        st["polls"] += 1
        try:
            paused = exchange_status_paused(self.client.get_exchange_status())
        except Exception:
            paused = None
        self._xp_status = paused
        if paused is None:
            st["poll_fails"] += 1
            return None
        for s, p in list(self._xp.items()):
            if -1 in paused or s in paused:
                p["by_status"] = True      # it agrees: trusted to say when it ends
            elif p.get("by_status"):
                self._xp_end(s, now_ts, "Kalshi's status shows it trading")
        return paused

    def _xp_paused_for(self, ticker: str) -> Optional[dict]:
        """The pause holding `ticker`'s shard, or None (a market of unknown
        shard is never held)."""
        s = self._ticker_shard.get(ticker) if self._xp else None
        return None if s is None else self._xp.get(s)

    def _xp_waiting(self, ticker: str, now_ts: float) -> bool:
        """EXCHANGE PAUSE: True when a place / amend for `ticker` must wait --
        its shard is paused and no probe is due (counted as held). Reads the
        status on its poll clock. The write loops ask first, so a held write
        is skipped before it is paced. Never raises."""
        if not self._xp:
            return False
        try:
            self._xp_poll(now_ts)
            p = self._xp_paused_for(ticker)
            if p is None or now_ts - p["last_refusal"] >= EXCH_PAUSE_PROBE_SECS:
                return False
            p["held"] += 1
            self._xp_stats["held"] += 1
            return True
        except Exception:
            return False

    def _cash_key(self, ticker: str):
        s = self._ticker_shard.get(ticker)
        return s if s is not None else ("market", ticker)

    def _cash_waiting(self, q, now_ts: float) -> bool:
        """SHARD CASH PAUSE: True when the new order `q` waits -- its shard
        refused one at least this costly for cash less than
        SHARD_CASH_PAUSE_SECS ago (counted as held). A pause past its time
        ends here. Never raises."""
        if not self._cash_pause:
            return False
        try:
            key = self._cash_key(q.ticker)
            p = self._cash_pause.get(key)
            if p is None:
                return False
            if now_ts >= p["until"]:
                self._cash_pause.pop(key, None)
                log(f"{self.tag} shard cash pause over: {p['label']} -- {p['held']} "
                    f"new order(s) held, {p['refused']} refused; trying again")
                return False
            if quote_cost_dollars(q) >= p["ceiling"] - 1e-9:
                p["held"] += 1
                self._cash_stats["held"] += 1
                return True
            return False
        except Exception:
            return False

    def _cash_refused(self, q, e, now_ts: float) -> bool:
        """SHARD CASH PAUSE: a create Kalshi refused for cash starts its
        shard's pause, or lowers the bar of the one running. True when it was
        a cash refusal. Never raises."""
        if SHARD_CASH_PAUSE_SECS <= 0 or not self.live:
            return False
        try:
            code = shard_cash_code(e)
            if not code:
                return False
            key = self._cash_key(q.ticker)
            cost = quote_cost_dollars(q)
            bar = 0.0 if code == "insufficient_shard_balance" else cost
            self._cash_stats["refused"] += 1
            p = self._cash_pause.get(key)
            if p is not None and now_ts < p["until"]:
                p["refused"] += 1
                p["ceiling"] = min(p["ceiling"], bar)
                return True
            label = (f"shard {key}" if isinstance(key, int)
                     else f"{q.ticker} (shard unknown)")
            self._cash_pause[key] = {"until": now_ts + SHARD_CASH_PAUSE_SECS,
                                     "ceiling": bar, "held": 0, "refused": 1,
                                     "label": label}
            self._cash_stats["pauses"] += 1
            log(f"{self.tag} shard cash pause: {label} refused a ${cost:,.2f} "
                f"{q.book_side} on {q.ticker} ({code}); new orders there costing "
                f"${bar:,.2f}+ wait {SHARD_CASH_PAUSE_SECS / 60:g} min")
            return True
        except Exception:
            return False

    def _xp_hold(self, ticker: str, now_ts: float) -> bool:
        """EXCHANGE PAUSE, at the send (place_order / amend_order_inplace):
        True holds the write. When the probe is due this one write goes, and
        the probe clock restarts."""
        if self._xp_waiting(ticker, now_ts):
            return True
        p = self._xp_paused_for(ticker)
        if p is not None:
            p["last_refusal"] = now_ts
            p["probes"] += 1
            self._xp_stats["probes"] += 1
        return False

    def _xp_refused(self, ticker: str, e, kind: str,
                    now_ts: Optional[float] = None) -> bool:
        """EXCHANGE PAUSE: judge a place / amend Kalshi refused. True when it
        is a trading pause and `ticker`'s shard is (now) paused -- a pause
        code with /exchange/status showing the shard (or the exchange) not
        trading, or, the status unreadable or not agreeing, pause-code
        refusals across EXCH_PAUSE_EVENTS events of the shard inside
        EXCH_PAUSE_PROBE_SECS; any other 409/503 only with the status
        agreeing. A market of unknown shard never pauses one. Never raises."""
        if EXCH_PAUSE_MODE != "on" or not self.live:
            return False
        try:
            now_ts = time.time() if now_ts is None else now_ts
            s = self._ticker_shard.get(ticker)
            code = exchange_pause_code(e)
            if s is None or (not code and getattr(e, "status", None) not in (409, 503)):
                return False
            p = self._xp.get(s)
            if p is not None:              # paused already: a probe refused
                p["last_refusal"] = now_ts
                p["refused"] += 1
                self._xp_stats["refused"] += 1
                return True
            status = self._xp_poll(now_ts, force=True)
            agrees = status is not None and (-1 in status or s in status)
            if not agrees:
                if not code:
                    return False
                q = self._xp_refusals.setdefault(s, deque())
                q.append((now_ts, self._event_of(ticker)))
                while q and q[0][0] < now_ts - EXCH_PAUSE_PROBE_SECS:
                    q.popleft()
                if len({ev for _t, ev in q}) < EXCH_PAUSE_EVENTS:
                    return False
            self._xp_begin(s, ticker, code or kalshi_error_code(e)
                           or f"HTTP {getattr(e, 'status', '?')}", kind, now_ts,
                           agrees, status)
            return True
        except Exception as ex:
            log(f"{self.tag} ! exchange-pause check failed: {ex}")
            return False

    def _xp_begin(self, s: int, ticker: str, code: str, kind: str, now_ts: float,
                  agrees: bool, status: Optional[Set[int]]) -> None:
        """A pause begins on shard `s` (one that left it under
        EXCH_PAUSE_MERGE_SECS ago continues: its start, counts, email)."""
        last = self._xp_recent.pop(s, None)
        cont = last is not None and now_ts - last["ended"] < EXCH_PAUSE_MERGE_SECS
        p = {"since": now_ts, "last_refusal": now_ts, "code": code, "kind": kind,
             "ticker": ticker, "by_status": agrees, "held": 0, "refused": 1,
             "probes": 0, "alerted": False, "closure": None}
        if cont:
            for k in ("since", "held", "probes", "alerted", "closure"):
                p[k] = last[k]
            p["refused"] += last["refused"]
        else:
            self._xp_stats["pauses"] += 1
        self._xp[s] = p
        self._xp_stats["refused"] += 1
        self._xp_refusals.pop(s, None)
        c, err = self._xp_closure(now_ts)
        log(f"{self.tag} EXCHANGE PAUSE{' (again)' if cont else ''} on shard {s}: "
            f"Kalshi refused a {kind} on {ticker} ({code}); "
            + ("/exchange/status shows it not trading" if agrees else
               f"{EXCH_PAUSE_EVENTS}+ events refused in {EXCH_PAUSE_PROBE_SECS:g}s "
               f"with its status {'unreadable' if status is None else 'showing it trading'}")
            + f" -- places and amends there held (cancels still go out); the "
              f"status read every {EXCH_PAUSE_POLL_SECS:g}s, a probe write every "
              f"{EXCH_PAUSE_PROBE_SECS:g}s; "
            + (f"inside Kalshi's published closure {_et_clock(c[0], day=True)}-"
               f"{_et_clock(c[1])} ET" if c else
               "NOT in Kalshi's published schedule" if not err else
               f"Kalshi's schedule unreadable ({err})"))

    def _xp_end(self, s: int, now_ts: float, why: str) -> None:
        """A pause leaves shard `s`: logged, and sunk to
        exchange_pauses_<date>.jsonl."""
        p = self._xp.pop(s, None)
        if p is None:
            return
        self._xp_recent[s] = dict(p, ended=now_ts)
        last = {"shard": s, "since": p["since"], "ended": now_ts,
                "secs": round(now_ts - p["since"], 1), "why": why}
        last.update({k: p[k] for k in ("code", "kind", "ticker", "by_status", "held",
                                       "refused", "probes", "alerted", "closure")})
        self._xp_stats["last"] = last
        log(f"{self.tag} exchange pause over on shard {s}: {why}, after "
            f"{_dur_hm(now_ts - p['since'])} ({p['held']} writes held, "
            f"{p['refused']} refused, {p['probes']} probes)")
        self._sink("exchange_pauses", dict(last))

    def _xp_ok(self, ticker: str, kind: str) -> None:
        """A place / amend Kalshi took: its shard trades, so a pause there ends."""
        s = self._ticker_shard.get(ticker)
        if s is not None and s in self._xp:
            self._xp_end(s, time.time(), f"Kalshi took a {kind} ({ticker})")

    def _xp_closure(self, ts: float) -> Tuple[Optional[Tuple[float, float]], str]:
        """(the closure of the cached /exchange/schedule covering ts, or None;
        '' or why that schedule cannot say)."""
        if self._xp_sched is None:
            return None, self._xp_sched_err or "not read yet"
        try:
            return published_closure(self._xp_sched, ts), ""
        except ValueError as e:
            return None, str(e)

    def _xp_watchdog_view(self, selected, resting):
        """The selected markets and resting orders the watchdog judges: those
        on a shard Kalshi has paused left out -- all of them while its status
        (read during the pause) shows the whole exchange paused."""
        if not self._xp:
            return selected, resting
        st = self._xp_status or set()
        if -1 in st:
            return [], []
        out = set(self._xp) | st
        return ([t for t in selected if self._ticker_shard.get(t) not in out],
                [o for o in resting
                 if self._ticker_shard.get(o.get("ticker", "")) not in out])

    def _xp_shard_paused(self, ticker: str) -> bool:
        """True for a market _xp_watchdog_view leaves out: its shard held by
        a pause or shown paused by the status read during one -- every market
        while that status shows the whole exchange paused. The coverage alert
        asks this (coverage_exempt)."""
        if not self._xp:
            return False
        st = self._xp_status or set()
        return -1 in st or self._ticker_shard.get(ticker) in (set(self._xp) | st)

    def _xp_check(self, now_ts: float) -> None:
        """EXCHANGE PAUSE, once a full cycle: refresh Kalshi's published
        schedule (every EXCH_SCHEDULE_TTL_SECS; 10 min after a failed read
        while none is in hand), poll the status, log the pauses, and send
        the `exchange_pause` email, once a pause, when it has run
        EXCH_PAUSE_ALERT_MIN outside the published schedule (or with it
        unreadable) or EXCH_PAUSE_OVERRUN_MIN past the published reopening.
        Never raises."""
        if EXCH_PAUSE_MODE != "on" or not self.live:
            return
        try:
            age = now_ts - self._xp_sched_at
            if age >= EXCH_SCHEDULE_TTL_SECS or (self._xp_sched is None and age >= 600):
                self._xp_sched_at = now_ts
                try:
                    js = self.client.get("/exchange/schedule")
                    published_closure(js, now_ts)            # it reads
                    self._xp_sched, self._xp_sched_err = js, ""
                except Exception as e:
                    self._xp_sched_err = f"{type(e).__name__}: {e}"[:200]
                    log(f"{self.tag} ! exchange schedule read failed "
                        f"({self._xp_sched_err})"
                        + ("; keeping the last one" if self._xp_sched is not None else ""))
            if not self._xp:
                return
            self._xp_poll(now_ts)
            if not self._xp:
                return
            c, err = self._xp_closure(now_ts)
            parts, due = [], []
            for s, p in sorted(self._xp.items()):
                dur = now_ts - p["since"]
                parts.append(f"shard {s} {_dur_hm(dur)} ({p['code']}; {p['held']} "
                             f"held, {p['refused']} refused, {p['probes']} probes)")
                if c is not None:
                    p["closure"] = list(c)       # a published closure: no email inside it
                    continue
                if p["alerted"]:
                    continue
                if p["closure"] is not None:
                    over = now_ts - p["closure"][1]
                    if over >= EXCH_PAUSE_OVERRUN_MIN * 60:
                        due.append((p["since"], s, p,
                                    f"Kalshi's published closure ended at "
                                    f"{_et_clock(p['closure'][1])} ET, {_dur_hm(over)} ago"))
                elif dur >= EXCH_PAUSE_ALERT_MIN * 60:
                    due.append((p["since"], s, p,
                                "that is outside Kalshi's published schedule "
                                "(GET /exchange/schedule)" if not err else
                                f"Kalshi's schedule could not be read ({err})"))
            if due:
                # one email for the shards that came due together
                due.sort(key=lambda x: (x[0], x[1]))
                since, _s, p0, why = due[0]
                for _t, _s, p, _w in due:
                    p["alerted"] = True
                self._xp_stats["alerts"] += 1
                shards = ", ".join(str(s) for _t, s, _p, _w in due)
                self.alerter.alert(
                    "exchange_pause",
                    f"Kalshi has refused this bot's orders on shard"
                    f"{'s' if len(due) > 1 else ''} {shards} for "
                    f"{_dur_hm(now_ts - since)} (since {_et_clock(since, day=True)} ET: "
                    f"{p0['code']}), and {why}. The bot holds new orders and "
                    f"amends there and resumes by itself once Kalshi takes one "
                    f"again (its status read every {EXCH_PAUSE_POLL_SECS:g}s, a "
                    f"probe order every {EXCH_PAUSE_PROBE_SECS:g}s). If this "
                    f"recurs at a new time, Kalshi's maintenance schedule has "
                    f"changed.", key="exchange_pause", urgent=True, now_ts=now_ts)
            log(f"{self.tag} exchange pause: " + ", ".join(parts) + "; "
                + (f"inside Kalshi's published closure to {_et_clock(c[1])} ET" if c
                   else "outside Kalshi's published schedule" if not err
                   else f"schedule unreadable ({err})"))
        except Exception as e:
            log(f"{self.tag} ! exchange-pause check failed: {e}")

    # ---- dollar worst-case limits + skew (2026-10-17, RISK_LIMITS, dry) ----

    def _risk_mark(self, t: str) -> Optional[float]:
        """A market's YES mark (cents) for the dollar limits: the cycle's mark
        of a held position (state.last_mark), else the mid of the last
        two-sided external touch the cycle read; None if neither."""
        mk = self.state.last_mark.get(t)
        if mk is not None:
            return float(mk)
        p = self._last_panel.get(t)
        if p and p.get("ext_bid") is not None and p.get("ext_ask") is not None:
            return (float(p["ext_bid"]) + float(p["ext_ask"])) / 2.0
        return None

    def _risk_market_day(self, t: str) -> float:
        """The bot's reward estimate a day for a market it has orders on now
        (0 for one it does not quote)."""
        if not any(o["rem"] > 0 for o in self._resting_view.get(t, ())):
            return 0.0
        p = self._last_panel.get(t) or {}
        return float(p.get("est_frac") or 0.0) * float(p.get("pool_per_day") or 0.0)

    def _risk_smooth(self, key: str, x: float, now_ts: float) -> float:
        """`x` smoothed over RISK_REWARD_TAU_SECS (the first look: x)."""
        old = self._risk_day.get(key)
        v = x if old is None else old[0] + (x - old[0]) * (
            1.0 - math.exp(-max(0.0, now_ts - old[1]) / RISK_REWARD_TAU_SECS))
        self._risk_day[key] = (v, now_ts)
        return v

    def _risk_step(self, now_ts: float, budget_s: float) -> None:
        """RISK_LIMITS (dry): work the current pass for up to `budget_s`,
        starting a new one RISK_PASS_EVERY_SECS after the last began. The
        run's first pass only reads every event's worst case (so the group
        sums are whole before any side is judged). Never raises."""
        if RISK_LIMITS == "off":
            return
        try:
            t0 = time.time()
            if self._risk_pass is None:
                if now_ts - self._risk_last_pass < RISK_PASS_EVERY_SECS or \
                        not (self._risk_positions or self._resting_view):
                    return
                self._risk_begin_pass(now_ts)
            P = self._risk_pass
            while self._risk_queue and time.time() - t0 < budget_s:
                self._risk_eval_event(self._risk_queue.popleft(), now_ts)
            P["secs"] += time.time() - t0
            if not self._risk_queue:
                self._risk_end_pass(now_ts)
        except Exception as e:
            self._risk["fails"] += 1
            self._risk_pass = None
            self._risk_queue.clear()
            log(f"{self.tag} ! risk limits check failed: {e}")

    def _risk_begin_pass(self, now_ts: float) -> None:
        """A new pass over every event with a position on the account or an
        order of ours resting, and each group's sums from its events' last
        look (an event updates its own share when the pass reaches it)."""
        self._risk_last_pass = now_ts
        tickers = {t for t, p in self._risk_positions.items()
                   if abs(float(p or 0.0)) > 1e-9}
        tickers |= {t for t, lst in self._resting_view.items()
                    if any(o["rem"] > 0 for o in lst)}
        events: Dict[str, List[str]] = {}
        for t in sorted(tickers):
            events.setdefault(self._event_of(t), []).append(t)
        for ev in [e for e in self._risk_ev if e not in events]:
            del self._risk_ev[ev]
        for k in [k for k, (_v, ts) in self._risk_day.items()
                  if ts < now_ts - 86400]:
            del self._risk_day[k]
        gsum: Dict[str, Dict[str, float]] = {}
        for r in self._risk_ev.values():
            if r["g"] is not None:
                s = gsum.setdefault(r["g"], {"w0": 0.0, "long": 0.0, "short": 0.0,
                                             "day": 0.0, "events": 0})
                for k in ("w0", "long", "short", "day"):
                    s[k] += r[k]
                s["events"] += 1
        self._risk_pass = {"start": now_ts, "events": events, "gsum": gsum,
                           "seen": set(), "evaluated": 0, "sides": 0,
                           "unmarked": 0, "secs": 0.0}
        self._risk_queue = deque(sorted(events))

    def _risk_eval_event(self, ev: str, now_ts: float) -> None:
        """One event of the pass: its worst case, long / short dollars at
        risk and reward a day (into the group sums); then, once primed, each
        side with our orders: the worst case if all of it filled, its state
        (ok / skew / block) and a `state` line when that changed."""
        P = self._risk_pass
        tickers = P["events"].get(ev) or []
        if not tickers:
            return
        exempt = bool(RISK_EXEMPT) and series_of(tickers[0]).startswith(RISK_EXEMPT)
        g = None if exempt else risk_group_of(tickers[0])
        mm = dash_cache("markets_meta.json")
        em = dash_cache("events_meta.json").get(ev) or {}
        me, n_ev = em.get("me"), em.get("n")
        struct = {t: risk_struct(mm.get(t)) for t in tickers}
        marks = {t: self._risk_mark(t) for t in tickers}
        pos = {t: float(self._risk_positions.get(t, 0.0) or 0.0) for t in tickers}
        w0 = risk_event_worst([(t, pos[t], marks[t]) for t in tickers],
                              struct, me, n_ev)
        long_d = sum(pos[t] * marks[t] / 100.0 for t in tickers
                     if marks[t] is not None and pos[t] > 1e-9)
        short_d = sum(-pos[t] * (100.0 - marks[t]) / 100.0 for t in tickers
                      if marks[t] is not None and pos[t] < -1e-9)
        P["unmarked"] += sum(1 for t in tickers
                             if marks[t] is None and abs(pos[t]) > 1e-9)
        day = self._risk_smooth("ev:" + ev, sum(self._risk_market_day(t)
                                                for t in tickers), now_ts)
        new = {"w0": w0, "long": long_d, "short": short_d, "day": day, "g": g,
               "exempt": exempt}
        old = self._risk_ev.get(ev)
        self._risk_ev[ev] = new
        if g is not None:
            s = P["gsum"].setdefault(g, {"w0": 0.0, "long": 0.0, "short": 0.0,
                                         "day": 0.0, "events": 0})
            same = old is not None and old["g"] == g
            for k in ("w0", "long", "short", "day"):
                s[k] += new[k] - (old[k] if same else 0.0)
            if not same:
                s["events"] += 1
        P["evaluated"] += 1
        if exempt or not self._risk_primed:
            return
        lim_e = max(RISK_EVENT_FLOOR, RISK_EVENT_DAYS * day, 0.01)
        gs = P["gsum"].get(g) if g is not None else None
        lim_g = max(RISK_GROUP_FLOOR, RISK_GROUP_DAYS * gs["day"], 0.01) if gs else 0.0
        gdir = ""
        if gs:
            gdir = "short" if gs["short"] > gs["long"] + 1e-9 else \
                ("long" if gs["long"] > gs["short"] + 1e-9 else "")
        directional = g is not None and g.startswith(RISK_DIRECTIONAL_GROUPS)
        for t in tickers:
            lst = self._resting_view.get(t, ())
            for side in ("bid", "ask"):
                mine = [o for o in lst if o["side"] == side and o["rem"] > 0
                        and not o.get("pad")]
                rest = sum(o["rem"] for o in mine)
                if rest <= 0:
                    continue
                key = (t, side)
                P["seen"].add(key)
                if marks[t] is None:
                    continue                    # unmarked: its state stands
                d = rest if side == "bid" else -rest
                w1 = risk_event_worst(
                    [(x, pos[x] + (d if x == t else 0.0), marks[x]) for x in tickers],
                    struct, me, n_ev)
                P["sides"] += 1
                adds = w1 < w0 - 0.01
                u0e, u1e = -w0 / lim_e, -w1 / lim_e
                u0g = u1g = None
                with_dir = None
                if adds and gs is not None:
                    with_dir = (side == "bid" and gdir == "long") or \
                        (side == "ask" and gdir == "short")
                    if not directional or with_dir:
                        u0g = -gs["w0"] / lim_g
                        u1g = -(gs["w0"] + w1 - w0) / lim_g
                state, by = "ok", ""
                if adds:
                    u1 = max(u1e, u1g if u1g is not None else 0.0)
                    u0 = max(u0e, u0g if u0g is not None else 0.0)
                    if u1 > 1.0:
                        state = "block"
                        by = "group" if u1g is not None and u1g >= u1e else "event"
                    elif u0 >= RISK_SKEW_FROM:
                        state = "skew"
                        by = "group" if u0g is not None and u0g >= u0e else "event"
                side_day = 0.5 * self._risk_market_day(t)
                prev = self._risk_side.get(key)
                prev_state = prev["state"] if prev else "ok"
                if state != "ok":
                    self._risk_side[key] = {
                        "state": state, "event": ev, "group": g,
                        "since": prev["since"] if prev and prev_state == state else now_ts,
                        "side_day": side_day}
                elif prev is not None:
                    del self._risk_side[key]
                if state == prev_state:
                    continue
                self._risk["transitions"] += 1
                pxs = [o["px"] for o in mine]
                rec = {"ev": "state", "ts": round(now_ts, 3), "ticker": t,
                       "event": ev, "group": g, "side": side, "state": state,
                       "prev": prev_state, "by": by,
                       "px": max(pxs) if side == "bid" else min(pxs),
                       "rest": rest, "pos": pos[t], "mark": marks[t],
                       "w0": round(w0, 2), "w1": round(w1, 2),
                       "lim_e": round(lim_e, 2), "u0e": round(u0e, 3),
                       "u1e": round(u1e, 3), "side_day": round(side_day, 3),
                       "ev_day": round(day, 3)}
                if gs is not None:
                    rec.update(g_w0=round(gs["w0"], 2), lim_g=round(lim_g, 2),
                               g_day=round(gs["day"], 3), gdir=gdir,
                               directional=directional, with_dir=with_dir,
                               u0g=None if u0g is None else round(u0g, 3),
                               u1g=None if u1g is None else round(u1g, 3))
                if state == "block":
                    # the share of the side that would still fit under the
                    # limit(s) it breaks -- for scoring a cap in place of a
                    # block
                    inc = w0 - w1
                    fit = (lim_e + w0) / inc if u1e > 1.0 else 1.0
                    if u1g is not None and u1g > 1.0:
                        fit = min(fit, (lim_g + gs["w0"]) / inc)
                    rec["fit"] = round(min(1.0, max(0.0, fit)), 3)
                if prev is not None:
                    rec["secs"] = round(now_ts - prev["since"], 1)
                self._sink("risk_dry", rec)

    def _risk_end_pass(self, now_ts: float) -> None:
        """Close the pass: the priming pass logs the run's `start` line (and
        the first judged pass follows at once); afterwards a side that has
        no orders left ends its state (`none`), the counters update, and a
        `pass` summary goes out every RISK_SUMMARY_SECS."""
        P = self._risk_pass
        self._risk_pass = None
        if P is None:
            return
        st = self._risk
        if not self._risk_primed:
            self._risk_primed = True
            self._risk_last_pass = 0.0
            self._sink("risk_dry", {
                "ev": "start", "ts": round(now_ts, 3), "run_id": RUN_ID,
                "event_floor": RISK_EVENT_FLOOR, "event_days": RISK_EVENT_DAYS,
                "group_floor": RISK_GROUP_FLOOR, "group_days": RISK_GROUP_DAYS,
                "skew_from": RISK_SKEW_FROM, "exempt": list(RISK_EXEMPT),
                "tau_h": RISK_REWARD_TAU_SECS / 3600.0,
                "directional": list(RISK_DIRECTIONAL_GROUPS),
                "events": len(P["events"]), "prime_s": round(P["secs"], 2)})
            return
        for key in [k for k in self._risk_side if k not in P["seen"]]:
            prev = self._risk_side.pop(key)
            st["transitions"] += 1
            self._sink("risk_dry", {
                "ev": "state", "ts": round(now_ts, 3), "ticker": key[0],
                "event": prev["event"], "group": prev["group"], "side": key[1],
                "state": "none", "prev": prev["state"],
                "secs": round(now_ts - prev["since"], 1)})
        blk = [v for v in self._risk_side.values() if v["state"] == "block"]
        skw = [v for v in self._risk_side.values() if v["state"] == "skew"]
        live_ev = [r for r in self._risk_ev.values() if not r["exempt"]]
        st.update(passes=st["passes"] + 1, events=P["evaluated"],
                  sides=P["sides"], unmarked=P["unmarked"],
                  block_now=len(blk), skew_now=len(skw),
                  block_day=round(sum(v["side_day"] for v in blk), 2),
                  skew_day=round(sum(v["side_day"] for v in skw), 2),
                  worst_total=round(sum(r["w0"] for r in live_ev), 2),
                  pass_s=round(P["secs"], 2))
        if now_ts - self._risk_last_summary < RISK_SUMMARY_SECS:
            return
        self._risk_last_summary = now_ts
        groups = {}
        for g, s in sorted(P["gsum"].items()):
            lim = max(RISK_GROUP_FLOOR, RISK_GROUP_DAYS * s["day"])
            groups[g] = {"worst": round(s["w0"], 2), "limit": round(lim, 2),
                         "day": round(s["day"], 3), "long": round(s["long"], 2),
                         "short": round(s["short"], 2), "events": s["events"]}
        over = []
        for ev, r in self._risk_ev.items():
            if r["exempt"]:
                continue
            lim = max(RISK_EVENT_FLOOR, RISK_EVENT_DAYS * r["day"])
            if -r["w0"] >= RISK_SKEW_FROM * lim:
                over.append([round(-r["w0"] / lim, 3), ev, round(r["w0"], 2),
                             round(lim, 2)])
        over.sort(reverse=True)
        self._sink("risk_dry", {
            "ev": "pass", "ts": round(now_ts, 3), "secs": round(P["secs"], 2),
            "events": P["evaluated"], "sides": P["sides"],
            "unmarked": P["unmarked"], "block": len(blk), "skew": len(skw),
            "block_day": st["block_day"], "skew_day": st["skew_day"],
            "worst_total": st["worst_total"],
            "exempt_worst": round(sum(r["w0"] for r in self._risk_ev.values()
                                      if r["exempt"]), 2),
            "groups": groups, "events_over_skew": len(over),
            "top_events": over[:15]})
        msg = (f"{len(blk)} side(s) would block (~${st['block_day']:.2f}/day), "
               f"{len(skw)} would skew (~${st['skew_day']:.2f}/day)")
        if msg != self._risk_last_msg:
            self._risk_last_msg = msg
            log(f"{self.tag} risk limits (dry): {msg}; worst case "
                f"${-st['worst_total']:,.0f} over {len(live_ev)} events, "
                f"{len(over)} event(s) past {RISK_SKEW_FROM:.0%} of their limit")

    def _idle(self, secs: float, stopping: dict) -> bool:
        """Sleep up to `secs` between cycles. With the WebSocket feed running
        it waits on the feed instead and handles its events as they arrive;
        it returns True early only in fast mode (a stale rung was cancelled
        or one of our orders filled), never sooner than WS_MIN_CYCLE_GAP_SECS
        after the last cycle started. In shadow it always runs to `secs`."""
        ws = self._ws
        if ws is None or secs <= 0:
            if secs > 0:
                time.sleep(secs)
            return False
        end = time.time() + secs
        next_ok = 0.0
        while not stopping.get("flag"):
            remain = end - time.time()
            if remain <= 0:
                return False
            ws.event_flag.wait(min(remain, 0.5))
            now_ts = time.time()
            # at most WS_IDLE_BATCHES_PER_SEC looks a second: a busy feed
            # (~150 book changes/s) would otherwise wake this loop on every
            # message; the changes accumulate in the feed until the next look
            if now_ts < next_ok:
                time.sleep(max(0.0, min(next_ok, end) - now_ts))
                now_ts = time.time()
            next_ok = now_ts + 1.0 / WS_IDLE_BATCHES_PER_SEC
            try:
                self._ws_process_events(now_ts)
            except Exception as e:
                log(f"{self.tag} ! WS event handling failed: {e}")
            if self._ws_wake and \
                    now_ts - self._last_cycle_start >= WS_MIN_CYCLE_GAP_SECS:
                self._ws_wake = False
                self._ws_fast["wakes"] += 1
                return True
            # back of the line (2026-10-17, Jack: "send it between cycles"):
            # its line reads and moves run here, a slice at a time, so the
            # feed's events keep their turn between slices
            plan = self._bol_plan
            if plan is not None and not plan["done"]:
                left = end - time.time()
                if left > 0.05:
                    self._back_of_line_step(time.time(), min(0.3, left))
            # the dollar limits' dry check (2026-10-17, RISK_LIMITS): a slice
            # of its pass, after the feed's events and the line moves
            elif RISK_LIMITS != "off":
                left = end - time.time()
                if left > 0.05:
                    self._risk_step(time.time(), min(RISK_SLICE_SECS, left))
        return False

    def _get_resting_orders_global(self) -> List[dict]:
        """All resting orders on the account with our client prefix, paginated.
        (Global read: this bot spans many events; other bots' prefixes differ.)
        Side effect: counts FOREIGN resting orders per ticker (manual orders,
        other bots) — a foreign order on a managed market triggers the
        manual-standoff yield."""
        orders: List[dict] = []
        foreign: Dict[str, int] = {}
        order_ticker: Dict[str, str] = {}
        cursor = None
        for _page in range(40):
            resp = self.client.get_orders(status="resting", limit=200, cursor=cursor)
            batch = resp.get("orders") or []
            for o in batch:
                if o.get("status") != "resting":
                    continue
                if str(o.get("client_order_id", "")).startswith(CLIENT_ORDER_PREFIX + "-"):
                    orders.append(o)
                    t = o.get("ticker", "")
                    order_ticker[o.get("order_id", "")] = t
                    self._note_shard(t, o.get("exchange_index"))
                else:
                    t = o.get("ticker", "")
                    foreign[t] = foreign.get(t, 0) + 1
            cursor = resp.get("cursor")
            if not cursor or not batch:
                break
        self._foreign_resting = foreign
        self._order_ticker = order_ticker
        return orders

    def _note_shard(self, ticker: str, exchange_index) -> None:
        """Remember the Kalshi exchange shard a market lives on (the
        exchange_index on market and order reads); cancel_order routes by
        it. Shards are per event and Kalshi does not migrate live markets."""
        if not ticker:
            return
        try:
            self._ticker_shard[ticker] = int(exchange_index)
        except (TypeError, ValueError):
            pass

    def _merge_ledger(self, exchange_orders: List[dict], now_ts: float) -> List[dict]:
        """Union of the exchange view and the local ledger (Kalshi portfolio
        reads are eventually consistent — see crypto_touch_mm for the whole
        rationale). Unconfirmed young entries count as resting; older ones are
        verified once via get_order; confirmed-then-absent entries are done."""
        merged = list(exchange_orders)
        seen_ids = {o.get("order_id") for o in exchange_orders}
        grace = 2 * POLL_SECS + 15
        for oid, entry in list(self.state.ledger.items()):
            if oid in seen_ids:
                entry["_confirmed"] = True
                continue
            if entry["_confirmed"] or now_ts >= entry["_placed_at"] + ORDER_TTL_SECS:
                self.state.ledger.pop(oid, None)
                self.state.order_ages.pop(oid, None)
                continue
            if now_ts - entry["_placed_at"] <= grace:
                merged.append(entry)
                continue
            try:
                order = (self.client.get_order(oid) or {}).get("order") or {}
                if order.get("status") == "resting":
                    entry["_confirmed"] = True
                    merged.append(entry)
                else:
                    self.state.ledger.pop(oid, None)
                    self.state.order_ages.pop(oid, None)
            except HttpError as e:
                if e.status == 404:
                    self.state.ledger.pop(oid, None)
                    self.state.order_ages.pop(oid, None)
                else:
                    merged.append(entry)
            except Exception:
                merged.append(entry)
        return merged

    def fetch_resting_orders(self, now_ts: float) -> List[dict]:
        if not self.live:
            expired = [oid for oid, o in self.state.sim_orders.items()
                       if o.get("expire_at", 0) <= now_ts]
            for oid in expired:
                self.state.sim_orders.pop(oid, None)
                self.state.order_ages.pop(oid, None)
            return list(self.state.sim_orders.values())
        return self._merge_ledger(self._get_resting_orders_global(), now_ts)

    def cancel_all_bot_orders(self) -> int:
        """Cancel every resting imm- order on the account (any run)."""
        if not self.live:
            n = len(self.state.sim_orders)
            self.state.sim_orders.clear()
            self.state.order_ages.clear()
            if n:
                log(f"{self.tag} [DRY] cancelled all {n} simulated orders")
            return n
        n = 0
        try:
            orders = self._merge_ledger(self._get_resting_orders_global(), time.time())
            for o in orders:
                if self.cancel_order(o["order_id"], reason="cancel_all"):
                    n += 1
        except Exception as e:
            log(f"{self.tag} ! cancel-all sweep failed: {e}")
        return n

    def rain_directional_take(self, t: str, ext_bid, ext_ask, fair_c: float,
                              bid_bad: bool, ask_bad: bool, now_ts: float) -> None:
        """Take the NWS side of a divergent rain book (see RAIN_DIR_ENABLE
        block). ask_bad: touch ask under fair-TOL -> buy YES at the ask.
        bid_bad: touch bid over fair+TOL -> buy NO at (100 - bid). Taker
        (post_only=False), once per market, capped per 24h, ledgered."""
        if not (RAIN_DIR_ENABLE and RAIN_DIR_SIZE > 0):
            return
        if t in self.state.rain_dir_done:
            return
        taken_24h = sum(1 for ts_ in self.state.rain_dir_done.values()
                        if now_ts - ts_ < 86400) * RAIN_DIR_SIZE
        if taken_24h + RAIN_DIR_SIZE > RAIN_DIR_MAX_PER_DAY:
            log(f"{self.tag} rain-DIR skip {t}: 24h cap "
                f"({taken_24h}/{RAIN_DIR_MAX_PER_DAY} contracts)")
            return
        if ask_bad and ext_ask is not None:
            take_side, px, kwargs = "yes", int(ext_ask), dict(
                side="yes", action="buy", yes_price=int(ext_ask))
            edge = fair_c - ext_ask
        elif bid_bad and ext_bid is not None:
            no_px = 100 - int(ext_bid)
            take_side, px, kwargs = "no", no_px, dict(
                side="no", action="buy", no_price=no_px)
            edge = ext_bid - fair_c
        else:
            return
        expiration_ts = int(now_ts + 600)
        cutoff_ts = self.state.cutoff_ts.get(t)
        if cutoff_ts is not None:
            expiration_ts = min(expiration_ts, int(cutoff_ts))
            if expiration_ts <= now_ts + 1:
                return
        client_order_id = f"{CLIENT_ORDER_PREFIX}-{RUN_ID}-{uuid.uuid4().hex[:12]}"
        oid = f"dry-{uuid.uuid4().hex[:8]}"
        if self.live:
            try:
                resp = self.client.create_order(
                    ticker=t, client_order_id=client_order_id,
                    count=RAIN_DIR_SIZE, type="limit", post_only=False,
                    expiration_ts=expiration_ts,
                    self_trade_prevention_type=STP_TYPE, **kwargs)
                oid = ((resp.get("order") or {}).get("order_id")
                       or resp.get("order_id", "?"))
                self.state.our_order_ids[oid] = now_ts
            except Exception as e:
                log(f"{self.tag} ! rain-DIR order failed {t}: {e}")
                return
        self.state.rain_dir_done[t] = now_ts
        try:
            new = not os.path.exists(RAIN_DIR_LEDGER)
            with open(RAIN_DIR_LEDGER, "a", encoding="utf-8") as f:
                if new:
                    f.write(RAIN_DIR_LEDGER_HEADER)
                f.write(f"{datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')},"
                        f"{t},{take_side},{RAIN_DIR_SIZE},{px},{fair_c:.0f},"
                        f"{ext_bid if ext_bid is not None else ''},"
                        f"{ext_ask if ext_ask is not None else ''},"
                        f"{edge:.0f},{oid}\n")
        except OSError as e:
            log(f"{self.tag} ! rain-DIR ledger write failed: {e}")
        log(f"{self.tag} rain-DIR TAKE {t}: {take_side.upper()} {RAIN_DIR_SIZE}x @ "
            f"{px}c vs fair {fair_c:.0f}c (edge {edge:+.0f}c)"
            f"{'' if self.live else ' [DRY]'}")

    def cancel_market_orders(self, ticker: str, resting: List[dict]) -> int:
        n = 0
        for o in resting:
            if o.get("ticker") == ticker and self.cancel_order(
                    o.get("order_id", ""), reason="market_cancel"):
                n += 1
        return n

    # ---- far-strike quake asks (QUAKE_ASK_STRIKES, 2026-10-11) -------------

    def _quake_pull_asks(self, ticker: str, resting: List[dict],
                         floor_c: Optional[int], why: str) -> int:
        """The cycle's own pull: cancel our resting asks on quake market
        `ticker` that the ask verdict no longer allows -- every ask when
        floor_c is None, else those priced under floor_c. Pulled orders leave
        `resting` (in place) so the diff neither keeps nor re-cancels them."""
        pulled: Set[str] = set()
        for o in resting:
            if o.get("ticker") != ticker:
                continue
            parsed = order_yes_book_cents(o)
            if parsed is None or parsed[0] != "ask":
                continue
            ox = order_yes_exact_cents(o)
            px = float(parsed[1]) if ox is None else ox
            if floor_c is not None and px >= floor_c - 1e-9:
                continue
            oid = str(o.get("order_id") or "")
            if oid and self.cancel_order(
                    oid, reason="quake_ask_off" if floor_c is None
                    else "quake_ask_floor"):
                self.state.cancelled_today += 1
                pulled.add(oid)
        if pulled:
            resting[:] = [o for o in resting if o.get("order_id") not in pulled]
            log(f"{self.tag} quake ask pull {ticker}: "
                + (why if floor_c is None else f"priced under the {floor_c}c floor")
                + f" -- cancelled {len(pulled)}")
        return len(pulled)

    def _quake_ask_note(self, ticker: str, floor_c: Optional[int],
                        why: str) -> None:
        """One log line each time a far strike's ask turns on or off."""
        state = "off" if floor_c is None else "on"
        if self._quake_ask_state.get(ticker) != state:
            log(f"{self.tag} quake ask {state} {ticker}: "
                + (why if floor_c is None else f"floor {floor_c}c, "
                   f"up to {QUAKE_ASK_MAX_CONTRACTS} contracts"))
        self._quake_ask_state[ticker] = state

    def _quake_ask_brake_note(self, ticker: str, now_ts: float,
                              src: str) -> None:
        """One of our asks on a quake market filled (src: 'WS fill' / 'fill'):
        brake every ask in its event (quake_ask_brake); the refresher's next
        sweep pulls the rest. Never raises."""
        try:
            ev = self._event_of(ticker)
            if quake_ask_brake(ev, now_ts):
                log(f"{self.tag} quake ask brake {ev}: an ask on {ticker} filled "
                    f"({src}) -- no asks in the event for "
                    f"{QUAKE_ASK_FILL_BRAKE_MIN:g} min")
        except Exception as e:
            log(f"{self.tag} ! quake ask brake failed: {e}")

    def _yt2_fill_pause_note(self, ticker: str, fill_ts: float,
                             src: str) -> None:
        """A maker fill of ours on a YouTube #2 market (src: 'WS fill' /
        'fill'): its whole event stays aside until YT2_FILL_PAUSE_MIN after
        the fill; a later fill extends it. The quote loop pulls the event's
        orders on its next cycle (~20 s; the follow-up fills this stops came
        1-60 min later). A fill older than the pause (a startup reconcile)
        starts nothing. Never raises."""
        try:
            if YT2_FILL_PAUSE_MIN <= 0 or not yt2_series(series_of(ticker)):
                return
            now_ts = time.time()
            until = float(fill_ts or now_ts) + YT2_FILL_PAUSE_MIN * 60
            pauses = self.state.yt2_fill_pause_until  # (the WS and trading threads)
            ev = self._event_of(ticker)
            prev = pauses.get(ev, 0.0)
            if until <= now_ts or until <= prev:
                return
            for e_old in [e for e, u in list(pauses.items()) if u < now_ts]:
                pauses.pop(e_old, None)
            pauses[ev] = until
            log(f"{self.tag} yt2 fill pause {ev}: our fill on {ticker} ({src}) "
                f"-> the event stays aside until "
                f"{datetime.fromtimestamp(until, timezone.utc):%H:%M:%SZ}"
                + (" (extended)" if prev > now_ts else ""))
        except Exception as e:
            log(f"{self.tag} ! yt2 fill pause failed: {e}")

    def _astest_fill_pause_note(self, ticker: str, fill_ts: float,
                                src: str, count: float = 0.0) -> None:
        """A maker fill of ours on an AS test family (astest_family: gas,
        Billboard, VoteHub; src: 'WS fill' / 'fill'): its whole event stays
        aside until ASTEST_<F>_FILL_PAUSE_MIN after the fill -- a print that
        moves walks through the strikes -- and a later fill extends it. The
        yt2 pause's scheme. A fill older than the pause (a startup reconcile)
        starts nothing. `count` feeds the family's burst breaker
        (ASTEST_<F>_BURST_CONTRACTS, one tally per family): only the cycle's
        fill read passes it, so a fill the WS feed saw first is not counted
        twice. Never raises."""
        try:
            fam = astest_family(series_of(ticker))
            if fam is None:
                return
            pause_min = astest_knob(fam, "FILL_PAUSE_MIN")
            now_ts = time.time()
            fts = float(fill_ts or now_ts)
            pauses = self.state.astest_fill_pause_until  # (the WS and trading threads)
            for e_old in [e for e, u in list(pauses.items()) if u < now_ts]:
                pauses.pop(e_old, None)
            until = fts + pause_min * 60
            ev = self._event_of(ticker)
            prev = pauses.get(ev, 0.0)
            if pause_min > 0 and until > now_ts and until > prev:
                pauses[ev] = until
                log(f"{self.tag} astest fill pause {ev}: our fill on {ticker} ({src}) "
                    f"-> the event stays aside until "
                    f"{datetime.fromtimestamp(until, timezone.utc):%H:%M:%SZ}"
                    + (" (extended)" if prev > now_ts else ""))
            bar = astest_knob(fam, "BURST_CONTRACTS")
            if count <= 0 or bar <= 0:
                return
            bursts = getattr(self, "_astest_bursts", None)
            if bursts is None:
                bursts = self._astest_bursts = {}
            burst = bursts.setdefault(fam, [])
            burst.append((fts, float(count)))
            window_min = astest_knob(fam, "BURST_WINDOW_MIN")
            since = now_ts - window_min * 60
            burst[:] = [(t_, n_) for t_, n_ in burst if t_ >= since]
            total = sum(n_ for _t, n_ in burst)
            f_until = now_ts + astest_knob(fam, "BURST_PAUSE_MIN") * 60
            fam_key = astest_knob(fam, "FAMILY_KEY")
            if total >= bar and pauses.get(fam_key, 0.0) <= now_ts:
                pauses[fam_key] = f_until
                burst.clear()
                what = "gas" if fam == "GAS" else astest_knob(fam, "LABEL")
                self.alerter.alert(
                    "astest_burst",
                    f"opportunistic AS test: our {what} fills reached {total:g} "
                    f"contracts in {window_min:g} min (bar "
                    f"{bar:g}, last {ticker}) -- every {what} "
                    f"event stands aside until "
                    f"{datetime.fromtimestamp(f_until, ET):%H:%M} ET; positions ride",
                    key="astest_burst" if fam == "GAS" else f"astest_burst:{fam}")
        except Exception as e:
            log(f"{self.tag} ! astest fill pause failed: {e}")

    def _quake_resting_asks(self) -> List[Tuple[str, str, float]]:
        """[(ticker, order_id, yes price)] for every resting ask of ours on a
        quake market: the ledger (every order this process placed or adopted;
        the dry run's sim book instead) plus the cycle's resting view (built
        with the WS feed), less the ids the refresher has already pulled.
        Read off the trading thread (snapshots only)."""
        out: Dict[str, Tuple[str, float]] = {}
        for t, lst in list(self._resting_view.items()):
            if not quake_gated(series_of(t)):
                continue
            for o in list(lst):
                oid = str(o.get("order_id") or "")
                if oid and o.get("side") == "ask" and float(o.get("rem") or 0.0) > 0:
                    out[oid] = (t, float(o.get("px") or 0.0))
        book = self.state.ledger if self.live else self.state.sim_orders
        for oid, led in list(book.items()):
            t = str(led.get("ticker") or "")
            if not oid or oid in out or not quake_gated(series_of(t)) \
                    or led.get("book_side") != "ask" \
                    or float(led.get("remaining_count") or 0.0) <= 0:
                continue
            px = led.get("yes_price_exact")
            out[oid] = (t, float(px) if px is not None
                        else float(led.get("yes_price") or 0.0))
        now_ts = time.time()
        return [(t, oid, px) for oid, (t, px) in out.items()
                if self._quake_ask_pulled.get(oid, 0.0) <= now_ts]

    def _quake_ask_sweep(self, now_ts: float) -> int:
        """THE PULL (QUAKE_ASK_STRIKES): cancel each resting quake ask of ours
        whose verdict is off (quake_ask_floor), straight from the quake
        refresher thread -- every second, the GFZ / USGS polls being the
        trigger -- and from the EMSC reader the moment a big enough quake is
        pushed, so nothing waits for the trading thread's cycle (which may be
        minutes long, or wedged). A pulled id is skipped for 15 min, a failed
        cancel retried after 5 s. Leaves the cycle heartbeat as it found it:
        these cancels must never hide a wedged trading thread from the hang
        watchdog. Returns the number cancelled."""
        with self._quake_ask_lock:
            return self._quake_ask_sweep_locked(now_ts)

    def _quake_emsc_note(self, watch: Any, text: str, now_ts: float) -> Optional[dict]:
        """One EMSC realtime message into the watch (usgs_quake_fair
        .parse_emsc / update_emsc). A kept quake big enough to pull a far-strike
        ask (the lowest ask strike - ASK_PULL_BELOW_MAG) is logged and the asks
        are re-checked at once rather than on the refresher's next second.
        Returns the parsed event, or None when the message is not one."""
        import usgs_quake_fair as uqf
        parsed = uqf.parse_emsc(text)
        if parsed is None:
            return None
        action, ev = parsed
        kept = watch.update_emsc(ev, now_ts)
        if kept and QUAKE_ASK_STRIKES and \
                ev["mag"] >= min(QUAKE_ASK_STRIKES) - uqf.ASK_PULL_BELOW_MAG - 1e-9:
            log(f"{self.tag} quake EMSC {action or 'event'} M{ev['mag']:g} "
                f"{ev['id']} ({ev['place']}) -- far-strike asks re-checked")
            self._quake_ask_sweep(time.time())
        return ev

    def _quake_emsc_loop(self, watch: Any) -> None:
        """The EMSC realtime reader (QUAKE_EMSC_ENABLE), on its own daemon
        thread: one websocket (kalshi_ws.WSConnection, stdlib only), a ping
        every QUAKE_EMSC_PING_SECS, redialled with capped backoff on any
        failure or after QUAKE_EMSC_DEAD_SECS without a frame (not even a
        pong). Each message goes through _quake_emsc_note. Never raises; a
        failure is logged once until the feed is back."""
        import socket as _socket
        import kalshi_ws
        import usgs_quake_fair as uqf
        backoff, last_err = 5.0, None
        while True:
            conn = kalshi_ws.WSConnection(uqf.EMSC_WS_URL, timeout=5.0)
            try:
                conn.connect()
                watch.emsc_alive(time.time())
                log(f"{self.tag} quake: EMSC realtime feed "
                    + ("back" if last_err else "connected"))
                backoff, last_err, last_ping = 5.0, None, 0.0
                while True:
                    mono = time.monotonic()
                    if mono - last_ping >= QUAKE_EMSC_PING_SECS:
                        conn.ping(b"imm")
                        last_ping = mono
                    try:
                        op, payload = conn.recv_message()
                    except _socket.timeout:
                        op = payload = None
                    # a frame of any kind (pongs included) is a live feed
                    watch.emsc_alive(time.time() - (time.monotonic() - conn.last_rx))
                    if time.monotonic() - conn.last_rx > QUAKE_EMSC_DEAD_SECS:
                        raise kalshi_ws.WSError(
                            f"no frame for {QUAKE_EMSC_DEAD_SECS:g}s (not even a pong)")
                    if op == kalshi_ws.OP_TEXT and payload:
                        try:
                            self._quake_emsc_note(
                                watch, payload.decode("utf-8", "replace"), time.time())
                        except Exception as e:
                            log(f"{self.tag} ! quake EMSC message skipped: "
                                f"{type(e).__name__}: {str(e)[:120]}")
            except Exception as e:
                err = f"{type(e).__name__}: {str(e)[:120]}"
                if err != last_err:
                    log(f"{self.tag} ! quake EMSC feed: {err}; redialling "
                        f"(asks still pulled on GFZ / USGS)")
                last_err = err
            finally:
                conn.close()
            time.sleep(backoff)
            backoff = min(backoff * 2.0, 120.0)

    def _quake_ask_sweep_locked(self, now_ts: float) -> int:
        """_quake_ask_sweep's body (the caller holds _quake_ask_lock)."""
        for oid in [o for o, until in self._quake_ask_pulled.items()
                    if until < now_ts - 60]:
            self._quake_ask_pulled.pop(oid, None)
        asks = self._quake_resting_asks()
        if not asks:
            return 0
        verdicts: Dict[str, Tuple[Optional[int], str]] = {}
        pulled: Dict[str, List[str]] = {}
        for t, oid, _px in asks:
            if t not in verdicts:
                verdicts[t] = quake_ask_floor(t, now_ts)
            if verdicts[t][0] is not None:
                continue
            hb = self._heartbeat
            try:
                ok = self.cancel_order(oid, reason="quake_ask_pull")
            finally:
                self._heartbeat = hb
            self._quake_ask_pulled[oid] = now_ts + (900.0 if ok else 5.0)
            if ok:
                self.state.cancelled_today += 1
                pulled.setdefault(t, []).append(oid)
                for o in list(self._resting_view.get(t, ())):
                    if o.get("order_id") == oid:
                        o["rem"] = 0.0
        for t, oids in pulled.items():
            log(f"{self.tag} quake ask PULL {t}: {verdicts[t][1]} -- cancelled "
                f"{len(oids)} (refresher, off the trading thread)")
        return sum(len(v) for v in pulled.values())

    def fetch_positions(self) -> Dict[str, float]:
        """ticker -> signed YES position, all unsettled markets on the account.
        Raises DataError-alike on failure so the cycle counts as errored."""
        positions: Dict[str, float] = {}
        cursor = None
        for _page in range(40):
            resp = self.client.get_positions(limit=200, cursor=cursor,
                                             settlement_status="unsettled")
            for p in (resp.get("market_positions") or resp.get("positions") or []):
                pos = p.get("position")
                if pos is not None and p.get("ticker") and abs(float(pos)) > 1e-9:
                    positions[p["ticker"]] = float(pos)
            cursor = resp.get("cursor")
            if not cursor:
                break
        # the NFL sniper's own book is not manual trading (SNIPE_BOOK_FILE)
        return net_out_snipe_book(positions, load_snipe_book(), self.pnl.pos)

    @staticmethod
    def _fill_ts(f: dict) -> int:
        ts = f.get("ts")
        if ts is not None:
            try:
                return int(ts)
            except (TypeError, ValueError):
                pass
        dt = parse_iso_utc(f.get("created_time", ""))
        return int(dt.timestamp()) if dt else 0

    def fetch_new_fills(self) -> List[dict]:
        """NEW fills of OUR OWN ORDERS since the last read (live only).
        Ownership is matched by order_id against the persisted our_order_ids
        set — NOT by ticker: the user trades some of the same mention markets
        by hand, and his fills must never enter this bot's P&L or loss halt.
        min_ts is inclusive and second-granular, so boundary fills reappear
        every read — fill_id dedupe stops them re-booking every 90s."""
        if not self.live:
            return []
        fills: List[dict] = []
        cursor = None
        newest_any = 0
        min_ts = (self.state.last_fill_ts - 2) if self.state.last_fill_ts \
            else int(time.time()) - 3600
        for _page in range(20):
            resp = self.client.get_fills(min_ts=min_ts, limit=200, cursor=cursor)
            batch = resp.get("fills") or []
            for f in batch:
                newest_any = max(newest_any, self._fill_ts(f))
                fid = f.get("fill_id") or f.get("trade_id") or ""
                if f.get("order_id") not in self.state.our_order_ids \
                        or fid in self.state.seen_fill_ids:
                    continue
                self.state.seen_fill_ids[fid] = self._fill_ts(f)
                fills.append(f)
            cursor = resp.get("cursor")
            if not cursor or not batch:
                break
        # Advance the cursor on ANY observed fill (the crypto fleet fills
        # constantly on this account) — anchoring it to our own fills only
        # would let the scan window grow past the pagination cap.
        if newest_any:
            self.state.last_fill_ts = max(self.state.last_fill_ts, newest_any)
        if len(self.state.seen_fill_ids) > 4000:   # bounded memory
            cut = sorted(self.state.seen_fill_ids.values())[len(self.state.seen_fill_ids) - 3000]
            self.state.seen_fill_ids = {k: v for k, v in self.state.seen_fill_ids.items()
                                        if v >= cut}
        return fills

    # ---- universe: programs -> candidate markets -> selection ---------------

    def fetch_programs(self) -> Dict[str, dict]:
        """market_ticker -> aggregated active liquidity program info."""
        now = datetime.now(timezone.utc)
        programs: List[dict] = []
        cursor = None
        for _page in range(20):
            params = {"limit": 1000, "status": "active"}
            if cursor:
                params["cursor"] = cursor
            resp = self.client.get("/incentive_programs", params=params)
            batch = resp.get("incentive_programs") or []
            programs.extend(batch)
            cursor = resp.get("next_cursor")
            if not cursor or not batch:
                break
        by_market: Dict[str, dict] = {}
        for p in programs:
            if p.get("incentive_type") != "liquidity" or p.get("paid_out"):
                continue
            start = parse_iso_utc(p.get("start_date", ""))
            end = parse_iso_utc(p.get("end_date", ""))
            if not start or not end or not (start <= now < end):
                continue
            days = max((end - start).total_seconds() / 86400.0, 1.0 / 24)
            dpd = (p.get("period_reward") or 0) / 10000.0 / days
            try:
                target = float(p.get("target_size_fp") or 0)
            except (TypeError, ValueError):
                target = 0.0
            df = (p.get("discount_factor_bps") or 5000) / 10000.0
            t = p.get("market_ticker") or ""
            cur = by_market.get(t)
            if cur is None:
                by_market[t] = {"dollars_per_day": dpd, "start": start,
                                "end": end, "target": target, "df": df}
            else:
                cur["dollars_per_day"] += dpd
                # the union window: overlapping programs on one market are
                # one paying stretch, and the period roll below keys off its
                # start, so a second program joining late must not look like
                # a new period
                cur["start"] = min(cur["start"], start)
                cur["end"] = max(cur["end"], end)
                cur["target"] = max(cur["target"], target)
        self.state.programs_count = len(by_market)
        return by_market

    @staticmethod
    def _blocked(ticker: str) -> bool:
        prefixes = SERIES_BLOCKLIST_PREFIXES
        if ticker.startswith(HIGHT_PREFIX) and hight_series(series_of(ticker)):
            # the IMM's own high-temperature family (2026-10-23): the "KXHIGH"
            # ownership block stands aside for its markets
            prefixes = tuple(p for p in prefixes if p != HIGHT_PREFIX)
        # the opportunistic AS test's states (2026-10-26): the state pattern
        # block stands aside for its members -- and for a gas-state daily
        # pick's event (2026-10-27, astest_pick_gas_ticker)
        astest = astest_gas_series(series_of(ticker)) or astest_pick_gas_ticker(ticker)
        if any(ticker.startswith(p) for p in prefixes) \
                or (series_pattern_blocked(series_of(ticker)) and not astest) \
                or event_pattern_blocked(ticker):
            # A wind-down event (BLOCKLIST_WIND_DOWN_EVENTS) is the one
            # exception to a prefix block. Accept the market ticker or the
            # event ticker itself: the freeze paths pass markets, the
            # family probe passes "<series>-X". A CPI pilot event is exempt
            # the same way while its window is open (cpi_pilot_active).
            if ticker not in BLOCKLIST_WIND_DOWN_EVENTS and \
                    ticker.rsplit("-", 1)[0] not in BLOCKLIST_WIND_DOWN_EVENTS \
                    and not cpi_pilot_active(ticker):
                return True
        # the YouTube #2 pilot, ended 2026-10-22 (YT2_ENDED)
        if YT2_ENDED and yt2_series(series_of(ticker)):
            return True
        # Strike-suffix block (MARKET_BLOCK_SUFFIXES, the -NQE leg): only a
        # MARKET ticker has a strike segment -- two dashes or more. Event
        # tickers and the "<series>-X" probe have one and fall through.
        if (MARKET_BLOCK_SUFFIXES and ticker.count("-") >= 2
                and ticker.rsplit("-", 1)[1] in MARKET_BLOCK_SUFFIXES):
            return True
        return series_of(ticker) in FREEZE_SERIES

    @classmethod
    def _allowed(cls, ticker: str) -> bool:
        """Blocklist always wins; then the exact-series allowlist (MENTION
        suffix + named crypto series), the finecon group, and the name-
        pattern families (prefixes; *CC/*ADS/*POS via ALLOW_FAMILY_SUFFIXES,
        source-verified -- family_series_allowed; the sports ladder /
        escalator regexes, ALLOW_SERIES_PATTERNS; the election family,
        election_series; the awards by Kalshi tag, awards_extra_series; the
        graduate families by Kalshi metadata, graduate_auto_series; the
        single-event mentions by Kalshi category, mention_auto_series; the AS
        test's Billboard and VoteHub families while live, astest_new_series;
        the road races by name, marathon_series) unless ALLOWLIST_ONLY is
        off."""
        if cls._blocked(ticker):
            return False
        if not ALLOWLIST_ONLY:
            return True
        series = ticker.split("-")[0]
        # FINECON_SERIES checked live (not just via the import-time
        # ALLOW_SERIES merge): task-appended Carbon Arc extensions must
        # be allowed the same refresh they join the group.
        return series in ALLOW_SERIES or series in EXTRA_ALLOW_SERIES or \
            series in FINECON_SERIES or \
            any(series.endswith(suf) for suf in ALLOW_SERIES_SUFFIXES) or \
            family_series_allowed(series) or \
            series_pattern_allowed(series) or \
            election_series(series) or \
            datacenter_series(series) or \
            rainstorm_span_allowed(ticker) or \
            rain_period_gated(ticker) or \
            (rain_monthly_auto(series) and not rain_period_ticker(ticker)) or \
            ytw_pilot_ticker(ticker) or \
            snow_monthly_series(series) or \
            bigsky_series(series) or \
            resort_snow_series(series) or \
            bway_fair_series(series) or \
            ercot_fair_series(series) or \
            lowt_series(series) or \
            hight_series(series) or \
            cpi_pilot_active(ticker) or \
            nfl_h2h_series(series) or \
            nfl_auto_entry(series) is not None or \
            league_auto_entry(series) is not None or \
            awards_extra_series(series) or \
            mlb_mvp_series(series) or \
            graduate_auto_series(series) or \
            mention_auto_series(series) or \
            (astest_new_series(series) and astest_pick_event_ok(ticker)) or \
            marathon_series(series) or \
            any(series.startswith(p) for p in ALLOW_SERIES_PREFIXES)

    def period_accrued(self, ticker: str) -> float:
        """The floor credit: THIS program period's estimated accrual
        (accrued_est - period_base) under FLOOR_ACCRUAL_PER_PERIOD, else the
        lifetime accrued_est. No baseline = first period seen = lifetime."""
        acc = self.state.accrued_est.get(ticker, 0.0)
        if not FLOOR_ACCRUAL_PER_PERIOD:
            return acc
        return max(0.0, acc - self.state.period_base.get(ticker, 0.0))

    def _floor_clocks(self, ticker: str, reaches_min: bool,
                      now_ts: float) -> Tuple[float, float]:
        """Advance the two floor clocks for one reading of `ticker` and return
        (sub_bar_secs, above_secs).

        above_secs: how long the projection has held at/above its bar in an
        unbroken run (state.admit_run; a run breaks on a sub-bar reading or a
        gap > ADMIT_RUN_MAX_GAP_SECS between readings). Fresh admission waits
        for it to reach ADMIT_SUSTAIN_SECS.

        sub_bar_secs: how long the hopeless clock has run (state.hopeless_since,
        started by the first sub-bar reading). Since 2026-09-27 an above-bar
        reading resets it only once its run has lasted ADMIT_SUSTAIN_SECS --
        a single spike no longer buys a fresh 30 minutes. A member is still
        never evicted on an above-bar reading (the exit needs reaches_min
        False), so the clock can only fire on the NEXT sub-bar reading.
        ADMIT_SUSTAIN_SECS <= 0 restores the single-reading reset."""
        run = self.state.admit_run.get(ticker)
        if reaches_min:
            if run is None or now_ts - run[1] > ADMIT_RUN_MAX_GAP_SECS \
                    or now_ts < run[1]:
                run = [now_ts, now_ts]
            else:
                run = [run[0], now_ts]
            self.state.admit_run[ticker] = run
            above_secs = now_ts - run[0]
            if ADMIT_SUSTAIN_SECS <= 0 or above_secs >= ADMIT_SUSTAIN_SECS:
                self.state.hopeless_since.pop(ticker, None)
        else:
            self.state.admit_run.pop(ticker, None)
            above_secs = 0.0
            self.state.hopeless_since.setdefault(ticker, now_ts)
        sub_bar_secs = now_ts - self.state.hopeless_since.get(ticker, now_ts)
        return sub_bar_secs, above_secs

    def _room_priority(self, meta: "MarketMeta") -> bool:
        """First call on the event's room in the quote loop: a market in
        near-cliff mode (verdict this refresh, or the sticky size mode)."""
        return NEAR_CLIFF_ROOM_PRIORITY and (
            meta.ticker in self._near_cliff_boost
            or bool(getattr(meta, "near_cliff", False)))

    def _near_cliff_size_mult(self, ticker: str) -> float:
        """NEAR_CLIFF_SIZE_MULT while `ticker` is in near-cliff mode (armed by
        the floor verdict, sticky until the banked accrual crosses the cliff
        or the market leaves the selection), else 1.0."""
        if NEAR_CLIFF_SIZE_MULT <= 0 or NEAR_CLIFF_SIZE_MULT == 1.0:
            return 1.0
        if ticker not in self._near_cliff_boost:
            return 1.0
        # a Carbon Arc market is 1x while its data lands (CA_LANDING_WINDOWS)
        if ca_landing_window(series_of(ticker), datetime.now(timezone.utc)):
            return 1.0
        return NEAR_CLIFF_SIZE_MULT

    def _yield_size_mult(self, ticker: str) -> float:
        """YIELD_SIZE_MULT while `ticker` is in the yield size mode, else 1.0
        (and 1.0 for a Carbon Arc market inside its data landing window)."""
        if not yield_size_active() or ticker not in self._yield_boost:
            return 1.0
        if ca_landing_window(series_of(ticker), datetime.now(timezone.utc)):
            return 1.0
        return YIELD_SIZE_MULT

    def _market_size_mult(self, ticker: str) -> float:
        """Every PER-MARKET ladder multiplier: near-cliff size mode x yield size
        mode. The one number each reader of the shape applies (estimator probe
        and floor projection, collateral reservation, quote loop, placement
        guard), so all of them see the ladder the quote loop rests."""
        return self._near_cliff_size_mult(ticker) * self._yield_size_mult(ticker)

    def _yield_size_verdict(self, meta: "MarketMeta", now_ts: float) -> None:
        """Arm / keep / drop the yield size mode on this refresh's estimate.
        Arms at YIELD_SIZE_MIN, holds down to YIELD_SIZE_EXIT_FRAC of it."""
        t = meta.ticker
        if not (yield_size_active(now_ts) and yield_size_eligible(meta.series)):
            self._yield_boost.pop(t, None)
        else:
            y = meta.yield_per_contract or 0.0
            if t in self._yield_boost:
                if y < YIELD_SIZE_MIN * YIELD_SIZE_EXIT_FRAC:
                    del self._yield_boost[t]
            elif y >= YIELD_SIZE_MIN:
                self._yield_boost[t] = now_ts
        meta.ys_size_mult = YIELD_SIZE_MULT if t in self._yield_boost else 1.0

    def _prune_yield_boost(self) -> None:
        """Drop the yield size mode for markets that left the selection (a
        challenger armed last refresh and not taken is re-judged when next
        estimated)."""
        for t in [t for t in self._yield_boost if t not in self.state.selected]:
            del self._yield_boost[t]

    def _prune_near_cliff_boost(self) -> None:
        """End near-cliff mode for markets that crossed the cliff (banked >=
        PAYOUT_FLOOR_DOLLARS this period) or left the selection. Runs at the
        top of the refresh's yield pass, before the estimator reads it."""
        for t in list(self._near_cliff_boost):
            banked = self.period_accrued(t)
            crossed = banked >= PAYOUT_FLOOR_DOLLARS
            if crossed or t not in self.state.selected:
                del self._near_cliff_boost[t]
                if crossed:
                    log(f"{self.tag} near-cliff: {t} crossed the cliff (banked "
                        f"${banked:.2f}); ladder back to normal size")

    def _paid_basis_delta(self, ticker: str, prev_acc: float,
                          new_acc: float) -> float:
        """PAID basis: nothing counts until this market's own accrual clears
        the $1 program floor, and the whole backlog lands in the cycle that
        crosses it. Per PERIOD since 2026-09-22 (FLOOR_ACCRUAL_PER_PERIOD): a
        market that crossed in a paid period starts the next one uncrossed
        (the roll discards its flag) and is measured from that period's
        baseline, so a re-listing that stays under the floor pays nothing."""
        base = (self.state.period_base.get(ticker, 0.0)
                if FLOOR_ACCRUAL_PER_PERIOD else 0.0)
        if ticker in self.state.paid_crossed:
            return new_acc - prev_acc
        if new_acc - base >= PAYOUT_FLOOR_DOLLARS:
            self.state.paid_crossed.add(ticker)
            return new_acc - base
        return 0.0

    def _roll_reward_periods(self, by_market: Dict[str, dict]) -> None:
        """Re-baseline per-period accrual when a market's program re-lists.

        These programs re-list weekly (measured 2026-09-11:
        KXAAAGASMINM-26SEP30 ran 09-02 -> 09-09 and again 09-09 -> 09-16),
        and accrued_est keeps running across the boundary, so without a
        baseline "what did this market earn this period" is unanswerable —
        the number the exchange's own rewards view shows.

        Called on the LIVE feed only: an empty/failed programs read must not
        look like every market's period ended."""
        rolled = 0
        for t, info in by_market.items():
            start = info.get("start")
            if start is None:
                continue
            key = start.isoformat()
            prev = self.state.period_start.get(t)
            if prev == key:
                continue
            if prev is None:
                # First sight. The running period may be half over already,
                # so there is no honest baseline — record the period and
                # leave the baseline absent until the next roll.
                self.state.period_base.pop(t, None)
            else:
                self.state.period_base[t] = self.state.accrued_est.get(t, 0.0)
                if FLOOR_ACCRUAL_PER_PERIOD:
                    # a new period starts uncrossed (see _paid_basis_delta)
                    self.state.paid_crossed.discard(t)
                rolled += 1
            self.state.period_start[t] = key
        if rolled:
            log(f"{self.tag} reward period rolled on {rolled} market(s); "
                f"per-period accrual re-baselined")
        # Heal a paid_crossed flag earned in an EARLIER period on a market
        # whose current period is still under the floor -- the state the
        # 2026-09-22 change inherited (KXRT re-listed at 16:49Z with the
        # flags of the paid period still set). Once per refresh, cheap.
        if FLOOR_ACCRUAL_PER_PERIOD:
            stale = [t for t in self.state.paid_crossed
                     if t in self.state.period_base
                     and self.period_accrued(t) < PAYOUT_FLOOR_DOLLARS]
            for t in stale:
                self.state.paid_crossed.discard(t)
            if stale:
                log(f"{self.tag} paid-basis: {len(stale)} market(s) uncrossed -- "
                    f"this period is under the ${PAYOUT_FLOOR_DOLLARS:.2f} floor")

    # ---- the universe refresh's network guard (2026-10-11, UNIVERSE_NET_GUARD)

    def _note_net_error(self, e: Optional[BaseException] = None) -> None:
        """A main-thread call that got no answer (is_network_error; None =
        the caller already knows): the universe refresh then defers for
        UNIVERSE_NET_TROUBLE_SECS. Never raises."""
        if e is None or is_network_error(e):
            self._net_err_at = time.time()

    @staticmethod
    def _refresh_abort_worthy(e: BaseException) -> bool:
        """Kalshi out of reach (a network error) or overloaded (a 429 / 5xx
        that outlasted the client's retries), not a bad request."""
        return is_network_error(e) or (
            isinstance(e, HttpError) and e.status in (429, 500, 502, 503, 504))

    def _universe_net_trouble(self, now_ts: float) -> str:
        """Why a due universe refresh should wait (UNIVERSE_NET_GUARD), or ''."""
        if now_ts < self.wake_grace_until:
            return (f"waking from a sleep (grace {self.wake_grace_until - now_ts:.0f}s "
                    f"left)")
        if self._net_err_at and now_ts - self._net_err_at < UNIVERSE_NET_TROUBLE_SECS:
            return f"a network error {now_ts - self._net_err_at:.0f}s ago"
        ws = self._ws
        if ws is not None and WS_MODE != "off":
            try:
                if not ws.healthy():
                    return "the WebSocket feed is down or silent"
            except Exception:
                pass
        return ""

    def _universe_skip(self, kind: str, why: str, now_ts: float) -> None:
        """Count a deferred / aborted refresh for latency.universe."""
        g = self._universe_guard
        g[kind] = g.get(kind, 0) + 1
        g["last"] = (f"{kind} {datetime.fromtimestamp(now_ts, timezone.utc):%m-%d %H:%M:%S}Z"
                     f": {why}")

    def _universe_abort(self, why: str, e: Optional[BaseException],
                        now_ts: float) -> None:
        """End this refresh with the current universe kept (UNIVERSE_NET_GUARD)."""
        if e is not None:
            self._note_net_error(e)
        self._universe_skip("aborted", why, now_ts)
        log(f"{self.tag} ! universe refresh aborted: {why}; the current universe "
            f"stays, and the next due refresh waits for the network")

    def refresh_universe(self, now_utc: datetime, positions: Dict[str, float]) -> None:
        now_ts = now_utc.timestamp()
        # Pick up call-time overrides and auto-enrolled series written since
        # the last refresh (daily task / hand edits) — cheap mtime checks,
        # no restart needed.
        load_file_event_overrides()
        load_extra_allow_series()
        load_astest_picks(now_utc)    # the AS test's daily picks (2026-10-27)
        load_finecon_extra_series()
        load_election_extra_series()
        load_nfl_auto_series()        # NFL auto families (2026-10-12)
        load_league_auto_series()     # NBA / WNBA / MLB auto families (2026-10-15)
        load_awards_extra_series()    # awards by Kalshi tag (2026-10-12)
        load_graduate_auto_series()   # graduate families by metadata (2026-10-12)
        load_mention_auto_series()    # single-event mentions by category (2026-10-13)
        load_election_dates_extra()   # hot-reloaded rows (2026-10-07)
        load_awards_dates_extra()
        load_family_verdicts()
        load_sat_gate()
        load_rain_fair()
        load_lowt_fair()              # low-temperature fair (2026-10-23)
        load_hight_fair()             # high-temperature fair (2026-10-23)
        _ca_n, _ca_moved = load_ca_fair()
        if _ca_moved:
            log(f"{self.tag} ca-fair reloaded: {_ca_n} series, "
                f"{_ca_moved} with a new read")
        _or_n, _or_moved = load_or_fair()
        if _or_moved:
            log(f"{self.tag} or-fair reloaded: {_or_n} events, "
                f"{_or_moved} with a new day")
        load_rain_monthly()
        load_snow_monthly()
        load_cpi_fair()
        load_rain_wknd()
        load_resort_snow()
        load_bway_fair()              # Broadway weekly attendance (2026-10-25)
        load_approve_fair()           # RCP approval (2026-10-26)
        load_tmention_fair()          # Trump mention base rates (2026-10-26)
        load_ercot_fair()             # ERCOT daily peak (2026-10-26)
        load_rt_fair()
        _sh_n, _sh_moved = load_share_fair()
        if _sh_moved:
            log(f"{self.tag} share-fair reloaded: {_sh_n} events, "
                f"{_sh_moved} with a new day")
        _vc_n, _vc_moved = load_vercel_fair()
        if _vc_moved:
            log(f"{self.tag} vercel-fair reloaded: {_vc_n} events, "
                f"{_vc_moved} with a new anchor")
        if YTW_ENABLE:
            load_ytw_fair()
        if YT1_ENABLE:
            load_yt1_fair()
        load_gb_fair()
        load_dc_fair()
        # Hourly program families (KXTEMP) activate at the TOP OF THE HOUR —
        # but LATE (absent ~hh:01, present ~hh:11): a single hour-crossed
        # refresh reliably fires before Kalshi publishes now that keep-alive
        # keeps cycles short, and the 600s gate then sat blind to ~hh:11
        # (observed 2026-07-21: AUSH-2023 dark 12 min). So inside the
        # activation window the gate drops to per-cycle; hour_crossed still
        # covers long gaps (sleep/wake) that skip the window entirely.
        # 2026-09-27: armed only while an hourly program is in the feed
        # (HOURLY_ACTIVATION_AUTO; _hourly_programs_live is set below).
        hour_crossed = int(now_ts // 3600) != int(self.state.universe_at // 3600)
        in_activation_window = (
            (now_ts % 3600) < HOURLY_ACTIVATION_WINDOW_SECS
            and (not HOURLY_ACTIVATION_AUTO or self._hourly_programs_live))
        if (now_ts - self.state.universe_at < UNIVERSE_REFRESH_SECS
                and not hour_crossed and not in_activation_window):
            return
        # NETWORK GUARD (UNIVERSE_NET_GUARD): a refresh that comes due in
        # network trouble waits, with the current universe kept, for up to
        # UNIVERSE_DEFER_MAX_SECS
        if UNIVERSE_NET_GUARD:
            why = self._universe_net_trouble(now_ts)
            since = self._universe_deferred_since
            if why:
                if since is None:
                    self._universe_deferred_since = since = now_ts
                    log(f"{self.tag} universe refresh deferred: {why}; the current "
                        f"universe stays (it runs anyway after "
                        f"{UNIVERSE_DEFER_MAX_SECS / 60:.0f} min)")
                if now_ts - since < UNIVERSE_DEFER_MAX_SECS:
                    self._universe_skip("deferred", why, now_ts)
                    return
                log(f"{self.tag} universe refresh: deferred {now_ts - since:.0f}s "
                    f"and still {why}; running it anyway")
            elif since is not None:
                log(f"{self.tag} universe refresh resumes after "
                    f"{now_ts - since:.0f}s deferred")
            self._universe_deferred_since = None
        _config_gaps_prune()          # gaps fixed since the last refresh
        try:
            by_market = self.fetch_programs()
        except Exception as e:
            # out of reach: keep the universe rather than a cycle error toward
            # the fail-safe (UNIVERSE_NET_GUARD)
            if not (UNIVERSE_NET_GUARD and self._refresh_abort_worthy(e)):
                raise
            self._universe_abort(f"the programs read got no answer ({e!r:.80})",
                                 e, now_ts)
            return
        # Live-program set for the no-rent freeze (empty on a failed/empty
        # read keeps the failsafe in the consumers: never mass-freeze on a
        # transient feed outage).
        if by_market:
            self.state.programmed = set(by_market)
            # CARBON ARC FAMILIES (2026-09-22, see ALLOW_FAMILY_SUFFIXES):
            # source-verify novel suffix matches BEFORE the candidates
            # filter below reads _allowed, so a sibling Kalshi listed since
            # the last refresh is admitted in this one. LIVE feed only.
            self._resolve_family_verdicts(by_market, now_ts)
            # FINECON FAMILY (2026-09-09): admit prefix-matching series the
            # moment Kalshi programs them, so a newly listed central bank is
            # covered the same refresh rather than waiting for a hand add.
            # Runs on the LIVE feed only — never on a failed/empty read.
            finecon_expand_family(by_market)
            # Per-period accrual baselines (Jack 2026-09-11). LIVE feed only,
            # same guard as the family expansion above.
            self._roll_reward_periods(by_market)
            # Period rain series the feed programs (2026-10-04): the rain
            # refresher prices them beside its own list, so a new city's
            # fair exists by the time its markets reach the gate.
            _rp = {series_of(t) for t in by_market if rain_period_gated(t)}
            if _rp - self._rain_period_series:
                log(f"{self.tag} rain-period series in the feed: "
                    f"{','.join(sorted(_rp))}")
            self._rain_period_series = _rp
            # ...and the monthly rain cities beyond the named list
            # (2026-10-26), the same way: the writer prices and auto-maps them
            _rmx = {series_of(t) for t in by_market
                    if rain_monthly_auto(series_of(t)) and not rain_period_ticker(t)}
            if _rmx - self._rain_monthly_extra:
                log(f"{self.tag} rain-monthly cities beyond the list in the feed: "
                    f"{','.join(sorted(_rmx))}")
            self._rain_monthly_extra = _rmx
            # ...and the snow monthlies (2026-10-04), the same way
            _sn = {series_of(t) for t in by_market if snow_monthly_series(series_of(t))}
            if _sn - self._snow_series:
                log(f"{self.tag} snow-monthly series in the feed: "
                    f"{','.join(sorted(_sn))}")
            self._snow_series = _sn
            # ...and every resort-named series (2026-10-22): the resort
            # writer maps a new one, and its "mapped" list enrolls it
            _rs = {series_of(t) for t in by_market if resort_snow_candidate(series_of(t))}
            if _rs - self._resort_series:
                log(f"{self.tag} resort-snow series in the feed: "
                    f"{','.join(sorted(_rs))}")
            self._resort_series = _rs
            # Daily-family classification from the live feed (Jack 2026-09-12):
            # feeds hour_size_mult / saturday_size_mult; persisted each refresh.
            _added, _dropped = refresh_daily_series(by_market, now_utc)
            if _added or _dropped:
                log(f"{self.tag} daily families (structural): "
                    f"+{','.join(_added) or '-'} -{','.join(_dropped) or '-'} "
                    f"-> {len(DAILY_SERIES_DYNAMIC)} classified + prefixes "
                    f"{','.join(DAILY_PREFIXES)}")

        def ticker_cutoff_passed(t: str) -> bool:
            # (imm_quote_gaps.py mirrors this pre-filter — keep in sync.)
            # Cheap pre-filter: drop only when the ticker-embedded event DAY is
            # fully over. Same-day markets stay in — the schedule resolver may
            # grant them an intraday cutoff (quote until kickoff - buffer),
            # and the fallback midnight rule still kills them in _screen.
            # close-anchored series (hourly weather) ignore the ticker date
            # entirely; the closing/cutoff screens govern them instead.
            ov = series_override(series_of(t))
            if ov and ov.cutoff_from_close_min is not None:
                return False
            # Series whose ticker date is unreliable must reach the resolver
            # instead of being pre-dropped on the string: earnings-mention (the
            # ticker date is a Kalshi estimate, often stale) and any event with
            # a manual override. The resolver + _screen enforce the real cutoff.
            if series_of(t).startswith(_EARNINGS_PREFIX) \
                    or t.rsplit("-", 1)[0] in EVENT_START_OVERRIDES:
                return False
            # Schedule-API series: a postponed game moves past the ticker
            # date while its programs keep paying — never pre-drop on the
            # string; the resolver's live schedule + _screen govern.
            if schedule_resolved_series(series_of(t)):
                return False
            # Elections: the verified ELECTION_DATES row is the date, not the
            # ticker string (2026-09-28) -- the cutoff decides in _screen.
            if election_series(series_of(t)):
                return False
            # Mention-family tickers may embed a LISTING date (26AUG13
            # ran to Sep 4 — the 2026-08-14 listing-date fix): the string
            # alone cannot tell, so they always hydrate and the real
            # cutoff (trade_cutoff_utc, which sees expected_expiration)
            # decides in _screen. Without this, the fixed cutoff never
            # runs: this pre-filter dropped KXTRUMPMENTION-26AUG13 at
            # td+24h before trade_cutoff_utc saw it — the same rule
            # duplicated one layer up (the 7/14 class, again).
            if any(series_of(t).endswith(suf) for suf in ALLOW_SERIES_SUFFIXES):
                return False
            td = parse_event_date(t)
            return td is not None and now_utc >= td + timedelta(hours=24)

        candidates = sorted(
            ((t, info) for t, info in by_market.items()
             if self._allowed(t) and info["dollars_per_day"] > 0
             and not ticker_cutoff_passed(t)),
            key=lambda kv: -kv[1]["dollars_per_day"])[:MAX_CANDIDATE_BOOKS]

        # New family members (prefix/suffix-admitted) clone their archetype
        # guards before anything downstream reads SERIES_OVERRIDES.
        for t, _info in candidates:
            ensure_family_override(series_of(t))

        # OPEN SCAN (2026-09-05, see the SCAN_* block): the complement of the
        # allowed universe, string-screened here (not blocked/allowed/an
        # excluded family, day-dated ticker) and pool-ranked so the bulk
        # read below stays bounded. Members ride along regardless of rank —
        # they are quote-to-completion and must reach the estimator. The
        # per-market screens that need the market object run after the read.
        scan_pre: List[Tuple[str, dict]] = []
        scan_skips: Dict[str, int] = {}
        scan_on = SCAN_TOP_N > 0 and ALLOWLIST_ONLY
        if scan_on:
            for _s in sorted(SCAN_GUARDED_SERIES):
                # a scan series that became allowlisted meanwhile (extra-allow
                # / finecon hot reload) hands its guard set back to the book:
                # the finecon guard if it joined that group (its loader saw
                # the scan entry and skipped), else the family inheritance
                if self._allowed(f"{_s}-X"):
                    release_scan_override(_s)
                    if _s in FINECON_SERIES and _s not in SERIES_OVERRIDES:
                        SERIES_OVERRIDES[_s] = SeriesOverride(
                            min_est_per_day=_env_float("IMM_FINECON_MIN_RATE", 0.0),
                            safe_join=True)
                    ensure_family_override(_s)
            for t, info in by_market.items():
                if info["dollars_per_day"] <= 0:
                    continue
                why = scan_universe_reason(t)
                if why is not None:
                    if why not in ("allowed", "blocked", "off", "allowlist_off"):
                        scan_skips[why] = scan_skips.get(why, 0) + 1
                    continue
                if ticker_cutoff_passed(t):
                    scan_skips["cutoff_passed"] = scan_skips.get("cutoff_passed", 0) + 1
                    continue
                # NOTE there is no string-level `undated` drop any more (Jack
                # 2026-09-07 "open the undated bucket"). Whether an undated
                # market has a stand-down guard depends on its OCCURRENCE,
                # which only exists on the market object, so it has to
                # hydrate to be judged; _scan_admission then rejects it as
                # `undated` unless a cutoff resolved or it is a Fiscal.ai
                # month event. The bulk cap below still bounds the reads, and
                # it is pool-ranked, so the biggest pools hydrate first.
                scan_pre.append((t, info))
            scan_pre.sort(key=lambda kv: -kv[1]["dollars_per_day"])
            if len(scan_pre) > SCAN_MAX_BULK:
                _keep = scan_pre[:SCAN_MAX_BULK] + [
                    kv for kv in scan_pre[SCAN_MAX_BULK:]
                    if kv[0] in self.state.scan_members]
                # HOURLY TAIL SWEEP (2026-09-13, see SCAN_SWEEP_HOURS): a
                # rotating slice of what the pool-ranked cap would otherwise
                # never hydrate, so the whole tail is screened once an hour
                _tail = [kv for kv in scan_pre[SCAN_MAX_BULK:]
                         if kv[0] not in self.state.scan_members]
                _idx, self._scan_tail_cursor = scan_tail_slice(
                    len(_tail), self._scan_tail_cursor, UNIVERSE_REFRESH_SECS)
                if _idx:
                    _keep += [_tail[i] for i in _idx]
                    scan_skips["tail_swept"] = len(_idx)
                scan_skips["bulk_cap"] = len(scan_pre) - len(_keep)
                scan_pre = _keep
        scan_pre_set = {t for t, _i in scan_pre}
        # HOURLY-WINDOW AUTO-ARM (2026-09-27, see HOURLY_ACTIVATION_AUTO): the
        # per-cycle refresh window is for hourly program families only, so
        # it follows whether one is in the feed. LIVE feed only: a failed or
        # empty read keeps the previous verdict.
        if by_market:
            _max_len = timedelta(hours=HOURLY_PROGRAM_MAX_HOURS)
            _hourly = sum(1 for _t, _i in candidates + scan_pre
                          if _i.get("start") is not None
                          and _i.get("end") is not None
                          and _i["end"] - _i["start"] <= _max_len)
            if (_hourly > 0) != self._hourly_programs_live:
                log(f"{self.tag} hourly activation window "
                    + (f"ARMED: {_hourly} candidate market(s) on programs of "
                       f"<= {HOURLY_PROGRAM_MAX_HOURS:g}h" if _hourly else
                       f"disarmed: no candidate program of <= "
                       f"{HOURLY_PROGRAM_MAX_HOURS:g}h in the feed")
                    + ("" if HOURLY_ACTIVATION_AUTO else
                       " (IMM_HOURLY_ACTIVATION_AUTO=0: window stays on)"))
            self._hourly_programs_live = _hourly > 0
        scan_metas: List[Tuple[MarketMeta, dict]] = []

        metas: List[MarketMeta] = []
        # tickers whose WHOLE book is outside the quoting band this refresh
        unquotable_now: Set[str] = set()
        tickers = [t for t, _info in candidates] + [t for t, _i in scan_pre]
        markets: Dict[str, dict] = {}
        _bulk_t0 = time.monotonic()
        for i in range(0, len(tickers), 50):
            chunk = tickers[i:i + 50]
            # NETWORK GUARD: a chunk that cannot be read must not drop its
            # members (their quotes would be cancelled as unselected), so a
            # Kalshi that is out of reach or slow ends the refresh instead
            if (UNIVERSE_NET_GUARD and UNIVERSE_BULK_BUDGET_SECS > 0
                    and time.monotonic() - _bulk_t0 > UNIVERSE_BULK_BUDGET_SECS):
                self._universe_abort(
                    f"bulk market reads ran over {UNIVERSE_BULK_BUDGET_SECS:.0f}s "
                    f"({i} of {len(tickers)} tickers read)", None, now_ts)
                self._note_net_error()
                return
            try:
                resp = self.client.get_markets(tickers=",".join(chunk), limit=len(chunk))
                for m in (resp.get("markets") or []):
                    markets[m.get("ticker", "")] = m
                    self._note_shard(m.get("ticker", ""), m.get("exchange_index"))
            except Exception as e:
                if UNIVERSE_NET_GUARD and self._refresh_abort_worthy(e):
                    self._universe_abort(
                        f"a bulk market read got no answer ({e!r:.80})", e, now_ts)
                    if not is_network_error(e):
                        self._note_net_error()      # Kalshi overloaded: wait too
                    return
                log(f"{self.tag} ! bulk market read failed ({e}); chunk skipped")

        # (imm_quote_gaps.py mirrors this meta construction — keep in sync.)
        for t, info in candidates + scan_pre:
            m = markets.get(t)
            if not m or m.get("status") not in ("active", "open"):
                continue
            event_ticker = m.get("event_ticker") or t.rsplit("-", 1)[0]
            series = t.split("-")[0]
            close_time = parse_iso_utc(m.get("close_time", ""))
            # Close-anchored series (hourly weather): the whole life is the
            # event, so the cutoff is close_time minus a toxicity buffer and
            # the event-start machinery below doesn't apply.
            ov_close = series_override(series)
            if ov_close and ov_close.cutoff_from_close_min is not None:
                cutoff = (close_time - timedelta(minutes=ov_close.cutoff_from_close_min)
                          if close_time is not None else None)
            else:
                # Real event start (statsapi / ESPN / fixed broadcast hour) beats
                # the midnight-ET ticker-date fallback: mention programs run
                # through game day, and the pre-broadcast daytime is safe rent.
                resolved = self.resolver.resolve(series, event_ticker)
                if resolved is not None:
                    ov = series_override(series)
                    if event_ticker in EVENT_START_OVERRIDES:
                        # earnings call / disclosure release: tight, precise
                        # buffer — all orders expire OVERRIDE_BUFFER_MIN before.
                        buffer_min = OVERRIDE_BUFFER_MIN
                    elif ov and ov.start_buffer_min is not None:
                        buffer_min = ov.start_buffer_min
                    else:
                        buffer_min = EVENT_START_BUFFER_MIN
                    cutoff = resolved - timedelta(minutes=buffer_min)
                else:
                    _occ = parse_iso_utc(m.get("occurrence_datetime", ""))
                    _exp = parse_iso_utc(m.get("expected_expiration_time", ""))
                    cutoff = trade_cutoff_utc(event_ticker, _occ, _exp)
                    # NO-CUTOFF MENTION CLASS (see MENTION_NO_CUTOFF_GATE):
                    # this branch IS "no derivable start" — the resolver had
                    # nothing and the cutoff above is the ticker-date
                    # fallback (or None). Put the series on the live-event
                    # depth gate before the estimator hook below reads it.
                    if (not mention_cutoff_is_clear(series, None, _occ, _exp)
                            and mark_no_cutoff_mention(series, now_ts)):
                        log(f"{self.tag} {series}: mention event "
                            f"{event_ticker} has no derivable start "
                            f"(cutoff {cutoff.isoformat() if cutoff else None}"
                            f" is the ticker-date fallback) — series on the "
                            f"live-event depth gate: pads OFF, whole event "
                            f"stands down on thin depth")
            # Series tighteners (early-stop + hard floor) — shared with the
            # orphan-restore path via apply_series_cutoff_adjustments.
            cutoff = apply_series_cutoff_adjustments(series, event_ticker, cutoff,
                                                     close_time=close_time,
                                                     market=m)
            if t in scan_pre_set:
                # open-scan month-named events (Fiscal.ai KPI class): out at
                # 00:00 ET on the first of the report month, unless Kalshi's
                # published report date lands after the paying window (then
                # the window is release-free — see scan_report_month_cutoff)
                cutoff = scan_report_month_cutoff(
                    event_ticker, cutoff,
                    report=scan_report_date(
                        parse_iso_utc(m.get("occurrence_datetime", "")),
                        parse_iso_utc(m.get("expected_expiration_time", ""))),
                    program_end=info["end"])
            bid = market_cents(m, "yes_bid")
            ask = market_cents(m, "yes_ask")
            _mid = (bid + ask) / 2.0 if bid and ask else None
            _spr = (ask - bid) if bid and ask else None
            if _mid is None and ask and sports_ladder_league(series) is not None:
                # SUB-CENT EDGE (subcent_edge_quotes): market_cents reads a
                # bid under 1c as "no bid"; for this family it is the touch
                _bx = subcent_bid_cents(m)
                if _bx is not None and _bx < ask:
                    _mid, _spr = (_bx + ask) / 2.0, ask      # its bucket is 0
            try:
                volume = float(m.get("volume_fp") or m.get("volume") or 0)
            except (TypeError, ValueError):
                volume = 0.0
            # the pool over the window Kalshi will pay (trimmed_pool_rate)
            _dpd, _pool_end = trimmed_pool_rate(
                series, event_ticker, info["dollars_per_day"],
                info.get("start"), info["end"],
                rules=m.get("rules_primary") or "", now=now_utc)
            if _pool_end is not None \
                    and self._trimmed_pool_noted.get(event_ticker) != _pool_end:
                self._trimmed_pool_noted[event_ticker] = _pool_end
                _st = EVENT_START_OVERRIDES.get(event_ticker)
                log(f"{self.tag} trimmed-window pool {event_ticker}: program "
                    f"listed to {info['end']:%m-%d %H:%MZ}, "
                    + (f"event starts {_st:%m-%d %H:%MZ}" if _st is not None
                       else "no start time, the rules' scheduled day")
                    + f" -> pool spread to {_pool_end:%m-%d %H:%MZ}: "
                    f"${info['dollars_per_day']:.2f} -> ${_dpd:.2f}/day per market "
                    f"(Kalshi trims the period to the close and pays it whole)")
            meta = MarketMeta(
                ticker=t, event_ticker=event_ticker, series=series,
                dollars_per_day=_dpd, program_end=info["end"],
                target_size=info["target"], discount_factor=info["df"],
                cutoff=cutoff, close_time=close_time,
                mid_cents=_mid,
                spread_cents=_spr,
                volume=volume, status=m.get("status", ""),
                open_time=parse_iso_utc(m.get("open_time", "")),
                program_start=info.get("start"),
                price_step=market_price_step(m))
            if _pool_end is not None:
                meta.pool_listed_per_day = info["dollars_per_day"]
                meta.pool_end_eff = _pool_end
            # Band state for the LIFETIME SLOT RULE (2026-09-09), recorded
            # here because this is the last point a slot-holding market is
            # still in hand: one whose touches are outside the band is
            # dropped by _screen as `extreme_mid` and never reaches the cut.
            _plo, _phi = member_price_band(series, t in self.state.selected)
            if not (bid and _plo <= bid <= _phi)                     and not (ask and _plo <= ask <= _phi):
                unquotable_now.add(t)
            if t in scan_pre_set:
                # open-scan candidate: flagged, given its 24h volume (the
                # activity screen + fill-weighted exposure need it) and held
                # back for the admission pass below
                meta.scan = True
                try:
                    meta.volume_24h = float(m.get("volume_24h_fp")
                                            or m.get("volume_24h") or 0)
                except (TypeError, ValueError):
                    meta.volume_24h = 0.0
                scan_metas.append((meta, m))
                continue
            metas.append(meta)

        # OPEN SCAN admission (2026-09-05): event volumes first (they need
        # every bulk-read sibling, pinned strikes included — informed flow
        # on one strike shows up on its neighbours), then the per-market
        # screens richest pool first so the bounded series/candle reads go
        # where the money is. Members skip admission (quote-to-completion)
        # but take the guard set; a tier halted today admits nothing and
        # drops its members from the candidate list (they were deselected
        # when the budget tripped).
        if scan_metas:
            _roll_day = _halt_day_key(now_utc)
            # AVERAGE 24h volume per market on the event (Jack 2026-09-06),
            # over the bulk-read siblings — pinned/one-sided strikes
            # included, which is the point: they are part of how busy the
            # event's ladder really is. Denominator is the same set as the
            # sum, so an event read in part is judged on what was read.
            _ev_sum: Dict[str, float] = {}
            _ev_n: Dict[str, int] = {}
            for _meta, _m in scan_metas:
                _ev_sum[_meta.event_ticker] = (
                    _ev_sum.get(_meta.event_ticker, 0.0) + _meta.volume_24h)
                _ev_n[_meta.event_ticker] = _ev_n.get(_meta.event_ticker, 0) + 1
            ev_vol24 = {ev: _ev_sum[ev] / _ev_n[ev] for ev in _ev_sum}
            budget = {"series": SCAN_MAX_SERIES_FETCHES,
                      "history": SCAN_MAX_HISTORY_FETCHES}
            scan_halted = self.state.scan_halt_day == _roll_day
            scan_metas.sort(key=lambda mm: -mm[0].dollars_per_day)
            # MEMBER POLICY RE-TEST FIRST (2026-09-24): the series-read
            # budget goes to the book the bot is actually quoting before any
            # candidate spends it, so a keyword change reaches every member
            # on the first refresh. An evicted member is left out of the
            # candidate list: it leaves `selected`, the stray-order sweep
            # cancels its quotes, positions ride. _scan_admission re-rejects
            # it on the same screen every refresh, so no bar is needed.
            _evicted: Set[str] = set()
            if not scan_halted:
                for _meta, _m in scan_metas:
                    if _meta.ticker not in self.state.scan_members:
                        continue
                    _why = self._scan_member_policy(
                        _meta, now_utc.timestamp(), budget)
                    if _why is not None:
                        _evicted.add(_meta.ticker)
                        _k = "member_" + _why
                        scan_skips[_k] = scan_skips.get(_k, 0) + 1
                        log(f"{self.tag} open-scan member {_meta.ticker} "
                            f"evicted: {_why} (policy re-test)")
            _admissible: List[MarketMeta] = []
            for _meta, _m in scan_metas:
                if scan_halted:
                    scan_skips["scan_halted"] = scan_skips.get("scan_halted", 0) + 1
                    continue
                if _meta.ticker in _evicted:
                    continue
                if _meta.ticker not in self.state.scan_members:
                    why = self._scan_admission(_meta, _m, ev_vol24, now_utc, budget)
                    if why is not None:
                        scan_skips[why] = scan_skips.get(why, 0) + 1
                        continue
                    _admissible.append(_meta)
                    continue
                ensure_scan_override(_meta.series)
                metas.append(_meta)
            # BOOK BUDGET BY LEAST-RECENTLY-ESTIMATED (2026-09-13 "scan for
            # new available markets hourly"): the budget went to the same
            # top-SCAN_MAX_BOOKS pools every refresh, so an admissible market
            # under that line was never estimated at all (`book_cap` 45-612
            # per refresh on 9/11-9/12, the same names each time). See
            # scan_book_order: every admissible market is estimated within
            # ceil(admissible / SCAN_MAX_BOOKS) refreshes -- two, at 9/12's
            # 155-213 eligible against 120. Members skip the budget as before.
            _seen = self._scan_book_seen
            _now_ts = now_utc.timestamp()
            for _i, _meta in enumerate(scan_book_order(_admissible, _seen)):
                if _i >= SCAN_MAX_BOOKS:
                    scan_skips["book_cap"] = scan_skips.get("book_cap", 0) + 1
                    continue
                _seen[_meta.ticker] = _now_ts
                ensure_scan_override(_meta.series)
                metas.append(_meta)
            # forget names that left the candidate set (memory hygiene)
            _live = {_meta.ticker for _meta, _m in scan_metas}
            for _t in [t for t in _seen if t not in _live]:
                _seen.pop(_t, None)

        # Pass 1: hard screens (+ yield-to-human: never select a market the
        # user is trading manually — divergence vs our own book, a foreign
        # resting order, an active standoff, OR any manual footprint elsewhere
        # in the same EVENT).
        manual_evts = self.manual_events(positions)
        # Sticky membership = the live selection PLUS the persisted one (a
        # restart wipes state.selected — without the persisted set, every
        # restart stranded all in-flight accruals; observed 2026-07-21:
        # CHIH-2109-T75.99 quoted 12:04, dropped 12:06 after the task restart).
        prev_selected = set(self.state.selected) | self.state.sticky_prev
        # Events the bot is ALREADY working. The rate bar below is scoped to
        # these (Jack 2026-08-05: "i want sticky quoting when a market is
        # already quoted, unless it is hopeless. i do not want to open up new
        # events that otherwise weren't being quoted"): a sibling strike on an
        # event we already hold is depth on an exposure we already took, but
        # the first strike of an untouched event is a NEW exposure and still
        # has to clear the bar. Dropping the bar outright did both — measured
        # +122 markets across +9 previously-excluded events.
        prev_events = {"-".join(t.split("-")[:2]) for t in prev_selected}
        screened: List[MarketMeta] = []
        skipped: Dict[str, int] = {}
        # Per-market decision trail. `skipped` counts reasons; this
        # records WHICH market got which one, so "why was X not quoted"
        # and "would the markets I cut have earned more" stop being
        # unanswerable. Analytics only — nothing reads it back.
        decisions: Dict[str, str] = {}
        # Decision INPUTS (2026-09-26, SELECTION_INPUTS): what each floor rule
        # actually looked at, per ticker. Analytics only -- nothing reads it.
        floor_in: Dict[str, dict] = {}
        # members kept despite a pass-1 screen / unreadable book (sticky), so
        # the waiver that kept them is visible instead of silent
        screen_waived: Dict[str, str] = {}
        for meta in metas:
            t = meta.ticker
            coexist = manual_coexist(meta.series, meta.event_ticker)
            manual = abs(positions.get(t, 0.0) - self.pnl.pos.get(t, 0.0))
            foreign_n = self._foreign_resting.get(t, 0) if self.live else 0
            # quote_all markets yield ONLY on a live foreign order here (or an
            # active standoff from one); positions and sibling activity don't
            # stop the bot — the user wants full event coverage. The same for
            # MANUAL_COEXIST_EVENTS (2026-10-13).
            if coexist:
                manual_skip = bool(foreign_n) or t in self.state.manual_standoff
            else:
                manual_skip = (t in self.state.manual_standoff or foreign_n
                               or manual >= MANUAL_STANDOFF_CONTRACTS
                               or meta.event_ticker in manual_evts)
            if manual_skip:
                skipped["manual"] = skipped.get("manual", 0) + 1
                decisions[t] = "manual"
                continue
            reason = self._screen(meta, now_utc,
                                  member=t in prev_selected)
            if (reason and (t in prev_selected
                            or fair_close_hold(meta.series, self.pnl.pos.get(t, 0.0)))
                    and reason not in STICKY_DEATH_REASONS):
                # Sticky: ride out transient quality states on a market we
                # already started quoting (see STICKY_DEATH_REASONS note).
                screened.append(meta)
                screen_waived[t] = reason
            elif reason:
                skipped[reason] = skipped.get(reason, 0) + 1
                decisions[t] = reason
            else:
                screened.append(meta)

        # Pass 2: reward yield per resting contract from each candidate's LIVE
        # book — the objective is incentive per contract-minute quoted, so a
        # $25/day pool with an empty near-touch beats a $145/day pool where
        # farmers already stack the qualification walk.
        own_by_ticker: Dict[str, List[Tuple[str, int, float]]] = {}
        if self.live:
            for o in self.state.ledger.values():
                own_by_ticker.setdefault(o.get("ticker", ""), []).append(
                    (o.get("book_side", "bid"), int(o.get("yes_price", 0)),
                     float(o.get("remaining_count", 0))))
        # two-market twins for the complement lead, and the own orders a
        # twin's book is read without (COMP_LEAD_MODE)
        self._comp_own = own_by_ticker
        if COMP_LEAD_MODE in ("on", "dry"):
            self._refresh_comp_pairs(metas, now_ts)
        self._prune_near_cliff_boost()
        self._prune_yield_boost()
        # the books pass 2 reads go on the WebSocket feed (WS_CANDIDATES)
        self._ws_cand_subscribe(
            [m.ticker for m in screened
             if m.event_ticker not in self.state.event_live_halt]
            # ...with every complement group's siblings and ladder's strikes
            # (COMP_LEAD_MODE)
            + sorted(set(self._comp_groups) | set(self._ladders)))
        # ...and its REST reads are budgeted (CAND_REST_BUDGET_SECS), from
        # after the feed's warm-up wait
        self._cand_rest = {"t0": time.monotonic(), "fails": 0, "off": ""}
        _rest_skip0 = self._ws_cand["rest_skipped"]
        ranked: List[MarketMeta] = []
        for meta in screened:
            quote_all = (series_override(meta.series) or SeriesOverride()).quote_all
            # FAIR CLOSE: a fair-lead market holding a position stays selected
            fc_hold = fair_close_hold(meta.series, self.pnl.pos.get(meta.ticker, 0.0))
            if not self._estimate_candidate_yield(meta, own_by_ticker.get(meta.ticker, [])):
                if meta.ticker in prev_selected or fc_hold:
                    ranked.append(meta)   # sticky: transient book-read failure
                    screen_waived[meta.ticker] = "book_unreadable"
                else:
                    skipped["book_unreadable"] = skipped.get("book_unreadable", 0) + 1
                    decisions[meta.ticker] = "book_unreadable"
                continue
            # Shared min-payout projection for the entry floor AND the
            # hopeless exit. For a MEMBER it is optimistic: accrued-so-far +
            # max(current, 1h-peak) remaining -- the peak is a dip guard so
            # one low reading cannot evict. NOTE the peak alone does NOT stop
            # a dip from evicting: `pts` only refreshes on a new HIGH, so a
            # declining estimate lets the peak expire and then one low
            # reading is enough. The explicit dip guard below is what holds.
            # For a FRESH candidate the peak is NOT consulted (Jack
            # 2026-09-13: "test fresh admissions on the current estimate
            # plus accrued only, no peak"): the entry test is what the
            # market earns NOW plus what it has banked. Measured the day the
            # 60-seat cap opened: 15 Sunday state-print strikes entered at
            # 14:31Z on peaks from the 13:3x window ($1.5-2.1 projected)
            # while their live projection was $0.75-1.46; the peaks expired
            # by the 14:39Z refresh and the same rule put all 15 on the
            # hopeless clock -- an hour of fill risk, then a permanent bar,
            # for markets that never cleared the floor on their own numbers.
            # Accrued still counts for a re-entrant (a market that banked
            # most of its floor re-enters on the remaining window).
            # 2026-09-26: MEMBERS are on the live projection too unless
            # IMM_MEMBER_PEAK_GUARD=1 (see MEMBER_PEAK_GUARD) -- the peak's
            # single-reading re-seed made exits a lottery, and the 30-minute
            # sustain clock below is the dip guard. The peak is still
            # tracked, so the knob restores it without a warm-up hour.
            qdays = _quotable_days(meta, now_utc)
            # day-size projection (FLOOR_PROJECTION_BASE_SIZE, 2026-09-25):
            # a market is not admitted on doubled size and evicted on normal
            est_total = meta.floor_dollars_per_day * qdays
            peak, pts = self._est_peak.get(meta.ticker, (0.0, 0.0))
            if now_ts - pts > EST_PEAK_TTL_SECS:
                peak = 0.0
            if est_total > peak:
                self._est_peak[meta.ticker] = (est_total, now_ts)
                peak = est_total
            accrued = self.period_accrued(meta.ticker)
            proj_peak = peak if (MEMBER_PEAK_GUARD
                                 and meta.ticker in prev_selected) else 0.0
            # THE BAR (floor_bar_dollars, 2026-09-25): the exchange's $1.00
            # cliff for a member or a re-entrant with banked period accrual,
            # the $1.50 entry margin for a fresh candidate. Sub-$1 accrual
            # pays nothing, so the exit must ask "can it still clear $1",
            # not "would we enter it today".
            floor_bar = floor_bar_dollars(
                meta.series, meta.ticker in prev_selected or accrued > 0.0)
            projected_total = accrued + max(est_total, proj_peak)
            reaches_min = projected_total >= floor_bar
            # NEAR-CLIFF (Jack 2026-09-26, see NEAR_CLIFF_DOLLARS): a market
            # that has banked most of the cliff and projects to just under
            # it quotes to completion -- the same verdict feeds the hopeless
            # exit below, so it cannot flap around the cliff.
            meta.near_cliff = False
            # (a fresh zero-yield candidate is still stopped by the zero_yield
            # gate below, so it neither logs nor arms the size mode)
            if not reaches_min and near_cliff_ok(accrued, projected_total) \
                    and (meta.ticker in prev_selected or meta.yield_per_contract > 0):
                reaches_min = True
                meta.near_cliff = True
                # SIZE mode arms only past the banked gate (strict, Jack:
                # "only do this if banked is > $0.50") and with the knob on
                armed = False
                if meta.ticker not in self._near_cliff_boost \
                        and accrued > NEAR_CLIFF_BOOST_MIN_BANKED \
                        and NEAR_CLIFF_SIZE_MULT > 0 and NEAR_CLIFF_SIZE_MULT != 1.0:
                    self._near_cliff_boost[meta.ticker] = now_ts
                    armed = True
                if meta.ticker not in self._near_cliff_noted or armed:
                    self._near_cliff_noted[meta.ticker] = now_ts
                    _sz = self._near_cliff_size_mult(meta.ticker)
                    log(f"{self.tag} near-cliff: {meta.ticker} banked ${accrued:.2f} "
                        f"+ projected ${max(est_total, proj_peak):.2f} = "
                        f"${projected_total:.2f}, within ${NEAR_CLIFF_DOLLARS:.2f} of "
                        f"the ${PAYOUT_FLOOR_DOLLARS:.2f} cliff; quoting to completion"
                        + (f" at x{_sz:g} size until it crosses" if _sz != 1.0
                           else f" at plain size (banked <= ${NEAR_CLIFF_BOOST_MIN_BANKED:.2f})"
                           if NEAR_CLIFF_SIZE_MULT > 0 and NEAR_CLIFF_SIZE_MULT != 1.0
                           else ""))
            meta.near_cliff_boost = meta.ticker in self._near_cliff_boost
            # DIP GUARD (Jack 2026-08-05). Track how long the projection has
            # been continuously under the bar; the exit below refuses to fire
            # until that exceeds HOPELESS_SUSTAIN_SECS, so a dip cannot evict.
            # ADMISSION CLOCK (2026-09-27): the mirror image -- how long it
            # has HELD at/above the bar. Fresh entry waits for it, and only a
            # held run (not a single spike) resets the dip guard's clock.
            sub_bar_secs, above_secs = self._floor_clocks(
                meta.ticker, reaches_min, now_ts)
            # DECISION INPUTS: stash what the floor rules below look at. Reads
            # only; its own try so an analytics bug can never break selection.
            if SELECTION_INPUTS:
                try:
                    _pk = self._est_peak.get(meta.ticker)
                    floor_in[meta.ticker] = {
                        "member": meta.ticker in prev_selected,
                        "qdays": round(qdays, 4),
                        "est_total": round(est_total, 4),
                        "peak": round(peak, 4),
                        "peak_age_s": round(now_ts - _pk[1]) if _pk else None,
                        "proj_peak": round(proj_peak, 4),
                        "banked": round(accrued, 4),
                        "accrued_lifetime": round(
                            self.state.accrued_est.get(meta.ticker, 0.0), 4),
                        "period_base": self.state.period_base.get(meta.ticker),
                        "period_start": self.state.period_start.get(meta.ticker),
                        "floor_bar": floor_bar,
                        "projected_total": round(projected_total, 4),
                        # before the near-cliff override flips it True
                        "reaches_min_raw": projected_total >= floor_bar,
                        "reaches_min": reaches_min,
                        "near_cliff_armed_ts": self._near_cliff_boost.get(meta.ticker),
                        "hopeless_since": self.state.hopeless_since.get(meta.ticker),
                        "sub_bar_secs": round(sub_bar_secs),
                        # the admission clock (2026-09-27): held-above time
                        "above_secs": round(above_secs),
                        "rate_bar": series_min_est_rate(meta.series),
                        # the $/day the rate bar compares (RATE_FLOOR_SCHEDULE)
                        "rate_est": round(rate_floor_rate(meta), 4),
                        "rate_proj": round(rate_floor_projected(
                            accrued, est_total, proj_peak, qdays), 4),
                        "new_event": meta.event_ticker not in prev_events,
                        "exempt": ("quote_all" if quote_all else
                                   "fair_close" if fc_hold else
                                   "force" if meta.event_ticker in FORCE_EVENTS else
                                   "curated" if curated_event(meta.event_ticker,
                                                              meta.series, now_utc) else
                                   "finecon" if meta.series in FINECON_SERIES else
                                   "no_new" if meta.series in NO_NEW_SERIES else ""),
                    }
                except Exception:
                    pass
            if quote_all or fc_hold:
                # user wants EVERY market of the event (2026-07-12): exempt
                # from floors, the hopeless exit and the yield ranking (and a
                # fair-lead market holding a position: FAIR CLOSE)
                ranked.append(meta)
            elif meta.series in NO_NEW_SERIES \
                    and meta.ticker not in prev_selected:
                # no-new gate (Jack 2026-07-28): company family admits no
                # fresh markets; members above keep quoting via the branch
                # below until natural death.
                skipped["no_new"] = skipped.get("no_new", 0) + 1
                decisions[meta.ticker] = "no_new"
            elif HOPELESS_EXIT and not reaches_min \
                    and sub_bar_secs >= HOPELESS_SUSTAIN_SECS \
                    and meta.ticker in prev_selected \
                    and meta.series not in FINECON_SERIES \
                    and (SCAN_HOPELESS_EXIT or not meta.scan) \
                    and meta.event_ticker not in FORCE_EVENTS \
                    and not curated_event(meta.event_ticker, meta.series, now_utc):
                # STICKY EXIT (Jack 2026-07-25): "<5% chance to reach $1 by
                # program end -> stop quoting, even if already started". The
                # deliberate exception to sticky retention — sub-$1 accrual
                # pays NOTHING, so riding a hopeless market to its natural
                # end is pure fill risk for zero reward. The accrued credit
                # keeps every market that's genuinely close to $1 (the 7/24
                # TRUMPMENTION rule). Wind-down continues reduce-only via
                # managed_extra. OVERRIDE-listed events are EXEMPT (both
                # states, so no flapping — Jack 2026-07-28, tele-rally 8/22
                # quoted: the drain rule targets the anonymous scrap tail,
                # not hand-curated event windows, and the estimator's
                # absolute $1 verdicts are least trustworthy on the short
                # windows overrides create). Finecon members are EXEMPT
                # too (Jack 2026-09-03 "once start quoting, should quote
                # to completion. dont unquote them"): cents-a-day rates on
                # deliberately quiet long windows are where the absolute
                # $1 projection is noisiest, and the group is 10 small
                # ladders — the drain rule's fill-risk argument is thin.
                skipped["hopeless"] = skipped.get("hopeless", 0) + 1
                decisions[meta.ticker] = "hopeless"
                # HOPELESS IS A PERMANENT BAR FOR SCAN MARKETS (Jack
                # 2026-09-09: "after hopeless eviction, the market should be
                # barred"). Nothing used to stop a re-admission: the exit
                # branch requires `prev_selected`, so once out the market is
                # judged only by the ordinary entry floor, and a jittering
                # estimate buys it back. Measured 2026-09-08:
                # KXDIESELELECT-26NOV03-T4.40 was admitted 20:38, evicted
                # 22:42, RE-ADMITTED 04:00 on one of the five scarce daily
                # openings, and evicted again 06:00 — two of that day's five
                # openings spent re-buying markets already judged unable to
                # reach the payout floor. Scan only; the normal book keeps its
                # existing re-entry behaviour.
                if meta.scan and SCAN_HOPELESS_BAR:
                    if meta.ticker not in self.state.scan_hopeless_barred:
                        log(f"{self.tag} open-scan barred {meta.ticker}: "
                            f"hopeless (projection cannot reach "
                            f"${floor_bar:.2f} before "
                            f"program end); no re-admission")
                    self.state.scan_hopeless_barred[meta.ticker] = now_ts
            elif meta.ticker not in prev_selected \
                    and meta.event_ticker not in prev_events \
                    and meta.event_ticker not in FORCE_EVENTS \
                    and rate_floor_rate(meta) < series_min_est_rate(meta.series) \
                    and rate_floor_projected(accrued, est_total, proj_peak,
                                             qdays) \
                    < RATE_FLOOR_TOTAL_ALT:
                # Rate-floored only when the market ALSO fails the horizon
                # escape. The projected total uses the same quantity as the
                # payout floor below (accrued + best of current/1h-peak) so the
                # two gates cannot disagree about what a market will earn.
                # Re-entry rate floor OUTRANKS event curation (Jack 2026-08-02
                # TLN audit: the auto-written company-disclosure override
                # curated KXTLN-26AUGGEN past the $2 bar at ~$0.45/day est).
                # The curated bypass below exists because SHORT windows sink
                # est_TOTAL — a per-day RATE has no such excuse. Members stay
                # sticky (rate dips never evict; hopeless owns exits).
                skipped["rate_floor"] = skipped.get("rate_floor", 0) + 1
                decisions[meta.ticker] = "rate_floor"
            elif meta.ticker in prev_selected \
                    or meta.event_ticker in FORCE_EVENTS \
                    or curated_event(meta.event_ticker, meta.series, now_utc):
                # Sticky members and event-start-override events bypass the
                # entry floor / zero-yield / budget-race filters (original
                # sticky patch, commit 6f1e3d2 + the 2026-07-24 TRUMPMENTION
                # revival: a curated override window must not be vetoed by
                # the floor). Budget, pass-1 screens and yield-to-human
                # still govern.
                ranked.append(meta)
            elif meta.yield_per_contract <= 0:
                skipped["zero_yield"] = skipped.get("zero_yield", 0) + 1
                decisions[meta.ticker] = "zero_yield"
            elif not reaches_min:
                # entry floor, now with the accrued credit: a re-admitted
                # market that already banked most of its $1 re-enters even
                # when the remaining window alone couldn't clear the bar.
                skipped["payout_floor"] = skipped.get("payout_floor", 0) + 1
                decisions[meta.ticker] = "payout_floor"
            elif ADMIT_SUSTAIN_SECS > 0 and not meta.near_cliff \
                    and above_secs < ADMIT_SUSTAIN_SECS:
                # THE ADMISSION CLOCK (2026-09-27, see ADMIT_SUSTAIN_SECS):
                # over the bar on this reading, but not yet for the sustain
                # window -- a spike this refresh is not an admission. It
                # enters on the first reading that finds the run long enough.
                skipped["admit_pending"] = skipped.get("admit_pending", 0) + 1
                decisions[meta.ticker] = "admit_pending"
            else:
                # an ADMISSION starts the dip guard clean, as it always did
                # (a held run already cleared it; this covers the near-cliff
                # re-entrant, admitted on its first reading)
                self.state.hopeless_since.pop(meta.ticker, None)
                ranked.append(meta)
        if self._cand_rest["off"]:
            log(f"{self.tag} ! universe refresh: candidate REST reads stopped "
                f"after {time.monotonic() - self._cand_rest['t0']:.0f}s -- "
                f"{self._cand_rest['off']}; "
                f"{self._ws_cand['rest_skipped'] - _rest_skip0} book(s) not "
                f"read (members ride through, fresh candidates wait for the "
                f"next refresh)")
        self._cand_rest = None
        # Mild stickiness so estimator jitter doesn't churn the selection.
        ranked.sort(key=lambda m: -m.yield_per_contract
                    * (1.15 if m.ticker in self.state.selected else 1.0))

        # Finecon quote-to-completion members (Jack 2026-09-03: "once start
        # quoting, should quote to completion. dont unquote them"): a group
        # market the bot is already quoting is immune to BOTH ranking cuts
        # below — it leaves only by natural completion or a safety screen.
        fin_sticky = {m.ticker for m in ranked
                      if m.series in FINECON_SERIES
                      and m.ticker in prev_selected}
        # Open-scan members (2026-09-05): the same quote-to-completion
        # immunity — they leave by natural completion, a safety screen or
        # the tier's own tripwires, never by being out-ranked.
        scan_sticky = {m.ticker for m in ranked
                       if m.scan and m.ticker in prev_selected}

        # Per-event TOP-N (Jack 2026-09-02, gas — see event_top_n_cut):
        # applied BEFORE sticky seeding so a market past the cap falls out of
        # `ranked`, out of `selected`, and through the normal deselect/cancel
        # path this cycle. Finecon/scan members are fully immune; the capped
        # families' own quoting markets hold their slots against challengers
        # (Jack 2026-09-06 "it should be constant" — EVENT_TOP_N_STICKY) but
        # are still trimmed if they alone exceed N.
        topn_sticky = {m.ticker for m in ranked
                       if EVENT_TOP_N_STICKY
                       and event_top_n_for(m.series) > 0
                       and m.ticker in prev_selected}
        # Lifetime slot ledger (Jack 2026-09-07 "3 max quoted markets on an
        # event, not 3 at a given time"): what each capped event has already
        # spent. Read before the cut, written after it with whatever the cut
        # kept — so a market only ever burns a slot by actually surviving
        # into the selection.
        slots_used = ({e: self._live_event_slots(e, v, unquotable_now)
                       for e, v in self.state.event_slots.items()}
                      if EVENT_TOP_N_LIFETIME else None)
        topn_cut = event_top_n_cut(ranked, prev_selected,
                                   immune=fin_sticky | scan_sticky,
                                   members=topn_sticky,
                                   slots_used=slots_used)
        if topn_cut:
            skipped["event_top_n"] = len(topn_cut)
            decisions.update({_t: "event_top_n" for _t in topn_cut})
            ranked = [m for m in ranked if m.ticker not in topn_cut]
        if EVENT_TOP_N_LIFETIME:
            # TTL TOUCH ONLY — the slot itself is spent much further down,
            # against the FINAL selection (Jack 2026-09-09: "fix the lifetime
            # slot ordering too"). The touch cannot move with it: `ts` is the
            # persist filter (EVENT_SLOTS_TTL_SECS, 14d), so an event whose
            # candidates are all cut this refresh must still keep its ledger
            # entry alive or it would age out of the state file and hand the
            # event a fresh lifetime budget — the exact "kept admitting
            # replacements" the ledger exists to stop.
            for _m in ranked:
                if event_top_n_for(_m.series) <= 0:
                    continue
                _slot = self.state.event_slots.setdefault(
                    _m.event_ticker, {"markets": [], "ts": now_ts})
                _slot["ts"] = now_ts

        # Finecon GROUP top-N (Jack 2026-09-02 — see finecon_group_cut):
        # after the per-event cut so a gas-monthly strike trimmed there can
        # never re-enter through the group walk; admission-only for the
        # slots the quote-to-completion members leave free, plus the daily
        # openings (Jack 2026-09-05) — up to FINECON_DAILY_OPENINGS
        # over-cap admissions per ET day so a fresh high-ROI event can
        # enter even with all 15 slots held.
        et_today = now_utc.astimezone(ET).date().isoformat()
        if self.state.finecon_admit_day != et_today:
            self.state.finecon_admit_day = et_today
            self.state.finecon_admits_today = 0
        openings_left = max(0, FINECON_DAILY_OPENINGS
                            - self.state.finecon_admits_today)
        # Pre-refresh membership for the refill target. `fin_sticky` is built
        # from the post-screen `ranked`, so this refresh's departures are
        # already subtracted from it; `prev_selected` still holds them.
        fin_prev_count = sum(1 for _t in prev_selected
                             if series_of(_t) in FINECON_SERIES)
        fin_cut = finecon_group_cut(ranked, prev_selected,
                                    members=fin_sticky,
                                    extra_openings=openings_left,
                                    refill_to=fin_prev_count)
        if fin_cut:
            skipped["finecon_top_n"] = len(fin_cut)
            decisions.update({_t: "finecon_top_n" for _t in fin_cut})
            ranked = [m for m in ranked if m.ticker not in fin_cut]
        kept_group = sum(1 for m in ranked if m.series in FINECON_SERIES)
        # A REFILL IS NOT AN EXPANSION: charge openings only for growth past
        # the pre-refresh membership, or the seat a departure freed would
        # bill an opening it never used.
        used = finecon_openings_used(
            kept_group, max(len(fin_sticky),
                            fin_prev_count if FINECON_REFILL_ON_DEPARTURE
                            else 0))
        if used:
            self.state.finecon_admits_today += used
            log(f"{self.tag} finecon daily openings: {used} used this "
                f"refresh ({self.state.finecon_admits_today}"
                f"/{FINECON_DAILY_OPENINGS} today)")

        # OPEN SCAN group walk (2026-09-05 — see scan_group_cut): the
        # finecon walk with its own slots, per-event cap, daily openings and
        # burn counter, over the metas flagged `scan`.
        if self.state.scan_admit_day != et_today:
            self.state.scan_admit_day = et_today
            self.state.scan_admits_today = 0
        # PACED (2026-09-09): only the openings unlocked by now are spendable.
        scan_openings_left = max(0, scan_openings_allowed(now_utc)
                                 - self.state.scan_admits_today)
        # Pre-refresh membership: `scan_sticky` already lost this refresh's
        # departures, so the refill target has to come from persisted state.
        scan_prev_count = len(self.state.scan_members)
        scan_cut = scan_group_cut(ranked, prev_selected, members=scan_sticky,
                                  extra_openings=scan_openings_left,
                                  refill_to=scan_prev_count)
        if scan_cut:
            skipped["scan_top_n"] = len(scan_cut)
            decisions.update({_t: "scan_top_n" for _t in scan_cut})
            ranked = [m for m in ranked if m.ticker not in scan_cut]
        kept_scan = sum(1 for m in ranked if m.scan)
        # A REFILL IS NOT AN EXPANSION: charge openings only for growth past
        # the pre-refresh membership, or the seat a departure freed would
        # bill an opening it never used.
        used_scan = scan_openings_used(
            kept_scan, max(len(scan_sticky),
                           scan_prev_count if SCAN_REFILL_ON_DEPARTURE else 0))
        if used_scan:
            self.state.scan_admits_today += used_scan
            log(f"{self.tag} open-scan daily openings: {used_scan} used this "
                f"refresh ({self.state.scan_admits_today}"
                f"/{SCAN_DAILY_OPENINGS} today)")

        selected: Dict[str, MarketMeta] = {}
        collateral = 0.0
        # Inventory reserve: the bot's OWN open book consumes budget at a
        # 50c/contract estimate. Own-book positions, not account positions —
        # the fleet's and the user's manual inventory must not starve this
        # bot's budget.
        inv_reserve = sum(abs(v) for v in self.pnl.pos.values()) * 0.50

        def market_cost(meta: MarketMeta) -> float:
            if meta.mid_cents is None or meta.spread_cents is None:
                # Retained one-sided/pinned market: no readable mid; actual
                # resting there is ~1c-side scraps, so don't charge the budget.
                return 0.0
            bid = int(meta.mid_cents - meta.spread_cents / 2)
            ask = int(meta.mid_cents + meta.spread_cents / 2)
            lv = scale_levels(hour_scaled_levels(meta.series, now_utc),
                              self._market_size_mult(meta.ticker))
            # per-side deep-reference size multipliers (2026-08-02 audit):
            # atref rests up to 2x the spec size, so an unscaled reservation
            # under-charged the budget up to ~2x on mid-priced deep-ref books
            # (anchor pricing stays — actual rests at/below the anchor cost).
            _cbm, _cam = side_size_mults(meta.ticker, now_utc, meta.mid_cents)
            worst = (ladder_collateral_dollars(bid, None, scale_levels(lv, _cbm))
                     * meta.ref_mult_bid
                     + ladder_collateral_dollars(None, ask, scale_levels(lv, _cam))
                     * meta.ref_mult_ask)
            return worst * COLLATERAL_REALIZATION   # realistic, not worst-case

        # quote_all series (e.g. Love Island) are force-included: EVERY market
        # of the event, exempt from the yield ranking, MAX_MARKETS, and the
        # collateral budget (user decision 2026-07-12 — high incentive/minute,
        # one-day pools). They're taken first so they always fit.
        # Sticky retention is seeded FIRST: the budget and the event cap can
        # never evict a market the bot already started quoting (its accrual
        # rides to the market's natural end). Their events count toward the
        # event cap — they are genuinely open.
        selected_events: Set[str] = set()
        for meta in ranked:
            if meta.ticker in prev_selected:
                collateral += market_cost(meta)
                selected[meta.ticker] = meta
                selected_events.add(meta.event_ticker)
        forced = [m for m in ranked
                  if m.ticker not in selected
                  and ((series_override(m.series) or SeriesOverride()).quote_all
                       or fair_close_hold(m.series, self.pnl.pos.get(m.ticker, 0.0)))]
        for meta in forced:
            collateral += market_cost(meta)
            selected[meta.ticker] = meta
        forced_collateral = collateral
        # MAX_MARKETS bounds the number of distinct EVENTS, not markets: once an
        # event is opened (its best-yielding market clears the budget), EVERY
        # other screened market of that event is eligible too — no per-event
        # market cap (user rule 2026-07-13). The collateral budget is then the
        # only governor on how many of an event's markets actually rest.
        # Iterate ALL ranked (no break): a sibling of an already-open event must
        # stay reachable even after the event cap is hit.
        for meta in ranked:
            if meta.ticker in selected:
                continue
            new_event = meta.event_ticker not in selected_events
            if MAX_MARKETS > 0 and new_event and len(selected_events) >= MAX_MARKETS:
                continue
            cost = market_cost(meta)
            if collateral + cost + inv_reserve > COLLATERAL_BUDGET:
                skipped["budget"] = skipped.get("budget", 0) + 1
                decisions[meta.ticker] = "budget"
                continue
            collateral += cost
            selected[meta.ticker] = meta
            selected_events.add(meta.event_ticker)

        dropped = [t for t in self.state.selected if t not in selected]
        added = [t for t in selected if t not in self.state.selected]
        self.state.selected = selected
        # LIFETIME SLOTS ARE SPENT HERE (Jack 2026-09-09: "fix the lifetime
        # slot ordering too"). The ledger used to be written straight after
        # event_top_n_cut, which is what the comment up there always claimed
        # ("written after it with whatever the cut kept — so a market only
        # ever burns a slot by actually surviving into the selection"). Three
        # more filters run after that point, and every one of them could take
        # a market that had already recorded its slot: finecon_group_cut,
        # scan_group_cut, and the MAX_MARKETS/collateral loop below. A market
        # cut by any of them held a PERMANENT slot on its event without ever
        # being quoted or earning a cent. Measured 2026-09-09 17:17Z: 3 such
        # slots on events with live programs (KXDIESELYE-26DEC31 2 of its 3,
        # KXAAAGASDVA-26SEP10 1 of 3).
        #
        # `ranked` is iterated rather than `selected` so the ledger keeps its
        # ROI order; `selected` is built only from `ranked`, so the two agree
        # on membership. The per-event cap is unaffected: event_top_n_cut
        # reads `slots_used` from the PREVIOUS refreshes' ledger, above, and
        # appending later cannot let an event exceed N — only markets the cut
        # already allowed can reach here.
        if EVENT_TOP_N_LIFETIME:
            for _m in ranked:
                if _m.ticker not in selected or event_top_n_for(_m.series) <= 0:
                    continue
                _slot = self.state.event_slots.setdefault(
                    _m.event_ticker, {"markets": [], "ts": now_ts})
                _slot["ts"] = now_ts
                if _m.ticker not in _slot["markets"]:
                    _slot["markets"].append(_m.ticker)
                    log(f"{self.tag} event slot {len(_slot['markets'])}"
                        f"/{event_top_n_for(_m.series)} on "
                        f"{_m.event_ticker}: {_m.ticker}")
        # Open-scan membership bookkeeping (2026-09-05): an admission anchors
        # the drift tripwire at the admission mid and joins the loss-budget
        # book (which only shrinks once a market is flat AND gone).
        new_scan = {t for t, m in selected.items() if m.scan}
        for t in sorted(new_scan - self.state.scan_members):
            mid0 = selected[t].mid_cents
            if mid0 is not None:
                self.state.scan_entry_mid[t] = mid0
            log(f"{self.tag} open-scan admit {t}: pool "
                f"${selected[t].dollars_per_day:.2f}/d, est "
                f"${selected[t].est_dollars_per_day:.2f}/d, mid "
                f"{mid0 if mid0 is None else round(mid0, 1)}c, vol24h "
                f"{selected[t].volume_24h:.0f}")
        for t in self.state.scan_members - new_scan:
            self.state.scan_entry_mid.pop(t, None)
        self.state.scan_members = new_scan
        self.state.scan_book |= new_scan
        # The persisted sticky set is consumed by this refresh: survivors are
        # in state.selected now; the rest died a natural death and must not be
        # resurrected by later refreshes (or grow the persist unboundedly).
        self.state.sticky_prev = set()
        self._est_peak = {t: v for t, v in self._est_peak.items()
                          if now_ts - v[1] <= EST_PEAK_TTL_SECS}
        self.state.universe_at = now_ts
        est_total = sum(m.est_dollars_per_day for m in selected.values())
        log(f"{self.tag} universe: {self.state.programs_count} program markets -> "
            f"{len(metas)} candidates -> {len(selected)} selected "
            f"across {len(selected_events)}"
            f"{('/' + str(MAX_MARKETS)) if MAX_MARKETS > 0 else ''} events "
            f"({len(forced)} forced quote-all @ ~${forced_collateral:.0f}, "
            f"total ~${collateral:.0f} ladder collateral, "
            f"${inv_reserve:.0f} inventory reserve); skips {skipped}")
        if yield_size_active(now_ts):
            n_ys = sum(1 for t in selected if t in self._yield_boost)
            if n_ys != getattr(self, "_ys_logged_n", None):
                self._ys_logged_n = n_ys
                log(f"{self.tag} yield size: {n_ys} of {len(selected)} selected markets at "
                    f"x{YIELD_SIZE_MULT:g} (yield >= ${YIELD_SIZE_MIN:g}/contract/day, "
                    f"held to ${YIELD_SIZE_MIN * YIELD_SIZE_EXIT_FRAC:g})")
        if added:
            log(f"{self.tag} + selected: {', '.join(sorted(added)[:8])}"
                + (" ..." if len(added) > 8 else ""))
        if dropped:
            log(f"{self.tag} - deselected: {', '.join(sorted(dropped)[:8])}"
                + (" ..." if len(dropped) > 8 else ""))
        # The prose above truncates to 8 tickers and the skip reasons are only
        # ever aggregate counts, so ~86% of the candidate universe has left no
        # per-market record anywhere. Two sinks fix that at different cadences.
        try:
            by_ticker = {m.ticker: m for m in metas}
            # keys the selection rows already own; the decision-input merge
            # below may never overwrite them (send_opportunistic_imm.py
            # substring-filters on '"decision": "selected"' and '"is_scan": true')
            _RESERVED = {"ticker", "decision", "prev", "ts", "is_scan", "series",
                         "event_ticker", "near_cliff", "near_cliff_boost"}

            def _input_fields(mt) -> dict:
                """Decision INPUTS for one candidate (SELECTION_INPUTS). Its own
                try: an exception anywhere in this block would mute the WHOLE
                selection stream for the run, so a bug here must cost at most
                these extra fields, never the rows."""
                if not SELECTION_INPUTS or mt is None:
                    return {}
                try:
                    out = {
                        "est_frac": round(mt.est_frac, 6),
                        "est_hour_mult": mt.est_hour_mult,
                        "nc_size_mult": mt.nc_size_mult,
                        "ys_size_mult": mt.ys_size_mult,
                        "floor_by_mult": mt.floor_by_mult or None,
                        "floor_realized_ratio": (
                            round(mt.floor_realized_ratio, 4)
                            if mt.floor_realized_ratio is not None else None),
                        "cutoff": mt.cutoff.isoformat() if mt.cutoff else None,
                        "program_end": (mt.program_end.isoformat()
                                        if mt.program_end else None),
                        "screen_waived": screen_waived.get(mt.ticker),
                    }
                    if mt.pool_end_eff is not None:     # trimmed_pool_rate
                        out["pool_listed_per_day"] = round(mt.pool_listed_per_day, 2)
                        out["pool_end_eff"] = mt.pool_end_eff.isoformat()
                    out.update(floor_in.get(mt.ticker, {}))
                    return {k: v for k, v in out.items() if k not in _RESERVED}
                except Exception:
                    return {}

            def _meta_fields(mt) -> dict:
                if mt is None:
                    return {}
                return {
                    **_input_fields(mt),
                    "series": mt.series, "event_ticker": mt.event_ticker,
                    "est_dollars_per_day": round(mt.est_dollars_per_day, 4),
                    "floor_dollars_per_day": round(mt.floor_dollars_per_day, 4),
                    "floor_mult_profile": mt.floor_mult_profile,
                    "near_cliff": bool(getattr(mt, "near_cliff", False)),
                    "near_cliff_boost": bool(getattr(mt, "near_cliff_boost", False)),
                    "yield_per_contract": round(mt.yield_per_contract, 6),
                    "dollars_per_day": round(mt.dollars_per_day, 2),
                    "target_size": mt.target_size,
                    "est_collateral_dollars": round(mt.est_collateral_dollars, 2),
                    "book_depth_contracts": mt.book_depth_contracts,
                    "mid_cents": mt.mid_cents, "spread_cents": mt.spread_cents,
                    "volume": mt.volume, "is_scan": bool(getattr(mt, "scan", False)),
                    # decides per-event slots as of 2026-09-07 (a one-sided
                    # candidate sorts below every two-sided one and forfeits
                    # tenure), so "why did X hold the slot" is unanswerable
                    # without it — the exact question the est/ROI columns
                    # alone could not settle for KXTRUEV-26SEP07-T1263.42.
                    "quotable_sides": mt.quotable_sides,
                }

            # (a) Event-driven: only decisions that CHANGED since the last
            # refresh. This is what makes an incident reconstructable — both
            # times this bot silently benched hundreds of markets, the state
            # had to be recovered from prose after the fact.
            now_dec = dict(decisions)
            for tk in selected:
                now_dec[tk] = "selected"
            events = []
            for tk, dec in now_dec.items():
                if self._selection_prev.get(tk) != dec:
                    events.append({"ticker": tk, "decision": dec,
                                   "prev": self._selection_prev.get(tk),
                                   **_meta_fields(by_ticker.get(tk))})
            for tk, prev in self._selection_prev.items():
                if tk not in now_dec and prev != "gone":
                    events.append({"ticker": tk, "decision": "gone", "prev": prev})
            for e in events:
                e["ts"] = now_utc.isoformat()
                self._sink("selection_events", e)
            self._selection_prev = now_dec

            # (a2) FLOOR STATE of MEMBERS (SELECTION_INPUTS). A member under
            # the bar keeps decision "selected" while its hopeless clock runs,
            # and selection_events fires only on a decision CHANGE -- so the
            # clock starting, resetting, being carried by near-cliff, or the
            # boost arming were all invisible. Emitted to its OWN sink, not
            # selection_events, so that stream keeps meaning "one row per
            # decision change". Own try: a bug here must not mute selection.
            if SELECTION_INPUTS:
                try:
                    fs_now: Dict[str, tuple] = {}
                    for tk in now_dec:
                        fi = floor_in.get(tk)
                        if not fi or not fi.get("member"):
                            continue
                        fs_now[tk] = (fi.get("reaches_min_raw"), fi.get("reaches_min"),
                                      tk in self._near_cliff_boost)
                    # A member kept sticky through an unreadable book skips the
                    # floor computation this refresh, so it has no floor_in.
                    # Carry its last known state forward: forgetting it would
                    # re-emit an unchanged state as "new" next refresh, or
                    # misreport the prior state of a real change.
                    for tk, dec in now_dec.items():
                        if dec == "selected" and tk not in fs_now \
                                and tk in self._floor_state_prev:
                            fs_now[tk] = self._floor_state_prev[tk]
                    for tk, fs in fs_now.items():
                        pfs = self._floor_state_prev.get(tk)
                        if pfs != fs:
                            self._sink("floor_state", {
                                "ts": now_utc.isoformat(), "ticker": tk,
                                "decision": now_dec.get(tk),
                                "reaches_min_raw": fs[0], "reaches_min": fs[1],
                                "near_cliff_boost_armed": fs[2],
                                "prev_state": list(pfs) if pfs else None,
                                **_meta_fields(by_ticker.get(tk))})
                    self._floor_state_prev = fs_now
                except Exception as e:
                    if "floor_state" not in self._sink_muted:
                        self._sink_muted.add("floor_state")
                        log(f"{self.tag} ! floor-state sink failed ({e}); muted this run")

            # (b) Hourly full snapshot of every candidate. This is the only
            # thing that makes the counterfactual possible: realized credits
            # on the markets we kept against modelled yield on the ones each
            # cut reason dropped.
            if now_ts - self._selection_snap_at >= 3600:
                self._selection_snap_at = now_ts
                for mt in metas:
                    self._sink("selection_snapshot", {
                        "ts": now_utc.isoformat(), "ticker": mt.ticker,
                        "decision": now_dec.get(mt.ticker, "not_ranked"),
                        **_meta_fields(mt)})
                log(f"{self.tag} selection snapshot: {len(metas)} candidates "
                    f"({len(events)} decision changes this refresh)")
        except Exception as e:
            if "selection" not in self._sink_muted:
                self._sink_muted.add("selection")
                log(f"{self.tag} ! selection sink failed ({e}); muted this run")
        if scan_on:
            log(f"{self.tag} open-scan: {len(scan_pre)} string-screened -> "
                f"{sum(1 for m in metas if m.scan)} eligible -> "
                f"{len(new_scan)}/{SCAN_TOP_N} members "
                + (f"(+{self.state.scan_admits_today}/{SCAN_DAILY_OPENINGS} "
                   f"openings used today" if SCAN_DAILY_OPENINGS > 0
                   else f"(hard cap {scan_ceiling()}")
                + (", HALTED today" if self.state.scan_halt_day == _halt_day_key(now_utc) else "")
                + f"); rejects {dict(sorted(scan_skips.items()))}")
        _config_gaps_window_done(bool(metas))

    # ---- Carbon Arc name-pattern families (2026-09-22) ---------------------

    def _ca_late_note(self, event_ticker: str, bm: float, am: float) -> None:
        """Log once per event (per process) when the Carbon Arc late-month
        rule engages, so the halved ladder is never a silent change."""
        seen = getattr(self, "_ca_late_seen", None)
        if seen is None:
            seen = self._ca_late_seen = set()
        if event_ticker in seen:
            return
        seen.add(event_ticker)
        _b = "bid side BLOCKED" if bm <= 0 else f"bids x{bm:g}"
        _a = "ask side BLOCKED" if am <= 0 else f"asks x{am:g}"
        _stop = ca_stop_utc(event_ticker)
        _tail = ""
        if _stop is not None:
            _tail = (f"; quoting stops {_stop.astimezone(ET).strftime('%b %d %H:%M ET')}"
                     f" (last {CA_LATE_STOP_DAYS:g} days of the month)")
        log(f"{self.tag} Carbon Arc late-month: {event_ticker} {_b} / {_a} "
            f"(inside {CA_LATE_DAYS:g}d of the measurement month's end){_tail}")

    # ---- lone-reference guard (2026-10-16, LONE_REF_GUARD_MODE) ------------

    def _lone_ref_check(self, t: str, meta, yes_levels, no_levels, own_in_book,
                        own, ref_bid_px: Optional[int], ref_ask_px: Optional[int],
                        now_ts: float, quiet: bool = False,
                        on: Optional[bool] = None) -> Tuple[bool, bool]:
        """(bid, ask): True for a side the lone-reference guard trips this
        cycle (LONE_REF_GUARD_MODE). The book is netted of `own_in_book`.
        The jump test reads `own`, our resting orders (live or simulated):
        each side's top price is kept as change points over the window
        (None = no rung). Logs each hold and clear once, unless `quiet` (a
        market only the bait-fingerprint stop watches); `on` = the caller
        stands the tripped side aside (default: LONE_REF_GUARD_MODE "on";
        True too in an event a bait stop guards)."""
        ext_yes, ext_no = external_levels(yes_levels, no_levels, own_in_book)
        win_start = now_ts - LONE_REF_JUMP_WINDOW_MIN * 60.0
        if on is None:
            on = LONE_REF_GUARD_MODE == "on"
        tag = ("" if LONE_REF_GUARD_MODE == "on" else " (bait-stop event)") if on \
            else " (dry)"
        out: List[bool] = []
        for side, ref_yes, ext in (("bid", ref_bid_px, ext_yes),
                                   ("ask", ref_ask_px, ext_no)):
            key = (t, side)
            own_px = (None if ref_yes is None
                      else ref_yes if side == "bid" else 100 - ref_yes)
            # where our rung rests now, before this cycle's requote (own
            # price space): the price a move to the reference jumps from
            mine = [int(px) if bs == "bid" else 100 - int(px)
                    for bs, px, _n in own if bs == side]
            cur = max(mine) if mine else None
            hist = self._lone_ref_rungs.setdefault(key, deque())
            if not hist or hist[-1][1] != cur:
                hist.append((now_ts, cur))
            # keep the change point in force at the window's start
            while len(hist) > 1 and hist[1][0] <= win_start:
                hist.popleft()
            window = ([p for _ts, p in hist if p is not None]
                      if LONE_REF_JUMP_WINDOW_MIN > 0 else None)
            if hist[-1][1] is None and hist[-1][0] <= win_start:
                del self._lone_ref_rungs[key]      # no rung all window
            trip = lone_ref_trip(levels_desc(ext), meta.target_size, own_px, window)
            if trip and key not in self._lone_ref_held:
                self._lone_ref_held.add(key)

                def yes(p: int, _side: str = side) -> int:
                    return p if _side == "bid" else 100 - p

                if trip["jump"] is None:
                    how = "; no rung there before"
                elif trip["jump"]:
                    how = (f"; our rung jumped {trip['jump']}c in "
                           f"{LONE_REF_JUMP_WINDOW_MIN}m")
                else:
                    how = ""
                if not quiet:
                    log(f"{self.tag} lone-ref guard{tag} {t} {side}: the reference "
                        f"{yes(trip['ref'])}c rests on {trip['top']:.0f} external "
                        f"contracts (< {LONE_REF_MAX_MULT:g} x "
                        f"{meta.target_size / 5.0:.0f}), the rest of the book's is "
                        f"{yes(trip['rest'])}c{how} -- "
                        + ("side stood aside" if on else "would stand aside"))
            elif not trip and key in self._lone_ref_held:
                self._lone_ref_held.discard(key)
                if not quiet:
                    log(f"{self.tag} lone-ref guard{tag} {t} {side}: clear")
            out.append(bool(trip))
        return out[0], out[1]

    # ---- bait-fingerprint stop (2026-10-22, BAIT_STOP_MODE) -----------------

    def bait_side_stopped(self, ticker: str, book_side: str, now_ts: float) -> bool:
        """True while a bait stop holds `book_side` of `ticker` out."""
        return BAIT_STOP_MODE == "on" and self.state.bait_side_until.get(
            self._toxic_key(ticker, book_side), 0.0) > now_ts

    def bait_event_guarded(self, event: str, now_ts: float) -> bool:
        """True while a bait stop runs the lone-ref guard ON in `event`."""
        return BAIT_STOP_MODE == "on" and \
            self.state.bait_event_until.get(event, 0.0) > now_ts

    def _bait_note_fill(self, f: dict, tkr: str, join, count: float,
                        now_ts: float) -> None:
        """Queue one of our fills for the bait-fingerprint tape check when it
        took the whole rung (the fills row's our_left_before, else
        our_remaining_before) on a side the lone-reference test flags right
        now. `join` = _log_fill's (book_side, our_px, remaining, left).
        Never raises."""
        try:
            if not join or f.get("is_taker") or not bait_series(series_of(tkr)):
                return
            book_side, our_px, rem, left = join
            whole = left if left is not None else rem
            if book_side not in ("bid", "ask") or our_px is None or whole is None \
                    or float(whole) <= 0 or count + 1e-6 < float(whole):
                return
            if (tkr, book_side) not in self._lone_ref_held or \
                    self._is_pad_price(book_side, our_px):
                return
            tid = str(f.get("trade_id") or f.get("fill_id") or "")
            if not tid or tid in self._bait_seen:
                return
            self._bait_seen[tid] = now_ts
            if len(self._bait_seen) > 2000:
                for k in [k for k, v in self._bait_seen.items() if v < now_ts - 86400]:
                    del self._bait_seen[k]
            fts = self._fill_ts(f)
            self._bait["candidates"] += 1
            self._bait_pending.append(dict(
                ticker=tkr, side=book_side, px=float(our_px), n=float(count),
                trade_id=tid, fill_ts=float(fts) if fts else now_ts, tries=0))
        except Exception as e:
            log(f"{self.tag} ! bait note failed: {e}")

    def _bait_check_pending(self, now_ts: float) -> None:
        """Read Kalshi's public tape for each queued fill BAIT_TAPE_DELAY_SECS
        after it and stop the side of every fingerprint (_bait_stop). A fill
        whose print is not on the tape yet, or whose read failed, is retried
        next cycle, BAIT_TAPE_MAX_TRIES times in all. Never raises."""
        if not self._bait_pending or self.client is None:
            return
        keep: List[dict] = []
        for c in self._bait_pending:
            if now_ts - c["fill_ts"] < BAIT_TAPE_DELAY_SECS:
                keep.append(c)
                continue
            fp: Optional[bool] = None
            try:
                self._bait["tape_reads"] += 1
                fp = bait_fingerprint(self._bait_read_tape(c["ticker"], int(c["fill_ts"])),
                                      c["trade_id"], c["n"])
                if fp is None:
                    self._bait["not_on_tape"] += 1
            except Exception as e:
                self._bait["tape_fails"] += 1
                if self._bait["tape_fails"] <= 3:
                    log(f"{self.tag} ! bait tape read failed for {c['ticker']}: {e}")
            if fp is None:
                c["tries"] += 1
                if c["tries"] < BAIT_TAPE_MAX_TRIES:
                    keep.append(c)
                continue
            if not fp:
                self._bait["bigger_taker"] += 1
                continue
            self._bait["fingerprints"] += 1
            self._bait_stop(c, now_ts)
        self._bait_pending = keep

    def _bait_read_tape(self, ticker: str, ts: int) -> List[dict]:
        """Kalshi's public prints on `ticker` 3s either side of `ts`, one
        signed read. Not the client's get_trades: that sends `ticker` twice,
        which Kalshi rejects ("multiple values for single value parameter")."""
        js = self.client.get("/markets/trades", params={
            "ticker": ticker, "min_ts": ts - 3, "max_ts": ts + 3, "limit": 200})
        return (js or {}).get("trades") or []

    def _bait_stop(self, c: dict, now_ts: float) -> None:
        """A fingerprint: the side out until ET midnight and the event's
        lone-ref guard ON until then ("on"), or only logged ("dry"). Sinks
        one bait_stops row either way."""
        t, side = c["ticker"], c["side"]
        ev = self._event_of(t)
        until = et_day_end_ts(now_ts)
        live = BAIT_STOP_MODE == "on"
        if live:
            self.state.bait_side_until[self._toxic_key(t, side)] = until
            self.state.bait_event_until[ev] = max(
                until, self.state.bait_event_until.get(ev, 0.0))
            self._bait["stops"] += 1
        self._bait["last"] = dict(ts=round(now_ts, 1), ticker=t, side=side,
                                  px=c["px"], n=c["n"])
        self._sink("bait_stops", {
            "ts": round(now_ts, 3), "mode": BAIT_STOP_MODE, "ticker": t,
            "event": ev, "side": side, "px": c["px"], "count": c["n"],
            "trade_id": c["trade_id"], "fill_ts": c["fill_ts"], "until": until})
        log(f"{self.tag} bait stop{'' if live else ' (dry)'}: {t} {side.upper()} "
            f"@ {c['px']:g}c -- a taker of exactly our {c['n']:g} took the whole "
            f"rung on a lone top our rung had jumped to; "
            + (f"that side out until 00:00 ET, and the lone-ref guard ON for "
               f"{ev} until then" if live else
               "would stand that side aside until 00:00 ET (dry)"))
        if live:
            self._save_persist()

    # ---- join ahead of the pile (2026-10-11, JOIN_AHEAD_MODE) --------------

    def _refresh_comp_pairs(self, metas: List["MarketMeta"], now_ts: float) -> None:
        """Group the markets of every mutually exclusive event in the
        complement-lead scope (COMP_LEAD_MODE) from Kalshi's event record:
        an event with two or more candidates is read when unread or older than
        COMP_PAIR_TTL_SECS, at most COMP_PAIR_READS_PER_REFRESH a refresh. A
        group is EVERY market of the event (siblings outside the programs
        too), and only while all of them are open; a failed read leaves the
        event ungrouped until the next try. Never raises."""
        by_ev: Dict[str, Set[str]] = {}
        for m in metas:
            if comp_lead_series(m.series):
                by_ev.setdefault(m.event_ticker, set()).add(m.ticker)
        reads = 0
        for ev in sorted(by_ev):
            cands = by_ev[ev]
            if len(cands) < 2:
                continue
            hit = self._comp_events.get(ev)
            if hit is not None and now_ts - hit[0] < COMP_PAIR_TTL_SECS:
                continue
            if reads >= COMP_PAIR_READS_PER_REFRESH:
                break
            reads += 1
            try:
                js = self.client.get(f"/events/{ev}",
                                     params={"with_nested_markets": "true"}) or {}
            except Exception as e:
                if not getattr(self, "_comp_read_err_logged", False):
                    self._comp_read_err_logged = True
                    log(f"{self.tag} ! comp lead: event read {ev} failed ({e!r}); "
                        f"retried in 10 min, keeping what it had (logged once)")
                # retried in 10 minutes; a group it had stands meanwhile
                self._comp_events[ev] = (now_ts - COMP_PAIR_TTL_SECS + 600.0,
                                         hit[1] if hit is not None else None)
                continue
            e = js.get("event") or {}
            mk = e.get("markets") or js.get("markets") or []
            tickers = tuple(sorted(str(x.get("ticker") or "") for x in mk))
            open_ = all(str(x.get("status") or "").lower() in ("active", "open")
                        for x in mk)
            me = bool(e.get("mutually_exclusive"))
            ok = me and len(tickers) >= 2 and cands <= set(tickers) and open_
            self._comp_events[ev] = (now_ts, tickers if ok else None)
            # ...or a threshold ladder: every strike open, one underlying
            lad = None if me or not open_ or not cands <= set(tickers) else ladder_order(mk)
            self._ladder_events[ev] = lad
        groups: Dict[str, Tuple[str, ...]] = {}
        for _ev, (_at, grp) in self._comp_events.items():
            if grp is not None:
                for t in grp:
                    groups[t] = grp
        pairs = {t: (g[1] if g[0] == t else g[0]) for t, g in groups.items()
                 if len(g) == 2}
        ladders = {t: lad for lad in self._ladder_events.values() if lad for t in lad}
        if set(groups) != set(self._comp_groups) or set(ladders) != set(self._ladders):
            n_ev = len({g for g in groups.values()})
            n_lad = len({g for g in ladders.values()})
            log(f"{self.tag} comp lead: {n_ev} mutually exclusive event(s) grouped, "
                f"{len(pairs) // 2} of them two-market ({reads} event read(s) "
                f"this refresh); {n_lad} threshold ladder(s)")
        self._comp_groups = groups
        self._comp_pairs = pairs
        self._ladders = ladders

    def _comp_linked(self, t: str) -> bool:
        """Does another market's book price `t` (a mutually exclusive group
        or a threshold ladder)?"""
        return t in self._comp_groups or t in self._ladders

    def _lead_source(self, meta) -> Optional[str]:
        """Where `meta`'s leads would come from: "comp" (other markets' books:
        the complement lead), "fair" (its fresh model fair: FAIR LEAD) or
        None. Each mode's own switch applies (lead_mode)."""
        if self._comp_linked(meta.ticker) and comp_lead_series(meta.series):
            return "comp"
        if fair_lead_fair_c(meta.ticker, meta.series, time.time()) is not None:
            return "fair"
        return None

    def _comp_books(self, tickers) -> List[Tuple[str, List[List[float]], List[List[float]]]]:
        """Each of `tickers`' EXTERNAL books on the WS feed, as (ticker, YES
        levels, NO levels); a market off the feed is left out."""
        ws = self._ws
        out = []
        for s in tickers:
            try:
                ob = ws.book_fp(s) if ws is not None else None
            except Exception:
                ob = None
            if ob is None:
                continue
            sy, sn = orderbook_levels(ob)
            own_s = self._comp_own.get(s, []) if self.live else []
            if own_s:
                sy, sn = external_levels(sy, sn, own_s)
            out.append((s, sy, sn))
        return out

    def _comp_sib_books(self, t: str
                        ) -> Optional[List[Tuple[str, List[List[float]], List[List[float]]]]]:
        """Each of `t`'s siblings' EXTERNAL book from the WS feed, as
        (ticker, YES levels, NO levels); None when `t` has no group or any
        sibling's book is off the feed."""
        grp = self._comp_groups.get(t)
        ws = self._ws
        if not grp or ws is None:
            return None
        out = []
        for s in grp:
            if s == t:
                continue
            try:
                ob = ws.book_fp(s)
            except Exception:
                ob = None
            if ob is None:
                return None
            sy, sn = orderbook_levels(ob)
            own_s = self._comp_own.get(s, []) if self.live else []
            if own_s:
                sy, sn = external_levels(sy, sn, own_s)
            out.append((s, sy, sn))
        return out or None

    def _comp_lead(self, meta, yes_ext: List[List[float]], no_ext: List[List[float]]
                   ) -> Tuple[Optional[Tuple[int, int, int]],
                              Optional[Tuple[int, int, int]]]:
        """This market's (bid lead, ask lead) off its siblings' WS books
        (comp_lead_group; `yes_ext` / `no_ext` = its own EXTERNAL book):
        (None, None) without a group, outside the scope, on a sub-penny book
        or when the feed cannot serve every sibling's book. A threshold
        ladder's strike leads off the other strikes' books (ladder_lead_group;
        a strike off the feed is left out). A market no other book prices
        leads off its fresh model fair (fair_lead_group, FAIR LEAD)."""
        t = meta.ticker
        src = self._lead_source(meta)
        if src is None or meta.price_step < 0.01:
            return None, None
        # where its sides lead now, else where they last led (COMP_HOLD_FILE):
        # a leading side never moves up
        held = self._comp_lead_px.get(t)
        if held is None:
            h = self._comp_holds.get(t)
            if h is not None and time.time() - float(h[2]) < COMP_HOLD_TTL_SECS:
                held = (h[0], h[1], 0)
        held = held or (None, None, 0)
        if src == "fair":
            fair_c = fair_lead_fair_c(t, meta.series, time.time())
            if fair_c is None:
                return None, None
            self._fair_gap_note(t, yes_ext, no_ext, fair_c)
            return fair_lead_group(yes_ext, no_ext, fair_c,
                                   meta.target_size, meta.discount_factor,
                                   hold_bid=held[0], hold_ask=held[1])
        if t not in self._comp_groups:
            lad = self._ladders[t]
            i = lad.index(t)
            easier = [(sy, sn) for _s, sy, sn in self._comp_books(lad[:i])]
            harder = [(sy, sn) for _s, sy, sn in self._comp_books(lad[i + 1:])]
            return ladder_lead_group(yes_ext, no_ext, easier, harder,
                                     meta.target_size, meta.discount_factor,
                                     hold_bid=held[0], hold_ask=held[1])
        sibs = self._comp_sib_books(t)
        if sibs is None:
            return None, None
        return comp_lead_group(yes_ext, no_ext, [(sy, sn) for _s, sy, sn in sibs],
                               meta.target_size, meta.discount_factor,
                               hold_bid=held[0], hold_ask=held[1],
                               bid_ok=comp_bid_lead_series(meta.series))

    def _load_comp_holds(self) -> Dict[str, list]:
        """COMP_HOLD_FILE's entries ({} when absent or unreadable)."""
        try:
            with open(os.path.join(STATUS_DIR, COMP_HOLD_FILE), encoding="utf-8") as f:
                d = json.load(f)
            return {str(k): list(v) for k, v in (d.get("holds") or {}).items()
                    if isinstance(v, list) and len(v) == 3}
        except (OSError, ValueError, AttributeError):
            return {}

    def _note_comp_hold(self, t: str, bid: Optional[int], ask: Optional[int],
                        now_ts: float) -> None:
        """Remember where `t`'s sides lead (COMP_HOLD_FILE): written when it
        changes, lapsed entries dropped. Never raises."""
        old = self._comp_holds.get(t)
        if old is not None and old[0] == bid and old[1] == ask:
            return
        self._comp_holds[t] = [bid, ask, now_ts]
        self._comp_holds = {k: v for k, v in self._comp_holds.items()
                            if now_ts - float(v[2]) < COMP_HOLD_TTL_SECS}
        path = os.path.join(STATUS_DIR, COMP_HOLD_FILE)
        try:
            with open(path + ".tmp", "w", encoding="utf-8") as f:
                json.dump({"updated": datetime.now(timezone.utc).isoformat(),
                           "holds": self._comp_holds}, f, indent=1, sort_keys=True)
            os.replace(path + ".tmp", path)
        except OSError as e:
            if not getattr(self, "_comp_hold_err_logged", False):
                self._comp_hold_err_logged = True
                log(f"{self.tag} ! {COMP_HOLD_FILE} write failed ({e}); the "
                    f"holds stay in memory (logged once)")

    def _comp_lead_note(self, t: str, lead_b, lead_a, n: int,
                        src: str = "comp") -> None:
        """Log each side's complement lead -- or, `src` "fair", its fair lead
        -- when it starts, stops or moves 3c or more (the mode's dry says
        so)."""
        dry = "" if lead_mode(src) == "on" else " (dry)"
        kind, margin = ("fair", FAIR_LEAD_MARGIN_C) if src == "fair" \
            else ("comp", COMP_LEAD_MARGIN_C)
        grp = self._comp_groups.get(t) or ()
        who, verb = ((f"{self._comp_pairs[t]}'s book", "implies") if t in self._comp_pairs
                     else (f"its {max(len(grp) - 1, 0)} siblings' books", "imply"))
        if src == "fair":
            who, verb = (("the weekend rain fair" if rain_wknd_series(series_of(t))
                          else "its model fair"), "implies")
        for side, lead in (("bid", lead_b), ("ask", lead_a)):
            if src != "fair" and not grp and t in self._ladders:
                who, verb = (("its harder strikes' books", "imply") if side == "bid"
                             else ("its easier strikes' books", "imply"))
            key = (t, side)
            px = None if lead is None else lead[0]
            prev = self._comp_lead_noted.get(key)
            if px == prev or (px is not None and prev is not None
                              and abs(px - prev) < 3):
                continue
            self._comp_lead_noted[key] = px
            if px is None:
                log(f"{self.tag} {kind} lead{dry} {t} {side}: off -- {who} no longer "
                    f"put{'s' if src == 'fair' else ''} it ahead of its own, or "
                    f"an order stepped ahead of it")
                continue
            _p, cap, best = lead
            implied = cap + margin if side == "bid" else cap - margin
            ahead = (px > best) if side == "bid" else (px < best)
            where = (f"ahead of its own {best}c" if ahead else
                     f"held at the cap, {'with' if px == best else 'behind'} its own "
                     f"{best}c")
            log(f"{self.tag} {kind} lead{dry} {t} {side}: {n} @ {px}c, {where}; "
                f"{who} {verb} {implied}c")

    def _fair_gap_note(self, t: str, yes_ext: List[List[float]],
                       no_ext: List[List[float]], fair_c: float) -> None:
        """Log the disagreement guard (FAIR_LEAD_MAX_GAP_C) when it starts or
        stops holding `t`'s fair leads back."""
        if not FAIR_LEAD_MAX_GAP_C:
            return
        eb, ea = external_best(yes_ext, no_ext)
        held = any(fair_gate_breach(eb, ea, fair_c, FAIR_LEAD_MAX_GAP_C))
        if held == self._fair_gap_held.get(t, False):
            return
        self._fair_gap_held[t] = held
        dry = "" if lead_mode("fair") == "on" else " (dry)"
        if held:
            log(f"{self.tag} fair lead guard{dry} {t}: book {eb}x{ea} sits more than "
                f"{FAIR_LEAD_MAX_GAP_C}c past the {fair_c:.1f}c fair -- no lead until "
                f"it is back inside")
        else:
            log(f"{self.tag} fair lead guard{dry} {t}: book {eb}x{ea} back within "
                f"{FAIR_LEAD_MAX_GAP_C}c of the {fair_c:.1f}c fair -- leads allowed")

    def _fair_close_note(self, t: str, close_b, close_a, pos: float, fair_c: float,
                         yes_ext: List[List[float]], no_ext: List[List[float]],
                         avg_c: Optional[float] = None) -> None:
        """Log the closing rung (FAIR CLOSE) when it starts, stops or moves 3c
        or more (dry says so)."""
        dry = "" if FAIR_CLOSE_MODE == "on" else " (dry)"
        side, rung = ("bid", close_b) if pos < 0 else ("ask", close_a)
        key = (t, side)
        px = None if rung is None else rung[0]
        prev = self._fair_close_noted.get(key)
        if px == prev or (px is not None and prev is not None and abs(px - prev) < 3):
            return
        self._fair_close_noted[key] = px
        what = f"a short of {-pos:g}" if pos < 0 else f"a long of {pos:g}"
        eb, ea = external_best(yes_ext, no_ext)
        if rung is None:
            log(f"{self.tag} fair close{dry} {t} {side}: off -- the side already rests "
                f"as near the {fair_c:.1f}c fair, or that price would cross or not "
                f"earn (book {eb}x{ea}); {what} rests at the side's own price")
            return
        model = int(math.floor(fair_c)) if pos < 0 else int(math.ceil(fair_c))
        past = (px - model) if pos < 0 else (model - px)
        extra = (f", {past}c past the model for a larger reward share, still "
                 f"{(avg_c - px) if pos < 0 else (px - avg_c):+.1f}c a contract over "
                 f"the {avg_c:.1f}c entry" if past > 0 and avg_c is not None else "")
        log(f"{self.tag} fair close{dry} {t} {side}: {rung[1]} @ {px}c, closing {what} "
            f"at the weekend rain fair's {fair_c:.1f}c (book {eb}x{ea}){extra}")

    # ---- COMPLEMENT HEDGE (COMP_HEDGE_MODE) ---------------------------------

    def _load_comp_hedges(self) -> List[dict]:
        """COMP_HEDGE_FILE's open jobs ([] when absent or unreadable)."""
        try:
            with open(os.path.join(STATUS_DIR, COMP_HEDGE_FILE), encoding="utf-8") as f:
                d = json.load(f)
            return [j for j in (d.get("jobs") or []) if isinstance(j, dict)
                    and isinstance(j.get("legs"), dict)]
        except (OSError, ValueError, AttributeError):
            return []

    def _save_comp_hedges(self) -> None:
        """Write the open jobs (COMP_HEDGE_FILE). Never raises."""
        path = os.path.join(STATUS_DIR, COMP_HEDGE_FILE)
        try:
            with open(path + ".tmp", "w", encoding="utf-8") as f:
                json.dump({"updated": datetime.now(timezone.utc).isoformat(),
                           "jobs": self._comp_hedges}, f, indent=1, sort_keys=True)
            os.replace(path + ".tmp", path)
        except OSError as e:
            if not getattr(self, "_comp_hedge_err_logged", False):
                self._comp_hedge_err_logged = True
                log(f"{self.tag} ! {COMP_HEDGE_FILE} write failed ({e}); the "
                    f"jobs stay in memory (logged once)")

    def _lock_kind(self, t: str, side: str) -> Optional[Tuple[str, Tuple[str, ...]]]:
        """(lock_plan kind, its leg markets) for one of OUR fills on `t`'s
        `side` ("bid": we bought YES, "ask": we sold it), or None: in a
        mutually exclusive event a sale locks on the siblings, a buy only in
        a two-market election pair (on the twin); on a threshold ladder a
        sale locks on the easier strikes, a buy on the harder ones."""
        grp = self._comp_groups.get(t)
        if grp:
            sibs = tuple(s for s in grp if s != t)
            if side == "ask":
                return "me_ask", sibs
            if len(grp) == 2 and comp_bid_lead_series(series_of(t)):
                return "pair_bid", sibs
            return None
        lad = self._ladders.get(t)
        if lad and t in lad:
            i = lad.index(t)
            if side == "ask" and i > 0:
                return "ladder_ask", lad[:i]
            if side == "bid" and i < len(lad) - 1:
                return "ladder_bid", lad[i + 1:]
        return None

    def _comp_hedge_on_fill(self, f: dict, tkr: str, side: str, action: str,
                            count: float, px_cents: float, now_ts: float,
                            pos_before: Optional[float] = None,
                            pos_after: Optional[float] = None) -> None:
        """One of OUR fills: a hedge leg's credits its job; a maker fill that
        opens or adds to a position (pos_before -> pos_after; unknown: the
        whole fill) opens a lock job (_lock_kind) for what it opened -- a
        lead's fill (at the price its side leads at now, led at in the last
        10 minutes, or last led at) under COMP_HEDGE_MODE for up to
        COMP_HEDGE_MAX_AGE_SECS, any other under LOCK_MODE for
        LOCK_WATCH_SECS. Never raises."""
        try:
            oid = str(f.get("order_id") or "")
            for j in self._comp_hedges:
                lg = j["legs"].get(tkr)
                if lg is not None and oid and oid in lg.get("oids", ()):
                    lg["filled"] = float(lg.get("filled", 0.0)) + count
                    lg["value"] = float(lg.get("value", 0.0)) + count * px_cents
                    lg["fee"] = float(lg.get("fee", 0.0)) + taker_fee_cents(
                        px_cents, count, LOCK_MAKER_FEE_MULT)
                    self._sink("comp_hedge", {
                        "ts": datetime.now(timezone.utc).isoformat(),
                        "kind": "leg_fill", "job": j["id"], "ticker": tkr,
                        "count": count, "px": px_cents, "order_id": oid})
                    self._save_comp_hedges()
                    return
            if f.get("is_taker"):
                return
            book_side = "bid" if (side == "yes") == (action == "buy") else "ask"
            # only what the fill opened is locked: one that cuts a position
            # realizes it instead
            if pos_before is None or pos_after is None:
                opened = count
            elif book_side == "ask":
                opened = max(0.0, -pos_after) - max(0.0, -pos_before)
            else:
                opened = max(0.0, pos_after) - max(0.0, pos_before)
            n = math.floor(opened + 1e-9)
            if n < 1:
                return
            i = 0 if book_side == "bid" else 1
            lead = self._comp_lead_px.get(tkr)
            # the side's lead price now, any it led at in the last 10 minutes
            # (the rung may have moved since it filled), or where it last led
            prices = set(p_ for p_, at in self._comp_lead_seen.get((tkr, book_side), {}).items()
                         if now_ts - at <= 600.0)
            if lead is not None and lead[i] is not None:
                prices.add(lead[i])
            h = self._comp_holds.get(tkr)
            if h is not None and h[i] is not None:
                prices.add(h[i])
            on_lead = any(abs(px_cents - float(p_)) <= 0.5 for p_ in prices)
            mode = COMP_HEDGE_MODE if on_lead else LOCK_MODE
            if mode not in ("on", "dry"):
                return
            lk = self._lock_kind(tkr, book_side)
            # a lead's fill booked before the groups are read (the startup
            # reconcile) waits for its group; any other needs one now -- and a
            # FAIR lead's has none to wait for (its family is never grouped)
            if lk is None and (not on_lead or self._comp_linked(tkr)
                               or series_of(tkr) in FAIR_LEAD_SERIES):
                return
            job = {"id": f"{tkr}-{book_side}-{oid[:8] or 'x'}-{int(now_ts)}",
                   "event": "-".join(tkr.split("-")[:-1]) or tkr,
                   "ticker": tkr, "side": book_side, "kind": lk[0] if lk else None,
                   "lead": on_lead, "mode": mode, "price": float(px_cents),
                   "count": float(n), "at": now_ts,
                   "until": now_ts + (COMP_HEDGE_MAX_AGE_SECS if on_lead else LOCK_WATCH_SECS),
                   "tries": 0, "legs": {}, "best": None}
            if lk is None:
                job["need_group"] = True
            self._comp_hedges.append(job)
            self._save_comp_hedges()
            if on_lead:
                log(f"{self.tag} comp hedge: {tkr} {book_side.upper()} filled {n:g} @ "
                    f"{px_cents:g}c on its lead -- will lock it on "
                    + (f"{len(lk[1])} {'sibling' if lk[0] in ('me_ask', 'pair_bid') else 'strike'}(s)"
                       if lk else "its siblings once its group is read")
                    + (" (dry)" if mode != "on" else ""))
            self._sink("comp_hedge", {
                "ts": datetime.now(timezone.utc).isoformat(), "kind": "open",
                "job": job["id"], "ticker": tkr, "side": book_side, "lock": job["kind"],
                "lead": on_lead, "count": float(n), "px": px_cents,
                "legs": list(lk[1]) if lk else []})
        except Exception as e:
            log(f"{self.tag} ! comp hedge fill note failed ({type(e).__name__}: {e})")

    def _lock_leg_fill(self, oid: str) -> bool:
        """Is `oid` one of an open lock job's legs?"""
        return bool(oid) and any(oid in lg.get("oids", ())
                                 for j in self._comp_hedges
                                 for lg in j["legs"].values())

    def _lock_maker_px(self, s: str, sell: bool) -> Optional[int]:
        """The most aggressive price a lock leg on `s` RESTS at: a sale 1c over
        its best YES bid, a buy 1c under its best YES offer -- on the WHOLE
        book, our own orders in it, so a leg never crosses one of ours -- or
        None off the feed or out of 1-99c."""
        try:
            ob = self._ws.book_fp(s) if self._ws is not None else None
        except Exception:
            ob = None
        if ob is None:
            return None
        yes, no = orderbook_levels(ob)
        if sell:
            best = max((px for px, q in yes if q > 0), default=0.0)
            px = int(math.floor(best + 1e-9)) + 1
        else:
            best_no = max((px for px, q in no if q > 0), default=0.0)
            px = int(math.ceil(100.0 - best_no - 1e-9)) - 1
        return px if 1 <= px <= 99 else None

    def _lock_cancel(self, oid: str, ticker: str, why: str) -> None:
        """Cancel one resting lock leg, routed by its market (an order on
        another shard 404s on shard 0). Never raises."""
        if not oid or oid in self._lock_cancelled:
            return
        now = time.time()
        self._lock_cancelled[oid] = now
        if len(self._lock_cancelled) > 2000:
            self._lock_cancelled = {k: v for k, v in self._lock_cancelled.items()
                                    if now - v < 6 * 3600}
        if not self.live:
            log(f"{self.tag} [DRY] comp hedge cancel {ticker} {oid} ({why})")
            return
        try:
            if ticker:
                self.client.cancel_order(oid, exchange_index=-1, market_ticker=ticker)
            else:
                self.client.cancel_order(oid)
            log(f"{self.tag} comp hedge cancel {ticker} {oid} ({why})")
            self._sink("comp_hedge", {"ts": datetime.now(timezone.utc).isoformat(),
                                      "kind": "cancel", "ticker": ticker,
                                      "order_id": oid, "why": why})
        except HttpError as e:
            if e.status not in (404, 409):           # 404/409: already gone
                self._lock_cancelled.pop(oid, None)
                log(f"{self.tag} ! comp hedge cancel failed {oid}: {e}")
        except Exception as e:
            self._lock_cancelled.pop(oid, None)
            log(f"{self.tag} ! comp hedge cancel failed {oid}: {e}")

    def _comp_hedge_run(self, now_ts: float) -> None:
        """Work the open lock jobs with resting MAKER legs (Jack 2026-10-29:
        "Don't be a taker, only maker"). A job with no leg working is priced
        on its leg markets at the prices a leg rests at (_lock_maker_px) and,
        when lock_plan clears the edge there, rests those legs; their fills
        count toward its floor, and once the floor clears the edge the legs
        left are cancelled. A job none of whose legs has filled locks only
        what its market still holds (the oldest job first; legs resting for
        more are cancelled and priced again) and ends when the bot has
        unwound it or its watch (`until`) runs out; one with fills works until
        it locks or COMP_HEDGE_MAX_AGE_SECS. A leg is working while the last
        exchange read shows it resting, or for 60s after it was sent; resting
        legs no open job owns are cancelled. Locked, lapsed and dry jobs are
        logged and dropped. Never raises."""
        resting = self._lock_resting       # the last cycle's read; None: none yet
        changed = False
        keep: List[dict] = []
        owned: Set[str] = set()
        held_left: Dict[Tuple[str, str], float] = {}
        for j in sorted(self._comp_hedges, key=lambda x: float(x.get("at", 0.0))):
            try:
                t, side, p = j["ticker"], j["side"], float(j["price"])
                # (a job saved before the every-fill locks is a lead's)
                lead = j.get("lead", True) is not False
                if not j.get("kind"):
                    # a pre-lock job (side only) or one waiting for its group
                    lk = self._lock_kind(t, side)
                    if lk is not None:
                        j["kind"], j["need_group"] = lk[0], False
                        changed = True
                kind = j.get("kind")
                lk = self._lock_kind(t, side) if kind else None
                leg_tickers = lk[1] if (lk and lk[0] == kind) else tuple(j["legs"])
                legs = j["legs"]
                q = float(j["count"])
                done = {s: (float(lg.get("filled", 0.0)), float(lg.get("value", 0.0)),
                            float(lg.get("fee", 0.0)))
                        for s, lg in legs.items() if float(lg.get("filled", 0.0)) > 0}
                working = {s: lg for s, lg in legs.items()
                           if lg.get("oid") and lg["oid"] not in self._lock_cancelled
                           and (resting is None or lg["oid"] in resting
                                or now_ts - float(lg.get("sent_at", 0.0)) < 60.0)}

                def end_legs(why: str) -> None:
                    for s_, lg_ in working.items():
                        self._lock_cancel(lg_["oid"], s_, why)
                        lg_["oid"] = None

                age = now_ts - float(j.get("at", now_ts))
                edge = COMP_HEDGE_LEAD_EDGE_C if lead else COMP_HEDGE_EDGE_C
                if kind and done:
                    f_done, _pl = lock_plan(kind, p, q, {}, done, edge_c=edge)
                    if f_done >= edge - 1e-9:
                        end_legs("locked")
                        what = ", ".join(f"{s} {d[0]:g}" for s, d in sorted(done.items()))
                        log(f"{self.tag} comp hedge: {t} {side} {q:g} @ {p:g}c locked "
                            f"{f_done:+.1f}c a contract ({kind}: {what})")
                        self._sink("comp_hedge", {
                            "ts": datetime.now(timezone.utc).isoformat(), "kind": "done",
                            "job": j["id"], "ticker": t, "lock": kind,
                            "lead": lead, "edge_c": round(f_done, 2),
                            "count": q, "legs": {s: d[0] for s, d in done.items()}})
                        if lead:
                            self.alerter.alert(
                                "comp_hedge", f"{t}: lead {side} filled {q:g} @ {p:g}c, "
                                f"locked {f_done:+.1f}c a contract on {len(done)} market(s)",
                                key=j["id"], urgent=False)
                        changed = True
                        continue
                if not done and now_ts > float(j.get("until", float(j.get("at", now_ts))
                                                    + COMP_HEDGE_MAX_AGE_SECS)):
                    # its watch is over with nothing filled: ordinary inventory
                    end_legs("watch_over")
                    self._sink("comp_hedge", {
                        "ts": datetime.now(timezone.utc).isoformat(), "kind": "nolock",
                        "job": j["id"], "ticker": t, "lock": kind,
                        "lead": lead, "count": q, "best_c": j.get("best")})
                    if lead:
                        log(f"{self.tag} ! comp hedge: {j['id']} gave up after "
                            f"{COMP_HEDGE_MAX_AGE_SECS / 3600:g}h without a lock (best "
                            f"{j.get('best')}c a contract)")
                        self.alerter.alert(
                            "comp_hedge", f"{t}: lead fill {q:g} @ {p:g}c never locked "
                            f"in {COMP_HEDGE_MAX_AGE_SECS / 3600:g}h", key=j["id"], urgent=True)
                    changed = True
                    continue
                if done and age > COMP_HEDGE_MAX_AGE_SECS:
                    end_legs("gave_up")
                    log(f"{self.tag} ! comp hedge: {j['id']} gave up after "
                        f"{COMP_HEDGE_MAX_AGE_SECS / 3600:g}h with legs "
                        + ", ".join(f"{s} {d[0]:g}" for s, d in sorted(done.items()))
                        + " filled and no lock")
                    self._sink("comp_hedge", {
                        "ts": datetime.now(timezone.utc).isoformat(), "kind": "expired",
                        "job": j["id"], "ticker": t, "lock": kind,
                        "legs": {s: d[0] for s, d in done.items()}})
                    self.alerter.alert(
                        "comp_hedge", f"{t}: lock gave up with legs "
                        + ", ".join(f"{s} {d[0]:g}" for s, d in sorted(done.items()))
                        + " filled", key=j["id"], urgent=True)
                    changed = True
                    continue
                keep.append(j)
                owned |= {lg["oid"] for lg in working.values()}
                if not kind or (resting is None and self.live):
                    continue
                if not done:
                    # what the market still holds this way, oldest job first
                    pos = self.pnl.pos.get(t, 0.0)
                    left = held_left.setdefault(
                        (t, side), max(0.0, -pos) if side == "ask" else max(0.0, pos))
                    cnt = float(min(q, math.floor(left + 1e-9)))
                    held_left[(t, side)] = left - cnt
                    if cnt < 1:
                        end_legs("unwound")
                        self._sink("comp_hedge", {
                            "ts": datetime.now(timezone.utc).isoformat(),
                            "kind": "unwound", "job": j["id"], "ticker": t, "count": q})
                        keep.remove(j)
                        changed = True
                        continue
                    if cnt < q:
                        end_legs("resized")      # priced again for what is held
                        owned -= {lg.get("oid") for lg in working.values()}
                        working = {}
                        j["count"] = q = cnt
                        changed = True
                if working:
                    continue                     # legs working: wait for their fills
                # price the plan where each leg would rest
                sell = LOCK_KINDS[kind][0]
                books: Dict[str, List[Tuple[int, float]]] = {}
                for s in leg_tickers:
                    px = self._lock_maker_px(s, sell)
                    if px is not None:
                        books[s] = [(px, q)]
                floor, plan = lock_plan(kind, p, q, books, done, edge_c=edge,
                                        fee_mult=LOCK_MAKER_FEE_MULT)
                if j.get("best") is None or floor > float(j["best"]) + 0.05:
                    j["best"] = round(floor, 2)
                if not plan:
                    if not j.get("waiting"):
                        j["waiting"] = True
                        changed = True
                        if lead:
                            log(f"{self.tag} comp hedge: {j['id']} waits -- the books now "
                                f"leave {floor:+.1f}c a contract, under {edge:g}c")
                    continue
                j["waiting"] = False
                j["tries"] = int(j.get("tries", 0)) + 1
                leg_side = "ask" if sell else "bid"
                what = ", ".join(f"{s} {n} @ {px}c" for s, (px, n) in sorted(plan.items()))
                if (j.get("mode") or COMP_HEDGE_MODE) != "on":
                    # dry: the legs it would rest, once, and the job is dropped
                    for s, (px, n) in plan.items():
                        legs.setdefault(s, {"filled": 0.0, "value": 0.0, "fee": 0.0,
                                            "oids": [], "sent_at": 0.0})
                        self._comp_hedge_send(s, leg_side, px, n, j, now_ts)
                    log(f"{self.tag} comp hedge (dry): {j['id']} would rest legs for "
                        f"{floor:+.1f}c a contract ({kind}: {what}); dropped")
                    keep.remove(j)
                    changed = True
                    continue
                log(f"{self.tag} comp hedge: {t} {side} {q:g} @ {p:g}c -- resting maker legs "
                    f"for {floor:+.1f}c a contract ({kind}: {what})")
                for s, (px, n) in plan.items():
                    lg = legs.setdefault(s, {"filled": 0.0, "value": 0.0, "fee": 0.0,
                                             "oids": [], "sent_at": 0.0})
                    oid = self._comp_hedge_send(s, leg_side, px, n, j, now_ts)
                    # a refused leg (short cash on the shard, say) waits 10
                    # minutes, not one
                    lg["sent_at"] = now_ts if (oid or not self.live) else now_ts + 540.0
                    lg["oid"] = oid
                    if oid:
                        lg.setdefault("oids", []).append(oid)
                        owned.add(oid)
                changed = True
            except Exception as e:
                keep.append(j)
                log(f"{self.tag} ! comp hedge job {j.get('id')} failed "
                    f"({type(e).__name__}: {e}); kept")
        # a resting leg no open job owns (its job ended, or a past run's)
        for oid, o in (resting or {}).items():
            if oid not in owned:
                self._lock_cancel(oid, str(o.get("ticker") or ""), "orphan")
        if self._comp_hedges or keep:
            self._comp_hedges = keep
            if changed:
                self._save_comp_hedges()

    def _comp_hedge_send(self, ticker: str, book_side: str, px: int, count: int,
                         job: dict, now_ts: float) -> Optional[str]:
        """Rest one lock leg: a post-only limit order -- never a taker (Jack
        2026-10-29: "Don't be a taker, only maker") -- to buy (bid) or sell
        (ask) `count` YES at `px`, for LOCK_LEG_TTL_SECS at most (its job's
        watch and the market's cutoff bound it too). Its fills are ours. A job
        in dry mode only logs; a dry run credits the leg in full. Returns the
        order id."""
        what = "buy" if book_side == "bid" else "sell"
        label = f"{ticker} {what} {count} YES @ {px}c (maker)"
        row = {"ts": datetime.now(timezone.utc).isoformat(), "kind": "send",
               "job": job["id"], "ticker": ticker, "side": book_side,
               "px": px, "count": count}
        live_mode = (job.get("mode") or COMP_HEDGE_MODE) == "on"
        if not live_mode or not self.live:
            log(f"{self.tag} [DRY] comp hedge {label}")
            self._sink("comp_hedge", dict(row, dry=True))
            if not self.live and live_mode:
                leg = job["legs"][ticker]
                leg["filled"] = float(leg.get("filled", 0.0)) + count
                leg["value"] = float(leg.get("value", 0.0)) + count * px
                leg["fee"] = float(leg.get("fee", 0.0)) + taker_fee_cents(
                    px, count, LOCK_MAKER_FEE_MULT)
            return None
        expiration_ts = int(min(now_ts + LOCK_LEG_TTL_SECS,
                                float(job.get("until") or now_ts + LOCK_LEG_TTL_SECS)))
        cutoff_ts = self.state.cutoff_ts.get(ticker)
        if cutoff_ts is not None:
            expiration_ts = min(expiration_ts, int(cutoff_ts))
        if expiration_ts <= now_ts + 5:
            log(f"{self.tag} comp hedge: not resting {label}: its job or the market's "
                f"cutoff ends first")
            return None
        client_order_id = f"{CLIENT_ORDER_PREFIX}-{RUN_ID}-h{uuid.uuid4().hex[:11]}"
        if book_side == "bid":
            kwargs = dict(side="yes", action="buy", yes_price=px)
        else:
            kwargs = dict(side="no", action="buy", no_price=100 - px)
        try:
            resp = self.client.create_order(
                ticker=ticker, client_order_id=client_order_id, count=count,
                type="limit", post_only=True, expiration_ts=expiration_ts,
                self_trade_prevention_type=STP_TYPE, **kwargs)
            oid = (resp.get("order") or {}).get("order_id") or resp.get("order_id", "")
            if oid:
                self.state.our_order_ids[oid] = now_ts   # its fills are ours
                self._journal_order_id(oid, now_ts)
            log(f"{self.tag} comp hedge {label} -> {oid}")
            self._sink("comp_hedge", dict(row, order_id=oid))
            return oid or None
        except Exception as e:
            body = str(getattr(e, "body", "") or "")[:300]
            log(f"{self.tag} ! comp hedge rejected ({e}){' ' + body if body else ''}: "
                f"{label}")
            self._sink("comp_hedge", dict(row, error=str(e), error_body=body))
            return None

    def _join_ahead(self, t: str, meta, yes_levels, no_levels, own_in_book,
                    ext_bid: Optional[int], ext_ask: Optional[int],
                    ref_bid_px: Optional[int], ref_ask_px: Optional[int],
                    lv_bid, lv_ask, room_buy: float, room_sell: float,
                    unwind_bid: int, unwind_ask: int, hm: float,
                    rung_lo: int, pmin_s: int, pmax_s: int
                    ) -> Tuple[Optional[int], Optional[int]]:
        """(bid, ask) reference prices for build_side_ladder (YES cents)
        under JOIN_AHEAD_MODE: the join-ahead price where join_ahead_pick
        moves a side; else the EXTERNAL reference, so our own forward rung
        cannot hold the reference forward once the pile has gone; else the
        plain reference unchanged (no external reference, no room, a full
        unwind, mode dry). Logs each side's move and return once."""
        ext_yes, ext_no = external_levels(yes_levels, no_levels, own_in_book)
        target, df = meta.target_size, meta.discount_factor
        pool = float(meta.dollars_per_day or 0.0)
        safe = series_safe_join(meta.series)
        live = JOIN_AHEAD_MODE == "on"
        tag = "" if live else " (dry)"
        out: List[Optional[int]] = []
        for side in ("bid", "ask"):
            ref = ref_bid_px if side == "bid" else ref_ask_px
            anchor = ext_bid if side == "bid" else ext_ask
            opp = ext_ask if side == "bid" else ext_bid
            room = room_buy if side == "bid" else room_sell
            unwind = unwind_bid if side == "bid" else unwind_ask
            lv = lv_bid if side == "bid" else lv_ask
            if ref is None or anchor is None or room < 1 or unwind > 0 or not lv:
                out.append(ref)
                continue
            # post-only, exactly as build_side_ladder moves its anchor
            if side == "bid" and opp is not None and anchor >= opp:
                anchor = opp - 1
            elif side == "ask" and opp is not None and anchor <= opp:
                anchor = opp + 1
            levels = levels_desc(ext_yes if side == "bid" else ext_no)
            r_ext = side_reference_level(levels, target)
            if r_ext is None:
                out.append(ref)
                continue
            spread = (((opp - anchor) if side == "bid" else (anchor - opp))
                      if opp is not None else None)
            off = JOIN_AHEAD_MIN_TICKS
            if safe and (spread is None or spread < SAFE_JOIN_MIN_SPREAD):
                off = max(off, SAFE_JOIN_OFFSET_TICKS)
            total0 = sum(s for _t, s in lv)
            if side == "bid":
                plain = r_ext
                base_yes = min(anchor, max(r_ext, max(rung_lo, RUNG_DEEP_FLOOR)))
                base_own = base_yes
                top_own = min(anchor - off, pmax_s, STICKY_PRICE_MAX)
            else:
                plain = 100 - r_ext
                base_yes = max(anchor, min(plain, min(pmax_s, STICKY_PRICE_MAX)))
                base_own = 100 - base_yes
                top_own = 100 - max(anchor + off, pmin_s, STICKY_PRICE_MIN)

            def size_at(p_own: int, _side=side, _anchor=anchor, _total=total0,
                        _room=room) -> int:
                p_yes = p_own if _side == "bid" else 100 - p_own
                m = capped_ref_mult(_anchor, p_yes, _side, hour_mult=hm,
                                    series=meta.series)
                return min(int(round(_total * m)), int(_room))

            pick = join_ahead_pick(levels, base_own, top_own, size_at,
                                   target, df, pool)
            key = (t, side)
            prev = self._join_ahead_state.get(key)
            if pick is None:
                if prev is not None:
                    del self._join_ahead_state[key]
                    log(f"{self.tag} join-ahead{tag} {t} {side}: back to the "
                        f"reference {base_yes}c")
                out.append(plain if live else ref)
                continue
            px_yes = pick["px"] if side == "bid" else 100 - pick["px"]
            if prev != px_yes:
                self._join_ahead_state[key] = px_yes
                log(f"{self.tag} join-ahead{tag} {t} {side}: {base_yes}c -> "
                    f"{px_yes}c (side share {100 * pick['base_share']:.1f}% -> "
                    f"{100 * pick['share']:.1f}%, +${pick['gain_day']:.2f}/day; "
                    f"{pick['base_ahead']:,.0f} -> {pick['ahead']:,.0f} contracts "
                    f"ahead; {size_at(base_own)} -> {pick['size']} lots)")
            out.append(px_yes if live else ref)
        return out[0], out[1]

    def _resolve_family_verdicts(self, by_market: Dict[str, dict],
                                 now_ts: float) -> int:
        """Source-verify the family-suffix series in the LIVE programs feed
        (ALLOW_FAMILY_SUFFIXES): one GET /series per series that has no
        verdict or whose verdict is older than FAMILY_VERDICT_TTL_SECS, at
        most FAMILY_MAX_SERIES_FETCHES per refresh, never-read series first.
        A failed or empty read keeps whatever verdict exists (a transient
        429 must not un-admit a quoting family) and is retried next refresh;
        a never-read series stays NOT allowed until its read succeeds. Runs
        BEFORE the candidates filter so a resolution admits in the same
        refresh. Returns the number of verdicts written."""
        if not FAMILY_SOURCE_CHECK or not by_market:
            return 0
        pending: List[Tuple[int, str]] = []
        seen: Set[str] = set()
        for t in by_market:
            s = series_of(t)
            if s in seen or not series_verdict_wanted(s):
                continue
            seen.add(s)
            ent = FAMILY_VERDICTS.get(s)
            if not isinstance(ent, dict) or "carbon_arc" not in ent:
                pending.append((0, s))
            elif now_ts - float(ent.get("ts") or 0.0) >= FAMILY_VERDICT_TTL_SECS:
                pending.append((1, s))
        if not pending:
            return 0
        pending.sort()
        budget = max(0, FAMILY_MAX_SERIES_FETCHES)
        written = 0
        for _rank, s in pending[:budget]:
            try:
                so = (self.client.get(f"/series/{s}") or {}).get("series") or {}
            except Exception as e:
                log(f"{self.tag} ! family series read failed {s}: {e}; "
                    f"{'verdict kept' if s in FAMILY_VERDICTS else 'not allowed until read'}")
                continue
            if not so:
                log(f"{self.tag} ! family series read empty for {s}; retry next refresh")
                continue
            ok = series_is_carbon_arc(so)
            prev = family_verdict(s)
            title = str(so.get("title") or "")[:80]
            title = title.encode("ascii", "replace").decode("ascii")
            FAMILY_VERDICTS[s] = {"carbon_arc": ok, "ts": now_ts, "title": title}
            written += 1
            if prev != ok:
                log(f"{self.tag} family verdict {s}: "
                    f"{'Carbon Arc -> normal book' if ok else 'NOT Carbon Arc -> not a family member'}"
                    f" ({title or 'untitled'})")
        if written:
            save_family_verdicts()
        if len(pending) > budget:
            log(f"{self.tag} family verdicts: {len(pending) - budget} series "
                f"still pending (budget {budget}/refresh)")
        return written

    # ---- open-scan tier (2026-09-05) -----------------------------------------

    def _scan_series_ok(self, series: str, now_ts: float,
                        budget: Dict[str, int]) -> Tuple[bool, str]:
        """FAMILY screen behind a persisted per-series cache (one GET /series
        per SCAN_SERIES_META_TTL_SECS). Budget exhausted or unreadable ->
        NOT ok ('..._pending' / '..._unavailable'), retried next refresh;
        an unreadable/empty object is never cached. A cached verdict is
        re-read against the current category knob (scan_cached_verdict):
        a lifted ban makes the entry stale -> fresh read; a new ban rejects
        in place."""
        ent = self.state.scan_series_meta.get(series)
        if ent and now_ts - float(ent.get("ts", 0)) < SCAN_SERIES_META_TTL_SECS:
            cached = scan_cached_verdict(ent)
            if cached is not None:
                return cached
        if budget["series"] <= 0:
            return False, "series_meta_pending"
        budget["series"] -= 1
        try:
            resp = self.client.get(f"/series/{series}") or {}
            so = resp.get("series") or {}
        except Exception as e:
            log(f"{self.tag} ! open-scan series read failed {series}: {e}")
            return False, "series_meta_unavailable"
        ok, why, cat = scan_series_meta_verdict(so)
        if why == "series_meta_unavailable":
            return False, why
        self.state.scan_series_meta[series] = {
            "ts": now_ts, "ok": ok, "why": why, "category": cat,
            "fiscal": scan_series_is_fiscal(so),
            "sources": series_source_blobs(so)}
        return ok, why

    def _scan_member_policy(self, meta: MarketMeta, now_ts: float,
                            budget: Dict[str, int]) -> Optional[str]:
        """POLICY re-test of a sitting open-scan MEMBER (2026-09-24). Members
        skip _scan_admission (quote-to-completion: the ROI, activity and
        history screens judged them once), but the policy screens are not
        a one-time judgement: a live-source keyword added after admission
        (openrouter / vercel on 9/24 -- KXTOKENUSE, KXXIAOMISHARE and five
        Vercel members were quoting on week-old ok-verdicts) or a category
        re-ban must take the member out that refresh. None = keep; else the
        reject reason. A pending or unreadable series read KEEPS the member
        (never evict on a missing read); the live rule's prong B applies
        exactly as it does at admission."""
        ok, why = self._scan_series_ok(meta.series, now_ts, budget)
        if ok or why in ("series_meta_pending", "series_meta_unavailable"):
            return None
        if why == "live_source" and not live_reward_overlaps(meta):
            return None
        return why or "series_meta"

    def _scan_series_fiscal(self, series: str) -> Optional[bool]:
        """The persisted Fiscal.ai flag for a series: True/False once the
        series has been read, None while unknown."""
        ent = self.state.scan_series_meta.get(series)
        if not isinstance(ent, dict) or "fiscal" not in ent:
            return None
        return bool(ent.get("fiscal"))

    def _scan_history_ok(self, meta: MarketMeta, now_ts: float,
                         budget: Dict[str, int]) -> Tuple[bool, str]:
        """HISTORY screen behind a persisted per-market cache (one hourly
        candlestick read per SCAN_HISTORY_TTL_SECS). Same fail-closed
        budget/unavailable semantics as the series screen."""
        ent = self.state.scan_history_cache.get(meta.ticker)
        if ent and now_ts - float(ent.get("ts", 0)) < SCAN_HISTORY_TTL_SECS:
            # re-scored against the CURRENT caps, so a knob change lands on
            # the next refresh instead of waiting out the 6h TTL; None means
            # the entry's stats are incomplete and it must be re-read
            scored = scan_history_rescore(ent)
            if scored is not None:
                return scored
        if budget["history"] <= 0:
            return False, "history_pending"
        budget["history"] -= 1
        try:
            resp = self.client.get(
                f"/series/{meta.series}/markets/{meta.ticker}/candlesticks",
                params={"start_ts": int(now_ts - SCAN_HISTORY_HOURS * 3600),
                        "end_ts": int(now_ts), "period_interval": 60}) or {}
        except Exception as e:
            log(f"{self.tag} ! open-scan candles read failed {meta.ticker}: {e}")
            return False, "history_unavailable"
        candles = resp.get("candlesticks")
        if not isinstance(candles, list):
            return False, "history_unavailable"
        v = scan_history_verdict(candles)
        self.state.scan_history_cache[meta.ticker] = dict(v, ts=now_ts)
        return v["ok"], v["why"]

    def _scan_admission(self, meta: MarketMeta, m: dict,
                        ev_vol24: Dict[str, float], now_utc: datetime,
                        budget: Dict[str, int]) -> Optional[str]:
        """Every open-scan admission screen for a NON-member candidate, in
        cost order (string, then market-object, then cached/bounded reads).
        None = admissible; else the reject reason (also the quote-gaps
        label). Members never come here — they quote to completion.

        `ev_vol24` maps event -> AVERAGE 24h volume per market on that
        event (Jack 2026-09-06), not the sum it held until then."""
        now_ts = now_utc.timestamp()
        if meta.event_ticker in self.state.scan_evicted_events:
            return "evicted"
        if SCAN_HOPELESS_BAR and meta.ticker in self.state.scan_hopeless_barred:
            # this exact strike already proved it cannot reach the payout
            # floor before its program ends (see the hopeless branch)
            return "hopeless_barred"
        strikes = [x for x in self.state.scan_series_strikes.get(meta.series, [])
                   if now_ts - x < SCAN_SERIES_STRIKE_TTL_SECS]
        if 0 < SCAN_SERIES_STRIKE_LIMIT <= len(strikes):
            return "series_struck"
        # Fiscal.ai month-named KPI events (Jack 2026-09-06): the 'undated'
        # reject is waived only for a Fiscal.ai-settled series, which takes
        # the (cached, budgeted) series read BEFORE the structure verdict.
        # Non-numeric month binaries never earn that read — 'shape' first.
        # An undated ticker is admissible when SOME stand-down guard exists:
        # a resolved cutoff (Kalshi's published occurrence, via
        # trade_cutoff_utc), or the Fiscal.ai report month. cutoff_known is
        # checked first because it costs no read — only a month-named ticker
        # with no cutoff pays for a series read to learn its family.
        cutoff_known = meta.cutoff is not None
        fiscal = False
        if SCAN_REQUIRE_DATED and not cutoff_known \
                and parse_event_date(meta.ticker) is None \
                and parse_event_month(meta.ticker) is not None:
            pre = scan_shape_reason(meta.ticker, m.get("strike_type"), fiscal=True)
            if pre is not None:
                return pre        # a month-named binary: 'shape', no read spent
            known = self._scan_series_fiscal(meta.series)
            if known is None:
                # unknown, or a verdict persisted before the flag existed:
                # read (or re-read) the series now
                self.state.scan_series_meta.pop(meta.series, None)
                ok, why = self._scan_series_ok(meta.series, now_ts, budget)
                if not ok:
                    return why or "series_meta"
                known = self._scan_series_fiscal(meta.series)
            fiscal = bool(known)
        why = scan_shape_reason(meta.ticker, m.get("strike_type"),
                                fiscal=fiscal, cutoff_known=cutoff_known)
        if why:
            return why
        if meta.cutoff is not None and now_utc >= meta.cutoff:
            # the report-month cutoff (or any resolved cutoff) already
            # passed: the normal book's _screen would kill it anyway —
            # say so here, before the reads
            return "cutoff_passed"
        # BOTH SIDES OUTSIDE THE QUOTING BAND (Jack 2026-09-07: "add a screen
        # for books entirely outside the quotable band, dont allow them as
        # one of the 30"). The per-side top-in-band rule in the quote loop
        # stands a side down when its own touch is out of band, and stands
        # the whole market down when both are — so such a market is SELECTED,
        # holds a slot, and rests nothing. Measured the day this shipped:
        # KXDIESELELECT / KXDIESELYE came in on a 4c/98c book and took three
        # of the tier's new slots to place zero orders (KXDIESELMINY is the
        # same shape in the normal book, holding 3 per-event slots).
        # Cheap and read-free, so it runs before the age/activity screens.
        # A MEMBER whose book widens into this state is not caught here
        # (members skip admission) but the hopeless exit gets it: with no
        # placeable quote the estimator returns 0/day, which cannot reach the
        # $1 floor, and SCAN_HOPELESS_EXIT evicts it after the sustain window.
        _pmin, _pmax = member_price_band(meta.series, False)
        _bid = market_cents(m, "yes_bid")
        _ask = market_cents(m, "yes_ask")
        if not (_bid is not None and _pmin <= _bid <= _pmax) \
                and not (_ask is not None and _pmin <= _ask <= _pmax):
            return "band"
        if meta.open_time is None or \
                (now_utc - meta.open_time).total_seconds() < SCAN_MIN_AGE_HOURS * 3600:
            return "age"
        if meta.volume_24h > SCAN_MAX_VOLUME_24H:
            return "volume"
        if ev_vol24.get(meta.event_ticker, 0.0) > SCAN_MAX_EVENT_AVG_VOLUME_24H:
            return "event_avg_volume"
        ok, why = self._scan_series_ok(meta.series, now_ts, budget)
        if not ok:
            # LIVE-FEED RULE prong B (Jack 2026-09-24): a live settlement
            # source rejects only when the reward window overlaps the
            # market's resolution (almost) entirely -- live_reward_overlaps.
            # Every other family reject stands as read.
            if why != "live_source" or live_reward_overlaps(meta):
                return why or "series_meta"
        ok, why = self._scan_history_ok(meta, now_ts, budget)
        if not ok:
            return why or "history"
        return None

    def _scan_evict_event(self, ev: str, why: str,
                          by_event: Dict[str, List[MarketMeta]],
                          resting: List[dict], desired: List[Quote],
                          now_ts: float) -> None:
        """PERMANENT open-scan eviction of a whole event: quotes cancelled on
        every scan member of it, the members deselected (inventory winds
        down reduce-only through managed_extra like any deselection), this
        cycle's already-built quotes stripped in place, the event barred
        from re-admission and its series struck."""
        self.state.scan_evicted_events[ev] = now_ts
        members = [m2 for m2 in by_event.get(ev, [])
                   if m2.ticker in self.state.scan_members]
        series = members[0].series if members else ev.split("-")[0]
        self.state.scan_series_strikes.setdefault(series, []).append(now_ts)
        n_cx = 0
        for m2 in members:
            n_cx += self.cancel_market_orders(m2.ticker, resting)
            self.state.selected.pop(m2.ticker, None)
            self.state.scan_members.discard(m2.ticker)
            self.state.scan_entry_mid.pop(m2.ticker, None)
        ev_ticks = {m2.ticker for m2 in members}
        desired[:] = [q for q in desired if q.ticker not in ev_ticks]
        n_strikes = sum(1 for x in self.state.scan_series_strikes.get(series, [])
                        if now_ts - x < SCAN_SERIES_STRIKE_TTL_SECS)
        self.alerter.alert(
            "scan_evict",
            f"{ev}: {why} — evicting the event from the open-scan tier "
            f"PERMANENTLY ({len(members)} member(s), {n_cx} orders cancelled; "
            f"series {series} strike {n_strikes}/{SCAN_SERIES_STRIKE_LIMIT}"
            + (", family barred" if 0 < SCAN_SERIES_STRIKE_LIMIT <= n_strikes
               else "") + ")", key=ev)

    def _scan_book_pnl(self) -> float:
        """The tier's realized + mark-to-market over scan_book (in-process
        realized; the cross-restart composition is scan_pnl_carry)."""
        total = 0.0
        for t in self.state.scan_book:
            total += self.pnl.realized.get(t, 0.0)
            p = self.pnl.pos.get(t, 0.0)
            mark = self.state.last_mark.get(t)
            if abs(p) > 1e-9 and mark is not None:
                total += p * (mark - self.pnl.avg.get(t, 0.0)) / 100.0
        return total

    def _nfl_live_games(self, now_ts: float) -> Tuple[Optional[bool], str]:
        """nfl_live_verdict on the resolver's ESPN client (its host-down
        skip), cached NFL_LIVE_TTL_SECS."""
        c = self._nfl_live_cache
        if c is not None and now_ts - c[0] < NFL_LIVE_TTL_SECS:
            return c[1], c[2]
        verdict, why = nfl_live_verdict(self.resolver._get, now_ts,
                                        self._nfl_final_seen)
        self._nfl_live_cache = (now_ts, verdict, why)
        return verdict, why

    def _mlb_get(self, url: str, now_ts: float, ttl: float):
        """An ESPN MLB board through the resolver's client (its host-down
        skip), cached per URL for `ttl` seconds; raises when unreadable."""
        hit = self._mlb_get_cache.get(url)
        if hit is not None and now_ts - hit[0] < ttl:
            return hit[1]
        data = self.resolver._get(url)
        self._mlb_get_cache[url] = (now_ts, data)
        return data

    def _mlb_mvp_hold(self, series: str, now_ts: float) -> str:
        """Why an MLB postseason MVP market sits out now ('' = quote): its
        round decided on ESPN's boards -- today's and the
        MLB_DECIDED_LOOKBACK_DAYS before it, sticky for the process -- or
        any MLB game live (espn_live_verdict). An unreadable board holds it
        too (fail closed). See MLB_MVP_ROUNDS."""
        rnd = MLB_MVP_ROUNDS[series]
        today = datetime.fromtimestamp(now_ts, timezone.utc).astimezone(ET).date()
        for k in range(MLB_DECIDED_LOOKBACK_DAYS + 1):
            if rnd in self._mlb_decided:
                break
            d = today - timedelta(days=k)
            url = (f"{ESPN_SITE_API}/{ESPN_LEAGUE_PATHS['MLB']}/"
                   f"scoreboard?dates={d.strftime('%Y%m%d')}")
            try:
                # today's / yesterday's boards as fresh as the live check;
                # older ones are final
                board = self._mlb_get(url, now_ts,
                                      MLB_LIVE_TTL_SECS if k <= 1 else 6 * 3600)
            except Exception as e:                       # noqa: BLE001
                return f"MLB scoreboard unreadable ({type(e).__name__})"
            for r, summary in mlb_rounds_decided(board).items():
                if r not in self._mlb_decided:
                    self._mlb_decided[r] = summary
                    log(f"{self.tag} mlb {r} decided ({summary}): its MVP "
                        f"markets stay out")
        if rnd in self._mlb_decided:
            return f"{rnd} decided ({self._mlb_decided[rnd]})"
        live, why = espn_live_verdict(
            "MLB", lambda u: self._mlb_get(u, now_ts, MLB_LIVE_TTL_SECS),
            now_ts, self._mlb_final_seen, MLB_LIVE_COOLDOWN_MIN,
            MLB_GAME_OVER_AFTER_H, "first pitch")
        if live is not False:
            return why or "MLB scoreboard unreadable"
        return ""

    def _league_auto_hold(self, series: str, now_ts: float, ticker: str = "") -> str:
        """Why a league auto family SEASON member sits out now ('' =
        quote): its deciding round ("decided_by") decided on its league's
        ESPN boards -- today's and the MLB_DECIDED_LOOKBACK_DAYS before it,
        sticky for the process -- or any game of its league live
        (espn_live_verdict). An unreadable board holds it too (fail
        closed). See LEAGUE_AUTO_ENABLE."""
        e = league_auto_entry(series) or {}
        league = e.get("league") or series_league(series) or ""
        if league == "LOL":
            return self._lol_hold(ticker or series, now_ts)
        path = ESPN_LEAGUE_PATHS.get(league)
        if not path:
            return f"no ESPN scoreboard for {league or series}"
        decided = self._league_decided.setdefault(league, {})
        rnd = e.get("decided_by")
        if rnd:
            today = datetime.fromtimestamp(now_ts, timezone.utc).astimezone(ET).date()
            for k in range(MLB_DECIDED_LOOKBACK_DAYS + 1):
                if rnd in decided:
                    break
                d = today - timedelta(days=k)
                url = f"{ESPN_SITE_API}/{path}/scoreboard?dates={d.strftime('%Y%m%d')}"
                try:
                    board = self._mlb_get(url, now_ts,
                                          LEAGUE_LIVE_TTL_SECS if k <= 1 else 6 * 3600)
                except Exception as ex:                      # noqa: BLE001
                    return f"{league} scoreboard unreadable ({type(ex).__name__})"
                for r, summary in mlb_rounds_decided(board).items():
                    if r not in decided:
                        decided[r] = summary
                        log(f"{self.tag} {league} {r} decided ({summary}): league "
                            f"auto members tied to it stay out")
            if rnd in decided:
                return f"{rnd} decided ({decided[rnd]})"
        live, why = espn_live_verdict(
            league, lambda u: self._mlb_get(u, now_ts, LEAGUE_LIVE_TTL_SECS),
            now_ts, self._league_final_seen.setdefault(league, {}),
            LEAGUE_LIVE_COOLDOWN_MIN, LEAGUE_GAME_OVER_AFTER_H.get(league, 4.0),
            LEAGUE_START_WORD.get(league, "the start"))
        if live is not False:
            return why or f"{league} scoreboard unreadable"
        return ""

    def _lol_live(self, now_ts: float) -> List[dict]:
        """getLive's events, cached LEAGUE_LIVE_TTL_SECS; raises when unreadable."""
        c = self._lol_cache.get("live")
        if c is not None and now_ts - c[0] < LEAGUE_LIVE_TTL_SECS:
            return c[1]
        data = self._lol_get("getLive?hl=en-US")
        evs = list((((data or {}).get("data") or {}).get("schedule") or {}).get("events") or [])
        self._lol_cache["live"] = (now_ts, evs)
        return evs

    def _lol_schedule(self, slug: str, now_ts: float) -> List[dict]:
        """A tournament's schedule -- the default page plus LOL_SCHEDULE_PAGES
        older and newer pages, deduplicated -- cached LOL_SCHEDULE_TTL_SECS;
        raises when unreadable."""
        key = f"sched:{slug}"
        c = self._lol_cache.get(key)
        if c is not None and now_ts - c[0] < LOL_SCHEDULE_TTL_SECS:
            return c[1]
        base = f"getSchedule?hl=en-US&leagueId={LOL_LEAGUE_IDS[slug]}"

        def page(path):
            return (((self._lol_get(path) or {}).get("data") or {}).get("schedule") or {})
        first = page(base)
        evs = list(first.get("events") or [])
        for way in ("older", "newer"):
            tok = (first.get("pages") or {}).get(way)
            for _ in range(LOL_SCHEDULE_PAGES):
                if not tok:
                    break
                p = page(f"{base}&pageToken={tok}")
                evs += p.get("events") or []
                tok = (p.get("pages") or {}).get(way)
        seen: Set[Any] = set()
        out: List[dict] = []
        for e_ in evs:
            k = (e_.get("match") or {}).get("id") or (e_.get("startTime"), e_.get("blockName"))
            if k not in seen:
                seen.add(k)
                out.append(e_)
        self._lol_cache[key] = (now_ts, out)
        return out

    def _lol_hold(self, ticker: str, now_ts: float) -> str:
        """Why a League of Legends season member sits out now ('' = quote): its
        deciding stage complete (sticky), a match of its tournament live or
        just over (the cooldown), or the lolesports feed unreadable (fail
        closed). See LOL_API."""
        ev = "-".join(ticker.split("-")[:2])
        slug = lol_event_tournament(ev)
        stage = lol_deciding_stage(ev)
        done = f"{slug}:{stage}"
        if stage and done in self._lol_decided:
            return f"{stage} complete ({slug})"
        try:
            sched = self._lol_schedule(slug, now_ts) if slug in LOL_LEAGUE_IDS else []
            live = self._lol_live(now_ts)
        except Exception as ex:                          # noqa: BLE001
            return f"lolesports feed unreadable ({type(ex).__name__})"
        if stage and lol_stage_complete(sched, stage, now_ts):
            self._lol_decided.add(done)
            log(f"{self.tag} LoL {slug} {stage} complete: its league auto members stay out")
            return f"{stage} complete ({slug})"
        why = lol_live_reason(live, sched, slug, now_ts)
        k = slug or "*"
        if why:
            self._lol_last_live[k] = now_ts
            return why
        last = self._lol_last_live.get(k)
        if last is not None and now_ts - last < LEAGUE_LIVE_COOLDOWN_MIN * 60:
            return (f"{slug or 'a LoL'} match live {(now_ts - last) / 60:.0f}m ago "
                    f"(cooldown {LEAGUE_LIVE_COOLDOWN_MIN}m)")
        return ""

    def _twk_pnl(self, key: str) -> float:
        """One pilot budget's realized + mark-to-market (pilot_halt_key: a
        Trump weekly series, or the NFL head-to-head family) over its tickers
        in the bot's own P&L book; the cross-restart composition is
        twk_pnl_carry[key]."""
        total = 0.0
        for t in set(self.pnl.realized) | set(self.pnl.pos):
            if pilot_budget_key(t) != key:
                continue
            total += self.pnl.realized.get(t, 0.0)
            p = self.pnl.pos.get(t, 0.0)
            mark = self.state.last_mark.get(t)
            if abs(p) > 1e-9 and mark is not None:
                total += p * (mark - self.pnl.avg.get(t, 0.0)) / 100.0
        return total

