        total = 0.0
        for t in set(self.pnl.realized) | set(self.pnl.pos):
            if not ytw_series(series_of(t)):
                continue
            total += self.pnl.realized.get(t, 0.0)
            p = self.pnl.pos.get(t, 0.0)
