    def _coverage(self, ticker: str, counted: bool) -> float:
        """Update + return the per-market counted-snapshot EMA.

        OBSERVABILITY ONLY since 2026-08-04 — it is NOT a factor in any reward
        estimate any more. It used to multiply the accrual rate as a proxy for
        the payout's non-excluded ratio, which double-counted the exclusion:
        `estimate_reward_share` already returns 0.0 for a snapshot that fails
        the two-sided target test, so an excluded snapshot contributes nothing
        to the integral before any EMA is applied. Writing out the program's
        arithmetic makes the double-count obvious — with C counted snapshots
        out of S, pool P, and per-snapshot share frac_i:

            payout = P x (C/S) x (sum_{i in C} frac_i)/C = (P/S) x sum_i frac_i

        i.e. exactly `sum(frac x dollars_per_day x dt)`, the raw integral. The
        (C/S) scaling cancels against the per-snapshot normalisation; applying
        an EMA of the same indicator on top is a second, unjustified haircut.

        Measured against Jack's 2026-08-04 statement on the only clean window
        (events that started after the post-amendment rewrite shipped
        2026-08-01 19:13Z, n=99 credited events, $960.96): the raw integral
        came in at 0.982x credited, the coverage-multiplied one at 1.057x.
        Applying the $1 payout floor as well lands the raw integral at 1.016x.
        """
        prev = self._coverage_ema.get(ticker)
        cur = 1.0 if counted else 0.0
        ema = cur if prev is None else prev + COVERAGE_EMA_ALPHA * (cur - prev)
        self._coverage_ema[ticker] = ema
        return ema

    def _ca_shadow_note(self, meta: MarketMeta, yes_levels: List[List[float]],
                        no_levels: List[List[float]], ext_b: Optional[int],
                        ext_a: Optional[int]) -> None:
        """Append what the Carbon Arc empty-book rule (C) and the 1-99 band
        (D) WOULD quote on this book to ca_shadow_<UTC date>.jsonl (see
        CA_SHADOW): once per CA_SHADOW_LOG_SECS per market, or sooner when
        the proposal changes. Never raises; never touches `meta`."""
        try:
            now = time.time()
            p = ca_shadow_proposals(meta, yes_levels, no_levels, ext_b, ext_a, now)
            if p is None:
                return
            last = self.__dict__.setdefault("_ca_shadow_last", {})
            sig = json.dumps([p["src"], (p.get("C") or {}).get("sides"),
                              (p.get("D") or {}).get("sides")])
            prev = last.get(meta.ticker)
            if prev is not None and prev[0] == sig and now - prev[1] < CA_SHADOW_LOG_SECS:
                return
            last[meta.ticker] = (sig, now)
            stamp = datetime.now(timezone.utc)
            p["ts"] = stamp.isoformat(timespec="seconds")
            with open(os.path.join(STATUS_DIR, f"ca_shadow_{stamp:%Y-%m-%d}.jsonl"),
                      "a", encoding="utf-8") as f:
                f.write(json.dumps(p, sort_keys=True) + "\n")
        except Exception as e:
            if not self.__dict__.get("_ca_shadow_err"):
                self._ca_shadow_err = True
                log(f"{self.tag} ! ca-shadow note failed ({type(e).__name__}: {e}); "
                    f"quoting is unaffected")

    def _estimate_candidate_yield(self, meta: MarketMeta,
                                  own_live: List[Tuple[str, int, float]]) -> bool:
        """Fill meta.est_frac / est_dollars_per_day / yield_per_contract from
        the candidate's live orderbook. Live mode with resting orders: score
        what is actually resting (it's already in the book). Otherwise: overlay
        the default ladder joined to the current external best. Returns False
        when the book can't be read."""
        meta.floor_dollars_per_day = 0.0     # set with the estimate below
        # decision-input logging: set below only if the estimate actually runs
        meta.est_hour_mult = meta.nc_size_mult = meta.ys_size_mult = None
        meta.floor_realized_ratio = None
        # Live-CONFIRMED events never come back (Jack 2026-08-31 #2): worth
        # nothing by decree, without even reading the book — so no market of
        # the event can be selected or hold an event slot again.
        if meta.event_ticker in self.state.event_live_halt:
            meta.est_frac = meta.est_dollars_per_day = 0.0
            meta.yield_per_contract = 0.0
            return True
        # the universe refresh reads ~3,000 candidate books (REST: ~150s on
        # 10/8): without a tick here our WS fills waited it out (10/4 21:01Z:
        # two sweep trips logged 37s after their fills)
        self._ws_cycle_tick()
        try:
            ob = self._read_candidate_book(meta.ticker)   # WS_CANDIDATES
        except Exception:
            return False
        if BOOK_LOG_CANDIDATES:
            # Own size from the PREVIOUS cycle's exchange resting read (the
            # universe refresh runs before this cycle's read), not the local
            # ledger, which fills never reduce. For any market we quote, the
            # managed row of the same cycle carries the fresher own size.
            self._book_log_add(meta.ticker, "candidate", ob,
                               self._book_own_exch.get(meta.ticker, ()), meta,
                               own_src="resting_prev_cycle")
        yes_levels, no_levels = orderbook_levels(ob)
        meta.book_depth_contracts = (sum(q for _px, q in yes_levels)
                                     + sum(q for _px, q in no_levels))
        ext_b, ext_a = external_best(yes_levels, no_levels)
        # CARBON ARC SHADOW (C / D, 2026-10-16): logs what the empty-book rule
        # and the 1-99 band would quote; never changes this estimate
        if CA_SHADOW_ENABLE and carbon_arc_settled(meta.series):
            self._ca_shadow_note(meta, yes_levels, no_levels, *(
                external_best(yes_levels, no_levels, own_live) if own_live
                else (ext_b, ext_a)))
        # LIVE-EVENT DEPTH GATE, selection side (Jack 2026-08-31). This hook
        # is what makes the gate EVENT-wide in practice: a thin strike reads
        # est=0 and never gets selected, so the quote loop alone would never
        # see it — its deep siblings would quote a live event unopposed. Any
        # quotable (in-band) candidate of a gated series with a thin external
        # side marks the whole event halted here, and the quote loop refuses
        # every sibling. Runs BEFORE sides_can_qualify so the thin market
        # itself also ranks as worthless.
        if series_event_depth_gated(meta.series) \
                and pad_band_ok(meta.series, ext_b, ext_a) \
                and event_live_gate_armed(meta.event_ticker, time.time()):
            d_yes, d_no = external_depths(yes_levels, no_levels, own_live)
            stacked = (EVENT_DEPTH_STACK_CONTRACTS > 0
                       and max(d_yes, d_no) >= EVENT_DEPTH_STACK_CONTRACTS)
            if not stacked and (d_yes < EVENT_DEPTH_MIN_CONTRACTS
                                or d_no < EVENT_DEPTH_MIN_CONTRACTS):
                first = meta.event_ticker not in self.state.event_depth_halt
                self.state.event_depth_halt[meta.event_ticker] = time.time()
                if first:
                    self.alerter.alert(
                        "event_depth",
                        f"{meta.event_ticker}: {meta.ticker} external depth "
                        f"yes {d_yes:.0f} / no {d_no:.0f} < "
                        f"{EVENT_DEPTH_MIN_CONTRACTS:.0f} — event likely "
                        f"LIVE; standing down the whole event",
                        key=meta.event_ticker, urgent=False)
                meta.est_frac = meta.est_dollars_per_day = 0.0
                meta.yield_per_contract = 0.0
                return True      # readable; deliberately worth nothing
        # Same qualification gate the quote loop applies (Jack 2026-08-05).
        # It has to be here as well or selection keeps RANKING markets the
        # loop then refuses to quote — they would hold budget and an event
        # slot while resting nothing, and read as a silent capacity leak.
        # Runs AFTER external_best because the pad conditions need the touch.
        _bid_ok, _ask_ok = sides_can_qualify(
            meta.series, meta.target_size,
            sum(q for _px, q in yes_levels), sum(q for _px, q in no_levels),
            ext_b, ext_a, ticker=meta.ticker)
        if not (_bid_ok and _ask_ok):
            meta.est_frac = meta.est_dollars_per_day = 0.0
            meta.yield_per_contract = 0.0
            return True              # readable, just worth nothing
        rb, ra = ladder_reference_prices(yes_levels, no_levels, meta.target_size)
        # TWO-MARKET COMPLEMENT LEAD: the leads the quote loop would rest, read
        # off the EXTERNAL book (an incumbent's own orders netted out) and the
        # twin's -- or off the market's model fair (FAIR LEAD); they price the
        # probe ladder below, and so the estimate and the floor projection
        # (each mode on only): a market under the payout bar behind its wall
        # is admitted when its lead clears it
        _leads: Tuple[Optional[Tuple[int, int, int]],
                      Optional[Tuple[int, int, int]]] = (None, None)
        _lsrc = self._lead_source(meta)
        if _lsrc is not None and lead_mode(_lsrc) == "on":
            _lx_yes, _lx_no = (external_levels(yes_levels, no_levels, own_live)
                               if (self.live and own_live) else (yes_levels, no_levels))
            _leads = self._comp_lead(meta, _lx_yes, _lx_no)
        _lead_n = comp_lead_size(meta.target_size)
        # capped so hour x ref <= TOTAL_SIZE_MULT_CAP; consumers (side rooms,
        # collateral reservation) inherit the cap through these meta fields
        _hm = hour_size_mult(meta.series, datetime.now(timezone.utc))
        meta.est_hour_mult = _hm       # decision-input logging (analytics only)
        meta.ref_mult_bid = capped_ref_mult(ext_b, rb, "bid", hour_mult=_hm,
                                            series=meta.series)
        meta.ref_mult_ask = capped_ref_mult(ext_a, ra, "ask", hour_mult=_hm,
                                            series=meta.series)
        # The buildable ladder, computed for EVERY candidate (pure local
        # arithmetic on the book we already read — no extra API call). The
        # challenger path below scores it; the incumbent path scores its real
        # resting orders instead, but both need the same honest answer to
        # "could we quote both sides here right now?", because a market whose
        # bid falls under the band earns at most half a pool's snapshot score
        # and is one tick from earning nothing (Jack 2026-09-07 on
        # KXTRUEV-26SEP07-T1263.42: "only supports 1 side quoting, and is
        # more likely to fall out of the quoting range and stop earning").
        _now = datetime.now(timezone.utc)
        # near-cliff SIZE mode scales the hypothetical ladder too, so the
        # projection sees the size the quote loop will rest
        _ncm = self._near_cliff_size_mult(meta.ticker)
        meta.nc_size_mult = _ncm       # decision-input logging (analytics only)
        # ...and the yield size mode (2026-10-05) on top: every per-market
        # multiplier the quote loop will apply (_market_size_mult)
        _msm = _ncm * self._yield_size_mult(meta.ticker)
        _lv = scale_levels(hour_scaled_levels(meta.series, _now), _msm)
        # Carbon Arc late-month rule: the hypothetical ladder is per side too,
        # so the reward estimate (and the $1 floor projection built on it)
        # see the size the quote loop will actually rest.
        # (side_size_mults: the same rule plus the bid-only quake family)
        _cbm, _cam = side_size_mults(meta.ticker, _now, meta.mid_cents)
        # The band the quote loop quotes a SELECTED market in -- which every
        # candidate is by the time the loop reaches it (ESTIMATE_SIDE_BAND).
        _qlo, _qhi = member_price_band(meta.series, True)

        def _sides_in_band(eb: Optional[int],
                           ea: Optional[int]) -> Tuple[bool, bool]:
            """The quote loop's PER-SIDE TOP-IN-BAND test (Jack 2026-08-03):
            may the bid / ask side rest, on these EXTERNAL touches?"""
            return (eb is not None and _qlo <= eb <= _qhi,
                    ea is not None and _qlo <= ea <= _qhi)

        def _probe_ladder(hm: float, lv: List[Tuple[int, int]],
                          rmb: float, rma: float,
                          eb: Optional[int], ea: Optional[int],
                          rpb: Optional[int], rpa: Optional[int],
                          sides: Optional[Tuple[float, float]] = None,
                          leads: Tuple[Optional[Tuple[int, int, int]],
                                       Optional[Tuple[int, int, int]]] = (None, None)
                          ) -> List[Quote]:
            """The buildable ladder at hour multiplier `hm` on rung sizes
            `lv`, per-side reference multipliers `rmb` / `rma`, external
            touches `eb` / `ea` and reference prices `rpb` / `rpa` -- pure
            local arithmetic on the book already read. Called at the live
            multiplier for the yield estimate and at 1.0 (day size) for the
            floor projection (FLOOR_PROJECTION_BASE_SIZE, 2026-09-25).
            `sides` = the (bid, ask) side multipliers, default the live
            side_size_mults; the floor projection passes each window
            piece's own (FLOOR_PROJECTION_SIDES). `leads` = the (bid, ask)
            complement leads (comp_lead_prices): a leading side rests one
            rung of at least target/5 at its lead price, as the loop does."""
            sbm, sam = (_cbm, _cam) if sides is None else sides
            lvb, lva = scale_levels(lv, sbm), scale_levels(lv, sam)
            smb, sma = clamp_side_max_to_position_cap(
                int(round(sum(s for _t, s in lvb) * rmb)),
                int(round(sum(s for _t, s in lva) * rma)),
                series_max_position(meta.series))
            if quake_ask_strike(meta.ticker):
                sma = min(sma, QUAKE_ASK_MAX_CONTRACTS)   # the loop's ask cap
            out: List[Quote] = []
            band: Optional[Tuple[int, int]] = None
            if ESTIMATE_SIDE_BAND:
                # the quote loop's side test and rung band, verbatim: a side
                # rests only while its own touch is in the band (which also
                # satisfies the loop's px_ok), and its rungs clamp to the
                # deep floor on a healthy book, else the band floor
                bid_ok, ask_ok = _sides_in_band(eb, ea)
                band = (RUNG_DEEP_FLOOR if (bid_ok and ask_ok) else _qlo, _qhi)
            else:
                # atref: the band gates PLACEMENT no longer follows the touch,
                # so a touch outside the band must not kill the side (rain
                # books trade whole cities under 5c).
                bid_ok = eb is not None and (
                    (LADDER_MODE == "atref" and rpb is not None)
                    or eb >= series_price_min(meta.series))
                ask_ok = ea is not None and (
                    (LADDER_MODE == "atref" and rpa is not None)
                    or ea <= series_price_max(meta.series))
            lb, la = leads
            _cap = int(series_max_position(meta.series))
            if lb is not None or la is not None:    # a leading market's cap
                _cap = max(_cap, int(FAIR_LEAD_MAX_POSITION if _lsrc == "fair"
                                     else COMP_LEAD_MAX_POSITION))

            def _lead_room(sm: int) -> int:
                return max(sm, _lead_n) if _cap <= 0 else min(max(sm, _lead_n), _cap)

            if bid_ok:
                if (lb is not None and sum(s for _t, s in lvb) > 0
                        and comp_lead_band_ok(lb[0], band, meta.series)):
                    out += build_side_ladder(meta.ticker, "bid", lb[0], ea,
                                             _lead_room(smb), levels=lvb,
                                             ref_px=lb[0], band=band,
                                             hour_mult=hm, min_total=_lead_n)
                else:
                    out += build_side_ladder(meta.ticker, "bid", eb, ea,
                                             smb, levels=lvb, ref_px=rpb,
                                             band=band, hour_mult=hm)
            if ask_ok:
                if (la is not None and sum(s for _t, s in lva) > 0
                        and comp_lead_band_ok(la[0], band, meta.series)):
                    out += build_side_ladder(meta.ticker, "ask", la[0], eb,
                                             _lead_room(sma), levels=lva,
                                             ref_px=la[0], band=band,
                                             hour_mult=hm, min_total=_lead_n)
                else:
                    out += build_side_ladder(meta.ticker, "ask", ea, eb,
                                             sma, levels=lva, ref_px=rpa,
                                             band=band, hour_mult=hm)
            if (SUBPENNY_JOIN and meta.price_step < 0.01
                    and sports_ladder_league(meta.series) is not None):
                # the loop's sub-cent edge rungs (subcent_edge_quotes)
                _has = {q.book_side for q in out if not q.is_pad}
                _yx, _nx = orderbook_exact_levels(ob)
                out += subcent_edge_quotes(
                    meta.ticker, _yx, _nx, [],
                    bid_size=smb if "bid" not in _has else 0,
                    ask_size=sma if "ask" not in _has else 0)
            if quake_gated(meta.series):
                # quake gate: the bids the loop will rest, capped at fair --
                # and on an ask strike the ask it may rest, floored at fair
                _qcap, _qask = quake_probe_caps(meta.ticker, _now.timestamp(),
                                                meta.close_time)
                out = [] if _qcap is None else quake_cap_quotes(
                    out, _qcap, _qask, QUAKE_ASK_MAX_CONTRACTS)
            if mort_series(meta.series):
                # mortgage gate: nothing while it stands aside, else the
                # rungs held MORT_FAIR_TOL_CENTS clear of the fair
                _mw, _mi, _mc = mort_gate(meta.ticker, _now.timestamp(), eb, ea)
                out = [] if (_mw or _mc is None) else mort_cap_quotes(out, *_mc)
            if poke_series(meta.series):
                # Pokemon gate: the same, POKE_FAIR_TOL_CENTS clear
                _pw, _pi, _pc = poke_gate(meta.ticker, _now.timestamp(), eb, ea)
                out = [] if (_pw or _pc is None) else mort_cap_quotes(out, *_pc)
            if nfl_series(meta.series):
                # NFL prop gate: nothing while it stands aside, else the
                # rungs held inside the player-history band -- and only the
                # sides that still earn (drop_unearning_sides)
                _nw, _ni, _nc = nfl_gate(meta.ticker, _now.timestamp(), eb, ea)
                out = [] if (_nw or _nc is None) else nfl_cap_quotes(
                    out, *_nc, price_step=meta.price_step)
                out = drop_unearning_sides(
                    out, yes_levels, no_levels,
                    own_live if self.live else [],
                    meta.target_size, meta.discount_factor)
            # monthly rain one side (RAIN_MONTHLY_ONE_SIDE): on a band breach
            # the loop rests only the side that does not fight the fair, so
            # the estimate -- and the payout floor judged on it -- counts
            # that side alone, and only while it earns
            _rso = (rain_monthly_side_out(meta.series, meta.ticker,
                                          _now.timestamp(), eb, ea)
                    # ...and the Vercel bid only on an ask breach (VERCEL_BID_ONLY)
                    or vercel_side_out(meta.series, meta.ticker, _now.timestamp(),
                                       eb, ea, meta.close_time))
            if _rso is not None:
                out = drop_unearning_sides(
                    [q for q in out if q.book_side != _rso],
                    yes_levels, no_levels, own_live if self.live else [],
                    meta.target_size, meta.discount_factor)
            return out

        def _overlay_with_pads(quotes: List[Quote],
                               ylv: List[List[float]], nlv: List[List[float]],
                               eb: Optional[int], ea: Optional[int]
                               ) -> List[Tuple[str, int, float]]:
            """Overlay tuples for estimate_reward_share(own_in_book=False):
            the ladder plus the depth pads the quote loop would rest on thin
            sides of the book `ylv` / `nlv` (global pad_to_target,
            2026-07-29): without them a side under the reward target reads
            qualifies=False -> est 0 -> the market dies at the floor before
            the quote loop could ever pad it. Mirrors the quote loop's
            pad_missing_side (coverage-leak fix) AND the pad distance gates:
            any quoting at all pads BOTH sides for members, but only
            >= PAD_MIN_TICKS_BEHIND the external touch."""
            overlay = [(q.book_side, q.price_cents, float(q.count)) for q in quotes]
            if series_pad_to_target(meta.series) and meta.target_size > 0 \
                    and pad_band_ok(meta.series, eb, ea):
                nt_bid = sum(q.count for q in quotes if q.book_side == "bid")
                nt_ask = sum(q.count for q in quotes if q.book_side == "ask")
                if nt_bid > 0 or nt_ask > 0:
                    if eb is not None and not no_side_only(meta.ticker) \
                            and eb - PAD_BID_CENTS >= PAD_MIN_TICKS_BEHIND:
                        n = pad_quantity(sum(sz for _px, sz in ylv) + nt_bid,
                                         meta.target_size)
                        if n > 0:
                            overlay.append(("bid", PAD_BID_CENTS, float(n)))
                    if ea is not None and not series_bid_only(meta.series) \
                            and PAD_ASK_CENTS - ea >= PAD_MIN_TICKS_BEHIND:
                        n = pad_quantity(sum(sz for _px, sz in nlv) + nt_ask,
                                         meta.target_size)
                        if n > 0:
                            overlay.append(("ask", PAD_ASK_CENTS, float(n)))
            return overlay

        _probe = _probe_ladder(_hm, _lv, meta.ref_mult_bid, meta.ref_mult_ask,
                               ext_b, ext_a, rb, ra, leads=_leads)
        # Sides that will actually REST. This must replicate the quote
        # loop's PER-SIDE TOP-IN-BAND gate (Jack 2026-08-03, CHIH T69.99):
        # "a side whose OWN touch is outside the band stands down alone —
        # its rungs die as diff-unmatched, its pad stays to qualify the
        # snapshot — while the healthy side keeps earning". Reading it off
        # `_probe` instead was WRONG and shipped that way for one refresh:
        # under LADDER_MODE=atref build_side_ladder is deliberately EXEMPT
        # from the band (Jack 2026-08-01, "don't arbitrarily constrain to
        # 5c"), so it happily builds a bid rung at a 4c reference that the
        # loop then never places — KXTRUEV-26SEP07-T1263.42 measured
        # two-sided while resting an ask and nothing else. (Since 2026-09-27
        # the probe applies this same test too -- ESTIMATE_SIDE_BAND -- so
        # the count and the estimate describe the same ladder.)
        if ESTIMATE_SIDE_BAND:
            # the probe's own test, on the touches the loop reads: EXTERNAL
            # (an incumbent's resting orders stripped) against the band a
            # selected market quotes in -- a 91-93c ask counts for a
            # challenger too, since the loop places it once admitted
            _qb, _qa = (external_best(yes_levels, no_levels, own_live)
                        if (self.live and own_live) else (ext_b, ext_a))
            meta.quotable_sides = sum(_sides_in_band(_qb, _qa))
            if (SUBPENNY_JOIN and meta.price_step < 0.01
                    and sports_ladder_league(meta.series) is not None):
                _yx, _nx = orderbook_exact_levels(ob)
                _edge = {q.book_side for q in subcent_edge_quotes(
                    meta.ticker, _yx, _nx, [], 1, 1)}
                _qbo, _qao = _sides_in_band(_qb, _qa)
                meta.quotable_sides += int("bid" in _edge and not _qbo) \
                    + int("ask" in _edge and not _qao)
        else:
            _pmin_s, _pmax_s = member_price_band(
                meta.series, meta.ticker in self.state.selected)
            meta.quotable_sides = (
                int(ext_b is not None and _pmin_s <= ext_b <= _pmax_s)
                + int(ext_a is not None and _pmin_s <= ext_a <= _pmax_s))
        if self.live and own_live:
            frac, sides = estimate_reward_share(
                yes_levels, no_levels, own_live,
                meta.target_size, meta.discount_factor, own_in_book=True)
            n_contracts = sum(r for _s, _p, r in own_live)
            meta.est_collateral_dollars = sum(
                r * ((px if s == "bid" else 100 - px) / 100.0)
                for s, px, r in own_live)
            meta.est_exposure_dollars = _fill_weighted_exposure(
                own_live, yes_levels, no_levels, meta.volume_24h,
                own_in_book=True)
        else:
            quotes: List[Quote] = _probe
            if not quotes:
                meta.est_frac = meta.est_dollars_per_day = meta.yield_per_contract = 0.0
                return True
            overlay = _overlay_with_pads(quotes, yes_levels, no_levels, ext_b, ext_a)
            frac, sides = estimate_reward_share(
                yes_levels, no_levels, overlay,
                meta.target_size, meta.discount_factor, own_in_book=False)
            n_contracts = sum(q.count for q in quotes)
            # Pads INCLUDED here (unlike n_contracts): a 1c filler still ties
            # up real collateral, and the $-of-exposure ranking must see it.
            meta.est_collateral_dollars = sum(
                c * ((px if s == "bid" else 100 - px) / 100.0)
                for s, px, c in overlay)
            meta.est_exposure_dollars = _fill_weighted_exposure(
                overlay, yes_levels, no_levels, meta.volume_24h,
                own_in_book=False)
        self._coverage(meta.ticker, sides == 2)   # observability only (see _coverage)
        meta.est_frac = frac
        meta.est_dollars_per_day = frac * meta.dollars_per_day
        meta.yield_per_contract = \
            (meta.est_dollars_per_day / n_contracts) if n_contracts else 0.0
        # yield size mode verdict (2026-10-05) on this estimate: the size it
        # sets reaches the collateral reservation and the quote loop at once,
        # this estimate and its floor projection next refresh (conservative)
        self._yield_size_verdict(meta, time.time())
        # FLOOR PROJECTION. 2026-09-25 (FLOOR_PROJECTION_BASE_SIZE): judged at
        # DAY size so a market is not admitted on doubled size and evicted
        # on normal size. 2026-09-26 (FLOOR_PROJECTION_SCHEDULE, Jack: "the
        # payout-floor should factor in Saturday and quiet-hour size
        # proportionally to the calculation ... generally"): the projection
        # is the window-weighted mean of what the ladder earns at EACH
        # multiplier the schedule will apply over the remaining accrual
        # window (size_mult_profile), every multiplier scored on the EXTERNAL
        # book -- an incumbent's own hour-scaled orders stripped first
        # (external_levels), that multiplier's ladder re-overlaid on the
        # book's touches and reference prices. A window that carries the
        # live multiplier alone is the live estimate itself (for an
        # incumbent that is the score of what actually rests).
        # 2026-09-27 (FLOOR_PROJECTION_SIDES): each hour also carries the
        # per-side multipliers side_size_mults will apply THEN (the Carbon
        # Arc late-month cut from its window start), not the `now` reading.
        meta.floor_dollars_per_day = meta.est_dollars_per_day
        meta.floor_mult_profile = ""
        meta.floor_by_mult = []       # [] = the floor IS the live estimate
        if FLOOR_PROJECTION_BASE_SIZE and meta.dollars_per_day > 0:
            profile = floor_size_profile(
                meta.series, meta.ticker, _now, _quotable_days(meta, _now),
                hour_schedule=FLOOR_PROJECTION_SCHEDULE)
            meta.floor_mult_profile = floor_profile_str(profile)
            _live_key = (_hm, _cbm, _cam)

            def _is_live(k: Tuple[float, float, float]) -> bool:
                return all(abs(a - b) < 1e-9 for a, b in zip(k, _live_key))

            if not (len(profile) == 1 and _is_live(profile[0][0])):
                if self.live and own_live:
                    ext_yes, ext_no = external_levels(yes_levels, no_levels, own_live)
                    xb, xa = external_best(ext_yes, ext_no)
                    xrb, xra = ladder_reference_prices(ext_yes, ext_no, meta.target_size)
                else:
                    ext_yes, ext_no = yes_levels, no_levels
                    xb, xa, xrb, xra = ext_b, ext_a, rb, ra
                def _hyp_share(m: float, bm: float, am: float) -> float:
                    """The ladder at hour multiplier m and side multipliers
                    bm / am, scored on the external book."""
                    q_m = _probe_ladder(
                        m, scale_levels(scaled_levels_at(meta.series, m), _msm),
                        capped_ref_mult(xb, xrb, "bid", hour_mult=m, series=meta.series),
                        capped_ref_mult(xa, xra, "ask", hour_mult=m, series=meta.series),
                        xb, xa, xrb, xra, sides=(bm, am), leads=_leads)
                    if not q_m:
                        return 0.0
                    return estimate_reward_share(
                        ext_yes, ext_no,
                        _overlay_with_pads(q_m, ext_yes, ext_no, xb, xa),
                        meta.target_size, meta.discount_factor, own_in_book=False)[0]

                total = 0.0
                f_live: Optional[float] = None
                for (m, bm, am), w in profile:
                    f_m = _hyp_share(m, bm, am)
                    if _is_live((m, bm, am)):
                        f_live = f_m
                    total += w * f_m * meta.dollars_per_day
                    try:          # decision-input logging: the per-mult split
                        meta.floor_by_mult.append(
                            [m, round(w, 4), round(f_m * meta.dollars_per_day, 4)]
                            + ([] if (bm, am) == (1.0, 1.0) else [bm, am]))
                    except Exception:
                        pass
                # REALIZED ANCHOR (2026-09-27, FLOOR_PROJECTION_REALIZED): the
                # hypothetical ladders above are what the loop WOULD rest with
                # nothing in its way; an incumbent's real orders are also cut
                # by the event-room share, the inventory skew, the position
                # cap and the per-side band. Scale the whole schedule by what
                # actually rests over what the hypothetical says at the LIVE
                # multiplier (never above 1: the anchor only removes size the
                # loop cannot place).
                if FLOOR_PROJECTION_REALIZED and self.live and own_live:
                    if f_live is None:
                        f_live = _hyp_share(_hm, _cbm, _cam)
                    if f_live > 0:
                        meta.floor_realized_ratio = min(1.0, frac / f_live)
                        total *= meta.floor_realized_ratio
                meta.floor_dollars_per_day = total
        return True

    def _settle_or_drop(self, t: str, via: str = "settle_loop") -> None:
        """Own book says we hold `t`, the account's unsettled positions don't.
        Either the market settled (book the settlement trade through the P&L
        tracker at what Kalshi paid: 0/100 for yes/no, settlement_value for a
        scalar, our own cost for a void) or the user manually offset our lot
        after a standoff (drop the stale accounting entry). `via` names the
        caller on the sink row: the cycle's settle loop or the startup
        reconcile."""
        own = self.pnl.pos.get(t, 0.0)
        try:
            m = (self.client.get_market(t) or {}).get("market") or {}
        except Exception as e:
            log(f"{self.tag} ! settle check failed for {t} ({e}); retry next cycle")
            return
        result = str(m.get("result") or "").lower()
        status = str(m.get("status") or "").lower()
        # Captured before the pops below: this is the entry price the
        # settlement is scored against, and the else-branch destroys it.
        own_avg = self.pnl.avg.get(t, 0.0)
        px: Optional[float] = None
        if result in ("yes", "no"):
            px = 100.0 if result == "yes" else 0.0
        elif result in ("scalar", "void"):
            # SCALAR / VOID (2026-09-29). The sports ladders and escalators
            # (KXNFLFFPTSLADDER, KXNFLESCALATOR*, KXNFLLADDER*) settle
            # "scalar" at a fractional settlement_value_dollars, and so did
            # the early-closed KXBKNUGGETS strikes on 9/10. This used to fall
            # through to the manual-offset branch: all 34 offset rows on
            # 9/6-9/29 were Kalshi scalar settlements, dropped at cost with
            # the settlement leg (pos x (value - avg)) never booked. A void
            # refunds cost, so it books at our own entry price for zero
            # realized. Both wait for Kalshi's final status: the payout is
            # only fixed once the market is finalized.
            if status not in SETTLED_STATUSES:
                log(f"{self.tag} {t}: {result} result but market "
                    f"{status or '?'}; settlement not final, retry next cycle")
                return
            px = own_avg if result == "void" else settlement_value_cents(m)
            if px is None:
                log(f"{self.tag} ! {t}: settled scalar without a readable "
                    f"settlement_value_dollars "
                    f"({m.get('settlement_value_dollars')!r}); retry next cycle")
                return
        elif result:
            # Kalshi decided the market with a result this code cannot value.
            # It is not a manual offset, so keep the entry (still marked and
            # still in the loss halt) and say so each cycle until it can be.
            log(f"{self.tag} ! {t}: unknown settlement result {result!r} "
                f"(market {status or '?'}); own {own:+.0f} kept, retry next cycle")
            return
        if px is not None:
            self.pnl.on_fill(t, "yes", "sell" if own > 0 else "buy", abs(own), px)
            log(f"{self.tag} {t}: settled {result.upper()}; booked {own:+.0f} @ {px:g}c "
                f"(market realized ${self.pnl.realized.get(t, 0.0):+.2f})")
            # Nearly all of this bot's trading P&L lands here — it is a maker
            # that almost never closes a position, so settlement IS the exit.
            # The prose line above was the only record; the manual stitch
            # snapshots are event-level, whole-account and run-when-remembered
            # against an API that now serves ~66 days.
            self._sink("settlements", {
                "ts": datetime.now(timezone.utc).isoformat(),
                "ticker": t, "series": series_of(t),
                "event_ticker": self._event_of(t),
                "result": result,
                "settle_price_cents": px,
                "own_pos_at_settle": own,
                "own_avg_cents": own_avg,
                "market_realized_dollars": self.pnl.realized.get(t, 0.0),
                "market_status": status,
                "settlement_ts": m.get("settlement_ts"),
                "via": via,
            })
        else:
            log(f"{self.tag} {t}: own book {own:+.0f} but account flat and market "
                f"unsettled — manually offset; dropping stale entry")
            # Logged with a distinct result so a manual takeout can never be
            # counted as a settlement in any downstream P&L sum.
            self._sink("settlements", {
                "ts": datetime.now(timezone.utc).isoformat(),
                "ticker": t, "series": series_of(t),
                "event_ticker": self._event_of(t),
                "result": "manual_offset",
                "settle_price_cents": None,
                "own_pos_at_settle": own,
                "own_avg_cents": own_avg,
                "market_realized_dollars": self.pnl.realized.get(t, 0.0),
                "market_status": status,
                "via": via,
            })
            self.pnl.pos.pop(t, None)
            self.pnl.avg.pop(t, None)
        self.state.last_mark.pop(t, None)

    def _mark_from_book(self, t: str, ext_bid: int, ext_ask: int,
                        marked: Set[str]) -> None:
        """The order-book mark of a two-sided EXTERNAL touch: its mid. A book
        MARK_WIDE_SPREAD_CENTS or wider is left out of `marked` instead, so
        _refresh_marks marks it (if held) off the bulk read's last trade
        clamped inside this same external touch -- the order book carries no
        last trade. The caller keeps prev_mid on the mid either way."""
        if not wide_mark_book(ext_bid, ext_ask):
            self.state.last_mark[t] = (ext_bid + ext_ask) / 2.0
            marked.add(t)

    def _refresh_marks(self, marked_this_cycle: Set[str],
                       ext_touch: Optional[Dict[str, Tuple[Optional[int], Optional[int]]]] = None
                       ) -> None:
        """Ensure every open own-book position has a usable YES mark.
        Managed markets with a two-sided external book narrower than
        MARK_WIDE_SPREAD_CENTS were marked at its mid this cycle; anything
        else with inventory gets a bulk market read, marked by bulk_mark_cents
        (the mid of a two-sided book, the last trade clamped inside a wide one
        or to the live side of a one-sided one). A market whose order book was
        read this cycle is judged on that EXTERNAL touch (`ext_touch`, own
        quotes excluded) with the bulk read's last trade. A read with no usable
        price keeps the previous mark."""
        ext_touch = ext_touch or {}
        stale = [t for t, p in self.pnl.pos.items()
                 if abs(p) > 1e-9 and t not in marked_this_cycle]
        for i in range(0, len(stale), 50):
            chunk = stale[i:i + 50]
            try:
                resp = self.client.get_markets(tickers=",".join(chunk), limit=len(chunk))
            except Exception as e:
                log(f"{self.tag} ! mark refresh failed ({e}); stale marks stand")
                return
            for m in (resp.get("markets") or []):
                t = m.get("ticker", "")
                mk = bulk_mark_cents(m, ext_touch.get(t))
                if mk is not None:
                    self.state.last_mark[t] = mk

    def _live_event_slots(self, ev: str, entry: dict,
                          unquotable_now: Set[str]) -> List[str]:
        """The recorded lifetime slots of `ev` that STILL COUNT, pruning the
        ledger of any that no longer do (Jack 2026-09-09).

        A slot keeps counting while EITHER the market earned it by trading
        (gross fills >= EVENT_SLOT_EARNED_FILLS — spent forever, whatever the
        book does later) OR it is still quotable (at least one touch inside
        the band, so it is doing its job now). A market that is BOTH
        barely-traded AND wholly outside the band releases its slot.

        `unquotable_now` only contains markets bulk-read THIS refresh, so a
        slot-holder that vanished from the programs feed is never released on
        missing data — it keeps its slot until it reappears and proves itself
        unquotable. Fail-closed, matching every other screen here."""
        markets = list(entry.get("markets") or [])
        if not EVENT_TOP_N_LIFETIME or EVENT_SLOT_EARNED_FILLS <= 0:
            return markets
        kept, released = [], []
        for t in markets:
            earned = self.pnl.filled.get(t, 0.0) >= EVENT_SLOT_EARNED_FILLS
            if earned or t not in unquotable_now:
                kept.append(t)
            else:
                released.append(t)
        if released:
            entry["markets"] = kept
            for t in released:
                log(f"{self.tag} event slot released on {ev}: {t} "
                    f"(filled {self.pnl.filled.get(t, 0.0):.0f} < "
                    f"{EVENT_SLOT_EARNED_FILLS:g} and both sides out of band) "
                    f"-> {len(kept)}/{event_top_n_for(series_of(t))} spent")
        return kept

    def restore_orphan_metas(self, positions: Dict[str, float]) -> None:
        """After a restart, positions can exist on persisted known tickers
        that are no longer selected and whose MarketMeta died with the old
        process — without a meta they get no reduce-only management and are
        invisible to the event-cap accounting. Rebuild metas for them.

        NO-OP unless WINDDOWN_DROPPED (Jack 2026-09-07): with the wind-down
        off there is nothing to manage on a dropped market — its orders are
        cancelled — and the event-cap accounting no longer needs a meta
        either (event_net reads the own book directly)."""
        if not WINDDOWN_DROPPED:
            return
        missing = [t for t in self.state.known_tickers
                   if abs(positions.get(t, 0.0)) >= REDUCE_ONLY_MIN_CONTRACTS
                   and t not in self.state.selected
                   and t not in self.state.managed_extra
                   # BLOCKLISTED = frozen entirely — not even reduce-only
                   # wind-down (Jack 2026-07-25: the gas retirement's
                   # wind-down joined pinned books, fire-selling +55/+31
                   # longs at 1-8c asks and covering shorts he wanted left
                   # alone). Positions ride to settlement; flatten by hand.
                   and not self._blocked(t)
                   # NO-RENT FREEZE (Jack 2026-07-26, KXRT after its movie
                   # programs expired): a market with no LIVE incentive
                   # program gets no orders either — quotes exist only where
                   # rent exists. Empty programmed set = failsafe open.
                   and (not self.state.programmed or t in self.state.programmed)
                   # CALL-WINDOW FREEZE (Jack 2026-08-06: "sit out completely
                   # during call windows"). Same treatment as blocklisted —
                   # positions ride to settlement, flatten by hand.
                   and not self._call_window_started(self._event_of(t))
                   # only restore inventory that is genuinely OURS — a manual
                   # position on a once-quoted market is the user's business
                   and abs(positions.get(t, 0.0) - self.pnl.pos.get(t, 0.0))
                   < MANUAL_STANDOFF_CONTRACTS]
        if not missing:
            return
        for i in range(0, len(missing), 50):
            chunk = missing[i:i + 50]
            try:
                resp = self.client.get_markets(tickers=",".join(chunk), limit=len(chunk))
            except Exception as e:
                log(f"{self.tag} ! orphan meta read failed ({e}); retry next cycle")
                return
            for m in (resp.get("markets") or []):
                t = m.get("ticker", "")
                self._note_shard(t, m.get("exchange_index"))
                event_ticker = m.get("event_ticker") or t.rsplit("-", 1)[0]
                self.state.managed_extra[t] = MarketMeta(
                    ticker=t, event_ticker=event_ticker, series=t.split("-")[0],
                    dollars_per_day=0.0, program_end=None, target_size=0.0,
                    discount_factor=0.5,
                    cutoff=apply_series_cutoff_adjustments(
                        t.split("-")[0], event_ticker,
                        trade_cutoff_utc(
                            event_ticker,
                            parse_iso_utc(m.get("occurrence_datetime", "")),
                            parse_iso_utc(m.get("expected_expiration_time", ""))),
                        # close_time is what makes the close-anchored rule
                        # (temp close-10) work on THIS producer too; market
                        # is what makes the data-month release guard work here
                        close_time=parse_iso_utc(m.get("close_time", "")),
                        market=m),
                    close_time=parse_iso_utc(m.get("close_time", "")),
                    price_step=market_price_step(m))
                log(f"{self.tag} restored orphan position market {t} "
                    f"(pos {positions.get(t, 0):+.0f}, reduce-only)")

    @staticmethod
    def _call_window_started(event_ticker: str,
                            now_utc: Optional[datetime] = None) -> bool:
        """True once a scheduled call/disclosure has begun for this event, so
        the market must carry NO orders at all — not even reduce-only
        wind-down (Jack 2026-08-06: "sit out completely during call windows").

        This cannot be left to the cutoff. The selection path resolves a call
        time via resolver.resolve(), but restore_orphan_metas builds its
        cutoff from trade_cutoff_utc() alone, which knows nothing about
        EVENT_START_OVERRIDES — so KXEARNINGSMENTIONDKNG-26AUG07, whose call
        ran 16:00 ET on Aug 6, fell back to midnight-ET-of-Aug-7 and kept 7
        reduce-only orders resting 1.2h into the live call.

        Scoped to events with an EVENT_START_OVERRIDES entry (earnings calls
        and disclosure releases) on purpose. Series with no scheduled start —
        rates, gas, rain — keep their wind-down: freezing those would strand
        inventory at settlement instead of working it out, which is a P&L
        change nobody asked for.
        """
        start = EVENT_START_OVERRIDES.get(event_ticker)
        if start is None:
            return False
        now = now_utc or datetime.now(timezone.utc)
        # buffer included: orders are supposed to be GONE this many minutes
        # before the call, so the freeze has to bite inside the buffer too
        return now >= start - timedelta(minutes=OVERRIDE_BUFFER_MIN)

    @staticmethod
    def _event_of(ticker: str) -> str:
        return ticker.rsplit("-", 1)[0]

    def manual_events(self, positions: Dict[str, float]) -> Set[str]:
        """Events the user is trading by hand, from LIVE SIGNALS ONLY: any
        market of the event with a manual position (|account − own book| ≥
        threshold) or a foreign (non-imm) resting order. The bot avoids EVERY
        market of these events, so it never rests where the user's crossing
        order could hit it. Deliberately excludes the standoff set itself
        (downstream state) so a market releases once the real signal clears."""
        events: Set[str] = set()
        if not EVENT_LEVEL_STANDOFF:
            return events

        def coexist(t: str) -> bool:
            return manual_coexist(series_of(t), self._event_of(t))

        for t, v in positions.items():
            # quote_all series (Love Island) and MANUAL_COEXIST_EVENTS: the
            # user explicitly wants the bot in these events, so his POSITIONS
            # there don't yield — only a live order on a specific market does
            # (handled per-market below).
            if coexist(t):
                continue
            if abs(v - self.pnl.pos.get(t, 0.0)) >= MANUAL_STANDOFF_CONTRACTS:
                events.add(self._event_of(t))
        if self.live:
            for t, n in self._foreign_resting.items():
                if n and not coexist(t):
                    events.add(self._event_of(t))
        return events

    def _screen(self, meta: MarketMeta, now_utc: datetime,
                member: bool = False) -> Optional[str]:
        """Hard screens; returns a skip-reason or None if quotable.
        `member`: the 5-min cutoff pre-buffer exists to stop FRESH entry
        seconds before the end — members quote to the true cutoff (Jack
        2026-08-03: "bot stopped quoting 15min before"; the buffer was
        compounding with the 10-min cutoff into an effective 15)."""
        now_ts = now_utc.timestamp()
        if meta.cutoff is not None:
            buf = timedelta(minutes=0 if member else CUTOFF_SCREEN_BUFFER_MIN)
            if now_utc >= meta.cutoff - buf:
                return "cutoff"
        # A mention/broadcast market with NO derivable event window is either
        # tournament-wide (e.g. KXWCMENTION-MENWORLDCUP: broadcasts already
        # running daily — quoting it is quoting through live events) or
        # unparseable. Both mean: no defined safe period, stand down.
        if meta.cutoff is None and \
                any(meta.series.endswith(suf) for suf in ALLOW_SERIES_SUFFIXES):
            return "no_event_window"
        ov = series_override(meta.series)
        if ov and ov.cutoff_from_close_min is not None and meta.close_time is None:
            return "no_event_window"   # close-anchored series with no close time
        min_hours = (ov.min_hours_to_close if ov and ov.min_hours_to_close is not None
                     else MIN_HOURS_TO_CLOSE)
        if meta.close_time is not None and \
                (meta.close_time - now_utc).total_seconds() < min_hours * 3600:
            return "closing"
        if meta.program_end is not None and now_utc >= meta.program_end:
            return "program_over"
        # GasBuddy state gas (2026-09-27): with no fresh read the gate stands
        # the market aside every cycle, so it must not hold one of the
        # MAX_MARKETS slots -- all of Monday (the Tuesday print is not
        # modelled), and any GasBuddy / Kalshi-anchor outage. (The AS test's
        # gas dailies quote plain, 2026-10-25: ASTEST_ENABLE; so do its
        # gas-state daily picks, 2026-10-27.)
        if GB_FAIR_ENABLE and gb_fair_series(meta.series) \
                and not astest_plain_gas(meta.series):
            if not gb_has_read(meta.event_ticker, now_ts):
                return "gb_no_read"
            # ...and a strike whose listed touch the gate rejects right now
            # (a sure strike with a stale touch, or too early in the day to
            # call) must not take one of the event's 3 slots from one that
            # can quote. Transient disagreement between refreshes is the
            # quote loop's stand-aside; this only re-picks the slots.
            if meta.mid_cents is not None and meta.spread_cents is not None:
                half = meta.spread_cents / 2.0
                if gb_gate_reason(meta.ticker, now_ts, meta.mid_cents - half,
                                  meta.mid_cents + half)[0]:
                    return "gb_fair"
        # OpenRouter market share (Jack 2026-10-01: "set max 3 markets per
        # event"): the GasBuddy pair of screens -- no fresh read, or a listed
        # touch the gate rejects on its band -- so a strike the gate would
        # stand aside every cycle never holds one of the event's 3 slots. A
        # stalled feed or the daily-roll hold stays the quote loop's
        # (transient: screening them would churn the slots).
        if share_fair_series(meta.series):
            if not share_has_read(meta.event_ticker, now_ts):
                return "share_no_read"
            if meta.mid_cents is not None and meta.spread_cents is not None:
                half = meta.spread_cents / 2.0
                if share_gate_reason(meta.ticker, now_ts, meta.mid_cents - half,
                                     meta.mid_cents + half)[1].get("reason") == "band":
                    return "share_fair"
        # Data center counts (2026-10-01, DC_GATE_ENABLE): a strike with no
        # fresh read of its state, or one the count has already reached,
        # must not take one of the event's 3 slots.
        if DC_GATE_ENABLE and datacenter_series(meta.series):
            dc_why = dc_screen_reason(meta.ticker, now_ts)
            if dc_why:
                return dc_why
        if meta.mid_cents is None or meta.spread_cents is None:
            return "one_sided"
        if meta.spread_cents > MAX_JOIN_SPREAD_CENTS:
            return "wide"
        # Members are screened against the SAME band they are allowed to quote
        # in (member_price_band); fresh entry keeps the tighter 5-90.
        band_lo, band_hi = (MID_BAND_MEMBER_LO, MID_BAND_MEMBER_HI) if member \
            else (MID_BAND_LO, MID_BAND_HI)
        # A series whose OWN quoting band is wider than the global mid band is
        # screened on its band (sports ladders / escalators 1-99c, Jack
        # 2026-09-26): escalator mids of 2-4c are the product, not a pinned
        # book. A narrower series band never tightens this screen (unchanged).
        band_lo = min(band_lo, series_price_min(meta.series))
        band_hi = max(band_hi, series_price_max(meta.series))
        if sports_ladder_league(meta.series) is not None:
            # the family's EXACT band (0.05-99.5c, subcent_edge_quotes)
            band_lo = min(band_lo, SPORTS_LADDER_PRICE_MIN_EXACT)
            band_hi = max(band_hi, SPORTS_LADDER_PRICE_MAX_EXACT)
        if not (band_lo <= meta.mid_cents <= band_hi):
            return "extreme_mid"
        if MIN_VOLUME_CONTRACTS > 0 and meta.volume < MIN_VOLUME_CONTRACTS:
            # Fresh listings get a pass: mention markets list the day before
            # the game with zero volume, and that pre-event window is exactly
            # the rent we're here for. The anti-junk intent of the volume
            # screen only applies to markets old enough to have traded.
            age_ok = (meta.open_time is not None
                      and (now_utc - meta.open_time).total_seconds() < 24 * 3600)
            if not age_ok:
                return "no_volume"
        if self.state.breaker_until.get(meta.ticker, 0) > now_ts:
            return "breaker"
        if self.state.bench_until.get(meta.ticker, 0) > now_ts:
            return "benched"
        if meta.target_size <= 0:
            return "no_target"
        return None

    # ---- one polling cycle ---------------------------------------------------

    def _reconcile_since(self) -> int:
        """Where the startup reconcile starts looking for unbooked fills: an
        hour before the fill high-water mark this process inherited (a fill
        the killed run read but could not claim sits just under it), and
        never before the oldest fill seen_fill_ids still holds, since a fill
        that WAS booked and then pruned from it would read as unbooked. A
        state file without a high-water mark looks nowhere (fail closed)."""
        if not self._inherited_fill_ts:
            return int(time.time())
        since = self._inherited_fill_ts - 3600
        if self.state.seen_fill_ids:
            since = max(since, min(self.state.seen_fill_ids.values()))
        return int(since)

    def _unbooked_fills(self, t: str, since_ts: int) -> Tuple[List[dict], float]:
        """(own, foreign_net): the fills on `t` since `since_ts` that this bot
        has not booked (fill id not in seen_fill_ids), split by whose order
        they hit. A fill is OURS when its order is in our_order_ids or carries
        our client_order_id prefix -- stamped at placement, so it survives the
        hard kill that loses an order id, and the same test
        _get_resting_orders_global applies to resting orders. foreign_net is
        the signed YES contracts filled on everyone else's orders. Raises on
        a failed read."""
        fills: List[dict] = []
        cursor = None
        for _page in range(10):
            resp = self.client.get_fills(ticker=t, min_ts=since_ts, limit=200,
                                         cursor=cursor)
            batch = resp.get("fills") or []
            fills.extend(batch)
            cursor = resp.get("cursor")
            if not cursor or not batch:
                break
        ours: Dict[str, bool] = {}
        own: List[dict] = []
        foreign = 0.0
        for f in fills:
            fid = f.get("fill_id") or f.get("trade_id") or ""
            if not fid or fid in self.state.seen_fill_ids or f.get("ticker", t) != t:
                continue
            oid = str(f.get("order_id") or "")
            if oid not in ours:
                ours[oid] = bool(oid) and (
                    oid in self.state.our_order_ids
                    or str(((self.client.get_order(oid) or {}).get("order") or {})
                           .get("client_order_id") or "")
                    .startswith(CLIENT_ORDER_PREFIX + "-"))
            if ours[oid]:
                own.append(f)
            else:
                n = float(f.get("count_fp") or f.get("count") or 0)
                foreign += n if (f.get("action") == "buy") == (f.get("side") == "yes") else -n
        return own, foreign

    def _reconcile_orphaned_fills(self, positions: Dict[str, float]) -> None:
        """One-time post-restart cleanup for fills orphaned by an unclean
        shutdown: the bot placed an order, the process was hard-killed before
        the order_id/fill was persisted, so on restart the account holds a
        position the bot's own-book doesn't know — which then reads as "manual"
        and yields the whole event forever (observed 2026-07-14: an orphaned
        +5 LENO fill kept the entire ENGARG event yielded).

        Book those fills as the bot's own, scoped HARD so it can NEVER claim
        the user's manual book: (1) only markets the bot actually quotes
        (known_tickers); (2) only within the per-market position cap — a >cap
        position can't be ours; (3) only fills on OUR orders (OWNERSHIP GATE,
        2026-09-30): a fill not yet booked whose order carries our
        client_order_id prefix is booked at its own price through the normal
        fill path. A divergence with no such fill behind it is left to the
        yield-to-human standoff. Until this gate the reconcile adopted the
        whole account position at the mid: on 9/30 that claimed 22.36 of
        Jack's own contracts on KXMLBSEASONGAMES-27-2425 (a 400-lot pair he
        placed by hand, no client id) as the bot's. Runs on the first trusted
        (non-grace) cycle and once more ~4 min later.

        A market the account holds NOTHING in is not adopted as 0: it goes
        through _settle_or_drop, which books Kalshi's settlement or records a
        manual offset (2026-09-29). Every "->+0" adoption on record (73 itemized
        7/18-9/27) was a market that settled while the bot was down, and
        adopting 0 dropped it with no P&L and no row."""
        adopted, left = [], []
        since = self._reconcile_since()
        now_ts = time.time()
        for t in sorted(self.state.known_tickers):
            acct = positions.get(t, 0.0)
            own = self.pnl.pos.get(t, 0.0)
            if abs(acct - own) < MANUAL_STANDOFF_CONTRACTS:
                continue                      # below standoff threshold: harmless
            if abs(acct) > series_max_position(series_of(t)):
                continue                      # too big to be ours -> it's manual
            if t not in positions:
                self._settle_or_drop(t, via="startup_reconcile")
                continue
            try:
                own_fills, foreign = self._unbooked_fills(t, since)
            except Exception as e:
                log(f"{self.tag} ! startup reconcile: fills read failed for {t} "
                    f"({e}); nothing adopted")
                continue
            if not own_fills:
                left.append(f"{t} own {own:+.1f} vs account {acct:+.1f} "
                            f"({foreign:+.1f} on other orders)")
                continue
            for f in sorted(own_fills, key=self._fill_ts):
                fts = self._fill_ts(f)
                self.state.seen_fill_ids[f.get("fill_id") or f.get("trade_id")] = fts
                if f.get("order_id"):
                    self.state.our_order_ids.setdefault(f["order_id"], float(fts))
                self._book_fill(f, now_ts, toxic=False)
            adopted.append(f"{t} {own:+.1f}->{self.pnl.pos.get(t, 0.0):+.1f} "
                           f"({len(own_fills)} fill(s))")
        if left:
            log(f"{self.tag} startup reconcile: {len(left)} divergence(s) with no "
                f"unbooked fill on our orders, left to the manual standoff: "
                f"{', '.join(left[:8])}" + (" ..." if len(left) > 8 else ""))
        if adopted:
            log(f"{self.tag} startup reconcile: booked orphaned own fills on "
                f"{len(adopted)} market(s) (unclean-shutdown cleanup): "
                f"{', '.join(adopted[:8])}" + (" ..." if len(adopted) > 8 else ""))
            self.alerter.alert(
                "reconcile", f"booked orphaned own fills on {len(adopted)} "
                f"market(s) on restart: {', '.join(adopted[:6])}",
                key="reconcile", urgent=False)
            self._save_persist()

    def _ladder_asks_latch(self, cash: float, now_utc: datetime) -> bool:
        """The ladder / escalator asks' cash switch: on at or over
        SPORTS_LADDER_ASKS_ON_CASH (Jack 2026-10-04: "once cash is over $4k,
        turn on the full ladder/escalator again"), off again under
        SPORTS_LADDER_ASKS_OFF_CASH ("below $2k turn off the ask side just
        like you did today"), unchanged in between. `cash` is the IMM's
        shard's (ladder_cash). Persisted; True when it switches this call."""
        if not (SPORTS_LADDER_ASKS_OFF and SPORTS_LADDER_ASKS_ON_CASH > 0):
            return False
        ts = now_utc.timestamp()
        if _LADDER_ASKS_STATE.get("on_at") is None:
            if cash < SPORTS_LADDER_ASKS_ON_CASH:
                return False
            _LADDER_ASKS_STATE["on_at"] = ts
            self.state.ladder_asks_on_at = ts
            self._save_persist()
            off = (f"off again under ${SPORTS_LADDER_ASKS_OFF_CASH:,.0f}"
                   if SPORTS_LADDER_ASKS_OFF_CASH > 0 else "one-way")
            msg = (f"sports ladders / escalators: ASKS BACK ON -- free cash "
                   f"${cash:,.0f} reached ${SPORTS_LADDER_ASKS_ON_CASH:,.0f}; "
                   f"the family quotes both sides from this cycle ({off})")
            log(f"{self.tag} {msg}")
            self.alerter.alert("ladder_asks_on", msg, key="ladder_asks_on",
                               urgent=False)
            return True
        if SPORTS_LADDER_ASKS_OFF_CASH <= 0 or cash >= SPORTS_LADDER_ASKS_OFF_CASH:
            return False
        _LADDER_ASKS_STATE["on_at"] = None
        self.state.ladder_asks_on_at = 0.0
        self._save_persist()
        msg = (f"sports ladders / escalators: ASKS OFF -- free cash "
               f"${cash:,.0f} fell under ${SPORTS_LADDER_ASKS_OFF_CASH:,.0f}; "
               f"YES bids only from this cycle (resting asks cancelled, longs "
               f"ride) until it reaches ${SPORTS_LADDER_ASKS_ON_CASH:,.0f}")
        log(f"{self.tag} {msg}")
        self.alerter.alert("ladder_asks_off", msg, key="ladder_asks_off",
                           urgent=False)
        return True

    def _check_balance_floor(self, now_utc: datetime) -> bool:
        """True = floor breached and the bot halted. ACCOUNT VALUE (cash +
        Kalshi's valuation of the positions, account_value_dollars) against
        the day's anchor, set on first sight; a failed or partial read (no
        positions value) = no action."""
        try:
            b = self.client.get_balance()
            value = account_value_dollars(b)
            cash = float(b.get("balance_dollars") or 0.0)
        except Exception as e:
            log(f"{self.tag} ! balance read failed ({e}); floor check skipped")
            return False
        lc = ladder_cash(b)
        self._ladder_asks_latch(cash if lc is None else lc, now_utc)
        if value is None:
            log(f"{self.tag} ! balance read carried no portfolio_value; floor check skipped")
            return False
        if value <= 0:
            return False
        if self.state.account_value_day_start <= 0:
            self.state.account_value_day_start = value
            self._acct_reading = (value, value)
            return False
        # for the cycle's "risk:" line (risk_line)
        self._acct_reading = (value, self.state.account_value_day_start)
        drop = self.state.account_value_day_start - value
        if drop < ACCOUNT_DROP_HALT:
            return False
        # until the roll that re-anchors account_value_day_start (_next_roll_utc)
        self.state.halted_until = _next_roll_utc(now_utc).timestamp()
        n = self.cancel_all_bot_orders()
        self._save_persist()
        anchor = self.state.account_value_day_start
        # logged + kept for the daily summary; the EMAIL is the dedicated one below
        self.alerter.alert(
            "balance_floor", f"ACCOUNT VALUE dropped ${drop:.0f} since the "
            f"daily anchor (${anchor:.0f} -> ${value:.0f}: "
            f"cash ${cash:.0f} + positions ${value - cash:.0f}) "
            f">= ${ACCOUNT_DROP_HALT:.0f}; cancelled {n} IMM orders and halted "
            f"until the {SUMMARY_HOUR_CT}am CT roll. NOTE: the account is shared — the cause may be "
            f"another bot, manual trading, or a withdrawal. --clear-halt to "
            f"resume deliberately.", key="balance_floor", urgent=False)
        if self.alerter.enabled:
            subject, body = balance_halt_email(
                drop, anchor, value, cash, n, self.state.halted_until,
                self.state.pnl_today_last, self.live)
            if self.alerter.send_message(body, subject=subject):
                log(f"{self.tag} balance-guard halt email sent: {subject}")
        return True

    def _apply_event_live_clear(self) -> None:
        """Consume EVENT_LIVE_CLEAR_FILE (see its definition)."""
        try:
            with open(EVENT_LIVE_CLEAR_FILE, encoding="utf-8") as f:
                evs = [ln.split("#", 1)[0].strip() for ln in f]
        except OSError as e:
            log(f"{self.tag} ! {EVENT_LIVE_CLEAR_FILE} unreadable ({e})")
            return
        for ev in (e for e in evs if e):
            had = ev in self.state.event_live_halt
            self.state.event_live_halt.pop(ev, None)
            self.state.event_depth_halt.pop(ev, None)
            self.state.event_fill_strikes.pop(ev, None)
            self.state.event_fill_strike_ts.pop(ev, None)
            self.state.event_depth_ignore.pop(ev, None)
            log(f"{self.tag} event-live clear: {ev} "
                f"({'live confirm released' if had else 'was not live-confirmed'})")
        try:
            os.replace(EVENT_LIVE_CLEAR_FILE, EVENT_LIVE_CLEAR_FILE + ".done")
        except OSError as e:
            log(f"{self.tag} ! could not retire {EVENT_LIVE_CLEAR_FILE} ({e})")
        self._save_persist()

    def run_cycle(self, fast_only: bool = False) -> None:
        # fast_only = a FAST-LANE mini-cycle (see FAST_LANE_SECS): same managed
        # set, same resting read, but only fast-lane series are (re)quoted and
        # everything periodic (universe refresh, accrual, bench, watchdog,
        # cycle log, counters) is deferred to the next full cycle.
        now_utc = datetime.now(timezone.utc)
        now_ts = now_utc.timestamp()
        self._heartbeat = now_ts
        self._cycle_saved = False          # (write_status's save, below)
        # Book-log rows from this cycle join cycle_log on (cycle_ts, ticker):
        # same format as the cycle_log `ts` column.
        self._book_cycle_ts = now_utc.strftime('%Y-%m-%dT%H:%M:%SZ')

        # The 5am-CT roll (summary, counters, loss budgets, balance anchor)
        # runs FIRST, so the first cycle of a roll day -- full or fast-lane --
        # measures the fresh day before any halt or loss check. Run after the
        # cycle, a halt lasting until the roll woke into yesterday's counters
        # and tripped again (2026-10-01).
        self.alerter.maybe_daily_summary(now_utc, self.build_daily_summary)

        if os.path.exists(EVENT_LIVE_CLEAR_FILE):
            self._apply_event_live_clear()
        if os.path.exists(HALT_FILE):
            n = self.cancel_all_bot_orders()
            log(f"{self.tag} HALT file present ({HALT_FILE}); cancelled {n}; idle")
            return
        if self.state.halted_until > now_ts:
            log(f"{self.tag} daily-loss halt active until "
                f"{datetime.fromtimestamp(self.state.halted_until, timezone.utc)}; idle")
            return
        # Account-value hard floor: shared-account backstop against ANY
        # bot's malfunction (or this one's blind spots). Anchored at the
        # daily roll; deposits/withdrawals also move it — the alert says so.
        self._acct_reading = None       # this cycle's reading only (risk_line)
        if ACCOUNT_DROP_HALT > 0 and self.live and self._check_balance_floor(now_utc):
            return

        # Fills -> own book FIRST, before the positions read. Matched by ORDER
        # OWNERSHIP (our persisted order ids): the other bots AND the user's
        # manual trades share this account and must not pollute our P&L.
        # Ordering is load-bearing: booking fills AFTER fetch_positions left a
        # window where the account showed a fresh fill our own book didn't
        # know yet — the manual-divergence check then mistook the bot's OWN
        # fill for the user trading and dumped the whole event's quotes
        # (observed live 2026-07-14: a 5-lot TRUM fill deselected all 14
        # LATENIGHT markets and stray-cancelled 59 resting orders).
        self._cycle_cancelled = set()      # this cycle's cancels (WS view)
        self._cycle_amended = {}           # this cycle's amends: id -> new cents
        self._cycle_amended_ct = {}        # ...and the size each one set
        new_fills = self.fetch_new_fills()
        # the fills sink's join sees the whole batch (newest first) before
        # any of it is logged; analytics only, never raises
        self._join_note_fills(new_fills)
        for f in new_fills:
            try:
                self._book_fill(f, now_ts)
            except Exception as e:
                log(f"{self.tag} ! unparseable fill skipped: {e}")
        self._join_prune(now_ts)
        # lock the fills that opened a position, with resting maker legs on
        # the markets that price them (COMP_HEDGE_MODE / LOCK_MODE)
        self._comp_hedge_run(now_ts)
        # WebSocket feed events since the last look (2026-10-03): drained so
        # they do not pile up; never a cycle error
        try:
            self._ws_process_events(now_ts, in_cycle=True)
        except Exception as e:
            log(f"{self.tag} ! WS event handling failed: {e}")

        positions = self.fetch_positions()
        # Post-wake grace: reads right after a sleep can SUCCEED with garbage
        # (network up, DNS not yet — partial positions/orders), which once
        # standoff-flagged 113/114 candidates as "manual". Freeze standoff
        # state changes and the universe selection until reads are trusted;
        # existing quotes keep being managed against the current selection.
        in_grace = now_ts < self.wake_grace_until
        if in_grace:
            log(f"{self.tag} wake grace: standoffs + universe frozen "
                f"({self.wake_grace_until - now_ts:.0f}s left)")
        # One-time orphaned-own-fill cleanup, BEFORE manual_events reads the
        # own-book — so an orphaned fill can't spend even one cycle masquerading
        # as manual. Deferred out of wake grace (positions must be trusted).
        # TWO-SHOT: fills can land on a killed run's not-yet-swept orders AFTER
        # the first pass reads positions (observed 2026-07-19: 3 orphans missed
        # because the kill hit mid-placement-wave), so re-run once ~4 min later;
        # the known_tickers + cap scoping makes the repeat adoption safe.
        if not self._reconciled and not in_grace and self.live and not fast_only:
            self._reconcile_orphaned_fills(positions)
            self._reconciled = True
            self._reconcile_recheck_at = now_ts + 240
        elif (self._reconciled and self._reconcile_recheck_at
                and now_ts >= self._reconcile_recheck_at
                and not in_grace and self.live and not fast_only):
            self._reconcile_recheck_at = 0.0
            self._reconcile_orphaned_fills(positions)
        # Release standoffs whose manual activity is gone — the market's own
        # divergence/foreign-order must be clear AND no sibling market of its
        # event is still manual (event-level yield). The yielded market never
        # re-enters the managed loop, so it must be released here.
        manual_evts = self.manual_events(positions)
        if not in_grace and not fast_only:
            for st in list(self.state.manual_standoff):
                manual = abs(positions.get(st, 0.0) - self.pnl.pos.get(st, 0.0))
                foreign_n = self._foreign_resting.get(st, 0) if self.live else 0
                if (manual < MANUAL_STANDOFF_CONTRACTS and not foreign_n
                        and self._event_of(st) not in manual_evts):
                    self.state.manual_standoff.pop(st, None)
                    log(f"{self.tag} {st}: manual activity cleared; market eligible again")
            _u_t0, _u_at, _u_c0 = time.time(), self.state.universe_at, dict(self._ws_cand)
            self.refresh_universe(now_utc, positions)
            if self.state.universe_at != _u_at:       # a refresh ran
                self._note_universe_refresh(_u_t0, time.time(), _u_c0)
        if not fast_only:
            self.restore_orphan_metas(positions)

        # The data center counts gate a market within a cycle of a count
        # change, not a universe refresh later (cheap mtime check).
        if DC_GATE_ENABLE:
            load_dc_fair()
        # Managed set = selected + (only when the wind-down is armed) any
        # market we still hold inventory in. With WINDDOWN_DROPPED off — the
        # default since 2026-09-07 — a dropped market is simply unmanaged,
        # and the stray-order sweep below cancels whatever is resting on it.
        managed: Dict[str, MarketMeta] = dict(self.state.selected)
        if not WINDDOWN_DROPPED and self.state.managed_extra:
            log(f"{self.tag} dropped-market wind-down is off: releasing "
                f"{len(self.state.managed_extra)} held market(s) to the "
                f"stray-order sweep "
                f"({', '.join(sorted(self.state.managed_extra)[:6])}"
                + (" ..." if len(self.state.managed_extra) > 6 else "") + ")")
            self.state.managed_extra.clear()
        for t, meta in list(self.state.managed_extra.items()):
            if self._blocked(t):
                # frozen series (see restore_orphan_metas): flush any entry
                # that predates the blocklisting so no wind-down orders rest
                self.state.managed_extra.pop(t, None)
            elif self.state.programmed and t not in self.state.programmed:
                # NO-RENT FREEZE: the market's incentive program ended, so
                # wind-down quoting ends with it (Jack 2026-07-26, KXRT).
                # Re-programming re-admits it through normal selection.
                self.state.managed_extra.pop(t, None)
            elif self._call_window_started(meta.event_ticker, now_utc):
                # CALL-WINDOW FREEZE: the scheduled call has begun. Drop the
                # meta so the market goes unmanaged and the stray-order sweep
                # cancels whatever is still resting on it.
                self.state.managed_extra.pop(t, None)
            elif abs(positions.get(t, 0.0)) < REDUCE_ONLY_MIN_CONTRACTS:
                self.state.managed_extra.pop(t, None)
            elif t not in managed:
                managed[t] = meta
        if WINDDOWN_DROPPED:
            for t in list(self.state.selected):
                # remember metas for later reduce-only management
                if abs(positions.get(t, 0.0)) >= REDUCE_ONLY_MIN_CONTRACTS:
                    self.state.managed_extra[t] = self.state.selected[t]

        self.state.known_tickers |= set(managed)
        # Prune dead entries (unmanaged, flat) so the set stays bounded.
        self.state.known_tickers &= (set(managed) | set(positions))
        # WebSocket books follow the managed set (IMM_WS != off, 2026-10-03),
        # plus the last universe refresh's candidates (WS_CANDIDATES)
        if self._ws is not None:
            try:
                self._ws_managed_last = set(managed)
                self._ws.set_markets(self._ws_managed_last | self._ws_cand_want)
            except Exception as e:
                log(f"{self.tag} ! WS market sync failed: {e}")
        # Settle-or-drop own-book entries whose market vanished from the
        # unsettled-positions read. A settlement is REAL P&L that the fill
        # stream never reports — without booking it, a gapped position riding
        # to settlement is invisible to the loss halt (review-confirmed P0).
        for pt in list(self.pnl.pos):
            if abs(self.pnl.pos[pt]) > 1e-9 and pt not in positions and pt not in managed:
                self._settle_or_drop(pt)
        # (Fills were booked at the top of the cycle, before the positions
        # read — see the ordering note there.)
        # TODAY's realized P&L (lifetime minus the daily-roll baseline). The
        # LOSS HALT itself runs after the quoting loop, where fresh marks make
        # unrealized losses visible too — realized-only was blind to gapped
        # inventory riding to settlement (review-confirmed P0).
        realized = self.pnl.total_realized() - self.state.realized_baseline

        resting = self.fetch_resting_orders(now_ts)   # populates _foreign_resting
        # when that read finished (WS view rebuild: fills after it come off;
        # stamped at the END of a paged read, so a fill during it can only be
        # under-subtracted -- a missed sweep trip, never a false one)
        self._resting_read_at = time.time()
        own_by_ticker: Dict[str, List[Tuple[str, int, float]]] = {}
        own_exact_by_ticker: Dict[str, List[Tuple[str, float, float]]] = {}
        for o in resting:
            parsed = order_yes_book_cents(o)
            if parsed is not None:
                own_by_ticker.setdefault(o.get("ticker", ""), []).append(
                    (parsed[0], parsed[1], order_remaining(o)))
                _ox = order_yes_exact_cents(o)
                own_exact_by_ticker.setdefault(o.get("ticker", ""), []).append(
                    (parsed[0], _ox if _ox is not None else float(parsed[1]),
                     order_remaining(o)))
        # book log: the next universe refresh's candidate rows read our own
        # orders from THIS exchange read (a reference; the dict is rebuilt
        # every cycle and never mutated after this loop)
        self._book_own_exch = own_exact_by_ticker if self.live else {}
        # a complement lead reads its twin's book without our own orders there
        # (COMP_LEAD_MODE): this cycle's exchange read
        self._comp_own = own_by_ticker if self.live else {}
        # Events the user is trading by hand THIS cycle (foreign orders now
        # fresh). The per-market loop below yields every market of these.
        manual_evts = self.manual_events(positions)

        # PROFIT LOCK legs (lock_leg_order) belong to the lock engine: counted
        # above among our own orders, never kept, amended or cancelled below
        self._lock_resting = {str(o.get("order_id") or ""): o for o in resting
                              if lock_leg_order(o)}
        if self._lock_resting:
            resting = [o for o in resting if not lock_leg_order(o)]

        # Cancel resting orders on markets we no longer manage at all.
        managed_set = set(managed)
        # (a market no longer managed has no complement lead left to judge)
        self._comp_lead_px = {k: v for k, v in self._comp_lead_px.items()
                              if k in managed_set}
        self._fair_close_px = {k: v for k, v in self._fair_close_px.items()
                               if k in managed_set}
        stray = [o for o in resting if o.get("ticker") not in managed_set]
        for o in stray:
            if self.cancel_order(o.get("order_id", ""),
                                 reason="stray_unmanaged"):
                self.state.cancelled_today += 1
        if stray:
            resting = [o for o in resting if o.get("ticker") in managed_set]
            log(f"{self.tag} cancelled {len(stray)} stray orders on unmanaged markets")
        # Trackers for markets we no longer manage are stale — a months-old
        # prev_mid would fire a phantom move-breaker on re-selection.
        for d in (self.state.prev_mid, self.state.prev_pos, self.state.cutoff_ts):
            for t in [k for k in d if k not in managed_set]:
                d.pop(t, None)

        # Event exposure: net contracts per event across managed markets,
        # counted from the BOT'S OWN book — the user's manual positions
        # (on these or sibling markets of the event) are his risk budget,
        # not the bot's (user decision 2026-07-11).
        # Counted over the OWN BOOK, not the managed set (2026-09-07): with
        # the dropped-market wind-down off, a market we still hold inventory
        # in is no longer managed, and iterating `managed` would have made
        # that inventory invisible to its own event's cap — the bot could
        # then rebuild the same exposure on a sibling strike. Every own-book
        # position on a managed event counts, quoted or not.
        event_net: Dict[str, float] = {}
        managed_events = {m.event_ticker for m in managed.values()}
        _ev_of = {t: m.event_ticker for t, m in managed.items()}
        for t, p in self.pnl.pos.items():
            if abs(p) < 1e-9:
                continue
            ev = _ev_of.get(t) or self._event_of(t)
            if ev in managed_events:
                event_net[ev] = event_net.get(ev, 0.0) + p
        for ev in managed_events:
            event_net.setdefault(ev, 0.0)
        event_room_buy = {e: event_cap_contracts(e) - n for e, n in event_net.items()}
        event_room_sell = {e: event_cap_contracts(e) + n for e, n in event_net.items()}
        # A series' own side cut (SIDE_MULT_SERIES under 1) cuts that side's
        # event room by the same factor, as the quote loop cuts its position
        # room (side_cut_room): on a wide event the per-market share binds
        # before the ladder -- ~39 a word on a 35-word KXTRUMPMENTION event,
        # where the ladder's own cut left the bids at their old size
        # (2026-10-27, both Trump mention series at half bids).
        for e in event_room_buy:
            event_room_buy[e], event_room_sell[e] = side_cut_room(
                series_of(e), event_room_buy[e], event_room_sell[e])
        # Orders preserved on blind markets never enter `desired`, so charge
        # their resting size against the event budget up front — otherwise
        # sibling markets would hand out the room those orders may consume.
        blind_prev = {t for t, n in self.state.blind_streak.items() if n > 0}
        for o in resting:
            t = o.get("ticker", "")
            if t in blind_prev and t in managed:
                parsed = order_yes_book_cents(o)
                if parsed is None:
                    continue
                if self._is_pad_price(parsed[0], parsed[1]):
                    continue      # pads don't charge event room (see below)
                ev = managed[t].event_ticker
                if parsed[0] == "bid":
                    event_room_buy[ev] = event_room_buy.get(ev, event_cap_contracts(ev)) \
                        - order_remaining(o)
                else:
                    event_room_sell[ev] = event_room_sell.get(ev, event_cap_contracts(ev)) \
                        - order_remaining(o)
        # Per-event share: split remaining room across that event's quoted
        # markets, best-paying first (computed as we iterate).
        event_markets_left: Dict[str, int] = {}
        for t, meta in managed.items():
            event_markets_left[meta.event_ticker] = \
                event_markets_left.get(meta.event_ticker, 0) + 1

        desired: List[Quote] = []
        blind: Set[str] = set()
        # quake markets HELD this cycle (a fresh detection awaits NEIC): like
        # blind markets their resting bids never enter `desired`, so the diff
        # must preserve them. No up-front event-room charge is needed: a
        # detection holds every strike of the family at once, so no sibling
        # hands out room those bids could consume.
        quake_held: Set[str] = set()
        # ...of those, the ask strikes whose ask may still rest (renewable)
        quake_ask_renew: Set[str] = set()
        marked: Set[str] = set()          # tickers marked from live books this cycle
        # live-event depth gate, per-cycle books: events seen thin this
        # cycle, and per-event count of gated markets that read healthy —
        # the resume path requires EVERY managed market healthy this cycle.
        event_depth_thin: Set[str] = set()
        event_depth_ok: Dict[str, int] = {}
        # open-scan tripwire victims this cycle: no quotes at all this cycle
        # (siblings later in the play order included); reduce-only wind-down
        # begins next cycle through managed_extra
        scan_evicted_now: Set[str] = set()
        # per-market external touch this cycle — the asymmetric-chase bound
        # in diff_orders (keep aggressive-drifted rungs while not leading)
        touch_map: Dict[str, Tuple[Optional[int], Optional[int]]] = {}
        cycle_rows: List[str] = []        # cycle-logger panel (η/J calibration data)
        self._guard_now = {}              # guard skips seen THIS cycle (analytics)
        reward_frac_sum = 0.0
        cycle_rate: Dict[str, float] = {}   # ticker -> live est $/day this cycle
        quoted = 0
        # Round-robin across events (best-paying event first), NOT a flat
        # $/day sort: with many events managed, MAX_PLACEMENTS_PER_CYCLE would
        # be fully consumed by the top events every cycle and the tail (a
        # selected low-$/day event like AQI) never got reached — it stayed
        # selected but placed zero orders and earned nothing. Interleaving
        # guarantees every event's best markets are placed before any event's
        # deeper markets, so the per-cycle cap is shared fairly. Per-event
        # budget/share logic below is unchanged (it decrements per event).
        by_event: Dict[str, List[MarketMeta]] = {}
        for _m in managed.values():
            by_event.setdefault(_m.event_ticker, []).append(_m)
        # A depth halt's already-out-of-band strikes (event_depth_ignore,
        # 2026-10-06), taken on the first cycle that sees the halt from the
        # mids it found: the resume pass counts them as not blocking.
        for _ev in self.state.event_depth_halt:
            if _ev not in self.state.event_depth_ignore and _ev in by_event:
                self.state.event_depth_ignore[_ev] = sorted(
                    _m.ticker for _m in by_event[_ev]
                    if self.state.prev_mid.get(_m.ticker) is not None
                    and not (series_price_min(_m.series)
                             <= self.state.prev_mid[_m.ticker]
                             <= series_price_max(_m.series)))
        # Near-cliff markets lead their event (NEAR_CLIFF_ROOM_PRIORITY,
        # 2026-09-27) so they claim event room before any sibling; the event
        # order itself still follows the event's best pool.
        for _grp in by_event.values():
            _grp.sort(key=lambda m: (not self._room_priority(m), -m.dollars_per_day))
        _event_order = sorted(
            by_event, key=lambda e: -max(m.dollars_per_day for m in by_event[e]))
        order_of_play: List[MarketMeta] = []
        _depth = 0
        while any(_depth < len(by_event[e]) for e in _event_order):
            for e in _event_order:
                if _depth < len(by_event[e]):
                    order_of_play.append(by_event[e][_depth])
            _depth += 1
        # this cycle's book-read REST budget (BOOK_REST_BUDGET_SECS)
        self._book_rest = {"spent": 0.0, "fails": 0, "off": "", "skipped": 0}
        # ANNOUNCEMENT HALT (2026-10-19, MENTION_ANNOUNCE_SERIES): how far our
        # own position moved across each such event since its markets were
        # last quoted -- measured before the loop updates prev_pos -- and the
        # events whose burst this cycle has already counted
        announce_moves: Dict[str, float] = {}
        announce_counted: Set[str] = set()
        if not fast_only and MENTION_ANNOUNCE_SERIES:
            for _am in order_of_play:
                if mention_announce_series(_am.series):
                    _ap = self.state.prev_pos.get(_am.ticker)
                    if _ap is not None:
                        announce_moves[_am.event_ticker] = (
                            announce_moves.get(_am.event_ticker, 0.0)
                            + abs(self.pnl.pos.get(_am.ticker, 0.0) - _ap))
        for meta in order_of_play:
            # Fast tick: only fast-lane series are (re)quoted; everything else
            # is untouched this tick (its resting orders are preserved through
            # the diff below — see `preserve`).
            if fast_only and not series_fast_lane(meta.series):
                continue
            t = meta.ticker
            ev = meta.event_ticker
            pos = positions.get(t, 0.0)
            n_left = max(event_markets_left.get(ev, 1), 1)
            event_markets_left[ev] = n_left - 1
            # a near-cliff market may take the event's WHOLE remaining room
            # for its (boosted) ladder; everyone else splits what is left
            # ...and so may a market that led last cycle (COMP_LEAD_MAX_POSITION)
            split = 1 if (self._room_priority(meta) or t in self._comp_lead_px) else n_left
            share_buy = max(event_room_buy.get(ev, event_cap_contracts(ev)), 0.0) / split
            share_sell = max(event_room_sell.get(ev, event_cap_contracts(ev)), 0.0) / split

            # YIELD TO THE HUMAN: account position diverging from the bot's
            # own book, or a non-imm resting order here, means the user is
            # trading this market by hand — cancel our quotes and stand off
            # until the manual activity is gone. Without this, skew logic
            # would passively unwind his bets and STP would eat his orders.
            quote_all = (series_override(meta.series) or SeriesOverride()).quote_all
            coexist = manual_coexist(meta.series, meta.event_ticker)
            own_pos = self.pnl.pos.get(t, 0.0)
            manual_pos = pos - own_pos
            foreign_n = self._foreign_resting.get(t, 0) if self.live else 0
            event_manual = (meta.event_ticker in manual_evts) and not coexist
            pos_manual = (abs(manual_pos) >= MANUAL_STANDOFF_CONTRACTS) and not coexist
            # quote_all (Love Island) and MANUAL_COEXIST_EVENTS: yield a market
            # ONLY when the user has a live order resting on it (direct
            # order-collision risk); his positions and sibling markets never
            # stop the bot there.
            if foreign_n or pos_manual or event_manual:
                if t not in self.state.manual_standoff:
                    if in_grace:
                        # Suspect post-wake read: don't record the standoff or
                        # cancel anything off it — skip this market this cycle
                        # and re-evaluate on trusted data. A REAL new manual
                        # conflict yields at most WAKE_GRACE_SECS later.
                        log(f"{self.tag} {t}: manual signal during wake grace "
                            f"(foreign={foreign_n}, manual pos {manual_pos:+.0f}); "
                            f"deferring judgement")
                        self._gskip(t, "manual_grace", lambda: dict(foreign=foreign_n, manual_pos=round(manual_pos, 2), event_manual=event_manual, pos_manual=pos_manual))
                        continue
                    self.state.manual_standoff[t] = now_ts
                    why = ("elsewhere in event " + meta.event_ticker) if event_manual \
                        and not (foreign_n or pos_manual) \
                        else f"foreign orders={foreign_n}, manual pos {manual_pos:+.0f}"
                    self.alerter.alert(
                        "manual_standoff",
                        f"{t}: manual activity detected ({why}); yielding",
                        key=t, urgent=False)
                n = self.cancel_market_orders(t, resting)
                if n:
                    log(f"{self.tag} {t}: cancelled {n} quotes, yielding to manual")
                self.state.selected.pop(t, None)
                self.state.managed_extra.pop(t, None)
                self._gskip(t, "manual_yield", lambda: dict(foreign=foreign_n, manual_pos=round(manual_pos, 2), pos=pos, own_pos=own_pos, event_manual=event_manual, pos_manual=pos_manual, quote_all=quote_all, n_cx=n))
                continue
            self.state.manual_standoff.pop(t, None)
            if t in scan_evicted_now:
                self._gskip(t, "scan_evicted")
                continue

            reduce_only = t not in self.state.selected
            # Registry for place_order: exchange-side expiration is capped at
            # the cutoff so resting orders cannot fill past event start.
            if meta.cutoff is not None:
                self.state.cutoff_ts[t] = meta.cutoff.timestamp()
            else:
                self.state.cutoff_ts.pop(t, None)
            if meta.cutoff is not None:
                if now_utc >= meta.cutoff:
                    n = self.cancel_market_orders(t, resting)
                    if n:
                        log(f"{self.tag} {t}: event-start cutoff passed; cancelled {n}")
                    self.state.selected.pop(t, None)
                    self.state.managed_extra.pop(t, None)
                    self._gskip(t, "cutoff_passed", lambda: dict(cutoff=meta.cutoff.isoformat(), n_cx=n))
                    continue
                if (meta.cutoff - now_utc).total_seconds() \
                        < series_pre_cutoff_reduce_only_secs(meta.series):
                    reduce_only = True
            # AAA PRINT BLACKOUT: a recurring scheduled release reprices this
            # book, so stand fully aside across it and resume after. Unlike
            # the cutoff this does NOT deselect — the market is still ours,
            # it just holds no orders while the print lands. The CPI pilot's
            # weekday 08:25-11:05 ET window runs through the same path.
            if series_in_blackout(meta.series, now_utc):
                n = self.cancel_market_orders(t, resting)
                cpi = meta.series in CPI_PILOT_SERIES
                ust = meta.series in UST_EARLY_BLACKOUT_SERIES   # 10Y 06-07 ET (2026-10-22)
                if n:
                    log(f"{self.tag} {t}: "
                        + ("CPI pilot release blackout" if cpi else
                           "Treasury 06-07 ET blackout" if ust else "AAA print blackout")
                        + f"; cancelled {n}")
                self._gskip(t, "cpi_blackout" if cpi else "ust_blackout" if ust else "aaa_blackout", lambda: dict(n_cx=n))
                continue
            # STATE STATISTICS RELEASE PAUSE (2026-10-22): the same stand-aside
            # around each release of the agency the market's rules cite
            rel = series_release_window(meta.series, now_utc)
            if rel is not None:
                n = self.cancel_market_orders(t, resting)
                if n:
                    log(f"{self.tag} {t}: release pause ({rel[0]}, "
                        f"{rel[1].astimezone(ET):%m-%d %H:%M} ET); cancelled {n}")
                self._gskip(t, "release_pause", lambda: dict(n_cx=n, release=rel[0], at=rel[1].isoformat()))
                continue
            if meta.close_time is not None and \
                    (meta.close_time - now_utc).total_seconds() \
                    < series_min_hours_to_close(meta.series) * 3600:
                # Series-aware (hourly weather lives <1h; global default would
                # silently drop every KXTEMP market right after selection).
                self.cancel_market_orders(t, resting)
                self.state.selected.pop(t, None)
                self.state.managed_extra.pop(t, None)
                self._gskip(t, "closing", lambda: dict(close_time=meta.close_time.isoformat(), hours_left=round((meta.close_time - now_utc).total_seconds() / 3600.0, 3), min_hours=series_min_hours_to_close(meta.series)))
                continue
            if self.state.breaker_until.get(t, 0) > now_ts:
                self._gskip(t, "breaker_cooldown", lambda: dict(until=self.state.breaker_until.get(t)))
                continue

            # Fill-burst breaker BEFORE quoting: a large move of OUR OWN book
            # in one cycle means someone is sweeping our ladder (news/insider).
            # Own-book delta, not account delta — the user's manual trades on a
            # nearby market must not false-alarm this.
            prev = self.state.prev_pos.get(t)
            # GATED FILL TRIPWIRE (Jack 2026-09-01 — see the live-event gate
            # config block, point 5): fills on a gated market ARE the
            # adverse selection the gate exists to stop, and on these
            # junk-stacked books they are the only signal that cannot be
            # masked. First burst stands the WHOLE event down (resumable);
            # the EVENT_FILL_HALT_STRIKES-th confirms it LIVE permanently.
            # Independent of IMM_BREAKERS, and ahead of the per-market
            # breaker so the event-wide response owns gated series.
            if (series_event_depth_gated(meta.series) and prev is not None
                    and abs(own_pos - prev) >= EVENT_FILL_HALT_CONTRACTS
                    and event_live_gate_armed(meta.event_ticker, now_ts)):
                last_burst = self.state.event_fill_strike_ts.get(ev)
                if EVENT_FILL_STRIKE_TTL_SECS > 0 and (
                        last_burst is None
                        or now_ts - last_burst > EVENT_FILL_STRIKE_TTL_SECS):
                    self.state.event_fill_strikes.pop(ev, None)   # expired
                strikes = self.state.event_fill_strikes.get(ev, 0) + 1
                self.state.event_fill_strikes[ev] = strikes
                self.state.event_fill_strike_ts[ev] = now_ts
                event_depth_thin.add(ev)
                self.state.event_depth_halt[ev] = now_ts
                confirmed = strikes >= EVENT_FILL_HALT_STRIKES
                if confirmed:
                    self.state.event_live_halt.setdefault(ev, now_ts)
                n_cx = 0
                for m2 in by_event.get(ev, [meta]):
                    n_cx += self.cancel_market_orders(m2.ticker, resting)
                ev_ticks = {m2.ticker for m2 in by_event.get(ev, [meta])}
                desired = [q for q in desired if q.ticker not in ev_ticks]
                self.alerter.alert(
                    "event_fill",
                    f"{ev}: {t} own book moved {own_pos - prev:+.0f} in one "
                    f"cycle — getting filled on a gated event; standing the "
                    f"whole event down "
                    + ("PERMANENTLY (live confirmed, "
                       f"burst {strikes})" if confirmed else
                       f"(burst {strikes}/{EVENT_FILL_HALT_STRIKES})")
                    + f"; cancelled {n_cx}", key=ev)
                self.state.prev_pos[t] = own_pos
                self._gskip(t, "event_fill_tripwire", lambda: dict(own_pos=own_pos, prev_pos=prev, strikes=strikes, confirmed=confirmed, n_cx=n_cx))
                continue
            # OPEN-SCAN FILL TRIPWIRE (2026-09-05, see the SCAN_* block; OFF
            # unless IMM_SCAN_FILL_HALT > 0): being swept on a scan member
            # IS the adverse selection the tier's screens exist to avoid —
            # the whole event leaves the tier for good. Independent of
            # IMM_BREAKERS, ahead of the per-market breaker so the
            # event-wide response owns scan members.
            if (SCAN_FILL_HALT_CONTRACTS > 0 and t in self.state.scan_members
                    and prev is not None
                    and abs(own_pos - prev) >= SCAN_FILL_HALT_CONTRACTS):
                self._scan_evict_event(
                    ev, f"{t} own book moved {own_pos - prev:+.0f} in one cycle",
                    by_event, resting, desired, now_ts)
                scan_evicted_now.update(m2.ticker for m2 in by_event.get(ev, [meta]))
                self.state.prev_pos[t] = own_pos
                self._gskip(t, "scan_fill_tripwire", lambda: dict(own_pos=own_pos, prev_pos=prev))
                continue
            if (BREAKERS_ENABLED and prev is not None
                    and abs(own_pos - prev) >= FILL_BURST_CONTRACTS):
                self.state.breaker_until[t] = now_ts + FILL_BURST_COOLDOWN_SECS
                n = self.cancel_market_orders(t, resting)
                self.alerter.alert(
                    "fill_burst", f"{t}: our book moved {own_pos - prev:+.0f} in one "
                    f"cycle; cancelled {n} orders, standing down "
                    f"{FILL_BURST_COOLDOWN_SECS // 60}min", key=t, urgent=False)
                self.state.prev_pos[t] = own_pos
                self._gskip(t, "fill_burst", lambda: dict(own_pos=own_pos, prev_pos=prev, n_cx=n))
                continue
            self.state.prev_pos[t] = own_pos

            try:
                # REST exactly as before in shadow / off; in shadow the WS
                # book is compared with it (2026-10-03, _read_book)
                ob = self._read_book(t)
                yes_levels, no_levels = orderbook_levels(ob)
                self.state.blind_streak.pop(t, None)
            except BookRestOff:
                # this cycle's REST budget is spent (BOOK_REST_BUDGET_SECS):
                # the market keeps its quotes as they rest, and its blind
                # streak does NOT advance -- an outage must not ripen into
                # the 3-cycle cancel
                blind.add(t)
                if self._book_rest is not None:
                    self._book_rest["skipped"] += 1
                self._book_rest_stats["skipped"] += 1
                _why = (self._book_rest or {}).get("off", "")
                self._gskip(t, "rest_off", lambda: dict(why=_why))
                continue
            except Exception as e:
                self._note_net_error(e)         # (UNIVERSE_NET_GUARD)
                streak = self.state.blind_streak.get(t, 0) + 1
                self.state.blind_streak[t] = streak
                if streak <= BLIND_PRESERVE_CYCLES:
                    blind.add(t)
                    log(f"{self.tag} ! orderbook failed for {t} ({e}); blind "
                        f"{streak}/{BLIND_PRESERVE_CYCLES}, preserving quotes")
                else:
                    log(f"{self.tag} ! blind on {t} {streak} cycles; cancelling quotes")
                self._gskip(t, "blind", lambda: dict(streak=streak, preserved=streak <= BLIND_PRESERVE_CYCLES, err=str(e)[:120]))
                continue

            own = own_by_ticker.get(t, [])
            # FULL-DEPTH BOOK LOG. `ob` here is always THIS market's fresh
            # book: a failed read `continue`s above, before this line, so a
            # stale previous-iteration `ob` can never be logged. MUST stay
            # above the quote-shape block further down, which rebinds `ob`
            # to a list of own-bid tuples. own_exact nets our orders out at
            # read time (competitor depth = level - own).
            # Own size comes from this cycle's cycle-top resting read, EXCEPT
            # for an event whose orders an earlier sibling's event-wide cancel
            # pulled THIS cycle (event_depth_thin): that read predates the
            # cancel, so it would still list orders no longer in this book.
            # Derived from the existing per-cycle set -- nothing on the
            # trading path is mutated.
            _own_log = ([] if (not self.live or meta.event_ticker in event_depth_thin)
                        else own_exact_by_ticker.get(t, []))
            self._book_log_add(t, "managed", ob, _own_log, meta,
                               fast=fast_only, own_src="resting_read")
            # Dry-run sim orders were never sent, so they are NOT in the real
            # book — netting them out would erode phantom levels and walk our
            # anchor away from the true external best cycle after cycle.
            own_in_book = own if self.live else []
            ext_bid, ext_ask = external_best(yes_levels, no_levels, own_in_book)
            touch_map[t] = (ext_bid, ext_ask)

            # LIVE-EVENT DEPTH GATE (Jack 2026-08-31, TRUMPMENTION /
            # MAMDANIMENTION — see EVENT_DEPTH_GATE_PREFIXES): a thin
            # external side on any quotable market of these series means the
            # event is likely LIVE, so the WHOLE event stands down — resting
            # orders on every sibling cancelled, quotes already built this
            # cycle stripped before placement. Sits BEFORE the breakers on
            # purpose: a gated book that just went one-sided must halt the
            # event, not merely 30-min-breaker its own market. Selection
            # stays sticky (the top-in-band pattern), so quoting resumes on
            # its own once the whole event reads healthy for
            # EVENT_DEPTH_RESUME_SECS.
            if series_event_depth_gated(meta.series):
                d_yes, d_no = external_depths(yes_levels, no_levels, own_in_book)
                two_sided = ext_bid is not None and ext_ask is not None
                mid_g = (ext_bid + ext_ask) / 2.0 if two_sided else None
                mid_in_band = pad_band_ok(meta.series, ext_bid, ext_ask)
                # Lost-touch and jump signals read off the LAST KNOWN mid:
                # only a strike that was recently in band can signal (a
                # strike LISTED at the extremes proves nothing; its
                # scrap-book decay falls through to the ordinary one-sided /
                # band machinery). prev_mid keeps updating on every
                # two-sided read — out-of-band ones included, via the normal
                # flow below — so a slow creep past the band edge re-anchors
                # each cycle and can never accumulate into a false jump.
                pm_g = self.state.prev_mid.get(t)
                pm_in_band = (pm_g is not None
                              and series_price_min(meta.series) <= pm_g
                              <= series_price_max(meta.series))
                # Point 6: a known-future-dated event cannot be live, so
                # none of the live signals may fire for it. Point 7: a known
                # START arms the noisy signals late; the jump keeps the day.
                armed = event_live_gate_armed(meta.event_ticker, now_ts)
                armed_jump = event_live_gate_armed(meta.event_ticker, now_ts,
                                                   jump=True)
                went_one_sided = armed and not two_sided and pm_in_band
                # Settled-strike signature (Jack 2026-08-31 #2): in-band ->
                # out-of-band by a real one-cycle jump (49c -> 99c: the word
                # got said). Confirms the event LIVE — permanently.
                # The MID must leave the series price band, not merely the
                # pad gate (2026-10-05, KXTRUMPMENTION-26OCT05-SANC): pad_band_ok
                # also fails on a touch outside 10-90, so a gapped book --
                # 7x64, mid 35.5c, right after our sweep breaker pulled the
                # event -- read as a "settled strike" and killed the event
                # forever with every strike still trading 21-26c. A settled
                # word pins the mid itself (98x99); a wide book only pulls
                # a touch, which the thin / one-sided triggers already own.
                mid_out_of_range = two_sided and not (
                    series_price_min(meta.series) <= mid_g
                    <= series_price_max(meta.series))
                jumped_out = (armed_jump and two_sided and pm_in_band
                              and mid_out_of_range
                              and abs(mid_g - pm_g) >= EVENT_DEPTH_JUMP_CENTS)
                stacked = (EVENT_DEPTH_STACK_CONTRACTS > 0
                           and max(d_yes, d_no)
                           >= EVENT_DEPTH_STACK_CONTRACTS)
                thin = (mid_in_band and armed and not stacked
                        and (d_yes < EVENT_DEPTH_MIN_CONTRACTS
                             or d_no < EVENT_DEPTH_MIN_CONTRACTS))
                if jumped_out and ev not in self.state.event_live_halt:
                    self.state.event_live_halt[ev] = now_ts
                    self.alerter.alert(
                        "event_live",
                        f"{ev}: {t} jumped out of band ({pm_g:.0f}c -> "
                        f"{mid_g:.0f}c) — settled strike, event LIVE; "
                        f"PERMANENTLY standing down the whole event", key=ev)
                if thin or went_one_sided or jumped_out \
                        or ev in self.state.event_live_halt:
                    event_depth_thin.add(ev)
                    first = ev not in self.state.event_depth_halt
                    self.state.event_depth_halt[ev] = now_ts
                    n_cx = 0
                    for m2 in by_event.get(ev, [meta]):
                        n_cx += self.cancel_market_orders(m2.ticker, resting)
                    ev_ticks = {m2.ticker for m2 in by_event.get(ev, [meta])}
                    desired = [q for q in desired if q.ticker not in ev_ticks]
                    if two_sided:   # keep P&L marks honest through the halt
                        self.state.prev_mid[t] = mid_g
                        self._mark_from_book(t, ext_bid, ext_ask, marked)
                    if first and (thin or went_one_sided):
                        self.alerter.alert(
                            "event_depth",
                            f"{ev}: {t} "
                            + ("went one-sided" if went_one_sided else
                               f"external depth yes {d_yes:.0f} / no "
                               f"{d_no:.0f} < {EVENT_DEPTH_MIN_CONTRACTS:.0f}")
                            + f" — event likely LIVE; standing down the whole "
                            f"event (cancelled {n_cx})", key=ev, urgent=False)
                    self._gskip(t, "event_depth_trip", lambda: dict(d_yes=d_yes, d_no=d_no, mid=mid_g, prev_mid=pm_g, mid_in_band=mid_in_band, prev_in_band=pm_in_band, armed=armed, thin=thin, one_sided=went_one_sided, jumped=jumped_out, stacked=stacked, live_halt=ev in self.state.event_live_halt, n_cx=n_cx), book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
                # Only a healthy IN-BAND, two-sided, at/over-target book
                # argues for resume. An out-of-band pin or a history-less
                # one-sided book proves nothing, counts nothing, and thereby
                # BLOCKS resume for as long as it sits there (Jack
                # 2026-08-31 #2: a settled strike holds its event down —
                # and settlement ends the event anyway).
                # "In band" here is the MID in the series price band, the same
                # test the jump confirm uses -- not pad_band_ok's 10-90 touch
                # gate (2026-10-05, KXTRUMPMENTION-26OCT05: after a resumable
                # fill-tripwire halt at 14:09Z, TRUMA 6x7 / FENT 6x7 / DRIL
                # 8x9 / FARM 90x91 -- strikes the bot had been QUOTING --
                # failed the touch gate forever, so the event could never
                # resume). A real pin (95x97, mid 96) still blocks.
                # A strike already out of band when the halt began
                # (event_depth_ignore) counts too: it never argued for the
                # live event, so it must not hold the resume down forever.
                if (two_sided and not mid_out_of_range)                         or t in self.state.event_depth_ignore.get(ev, ()):
                    event_depth_ok[ev] = event_depth_ok.get(ev, 0) + 1
                if ev in self.state.event_depth_halt:
                    # market of a still-halted event: hold quiet (and keep
                    # marks/mid fresh so resume doesn't false-trip the move
                    # breaker) until the resume pass clears the event.
                    self.cancel_market_orders(t, resting)
                    if two_sided:
                        self.state.prev_mid[t] = mid_g
                        self._mark_from_book(t, ext_bid, ext_ask, marked)
                    self._gskip(t, "event_depth_hold", lambda: dict(d_yes=d_yes, d_no=d_no, mid_in_band=mid_in_band, halt_ts=self.state.event_depth_halt.get(ev)), book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue

            # ANNOUNCEMENT HALT (2026-10-19, see MENTION_ANNOUNCE_SERIES): a
            # word jumping out of band confirms the event LIVE for good; a
            # fill burst across the event stands it down (resumable; the
            # second within the strike TTL confirms it). Armed at all times,
            # pads kept, no thin trigger. Read before the mid-move block below
            # moves prev_mid on.
            if mention_announce_series(meta.series):
                two_a = ext_bid is not None and ext_ask is not None
                mid_a = (ext_bid + ext_ask) / 2.0 if two_a else None
                pm_a = self.state.prev_mid.get(t)
                lo_a, hi_a = series_price_min(meta.series), series_price_max(meta.series)
                out_a = two_a and not (lo_a <= mid_a <= hi_a)
                jump_a = (out_a and pm_a is not None and lo_a <= pm_a <= hi_a
                          and abs(mid_a - pm_a) >= EVENT_DEPTH_JUMP_CENTS)
                burst_a = (ev not in announce_counted
                           and announce_moves.get(ev, 0.0) >= MENTION_ANNOUNCE_FILL_CT)
                tripped_a = False
                if jump_a and ev not in self.state.event_live_halt:
                    self.state.event_live_halt[ev] = now_ts
                    tripped_a = True
                    self.alerter.alert(
                        "event_live",
                        f"{ev}: {t} jumped out of band ({pm_a:.0f}c -> "
                        f"{mid_a:.0f}c) — announcement, event LIVE; "
                        f"PERMANENTLY standing down the whole event", key=ev)
                if burst_a:
                    announce_counted.add(ev)
                    last_a = self.state.event_fill_strike_ts.get(ev)
                    if EVENT_FILL_STRIKE_TTL_SECS > 0 and (
                            last_a is None
                            or now_ts - last_a > EVENT_FILL_STRIKE_TTL_SECS):
                        self.state.event_fill_strikes.pop(ev, None)   # expired
                    strikes_a = self.state.event_fill_strikes.get(ev, 0) + 1
                    self.state.event_fill_strikes[ev] = strikes_a
                    self.state.event_fill_strike_ts[ev] = now_ts
                    self.state.event_depth_halt[ev] = now_ts
                    confirmed_a = strikes_a >= EVENT_FILL_HALT_STRIKES
                    if confirmed_a:
                        self.state.event_live_halt.setdefault(ev, now_ts)
                    tripped_a = True
                    self.alerter.alert(
                        "event_fill",
                        f"{ev}: our position moved {announce_moves.get(ev, 0.0):.0f} "
                        f"contracts across the event in one cycle — announcement? "
                        f"standing the whole event down "
                        + ("PERMANENTLY (live confirmed, "
                           f"burst {strikes_a})" if confirmed_a else
                           f"(burst {strikes_a}/{EVENT_FILL_HALT_STRIKES}; resumes "
                           f"after {EVENT_DEPTH_RESUME_SECS // 60} min healthy)"),
                        key=ev)
                if tripped_a:
                    event_depth_thin.add(ev)                 # no resume this cycle
                    n_cx = 0
                    for m2 in by_event.get(ev, [meta]):
                        n_cx += self.cancel_market_orders(m2.ticker, resting)
                    ev_ticks = {m2.ticker for m2 in by_event.get(ev, [meta])}
                    desired = [q for q in desired if q.ticker not in ev_ticks]
                    log(f"{self.tag} announcement halt {ev}: "
                        + (f"{t} jumped {pm_a:.0f}c -> {mid_a:.0f}c" if jump_a
                           else f"fill burst {announce_moves.get(ev, 0.0):.0f} contracts")
                        + f"; cancelled {n_cx}")
                if ev in self.state.event_live_halt or ev in self.state.event_depth_halt:
                    if not tripped_a:
                        self.cancel_market_orders(t, resting)
                        if two_a and not out_a:
                            # healthy evidence for the resume pass, which needs
                            # every managed market of the event healthy
                            event_depth_ok[ev] = event_depth_ok.get(ev, 0) + 1
                    if two_a:   # keep P&L marks and the jump anchor fresh
                        self.state.prev_mid[t] = mid_a
                        self._mark_from_book(t, ext_bid, ext_ask, marked)
                    self._gskip(t, "announce_halt" if tripped_a else "announce_hold", lambda: dict(jumped=jump_a, burst=burst_a, moved=announce_moves.get(ev, 0.0), mid=mid_a, prev_mid=pm_a, live=ev in self.state.event_live_halt), book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue

            # A book that WAS two-sided and just lost a side is the classic
            # news signature (everyone pulled their quotes) — the mid-move
            # breaker can't see it because there is no mid anymore. Stand down.
            if BREAKERS_ENABLED and (ext_bid is None or ext_ask is None):
                pm = self.state.prev_mid.pop(t, None)
                if pm is not None:
                    self.state.breaker_until[t] = now_ts + BREAKER_COOLDOWN_SECS
                    n = self.cancel_market_orders(t, resting)
                    self.alerter.alert(
                        "one_sided", f"{t}: book went one-sided (was mid {pm:.0f}c); "
                        f"cancelled {n}, standing down "
                        f"{BREAKER_COOLDOWN_SECS // 60}min", key=t, urgent=False)
                    self._gskip(t, "one_sided_breaker", lambda: dict(prev_mid=pm, n_cx=n), book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue

            # OPEN-SCAN MID TRIPWIRE (2026-09-05; OFF unless IMM_SCAN_MID_JUMP
            # or IMM_SCAN_DRIFT > 0): a one-cycle jump, or a drift from the
            # admission mid, on a market admitted for having no information
            # in it means information arrived. Event-wide permanent
            # eviction, like the fill tripwire; independent of IMM_BREAKERS.
            # Read BEFORE the breaker block below updates prev_mid.
            if (SCAN_MID_JUMP_CENTS > 0 or SCAN_DRIFT_CENTS > 0) \
                    and t in self.state.scan_members \
                    and ext_bid is not None and ext_ask is not None:
                mid_s = (ext_bid + ext_ask) / 2.0
                pm_s = self.state.prev_mid.get(t)
                entry_s = self.state.scan_entry_mid.get(t)
                jumped = (SCAN_MID_JUMP_CENTS > 0 and pm_s is not None
                          and abs(mid_s - pm_s) >= SCAN_MID_JUMP_CENTS)
                drifted = (SCAN_DRIFT_CENTS > 0 and entry_s is not None
                           and abs(mid_s - entry_s) >= SCAN_DRIFT_CENTS)
                if jumped or drifted:
                    self._scan_evict_event(
                        ev,
                        (f"{t} mid {pm_s:.0f}c -> {mid_s:.0f}c in one cycle"
                         if jumped else
                         f"{t} mid drifted {entry_s:.0f}c -> {mid_s:.0f}c "
                         f"since admission"),
                        by_event, resting, desired, now_ts)
                    scan_evicted_now.update(
                        m2.ticker for m2 in by_event.get(ev, [meta]))
                    self.state.prev_mid[t] = mid_s
                    self._mark_from_book(t, ext_bid, ext_ask, marked)
                    self._gskip(t, "scan_mid_tripwire", lambda: dict(mid=mid_s, prev_mid=pm_s, entry_mid=entry_s, jumped=jumped, drifted=drifted), book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue

            # Mid-move circuit breaker (external mid, so our own churn can't trip it).
            if ext_bid is not None and ext_ask is not None:
                mid = (ext_bid + ext_ask) / 2.0
                pm = self.state.prev_mid.get(t)
                self.state.prev_mid[t] = mid
                self._mark_from_book(t, ext_bid, ext_ask, marked)
                if (move_breaker_on(meta.series) and pm is not None
                        and abs(mid - pm) >= MID_MOVE_BREAKER_CENTS):
                    self.state.breaker_until[t] = now_ts + BREAKER_COOLDOWN_SECS
                    n = self.cancel_market_orders(t, resting)
                    self.alerter.alert(
                        "move_breaker", f"{t}: mid {pm:.0f}c -> {mid:.0f}c; cancelled {n}, "
                        f"standing down {BREAKER_COOLDOWN_SECS // 60}min", key=t, urgent=False)
                    self._gskip(t, "move_breaker", lambda: dict(mid=mid, prev_mid=pm, n_cx=n), book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
                if ext_bid >= ext_ask:      # crossed/locked external book: stay out
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "crossed", book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
                if ext_ask - ext_bid > MAX_JOIN_SPREAD_CENTS:
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "wide_spread", lambda: dict(max_spread=MAX_JOIN_SPREAD_CENTS), book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
            # TOP-IN-BAND (Jack 2026-07-21): if the top of book itself sits
            # outside the series price band, stand aside ENTIRELY — an in-band
            # rung under an out-of-band top (a 90c bid below a 92c touch) is
            # the same knife the band exists to dodge. Sticky keeps such a
            # market SELECTED (costless), so quoting resumes if the book
            # returns to the band.
            # Member band (5-93 since 8/3); fresh keeps the series band.
            pmin_s, pmax_s = member_price_band(
                series_of(t), t in self.state.selected)
            # PER-SIDE top-in-band (Jack 2026-08-03 "Do 1", CHIH T69.99: a
            # live 3x29 book was fully stood down because its wide spread
            # put the bid touch under 5c): a side whose OWN touch is outside
            # the band stands down alone — its rungs die as diff-unmatched,
            # its pad stays to qualify the snapshot — while the healthy side
            # keeps earning. BOTH sides out (the Austin 96x98 case) still
            # stands the whole market down.
            bid_in_band = ext_bid is None or pmin_s <= ext_bid <= pmax_s
            ask_in_band = ext_ask is None or pmin_s <= ext_ask <= pmax_s
            if not bid_in_band and not ask_in_band:
                self.cancel_market_orders(t, resting)
                self._gskip(t, "band_both_out", lambda: dict(lo=pmin_s, hi=pmax_s, member=t in self.state.selected), book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                continue
            # TWO-SIDED DEPTH GATE (Jack 2026-08-05: "dont quote, and remove
            # existing quotes, if either side has <1000 contracts"). A
            # snapshot is EXCLUDED unless BOTH sides reach the program's
            # target, so a book that cannot get there pays nothing however
            # well we quote it — resting there is fill risk for zero rent.
            # Padding series (hourly temp only, since 2026-08-05) are exempt:
            # their pads ARE the mechanism for reaching target on a thin side.
            #
            # Depth is measured on the book AS FETCHED, which in live mode
            # already contains our own resting orders — deliberately, because
            # the exchange counts them too: a side we personally lift over the
            # target does qualify and does earn. The cancel path is stable
            # rather than flapping, since once our orders are gone the side is
            # further from target, not closer.
            depth_yes = sum(q for _px, q in yes_levels)
            depth_no = sum(q for _px, q in no_levels)
            bid_ok, ask_ok = sides_can_qualify(
                meta.series, meta.target_size, depth_yes, depth_no,
                ext_bid, ext_ask, ticker=t)
            if not (bid_ok and ask_ok):
                n_cx = self.cancel_market_orders(t, resting)
                if n_cx:
                    log(f"{self.tag} cannot qualify {t}: yes {depth_yes:.0f} / "
                        f"no {depth_no:.0f} vs target {meta.target_size:.0f} "
                        f"(pad reaches: bid={bid_ok} ask={ask_ok}) "
                        f"— cancelled {n_cx}, standing down")
                self._gskip(t, "cannot_qualify", lambda: dict(target=meta.target_size, depth_yes=round(depth_yes), depth_no=round(depth_no), bid_ok=bid_ok, ask_ok=ask_ok, pads=series_pad_to_target(meta.series), n_cx=n_cx), book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                continue
            # Deep-rung floor: on a HEALTHY book (both touches present and
            # in-band) rungs may follow the reference below 5c, down to
            # RUNG_DEEP_FLOOR (Jack 2026-08-03).
            healthy = (ext_bid is not None and ext_ask is not None
                       and bid_in_band and ask_in_band)
            rung_lo = RUNG_DEEP_FLOOR if healthy else pmin_s

            # RAIN FAIR-VALUE GATE (Jack 2026-07-28; reworked same day —
            # "my primary goal is to stay near the top of the orderbooks
            # to get incentive rewards"): reward credit halves per tick
            # behind the touch, so the NWS fair must never re-price quotes
            # off the join. It is a SANITY SCREEN only: quotes always join
            # the touch unchanged; the gate stands the market down entirely
            # when the touch itself fights the forecast on the side that
            # would fill us badly — bid touch above fair+TOL (paying over
            # fair) or ask touch below fair-TOL (selling under fair). A
            # one-side breach parks BOTH sides (one-sided quoting earns no
            # reward and eats pickoff risk); sticky selection keeps the
            # market, so quoting auto-resumes when book and forecast agree
            # again. Missing/stale fair (TTL in rain_fair_p) -> gate open ->
            # plain band behavior.
            if RAIN_FAIR_ENABLE and meta.series == RAIN_FAIR_SERIES \
                    and not rain_fair_exempt(meta.event_ticker, now_utc):
                p_fair = rain_fair_p(t, now_ts)
                if p_fair is not None:
                    fair_c = p_fair * 100.0
                    bid_bad = (ext_bid is not None
                               and ext_bid > fair_c + RAIN_FAIR_TOL_CENTS)
                    ask_bad = (ext_ask is not None
                               and ext_ask < fair_c - RAIN_FAIR_TOL_CENTS)
                    if bid_bad or ask_bad:
                        if t not in self._rain_fair_stood:
                            self._rain_fair_stood.add(t)
                            log(f"{self.tag} rain-fair stand-aside {t}: book "
                                f"{ext_bid}x{ext_ask} vs fair {fair_c:.0f}c "
                                f"(tol {RAIN_FAIR_TOL_CENTS}c)")
                        self.cancel_market_orders(t, resting)
                        # divergent book = the systematic directional entry
                        # (Jack 2026-07-28); manual-standoff markets never
                        # reach here, so his own bets are never crossed.
                        self.rain_directional_take(
                            t, ext_bid, ext_ask, fair_c, bid_bad, ask_bad, now_ts)
                        self._gskip(t, "rain_fair", lambda: dict(fair=round(fair_c, 2), tol=RAIN_FAIR_TOL_CENTS, bid_bad=bid_bad, ask_bad=ask_bad), book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                        continue
            if t in self._rain_fair_stood:
                self._rain_fair_stood.discard(t)
                log(f"{self.tag} rain-fair resume {t}")

            # LOW-TEMPERATURE GATE (Jack 2026-10-23, see LOWT_ENABLE): a wide
            # sanity screen on lowt_fair's forecast. Quotes join the touch
            # unchanged; the market stands aside (both sides, cancel) with no
            # fresh fair, on a shape-filter day, or when the touch fights the
            # fair by more than LOWT_FAIR_TOL_CENTS on the adverse side.
            if lowt_series(meta.series):
                lt_why, lt_in = lowt_gate(t, now_ts, ext_bid, ext_ask)
                if lt_why:
                    if t not in self._lowt_stood:
                        self._lowt_stood.add(t)
                        log(f"{self.tag} lowt stand-aside {t}: {lt_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "lowt_fair", lambda: lt_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
            if t in self._lowt_stood:
                self._lowt_stood.discard(t)
                log(f"{self.tag} lowt resume {t}")
            # HIGH-TEMPERATURE GATE (2026-10-23, see HIGHT_ENABLE): the same
            # wide screen on hight_fair's read
            if hight_series(meta.series):
                ht_why, ht_in = hight_gate(t, now_ts, ext_bid, ext_ask)
                if ht_why:
                    if t not in self._hight_stood:
                        self._hight_stood.add(t)
                        log(f"{self.tag} hight stand-aside {t}: {ht_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "hight_fair", lambda: ht_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
            if t in self._hight_stood:
                self._hight_stood.discard(t)
                log(f"{self.tag} hight resume {t}")

            # CARBON ARC FAIR GATE (Jack 2026-09-26, see CA_FAIR_ENABLE): the
            # rain gate's shape on Carbon Arc's month-to-date read. Quotes
            # still join the touch; a new read parks BOTH sides for the
            # refresh hold (sticky selection keeps the market meanwhile), and
            # a touch that fights the read on the adverse side caps that side
            # -- ca_caps, applied last below, where only a side that still
            # earns rests (CA_FAIR_CAP; off, the breach parks both sides).
            ca_caps: Optional[Tuple[Optional[int], Optional[int]]] = None
            if CA_FAIR_ENABLE and carbon_arc_settled(meta.series):
                ca_why = ""
                ca_in: dict = {}     # guard-skip inputs, built on THIS path
                band = None
                # the panel's scheduled update (2026-10-15), then the hold
                # after our read moves, then the band
                _ca_sched = ca_schedule_hold(t, now_ts)
                if _ca_sched is not None:
                    ca_why, ca_in = _ca_sched
                elif ca_refresh_held(t, now_ts):
                    _ca_r = _ca_read(t, now_ts)
                    _ca_hold = ca_refresh_hold_min(
                        _ca_r[0].get("category") if _ca_r else None)
                    ca_why = (f"new Carbon Arc read, holding "
                              f"{_ca_hold:g}m while the book reprices")
                    ca_in = dict(hold_min=_ca_hold)
                else:
                    band = ca_fair_band(t, now_ts)
                    if band is not None:
                        pc, plo, phi = band
                        ca_bid_bad, ca_ask_bad = fair_gate_breach(
                            ext_bid, ext_ask, plo * 100.0, CA_FAIR_TOL_CENTS,
                            phi * 100.0)
                        if ca_bid_bad or ca_ask_bad:
                            ca_desc = (f"book {ext_bid}x{ext_ask} vs fair "
                                       f"{pc * 100:.0f}c [{plo * 100:.0f}-"
                                       f"{phi * 100:.0f}] (tol "
                                       f"{CA_FAIR_TOL_CENTS}c, "
                                       f"{'bid' if ca_bid_bad else 'ask'} side)")
                            if CA_FAIR_CAP:
                                ca_caps = ca_fair_caps(plo * 100.0, phi * 100.0)
                                if t not in self._ca_fair_capped:
                                    self._ca_fair_capped.add(t)
                                    log(f"{self.tag} ca-fair capped {t}: "
                                        f"{ca_desc}; "
                                        + (f"bids capped at {ca_caps[0]}c"
                                           if ca_bid_bad else
                                           f"asks floored at {ca_caps[1]}c")
                                        + ", resting only while it earns")
                            else:
                                ca_why = ca_desc
                                ca_in = dict(fair=round(pc * 100, 2),
                                             lo=round(plo * 100, 2),
                                             hi=round(phi * 100, 2),
                                             tol=CA_FAIR_TOL_CENTS,
                                             bid_bad=ca_bid_bad,
                                             ask_bad=ca_ask_bad)
                if ca_why:
                    if t not in self._ca_fair_stood:
                        self._ca_fair_stood.add(t)
                        log(f"{self.tag} ca-fair stand-aside {t}: {ca_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "ca_fair", lambda: ca_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
                if ca_caps is None and t in self._ca_fair_capped:
                    self._ca_fair_capped.discard(t)
                    self._ca_unearning.pop(t, None)
                    log(f"{self.tag} ca-fair uncapped {t}: "
                        + ("book back inside the read's band" if band is not None
                           else "no usable read"))
            if t in self._ca_fair_stood:
                self._ca_fair_stood.discard(t)
                log(f"{self.tag} ca-fair resume {t}")

            # OPENROUTER TOKEN-USAGE GATE (Jack 2026-09-27, see OR_FAIR_ENABLE):
            # the same stand-aside on OpenRouter's own daily totals, failing
            # CLOSED -- these series are quoted only against the feed.
            if OR_FAIR_ENABLE and meta.series in OR_FAIR_SERIES:
                or_why, or_in = or_gate_reason(t, now_ts, ext_bid, ext_ask)
                if or_why:
                    if t not in self._or_fair_stood:
                        self._or_fair_stood.add(t)
                        log(f"{self.tag} or-fair stand-aside {t}: {or_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "or_fair", lambda: or_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
            if t in self._or_fair_stood:
                self._or_fair_stood.discard(t)
                log(f"{self.tag} or-fair resume {t}")

            # OPENROUTER MARKET-SHARE GATE (Jack 2026-09-30, see
            # SHARE_FAIR_ENABLE): the same stand-aside on the Market Share
            # chart's own data, failing CLOSED, and out while a feed has
            # stalled.
            if share_fair_series(meta.series):
                sh_why, sh_in = share_gate_reason(t, now_ts, ext_bid, ext_ask)
                if sh_why:
                    if t not in self._share_fair_stood:
                        self._share_fair_stood.add(t)
                        log(f"{self.tag} share-fair stand-aside {t}: {sh_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "share_fair", lambda: sh_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
            if t in self._share_fair_stood:
                self._share_fair_stood.discard(t)
                log(f"{self.tag} share-fair resume {t}")

            # MONTHLY RAIN GATE (Jack 2026-10-01, see RAIN_MONTHLY_ENABLE): the
            # daily rain gate's stand-aside on the monthly model, failing
            # CLOSED, and out while it rains at the station; bids over the
            # fair + tol leave the asks quoting alone, while the market
            # clears the payout floor (RAIN_MONTHLY_ONE_SIDE). The period
            # totals (2026-10-04, RAIN_PERIOD_ENABLE) ride the same gate on
            # the same file; a band breach there caps the side that fights
            # the fair -- rain_caps, applied last below, where only a side
            # that still earns rests (RAIN_PERIOD_CAP).
            # The snow monthlies (2026-10-04, SNOW_MONTHLY_ENABLE) take the
            # same gate on their own file, with the period markets' caps,
            # and so do the 2026-10-11 fair-file gates (fair_file_gate:
            # the CPI pilot, weekend rain, Rotten Tomatoes) without the
            # station checks, and the 2026-10-22 ski-resort snowfall gate
            # with them.
            rain_caps: Optional[Tuple[Optional[int], Optional[int]]] = None
            rain_side_out: Optional[str] = None
            rain_period = rain_period_gated(t)
            snow = snow_monthly_series(meta.series)
            ffg = fair_file_gate(meta.series, t, now_ts, ext_bid, ext_ask)
            wx = ffg[0] if ffg else ("snow-monthly" if snow else
                                     "rain-period" if rain_period else "rain-monthly")
            if rain_monthly_series(meta.series) or rain_period or snow or ffg:
                if ffg:
                    _, rm_why, rm_in, rain_caps = ffg
                elif snow:
                    rm_why, rm_in, rain_caps = snow_monthly_gate(
                        t, now_ts, ext_bid, ext_ask)
                elif rain_period:
                    rm_why, rm_in, rain_caps = rain_period_gate(
                        t, now_ts, ext_bid, ext_ask)
                else:
                    rm_why, rm_in, rain_caps = rain_monthly_gate(
                        t, now_ts, ext_bid, ext_ask)
                    if rain_caps is not None:
                        rain_side_out = rm_in["side_out"]
                        if t in self.state.hopeless_since:
                            # the one side rests only above the payout floor
                            rm_why = (f"{rm_in['why']}; one side projects under "
                                      f"the ${PAYOUT_FLOOR_DOLLARS:.2f} payout floor")
                            rm_in = dict(rm_in, reason="payout_floor")
                            rain_caps = rain_side_out = None
                if rm_why:
                    if t not in self._rain_monthly_stood:
                        self._rain_monthly_stood.add(t)
                        log(f"{self.tag} {wx} stand-aside {t}: {rm_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, wx.replace("-", "_"), lambda: rm_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
                if rain_caps is not None and t not in self._rain_period_capped:
                    self._rain_period_capped.add(t)
                    log(f"{self.tag} {wx} capped {t}: {rm_in['why']}; "
                        + (f"{rain_side_out}s out, "
                           f"{'sell' if rain_side_out == 'bid' else 'buy'} only"
                           if rain_side_out else
                           f"bids capped at {rain_caps[0]}c" if rm_in.get("bid_bad")
                           else f"asks floored at {rain_caps[1]}c")
                        + ", resting only while it earns")
            if rain_caps is None and t in self._rain_period_capped:
                self._rain_period_capped.discard(t)
                self._rain_period_unearning.pop(t, None)
                log(f"{self.tag} {wx} uncapped {t}")
            if t in self._rain_monthly_stood:
                self._rain_monthly_stood.discard(t)
                log(f"{self.tag} {wx} resume {t}")

            # GASBUDDY STATE-GAS GATE (Jack 2026-09-27, see GB_FAIR_ENABLE):
            # the same stand-aside on GasBuddy's live state averages, failing
            # CLOSED -- the state dailies are quoted only against the feed.
            # The AS test's gas dailies quote plain (2026-10-25, ASTEST_ENABLE),
            # and so do its gas-state daily picks (2026-10-27).
            if GB_FAIR_ENABLE and gb_fair_series(meta.series) \
                    and not astest_plain_gas(meta.series):
                gb_why, gb_in = gb_gate_reason(t, now_ts, ext_bid, ext_ask)
                if gb_why:
                    if t not in self._gb_fair_stood:
                        self._gb_fair_stood.add(t)
                        log(f"{self.tag} gb-fair stand-aside {t}: {gb_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "gb_fair", lambda: gb_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
            if t in self._gb_fair_stood:
                self._gb_fair_stood.discard(t)
                log(f"{self.tag} gb-fair resume {t}")

            # DATA CENTER COUNT GATE (Jack 2026-10-01, see DC_GATE_ENABLE):
            # stand aside without a fresh read of the state, for the hold
            # after its count changes, and once the count reached the strike.
            if DC_GATE_ENABLE and datacenter_series(meta.series):
                dc_why, dc_in = dc_gate_reason(t, now_ts)
                if dc_why:
                    if t not in self._dc_stood:
                        self._dc_stood.add(t)
                        log(f"{self.tag} dc-count stand-aside {t}: {dc_why} {dc_in}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "dc_count", lambda: dc_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
            if t in self._dc_stood:
                self._dc_stood.discard(t)
                log(f"{self.tag} dc-count resume {t}")

            # USGS EARTHQUAKE BID-ONLY GATE (Jack 2026-09-27, see
            # QUAKE_ENABLE): stand aside (cancel) when the feed is stale, the
            # strike crossed or its fair leaves no bid; HOLD -- resting bids
            # left exactly as they are, never raised on the news -- while a
            # fresh quake detection awaits NEIC; otherwise the bid ladder
            # below is capped at the fair cap. On a far strike
            # (QUAKE_ASK_STRIKES) the ask side has its own verdict: no ask
            # while it is off (the refresher has usually pulled it already),
            # else asks floored at the fair -- and a hold keeps (renews) an
            # ask only while that verdict allows it.
            quake_cap: Optional[int] = None
            quake_ask_c: Optional[int] = None
            if quake_gated(meta.series):
                qk = quake_past_cutoff(quake_gate(t, now_ts, meta.close_time),
                                       meta.cutoff, now_utc)
                if qk["action"] == "stand":
                    self._quake_held.discard(t)
                    if t not in self._quake_stood:
                        self._quake_stood.add(t)
                        log(f"{self.tag} quake stand-aside {t}: {qk['why']}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "quake", lambda: qk, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
                quake_ask_c = qk.get("ask_floor_c")
                if quake_ask_strike(t):
                    self._quake_ask_note(t, quake_ask_c, qk.get("ask_why") or "")
                self._quake_pull_asks(t, resting, quake_ask_c,
                                      qk.get("ask_why") or "not an ask strike")
                if qk["action"] == "hold":
                    if t not in self._quake_held:
                        self._quake_held.add(t)
                        log(f"{self.tag} quake hold {t}: {qk['why']}")
                    quake_held.add(t)
                    if quake_ask_c is not None:
                        quake_ask_renew.add(t)
                    self._gskip(t, "quake_hold", lambda: qk, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
                quake_cap = int(qk["cap_c"])
            if t in self._quake_stood or t in self._quake_held:
                self._quake_stood.discard(t)
                self._quake_held.discard(t)
                log(f"{self.tag} quake resume {t}")

            # VERCEL PRE-D GATE (Jack 2026-09-27, see VERCEL_ENABLE): quoted
            # only before the measured day and only where the book agrees with
            # the pre-D fair; fails CLOSED without a fresh read. Offers under
            # fair - tol leave the bid quoting alone, while the market clears
            # the payout floor (VERCEL_BID_ONLY).
            vc_side_out: Optional[str] = None
            if vercel_series(meta.series):
                vc_why, vc_in = vercel_gate(t, now_ts, ext_bid, ext_ask,
                                            meta.close_time)
                if not vc_why and vc_in.get("side_out"):
                    if t in self.state.hopeless_since:
                        # the bid alone rests only above the payout floor
                        vc_why = (f"{vc_in['why']}; the bid alone projects under "
                                  f"the ${PAYOUT_FLOOR_DOLLARS:.2f} payout floor")
                        vc_in = dict(vc_in, reason="payout_floor")
                    else:
                        vc_side_out = vc_in["side_out"]
                if vc_why:
                    if t not in self._vercel_stood:
                        self._vercel_stood.add(t)
                        log(f"{self.tag} vercel stand-aside {t}: {vc_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "vercel_fair", lambda: vc_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
                if vc_side_out is not None and t not in self._vercel_bid_only:
                    self._vercel_bid_only.add(t)
                    log(f"{self.tag} vercel bid only {t}: {vc_in['why']}; asks "
                        f"out, the bid resting only while it earns")
            if vc_side_out is None and t in self._vercel_bid_only:
                self._vercel_bid_only.discard(t)
                self._vercel_unearning.pop(t, None)
                log(f"{self.tag} vercel two-sided {t}")
            if t in self._vercel_stood:
                self._vercel_stood.discard(t)
                log(f"{self.tag} vercel resume {t}")

            # YOUTUBE #2 PILOT LOSS HALT (Jack 2026-10-05, see YT2_ENABLE):
            # the family's daily loss limit tripped this roll day -- stood
            # aside, both sides, until the 5am-CT roll; positions ride.
            if yt2_series(meta.series) \
                    and self.state.yt2_halt_day == _halt_day_key(now_utc):
                self.cancel_market_orders(t, resting)
                yt2_in = {"pnl_today": round(self.state.yt2_pnl_today_last, 2),
                          "limit": YT2_DAILY_LOSS_LIMIT}
                self._gskip(t, "yt2_halt", lambda: yt2_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                continue
            # YOUTUBE #2 PILOT FILL PAUSE (Jack 2026-10-14, see
            # YT2_FILL_PAUSE_MIN): a fill of ours stood the event aside.
            if yt2_series(meta.series) and self.state.yt2_fill_pause_until.get(
                    meta.event_ticker, 0.0) > now_ts:
                self.cancel_market_orders(t, resting)
                yt2_until = self.state.yt2_fill_pause_until.get(meta.event_ticker, 0.0)
                yt2_pin = {"until": round(yt2_until, 1),
                           "left_s": round(yt2_until - now_ts)}
                self._gskip(t, "yt2_fill_pause", lambda: yt2_pin, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                continue
            # OPPORTUNISTIC AS TEST FILL PAUSE (Jack 2026-10-25, see
            # ASTEST_GAS_FILL_PAUSE_MIN): a fill of ours stood the event aside.
            # ...or the family burst breaker stood every event of the family
            # aside (gas; Billboard and VoteHub since 2026-10-27)
            _asf = astest_family(meta.series)
            if _asf is not None:
                _ap = self.state.astest_fill_pause_until
                _afk = astest_knob(_asf, "FAMILY_KEY")
                as_until = max(_ap.get(meta.event_ticker, 0.0), _ap.get(_afk, 0.0))
                if as_until > now_ts:
                    self.cancel_market_orders(t, resting)
                    as_pin = {"until": round(as_until, 1), "left_s": round(as_until - now_ts),
                              "family": _ap.get(_afk, 0.0) > now_ts}
                    self._gskip(t, "astest_fill_pause", lambda: as_pin, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue

            # YOUTUBE WEEKLY PILOT (Jack 2026-10-06, see YTW_ENABLE): its own
            # family loss halt, then the realtime fair gate (fails closed).
            if ytw_series(meta.series):
                if self.state.ytw_halt_day == _halt_day_key(now_utc):
                    self.cancel_market_orders(t, resting)
                    ytw_hin = {"pnl_today": round(self.state.ytw_pnl_today_last, 2),
                               "limit": YTW_DAILY_LOSS_LIMIT}
                    self._gskip(t, "ytw_halt", lambda: ytw_hin, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
                ytw_why, ytw_in = ytw_gate_reason(t, now_ts, ext_bid, ext_ask)
                if ytw_why:
                    if t not in self._ytw_stood:
                        self._ytw_stood.add(t)
                        log(f"{self.tag} ytw stand-aside {t}: {ytw_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "ytw_fair", lambda: ytw_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
                if t in self._ytw_stood:
                    self._ytw_stood.discard(t)
                    log(f"{self.tag} ytw resume {t}")

            # YOUTUBE #1 LEADER-BID PILOT (Jack 2026-10-14, see YT1_MODE):
            # only the fair's leader, bids at most P - YT1_EDGE_CENTS (applied
            # with the quake cap below); fails CLOSED without a fresh fair.
            yt1_cap: Optional[int] = None
            if yt1_series(meta.series):
                y1_why, y1_in, y1_cap = yt1_gate_reason(t, now_ts)
                if y1_why:
                    if t not in self._yt1_stood:
                        self._yt1_stood.add(t)
                        log(f"{self.tag} yt1 stand-aside {t}: {y1_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "yt1_fair", lambda: y1_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
                if t in self._yt1_stood:
                    self._yt1_stood.discard(t)
                    log(f"{self.tag} yt1 quoting {t}: bids at most {y1_cap}c "
                        f"(fair {y1_in['p'] * 100:.0f}%)")
                yt1_cap = y1_cap

            # TRUMP WEEKLY PILOT LOSS HALT (Jack 2026-10-11, see TWK_ENABLE):
            # this series' daily loss limit tripped this roll day -- stood
            # aside until the 5am-CT roll; positions ride.
            # (the NFL head-to-head family rides the same machinery, as one
            # budget: pilot_halt_key, 2026-10-12)
            _pk = pilot_budget_key(t)
            if _pk is not None and self.state.twk_halt_day.get(
                    _pk) == _halt_day_key(now_utc):
                self.cancel_market_orders(t, resting)
                twk_in = {"pnl_today": round(
                              self.state.twk_pnl_today_last.get(_pk, 0.0), 2),
                          "limit": pilot_halt_limit(_pk), "budget": _pk}
                self._gskip(t, "twk_halt", lambda: twk_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                continue

            # TREASURY GATE (Jack 2026-10-01, see TREASURY_GATE_ENABLE; every
            # Treasury series since 2026-10-02, TREASURY_GATE_ALL): quoted
            # only against the live CNBC yield's fair; fails CLOSED without a
            # fresh read or a model for the series.
            if treasury_gated_series(meta.series):
                tr_why, tr_in = treasury_gate_reason(
                    meta.series, t, now_ts, ext_bid, ext_ask, meta.close_time)
                if tr_why:
                    if t not in self._treasury_stood:
                        self._treasury_stood.add(t)
                        log(f"{self.tag} treasury stand-aside {t}: {tr_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "treasury_yield", lambda: tr_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
            if t in self._treasury_stood:
                self._treasury_stood.discard(t)
                log(f"{self.tag} treasury resume {t}")

            # LONG-DATED MORTGAGE GATE (Jack 2026-09-28, see MORT_ENABLE):
            # stand aside (cancel) without a fresh PMMS fair, on a shape the
            # model does not cover, or when the touch fights the fair;
            # otherwise every rung below stays MORT_FAIR_TOL_CENTS on the
            # safe side of the fair (mort_cap_quotes).
            mort_caps: Optional[Tuple[Optional[int], Optional[int]]] = None
            if mort_series(meta.series):
                mg_why, mg_in, mort_caps = mort_gate(t, now_ts, ext_bid, ext_ask)
                if mg_why:
                    if t not in self._mort_stood:
                        self._mort_stood.add(t)
                        log(f"{self.tag} mortgage stand-aside {t}: {mg_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "mort_fair", lambda: mg_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
            if t in self._mort_stood:
                self._mort_stood.discard(t)
                log(f"{self.tag} mortgage resume {t}")

            # POKEMON GATE (Jack 2026-10-03, see POKE_ENABLE): stand aside
            # (cancel) without a fresh TCGplayer fair, on an unmapped event
            # or one whose rules name another item, just after the item's
            # price jumped, or when the touch fights the fair; otherwise every
            # rung below stays POKE_FAIR_TOL_CENTS on the safe side of it
            # (stand-aside band POKE_BAND_TOL_CENTS).
            poke_caps: Optional[Tuple[Optional[int], Optional[int]]] = None
            if poke_series(meta.series):
                pk_why, pk_in, poke_caps = poke_gate(t, now_ts, ext_bid, ext_ask)
                if pk_why:
                    if t not in self._poke_stood:
                        self._poke_stood.add(t)
                        log(f"{self.tag} pokemon stand-aside {t}: {pk_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "poke_fair", lambda: pk_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
            if t in self._poke_stood:
                self._poke_stood.discard(t)
                log(f"{self.tag} pokemon resume {t}")

            # NFL PLAYER-PROP GATE (Jack 2026-10-03, see NFL_FAIR_ENABLE):
            # stand aside (cancel) without a fresh player-history fair, on an
            # injury-designated player, or when the touch sits outside the
            # fair band by more than NFL_BAND_TOL_CENTS; otherwise every rung
            # below stays inside the band (+-NFL_FAIR_TOL_CENTS).
            nfl_caps: Optional[Tuple[Optional[int], Optional[int]]] = None
            if nfl_series(meta.series):
                nf_why, nf_in, nfl_caps = nfl_gate(t, now_ts, ext_bid, ext_ask)
                if nf_why:
                    if t not in self._nfl_stood:
                        self._nfl_stood.add(t)
                        log(f"{self.tag} nfl stand-aside {t}: {nf_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "nfl_fair", lambda: nf_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
            # NFL HEAD-TO-HEAD PILOT and the NFL AUTO FAMILIES' GAME members
            # (Jack 2026-10-12, see NFL_H2H_ENABLE / NFL_AUTO_ENABLE): the
            # ladders' team-news hold on both teams, failing closed.
            if nfl_h2h_series(meta.series) or nfl_auto_game(meta.series):
                h2_why, h2_in = nfl_team_news_gate(t, now_ts)
                if h2_why:
                    if t not in self._nfl_stood:
                        self._nfl_stood.add(t)
                        log(f"{self.tag} nfl team-news stand-aside {t}: {h2_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "nfl_team_news", lambda: h2_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
            # ... and their SEASON members are out while any NFL game is live
            # (Jack 2026-10-12: "any props that go beyond a single game,
            # should be turned off anytime there's a live game")
            if nfl_auto_season(meta.series):
                lv_live, lv_why = self._nfl_live_games(now_ts)
                if lv_live is not False:
                    if t not in self._nfl_stood:
                        self._nfl_stood.add(t)
                        log(f"{self.tag} nfl live-game stand-aside {t}: {lv_why}")
                    self.cancel_market_orders(t, resting)
                    lv_in = {"reason": "live_game" if lv_live else "scoreboard",
                             "why": lv_why}
                    self._gskip(t, "nfl_live", lambda: lv_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
            if t in self._nfl_stood:
                self._nfl_stood.discard(t)
                log(f"{self.tag} nfl resume {t}")
            # NBA / WNBA / MLB AUTO FAMILIES' SEASON members (Jack 2026-10-15,
            # see LEAGUE_AUTO_ENABLE): out while any game of their league is
            # live, and for good once their deciding round is. Logged per
            # series.
            if league_auto_season(meta.series):
                la_why = self._league_auto_hold(meta.series, now_ts, t)
                la_key = nfl_auto_event_key(t)          # logged per event
                if la_why:
                    if la_key not in self._league_stood_series:
                        self._league_stood_series.add(la_key)
                        log(f"{self.tag} league auto stand-aside {la_key}: {la_why}")
                    self.cancel_market_orders(t, resting)
                    la_in = {"why": la_why}
                    self._gskip(t, "league_live", lambda: la_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
                if la_key in self._league_stood_series:
                    self._league_stood_series.discard(la_key)
                    log(f"{self.tag} league auto resume {la_key}")
            # ...and their GAME members' TEAM-NEWS HOLD (Jack 2026-10-22, see
            # LEAGUE_NEWS_LEAGUES): ESPN's injury report on both teams, held
            # LEAGUE_NEWS_HOLD_MIN after a change, failing closed. Logged per
            # event.
            if league_auto_game(meta.series):
                ln_why, ln_in = league_news_gate(
                    t, (league_auto_entry(meta.series) or {}).get("league") or "",
                    now_ts)
                ln_key = nfl_auto_event_key(t)
                if ln_why:
                    if ln_key not in self._league_news_stood:
                        self._league_news_stood.add(ln_key)
                        log(f"{self.tag} league team-news stand-aside {ln_key}: {ln_why}")
                    self.cancel_market_orders(t, resting)
                    self._gskip(t, "league_team_news", lambda: ln_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
                if ln_key in self._league_news_stood:
                    self._league_news_stood.discard(ln_key)
                    log(f"{self.tag} league team-news resume {ln_key}")
            # MLB POSTSEASON MVPs (Jack 2026-10-12: "quote MLB MVPs under a
            # no-quotes-during-games rule", see MLB_MVP_ROUNDS): out while any
            # MLB game is live, and for good once the round is decided.
            # Logged per series (49-98 markets each).
            if mlb_mvp_series(meta.series):
                mv_why = self._mlb_mvp_hold(meta.series, now_ts)
                if mv_why:
                    if meta.series not in self._mlb_stood_series:
                        self._mlb_stood_series.add(meta.series)
                        log(f"{self.tag} mlb mvp stand-aside {meta.series}: {mv_why}")
                    self.cancel_market_orders(t, resting)
                    mv_in = {"why": mv_why}
                    self._gskip(t, "mlb_mvp", lambda: mv_in, book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                    continue
                if meta.series in self._mlb_stood_series:
                    self._mlb_stood_series.discard(meta.series)
                    log(f"{self.tag} mlb mvp resume {meta.series}")

            # Past-cutoff managed markets (only reduce-only EXTRAS can reach
            # here — selected members die at the _screen): cancel and go
            # silent. Without this, a restored rain position kept reduce-only
            # churn running past the 6pm early stop (2026-07-29, NYC).
            if meta.cutoff is not None and now_utc >= meta.cutoff:
                self.cancel_market_orders(t, resting)
                self._gskip(t, "cutoff_extra", lambda: dict(cutoff=meta.cutoff.isoformat()), book=lambda: (ext_bid, ext_ask, yes_levels, no_levels))
                continue
            # Rooms: hard per-market cap, event share, then skew — all using
            # this market's SERIES ladder/cap (Love Island runs a bigger flat
            # 5/5/5 ladder with a tighter 50-contract net cap). For quote_all
            # series the cap/skew track the bot's OWN book, so the user's
            # coexisting manual position doesn't shrink the bot's room.
            lv = hour_scaled_levels(meta.series, now_utc)
            # near-cliff SIZE mode (2026-09-26): x NEAR_CLIFF_SIZE_MULT until
            # the banked accrual crosses the cliff (same shape everywhere:
            # collateral reservation and placement guard scale with it)
            # ...and the yield size mode (2026-10-05): _market_size_mult
            lv = scale_levels(lv, self._market_size_mult(t))
            hm = hour_size_mult(meta.series, now_utc)
            # Carbon Arc late-month rule (Jack 2026-09-24, ca_late_month_mults):
            # from here the ladder is PER SIDE -- no bid rungs and asks at
            # 50% inside the window, the plain ladder on both sides otherwise.
            ca_bm, ca_am = ca_late_month_mults(t, now_utc)
            # ...times the series' own side sizes (SIDE_MULT_SERIES, Trump B;
            # else the family's lean) and the event long-shot cut at this
            # book's mid (LONGSHOT_MULT)
            ss_bm, ss_am = series_side_mults(meta.series)
            ls_bm, ls_am = longshot_side_mults(meta.series, touch_mid(ext_bid, ext_ask))
            lv_bid = scale_levels(lv, ca_bm * ss_bm * ls_bm)
            lv_ask = scale_levels(lv, ca_am * ss_am * ls_am)
            if series_bid_only(meta.series) and not quake_ask_strike(t):
                lv_ask = []          # bid-only family (quake gate): no ask rungs
            if no_side_only(t):
                lv_bid = []          # NO side only (KXPRESRUN-28): no bid rungs
            if (ca_bm, ca_am) != (1.0, 1.0):
                self._ca_late_note(meta.event_ticker, ca_bm, ca_am)
            # deep-reference size multiplier feeds the side_max component of
            # room (position/event caps and skew still bind unscaled);
            # capped so hour x ref <= TOTAL_SIZE_MULT_CAP
            ref_bid_px, ref_ask_px = ladder_reference_prices(
                yes_levels, no_levels, meta.target_size)
            # TWO-MARKET COMPLEMENT LEAD (COMP_LEAD_MODE): a side its twin's
            # book prices well ahead of its own rests one rung of at least
            # target/5 at its lead price (comp_lead_prices) instead of at its
            # reference -- never on a reduce-only market, under a fair gate's
            # cap or outside the band the loop places at-ref rungs in. A FAIR
            # lead (FAIR LEAD) rests at least FAIR_LEAD_MARGIN_C inside its
            # fair, so inside whatever its own family's gate caps a side to
            lead_b = lead_a = None
            lead_n = comp_lead_size(meta.target_size)
            lead_src = self._lead_source(meta)
            if (lead_src is not None and not reduce_only
                    and quake_cap is None and yt1_cap is None and mort_caps is None
                    and poke_caps is None and nfl_caps is None
                    and ca_caps is None and (rain_caps is None or lead_src == "fair")):
                _lx_yes, _lx_no = (external_levels(yes_levels, no_levels, own_in_book)
                                   if own_in_book else (yes_levels, no_levels))
                if t not in self._comp_lead_px and own_in_book:
                    # after a restart: a resting rung of exactly the lead size
                    # is where that side leads (it must not move up either)
                    _hb = max((px for s, px, r in own_in_book if s == "bid"
                               and abs(r - lead_n) < 0.5 and px > PAD_BID_CENTS),
                              default=None)
                    _ha = min((px for s, px, r in own_in_book if s == "ask"
                               and abs(r - lead_n) < 0.5 and px < PAD_ASK_CENTS),
                              default=None)
                    if _hb is not None or _ha is not None:
                        self._comp_lead_px[t] = (_hb, _ha, lead_n)
                lead_b, lead_a = self._comp_lead(meta, _lx_yes, _lx_no)
                if lead_b is not None and not (bid_in_band and comp_lead_band_ok(
                        lead_b[0], (rung_lo, pmax_s), meta.series)):
                    lead_b = None
                if lead_a is not None and not (ask_in_band and comp_lead_band_ok(
                        lead_a[0], (rung_lo, pmax_s), meta.series)):
                    lead_a = None
                # (FAIR_LEAD_INV_QUOTE: a side already holding the lead's
                # position cap leads no more; it quotes its normal rung)
                if lead_src == "fair" and FAIR_LEAD_INV_QUOTE:
                    _lp = own_pos if coexist else pos
                    if _lp >= FAIR_LEAD_MAX_POSITION:
                        lead_b = None
                    if _lp <= -FAIR_LEAD_MAX_POSITION:
                        lead_a = None
                self._comp_lead_note(t, lead_b, lead_a, lead_n, src=lead_src)
                if lead_mode(lead_src) != "on":
                    lead_b = lead_a = None
            # FAIR CLOSE (FAIR_CLOSE_MODE): a fair-lead market holding a
            # position rests the whole of it on the side that reduces it, at
            # the model's own price where that earns (fair_close_group) and
            # beats where the side rests, else at the side's own price
            close_b = close_a = None
            close_n = 0
            _cpos = own_pos if coexist else pos
            _cfair = (fair_close_fair_c(t, meta.series, now_ts)
                      if abs(_cpos) >= 1 and not reduce_only
                      and meta.price_step >= 0.01 else None)
            if _cfair is not None:
                _cx_yes, _cx_no = (external_levels(yes_levels, no_levels, own_in_book)
                                   if own_in_book else (yes_levels, no_levels))
                _cavg = (self.pnl.avg.get(t) if abs(own_pos) >= 1
                         and (own_pos < 0) == (_cpos < 0) else None)
                close_b, close_a = fair_close_group(_cx_yes, _cx_no, _cfair, _cpos,
                                                    meta.target_size,
                                                    meta.discount_factor,
                                                    avg_c=_cavg)
                if close_b is not None and not (bid_in_band and comp_lead_band_ok(
                        close_b[0], (rung_lo, pmax_s), meta.series)):
                    close_b = None
                if close_a is not None and not (ask_in_band and comp_lead_band_ok(
                        close_a[0], (rung_lo, pmax_s), meta.series)):
                    close_a = None
                if FAIR_CLOSE_MODE == "on":
                    close_n = int(min(abs(_cpos), FAIR_LEAD_MAX_POSITION))
            # LONE-REFERENCE GUARD (LONE_REF_GUARD_MODE): a side whose
            # reference rests on a thin external top our rung would jump to
            # stands aside ("on": no rungs this cycle) or is logged ("dry").
            # The bait-fingerprint stop (BAIT_STOP_MODE) reads the same test
            # on its own series (quietly where the guard does not look), and
            # an event it stopped a side in runs the guard ON until ET
            # midnight.
            lr_guard = (LONE_REF_GUARD_MODE in ("on", "dry")
                        and lone_ref_series(meta.series))
            lr_bait = bait_series(meta.series)
            if LADDER_MODE == "atref" and (lr_guard or lr_bait):
                lr_on = (lr_guard and LONE_REF_GUARD_MODE == "on") or (
                    lr_bait and self.bait_event_guarded(meta.event_ticker, now_ts))
                lr_bid, lr_ask = self._lone_ref_check(
                    t, meta, yes_levels, no_levels, own_in_book, own,
                    ref_bid_px, ref_ask_px, now_ts,
                    quiet=not (lr_guard or lr_on), on=lr_on)
                if lr_on:
                    if lr_bid:
                        lv_bid = []
                    if lr_ask:
                        lv_ask = []
            side_max_bid = int(round(sum(s for _t, s in lv_bid) *
                                     capped_ref_mult(ext_bid, ref_bid_px, "bid",
                                                     hour_mult=hm,
                                                     series=meta.series)))
            side_max_ask = int(round(sum(s for _t, s in lv_ask) *
                                     capped_ref_mult(ext_ask, ref_ask_px, "ask",
                                                     hour_mult=hm,
                                                     series=meta.series)))
            # a leading side may rest target/5 (the caps and skew below bind)
            if lead_b is not None and lv_bid:
                side_max_bid = max(side_max_bid, lead_n)
            if lead_a is not None and lv_ask:
                side_max_ask = max(side_max_ask, lead_n)
            maxpos = series_max_position(meta.series)
            if lead_b is not None or lead_a is not None:       # a leading market's cap
                maxpos = max(maxpos, FAIR_LEAD_MAX_POSITION if lead_src == "fair"
                             else COMP_LEAD_MAX_POSITION)
            side_max_bid, side_max_ask = clamp_side_max_to_position_cap(
                side_max_bid, side_max_ask, maxpos)
            # (MANUAL_COEXIST_EVENTS too: the user's positions there are his)
            cap_pos = own_pos if coexist else pos
            # FULL UNWIND (unwind_side_sizes): the reducing side's ladder bound
            # becomes the whole position; the position cap, the event share
            # and the skew below still bind. A side with no ladder stays dark.
            unwind_bid, unwind_ask = unwind_side_sizes(meta.series, cap_pos, maxpos)
            unwind_bid = unwind_bid if lv_bid else 0
            unwind_ask = unwind_ask if lv_ask else 0
            side_max_bid = max(side_max_bid, unwind_bid)
            side_max_ask = max(side_max_ask, unwind_ask)
            # FAIR CLOSE: the closing side's bound is the whole position (up
            # to FAIR_LEAD_MAX_POSITION), with first call on the event's room
            if close_n and cap_pos < 0 and lv_bid:
                unwind_bid = max(unwind_bid, close_n)
                side_max_bid = max(side_max_bid, close_n)
                share_buy = max(share_buy, event_room_buy.get(ev, event_cap_contracts(ev)))
            if close_n and cap_pos > 0 and lv_ask:
                unwind_ask = max(unwind_ask, close_n)
                side_max_ask = max(side_max_ask, close_n)
                share_sell = max(share_sell, event_room_sell.get(ev, event_cap_contracts(ev)))
            # (a series' own side cut scales the position room too, so the
            # side rests the cut share of whichever bound binds: the ladder
            # and the event share carry it already)
            pos_room_buy, pos_room_sell = side_cut_room(
                meta.series, maxpos - cap_pos, maxpos + cap_pos)
            # LEAD INVENTORY (FAIR_LEAD_INV_QUOTE): the side a fair-lead
            # market's position adds to, with no lead on it, quotes its normal
            # rung as if the first FAIR_LEAD_MAX_POSITION of the position were
            # not there -- the series' own cap and skew judge the excess only
            skew_b = skew_a = cap_pos
            if FAIR_LEAD_INV_QUOTE and meta.series in FAIR_LEAD_SERIES:
                _xs = cap_pos - max(-FAIR_LEAD_MAX_POSITION,
                                    min(FAIR_LEAD_MAX_POSITION, cap_pos))
                _base = series_max_position(meta.series)
                # (a lead still on that side rests the rest of its own cap)
                if cap_pos >= 1:
                    skew_b = _xs
                    if lead_b is None:
                        pos_room_buy = side_cut_room(meta.series, _base - _xs,
                                                     _base + _xs)[0]
                if cap_pos <= -1:
                    skew_a = _xs
                    if lead_a is None:
                        pos_room_sell = side_cut_room(meta.series, _base - _xs,
                                                      _base + _xs)[1]
            room_buy = min(pos_room_buy, share_buy, side_max_bid)
            room_sell = min(pos_room_sell, share_sell, side_max_ask)
            fam_m = applied_mention_mult(meta.series)
            room_buy = skewed_side_room(room_buy, skew_b, accumulating=skew_b > 0,
                                        side_max=side_max_bid,
                                        soft=SKEW_SOFT_CONTRACTS * fam_m,
                                        hard=SKEW_HARD_CONTRACTS * fam_m)
            room_sell = skewed_side_room(room_sell, skew_a, accumulating=skew_a < 0,
                                         side_max=side_max_ask,
                                         soft=SKEW_SOFT_CONTRACTS * fam_m,
                                         hard=SKEW_HARD_CONTRACTS * fam_m)
            if reduce_only:
                # Only the reducing side, and never more than would flatten our
                # OWN book (a +5 position must not sell 35 and flip short 30).
                if own_pos > 0:
                    room_buy = 0.0
                    room_sell = min(room_sell, own_pos)
                elif own_pos < 0:
                    room_sell = 0.0
                    room_buy = min(room_buy, -own_pos)
                else:
                    room_buy = room_sell = 0.0
            # far-strike ask (QUAKE_ASK_STRIKES): QUAKE_ASK_MAX_CONTRACTS at
            # most, less the short its fills already sold
            quake_ask_room = int(max(0.0, QUAKE_ASK_MAX_CONTRACTS - max(0.0, -cap_pos)))
            if quake_ask_strike(t):
                room_sell = min(room_sell, float(quake_ask_room))

            # JOIN AHEAD OF THE PILE (2026-10-11, JOIN_AHEAD_MODE): the
            # at-reference rung may rest ahead of a pile its own size
            # demotes. Never where a fair gate caps a side this cycle (the
            # gate owns that price), nor on sub-penny books or reduce-only.
            pl_bid_px, pl_ask_px = ref_bid_px, ref_ask_px
            if (join_ahead_series(meta.series) and not reduce_only
                    and meta.price_step >= 0.01 and not quake_ask_strike(t)
                    and quake_cap is None and yt1_cap is None and mort_caps is None
                    and poke_caps is None and nfl_caps is None
                    and ca_caps is None and rain_caps is None):
                try:
                    pl_bid_px, pl_ask_px = self._join_ahead(
                        t, meta, yes_levels, no_levels, own_in_book, ext_bid,
                        ext_ask, ref_bid_px, ref_ask_px, lv_bid, lv_ask,
                        room_buy, room_sell, unwind_bid, unwind_ask, hm,
                        rung_lo, pmin_s, pmax_s)
                except Exception as e:      # never costs the cycle: plain refs
                    pl_bid_px, pl_ask_px = ref_bid_px, ref_ask_px
                    if not getattr(self, "_join_ahead_err_logged", False):
                        self._join_ahead_err_logged = True
                        log(f"{self.tag} ! join-ahead failed on {t} ({e!r}); "
                            f"plain reference placement (logged once)")

            # a leading side rests at its lead price, anchored there (the
            # anchor caps an at-ref rung) and at least target/5
            lead_on_b = lead_b is not None and bool(lv_bid)
            lead_on_a = lead_a is not None and bool(lv_ask)
            anc_bid, anc_ask = ext_bid, ext_ask
            if lead_on_b:
                pl_bid_px = anc_bid = lead_b[0]
            if lead_on_a:
                pl_ask_px = anc_ask = lead_a[0]
            if lead_on_b or lead_on_a:
                self._comp_lead_px[t] = (lead_b[0] if lead_on_b else None,
                                         lead_a[0] if lead_on_a else None, lead_n)
                self._note_comp_hold(t, self._comp_lead_px[t][0],
                                     self._comp_lead_px[t][1], now_ts)
                for _sd, _px in (("bid", self._comp_lead_px[t][0]),
                                 ("ask", self._comp_lead_px[t][1])):
                    if _px is not None:      # a fill read later still matches it
                        _seen = self._comp_lead_seen.setdefault((t, _sd), {})
                        _seen[_px] = now_ts
                        for _old in [k for k, at in _seen.items() if now_ts - at > 600.0]:
                            _seen.pop(_old, None)
            else:
                self._comp_lead_px.pop(t, None)
            # FAIR CLOSE: the closing rung rests at the model's price only where
            # that beats where the side would rest without it (fair_close_mark:
            # its lead, else its external best and reference, off the book
            # WITHOUT our orders -- 10/30 16:18Z: SGF's 200 at 58c set its own
            # mark a cycle after it rested and read as "already as near"); it
            # never crosses our own other side. The reducing side's own rung
            # rests at that mark too, so a big closing order never holds its
            # side where it stands once the model moves.
            _mb = _ma = None
            if _cfair is not None:
                _mb = fair_close_mark("bid", lead_b[0] if lead_on_b else None,
                                      _cx_yes, _cx_no, meta.target_size)
                _ma = fair_close_mark("ask", lead_a[0] if lead_on_a else None,
                                      _cx_yes, _cx_no, meta.target_size)
            close_on_b = (close_b is not None and bool(lv_bid)
                          and (_mb is None or close_b[0] > _mb)
                          and not (lead_on_a and close_b[0] >= lead_a[0]))
            close_on_a = (close_a is not None and bool(lv_ask)
                          and (_ma is None or close_a[0] < _ma)
                          and not (lead_on_b and close_a[0] <= lead_b[0]))
            if close_n and cap_pos < 0 and _mb is not None:
                pl_bid_px = _mb
            if close_n and cap_pos > 0 and _ma is not None:
                pl_ask_px = _ma
            if _cfair is not None:
                self._fair_close_note(t, close_b if close_on_b else None,
                                      close_a if close_on_a else None, _cpos,
                                      _cfair, _cx_yes, _cx_no, avg_c=_cavg)
            if FAIR_CLOSE_MODE != "on":
                close_on_b = close_on_a = False
            if close_on_b or close_on_a:
                self._fair_close_px[t] = (("bid", close_b[0]) if close_on_b
                                          else ("ask", close_a[0]))
            else:
                self._fair_close_px.pop(t, None)

            mq: List[Quote] = []
            # atref: placement no longer follows the touch, so a touch
            # outside the band must not kill the side (see build_side_ladder).
            # pmin_s/pmax_s carry the member-widened band (2-98 for sticky).
            if ext_bid is not None and room_buy > 0 and bid_in_band:
                px_ok = (LADDER_MODE == "atref" and ref_bid_px is not None) \
                    or ext_bid >= pmin_s
                if px_ok:
                    n_c = min(close_b[1], int(room_buy)) if close_on_b else 0
                    rest_b = int(room_buy) - n_c
                    # the side's own rung first: the diff then resizes an old
                    # rung into it and places the closing rung beside it
                    if rest_b > 0:
                        mq.extend(build_side_ladder(
                            t, "bid", anc_bid, ext_ask, rest_b, levels=lv_bid,
                            ref_px=pl_bid_px, band=(rung_lo, pmax_s), hour_mult=hm,
                            min_total=max(0 if close_on_b else unwind_bid,
                                          lead_n if lead_on_b else 0)))
                    if n_c:
                        mq.extend(build_side_ladder(t, "bid", close_b[0], ext_ask, n_c,
                                                    levels=lv_bid, ref_px=close_b[0],
                                                    band=(rung_lo, pmax_s),
                                                    hour_mult=hm, min_total=n_c))
            if ext_ask is not None and room_sell > 0 and ask_in_band:
                px_ok = (LADDER_MODE == "atref" and ref_ask_px is not None) \
                    or ext_ask <= pmax_s
                if px_ok:
                    n_c = min(close_a[1], int(room_sell)) if close_on_a else 0
                    rest_a = int(room_sell) - n_c
                    # the side's own rung first: the diff then resizes an old
                    # rung into it and places the closing rung beside it
                    if rest_a > 0:
                        mq.extend(build_side_ladder(
                            t, "ask", anc_ask, ext_bid, rest_a, levels=lv_ask,
                            ref_px=pl_ask_px, band=(rung_lo, pmax_s), hour_mult=hm,
                            min_total=max(0 if close_on_a else unwind_ask,
                                          lead_n if lead_on_a else 0)))
                    if n_c:
                        mq.extend(build_side_ladder(t, "ask", close_a[0], ext_bid, n_c,
                                                    levels=lv_ask, ref_px=close_a[0],
                                                    band=(rung_lo, pmax_s),
                                                    hour_mult=hm, min_total=n_c))

            # quake gate: every bid rung at most the fair cap; asks only on an
            # ask strike whose ask may rest, at the floor or above
            if quake_cap is not None:
                mq = quake_cap_quotes(mq, quake_cap, quake_ask_c, quake_ask_room)
            # the #1 leader-bid pilot: every bid rung at most its cap, no ask
            if yt1_cap is not None:
                mq = quake_cap_quotes(mq, yt1_cap)
            # monthly rain one side (RAIN_MONTHLY_ONE_SIDE): the side that
            # fights the fair rests no rung -- dropped before the pads, so a
            # member pads it for depth like any rungless side
            if rain_side_out is not None:
                mq = [q for q in mq if q.book_side != rain_side_out]
            # Vercel bid only (VERCEL_BID_ONLY): the same, for the asks
            if vc_side_out is not None:
                mq = [q for q in mq if q.book_side != vc_side_out]

            # Depth padding: on a side we're actually quoting whose total depth
            # is below the reward target, add throwaway contracts at the 1c/99c
            # mark so the whole side (and thus our near-touch ladder) qualifies.
            if series_pad_to_target(meta.series) and meta.target_size > 0 \
                    and pad_band_ok(meta.series, ext_bid, ext_ask):
                mq.extend(self._pad_quotes(
                    t, mq, yes_levels, no_levels, own, meta.target_size,
                    # coverage-leak fix: rent-earning members pad the rungless
                    # side too (one-sided snapshots pay nobody); reduce-only
                    # tails keep the old single-side behavior
                    pad_missing_side=(t in self.state.selected
                                      and not reduce_only),
                    ext_bid=ext_bid, ext_ask=ext_ask))

            # SUB-PENNY JOIN (Jack 2026-09-26, see subpenny_snap): on a market
            # priced finer than a cent, rest each rung AT the scored touch
            # inside its cent bucket instead of a fraction of a cent behind.
            if SUBPENNY_JOIN and mq and meta.price_step < 0.01:
                _yx, _nx = orderbook_exact_levels(ob)
                mq = subpenny_snap(mq, _yx, _nx,
                                   own_exact_by_ticker.get(t, []) if self.live else [])
            # SUB-CENT EDGE (Jack 2026-10-04, see subcent_edge_quotes): a
            # sports ladder / escalator side the whole-cent ladder left
            # empty, with its exact touch in 0.05-1c (bid) or 99-99.5c (ask)
            if (SUBPENNY_JOIN and meta.price_step < 0.01
                    and sports_ladder_league(meta.series) is not None):
                _has = {q.book_side for q in mq if not q.is_pad}
                _yx, _nx = orderbook_exact_levels(ob)
                mq.extend(subcent_edge_quotes(
                    t, _yx, _nx,
                    own_exact_by_ticker.get(t, []) if self.live else [],
                    bid_size=(int(min(side_max_bid, room_buy))
                              if (lv_bid and "bid" not in _has) else 0),
                    ask_size=(int(min(side_max_ask, room_sell))
                              if (lv_ask and "ask" not in _has) else 0)))
            # mortgage gate: LAST, after pads and the sub-penny snap, so
            # nothing rests within MORT_FAIR_TOL_CENTS of the fair
            if mort_caps is not None:
                mq = mort_cap_quotes(mq, *mort_caps)
            # Pokemon gate: likewise last, POKE_FAIR_TOL_CENTS clear
            if poke_caps is not None:
                mq = mort_cap_quotes(mq, *poke_caps)
            # NFL prop gate: likewise last, inside the player-history band,
            # and a side the caps left out of the scored walk does not rest
            # at all ("only quote a market if you're earning")
            if nfl_caps is not None:
                mq = nfl_cap_quotes(mq, *nfl_caps, price_step=meta.price_step)
                _n_before = {q.book_side for q in mq if not q.is_pad}
                if meta.price_step < 0.01:
                    # the walk runs over exact levels (see drop_unearning_sides)
                    _ey, _en = orderbook_exact_levels(ob)
                    mq = drop_unearning_sides(
                        mq, _ey, _en,
                        own_exact_by_ticker.get(t, []) if self.live else [],
                        meta.target_size, meta.discount_factor)
                else:
                    mq = drop_unearning_sides(mq, yes_levels, no_levels,
                                              own_in_book, meta.target_size,
                                              meta.discount_factor)
                _dropped = _n_before - {q.book_side for q in mq if not q.is_pad}
                if _dropped != self._nfl_unearning.get(t, set()):
                    if _dropped:
                        log(f"{self.tag} nfl not earning {t}: "
                            f"{'/'.join(sorted(_dropped))} side(s) out of the "
                            f"scored walk after the caps {nfl_caps} "
                            f"(book {ext_bid}x{ext_ask}) -- not resting them")
                    self._nfl_unearning[t] = _dropped
            # Carbon Arc gate (CA_FAIR_CAP): likewise last -- the side whose
            # touch fights the read rests at most at its cap, and only while
            # the scored walk still reaches it ("sit on the bid if it's
            # earning money on it, but not if it wouldnt earn")
            if ca_caps is not None:
                mq = mort_cap_quotes(mq, *ca_caps)
                _c_before = {q.book_side for q in mq if not q.is_pad}
                if meta.price_step < 0.01:
                    _ey, _en = orderbook_exact_levels(ob)
                    mq = drop_unearning_sides(
                        mq, _ey, _en,
                        own_exact_by_ticker.get(t, []) if self.live else [],
                        meta.target_size, meta.discount_factor)
                else:
                    mq = drop_unearning_sides(mq, yes_levels, no_levels,
                                              own_in_book, meta.target_size,
                                              meta.discount_factor)
                _c_dropped = _c_before - {q.book_side for q in mq if not q.is_pad}
                if _c_dropped != self._ca_unearning.get(t, set()):
                    if _c_dropped:
                        log(f"{self.tag} ca-fair not earning {t}: "
                            f"{'/'.join(sorted(_c_dropped))} side(s) out of "
                            f"the scored walk after the caps {ca_caps} "
                            f"(book {ext_bid}x{ext_ask}) -- not resting them")
                    self._ca_unearning[t] = _c_dropped
            # period rain gate (RAIN_PERIOD_CAP): the Carbon Arc rule -- the
            # side whose touch fights the fair rests at most at its cap, and
            # only while the scored walk still reaches it
            if rain_caps is not None:
                mq = mort_cap_quotes(mq, *rain_caps)
                _r_before = {q.book_side for q in mq if not q.is_pad}
                if meta.price_step < 0.01:
                    _ey, _en = orderbook_exact_levels(ob)
                    mq = drop_unearning_sides(
                        mq, _ey, _en,
                        own_exact_by_ticker.get(t, []) if self.live else [],
                        meta.target_size, meta.discount_factor)
                else:
                    mq = drop_unearning_sides(mq, yes_levels, no_levels,
                                              own_in_book, meta.target_size,
                                              meta.discount_factor)
                _r_dropped = _r_before - {q.book_side for q in mq if not q.is_pad}
                if _r_dropped != self._rain_period_unearning.get(t, set()):
                    if _r_dropped:
                        log(f"{self.tag} {wx} not earning {t}: "
                            f"{'/'.join(sorted(_r_dropped))} side(s) out of "
                            f"the scored walk after the caps {rain_caps} "
                            f"(book {ext_bid}x{ext_ask}) -- not resting them")
                    self._rain_period_unearning[t] = _r_dropped
            # Vercel bid only (VERCEL_BID_ONLY): the bid rests only while the
            # scored walk still reaches it
            if vc_side_out is not None:
                _v_before = {q.book_side for q in mq if not q.is_pad}
                if meta.price_step < 0.01:
                    _ey, _en = orderbook_exact_levels(ob)
                    mq = drop_unearning_sides(
                        mq, _ey, _en,
                        own_exact_by_ticker.get(t, []) if self.live else [],
                        meta.target_size, meta.discount_factor)
                else:
                    mq = drop_unearning_sides(mq, yes_levels, no_levels,
                                              own_in_book, meta.target_size,
                                              meta.discount_factor)
                _v_dropped = _v_before - {q.book_side for q in mq if not q.is_pad}
                if _v_dropped != self._vercel_unearning.get(t, set()):
                    if _v_dropped:
                        log(f"{self.tag} vercel not earning {t}: the bid is out "
                            f"of the scored walk (book {ext_bid}x{ext_ask}) -- "
                            f"not resting it")
                    self._vercel_unearning[t] = _v_dropped
            desired.extend(mq)
            if mq:
                quoted += 1
                # pads excluded: the event cap bounds NET INVENTORY risk, and
                # a 1c/99c pad's worst case is ~1c/contract. Counting them
                # burned the whole event's buy room after a few padded thin
                # strikes and silently killed every later sibling's YES side
                # (live bug 2026-07-29, TRUMPMENTIONB: ask-only on ~20
                # strikes the morning pads went global).
                bought = sum(q.count for q in mq
                             if q.book_side == "bid" and not q.is_pad)
                sold = sum(q.count for q in mq
                           if q.book_side == "ask" and not q.is_pad)
                event_room_buy[ev] = event_room_buy.get(ev, event_cap_contracts(ev)) - bought
                event_room_sell[ev] = event_room_sell.get(ev, event_cap_contracts(ev)) - sold

            # Reward-share estimate for status/summary + zero-share benching.
            # Live: our resting orders are already inside the fetched book.
            # Dry: overlay the DESIRED ladder (sim resting ~= desired; using
            # both would double-count).
            est_own = own if self.live else \
                [(q.book_side, q.price_cents, float(q.count)) for q in mq]
            frac, sides = estimate_reward_share(
                yes_levels, no_levels, est_own,
                meta.target_size, meta.discount_factor, own_in_book=self.live)
            self._coverage(t, sides == 2)   # observability only (see _coverage)
            # Coverage alert (2026-08-02): a member quoting into a snapshot
            # that can't count is the worst rent-per-risk state — page after
            # N consecutive FULL cycles (pads should make this ~impossible).
            # (A side or event stood down by the toxic-flow halt is one-sided
            # or dark ON PURPOSE -- if our pad was what lifted a side to
            # target, it stops qualifying -- so it neither counts nor pages;
            # nor does one the sweep or group breaker holds, or one on a shard
            # Kalshi has paused: coverage_exempt.)
            if not fast_only and t in self.state.selected and mq \
                    and pad_band_ok(meta.series, ext_bid, ext_ask) \
                    and not self.coverage_exempt(t, now_ts):
                if sides < 2:
                    streak = self.state.coverage_zero_streak.get(t, 0) + 1
                    self.state.coverage_zero_streak[t] = streak
                    if streak == COVERAGE_ALERT_CYCLES:
                        self.alerter.alert(
                            "coverage", f"{t}: quoted but only {sides} side(s) "
                            f"qualify for {streak} cycles (side under target "
                            f"{meta.target_size:.0f} despite pads?) — accruing "
                            f"ZERO while carrying fill risk", key=t)
                else:
                    self.state.coverage_zero_streak.pop(t, None)
            reward_frac_sum += frac * meta.dollars_per_day
            cycle_rate[t] = frac * meta.dollars_per_day
            # --- enriched quote shape + governing clamps -------------------
            # The 13 original columns reduce the whole quote to one scalar
            # (`quoted`), and yes_depth/no_depth INCLUDE our own resting size —
            # so competitor depth was not computable and "est_frac fell because
            # a farmer stacked in" could not be told apart from "est_frac fell
            # because my order got cancelled". Everything below is a live local
            # in this same iteration and was simply not written.
            #
            # Columns are APPENDED, never reordered: imm_reward_recon.py reads
            # this file positionally (row[0],[1],[7],[8],[11]) and gates on
            # len(row) >= 13, so appending is backward compatible and the
            # reward integral is untouched.
            try:
                # A tuple build raises NameError on the first unbound name and
                # we fall back to blanks — an analytics column can never crash
                # a live placement wave over a branch that skipped an assignment.
                _hm, _rlo, _rb, _rs, _ro = (hm, rung_lo, room_buy, room_sell,
                                            reduce_only)
            except NameError:
                _hm = _rlo = _rb = _rs = _ro = None
            try:
                ob = [(p, c) for s_, p, c in own if s_ == "bid"]
                oa = [(p, c) for s_, p, c in own if s_ == "ask"]
                shape = {
                    "own_bid_ct": sum(c for _p, c in ob),
                    "own_ask_ct": sum(c for _p, c in oa),
                    "own_bid_top": max((p for p, _c in ob), default=None),
                    "own_ask_top": min((p for p, _c in oa), default=None),
                    "own_pad_bid_ct": sum(c for p, c in ob if p == PAD_BID_CENTS),
                    "own_pad_ask_ct": sum(c for p, c in oa if p == PAD_ASK_CENTS),
                    "want_bid_ct": sum(q.count for q in mq if q.book_side == "bid"),
                    "want_ask_ct": sum(q.count for q in mq if q.book_side == "ask"),
                    "want_pad_ct": sum(q.count for q in mq if q.is_pad),
                }
            except Exception:
                shape = {}

            def _c(v, fmt="{:.0f}"):
                return "" if v is None else fmt.format(v)

            cycle_rows.append(
                f"{now_utc.strftime('%Y-%m-%dT%H:%M:%SZ')},{t},"
                f"{ext_bid if ext_bid is not None else ''},"
                f"{ext_ask if ext_ask is not None else ''},"
                f"{sum(q for _p, q in yes_levels):.0f},"
                f"{sum(q for _p, q in no_levels):.0f},"
                f"{meta.target_size:.0f},{frac:.5f},{sides},"
                f"{pos:.1f},{own_pos:.1f},{meta.dollars_per_day:.2f},"
                f"{sum(q.count for q in mq)},"
                # --- appended: quote shape (ours, so competitor depth =
                #     yes_depth - own_bid_ct) ---
                f"{_c(shape.get('own_bid_ct'))},{_c(shape.get('own_ask_ct'))},"
                f"{_c(shape.get('own_bid_top'))},{_c(shape.get('own_ask_top'))},"
                f"{_c(shape.get('own_pad_bid_ct'))},"
                f"{_c(shape.get('own_pad_ask_ct'))},"
                f"{_c(shape.get('want_bid_ct'))},{_c(shape.get('want_ask_ct'))},"
                f"{_c(shape.get('want_pad_ct'))},"
                # --- appended: what governed the size we chose ---
                f"{_c(_hm, '{:.2f}')},{_c(_rlo)},{_c(_rb)},{_c(_rs)},"
                # --- appended: market context + provenance ---
                f"{_c(meta.volume, '{:.0f}')},"
                f"{_c(meta.discount_factor, '{:.3f}')},"
                f"{1 if getattr(meta, 'scan', False) else 0},"
                f"{1 if t in self.state.selected else 0},"
                f"{1 if _ro else 0},{1 if fast_only else 0},"
                f"{RUN_ID},{CONFIG_HASH}\n")

            # Cache the panel for the fills and orders sinks. A fill arrives
            # one cycle AFTER the read that produced the order it hit, so this
            # cached panel — not a fresh read — is the correct book context,
            # and it costs no API call.
            self._last_panel[t] = {
                "ts": now_utc.isoformat(), "ext_bid": ext_bid,
                "ext_ask": ext_ask,
                "yes_depth": sum(q for _p, q in yes_levels),
                "no_depth": sum(q for _p, q in no_levels),
                "target": meta.target_size, "est_frac": frac,
                "qual_sides": sides, "pool_per_day": meta.dollars_per_day,
                "is_scan": bool(getattr(meta, "scan", False)),
            }
            if t in self.state.selected and not reduce_only and not fast_only:
                # 2026-08-06: this read `frac <= 0.0 and mq`. `frac` is scored
                # from est_own (our RESTING orders) but the guard tested `mq`
                # (our DESIRED quotes), so an outage / failsafe cancel-all /
                # rejected placement struck every selected market every cycle
                # and benched 293 of 471 candidates against healthy books
                # (Kalshi maintenance 07:16-09:00Z, cancel-all 07:18:44Z, 307
                # benches 07:45:59-08:13:29Z, selected 390 -> 31, est reward
                # ~$404/day -> ~$159/day). Judge the list that produced frac,
                # and never during wake grace (post-sleep reads "can SUCCEED
                # with garbage", see the grace comment above) — the one gate
                # standoffs and universe selection already had and this counter
                # never did. See zero_share_strike_counts.
                # The `else` RESETS rather than pauses: the new condition is
                # strictly narrower, so a flapping outage lands in it on every
                # untrusted cycle and cannot bank strikes across good ones.
                # A toxic-flow halt empties our side / event on purpose: its
                # zero share must not bench the market for an hour on top.
                if mq and not in_grace and zero_share_strike_counts(frac, est_own) \
                        and not self.toxic_market_halted(t, now_ts):
                    streak = self.state.zero_share_streak.get(t, 0) + 1
                    self.state.zero_share_streak[t] = streak
                    if streak >= QUALIFY_PATIENCE_CYCLES:
                        self.state.bench_until[t] = now_ts + BENCH_COOLDOWN_SECS
                        self.state.zero_share_streak.pop(t, None)
                        self.cancel_market_orders(t, resting)
                        self.state.selected.pop(t, None)
                        desired = [q for q in desired if q.ticker != t]
                        # "book below target size?" was dead code — that case
                        # is cancelled and `continue`d by sides_can_qualify
                        # long before it can reach the counter. State what the
                        # condition now actually proves, with the numbers.
                        self.alerter.alert(
                            "benched", f"{t}: our non-pad size RESTING on both "
                            f"sides and still zero reward share for "
                            f"{QUALIFY_PATIENCE_CYCLES} cycles ({sides} side(s) "
                            f"qualify; yes {depth_yes:.0f} / no {depth_no:.0f} "
                            f"vs target {meta.target_size:.0f}); benched "
                            f"{BENCH_COOLDOWN_SECS // 3600}h", key=t, urgent=False)
                else:
                    self.state.zero_share_streak.pop(t, None)

        # the book-read REST budget's verdict for this cycle, then no budget
        # outside the read loop (BOOK_REST_BUDGET_SECS)
        br, self._book_rest = self._book_rest, None
        if br is not None and br["off"]:
            st = self._book_rest_stats
            st["cycles_off"] += 1
            st["last"] = (f"{datetime.fromtimestamp(now_ts, timezone.utc):%m-%d %H:%M:%S}Z: "
                          f"{br['off']} ({br['skipped']} kept as they rest)")
            log(f"{self.tag} ! book reads: REST stopped after {br['spent']:.0f}s -- "
                f"{br['off']}; {br['skipped']} market(s) the feed could not serve "
                f"kept their quotes as they rest (no blind count)")

        # Guard-skip sink: full cycles evaluate every managed market, so a
        # ticker missing from _guard_now reliably means its guard CLEARED.
        # Fast ticks touch only fast-lane series and never flush.
        if not fast_only:
            self._flush_guard_skips(now_utc, now_ts, managed)

        # Live-event depth gate, resume pass: release a THIN-only halt on a
        # full cycle where NO market of it read thin, EVERY managed market
        # of it was actually evaluated healthy — in-band, two-sided, at
        # target; a blind/breakered/pinned/one-sided market is not evidence
        # and blocks release by not counting — and the last thin reading is
        # EVENT_DEPTH_RESUME_SECS old (a book refilling for a moment
        # mid-speech must not re-enter us). Live-CONFIRMED events
        # (event_live_halt) never release. Events with no managed markets
        # keep their halt (nothing quotes them anyway; the 7d persist TTL
        # prunes dead ones), so a halt can never flap on selection churn.
        if not fast_only:
            for ev_h in list(self.state.event_depth_halt):
                if ev_h in self.state.event_live_halt \
                        or ev_h in event_depth_thin:
                    continue
                n_mkts = len(by_event.get(ev_h, []))
                if (n_mkts and event_depth_ok.get(ev_h, 0) >= n_mkts
                        and now_ts - self.state.event_depth_halt[ev_h]
                        >= EVENT_DEPTH_RESUME_SECS):
                    del self.state.event_depth_halt[ev_h]
                    n_ign = len(self.state.event_depth_ignore.pop(ev_h, ()))
                    log(f"{self.tag} event-depth resume {ev_h}: all "
                        f"{n_mkts} market(s) healthy and no thin side for "
                        f"{EVENT_DEPTH_RESUME_SECS // 60}min"
                        + (f" ({n_ign} out-of-band at the halt ignored)"
                           if n_ign else ""))

        # Reward accrual estimate between cycles (share x $/day x dt), plus the
        # objective's denominator: contract-minutes actually resting.
        resting_contracts = sum(order_remaining(o) for o in resting)
        # Accrual integrates on FULL cycles only: a fast tick computes rates
        # for the fast-lane subset alone, and advancing the shared accrue
        # stamp on it would steal that interval from every other market's
        # integral (hopeless-exit credit corruption).
        if not fast_only:
            if self.state.reward_accrue_at:
                dt_days = (now_ts - self.state.reward_accrue_at) / 86400.0
                accrued = reward_frac_sum * dt_days
                self.state.reward_est_today += accrued
                self.state.reward_est_lifetime += accrued
                # Per-market accrual (same integral, split by ticker) — the
                # hopeless-exit / floor credit: accrued + projection vs $1.
                paid_delta = 0.0
                for t_, rate in cycle_rate.items():
                    if rate > 0:
                        prev_acc = self.state.accrued_est.get(t_, 0.0)
                        new_acc = prev_acc + rate * dt_days
                        self.state.accrued_est[t_] = new_acc
                        # PAID basis: _paid_basis_delta (per program period
                        # since 2026-09-22, see FLOOR_ACCRUAL_PER_PERIOD).
                        paid_delta += self._paid_basis_delta(t_, prev_acc, new_acc)
                self.state.reward_paid_today += paid_delta
                self.state.reward_paid_lifetime += paid_delta
                self.state.contract_minutes_today += \
                    resting_contracts * (now_ts - self.state.reward_accrue_at) / 60.0
            self.state.reward_accrue_at = now_ts

        # LOSS HALT on TOTAL P&L today (realized + mark-to-market), so gapped
        # inventory counts even before it settles. Runs before any placement.
        # touch_map: the external touch of every book read this cycle, so a
        # one-sided or wide managed book is marked without our own quotes.
        self._refresh_marks(marked, touch_map)
        # Mark series for every open position, every 5 minutes.
        #
        # This is what makes adverse selection measurable. A mark-out needs the
        # book at the fill and the book N minutes LATER — and the cycle log
        # goes dark the moment selection drops a market, which is exactly what
        # happens after a bad fill (bench / hopeless / depth-gate all evict).
        # Keying on open positions instead of the managed set means the series
        # continues for as long as we still carry the risk, and it costs no
        # extra API call: _refresh_marks has just populated last_mark.
        if now_ts - self._marks_at >= 300:
            self._marks_at = now_ts
            try:
                for tkr, p in self.pnl.pos.items():
                    if abs(p) <= 1e-9:
                        continue
                    self._sink("marks", {
                        "ts": now_utc.isoformat(), "ticker": tkr,
                        "series": series_of(tkr),
                        "event_ticker": self._event_of(tkr),
                        "pos": p, "avg_cents": self.pnl.avg.get(tkr, 0.0),
                        "mark_cents": self.state.last_mark.get(tkr),
                        "realized_dollars": self.pnl.realized.get(tkr, 0.0),
                    })
            except Exception as e:
                if "marks" not in self._sink_muted:
                    self._sink_muted.add("marks")
                    log(f"{self.tag} ! marks sink failed ({e}); muted this run")
        unrealized = self.pnl.unrealized(self.state.last_mark)
        unmarked = [t for t, p in self.pnl.pos.items()
                    if abs(p) > 1e-9 and t not in self.state.last_mark]
        if unmarked:
            log(f"{self.tag} ! {len(unmarked)} position(s) unmarkable (valued at "
                f"cost): {', '.join(unmarked[:5])}")
        total_pnl = self.pnl.total_realized() + unrealized
        if self.state.day_baseline is None:
            self.state.day_baseline = total_pnl
        # pnl_carry composes the halt across restarts: realized resets with
        # the process, so the persisted carry (last measured pnl_today, same
        # roll-day) is added to the fresh measurement.
        pnl_today = total_pnl - self.state.day_baseline + self.state.pnl_carry
        self.state.pnl_today_last = pnl_today
        if pnl_today <= -DAILY_LOSS_LIMIT:
            # until the roll that resets this counter (_next_roll_utc)
            self.state.halted_until = _next_roll_utc(now_utc).timestamp()
            n = self.cancel_all_bot_orders()
            self.alerter.alert(
                "loss_halt", f"P&L today ${pnl_today:.2f} (realized ${realized:.2f}, "
                f"unrealized ${unrealized:+.2f} on "
                f"{self.pnl.inventory_contracts():.0f} carried) <= "
                f"-${DAILY_LOSS_LIMIT:.0f}; cancelled {n} orders, halted until "
                f"the {SUMMARY_HOUR_CT}am CT roll", key="loss_halt")
            if not fast_only:
                self._write_cycle_log(cycle_rows)
            return

        # OPEN-SCAN DAILY LOSS BUDGET (2026-09-05): the tier's own realized +
        # MTM today over every market it ever admitted (scan_book), carried
        # across restarts like pnl_today. Tripping it deselects every scan
        # member (inventory winds down reduce-only) and blocks admissions
        # until the 5am-CT roll that resets it (keyed by _halt_day_key, not
        # the ET date, since 2026-10-01). The whole-book halt above is untouched —
        # this bounds the blast radius of an unreviewed universe on its own.
        if SCAN_DAILY_LOSS_LIMIT > 0 and self.state.scan_book and not fast_only:
            scan_total = self._scan_book_pnl()
            if self.state.scan_pnl_baseline is None:
                self.state.scan_pnl_baseline = scan_total
            scan_today = (scan_total - self.state.scan_pnl_baseline
                          + self.state.scan_pnl_carry)
            self.state.scan_pnl_today_last = scan_today
            _roll_day = _halt_day_key(now_utc)
            if scan_today <= -SCAN_DAILY_LOSS_LIMIT \
                    and self.state.scan_halt_day != _roll_day \
                    and self.state.scan_members:
                self.state.scan_halt_day = _roll_day
                halted_ids = set(self.state.scan_members)
                n_cx = 0
                for t_h in sorted(halted_ids):
                    n_cx += self.cancel_market_orders(t_h, resting)
                    self.state.selected.pop(t_h, None)
                desired = [q for q in desired if q.ticker not in halted_ids]
                self.state.scan_members = set()
                self.state.scan_entry_mid.clear()
                self.alerter.alert(
                    "scan_halt",
                    f"open-scan tier P&L today ${scan_today:+.2f} <= "
                    f"-${SCAN_DAILY_LOSS_LIMIT:.0f}; cancelled {n_cx} orders on "
                    f"{len(halted_ids)} scan member(s) and closed the tier "
                    f"until the {SUMMARY_HOUR_CT}am CT roll (inventory winds down reduce-only)",
                    key="scan_halt")
                self._save_persist()

        # YOUTUBE #2 PILOT DAILY LOSS HALT (Jack 2026-10-05, see YT2_ENABLE):
        # the pilot's realized + marked P&L today, composed across restarts
        # like the scan tier's. At -YT2_DAILY_LOSS_LIMIT its orders are
        # cancelled now and the quote loop stands the family aside until the
        # 5am-CT roll (yt2_halt_day); positions ride to settlement.
        if YT2_ENABLE and YT2_DAILY_LOSS_LIMIT > 0 and not fast_only:
            yt2_total = self._yt2_pnl()
            if self.state.yt2_pnl_baseline is None:
                self.state.yt2_pnl_baseline = yt2_total
            yt2_today = (yt2_total - self.state.yt2_pnl_baseline
                         + self.state.yt2_pnl_carry)
            self.state.yt2_pnl_today_last = yt2_today
            _roll_day = _halt_day_key(now_utc)
            if yt2_today <= -YT2_DAILY_LOSS_LIMIT \
                    and self.state.yt2_halt_day != _roll_day:
                self.state.yt2_halt_day = _roll_day
                halted_ids = {str(o.get("ticker", "")) for o in resting
                              if yt2_series(series_of(str(o.get("ticker", ""))))}
                n_cx = 0
                for t_h in sorted(halted_ids):
                    n_cx += self.cancel_market_orders(t_h, resting)
                desired = [q for q in desired if not yt2_series(series_of(q.ticker))]
                self.alerter.alert(
                    "yt2_halt",
                    f"YouTube #2 pilot P&L today ${yt2_today:+.2f} <= "
                    f"-${YT2_DAILY_LOSS_LIMIT:.0f}; cancelled {n_cx} orders on "
                    f"{len(halted_ids)} market(s) and stood the family aside "
                    f"until the {SUMMARY_HOUR_CT}am CT roll (positions ride)",
                    key="yt2_halt")
                self._save_persist()

        # YOUTUBE WEEKLY PILOT DAILY LOSS HALT (Jack 2026-10-06, see
        # YTW_ENABLE): the #2 pilot's scheme for KXYTVIEWSW.
        if YTW_ENABLE and YTW_DAILY_LOSS_LIMIT > 0 and not fast_only:
            ytw_total = self._ytw_pnl()
            if self.state.ytw_pnl_baseline is None:
                self.state.ytw_pnl_baseline = ytw_total
            ytw_today = (ytw_total - self.state.ytw_pnl_baseline
                         + self.state.ytw_pnl_carry)
            self.state.ytw_pnl_today_last = ytw_today
            _roll_day = _halt_day_key(now_utc)
            if ytw_today <= -YTW_DAILY_LOSS_LIMIT \
                    and self.state.ytw_halt_day != _roll_day:
                self.state.ytw_halt_day = _roll_day
                halted_ids = {str(o.get("ticker", "")) for o in resting
                              if ytw_series(series_of(str(o.get("ticker", ""))))}
                n_cx = 0
                for t_h in sorted(halted_ids):
                    n_cx += self.cancel_market_orders(t_h, resting)
                desired = [q for q in desired if not ytw_series(series_of(q.ticker))]
                self.alerter.alert(
                    "ytw_halt",
                    f"YouTube weekly pilot P&L today ${ytw_today:+.2f} <= "
                    f"-${YTW_DAILY_LOSS_LIMIT:.0f}; cancelled {n_cx} orders on "
                    f"{len(halted_ids)} market(s) and stood the family aside "
                    f"until the {SUMMARY_HOUR_CT}am CT roll (positions ride)",
                    key="ytw_halt")
                self._save_persist()

        # PILOT DAILY LOSS HALTS (Jack 2026-10-11, see TWK_ENABLE): the
        # YouTube pilots' scheme, one budget per pilot_halt_key -- each Trump
        # weekly series, and the NFL head-to-head family as one (2026-10-12).
        tw_keys = pilot_halt_keys()
        if NFL_AUTO_ENABLE and NFL_AUTO_DAILY_LOSS_LIMIT > 0 and NFL_AUTO_SERIES:
            # the NFL auto families' per-event budgets (2026-10-12): every
            # event with P&L on the book or a selected market
            _tk = set(self.pnl.realized) | set(self.pnl.pos) | set(self.state.selected)
            tw_keys += sorted({k for k in map(pilot_budget_key, _tk)
                               if k and k.startswith(NFL_AUTO_BUDGET_PREFIX)})
        if LEAGUE_AUTO_ENABLE and LEAGUE_AUTO_DAILY_LOSS_LIMIT > 0 and LEAGUE_AUTO_SERIES:
            # ... and the league auto families' (2026-10-15), the same way
            _tk = set(self.pnl.realized) | set(self.pnl.pos) | set(self.state.selected)
            tw_keys += sorted({k for k in map(pilot_budget_key, _tk)
                               if k and k.startswith(LEAGUE_AUTO_BUDGET_PREFIX)})
        if tw_keys and not fast_only:
            _roll_day = _halt_day_key(now_utc)
            for tw_s in tw_keys:
                tw_limit = pilot_halt_limit(tw_s)
                if tw_limit <= 0:
                    continue
                tw_total = self._twk_pnl(tw_s)
                if tw_s not in self.state.twk_pnl_baseline:
                    self.state.twk_pnl_baseline[tw_s] = tw_total
                tw_today = (tw_total - self.state.twk_pnl_baseline[tw_s]
                            + self.state.twk_pnl_carry.get(tw_s, 0.0))
                self.state.twk_pnl_today_last[tw_s] = tw_today
                if tw_today <= -tw_limit \
                        and self.state.twk_halt_day.get(tw_s) != _roll_day:
                    self.state.twk_halt_day[tw_s] = _roll_day
                    halted_ids = {str(o.get("ticker", "")) for o in resting
                                  if pilot_budget_key(str(o.get("ticker", ""))) == tw_s}
                    n_cx = 0
                    for t_h in sorted(halted_ids):
                        n_cx += self.cancel_market_orders(t_h, resting)
                    desired = [q for q in desired
                               if pilot_budget_key(q.ticker) != tw_s]
                    self.alerter.alert(
                        "twk_halt",
                        f"pilot {tw_s} P&L today ${tw_today:+.2f} <= "
                        f"-${tw_limit:.0f}; cancelled {n_cx} orders on "
                        f"{len(halted_ids)} market(s) and stood {tw_s} aside "
                        f"until the {SUMMARY_HOUR_CT}am CT roll (positions ride)",
                        key=f"twk_halt:{tw_s}")
                    self._save_persist()

        # TOXIC-FLOW SIDE HALT (Jack 2026-09-29, see TOXIC_HALT): judge the
        # fills that came due against this cycle's marks (quoted markets were
        # marked from their books, every open position by _refresh_marks),
        # then drop each halted side's quotes -- rungs and pads -- from
        # `desired`, so the diff cancels whatever rests there.
        if TOXIC_HALT:
            if not fast_only:
                self._toxic_confirm(
                    now_ts, marked | {t_ for t_, p_ in self.pnl.pos.items()
                                      if abs(p_) > 1e-9})
            desired = [q for q in desired
                       if not self.toxic_side_halted(q.ticker, q.book_side, now_ts)
                       and not self.toxic_event_halted(self._event_of(q.ticker),
                                                       now_ts)]

        # BAIT-FINGERPRINT STOP (2026-10-22, see BAIT_STOP_MODE): read the
        # tape for the whole-rung fills queued since the last cycle, then
        # drop each stopped side's quotes -- rungs and pads -- so the diff
        # cancels whatever of ours rests there until ET midnight (the event's
        # lone-ref guard turns ON from the next cycle)
        if BAIT_STOP_MODE in ("on", "dry"):
            if not fast_only:
                self._bait_check_pending(now_ts)
            if self.state.bait_side_until:
                desired = [q for q in desired
                           if not self.bait_side_stopped(q.ticker, q.book_side, now_ts)]

        # EVENT SWEEP BREAKER (on, 2026-10-04, see SWEEP_BREAKER): an event a
        # sweep tripped quotes nothing until its hold ends, so the diff
        # cancels whatever of ours still rests there
        if SWEEP_BREAKER == "on" and self._sweep_hold:
            desired = [q for q in desired
                       if not self.sweep_held(self._event_of(q.ticker), now_ts)]
        # ...and the cross-event breaker's held SIDES (on, 2026-10-17, see
        # SWEEP_GROUP): nothing on that side of the group until the hold ends
        if SWEEP_GROUP == "on" and self._grp_hold:
            desired = [q for q in desired
                       if not self.group_held(q.ticker, q.book_side, now_ts)]

        # Fast tick: non-fast managed markets built no `desired` this tick —
        # preserve their resting orders through the diff or it would cancel
        # every one of them as unmatched.
        preserve = (blind | quake_held) if not fast_only else \
            blind | quake_held | {mt for mt, mm in managed.items()
                                  if not series_fast_lane(mm.series)}
        to_place, to_cancel, to_amend = diff_orders(
            desired, resting, self.state.order_ages, now_ts,
            preserve_tickers=preserve, touch_by_ticker=touch_map)
        # held quake bids skip the diff (preserve) -- renew the ones due for
        # the TTL refresh at their own price and size (QUAKE_HOLD_RENEW)
        if QUAKE_HOLD_RENEW and quake_held:
            renew_place, renew_cancel = quake_hold_renewals(
                resting, quake_held, self.state.order_ages, now_ts,
                ask_ok=quake_ask_renew)
            for q in renew_place:
                log(f"{self.tag} quake hold renew {q.ticker}: "
                    f"{q.book_side.upper()} {q.count}x @ "
                    + (f"{q.price_exact:.2f}c" if q.price_exact is not None
                       else f"{q.price_cents}c")
                    + " (same price and size, TTL renewal while held)")
            to_place.extend(renew_place)
            to_cancel.extend(renew_cancel)
        log(f"{self.tag} {quoted}/{len(managed)} mkts quoted, {len(resting)} resting, "
            f"{len(to_amend)} amend, {len(to_cancel)} cancel, {len(to_place)} place, "
            f"est ${reward_frac_sum:.2f}/day reward share, P&L today ${pnl_today:+.2f} "
            f"(real {realized:+.2f}/unreal {unrealized:+.2f}) "
            f"{'[fast] ' if fast_only else ''}{'' if self.live else '[DRY RUN]'}")
        if not fast_only:
            log(f"{self.tag} " + risk_line(
                self._acct_reading, pnl_today,
                self.state.scan_pnl_today_last if self.state.scan_book else None))

        # Watchdog: markets selected but the book nearly empty for several
        # consecutive cycles — the silent-death signature (dead cutoffs,
        # missing overrides, API trouble). Page, don't wait to be noticed.
        # EXCHANGE PAUSE (2026-10-22): a shard Kalshi has paused cannot rest
        # orders, so its markets are left out (_xp_watchdog_view).
        wd_sel, wd_rest = self.state.selected, resting
        if not fast_only:
            self._xp_check(time.time())
            wd_sel, wd_rest = self._xp_watchdog_view(wd_sel, wd_rest)
        if fast_only:
            pass   # watchdog streaks count FULL cycles only (stable semantics)
        elif (len(wd_sel) >= WATCHDOG_MIN_SELECTED
                and len(wd_rest) < WATCHDOG_MIN_RESTING):
            self.state.watchdog_streak += 1
            if self.state.watchdog_streak == WATCHDOG_CYCLES:
                self.alerter.alert(
                    "watchdog", f"{len(wd_sel)} markets selected but "
                    f"only {len(wd_rest)} orders resting for {WATCHDOG_CYCLES} "
                    f"cycles — quoting looks silently dead (cutoffs? overrides? "
                    f"API?)", key="watchdog")
        else:
            self.state.watchdog_streak = 0

        # Amends FIRST (they're the urgent repricing and never free/consume
        # cap room), then cancels, then fresh placements. Paced like the
        # placements (PLACE_RATE_PER_SEC): the cap they share went 250 ->
        # 1000 on 10/1, and an amend bounced by an account-wide 429 storm
        # leaves the stale price resting, which is worse than a short wait.
        am_pacer = WritePacer(PLACE_RATE_PER_SEC if self.live else 0.0)
        for o_am, q_am in to_amend[:MAX_PLACEMENTS_PER_CYCLE]:
            if self._xp_waiting(q_am.ticker, time.time()):
                continue                   # its shard is paused (EXCH_PAUSE_MODE)
            am_pacer.wait()
            self._ws_cycle_tick()          # the in-cycle stale check / breaker
            if self.sweep_held(self._event_of(q_am.ticker), time.time()):
                self._sweep["skipped_writes"] += 1
                continue                   # the breaker pulled it this cycle
            if self.group_held(q_am.ticker, q_am.book_side, time.time()):
                self._grp["skipped_writes"] += 1
                continue                   # the group breaker pulled it
            self.amend_order_inplace(o_am, q_am, now_ts)
        if len(to_amend) > MAX_PLACEMENTS_PER_CYCLE:
            log(f"{self.tag} amend cap: {len(to_amend) - MAX_PLACEMENTS_PER_CYCLE} "
                f"deferred to next cycle")

        # REQUOTE_INTERLEAVE (2026-09-27): a cancel whose order is being
        # REPLACED runs inside place_with_caps, right before its replacement;
        # only cancels with no replacement run here, first, as before.
        if REQUOTE_INTERLEAVE:
            replaces, first_cancels = pair_requotes(to_place, to_cancel, resting)
        else:
            replaces, first_cancels = {}, list(to_cancel)
        cancel_failures = 0
        cancelled_ids: Set[str] = set()
        for oid in first_cancels:
            self._ws_cycle_tick()
            if self.cancel_order(oid, reason="requote_diff"):
                self.state.cancelled_today += 1
                cancelled_ids.add(oid)
            else:
                cancel_failures += 1
        if cancel_failures:
            raise RuntimeError(f"{cancel_failures} cancel(s) failed")

        swap_failures: List[str] = []
        placed = self.place_with_caps(to_place, resting, cancelled_ids, now_ts,
                                      replaces=replaces,
                                      failed_cancels=swap_failures)
        if placed:
            # Persist order-ids NOW, right after placing — not at end-of-cycle.
            # A hard-kill in the window between placement and the end-of-cycle
            # save orphaned the fills (the order_id never hit disk, so the
            # fill read back as "manual"). Saving here shrinks that window to
            # near zero; the startup reconcile mops up anything still missed.
            # Nothing the file holds changes in the rest of the cycle (in-
            # process counters, the WS view, the cycle logs), so write_status
            # does not write the same bytes again (_cycle_saved, 2026-10-10).
            self._cycle_saved = self._save_persist()
        self.state.placed_today += placed
        # the stale-quote check's view of what rests now (shadow: counting)
        if self._ws is not None and WS_MODE in ("on", "shadow"):
            try:
                self._build_resting_view(resting, now_ts)
            except Exception as e:
                log(f"{self.tag} ! WS resting view failed: {e}")
            # back of the line (2026-10-17): the plan, on the view just built
            # (its reads and moves run between cycles, in _idle)
            if not fast_only:
                self._back_of_line_pass(resting, now_ts)
                # the dollar limits (2026-10-17, dry) judge the account's
                # positions as this cycle read them, between cycles
                self._risk_positions = dict(positions)
        # rate-limit alert (2026-10-17): any 429 rejection, ours or the fleet's
        self._rate_limit_watch(time.time())
        if not fast_only:
            self.state.cycles_today += 1
            self.state.last_markets_line = (
                f"{quoted}/{len(managed)} mkts quoted ({len(desired)} quotes), "
                f"est ${reward_frac_sum:.2f}/day")
            self._write_cycle_log(cycle_rows)
        else:
            # Fast-lane mini-cycles BUILT these rows and then threw them away
            # — the highest-resolution book snapshots this bot takes (5s on
            # its fastest family) were discarded every time.
            #
            # They go to a SEPARATE file, deliberately. imm_reward_recon.py
            # derives each market's accrual from the gap between consecutive
            # distinct timestamps in cycle_log_*.csv; interleaving 5s rows
            # would shrink those gaps and silently under-count the reward
            # estimate that the whole realization factor rests on. The
            # filename must also not match its cycle_log_*.csv glob.
            self._write_fast_log(cycle_rows)
        if swap_failures:
            # A replaced order whose cancel failed kept resting and its
            # successor was not placed. Same consequence as a failed cancel
            # always had: the cycle counts as errored for the failsafe (raised
            # last, so this cycle's placements and logs are already saved).
            raise RuntimeError(f"{len(swap_failures)} cancel(s) failed")

    # 13 original columns + 21 appended 2026-09-06. APPEND ONLY, never
    # reorder: imm_reward_recon.py reads this file positionally
    # (row[0],[1],[7],[8],[11]) and gates on len(row) >= 13.
    CYCLE_LOG_HEADER = ("ts,ticker,ext_bid,ext_ask,yes_depth,no_depth,target,"
                        "est_frac,qual_sides,acct_pos,own_pos,pool_per_day,quoted,"
                        "own_bid_ct,own_ask_ct,own_bid_top,own_ask_top,"
                        "own_pad_bid_ct,own_pad_ask_ct,"
                        "want_bid_ct,want_ask_ct,want_pad_ct,"
                        "hour_mult,rung_lo,room_buy,room_sell,"
                        "vol24h,discount,is_scan,is_sticky,reduce_only,fast,"
                        "run_id,config_hash\n")

    def _write_cycle_log(self, rows: List[str]) -> None:
        """Per-cycle book panel -> daily CSV. This is the jump-frequency /
        qualification-flap sensor the strategy's calibration runs on; every
        dry-run day without it is data thrown away. Never raises."""
        if not rows or os.environ.get("IMM_CYCLE_LOG", "1") != "1":
            return
        try:
            os.makedirs(STATUS_DIR, exist_ok=True)
            path = os.path.join(
                STATUS_DIR,
                f"cycle_log_{datetime.now(timezone.utc).strftime('%Y-%m-%d')}.csv")
            fresh = not os.path.exists(path)
            # Schema transition: today's file may already carry an older,
            # narrower header. Re-emitting the header INLINE is safe and is
            # the cleanest signal to a reader that the width changed —
            # imm_reward_recon.py already skips any row whose first field is
            # "ts", so the reward integral is unaffected, and a pandas reader
            # can split the day on header rows. Rewriting the first line of an
            # 80 MB file mid-run would be far riskier than a second header.
            if not fresh and not self._cycle_hdr_ok:
                try:
                    with open(path, encoding="utf-8") as chk:
                        cur = chk.readline()
                    if cur and cur.strip() != self.CYCLE_LOG_HEADER.strip():
                        with open(path, "a", encoding="utf-8") as f:
                            f.write(self.CYCLE_LOG_HEADER)
                        log(f"{self.tag} cycle log schema widened to "
                            f"{self.CYCLE_LOG_HEADER.count(',') + 1} cols; "
                            f"header re-emitted inline in {os.path.basename(path)}")
                except OSError:
                    pass
            self._cycle_hdr_ok = True
            with open(path, "a", encoding="utf-8") as f:
                if fresh:
                    f.write(self.CYCLE_LOG_HEADER)
                f.writelines(rows)
        except Exception as e:
            log(f"{self.tag} ! cycle log write failed: {e}")

    def _write_fast_log(self, rows: List[str]) -> None:
        """Fast-lane book panels -> daily CSV, same schema as the cycle log.

        Kept out of cycle_log_*.csv on purpose (see the call site): the
        reward reconciler integrates over timestamp gaps in that file, and
        5-second rows would corrupt the integral. Never raises."""
        if not rows or os.environ.get("IMM_CYCLE_LOG", "1") != "1":
            return
        try:
            os.makedirs(STATUS_DIR, exist_ok=True)
            path = os.path.join(
                STATUS_DIR,
                f"fastlane_{datetime.now(timezone.utc).strftime('%Y-%m-%d')}.csv")
            fresh = not os.path.exists(path)
            with open(path, "a", encoding="utf-8") as f:
                if fresh:
                    f.write(self.CYCLE_LOG_HEADER)
                f.writelines(rows)
        except Exception as e:
            if "fastlane" not in self._sink_muted:
                self._sink_muted.add("fastlane")
                log(f"{self.tag} ! fast-lane log write failed ({e}); muted")

    @staticmethod
    def _is_pad_price(book_side: str, px: int) -> bool:
        return (book_side == "bid" and px == PAD_BID_CENTS) or \
               (book_side == "ask" and px == PAD_ASK_CENTS)

    def _pad_quotes(self, ticker: str, near_touch: List[Quote],
                    yes_levels: List[List[float]], no_levels: List[List[float]],
                    own: List[Tuple[str, int, float]], target: float,
                    pad_missing_side: bool = False,
                    ext_bid: Optional[int] = None,
                    ext_ask: Optional[int] = None) -> List[Quote]:
        """Throwaway depth-padding at the 1c/99c mark so each side we quote
        reaches the reward target size. Computed on depth EXCLUDING our own pad
        (netted out / not-yet-in-book) to avoid a self-referential churn loop.
        By default only pads a side we have near-touch quotes on.
        pad_missing_side (2026-08-02 coverage-leak fix, SELECTED markets):
        also pad a side with NO rung whenever the OTHER side is quoted — a
        one-sided-qualified snapshot pays NOBODY, so the quoted side was
        carrying full fill risk for zero rent (the sides==1 class: 29 mkts
        in today's cycle log). A lone 1c/99c pad "leads" nothing worth
        leading and un-excludes the snapshot; if it ever fills it does so at
        the best possible price."""
        pads: List[Quote] = []
        nt_bid = sum(q.count for q in near_touch if q.book_side == "bid")
        nt_ask = sum(q.count for q in near_touch if q.book_side == "ask")
        own_pad_bid = sum(r for bs, px, r in own if self._is_pad_price(bs, px)
                          and bs == "bid")
        own_pad_ask = sum(r for bs, px, r in own if self._is_pad_price(bs, px)
                          and bs == "ask")
        yes_depth = sum(sz for _px, sz in yes_levels)
        no_depth = sum(sz for _px, sz in no_levels)
        # Distance gates (Jack 2026-08-03): a pad only rests when it sits
        # >= PAD_MIN_TICKS_BEHIND behind its side's EXTERNAL touch — a 1c pad
        # under a 1-2c best bid is the market itself, bought up easily.
        bid_pad_safe = (ext_bid is not None
                        and ext_bid - PAD_BID_CENTS >= PAD_MIN_TICKS_BEHIND)
        ask_pad_safe = (ext_ask is not None
                        and PAD_ASK_CENTS - ext_ask >= PAD_MIN_TICKS_BEHIND)
        if bid_pad_safe and (nt_bid > 0 or (pad_missing_side and nt_ask > 0)) \
                and not no_side_only(ticker):
            # live: book already holds our near-touch, subtract only our pad;
            # dry: sim orders aren't in the book, add this cycle's near-touch.
            basis = (yes_depth - own_pad_bid) if self.live else (yes_depth + nt_bid)
            n = self._pad_release_hold(ticker, "bid",
                                       sticky_pad_quantity(basis, target, own_pad_bid),
                                       own_pad_bid)
            if n > 0:
                pads.append(Quote(ticker, "bid", PAD_BID_CENTS, n, is_pad=True))
        if ask_pad_safe and (nt_ask > 0 or (pad_missing_side and nt_bid > 0)) \
                and not series_bid_only(series_of(ticker)):
            basis = (no_depth - own_pad_ask) if self.live else (no_depth + nt_ask)
            n = self._pad_release_hold(ticker, "ask",
                                       sticky_pad_quantity(basis, target, own_pad_ask),
                                       own_pad_ask)
            if n > 0:
                pads.append(Quote(ticker, "ask", PAD_ASK_CENTS, n, is_pad=True))
        return pads

    def _pad_release_hold(self, ticker: str, side: str, n: int,
                          resting_pad: float) -> int:
        """`n` (the sticky size), unless that would shrink or release a
        resting pad whose outside depth has sat at the release level for less
        than pad_release_hold_secs: then the resting pad stays (PADS HOLD,
        2026-10-25). The clock starts on the first cycle that would release it
        and clears on any cycle that would not."""
        hold = pad_release_hold_secs(series_of(ticker))
        key = (ticker, side)
        keep = min(int(round(resting_pad)), PAD_MAX_CONTRACTS)
        if hold <= 0 or not PAD_STICKY or keep < 1 or n >= keep:
            self._pad_release_since.pop(key, None)
            return n
        now = time.time()
        since = self._pad_release_since.setdefault(key, now)
        return keep if now - since < hold else n

    @staticmethod
    def _identical_quote(o: dict, q: Quote) -> bool:
        """Is resting order `o` already exactly quote `q` (a pure TTL
        renewal)? Same side, cent bucket, exact sub-penny price, size."""
        parsed = order_yes_book_cents(o)
        if parsed is None or parsed != (q.book_side, q.price_cents):
            return False
        if q.price_exact is not None:
            ox = order_yes_exact_cents(o)
            if ox is None or abs(ox - q.price_exact) >= 0.005:
                return False
        return abs(order_remaining(o) - q.count) < 0.5

    def place_with_caps(self, to_place: List[Quote], resting: List[dict],
                        cancelled_ids: Set[str], now_ts: float,
                        replaces: Optional[Dict[int, str]] = None,
                        failed_cancels: Optional[List[str]] = None) -> int:
        """Unconditional backstops: per-(market,side) resting cap, per-level
        cap, global resting-order cap, per-cycle placement cap. Side/level
        caps are per the quote's SERIES ladder (Love Island is bigger). Pad
        orders (1c/99c depth fillers) are exempt from the ladder caps.

        `replaces` (REQUOTE_INTERLEAVE, 2026-09-27): {index in to_place: id of
        the resting order that placement replaces}. Each such order is
        cancelled IMMEDIATELY before its replacement is placed (it is left out
        of the cap totals up front -- a one-for-one swap -- and added back if
        its cancel fails, in which case the replacement is not placed and the
        id goes to `failed_cancels`). Replacements the cycle caps defer: an
        order already identical to its replacement keeps resting until the
        next cycle; any other is cancelled now, as before."""
        replaces = replaces or {}
        pending = set(replaces.values())
        by_id = {o.get("order_id"): o for o in resting}
        side_totals: Dict[Tuple[str, str], float] = {}
        level_totals: Dict[Tuple[str, str, int], float] = {}
        total_resting = 0

        def _count(o: dict, sign: int) -> int:
            parsed = order_yes_book_cents(o)
            if parsed is None:
                return 0
            rem = order_remaining(o) * sign
            if not self._is_pad_price(parsed[0], parsed[1]):
                skey = (o.get("ticker", ""), parsed[0])
                side_totals[skey] = side_totals.get(skey, 0.0) + rem
                lkey = (o.get("ticker", ""), parsed[0], parsed[1])
                level_totals[lkey] = level_totals.get(lkey, 0.0) + rem
            return sign

        for o in resting:
            if o.get("order_id") in cancelled_ids or o.get("order_id") in pending:
                continue
            # pad orders don't count against the ladder caps (inside _count)
            total_resting += _count(o, 1)
        # Drop expired place-uncertainty cooldowns.
        for key, ts in list(self.state.place_uncertain.items()):
            if now_ts - ts > 2 * POLL_SECS:
                self.state.place_uncertain.pop(key, None)
        placed = 0
        deferred_from: Optional[int] = None
        # PACED (PLACE_RATE_PER_SEC): each write below waits for its slot; a
        # swap books two so its cancel + replacement stay back to back
        pacer = WritePacer(PLACE_RATE_PER_SEC if self.live else 0.0)
        for i, q in enumerate(to_place):
            self._ws_cycle_tick()          # the in-cycle stale check / breaker
            held_sweep = self.sweep_held(self._event_of(q.ticker), time.time())
            if held_sweep or self.group_held(q.ticker, q.book_side, time.time()):
                # the breaker (or the group breaker, 2026-10-17) tripped after
                # the cycle's diff: nothing new goes in before its hold ends,
                # but an order this placement would have replaced still
                # leaves the book
                old_h = replaces.get(i)
                if old_h is not None:
                    pacer.wait()
                    if self.cancel_order(old_h, reason="sweep_breaker" if held_sweep
                                         else "group_breaker"):
                        self.state.cancelled_today += 1
                        cancelled_ids.add(old_h)
                    elif old_h in by_id:
                        total_resting += _count(by_id[old_h], 1)   # it still rests
                (self._sweep if held_sweep else self._grp)["skipped_writes"] += 1
                continue
            if self._xp_waiting(q.ticker, time.time()):
                # EXCHANGE PAUSE (2026-10-22): Kalshi refuses writes on this
                # shard -- the placement and any swap it carries wait, and
                # the order it would replace keeps resting
                old_x = replaces.get(i)
                if old_x is not None and old_x in by_id:
                    total_resting += _count(by_id[old_x], 1)
                continue
            if self._cash_pause and self._cash_waiting(q, time.time()):
                # SHARD CASH PAUSE (2026-10-27): the shard just refused an order
                # this costly for cash -- the placement and any swap it carries
                # wait, and the order it would replace keeps resting
                old_c = replaces.get(i)
                if old_c is not None and old_c in by_id:
                    total_resting += _count(by_id[old_c], 1)
                continue
            if placed >= MAX_PLACEMENTS_PER_CYCLE:
                log(f"{self.tag} placement cap {MAX_PLACEMENTS_PER_CYCLE}/cycle reached; "
                    f"{len(to_place) - i} deferred to next cycle")
                deferred_from = i
                break
            if total_resting >= MAX_TOTAL_RESTING_ORDERS:
                self.alerter.alert("order_cap", f"global resting-order cap "
                                   f"{MAX_TOTAL_RESTING_ORDERS} reached", key="order_cap",
                                   urgent=False)
                deferred_from = i
                break
            old = replaces.get(i)
            if old is not None:
                # the swap: the order this placement replaces leaves the book
                # only now, one call before its successor lands
                pacer.wait(2)
                if self.cancel_order(old, reason="requote_diff"):
                    self.state.cancelled_today += 1
                    cancelled_ids.add(old)
                else:
                    if failed_cancels is not None:
                        failed_cancels.append(old)
                    if old in by_id:
                        total_resting += _count(by_id[old], 1)   # it still rests
                    continue
            if (q.ticker, q.book_side, q.price_cents) in self.state.place_uncertain:
                continue   # a lost-response order may already rest at this level
            if q.is_pad:
                # Depth filler: exempt from the ladder side/level caps (that's
                # its whole purpose), but still counts toward the global
                # resting-order and per-cycle placement caps above.
                if old is None:
                    pacer.wait()
                if self.place_order(q, now_ts):
                    total_resting += 1
                    placed += 1
                continue
            series = series_of(q.ticker)
            # Same hour-scaled shape as the quote loop that built q — an
            # unscaled cap here would block every boosted rung with
            # side_cap/level_cap alerts (the duplicated-threshold class).
            # In atref mode the construction layer may further scale a rung
            # by up to REF_DEPTH_MAX_MULT (deep-reference sizing, 2026-08-01
            # — this gate blocked every scaled rung for ~an hour, pads-only
            # books on fresh events); bracket by the max legitimate
            # multiplier — the precise per-book cap already ran in the
            # room/ladder layer, this is the runaway backstop.
            lv_now = scale_levels(
                hour_scaled_levels(series, datetime.fromtimestamp(now_ts, tz=timezone.utc)),
                self._market_size_mult(q.ticker))
            cap_mult = REF_DEPTH_MAX_MULT if LADDER_MODE == "atref" else 1.0
            # a series sized up on one side (SIDE_MULT_SERIES) brackets that
            # side's caps by the same factor
            _ssm = max(1.0, series_side_mults(series)[0 if q.book_side == "bid" else 1])
            cap_mult *= _ssm
            side_cap = sum(s for _t, s in lv_now) * cap_mult
            # atref collapses the side's WHOLE ladder to one price level by
            # design, so the per-level bracket is the side bracket — the
            # per-rung max only applies to offsets-shaped ladders. (2026-08-02:
            # temp's multi-rung 5/2/2 override default collapsed to a 14-18
            # lot single rung > max-level 10 and every temp strike was
            # level_cap-blocked overnight.)
            max_level_size = side_cap if LADDER_MODE == "atref" \
                else max(s for _t, s in lv_now) * _ssm
            # FULL UNWIND: the side that reduces the bot's own position may
            # rest the whole position (the quote loop sized it the same way)
            _ub, _ua = unwind_side_sizes(series, self.pnl.pos.get(q.ticker, 0.0),
                                         series_max_position(series))
            _u = _ub if q.book_side == "bid" else _ua
            side_cap = max(side_cap, _u)
            max_level_size = max(max_level_size, _u)
            # a complement lead rests target/5 at its lead price (the quote
            # loop sized it so: COMP_LEAD_MODE)
            _cl = self._comp_lead_px.get(q.ticker)
            if _cl is not None and _cl[0 if q.book_side == "bid" else 1] == q.price_cents:
                side_cap = max(side_cap, _cl[2])
                max_level_size = max(max_level_size, _cl[2])
            # FAIR CLOSE: the side that reduces a fair-lead market's position
            # may rest the whole of it (the quote loop sized it so), and with
            # a closing rung ahead of the book its own ladder beside it -- an
            # old rung the diff is resizing still counts at its old size here
            # (10/30 14:19:45Z: LEX's 16 ahead "blocked at 60/60")
            _fp = self.pnl.pos.get(q.ticker, 0.0)
            if (FAIR_CLOSE_MODE == "on" and series in FAIR_LEAD_SERIES
                    and abs(_fp) >= 1 and (_fp < 0) == (q.book_side == "bid")):
                _fc = min(abs(_fp), FAIR_LEAD_MAX_POSITION)
                if self._fair_close_px.get(q.ticker, ("",))[0] == q.book_side:
                    side_cap += _fc
                else:
                    side_cap = max(side_cap, _fc)
                max_level_size = max(max_level_size, _fc)
            skey = (q.ticker, q.book_side)
            lkey = (q.ticker, q.book_side, q.price_cents)
            have_side = side_totals.get(skey, 0.0)
            have_level = level_totals.get(lkey, 0.0)
            if have_side + q.count > side_cap + 0.01:
                self.alerter.alert("side_cap", f"{q.ticker} {q.book_side}: blocked at "
                                   f"{have_side:.0f}/{side_cap}",
                                   key=f"{q.ticker}-{q.book_side}", urgent=False)
                continue
            if have_level + q.count > max_level_size + 0.01:
                self.alerter.alert("level_cap", f"{q.ticker} {q.book_side}@{q.price_cents}c: "
                                   f"blocked at {have_level:.0f}/{max_level_size}",
                                   key=f"{q.ticker}-{q.price_cents}", urgent=False)
                continue
            if old is None:
                pacer.wait()
            if self.place_order(q, now_ts):
                side_totals[skey] = have_side + q.count
                level_totals[lkey] = have_level + q.count
                total_resting += 1
                placed += 1
        if pacer.slept >= 1.0:
            log(f"{self.tag} placement pacing: {placed} placed at <= "
                f"{PLACE_RATE_PER_SEC:g} writes/s ({pacer.slept:.0f}s paced)")
        if deferred_from is not None and replaces:
            # replacements the caps pushed to the next cycle: a pure renewal
            # keeps its (identical) order resting meanwhile; any other swap
            # loses the old order now, as before
            kept = 0
            for j in range(deferred_from, len(to_place)):
                old = replaces.get(j)
                if old is None:
                    continue
                o = by_id.get(old)
                if o is not None and self._identical_quote(o, to_place[j]):
                    kept += 1
                    continue
                if self.cancel_order(old, reason="requote_diff"):
                    self.state.cancelled_today += 1
                    cancelled_ids.add(old)
                elif failed_cancels is not None:
                    failed_cancels.append(old)
            if kept:
                log(f"{self.tag} placement cap: {kept} identical renewal(s) "
                    f"left resting until the next cycle")
        return placed

    # ---- status / summary ----------------------------------------------------

    def write_status(self, now_utc: datetime) -> None:
        s = self.state
        cats: Dict[str, int] = {}
        for cat, _msg in self.alerter.today:
            cats[cat] = cats.get(cat, 0) + 1
        status = {
            "bot": "incentive_mm",
            "mode": "LIVE" if self.live else "DRY",
            "updated_at": now_utc.strftime("%Y-%m-%dT%H:%M:%SZ"),
            "selected": len(s.selected),
            "managed_extra": len(s.managed_extra),
            "manual_standoff": sorted(s.manual_standoff),
            # open-scan tier (2026-09-05)
            "scan_members": sorted(s.scan_members),
            "scan_slots": f"{len(s.scan_members)}/{SCAN_TOP_N}",
            "scan_openings_used": (
                s.scan_admits_today
                if s.scan_admit_day == now_utc.astimezone(ET).date().isoformat()
                else 0),
            "scan_evicted_events": len(s.scan_evicted_events),
            "scan_hopeless_barred": len(s.scan_hopeless_barred),
            "scan_halted_today": s.scan_halt_day == _halt_day_key(now_utc),
            "scan_pnl_today": round(s.scan_pnl_today_last, 2),
            "programs_seen": s.programs_count,
            "markets_line": s.last_markets_line,
            "reward_est_today": round(s.reward_est_today, 2),
            "reward_est_lifetime": round(s.reward_est_lifetime, 2),
            # paid basis = the raw integral with the exchange's $1-per-market
            # program floor applied; this is what Kalshi actually credits
            "reward_paid_today": round(s.reward_paid_today, 2),
            "reward_paid_lifetime": round(s.reward_paid_lifetime, 2),
            "contract_minutes_today": round(s.contract_minutes_today),
            "cents_per_1k_contract_min": round(
                100000 * s.reward_est_today / s.contract_minutes_today, 2)
            if s.contract_minutes_today else 0,
            "realized_today": round(self.pnl.total_realized() - s.realized_baseline, 2),
            "realized_lifetime": round(self.pnl.total_realized(), 2),
            "unrealized_mtm": round(self.pnl.unrealized(s.last_mark), 2),
            "inventory_contracts": round(self.pnl.inventory_contracts(), 1),
            "pnl_today": round(self.pnl.total_realized()
                               + self.pnl.unrealized(s.last_mark)
                               - (s.day_baseline or 0.0), 2),
            "fills_today": s.fills_today,
            "cycles_today": s.cycles_today,
            "placed_today": s.placed_today,
            "cancelled_today": s.cancelled_today,
            "errors_today": s.errors_today,
            "alerts_today": cats,
            "halted_until": s.halted_until,
            # WebSocket books (2026-10-03): feed health, shadow compare and
            # the stale-quote counts
            "latency": self._latency_status(),
            "summary_date": str(self.alerter.last_summary_date or ""),
            "summary_body": self.alerter.last_summary_body or "",
        }
        try:
            os.makedirs(STATUS_DIR, exist_ok=True)
            path = os.path.join(STATUS_DIR, "status_incentive_mm.json")
            tmp = path + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(status, f)
            os.replace(tmp, path)
        except Exception as e:
            log(f"{self.tag} ! status write failed: {e}")
        # dry-run markets must not contaminate the live "ours" set; a cycle
        # that saved right after placing already wrote everything (run_cycle)
        if self.live and not self._cycle_saved:
            self._save_persist()

    def _latency_status(self) -> dict:
        """The status file's `latency` block (WebSocket books). Never raises."""
        try:
            win = list(self._ws_audit_win)
            out = {"ws": {"mode": WS_MODE, "fast": WS_FAST,
                          "books_used": self._ws_books_used,
                          "rest_fallback": self._ws_rest_fallback,
                          "shadow": dict(self._ws_shadow),
                          "fast_stats": dict(self._ws_fast),
                          # the REST audit and its trip window (2026-10-04)
                          "audit": dict(self._ws_audit, every=WS_AUDIT_EVERY,
                                        window=len(win),
                                        window_bad_top=sum(1 for _e, tp in win
                                                           if not tp),
                                        window_bad_book=sum(1 for e, _tp in win
                                                            if not e)),
                          "stale_open": len(self._ws_flagged),
                          "check_in_cycle": WS_CHECK_IN_CYCLE,
                          # the narrow fast-cancel gate (2026-10-08)
                          "fast_min_gap_c": WS_FAST_MIN_GAP_C,
                          # the quote loop's book-read REST budget (2026-10-11)
                          "book_rest": dict(self._book_rest_stats,
                                            budget_s=BOOK_REST_BUDGET_SECS,
                                            max_fails=BOOK_REST_MAX_FAILS),
                          # candidate books on the feed (2026-10-08)
                          "cand": dict(self._ws_cand, mode=WS_CANDIDATES,
                                       want=len(self._ws_cand_want),
                                       shadow=dict(self._ws_cand_shadow))}}
            if self._ws is not None:
                out["ws"]["feed"] = self._ws.status()
            # the event sweep breaker (2026-10-04, SWEEP_BREAKER)
            now = time.time()
            # the bait-fingerprint stop (2026-10-22, BAIT_STOP_MODE)
            out["bait_stop"] = dict(
                self._bait, mode=BAIT_STOP_MODE, pending=len(self._bait_pending),
                sides_stopped=sum(1 for u in self.state.bait_side_until.values()
                                  if u > now),
                events_guarded=sum(1 for u in self.state.bait_event_until.values()
                                   if u > now))
            out["sweep"] = dict(self._sweep, mode=SWEEP_BREAKER,
                                hold_s=SWEEP_HOLD_SECS, holdout=SWEEP_HOLDOUT,
                                hold_by_series=dict(SWEEP_HOLD_BY_SERIES),
                                linked=[list(g) for g in SWEEP_LINKED_GROUPS],
                                held_now=sum(1 for u in self._sweep_hold.values()
                                             if u > now),
                                # escalating holds (2026-10-17)
                                escalate={"mode": SWEEP_ESCALATE,
                                          "window_min": SWEEP_ESCALATE_WINDOW_SECS / 60,
                                          "holds_min": [h / 60 for h in SWEEP_ESCALATE_HOLDS],
                                          "exclude": list(SWEEP_ESCALATE_EXCLUDE),
                                          "chains_now": sum(
                                              1 for s in self._sweep_esc.values()
                                              if s["reset_at"] > now and s["n"] >= 2)})
            # the cross-event breaker and the dollar limits (2026-10-17)
            out["group_breaker"] = dict(
                self._grp, mode=SWEEP_GROUP,
                window_min=SWEEP_GROUP_WINDOW_SECS / 60,
                hold_min=SWEEP_GROUP_HOLD_SECS / 60, min_ct=SWEEP_GROUP_MIN_CT,
                held_now=sum(1 for u in self._grp_hold.values() if u > now),
                windows_now=sum(1 for w in self._grp_win.values()
                                if w["until"] > now))
            out["risk_limits"] = dict(
                self._risk, mode=RISK_LIMITS, primed=self._risk_primed,
                event_limit=[RISK_EVENT_FLOOR, RISK_EVENT_DAYS],
                group_limit=[RISK_GROUP_FLOOR, RISK_GROUP_DAYS],
                skew_from=RISK_SKEW_FROM, exempt=list(RISK_EXEMPT),
                pass_open=self._risk_pass is not None)
            # back of the line (2026-10-17, BACK_OF_LINE)
            plan = self._bol_plan
            out["back_of_line"] = dict(self._bol, mode=BACK_OF_LINE,
                                       bumped_orders=len(self._bol_bumps),
                                       plan_open=bool(plan and not plan["done"]))
            # rate-limit alert (2026-10-17, RATE_LIMIT_ALERT)
            out["rate_limit"] = dict(self._rl, on=RATE_LIMIT_ALERT,
                                     pace_per_s=PLACE_RATE_PER_SEC,
                                     logs_watched=len(self._rl_offsets))
            # exchange pause (2026-10-22, EXCH_PAUSE_MODE)
            out["exchange_pause"] = dict(
                self._xp_stats, mode=EXCH_PAUSE_MODE,
                paused={str(s): {k: p[k] for k in (
                    "since", "last_refusal", "code", "by_status", "held",
                    "refused", "probes", "alerted", "closure")}
                    for s, p in self._xp.items()},
                status=(sorted(self._xp_status) if self._xp_status is not None
                        else None),
                schedule_read=self._xp_sched is not None,
                schedule_err=self._xp_sched_err)
            # cycle timing (2026-10-04): the REST book reads IMM_WS=on would
            # serve from the feed, inside each full cycle
            ct = list(self._cycle_times)
            if ct:
                reads = [r - s0 for s0, r, _e in ct if r > s0]
                runs = [e - s0 for s0, _r, e in ct]
                periods = [b[0] - a[0] for a, b in zip(ct, ct[1:])]

                def med(v: List[float]) -> Optional[float]:
                    return round(statistics.median(v), 1) if v else None
                out["cycle"] = {"n": len(ct), "reads_s": med(reads),
                                "run_s": med(runs), "period_s": med(periods),
                                "last_reads_s": round(ct[-1][1] - ct[-1][0], 1)
                                if ct[-1][1] > ct[-1][0] else None,
                                "last_run_s": round(ct[-1][2] - ct[-1][0], 1)}
            # universe refreshes (2026-10-08): how long each took and where
            # its candidate books came from (WS_CANDIDATES)
            ut = list(self._universe_times)
            if ut:
                durs = [t1 - t0 for t0, t1, _n, _w in ut]
                out["universe"] = {
                    "n": len(ut), "median_s": round(statistics.median(durs), 1),
                    "last_s": round(durs[-1], 1), "last_reads": ut[-1][2],
                    "last_ws": ut[-1][3],
                    "last_at": datetime.fromtimestamp(
                        ut[-1][1], timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")}
            # the power source (2026-10-11, POWER)
            if _power_state:
                out["power"] = {k: v for k, v in _power_state.items() if k != "key"}
            # ...and the network guard's deferred / aborted refreshes
            # (2026-10-11, UNIVERSE_NET_GUARD)
            g = self._universe_guard
            if g["deferred"] or g["aborted"] or self._universe_deferred_since:
                out.setdefault("universe", {}).update(
                    deferred=g["deferred"], aborted=g["aborted"], last_skip=g["last"],
                    deferring_s=(round(time.time() - self._universe_deferred_since)
                                 if self._universe_deferred_since else 0))
            return out
        except Exception as e:
            return {"error": str(e)[:200]}

    def build_daily_summary(self) -> str:
        s = self.state
        alerts = self.alerter.today
        if alerts:
            cats: Dict[str, int] = {}
            for cat, _msg in alerts:
                cats[cat] = cats.get(cat, 0) + 1
            alert_str = " ".join(f"{c}x{n}" for c, n in sorted(cats.items()))
        else:
            alert_str = "none"
        top_pos = sorted(((t, p) for t, p in self.pnl.pos.items() if abs(p) > 0.5),
                         key=lambda kv: -abs(kv[1]))[:5]
        pos_str = ", ".join(f"{t} {p:+.0f}" for t, p in top_pos) or "flat"
        realized_today = self.pnl.total_realized() - s.realized_baseline
        unrealized = self.pnl.unrealized(s.last_mark)
        inv = self.pnl.inventory_contracts()
        cm = s.contract_minutes_today
        eff = f", {100000 * s.reward_est_today / cm:.1f}c/1k-contract-min" if cm else ""
        body = (f"incentive_mm daily ({'LIVE' if self.live else 'DRY'}): "
                f"{s.last_markets_line} | est reward today ${s.reward_est_today:.2f} "
                f"(${s.reward_paid_today:.2f} paid basis) "
                f"({cm:,.0f} contract-min{eff}) | "
                f"realized today ${realized_today:+.2f} (lifetime "
                f"${self.pnl.total_realized():+.2f}), unrealized ${unrealized:+.2f} "
                f"on {inv:.0f} carried, fills {s.fills_today:.0f} | "
                f"inventory: {pos_str} | cycles {s.cycles_today}, placed {s.placed_today}, "
                f"cxl {s.cancelled_today}, errs {s.errors_today} | alerts: {alert_str}")
        s.cycles_today = s.placed_today = s.cancelled_today = s.errors_today = 0
        s.fills_today = 0.0
        # Record the COMPLETED day before zeroing — this is what the digest
        # reports as "last full day" (restart-proof, unlike the live counter).
        # The roll fires ~5am CT on day D covering ~5am D-1 -> 5am D, so the
        # period is labelled D-1.
        completed = (datetime.now(timezone.utc).astimezone(CT).date()
                     - timedelta(days=1)).isoformat()
        s.reward_history[completed] = round(s.reward_est_today, 2)
        s.reward_history = dict(sorted(s.reward_history.items())[-60:])
        s.reward_paid_history[completed] = round(s.reward_paid_today, 2)
        s.reward_paid_history = dict(sorted(s.reward_paid_history.items())[-60:])
        s.reward_est_today = 0.0
        s.reward_paid_today = 0.0
        s.contract_minutes_today = 0.0
        # roll both loss-halt windows + the restart-carry and balance anchor
        s.realized_baseline = self.pnl.total_realized()
        s.day_baseline = self.pnl.total_realized() + unrealized
        s.pnl_carry = 0.0
        s.pnl_today_last = 0.0
        s.account_value_day_start = 0.0    # re-anchors on the next cycle
        # open-scan tier loss budget: same roll (baseline re-anchors on the
        # next cycle's measurement, carry cleared), and the loss-budget book
        # sheds markets that are flat AND no longer members — only here, so
        # a settlement booked mid-day stays in that day's tier P&L
        s.scan_pnl_baseline = None
        s.scan_pnl_carry = 0.0
        s.scan_pnl_today_last = 0.0
        # YouTube #2 pilot loss halt: the same roll (yt2_halt_day is keyed by
        # the roll day, so a tripped halt simply stops matching)
        s.yt2_pnl_baseline = None
        s.yt2_pnl_carry = 0.0
        s.yt2_pnl_today_last = 0.0
        s.ytw_pnl_baseline = None
        s.ytw_pnl_carry = 0.0
        s.ytw_pnl_today_last = 0.0
        s.twk_pnl_baseline = {}
        s.twk_pnl_carry = {}
        s.twk_pnl_today_last = {}
        s.scan_book = {t for t in s.scan_book
                       if t in s.scan_members
                       or abs(self.pnl.pos.get(t, 0.0)) > 1e-9}
        return body

    # ---- main loop -----------------------------------------------------------

    # ---- planned-restart order handoff (RESTART_KEEP_ORDERS, 2026-09-27) ----

    @staticmethod
    def _restart_preflight() -> Tuple[bool, str]:
        """Import the ON-DISK source in a child python (same interpreter, same
        environment, the source's own directory). (True, "ok") when it
        imports; else (False, why). The handoff never proceeds without it."""
        import subprocess
        mod = os.path.splitext(os.path.basename(_SOURCE_PATH))[0]
        try:
            # UTF-8 both ways: a cp1252 console pipe must not turn one exotic
            # glyph in an import-time log line into a failed preflight
            out = subprocess.run(
                [sys.executable, "-c", f"import {mod}"],
                cwd=os.path.dirname(_SOURCE_PATH) or ".",
                env=dict(os.environ, PYTHONIOENCODING="utf-8"),
                capture_output=True, text=True, encoding="utf-8",
                errors="replace", timeout=RESTART_PREFLIGHT_TIMEOUT_SECS)
        except Exception as e:
            return False, f"{type(e).__name__}: {str(e)[:160]}"
        if out.returncode != 0:
            tail = (out.stderr or out.stdout or "").strip().splitlines()
            return False, (f"exit {out.returncode}: "
                           f"{tail[-1][:160] if tail else 'no output'}")
        return True, "ok"

    def _restart_keep_ok(self, ticker: str, now_ts: float) -> bool:
        """May this market's resting orders ride through a planned restart?
        Only a SELECTED market off every live-event / fast / near-cutoff
        list (see RESTART_KEEP_ORDERS)."""
        meta = self.state.selected.get(ticker)
        if meta is None:
            return False
        if series_fast_lane(meta.series) or quake_gated(meta.series):
            return False
        # A gated (live-event) series rides through only while its event's
        # live gate is NOT armed (2026-10-05, KXTRUMPMENTION-26OCT05: six
        # deploy restarts in three hours each cancelled the whole event at
        # handoff and left it dark ~2-3 min until the relaunch re-quoted --
        # for a 7pm ET speech whose noisy triggers arm at 6:30pm). The
        # refusal is for a restart MID-SPEECH;
        # before the arm time (point 7: start - 30 min with a known start;
        # the ticker day without one, as before) there is no speech to be in.
        if series_event_depth_gated(meta.series)                 and event_live_gate_armed(meta.event_ticker, now_ts):
            return False
        if meta.event_ticker in self.state.event_depth_halt \
                or meta.event_ticker in self.state.event_live_halt:
            return False
        cut = self.state.cutoff_ts.get(ticker)
        if cut is None and meta.cutoff is not None:
            cut = meta.cutoff.timestamp()
        if cut is not None and cut - now_ts < RESTART_KEEP_MIN_CUTOFF_SECS:
            return False
        return True

    def _prepare_restart_handoff(self) -> bool:
        """Planned code-change exit: leave the book resting for the relaunch
        instead of cancelling it. Cancels the orders _restart_keep_ok refuses,
        writes the handoff file and arms _handoff_keep (read by
        shutdown_cancel). Returns True when armed; any failure returns False
        and the exit cancels everything as before."""
        if not (RESTART_KEEP_ORDERS and self.live):
            return False
        if os.path.exists(HALT_FILE) or self.state.halted_until > time.time():
            return False                    # a halted bot hands over nothing
        ok, why = self._restart_preflight()
        if not ok:
            log(f"{self.tag} restart handoff SKIPPED: the new source failed "
                f"its import preflight ({why}); cancelling the book as before")
            return False
        now_ts = time.time()
        try:
            orders = self._merge_ledger(self._get_resting_orders_global(), now_ts)
        except Exception as e:
            log(f"{self.tag} restart handoff SKIPPED: resting read failed "
                f"({e}); cancelling the book as before")
            return False
        keep = [o for o in orders if self._restart_keep_ok(o.get("ticker", ""), now_ts)]
        keep_ids = {o.get("order_id") for o in keep}
        n_cx = 0
        for o in orders:
            if o.get("order_id") in keep_ids:
                continue
            if self.cancel_order(o.get("order_id", ""), reason="restart_handoff"):
                n_cx += 1
        payload = {"ts": round(now_ts, 3), "run_id": RUN_ID,
                   "source_mtime": _SOURCE_MTIME, "kept": len(keep),
                   "cancelled": n_cx,
                   "order_ids": sorted(str(i) for i in keep_ids if i),
                   # the fills sink's join (FILL_JOIN_*): the relaunch books
                   # every fill that lands after this run's last poll
                   "fill_join": self._join_export()}
        try:
            os.makedirs(STATUS_DIR, exist_ok=True)
            tmp = restart_handoff_path() + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(payload, f)
            os.replace(tmp, restart_handoff_path())
        except OSError as e:
            log(f"{self.tag} restart handoff SKIPPED: could not write "
                f"{RESTART_HANDOFF_FILE} ({e}); cancelling the book as before")
            return False
        self._handoff_keep = True
        self._handoff_kept = len(keep)
        log(f"{self.tag} restart handoff: {len(keep)} order(s) left resting for "
            f"the relaunch; cancelled {n_cx} on gated / fast-lane / "
            f"near-cutoff / unselected markets")
        return True

    def _watchdog_handoff(self, wedge: float,
                          stacks: str = "") -> Tuple[Optional[int], str]:
        """The hang watchdog's exit hands the book to the relaunch
        (WATCHDOG_HANDOFF) instead of leaving it to the startup cancel. Runs
        on the watchdog's I/O helper while the main thread is wedged: memory
        and one local file only. No network, no _save_persist (the main thread
        saved after its last placements, and the journal holds any since).
        Lists the ledger's orders that _restart_keep_ok passes; the relaunch
        cancels every other resting imm- order first (_adopt_restart_handoff,
        kind "watchdog"). Returns (orders listed, "ok"), or (None, why) when
        refused -- then no file is written and the relaunch cancels as
        before."""
        if not (WATCHDOG_HANDOFF and RESTART_KEEP_ORDERS and self.live):
            return None, "off"
        now_ts = time.time()
        if os.path.exists(HALT_FILE) or self.state.halted_until > now_ts:
            return None, "the bot is halted"
        if self._full_cycles < 1:
            return None, "no full cycle completed in this process"
        if wedge > CYCLE_HANG_EXIT_SECS + WATCHDOG_HANDOFF_SLACK_SECS:
            return None, f"the book went {wedge:.0f}s unmanaged"
        try:
            keep = sorted(str(oid) for oid, led in list(self.state.ledger.items())
                          if oid and self._restart_keep_ok(
                              str(led.get("ticker") or ""), now_ts))
            payload = {"ts": round(now_ts, 3), "run_id": RUN_ID,
                       "source_mtime": _SOURCE_MTIME, "kind": "watchdog",
                       "kept": len(keep), "cancelled": 0, "order_ids": keep,
                       "wedge_s": round(wedge), "stacks": stacks,
                       "fill_join": self._join_export()}
            os.makedirs(STATUS_DIR, exist_ok=True)
            tmp = restart_handoff_path() + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(payload, f)
            os.replace(tmp, restart_handoff_path())
        except Exception as e:
            return None, f"{type(e).__name__}: {str(e)[:120]}"
        return len(keep), "ok"

    def _restart_requested(self) -> bool:
        """Between cycles: act on an operator handoff request (see
        RESTART_REQUEST_FILE). Hands the book over exactly as the code-change
        exit does and returns True for run() to leave. A handoff that cannot
        arm still exits -- cancelling as before -- because the operator is
        restarting the task either way. A dry-run process never acts on it."""
        if not self.live:
            return False
        req = restart_request_pending(_PROCESS_START_TS)
        if req is None:
            return False
        try:
            os.remove(restart_request_path())
        except OSError:
            pass
        log(f"{self.tag} restart requested by {req.get('by') or 'an operator'}: "
            f"handing the book over and exiting for the relaunch")
        if self._prepare_restart_handoff():
            self._save_persist()
        return True

    def _adopt_restart_handoff(self) -> Optional[int]:
        """Startup: adopt the book a planned restart handed over, or the hang
        watchdog's exit (kind "watchdog": the orders it did not list are
        cancelled first). Returns the number of resting orders adopted, or
        None when the caller must cancel everything as before (no/unreadable/
        stale handoff file, knob off, or the resting read failed). The file
        is consumed either way, so a handoff can never be adopted twice."""
        path = restart_handoff_path()
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        except FileNotFoundError:
            return None
        except (OSError, ValueError) as e:
            log(f"{self.tag} ! {RESTART_HANDOFF_FILE} unreadable ({e})")
            data = None
        try:
            os.remove(path)
        except OSError:
            pass
        if isinstance(data, dict):
            # the last run's fills-sink join, whatever becomes of its book:
            # this run's first poll books the fills of the restart gap
            n_join = self._join_import(data.get("fill_join"))
            if n_join:
                log(f"{self.tag} startup: fill join for {n_join} order(s) "
                    f"handed over by run {data.get('run_id')}")
        if not RESTART_KEEP_ORDERS or not isinstance(data, dict):
            return None
        try:
            age = time.time() - float(data.get("ts") or 0.0)
        except (TypeError, ValueError):
            return None
        if not (0.0 <= age <= RESTART_HANDOFF_MAX_AGE_SECS):
            log(f"{self.tag} restart handoff from run {data.get('run_id')} is "
                f"{age:.0f}s old (limit {RESTART_HANDOFF_MAX_AGE_SECS}s); "
                f"cancelling the book as before")
            return None
        try:
            orders = self._get_resting_orders_global()
        except Exception as e:
            log(f"{self.tag} restart handoff: resting read failed ({e}); "
                f"cancelling the book as before")
            return None
        # a WATCHDOG handoff (_watchdog_handoff) lists only the orders its
        # hung run passed with _restart_keep_ok; every other resting imm-
        # order is cancelled here before the rest is adopted
        listed: Optional[Set[str]] = None
        if data.get("kind") == "watchdog":
            listed = {str(i) for i in (data.get("order_ids") or [])}
        now_ts = time.time()
        n = n_cx = 0
        for o in orders:
            oid = o.get("order_id")
            parsed = order_yes_book_cents(o)
            if not oid or parsed is None:
                continue
            created = parse_iso_utc(o.get("created_time") or "")
            placed = min(created.timestamp(), now_ts) if created else now_ts
            # the TTL refresh clock runs from the order's real birth, and the
            # ledger carries it like one of our own placements
            self.state.order_ages[oid] = placed
            self.state.our_order_ids.setdefault(oid, placed)
            self.state.ledger[oid] = {
                "order_id": oid, "ticker": o.get("ticker", ""),
                "book_side": parsed[0], "yes_price": parsed[1],
                "remaining_count": order_remaining(o),
                "yes_price_exact": order_yes_exact_cents(o),
                "status": "resting",
                "client_order_id": o.get("client_order_id"),
                "_placed_at": placed, "_confirmed": True,
            }
            self._join_set(oid, o.get("ticker", ""), parsed[0], parsed[1],
                           order_yes_exact_cents(o), order_remaining(o),
                           o.get("client_order_id"), placed)
            # (booked first, so the cancel's row names the market and fills
            # before it are still ours; a failed cancel leaves it adopted)
            if listed is not None and str(oid) not in listed \
                    and self.cancel_order(oid, reason="watchdog_handoff"):
                n_cx += 1
                continue
            n += 1
        log(f"{self.tag} startup: adopted {n} resting imm- order(s) handed over "
            f"by run {data.get('run_id')} {age:.0f}s ago "
            + (f"(WATCHDOG handoff after a {data.get('wedge_s')}s hang, stacks "
               f"{data.get('stacks') or 'not written'}; cancelled {n_cx} it did "
               f"not list: gated / fast-lane / near-cutoff / unselected "
               f"markets, or placed during the hang)" if listed is not None
               else "(restart handoff)")
            + "; the first cycle re-prices, keeps or strays them")
        return n

    def _write_wedge_snapshot(self, path: str, label: str, wedge: float,
                              hb: float) -> str:
        """Append one snapshot of every thread's stack (WEDGE STACKS) to
        `path`; returns the main thread's one-line summary. Raises on a
        failed write. Called on the watchdog's I/O helper thread, which it
        leaves out of the snapshot."""
        text, summary = format_thread_stacks(skip_ident=threading.get_ident())

        def iso(ts: float) -> str:
            return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(ts))
        with open(path, "a", encoding="utf-8") as f:
            f.write(f"=== IMM hang watchdog: no cycle heartbeat for {wedge:.0f}s "
                    f"({label}) ===\n"
                    f"utc {iso(time.time())} | last heartbeat {iso(hb)} | run "
                    f"{RUN_ID} | pid {os.getpid()} | config {CONFIG_HASH} | "
                    f"source mtime {_SOURCE_MTIME}\n"
                    f"main thread: {summary}\n\n{text}\n")
        return summary

    def _hang_watchdog_tick(self, wd: dict, now: float,
                            late: float = 0.0) -> bool:
        """One tick of the hang watchdog (run()'s daemon thread, every
        HANG_WATCHDOG_TICK_SECS; `late` = how far past that the tick woke).
        True = hard-exit now. `wd` carries one stall's snapshot file across
        ticks. What a tick does, in order:
          - a tick that woke a whole tick late: the PROCESS stalled, not
            just the cycle (a thread holding the GIL, or the machine slept);
          - a heartbeat that came back after a snapshot: a slow phase, logged;
          - CYCLE_HANG_DUMP_SECS without one: every thread's stack to
            wedge_<utc>.txt (WEDGE STACKS), once per stall;
          - past CYCLE_HANG_EXIT_SECS: the book handed over when that is
            safe (_watchdog_handoff), a snapshot appended to the same file,
            the exit.
        The decision is made here; the file writes and log lines run on one
        helper thread this tick waits on for at most WEDGE_IO_TIMEOUT_SECS."""
        hb = self._heartbeat
        wedge = now - hb
        notes: List[str] = []
        if late >= HANG_WATCHDOG_TICK_SECS:
            mem = _memory_note()    # paged out for want of RAM? (2026-10-11)
            notes.append(f"{self.tag} ! hang watchdog: a {HANG_WATCHDOG_TICK_SECS}s "
                         f"tick took {HANG_WATCHDOG_TICK_SECS + late:.0f}s -- the "
                         f"whole process stalled (a thread holding the GIL, the "
                         f"machine asleep, or the bot paged out for want of RAM)"
                         + (f"; {mem}" if mem else ""))
        if wd.get("path") and hb != wd.get("hb"):
            notes.append(f"{self.tag} cycle heartbeat back after "
                         f"{hb - wd['hb']:.0f}s (stacks in {wd['path']}): a slow "
                         f"phase, not a wedge")
            wd.clear()
        exiting = wedge > CYCLE_HANG_EXIT_SECS
        label = None
        if exiting:
            label = "snapshot 2, at the exit" if wd.get("path") else "at the exit"
        elif (CYCLE_HANG_DUMP_SECS > 0 and wedge > CYCLE_HANG_DUMP_SECS
              and not wd.get("path")):
            label = f"snapshot 1; the exit follows at {CYCLE_HANG_EXIT_SECS}s"
        if label is not None and not wd.get("path"):
            wd["path"], wd["hb"] = wedge_dump_path(now), hb
        if not notes and label is None:
            return False
        path = wd.get("path", "")

        def io() -> None:
            for line in notes:
                log(line)
            if label is None:
                return
            # the handoff first: it is what keeps the book up
            kept, why = (self._watchdog_handoff(wedge, path) if exiting
                         else (None, ""))
            try:
                summary = self._write_wedge_snapshot(path, label, wedge, hb)
                where = f"stacks -> {path} (main: {summary})"
            except Exception as e:
                where = f"stack dump FAILED ({type(e).__name__}: {str(e)[:120]})"
            if not exiting:
                log(f"{self.tag} ! no cycle heartbeat for {wedge:.0f}s -- {where}; "
                    f"hard exit at {CYCLE_HANG_EXIT_SECS}s")
                return
            log(f"{self.tag} !! no cycle heartbeat for {wedge:.0f}s — wedged "
                f"syscall? hard-exiting for launcher relaunch (state is "
                f"journaled); {where}; "
                + (f"book handed to the relaunch ({kept} order(s) listed; it "
                   f"cancels the rest)" if kept is not None
                   else f"no handoff ({why}): the relaunch cancels the book"))
        run_bounded(io, WEDGE_IO_TIMEOUT_SECS, "hang-watchdog-io")
        return exiting

    def shutdown_cancel(self) -> None:
        if self._shutdown_done or not self.live:
            return
        self._shutdown_done = True
        if self._handoff_keep:
            log(f"{self.tag} shutdown: left {self._handoff_kept} resting bot "
                f"order(s) for the relaunch (restart handoff)")
            return
        try:
            n = self.cancel_all_bot_orders()
            log(f"{self.tag} shutdown: cancelled {n} resting bot orders")
        except Exception as e:
            log(f"{self.tag} ! shutdown cancel failed: {e} "
                f"(orders TTL-expire within {ORDER_TTL_SECS}s)")

    def run(self, once: bool = False) -> None:
        mode = "LIVE" if self.live else "DRY RUN (no orders placed; --live to trade)"
        # Configuration identity, before anything else is logged: every
        # analytics row this run emits carries CONFIG_HASH, and this file is
        # what turns that hash back into the settings it stands for.
        global CONFIG, CONFIG_HASH
        try:
            CONFIG, CONFIG_HASH = _build_config()
            self._sink("config_history", {
                "ts": datetime.now(timezone.utc).isoformat(),
                "model_version": MODEL_VERSION,
                "git_sha": _git_sha(),
                "mode": mode,
                "source_mtime": _SOURCE_MTIME,
                "config": CONFIG,
            })
        except Exception as e:      # config identity must never block startup
            log(f"! config snapshot failed ({e}); analytics rows will carry "
                f"config_hash={CONFIG_HASH}")
        log(f"=== {MODEL_VERSION} run={RUN_ID} mode={mode} "
            f"config={CONFIG_HASH} ===")
        if not once:
            def _hang_watchdog():
                wd: dict = {}
                while True:
                    t0 = time.monotonic()
                    time.sleep(HANG_WATCHDOG_TICK_SECS)
                    late = time.monotonic() - t0 - HANG_WATCHDOG_TICK_SECS
                    try:
                        exit_now = self._hang_watchdog_tick(wd, time.time(), late)
                    except Exception:
                        # a bug in the snapshot / handoff never costs the exit
                        exit_now = time.time() - self._heartbeat > CYCLE_HANG_EXIT_SECS
                    if exit_now:
                        os._exit(86)
            threading.Thread(target=_hang_watchdog, daemon=True,
                             name="hang-watchdog").start()
        if RAIN_FAIR_ENABLE and not once:
            # Fair-value refresher: fetch NWS forecasts OFF the trading thread
            # (a wedged 20s HTTP call must never stall a cycle / trip the hang
            # watchdog) and talk to the quote loop only through the JSON file,
            # like every other external writer. Import failure just means rain
            # quotes anchor to the book, as before this feature.
            def _rain_fair_refresh():
                try:
                    import rain_fair
                except Exception as e:
                    log(f"{self.tag} ! rain-fair refresher disabled: {e}")
                    return
                # the writer also reads Kalshi's open KXRAIN cities and
                # models any new one from its rules (2026-10-09); a city it
                # can't resolve lands in the file's "unmapped" list, which
                # the family watch alerts on
                kalshi_get = fair_reader()
                while True:
                    try:
                        ok, fail = rain_fair.write_fair_file(
                            RAIN_FAIR_FILE, get_json=kalshi_get)
                        with open(RAIN_FAIR_FILE, encoding="utf-8") as fh:
                            _rf = json.load(fh) or {}
                        _auto = sorted((_rf.get("auto_stations") or {}))
                        _um = sorted((_rf.get("unmapped") or {}))
                        log(f"{self.tag} rain-fair refresh: {ok} stations ok"
                            + (f", {fail} FAILED" if fail else "")
                            + (f"; auto-modeled {','.join(_auto)}" if _auto else "")
                            + (f"; ! UNMAPPED {','.join(_um)}" if _um else ""))
                    except Exception as e:
                        log(f"{self.tag} ! rain-fair refresh failed: {e}")
                    time.sleep(max(300, RAIN_FAIR_REFRESH_MIN * 60))
            threading.Thread(target=_rain_fair_refresh, daemon=True,
                             name="rain-fair").start()
        if LOWT_ENABLE and not once:
            # Low-temperature fair refresher (2026-10-23): the rain
            # refresher's contract -- forecasts fetched off the trading
            # thread, handed to the quote loop only through LOWT_FAIR_FILE.
            # An import failure leaves no fair, and the gate fails closed.
            def _lowt_fair_refresh():
                try:
                    import lowt_fair
                except Exception as e:
                    log(f"{self.tag} ! lowt-fair refresher disabled: {e}")
                    return
                kalshi_get = fair_reader()
                while True:
                    try:
                        ok, skipped, failed = lowt_fair.write_fair_file(
                            LOWT_FAIR_FILE, get_json=kalshi_get)
                        log(f"{self.tag} lowt-fair refresh: {ok} events priced, "
                            f"{skipped} stood aside by the shape filters"
                            + (f", {failed} stations FAILED" if failed else ""))
                    except Exception as e:
                        log(f"{self.tag} ! lowt-fair refresh failed: {e}")
                    time.sleep(max(300, LOWT_FAIR_REFRESH_SECS))
            threading.Thread(target=_lowt_fair_refresh, daemon=True,
                             name="lowt-fair").start()
        if HIGHT_ENABLE and not once:
            # High-temperature fair refresher (2026-10-23): the low one's
            # contract on hight_fair.py
            def _hight_fair_refresh():
                try:
                    import hight_fair
                except Exception as e:
                    log(f"{self.tag} ! hight-fair refresher disabled: {e}")
                    return
                kalshi_get = fair_reader()
                while True:
                    try:
                        ok, skipped, failed = hight_fair.write_fair_file(
                            HIGHT_FAIR_FILE, get_json=kalshi_get)
                        log(f"{self.tag} hight-fair refresh: {ok} events priced, "
                            f"{skipped} stood aside by the shape filter"
                            + (f", {failed} stations FAILED" if failed else ""))
                    except Exception as e:
                        log(f"{self.tag} ! hight-fair refresh failed: {e}")
                    time.sleep(max(300, HIGHT_FAIR_REFRESH_SECS))
            threading.Thread(target=_hight_fair_refresh, daemon=True,
                             name="hight-fair").start()
        if CA_FAIR_ENABLE and not once:
            # Carbon Arc fair refresher (2026-09-26): the rain refresher's
            # contract -- every network call off the trading thread, the
            # quote loop reads only CA_FAIR_FILE. With no feed configured
            # (a Carbon Arc API token or a feed URL, in ~/.carbonarc_feed.json
            # or IMM_CA_FEED_TOKEN / IMM_CA_FEED_URL -- never in the public
            # repo) nothing is written and the gate stays open; the settings
            # are re-read every 10 minutes, so adding the token needs no
            # restart. Logs only when the outcome changes.
            def _ca_fair_refresh():
                try:
                    import carbon_arc_fair
                except Exception as e:
                    log(f"{self.tag} ! ca-fair refresher disabled: {e}")
                    return
                kalshi_get = fair_reader()
                last = None
                while True:
                    delay = max(30, CA_FAIR_REFRESH_SECS)
                    try:
                        if not carbon_arc_fair.feed_configured():
                            if last != "off":
                                log(f"{self.tag} ca-fair: no feed configured "
                                    f"-- gate open (plain quoting)")
                            last, delay = "off", 600
                        else:
                            ok, miss = carbon_arc_fair.write_fair_file(
                                CA_FAIR_FILE, get_json=kalshi_get)
                            if last != (ok, miss):
                                log(f"{self.tag} ca-fair refresh: {ok} series "
                                    f"with a read"
                                    + (f", {miss} mapped without one"
                                       if miss else ""))
                            last = (ok, miss)
                    except Exception as e:
                        if last != "err":
                            log(f"{self.tag} ! ca-fair refresh failed: {e}")
                        last = "err"
                    time.sleep(delay)
            threading.Thread(target=_ca_fair_refresh, daemon=True,
                             name="ca-fair").start()
        if OR_FAIR_ENABLE and not once:
            # OpenRouter token-usage refresher (2026-09-27): the Carbon Arc
            # refresher's contract. Polls every OR_FAIR_REFRESH_SECS, and
            # every OR_FAIR_FAST_SECS for OR_FAIR_FAST_WINDOW_MIN after
            # 00:00Z, when OpenRouter publishes the day just ended. No key
            # (~/.openrouter_key.json or IMM_OR_API_KEY) = nothing written,
            # so the token series stay stood aside (the gate fails closed).
            def _or_fair_refresh():
                try:
                    import openrouter_fair
                except Exception as e:
                    log(f"{self.tag} ! or-fair refresher disabled: {e}")
                    return
                kalshi_get = fair_reader()
                last = None
                while True:
                    now_u = datetime.now(timezone.utc)
                    fast = (now_u.hour * 60 + now_u.minute) < OR_FAIR_FAST_WINDOW_MIN
